# server.R

.cgv_server_definition <- function(input, output, session) {
    session_t0 <- app_perf_now()
    session_token <- as.character(session$token %||% "unknown")
    session_metric_enabled <- app_env_flag("APP_SESSION_METRICS", default = FALSE)
    if (isTRUE(session_metric_enabled)) {
        session_memory_metric_fields <- function() {
            snapshot <- tryCatch(app_memory_telemetry_snapshot(), error = function(e) NULL)
            if (!is.list(snapshot)) return("")
            mb_text <- function(value) {
                num <- suppressWarnings(as.numeric(value %||% NA_real_))
                if (is.finite(num) && !is.na(num) && num >= 0) sprintf("%.1f", num / 1024^2) else "NA"
            }
            sprintf(
                paste0(
                    " rss_mb=%s cache_mb=%s cache_budget_mb=%s",
                    " cache_total_budget_mb=%s cache_process_count=%s",
                    " cgroup_current_mb=%s cgroup_limit_mb=%s"
                ),
                mb_text(snapshot$rss_bytes),
                mb_text(snapshot$cache_bytes),
                mb_text(snapshot$cache_budget_bytes),
                mb_text(snapshot$cache_total_budget_bytes),
                as.character(as.integer(snapshot$cache_process_count %||% 1L)),
                mb_text(snapshot$cgroup_current_bytes),
                mb_text(snapshot$cgroup_limit_bytes)
            )
        }
        startup_epoch <- suppressWarnings(as.numeric(Sys.getenv("APP_START_EPOCH", "")))
        startup_msg <- if (is.finite(startup_epoch)) {
            sprintf(" startup_elapsed_s=%.1f", as.numeric(Sys.time()) - startup_epoch)
        } else {
            ""
        }
        message(sprintf(
            "[SESSION][start] token=%s pid=%d%s data_root=%s cache_dir=%s%s",
            session_token,
            Sys.getpid(),
            startup_msg,
            Sys.getenv("CGV_DATA_ROOT", "."),
            Sys.getenv("CGV_CACHE_DIR", "cache"),
            session_memory_metric_fields()
        ))
        session$onSessionEnded(function() {
            elapsed <- app_perf_elapsed_ms(session_t0) / 1000
            gc_info <- tryCatch(sum(gc()[, "used"], na.rm = TRUE), error = function(e) NA_real_)
            message(sprintf(
                "[SESSION][end] token=%s pid=%d elapsed_s=%.1f gc_used_cells=%s%s",
                session_token,
                Sys.getpid(),
                elapsed,
                if (is.finite(gc_info)) as.character(as.integer(gc_info)) else "NA",
                session_memory_metric_fields()
            ))
        })
    }

    # Factory: crea el conjunto completo de reactiveVals por pestaña.
    # Para agregar un nuevo estado por pestaña, añadirlo SOLO aquí.
    make_tab_rv_set <- function() {
        list(
            plotCounter         = reactiveVal(0),
            activePlotIds       = reactiveVal(integer()),
            titles              = make_keyed_reactive_map(),
            existingPlots       = reactiveVal(list()),
            fileData            = make_keyed_reactive_map(),
            chrNames            = reactiveVal(list()),
            genSequences        = make_keyed_reactive_map(),
            plotSignatures      = make_keyed_reactive_map(),
            annotationPaths     = reactiveVal(list()),
            genomePaths         = make_keyed_reactive_map(),
            organismInfo        = make_keyed_reactive_map(),
            plotMetrics         = make_keyed_reactive_map(),
            plotGeneMeta        = make_keyed_reactive_map(),
            closeObserversBound = reactiveVal(character())
        )
    }

    homo_rv <- make_tab_rv_set()
    ortho_rv <- make_tab_rv_set()

    # Aliases con los nombres originales — mantienen compatibilidad con todo el código existente.
    # reactiveVal es una función; asignar su referencia crea un alias al mismo estado reactivo.
    plotCounterHomologous <- homo_rv$plotCounter
    activePlotIdsHomologous <- homo_rv$activePlotIds
    titlesHomologous <- homo_rv$titles
    existingPlotsHomologous <- homo_rv$existingPlots
    fileDataHomologous <- homo_rv$fileData
    chrNamesHomologous <- homo_rv$chrNames
    genSequencesHomologous <- homo_rv$genSequences
    plotSignaturesHomologous <- homo_rv$plotSignatures
    annotationPathsHomologous <- homo_rv$annotationPaths
    genomePathsHomologous <- homo_rv$genomePaths
    organismInfoHomologous <- homo_rv$organismInfo
    plotMetricsHomologous <- homo_rv$plotMetrics
    plotGeneMetaHomologous <- homo_rv$plotGeneMeta
    closeObserversBoundHomologous <- homo_rv$closeObserversBound

    plotCounterOrthologous <- ortho_rv$plotCounter
    activePlotIdsOrthologous <- ortho_rv$activePlotIds
    titlesOrthologous <- ortho_rv$titles
    existingPlotsOrthologous <- ortho_rv$existingPlots
    fileDataOrthologous <- ortho_rv$fileData
    chrNamesOrthologous <- ortho_rv$chrNames
    genSequencesOrthologous <- ortho_rv$genSequences
    plotSignaturesOrthologous <- ortho_rv$plotSignatures
    annotationPathsOrthologous <- ortho_rv$annotationPaths
    genomePathsOrthologous <- ortho_rv$genomePaths
    organismInfoOrthologous <- ortho_rv$organismInfo
    plotMetricsOrthologous <- ortho_rv$plotMetrics
    plotGeneMetaOrthologous <- ortho_rv$plotGeneMeta
    closeObserversBoundOrthologous <- ortho_rv$closeObserversBound

    # ── LASTZ Debug helper ──────────────────────────────────────────
    # Sends step-by-step debug messages to the browser console.
    # Usage: lastz_dbg("step name", detail = "...", data = list(...), level = "log")
    lastz_dbg <- function(step, detail = NULL, data = NULL, level = "log") {
        msg <- list(step = as.character(step)[1L], level = as.character(level)[1L])
        if (!is.null(detail)) msg$detail <- as.character(detail)[1L]
        if (!is.null(data)) {
            msg$data <- tryCatch(
                as.list(data),
                error = function(e) list(toString_error = as.character(e$message))
            )
        }
        tryCatch(
            session$sendCustomMessage("lastz_debug", msg),
            error = function(e) message("[LASTZ-DEBUG][server] ", step, " | ", detail %||% "")
        )
        if (grepl("START|END|FATAL|worker plan", as.character(step), ignore.case = TRUE)) {
            message(
                "[LASTZ] ",
                as.character(step),
                if (!is.null(detail) && nzchar(as.character(detail))) paste0(" | ", as.character(detail)) else ""
            )
        }
    }

    read_lastz_worker_count <- function(default_workers = NULL) {
        default_val <- if (is.null(default_workers)) {
            tryCatch(as.integer(future::nbrOfWorkers()), error = function(e) 1L)
        } else {
            suppressWarnings(as.integer(default_workers))
        }
        if (!is.finite(default_val) || is.na(default_val) || default_val < 1L) {
            default_val <- 1L
        }
        raw_txt <- trimws(as.character(Sys.getenv("APP_LASTZ_WORKERS", "") %||% ""))
        if (!nzchar(raw_txt)) {
            return(default_val)
        }
        parsed <- suppressWarnings(as.integer(raw_txt))
        if (!is.finite(parsed) || is.na(parsed) || parsed < 1L) {
            return(default_val)
        }
        parsed
    }

    with_lastz_future_plan <- function(expr, label = "LASTZ") {
        target_workers <- read_lastz_worker_count(default_workers = 1L)
        lastz_dbg(
            paste0(label, " worker queue"),
            detail = sprintf("dedicated APP_LASTZ_WORKERS=%d; global future plan unchanged", as.integer(target_workers))
        )
        force(expr)
    }

    lastzFutureQueue <- tryCatch({
        target_workers <- read_lastz_worker_count(default_workers = 1L)
        promises:::WorkQueue$new(can_proceed = function() {
            total_workers <- tryCatch(as.integer(future::nbrOfWorkers()), error = function(e) 1L)
            free_workers <- tryCatch(as.integer(future::nbrOfFreeWorkers()), error = function(e) 0L)
            if (!is.finite(total_workers) || total_workers < 1L) total_workers <- 1L
            if (!is.finite(free_workers) || free_workers < 0L) free_workers <- 0L
            active_workers <- max(0L, total_workers - free_workers)
            free_workers > 0L && active_workers < min(as.integer(target_workers), total_workers)
        })
    }, error = function(e) promises::future_promise_queue())

    lastz_future_promise <- function(expr, envir = parent.frame(), ...) {
        promises::future_promise(
            expr = substitute(expr),
            envir = envir,
            ...,
            substitute = FALSE,
            queue = lastzFutureQueue
        )
    }

    lastzAlignmentResultCache <- new.env(parent = emptyenv())
    lastzBinaryFingerprintCache <- new.env(parent = emptyenv())

    read_lastz_cache_max_entries <- function(default_value = 48L) {
        raw_txt <- trimws(as.character(Sys.getenv("APP_LASTZ_CACHE_MAX_ENTRIES", as.character(default_value)) %||% as.character(default_value)))
        parsed <- suppressWarnings(as.integer(raw_txt))
        if (!is.finite(parsed) || is.na(parsed) || parsed < 1L) {
            parsed <- as.integer(default_value)
        }
        parsed
    }

    read_lastz_cache_max_bytes <- function(default_mb = 128) {
        raw_txt <- trimws(as.character(Sys.getenv("APP_LASTZ_CACHE_MAX_MB", as.character(default_mb)) %||% as.character(default_mb)))
        parsed <- suppressWarnings(as.numeric(raw_txt))
        if (!is.finite(parsed) || is.na(parsed) || parsed <= 0) parsed <- as.numeric(default_mb)
        parsed * 1024^2
    }

    lastz_binary_fingerprint <- function(bin_info = NULL) {
        path <- trimws(as.character((bin_info %||% list())$path %||% Sys.getenv("APP_LASTZ_BIN", "lastz") %||% "lastz"))
        path <- if (nzchar(path) && file.exists(path)) normalizePath(path, winslash = "/", mustWork = FALSE) else path
        info <- if (nzchar(path) && file.exists(path)) tryCatch(file.info(path), error = function(e) NULL) else NULL
        identity <- paste(
            path,
            if (!is.null(info) && nrow(info) > 0L) as.character(info$size[[1L]] %||% "") else "",
            if (!is.null(info) && nrow(info) > 0L) as.character(as.numeric(info$mtime[[1L]] %||% NA_real_)) else "",
            sep = "|"
        )
        cached <- cache_env_get(lastzBinaryFingerprintCache, identity, default = NULL)
        if (!is.null(cached)) return(as.character(cached))
        fingerprint <- if (nzchar(path) && file.exists(path) && requireNamespace("digest", quietly = TRUE)) {
            paste0(path, "|sha256:", digest::digest(file = path, algo = "sha256", serialize = FALSE))
        } else {
            identity
        }
        cache_env_set(lastzBinaryFingerprintCache, identity, fingerprint, max_size = 8L)
        fingerprint
    }

    lastz_ctx_cache_parts <- function(ctx, prefix = "ctx") {
        ctx <- ctx %||% list()
        path_txt <- trimws(as.character(ctx$genome_path %||% ""))
        path_norm <- if (nzchar(path_txt)) {
            tryCatch(normalizePath(path_txt, winslash = "/", mustWork = FALSE), error = function(e) path_txt)
        } else {
            ""
        }
        path_info <- if (nzchar(path_norm) && file.exists(path_norm)) {
            tryCatch(file.info(path_norm), error = function(e) NULL)
        } else {
            NULL
        }
        path_size <- if (!is.null(path_info) && nrow(path_info) > 0L) as.character(path_info$size[[1L]] %||% "") else ""
        path_mtime <- if (!is.null(path_info) && nrow(path_info) > 0L) as.character(as.numeric(path_info$mtime[[1L]] %||% NA_real_)) else ""
        c(
            prefix,
            as.character(ctx$plot_id %||% ""),
            as.character(ctx$organism_name %||% ""),
            path_norm,
            path_size,
            path_mtime,
            as.character(ctx$seqid %||% ""),
            as.character(ctx$strand %||% ""),
            as.character(suppressWarnings(as.integer(ctx$window_start %||% NA_integer_))),
            as.character(suppressWarnings(as.integer(ctx$window_end %||% NA_integer_)))
        )
    }

    lastz_alignment_cache_key <- function(mode,
                                          reference_ctx,
                                          query_ctx,
                                          format_name = "general",
                                          bin_info = NULL,
                                          extra_args = character(0)) {
        parts <- c(
            "lastz-align-v2",
            as.character(mode %||% "lastz"),
            as.character(format_name %||% ""),
            lastz_binary_fingerprint(bin_info),
            paste(as.character(extra_args %||% character(0)), collapse = "\001"),
            lastz_ctx_cache_parts(reference_ctx, "ref"),
            lastz_ctx_cache_parts(query_ctx, "qry")
        )
        if (requireNamespace("digest", quietly = TRUE)) {
            return(paste0("lastz-align-v2-", digest::digest(parts, algo = "sha256")))
        }
        stable_short_cache_key("lastz-align-v2", parts)
    }

    get_lastz_alignment_cached_result <- function(cache_key, reference_ctx = NULL, query_ctx = NULL) {
        cached <- cache_env_get(lastzAlignmentResultCache, cache_key, default = NULL)
        if (!is.null(cached)) return(cached)
        cached <- tryCatch(
            lastz_disk_cache_get(cache_key, reference_ctx = reference_ctx, query_ctx = query_ctx),
            error = function(e) NULL
        )
        if (!is.null(cached)) {
            cache_env_set(
                lastzAlignmentResultCache,
                cache_key,
                cached,
                max_size = read_lastz_cache_max_entries(),
                max_bytes = read_lastz_cache_max_bytes()
            )
        }
        cached
    }

    set_lastz_alignment_cached_result <- function(cache_key, result) {
        if (!is.list(result) || !identical(trimws(as.character(result$status %||% "")), "ok")) {
            return(invisible(result))
        }
        cache_env_set(
            lastzAlignmentResultCache,
            cache_key,
            result,
            max_size = read_lastz_cache_max_entries(),
            max_bytes = read_lastz_cache_max_bytes()
        )
    }

    run_canonical_lastz_contexts_async <- function(contexts, reference_ctx, ordered_ids = names(contexts)) {
        contexts <- contexts %||% list()
        reference_id <- trimws(as.character((reference_ctx %||% list())$plot_id %||% ""))
        ids <- unique(as.character(ordered_ids %||% names(contexts) %||% character(0)))
        query_ids <- ids[nzchar(ids) & ids != reference_id & ids %in% names(contexts)]
        invalid_state <- list(
            status = "invalid_input",
            runs = list(),
            contexts = contexts,
            reference_id = reference_id,
            query_ids = query_ids,
            stamp = as.character(Sys.time())
        )
        if (is.null(reference_ctx) || !nzchar(reference_id) || length(query_ids) == 0L) {
            return(promises::promise_resolve(invalid_state))
        }
        bin_info <- tryCatch(resolve_lastz_binary(), error = function(e) list(available = FALSE, path = ""))
        jobs <- lapply(query_ids, function(qid) {
            query_ctx <- contexts[[qid]]
            cache_key <- lastz_alignment_cache_key(
                mode = "canonical_lastz",
                reference_ctx = reference_ctx,
                query_ctx = query_ctx,
                format_name = "general-cigarx",
                bin_info = bin_info
            )
            cached <- get_lastz_alignment_cached_result(cache_key, reference_ctx, query_ctx)
            if (is.list(cached)) {
                return(promises::promise_resolve(list(qid = qid, cache_key = cache_key, cache_hit = TRUE, run = cached)))
            }
            lastz_future_promise({
                result <- tryCatch(
                    run_cached_canonical_lastz(
                        cache_key = cache_key,
                        reference_ctx = reference_ctx,
                        query_ctx = query_ctx,
                        engine = "lastz"
                    ),
                    error = function(e) list(
                        status = "engine_error",
                        stderr = conditionMessage(e),
                        blocks = data.frame(stringsAsFactors = FALSE),
                        segments = data.frame(stringsAsFactors = FALSE)
                    )
                )
                list(qid = qid, cache_key = cache_key, cache_hit = FALSE, run = result)
            }, seed = FALSE)
        })
        names(jobs) <- query_ids
        promises::promise_all(.list = jobs) %...>% (function(payloads) {
            payloads <- unname(as.list(payloads %||% list()))
            runs <- lapply(payloads, function(item) {
                result <- item$run %||% list(status = "engine_error", stderr = "empty result")
                if (!isTRUE(item$cache_hit)) set_lastz_alignment_cached_result(item$cache_key, result)
                result
            })
            names(runs) <- vapply(payloads, function(item) as.character(item$qid %||% ""), character(1))
            list(
                status = "done",
                runs = runs,
                contexts = contexts,
                reference_id = reference_id,
                query_ids = query_ids,
                stamp = as.character(Sys.time())
            )
        })
    }

    # Summarize a locus context for debug logging
    summarize_ctx_for_debug <- function(ctx, label = "ctx") {
        if (is.null(ctx)) return(list(label = label, status = "NULL"))
        gp <- as.character(ctx$genome_path %||% "")
        list(
            label = label,
            plot_id = as.character(ctx$plot_id %||% ""),
            genome_path = gp,
            genome_exists = if (nzchar(gp)) file.exists(gp) else FALSE,
            has_genome = isTRUE(ctx$has_genome),
            seqid = as.character(ctx$seqid %||% ""),
            window_start = as.integer(ctx$window_start %||% NA_integer_),
            window_end = as.integer(ctx$window_end %||% NA_integer_),
            organism = as.character(ctx$organism_name %||% "")
        )
    }
    # ── End LASTZ Debug helper ────────────────────────────────────

    # Organismo detectado
    make_state_cell <- function(initial_value) {
        cell <- initial_value
        function(value) {
            if (missing(value)) {
                return(cell)
            }
            cell <<- value
            invisible(cell)
        }
    }

    empty_plot_timing_tracker <- function() {
        list(
            run = NULL,
            expected = character(0),
            gate_expected = character(0),
            ready = character(0),
            painted = character(0),
            first_logged = FALSE,
            total_logged = FALSE,
            first_ready_ms = NA_real_,
            first_painted_logged = FALSE,
            first_painted_ms = NA_real_,
            ready_to_paint_logged = FALSE,
            total_painted_logged = FALSE,
            card_complete = character(0),
            first_card_complete_logged = FALSE,
            first_card_complete_ms = NA_real_
        )
    }

    ms_since_run_start <- function(run) {
        if (!is.list(run)) {
            return(NA_real_)
        }
        t0 <- suppressWarnings(as.numeric(run$t0 %||% NA_real_))
        if (!is.finite(t0)) {
            return(NA_real_)
        }
        now <- as.numeric(proc.time()[["elapsed"]])
        1000 * (now - t0)
    }

    start_plot_timing_tracker <- function(tracker_rv, run, context = "APP_TIMING") {
        tr <- empty_plot_timing_tracker()
        tr$run <- run
        tracker_rv(tr)
        if (is.list(run)) {
            app_perf_mark(run, "timing_start", context)
            browser_context <- if (grepl("^HOMO", context)) "homologous" else if (grepl("^ORTHO", context)) "orthologous" else ""
            functional_first_paint <- identical(browser_context, "orthologous") &&
                isTRUE(get0("orthoAutoRenderMore", envir = environment(), inherits = TRUE, ifnotfound = FALSE))
            functional_progressive <- identical(browser_context, "homologous") &&
                isTRUE(get0("homoProgressiveRender", envir = environment(), inherits = TRUE, ifnotfound = FALSE))
            if (isTRUE(app_perf_enabled()) || isTRUE(functional_first_paint) || isTRUE(functional_progressive)) {
                session$sendCustomMessage("cgv_plot_timing_start", list(
                    run_id = as.character(run$id %||% ""),
                    context = browser_context,
                    first_paint_only = !isTRUE(app_perf_enabled()) && isTRUE(functional_first_paint),
                    functional_only = !isTRUE(app_perf_enabled()) &&
                        (isTRUE(functional_first_paint) || isTRUE(functional_progressive))
                ))
            }
        }
        invisible(NULL)
    }

    initial_plot_timing_ids <- function(
        ids,
        initial_visible_count,
        plot_meta = NULL,
        primary_only = FALSE
    ) {
        ids_chr <- unique(as.character(ids %||% character(0)))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        if (isTRUE(primary_only) && is.list(plot_meta) && length(ids_chr) > 0L) {
            ids_chr <- Filter(function(plot_id) {
                meta <- tryCatch(plot_meta[[plot_id]], error = function(e) NULL)
                !identical((meta %||% list())$is_canonical, FALSE)
            }, ids_chr)
        }
        visible_n <- suppressWarnings(as.integer(initial_visible_count %||% 1L))
        if (!is.finite(visible_n) || is.na(visible_n) || visible_n < 1L) {
            visible_n <- 1L
        }
        if (length(ids_chr) <= visible_n) ids_chr else ids_chr[seq_len(visible_n)]
    }

    set_plot_timing_expected <- function(
        tracker_rv,
        ids,
        context = "APP_TIMING",
        gate_expected_ids = ids,
        gate_candidate_ids = ids
    ) {
        tr <- tracker_rv()
        ids_chr <- unique(as.character(ids %||% character(0)))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        gate_ids_chr <- unique(as.character(gate_expected_ids %||% character(0)))
        gate_ids_chr <- gate_ids_chr[nzchar(gate_ids_chr)]
        tr$expected <- ids_chr
        tr$gate_expected <- gate_ids_chr
        run <- tr$run
        if (is.list(run)) {
            browser_context <- if (grepl("^HOMO", context)) "homologous" else if (grepl("^ORTHO", context)) "orthologous" else ""
            functional_first_paint <- identical(browser_context, "orthologous") &&
                isTRUE(get0("orthoAutoRenderMore", envir = environment(), inherits = TRUE, ifnotfound = FALSE))
            functional_progressive <- identical(browser_context, "homologous") &&
                isTRUE(get0("homoProgressiveRender", envir = environment(), inherits = TRUE, ifnotfound = FALSE))
            functional_gate_active <- FALSE
            gate_candidates <- unique(as.character(gate_candidate_ids %||% character(0)))
            gate_candidates <- gate_candidates[nzchar(gate_candidates)]
            visible_expected_is_new <- length(gate_ids_chr) > 0L && gate_ids_chr[[1L]] %in% gate_candidates
            if (isTRUE(functional_first_paint) && isTRUE(visible_expected_is_new)) {
                activate_gate <- get0(
                    "activate_ortho_first_paint_gate",
                    envir = environment(),
                    inherits = TRUE,
                    ifnotfound = NULL
                )
                if (is.function(activate_gate)) {
                    functional_gate_active <- isTRUE(activate_gate(as.character(run$id %||% "")))
                }
            }
            if (isTRUE(app_perf_enabled()) || isTRUE(functional_gate_active) || isTRUE(functional_progressive)) {
                output_prefix <- if (identical(browser_context, "homologous")) "plot_homo_" else if (identical(browser_context, "orthologous")) "plot_ortho_" else "plot_"
                browser_expected_ids <- if (isTRUE(app_perf_enabled()) || isTRUE(functional_progressive)) ids_chr else gate_ids_chr
                session$sendCustomMessage("cgv_plot_timing_expect", list(
                    run_id = as.character(run$id %||% ""),
                    context = browser_context,
                    output_ids = paste0(output_prefix, browser_expected_ids, "-plot"),
                    first_paint_only = !isTRUE(app_perf_enabled()) && isTRUE(functional_gate_active),
                    functional_only = !isTRUE(app_perf_enabled()) &&
                        (isTRUE(functional_gate_active) || isTRUE(functional_progressive))
                ))
            }
            app_perf_mark(run, sprintf("expected_plots=%d", as.integer(length(ids_chr))), context)

            # Backfill timing markers if plots were already marked ready before expected was set.
            ready_now <- as.character(tr$ready %||% character(0))
            matched_ready <- intersect(ids_chr, ready_now)
            elapsed_ms <- suppressWarnings(as.numeric(ms_since_run_start(run)))
            if (!is.finite(elapsed_ms)) {
                elapsed_ms <- NA_real_
            }
            elapsed_label <- if (is.finite(elapsed_ms)) sprintf("%.1f", elapsed_ms) else "NA"

            if (!isTRUE(tr$first_logged) && length(matched_ready) > 0L) {
                app_perf_mark(
                    run,
                    sprintf("first_plot_ready_ms=%s ready=%d/%d", elapsed_label, as.integer(length(matched_ready)), as.integer(length(ids_chr))),
                    context
                )
                tr$first_logged <- TRUE
                tr$first_ready_ms <- elapsed_ms
                if (!isTRUE(tr$ready_to_paint_logged) && is.finite(tr$first_painted_ms) && is.finite(elapsed_ms)) {
                    app_perf_mark_ms(run, "server_ready_to_browser_paint_ms", max(0, tr$first_painted_ms - elapsed_ms), context)
                    tr$ready_to_paint_logged <- TRUE
                }
            }
            if (!isTRUE(tr$total_logged) && length(ids_chr) > 0L && length(matched_ready) >= length(ids_chr)) {
                app_perf_mark(
                    run,
                    sprintf("total_plots_ready_ms=%s ready=%d/%d", elapsed_label, as.integer(length(matched_ready)), as.integer(length(ids_chr))),
                    context
                )
                tr$total_logged <- TRUE
            }
        }
        tracker_rv(tr)
        invisible(NULL)
    }

    mark_plot_ready_timing <- function(tracker_rv, plot_id, context = "APP_TIMING") {
        tr <- tracker_rv()
        run <- tr$run
        pid <- as.character(plot_id %||% "")
        if (!nzchar(pid) || !is.list(run)) {
            return(invisible(NULL))
        }

        ready_now <- unique(c(as.character(tr$ready %||% character(0)), pid))
        tr$ready <- ready_now
        expected_ids <- as.character(tr$expected %||% character(0))
        matched_ready <- intersect(expected_ids, ready_now)
        elapsed_ms <- suppressWarnings(as.numeric(ms_since_run_start(run)))
        if (!is.finite(elapsed_ms)) {
            elapsed_ms <- NA_real_
        }
        elapsed_label <- if (is.finite(elapsed_ms)) sprintf("%.1f", elapsed_ms) else "NA"

        if (!isTRUE(tr$first_logged) && length(matched_ready) > 0L) {
            app_perf_mark(
                run,
                sprintf("first_plot_ready_ms=%s ready=%d/%d", elapsed_label, as.integer(length(matched_ready)), as.integer(length(expected_ids))),
                context
            )
            tr$first_logged <- TRUE
            tr$first_ready_ms <- elapsed_ms
            if (!isTRUE(tr$ready_to_paint_logged) && is.finite(tr$first_painted_ms) && is.finite(elapsed_ms)) {
                app_perf_mark_ms(run, "server_ready_to_browser_paint_ms", max(0, tr$first_painted_ms - elapsed_ms), context)
                tr$ready_to_paint_logged <- TRUE
            }
        }
        if (!isTRUE(tr$total_logged) && length(expected_ids) > 0L && length(matched_ready) >= length(expected_ids)) {
            app_perf_mark(
                run,
                sprintf("total_plots_ready_ms=%s ready=%d/%d", elapsed_label, as.integer(length(matched_ready)), as.integer(length(expected_ids))),
                context
            )
            tr$total_logged <- TRUE
        }
        tracker_rv(tr)
        invisible(NULL)
    }

    drop_plot_timing_id <- function(tracker_rv, plot_id) {
        tr <- tracker_rv()
        pid <- as.character(plot_id %||% "")
        if (!nzchar(pid) || !is.list(tr)) {
            return(invisible(NULL))
        }
        tr$expected <- setdiff(as.character(tr$expected %||% character(0)), pid)
        tr$gate_expected <- setdiff(as.character(tr$gate_expected %||% character(0)), pid)
        tr$ready <- setdiff(as.character(tr$ready %||% character(0)), pid)
        tr$painted <- setdiff(as.character(tr$painted %||% character(0)), pid)
        tracker_rv(tr)
        invisible(NULL)
    }

    plotMetricsPayloadCache <- new.env(parent = emptyenv())
    pendingMetricsBuilds <- new.env(parent = emptyenv())
    pendingMetricsPlotIds <- new.env(parent = emptyenv())

    pending_metrics_plot_key <- function(context = "homo", plot_id = "") {
        paste0(tolower(trimws(as.character(context %||% "homo"))), "::", as.character(plot_id %||% ""))
    }

    metrics_payload_build_is_pending <- function(context = "homo", plot_id = "") {
        pid <- sub("_c$", "", as.character(plot_id %||% ""))
        nzchar(pid) && exists(
            pending_metrics_plot_key(context, pid),
            envir = pendingMetricsPlotIds,
            inherits = FALSE
        )
    }

    clear_pending_metrics_plot_ids <- function(context = "homo", plot_ids = character(0)) {
        ids_chr <- unique(sub("_c$", "", as.character(plot_ids %||% character(0))))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        for (pid in ids_chr) {
            key <- pending_metrics_plot_key(context, pid)
            if (exists(key, envir = pendingMetricsPlotIds, inherits = FALSE)) {
                rm(list = key, envir = pendingMetricsPlotIds)
            }
        }
        invisible(NULL)
    }

    dispatch_pending_metrics_build <- function(run_id = "", reason = "browser_paint") {
        run_key <- trimws(as.character(run_id %||% ""))
        if (!nzchar(run_key) || !exists(run_key, envir = pendingMetricsBuilds, inherits = FALSE)) {
            return(invisible(FALSE))
        }
        job <- get(run_key, envir = pendingMetricsBuilds, inherits = FALSE)
        if (isTRUE(job$started)) {
            return(invisible(FALSE))
        }
        job$started <- TRUE
        assign(run_key, job, envir = pendingMetricsBuilds)
        app_perf_mark(
            job$perf_run,
            sprintf("metrics_payload_dispatch reason=%s", as.character(reason %||% "unknown")),
            job$perf_context
        )
        tryCatch(
            job$dispatch(),
            error = function(e) {
                app_perf_mark(
                    job$perf_run,
                    sprintf("metrics_payload_build_error=%s", as.character(e$message %||% "unknown")),
                    job$perf_context
                )
            },
            finally = {
                clear_pending_metrics_plot_ids(job$context, job$plot_ids)
                if (exists(run_key, envir = pendingMetricsBuilds, inherits = FALSE)) {
                    rm(list = run_key, envir = pendingMetricsBuilds)
                }
            }
        )
        invisible(TRUE)
    }

    merge_named_lists <- function(base_map, add_map) {
        out <- base_map
        add_names <- names(add_map %||% list())
        add_names <- add_names[!is.na(add_names) & nzchar(add_names)]
        if (length(add_names) > 0) {
            out[add_names] <- add_map[add_names]
        }
        out
    }

    metrics_payload_cache_key <- function(context = "homo", kind = "id", value = "") {
        paste(
            tolower(trimws(as.character(context %||% "homo"))),
            tolower(trimws(as.character(kind %||% "id"))),
            as.character(value %||% ""),
            sep = "::"
        )
    }

    get_metrics_accessors <- function(context = "homo") {
        ctx <- tolower(trimws(as.character(context %||% "homo")))
        if (identical(ctx, "ortho")) {
            list(
                metrics = plotMetricsOrthologous,
                file_data = fileDataOrthologous,
                titles = titlesOrthologous,
                organism = organismInfoOrthologous,
                annotation = annotationPathsOrthologous,
                signatures = plotSignaturesOrthologous,
                gene_meta = plotGeneMetaOrthologous,
                active_ids = activePlotIdsOrthologous
            )
        } else {
            list(
                metrics = plotMetricsHomologous,
                file_data = fileDataHomologous,
                titles = titlesHomologous,
                organism = organismInfoHomologous,
                annotation = annotationPathsHomologous,
                signatures = plotSignaturesHomologous,
                gene_meta = plotGeneMetaHomologous,
                active_ids = activePlotIdsHomologous
            )
        }
    }

    cache_metrics_payloads <- function(context = "homo", plot_ids = character(0), payloads = list(), plot_signatures = NULL) {
        ids_chr <- as.character(plot_ids %||% character(0))
        if (length(ids_chr) == 0L || length(payloads) == 0L) {
            return(invisible(NULL))
        }
        n_cache <- min(length(ids_chr), length(payloads))
        if (n_cache <= 0L) {
            return(invisible(NULL))
        }
        sig_map <- plot_signatures
        if (is.null(sig_map)) {
            sig_map <- list()
        }
        if (!is.list(sig_map)) {
            sig_map <- as.list(sig_map)
        }
        written_keys <- character(0)
        for (idx in seq_len(n_cache)) {
            pid <- ids_chr[[idx]]
            payload <- payloads[[idx]] %||% list()
            id_key <- metrics_payload_cache_key(context, "id", pid)
            assign(id_key, payload, envir = plotMetricsPayloadCache)
            written_keys <- c(written_keys, id_key)
            sig_by_id <- tryCatch(sig_map[[pid]], error = function(e) NULL)
            sig_by_idx <- if (idx <= length(sig_map)) {
                tryCatch(sig_map[[idx]], error = function(e) NULL)
            } else {
                NULL
            }
            sig_val <- as.character(sig_by_id %||% sig_by_idx %||% "")
            if (nzchar(sig_val)) {
                sig_key <- metrics_payload_cache_key(context, "sig", sig_val)
                assign(sig_key, payload, envir = plotMetricsPayloadCache)
                written_keys <- c(written_keys, sig_key)
            }
        }
        # cache_env_set() trims and rescans the complete environment per item.
        # A large human gene can add hundreds of id/signature pairs at once, so
        # write the batch first and rebuild LRU metadata in one pass.
        written_keys <- unique(written_keys)
        cache_meta <- cache_env_meta_get(plotMetricsPayloadCache)
        cache_meta$access <- cache_meta$access[setdiff(names(cache_meta$access), written_keys)]
        cache_meta$bytes <- cache_meta$bytes[setdiff(names(cache_meta$bytes), written_keys)]
        cache_env_meta_set(plotMetricsPayloadCache, cache_meta)
        trim_cache_env(plotMetricsPayloadCache, max_size = 8000L)
        invisible(NULL)
    }

    set_context_metrics_payloads <- function(context = "homo", plot_ids = character(0), payloads = list(), plot_signatures = NULL) {
        ids_chr <- as.character(plot_ids %||% character(0))
        if (length(ids_chr) == 0L || length(payloads) == 0L) {
            return(invisible(list()))
        }
        n_update <- min(length(ids_chr), length(payloads))
        if (n_update <= 0L) {
            return(invisible(list()))
        }
        acc <- get_metrics_accessors(context)
        current_map <- tryCatch(acc$metrics(), error = function(e) list())
        if (!is.list(current_map)) {
            current_map <- list()
        }
        updates <- list()
        for (idx in seq_len(n_update)) {
            updates[[ids_chr[[idx]]]] <- payloads[[idx]] %||% list()
        }
        acc$metrics(merge_named_lists(current_map, updates))
        cache_metrics_payloads(context = context, plot_ids = ids_chr, payloads = payloads, plot_signatures = plot_signatures)
        invisible(updates)
    }

    build_plot_metrics_group_payloads <- function(context = "homo",
                                                  plot_ids = character(0),
                                                  transcript_blocks = list(),
                                                  representative_name = "",
                                                  organism_name = "",
                                                  annotation_path = "",
                                                  use_report_map = FALSE,
                                                  report_path = "",
                                                  plot_signatures = NULL,
                                                  perf_run = NULL,
                                                  perf_context = "APP") {
        ids_chr <- as.character(plot_ids %||% character(0))
        if (length(ids_chr) == 0L || length(transcript_blocks) == 0L) {
            return(list())
        }
        metrics_t0 <- app_perf_now()
        payloads <- build_transcript_metrics_payloads(
            full_data = do.call(rbind,  transcript_blocks),
            transcript_blocks = transcript_blocks,
            representative_name = representative_name,
            organism_name = organism_name,
            annotation_path = annotation_path,
            use_report_map = isTRUE(use_report_map),
            report_path = report_path,
            perf_run = perf_run,
            perf_context = perf_context
        )
        app_perf_mark_ms(perf_run, "metrics_payload_build_ms", app_perf_elapsed_ms(metrics_t0), perf_context)
        set_context_metrics_payloads(
            context = context,
            plot_ids = ids_chr,
            payloads = payloads,
            plot_signatures = plot_signatures
        )
        payloads
    }

    schedule_plot_metrics_payload_build <- function(context = "homo",
                                                    plot_ids = character(0),
                                                    transcript_blocks = list(),
                                                    representative_name = "",
                                                    organism_name = "",
                                                    annotation_path = "",
                                                    use_report_map = FALSE,
                                                    report_path = "",
                                                    perf_run = NULL,
                                                    perf_context = "APP",
                                                    plot_signatures = NULL) {
        ids_chr <- as.character(plot_ids %||% character(0))
        if (length(ids_chr) == 0L || length(transcript_blocks) == 0L) {
            return(invisible(FALSE))
        }
        dispatch <- function() {
            payloads <- build_plot_metrics_group_payloads(
                context = context,
                plot_ids = ids_chr,
                transcript_blocks = transcript_blocks,
                representative_name = representative_name,
                organism_name = organism_name,
                annotation_path = annotation_path,
                use_report_map = use_report_map,
                report_path = report_path,
                plot_signatures = plot_signatures,
                perf_run = perf_run,
                perf_context = perf_context
            )
            cache_metrics_payloads(context = context, plot_ids = ids_chr, payloads = payloads, plot_signatures = plot_signatures)
            invisible(NULL)
        }
        # Large groups used to monopolize the Shiny event loop before the first
        # visible card could paint. Keep every metric, but let the canonical card
        # and its sequence-composition footer reach the browser first. The paint
        # acknowledgement dispatches the complete metrics build immediately.
        defer_until_first_paint <- length(ids_chr) > 24L && is.list(perf_run) &&
            nzchar(as.character(perf_run$id %||% ""))
        if (isTRUE(defer_until_first_paint) && requireNamespace("later", quietly = TRUE)) {
            run_key <- as.character(perf_run$id %||% "")
            for (pid in ids_chr) {
                assign(
                    pending_metrics_plot_key(context, pid),
                    run_key,
                    envir = pendingMetricsPlotIds
                )
            }
            assign(
                run_key,
                list(
                    dispatch = dispatch,
                    context = context,
                    plot_ids = ids_chr,
                    perf_run = perf_run,
                    perf_context = perf_context,
                    started = FALSE
                ),
                envir = pendingMetricsBuilds
            )
            app_perf_mark(
                perf_run,
                sprintf("metrics_payload_queued_after_first_paint plots=%d", as.integer(length(ids_chr))),
                perf_context
            )
            later::later(function() {
                dispatch_pending_metrics_build(run_key, reason = "paint_timeout")
            }, delay = 120)
            return(invisible(TRUE))
        }
        if (requireNamespace("later", quietly = TRUE)) {
            later::later(function() {
                tryCatch(dispatch(), error = function(e) {
                    app_perf_mark(perf_run, sprintf("metrics_payload_build_error=%s", as.character(e$message %||% "unknown")), perf_context)
                })
            }, delay = 0.05)
            return(invisible(TRUE))
        }
        FALSE
    }

    get_plot_metrics_payload <- function(plot_id, context = "homo") {
        pid <- as.character(plot_id %||% "")
        if (!nzchar(pid)) {
            return(NULL)
        }
        base_pid <- sub("_c$", "", pid)
        acc <- get_metrics_accessors(context)
        payload <- tryCatch(read_reactive_map_key(acc$metrics, pid), error = function(e) NULL)
        if (is.null(payload) && !identical(base_pid, pid)) {
            payload <- tryCatch(read_reactive_map_key(acc$metrics, base_pid), error = function(e) NULL)
        }
        if (!is.null(payload)) {
            return(payload)
        }

        cached <- cache_env_get(plotMetricsPayloadCache, metrics_payload_cache_key(context, "id", pid), default = NULL)
        if (is.null(cached) && !identical(base_pid, pid)) {
            cached <- cache_env_get(plotMetricsPayloadCache, metrics_payload_cache_key(context, "id", base_pid), default = NULL)
        }
        if (!is.null(cached)) {
            return(cached)
        }

        # A scheduled large-group build owns this payload. Returning NULL keeps
        # the footer (including sequence composition) non-blocking; the metrics
        # reactive invalidates it as soon as the complete equivalent payload is ready.
        if (metrics_payload_build_is_pending(context, base_pid)) {
            return(NULL)
        }

        sig_map <- tryCatch(acc$signatures(), error = function(e) list())
        sig_val <- as.character(sig_map[[base_pid]] %||% sig_map[[pid]] %||% "")
        if (nzchar(sig_val)) {
            cached_sig <- cache_env_get(plotMetricsPayloadCache, metrics_payload_cache_key(context, "sig", sig_val), default = NULL)
            if (!is.null(cached_sig)) {
                return(cached_sig)
            }
        }

        gene_meta_map <- tryCatch(acc$gene_meta(), error = function(e) list())
        titles_map <- tryCatch(acc$titles(), error = function(e) list())
        file_map <- tryCatch(acc$file_data(), error = function(e) list())
        organism_map <- tryCatch(acc$organism(), error = function(e) list())
        annotation_map <- tryCatch(acc$annotation(), error = function(e) list())
        active_ids <- tryCatch(as.character(acc$active_ids() %||% character(0)), error = function(e) character(0))

        ref_meta <- tryCatch(gene_meta_map[[base_pid]], error = function(e) NULL)
        if (is.null(ref_meta)) {
            ref_meta <- tryCatch(gene_meta_map[[pid]], error = function(e) NULL)
        }
        ref_title <- as.character(titles_map[[base_pid]] %||% titles_map[[pid]] %||% "")
        ann_path <- as.character(annotation_map[[base_pid]] %||% annotation_map[[pid]] %||% "")
        org_name <- as.character((organism_map[[base_pid]] %||% organism_map[[pid]] %||% list())$name %||% "")
        if (!nzchar(ann_path)) {
            return(NULL)
        }

        ref_gene_key <- canonical_gene_group_key(
            query_gene = as.character(ref_meta$query_gene %||% ""),
            matched_gene_name = as.character(ref_meta$display_gene_name %||% ref_meta$matched_gene_name %||% ""),
            matched_gene_id = as.character(ref_meta$matched_gene_id %||% ""),
            title_gene = as.character(extract_title_field(ref_title, "Gene") %||% "")
        )
        candidate_ids <- unique(c(base_pid, active_ids))
        group_ids <- Filter(function(candidate_id) {
            meta <- tryCatch(gene_meta_map[[candidate_id]], error = function(e) NULL)
            if (isTRUE(meta$is_canonical_copy)) {
                return(FALSE)
            }
            ann_candidate <- as.character(annotation_map[[candidate_id]] %||% "")
            if (!identical(ann_candidate, ann_path)) {
                return(FALSE)
            }
            org_candidate <- as.character((organism_map[[candidate_id]] %||% list())$name %||% "")
            if (!identical(org_candidate, org_name)) {
                return(FALSE)
            }
            title_candidate <- as.character(titles_map[[candidate_id]] %||% "")
            candidate_key <- canonical_gene_group_key(
                query_gene = as.character(meta$query_gene %||% ""),
                matched_gene_name = as.character(meta$display_gene_name %||% meta$matched_gene_name %||% ""),
                matched_gene_id = as.character(meta$matched_gene_id %||% ""),
                title_gene = as.character(extract_title_field(title_candidate, "Gene") %||% "")
            )
            identical(candidate_key, ref_gene_key)
        }, candidate_ids)
        group_ids <- as.character(group_ids %||% character(0))
        group_ids <- group_ids[nzchar(group_ids)]
        if (length(group_ids) == 0L) {
            return(NULL)
        }
        transcript_blocks <- lapply(group_ids, function(candidate_id) {
            tryCatch(file_map[[candidate_id]], error = function(e) NULL)
        })
        keep_idx <- which(vapply(transcript_blocks, function(x) !is.null(x) && nrow(x) > 0, logical(1)))
        if (length(keep_idx) == 0L) {
            return(NULL)
        }
        group_ids <- group_ids[keep_idx]
        transcript_blocks <- transcript_blocks[keep_idx]

        representative_name <- trimws(as.character(
            ref_meta$display_gene_name %||%
                ref_meta$matched_gene_name %||%
                ref_meta$query_gene %||%
                extract_title_field(ref_title, "Gene") %||%
                ""
        ))
        report_path <- get_assembly_report_path_for_annotation(ann_path, base_dir = ".")
        payloads <- build_plot_metrics_group_payloads(
            context = context,
            plot_ids = group_ids,
            transcript_blocks = transcript_blocks,
            representative_name = representative_name,
            organism_name = org_name,
            annotation_path = ann_path,
            use_report_map = nzchar(as.character(report_path %||% "")) && file.exists(report_path),
            report_path = report_path,
            plot_signatures = sig_map[group_ids],
            perf_run = app_perf_new_run(sprintf("%s_METRICS", toupper(context))),
            perf_context = if (identical(tolower(context), "ortho")) "ORTHO" else "HOMO"
        )
        base_idx <- match(base_pid, group_ids)
        pid_idx <- match(pid, group_ids)
        if (is.finite(base_idx) && !is.na(base_idx) && base_idx >= 1L && base_idx <= length(payloads)) {
            return(payloads[[base_idx]] %||% NULL)
        }
        if (is.finite(pid_idx) && !is.na(pid_idx) && pid_idx >= 1L && pid_idx <= length(payloads)) {
            return(payloads[[pid_idx]] %||% NULL)
        }
        NULL
    }

