    # ── NCBI Download reactive state ──────────────────────────────
    ncbiSearchResultsHomo   <- reactiveVal(data.frame())
    ncbiSelectedAccHomo     <- reactiveVal(NULL)
    ncbiDownloadStatusHomo  <- reactiveVal(list(state = "idle", pct = 0, msg = ""))
    ncbiSearchResultsOrtho  <- reactiveVal(data.frame())
    ncbiSelectedAccOrtho    <- reactiveVal(NULL)
    ncbiQueueOrtho          <- reactiveVal(list())
    ncbiDownloadStatusOrtho <- reactiveVal(list(state = "idle", pct = 0, msg = ""))
    orthoPreparedNcbiOrganisms <- reactiveVal(list())
    orthoPreparedUploadOrganisms <- reactiveVal(list())
    # Persist NCBI file paths so gene search can access them
    ncbiAnnotationPathHomo  <- reactiveVal(NULL)
    ncbiGenomePathHomo      <- reactiveVal(NULL)
    ncbiAnnotationPathsOrtho <- reactiveVal(list())   # named list: label -> path
    ncbiGenomePathsOrtho     <- reactiveVal(list())    # named list: label -> path
    ncbiDownloadingHomo     <- reactiveVal(FALSE)      # lock to prevent double clicks
    lastObservedHomoSourceKey <- reactiveVal("")
    lastObservedOrthoSourceKey <- reactiveVal("")

    stateHelpersDomain <- init_server_state_helpers_domain(
        autocompleteBuildEpochs_rv = autocompleteBuildEpochs,
        searchRunState_rv = searchRunState
    )
    parse_positive_int_env <- stateHelpersDomain$parse_positive_int_env
    get_autocomplete_epoch <- stateHelpersDomain$get_autocomplete_epoch
    bump_autocomplete_epoch <- stateHelpersDomain$bump_autocomplete_epoch
    cancel_autocomplete_background <- stateHelpersDomain$cancel_autocomplete_background
    compose_autocomplete_still_valid <- stateHelpersDomain$compose_autocomplete_still_valid
    get_search_run_mode_state <- stateHelpersDomain$get_search_run_mode_state
    begin_search_run <- stateHelpersDomain$begin_search_run
    finish_search_run <- stateHelpersDomain$finish_search_run
    secondary_work_initial_delay_sec <- app_env_int(
        "APP_SECONDARY_WORK_INITIAL_DELAY_MS",
        2500L,
        min_value = 250L,
        max_value = 30000L
    ) / 1000
    secondary_work_retry_delay_sec <- app_env_int(
        "APP_SECONDARY_WORK_RETRY_MS",
        750L,
        min_value = 100L,
        max_value = 10000L
    ) / 1000
    secondary_work_should_yield <- function() {
        search_state <- tryCatch(isolate(searchRunState()), error = function(e) list())
        search_active <- is.list(search_state) && length(search_state) > 0L && any(vapply(
            search_state,
            function(mode_state) isTRUE((mode_state %||% list())$active),
            logical(1)
        ))
        if (isTRUE(search_active)) {
            return(TRUE)
        }
        # Async lookup can finish before ggiraph paints the first primary card.
        # Resolve the gate lazily because its reactiveVal is declared below.
        first_paint_gate_rv <- get0(
            "orthoFirstPaintGate",
            envir = environment(),
            inherits = TRUE,
            ifnotfound = NULL
        )
        if (!is.function(first_paint_gate_rv)) {
            return(FALSE)
        }
        gate <- tryCatch(isolate(first_paint_gate_rv()), error = function(e) list())
        isTRUE((gate %||% list())$enabled) && !isTRUE((gate %||% list())$released)
    }
    schedule_string_worker_prewarm()
    begin_session_source_restore <- stateHelpersDomain$begin_session_source_restore
    consume_session_source_restore <- stateHelpersDomain$consume_session_source_restore
    finish_session_source_restore <- stateHelpersDomain$finish_session_source_restore
    new_ortho_first_paint_gate_state <- stateHelpersDomain$new_ortho_first_paint_gate
    arm_ortho_first_paint_gate_state <- stateHelpersDomain$arm_ortho_first_paint_gate
    release_ortho_first_paint_gate_state <- stateHelpersDomain$release_ortho_first_paint_gate
    analyticsPhase2DelayMs <- min(4000L, max(0L, parse_positive_int_env("APP_ANALYTICS_PHASE2_DELAY_MS", 900L)))
    analyticsPhase3DelayMs <- min(8000L, max(analyticsPhase2DelayMs + 250L, parse_positive_int_env("APP_ANALYTICS_PHASE3_DELAY_MS", 2200L)))
    orthoPlotsReadyGate <- reactive({
        ids <- as.character(primaryPlotIdsOrthologous() %||% character(0))
        if (length(ids) == 0L) return(TRUE)
        ready <- as.character(orthoRenderedPlotIds() %||% character(0))
        all(ids %in% ready)
    })
    # Stream primary cards in small batches. The safety cap still protects a
    # session from an accidentally unbounded environment override.
    cardRegistrationSafetyCap <- 256L
    homoRenderChunkSize <- max(
        1L,
        min(
            cardRegistrationSafetyCap,
            parse_positive_int_env("APP_HOMO_RENDER_CHUNK_SIZE", 1L)
        )
    )
    homoInitialVisibleCount <- max(
        1L,
        min(
            cardRegistrationSafetyCap,
            parse_positive_int_env("APP_HOMO_INITIAL_VISIBLE", 1L)
        )
    )
    homoProgressiveRender <- homoInitialVisibleCount == 1L && homoRenderChunkSize >= 1L
    homoAutoRenderDelay <- {
        raw <- suppressWarnings(as.numeric(Sys.getenv("APP_HOMO_AUTO_RENDER_DELAY_MS", "120")))
        if (!is.finite(raw) || is.na(raw)) raw <- 120
        min(1000, max(0, raw)) / 1000
    }
    homoVisibleCount <- reactiveVal(homoInitialVisibleCount)
    homoAutoRenderQueued <- reactiveVal(FALSE)
    homoAutoRenderGeneration <- 0L
    bump_homo_auto_render_generation <- function() {
        next_generation <- suppressWarnings(as.integer(homoAutoRenderGeneration %||% 0L))
        if (!is.finite(next_generation) || is.na(next_generation) || next_generation < 0L ||
            next_generation >= .Machine$integer.max) {
            next_generation <- 0L
        }
        homoAutoRenderGeneration <<- as.integer(next_generation + 1L)
        homoAutoRenderGeneration
    }
    cancel_homo_auto_render_queue <- function() {
        bump_homo_auto_render_generation()
        homoAutoRenderQueued(FALSE)
        invisible(NULL)
    }
    homoRenderedPlotIds <- reactiveVal(character())
    homoInsertedCardIds <- reactiveVal(character())
    homoHydratedIsoformIds <- reactiveVal(character())
    homoFooterOutputsBound <- reactiveVal(character())
    homoDownloadOutputsBound <- reactiveVal(character())
    orthoRenderChunkSize <- max(
        1L,
        min(
            cardRegistrationSafetyCap,
            parse_positive_int_env("APP_ORTHO_RENDER_CHUNK_SIZE", 1L)
        )
    )
    orthoAutoRenderMore <- {
        raw <- tolower(trimws(as.character(Sys.getenv("APP_ORTHO_AUTO_RENDER_MORE", "1") %||% "1")))
        !raw %in% c("", "0", "false", "no", "off")
    }
    configuredOrthoInitialVisibleCount <- max(
        1L,
        min(
            cardRegistrationSafetyCap,
            parse_positive_int_env("APP_ORTHO_INITIAL_VISIBLE", 1L)
        )
    )
    # Progressive rendering starts with one card. Operators can still opt out by
    # disabling AUTO_RENDER_MORE and raising APP_ORTHO_INITIAL_VISIBLE.
    orthoInitialVisibleCount <- if (isTRUE(orthoAutoRenderMore)) 1L else configuredOrthoInitialVisibleCount
    orthoAutoRenderDelay <- {
        raw <- suppressWarnings(as.numeric(Sys.getenv("APP_ORTHO_AUTO_RENDER_DELAY_MS", "120")))
        if (!is.finite(raw) || is.na(raw)) raw <- 120
        min(1000, max(0, raw)) / 1000
    }
    isoformRenderBatchSize <- max(
        1L,
        min(8L, parse_positive_int_env("APP_ISOFORM_RENDER_BATCH_SIZE", 1L))
    )
    isoformRenderBatchDelay <- {
        raw <- suppressWarnings(as.numeric(Sys.getenv("APP_ISOFORM_RENDER_BATCH_DELAY_MS", "120")))
        if (!is.finite(raw) || is.na(raw)) raw <- 120
        min(1000, max(0, raw)) / 1000
    }
    orthoFirstPaintTimeout <- min(
        120000L,
        max(5000L, parse_positive_int_env("APP_ORTHO_FIRST_PAINT_TIMEOUT_MS", 30000L))
    ) / 1000
    orthoFirstPaintActivationTimeout <- max(90, min(300, 3 * orthoFirstPaintTimeout))
    orthoVisibleCount <- reactiveVal(orthoInitialVisibleCount)
    orthoAutoRenderQueued <- reactiveVal(FALSE)
    orthoAutoRenderGeneration <- 0L
    bump_ortho_auto_render_generation <- function() {
        next_generation <- suppressWarnings(as.integer(orthoAutoRenderGeneration %||% 0L))
        if (!is.finite(next_generation) || is.na(next_generation) || next_generation < 0L ||
            next_generation >= .Machine$integer.max) {
            next_generation <- 0L
        }
        orthoAutoRenderGeneration <<- as.integer(next_generation + 1L)
        orthoAutoRenderGeneration
    }
    cancel_ortho_auto_render_queue <- function() {
        bump_ortho_auto_render_generation()
        orthoAutoRenderQueued(FALSE)
        invisible(NULL)
    }
    orthoRenderedPlotIds <- reactiveVal(character())
    orthoInsertedCardIds <- reactiveVal(character())
    orthoHydratedIsoformIds <- reactiveVal(character())
    orthoFooterOutputsBound <- reactiveVal(character())
    orthoSecondaryBindingsQueued <- reactiveVal(character())
    orthoDownloadOutputsBound <- reactiveVal(character())
    isoformToggleObserversBound <- reactiveVal(character())
    isoformExpandedGroups <- reactiveVal(list())
    homoPlotTimingTracker <- reactiveVal(empty_plot_timing_tracker())
    orthoPlotTimingTracker <- reactiveVal(empty_plot_timing_tracker())
    orthoFirstPaintGate <- reactiveVal(new_ortho_first_paint_gate_state(enabled = FALSE))

    reset_ortho_first_paint_gate <- function(run) {
        run_id <- trimws(as.character((run %||% list())$id %||% ""))
        previous <- isolate(orthoFirstPaintGate())
        next_gate <- new_ortho_first_paint_gate_state(
            run_id = run_id,
            enabled = FALSE,
            previous_token = previous$token %||% 0L
        )
        next_gate$release_reason <- "awaiting_expected_plot"
        orthoFirstPaintGate(next_gate)
        invisible(next_gate)
    }

    activate_ortho_first_paint_gate <- function(run_id) {
        current <- isolate(orthoFirstPaintGate())
        run_key <- trimws(as.character(run_id %||% ""))
        if (!isTRUE(orthoAutoRenderMore) || !nzchar(run_key) ||
            !identical(run_key, trimws(as.character(current$run_id %||% "")))) {
            return(invisible(FALSE))
        }
        visual_mode <- tolower(trimws(as.character(isolate(input$ortho_visual_mode) %||% "compact")))
        if (visual_mode %in% c("aligned", "pip", "pip_blocks", "pip_multipip")) {
            return(invisible(FALSE))
        }
        primary_count <- length(isolate(primaryPlotIdsOrthologous() %||% character(0)))
        current_visible <- suppressWarnings(as.integer(isolate(orthoVisibleCount()) %||% orthoInitialVisibleCount))
        if (!is.finite(current_visible) || is.na(current_visible) || current_visible < 1L) {
            current_visible <- orthoInitialVisibleCount
        }
        if (primary_count <= current_visible) {
            return(invisible(FALSE))
        }
        activated <- FALSE
        if (!isTRUE(current$enabled)) {
            current <- new_ortho_first_paint_gate_state(
                run_id = run_key,
                enabled = TRUE,
                previous_token = current$token %||% 0L
            )
            orthoFirstPaintGate(current)
            activated <- TRUE
            activation_token <- current$token
            if (requireNamespace("later", quietly = TRUE)) {
                later::later(function() {
                    if (isTRUE(session$isClosed())) return(invisible(NULL))
                    isolate({
                        latest <- orthoFirstPaintGate()
                        same_gate <- identical(as.character(latest$run_id %||% ""), run_key) &&
                            identical(as.integer(latest$token %||% 0L), as.integer(activation_token %||% 0L))
                        if (isTRUE(same_gate) && isTRUE(latest$enabled) && !isTRUE(latest$released)) {
                            release_ortho_first_paint_gate(run_key, reason = "activation_timeout")
                        }
                    })
                }, delay = orthoFirstPaintActivationTimeout)
            }
        }
        if (isTRUE(current$released)) {
            return(invisible(activated))
        }
        invisible(TRUE)
    }

    release_ortho_first_paint_gate <- function(run_id, reason, output_id = "") {
        current <- isolate(orthoFirstPaintGate())
        transition <- release_ortho_first_paint_gate_state(
            current,
            run_id = run_id,
            reason = reason,
            output_id = output_id
        )
        if (!isTRUE(transition$changed)) {
            return(invisible(FALSE))
        }
        orthoFirstPaintGate(transition$state)
        tracker_run <- isolate(orthoPlotTimingTracker())$run
        if (is.list(tracker_run) && identical(as.character(tracker_run$id %||% ""), as.character(run_id %||% ""))) {
            app_perf_mark(
                tracker_run,
                sprintf(
                    "first paint gate released reason=%s output=%s",
                    as.character(reason %||% "unknown"),
                    as.character(output_id %||% "")
                ),
                "ORTHO_UI"
            )
        }
        if (!isTRUE(app_perf_enabled()) && !identical(as.character(reason %||% ""), "browser_paint")) {
            try(
                session$sendCustomMessage("cgv_plot_timing_stop", list(run_id = as.character(run_id %||% ""))),
                silent = TRUE
            )
        }
        invisible(TRUE)
    }

    arm_ortho_first_paint_timeout <- function(run_id) {
        current <- isolate(orthoFirstPaintGate())
        transition <- arm_ortho_first_paint_gate_state(current, run_id = run_id)
        if (!isTRUE(transition$changed)) {
            return(invisible(FALSE))
        }
        orthoFirstPaintGate(transition$state)
        gate_token <- transition$state$token
        tracker_run <- isolate(orthoPlotTimingTracker())$run
        if (is.list(tracker_run) && identical(as.character(tracker_run$id %||% ""), as.character(run_id %||% ""))) {
            app_perf_mark(
                tracker_run,
                sprintf("first paint gate armed timeout_ms=%d", as.integer(1000 * orthoFirstPaintTimeout)),
                "ORTHO_UI"
            )
        }
        if (!requireNamespace("later", quietly = TRUE)) {
            release_ortho_first_paint_gate(run_id, reason = "timer_unavailable")
            return(invisible(TRUE))
        }
        later::later(function() {
            if (isTRUE(session$isClosed())) return(invisible(NULL))
            isolate({
                latest <- orthoFirstPaintGate()
                same_gate <- identical(as.character(latest$run_id %||% ""), as.character(run_id %||% "")) &&
                    identical(as.integer(latest$token %||% 0L), as.integer(gate_token %||% 0L))
                if (isTRUE(same_gate) && isTRUE(latest$armed) && !isTRUE(latest$released)) {
                    release_ortho_first_paint_gate(run_id, reason = "timeout")
                }
            })
        }, delay = orthoFirstPaintTimeout)
        invisible(TRUE)
    }

    handle_browser_plot_paint <- function(tracker_rv, payload, context = "APP_TIMING") {
        tr <- tracker_rv()
        run <- tr$run
        run_id <- trimws(as.character(payload$run_id %||% ""))
        output_id <- trimws(as.character(payload$output_id %||% ""))
        if (!is.list(run) || !nzchar(run_id) || !identical(run_id, as.character(run$id %||% "")) || !nzchar(output_id)) {
            return(invisible(FALSE))
        }
        if (output_id %in% as.character(tr$painted %||% character(0))) {
            return(invisible(FALSE))
        }
        tr$painted <- unique(c(as.character(tr$painted %||% character(0)), output_id))
        elapsed_ms <- suppressWarnings(as.numeric(ms_since_run_start(run)))
        client_click_ms <- suppressWarnings(as.numeric(payload$click_to_paint_ms %||% NA_real_))
        svg_bytes <- suppressWarnings(as.numeric(payload$svg_bytes %||% NA_real_))
        svg_nodes <- suppressWarnings(as.numeric(payload$svg_nodes %||% NA_real_))
        if (!isTRUE(tr$first_painted_logged)) {
            app_perf_mark_ms(run, "browser_first_plot_painted_ms", elapsed_ms, context)
            if (is.finite(client_click_ms)) {
                app_perf_mark_ms(run, "client_click_to_first_paint_ms", client_click_ms, context)
            }
            if (is.finite(tr$first_ready_ms) && is.finite(elapsed_ms)) {
                app_perf_mark_ms(run, "server_ready_to_browser_paint_ms", max(0, elapsed_ms - tr$first_ready_ms), context)
                tr$ready_to_paint_logged <- TRUE
            }
            if (is.finite(svg_bytes)) app_perf_mark_ms(run, "browser_svg_bytes", svg_bytes, context)
            if (is.finite(svg_nodes)) app_perf_mark_ms(run, "browser_svg_nodes", svg_nodes, context)
            tr$first_painted_logged <- TRUE
            tr$first_painted_ms <- elapsed_ms
        }
        expected_outputs <- if (grepl("^HOMO", context)) {
            paste0("plot_homo_", as.character(tr$expected %||% character(0)), "-plot")
        } else if (grepl("^ORTHO", context)) {
            paste0("plot_ortho_", as.character(tr$expected %||% character(0)), "-plot")
        } else {
            character(0)
        }
        if (!isTRUE(tr$total_painted_logged) && length(expected_outputs) > 0L && all(expected_outputs %in% tr$painted)) {
            app_perf_mark_ms(run, "browser_total_plots_painted_ms", elapsed_ms, context)
            tr$total_painted_logged <- TRUE
        }
        tracker_rv(tr)
        invisible(TRUE)
    }

    handle_browser_card_complete <- function(tracker_rv, payload, context = "APP_TIMING") {
        tr <- tracker_rv()
        run <- tr$run
        run_id <- trimws(as.character(payload$run_id %||% ""))
        output_id <- trimws(as.character(payload$output_id %||% ""))
        if (!is.list(run) || !nzchar(run_id) || !identical(run_id, as.character(run$id %||% "")) || !nzchar(output_id)) {
            return(invisible(FALSE))
        }
        if (output_id %in% as.character(tr$card_complete %||% character(0))) {
            return(invisible(FALSE))
        }
        tr$card_complete <- unique(c(as.character(tr$card_complete %||% character(0)), output_id))
        elapsed_ms <- suppressWarnings(as.numeric(ms_since_run_start(run)))
        client_click_ms <- suppressWarnings(as.numeric(payload$click_to_complete_ms %||% NA_real_))
        metrics_bytes <- suppressWarnings(as.numeric(payload$metrics_bytes %||% NA_real_))
        if (!isTRUE(tr$first_card_complete_logged)) {
            app_perf_mark_ms(run, "browser_first_card_complete_ms", elapsed_ms, context)
            if (is.finite(client_click_ms)) {
                app_perf_mark_ms(run, "client_click_to_card_complete_ms", client_click_ms, context)
            }
            if (is.finite(tr$first_painted_ms) && is.finite(elapsed_ms)) {
                app_perf_mark_ms(run, "browser_first_paint_to_card_complete_ms", max(0, elapsed_ms - tr$first_painted_ms), context)
            }
            if (is.finite(metrics_bytes)) {
                app_perf_mark_ms(run, "browser_card_metrics_bytes", metrics_bytes, context)
            }
            app_perf_mark(
                run,
                sprintf(
                    "card_complete output=%s sequence=%s metrics=%s",
                    output_id,
                    as.character(isTRUE(payload$has_sequence_composition)),
                    as.character(isTRUE(payload$has_metrics))
                ),
                context
            )
            tr$first_card_complete_logged <- TRUE
            tr$first_card_complete_ms <- elapsed_ms
        }
        tracker_rv(tr)
        invisible(TRUE)
    }

    observeEvent(input$cgv_plot_painted, {
        payload <- input$cgv_plot_painted %||% list()
        run_id <- trimws(as.character(payload$run_id %||% ""))
        if (!nzchar(run_id)) return(invisible(NULL))
        homo_run <- (homoPlotTimingTracker()$run %||% list())$id %||% ""
        ortho_run <- (orthoPlotTimingTracker()$run %||% list())$id %||% ""
        if (identical(run_id, as.character(homo_run))) {
            handled <- handle_browser_plot_paint(homoPlotTimingTracker, payload, "HOMO_TIMING")
            output_id <- trimws(as.character(payload$output_id %||% ""))
            if (isTRUE(handled) && grepl("^plot_homo_.+-plot$", output_id)) {
                plot_id <- sub("^plot_homo_(.+)-plot$", "\\1", output_id)
                ready_now <- as.character(homoRenderedPlotIds() %||% character(0))
                if (nzchar(plot_id) && !(plot_id %in% ready_now)) {
                    homoRenderedPlotIds(c(ready_now, plot_id))
                }
            }
            if (isTRUE(handled)) {
                dispatch_pending_metrics_build(run_id, reason = "browser_paint")
            }
        } else if (identical(run_id, as.character(ortho_run))) {
            handled <- handle_browser_plot_paint(orthoPlotTimingTracker, payload, "ORTHO_TIMING")
            expected_outputs <- paste0(
                "plot_ortho_",
                as.character(orthoPlotTimingTracker()$gate_expected %||% character(0)),
                "-plot"
            )
            output_id <- trimws(as.character(payload$output_id %||% ""))
            if (isTRUE(handled) && grepl("^plot_ortho_.+-plot$", output_id)) {
                plot_id <- sub("^plot_ortho_(.+)-plot$", "\\1", output_id)
                ready_now <- as.character(orthoRenderedPlotIds() %||% character(0))
                if (nzchar(plot_id) && !(plot_id %in% ready_now)) {
                    orthoRenderedPlotIds(c(ready_now, plot_id))
                }
            }
            if (isTRUE(handled) && output_id %in% expected_outputs) {
                release_ortho_first_paint_gate(
                    run_id,
                    reason = "browser_paint",
                    output_id = output_id
                )
            }
            if (isTRUE(handled)) {
                dispatch_pending_metrics_build(run_id, reason = "browser_paint")
            }
        }
    }, ignoreInit = TRUE, ignoreNULL = TRUE)
    observeEvent(input$ortho_visual_mode, {
        visual_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (!visual_mode %in% c("aligned", "pip", "pip_blocks", "pip_multipip")) {
            return(invisible(NULL))
        }
        gate_now <- isolate(orthoFirstPaintGate())
        if (isTRUE(gate_now$enabled) && !isTRUE(gate_now$released)) {
            release_ortho_first_paint_gate(
                as.character(gate_now$run_id %||% ""),
                reason = "non_card_visual_mode"
            )
        }
        invisible(NULL)
    }, ignoreInit = TRUE, ignoreNULL = TRUE)
    observe({
        gate_now <- orthoFirstPaintGate()
        if (!isTRUE(gate_now$enabled) || isTRUE(gate_now$released)) {
            return(invisible(NULL))
        }
        gate_target <- head(
            as.character(orthoPlotTimingTracker()$gate_expected %||% character(0)),
            1L
        )
        visible_target <- head(
            as.character(primaryPlotIdsOrthologous() %||% character(0)),
            1L
