        if (length(gate_target) == 0L || length(visible_target) == 0L ||
            !identical(gate_target[[1L]], visible_target[[1L]])) {
            release_ortho_first_paint_gate(
                as.character(gate_now$run_id %||% ""),
                reason = "visible_target_changed"
            )
        }
        invisible(NULL)
    })
