    as_text_vec <- function(x) {
        as.character(x)
    }

    as_text_one <- function(x) {
        vals <- as_text_vec(x)
        if (length(vals) == 0) {
            return("")
        }
        as.character(vals[[1]] %||% "")
    }

    clear_cache_env_prefix <- function(env, prefix) {
        prefix_txt <- as.character(prefix %||% "")
        if (!nzchar(prefix_txt)) {
            return(invisible(NULL))
        }
        keys <- ls(envir = env, all.names = TRUE)
        keys <- keys[startsWith(keys, prefix_txt)]
        if (length(keys) > 0L) {
            rm(list = keys, envir = env)
        }
        invisible(NULL)
    }

    clear_summary_cache_scope <- function(scope = "summary", drop_rows = FALSE) {
        scope_txt <- trimws(as.character(scope %||% "summary"))
        if (!nzchar(scope_txt)) {
            scope_txt <- "summary"
        }
        clear_cache_env_prefix(summaryFrameCache, paste0("summary-frame-v1||", scope_txt, "||"))
        if (isTRUE(drop_rows)) {
            clear_cache_env_prefix(summaryRowCache, paste0("summary-row-v1||", scope_txt, "||"))
        }
        invisible(NULL)
    }

    summary_annotation_fingerprint <- function(annotation_path) {
        p <- trimws(as.character(annotation_path %||% ""))
        if (!nzchar(p)) {
            return("ann:none")
        }
        tryCatch(
            paste0("ann:", gff_cache_key(p)),
            error = function(e) paste0("ann:", normalize_annotation_key(p))
        )
    }

    summary_sequence_fingerprint <- function(seq_blob) {
        txt <- as.character(seq_blob %||% "")
        if (!nzchar(txt)) {
            return("seq:none")
        }
        n_bytes <- suppressWarnings(nchar(txt, type = "bytes"))
        if (!is.finite(n_bytes)) {
            n_bytes <- nchar(txt)
        }
        head_txt <- substr(txt, 1L, min(96L, n_bytes))
        tail_start <- max(1L, n_bytes - 95L)
        tail_txt <- substr(txt, tail_start, n_bytes)
        paste("seq", as.integer(n_bytes), head_txt, tail_txt, sep = "::")
    }

    stable_short_cache_key <- function(prefix = "cache", ...) {
        parts <- unlist(list(...), use.names = FALSE)
        txt <- paste(as.character(parts %||% character(0)), collapse = "||")
        raw_vals <- as.integer(charToRaw(enc2utf8(txt %||% "")))
        if (length(raw_vals) == 0L) {
            raw_vals <- 0L
        }
        mod1 <- 2147483647
        mod2 <- 2147483629
        h1 <- 0
        h2 <- 0
        for (i in seq_along(raw_vals)) {
            val <- as.integer(raw_vals[[i]] %||% 0L)
            h1 <- (h1 * 131 + val + i) %% mod1
            h2 <- (h2 * 137 + val + 7L * i) %% mod2
        }
        paste0(
            as.character(prefix %||% "cache"),
            "||",
            sprintf("%08x%08x", as.integer(h1), as.integer(h2)),
            "||n",
            nchar(txt, type = "bytes")
        )
    }

    normalize_pip_local_blocks <- function(df_blocks,
                                           min_identity = 0,
                                           min_block_length = 0) {
        if (!is.data.frame(df_blocks) || nrow(df_blocks) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        out <- df_blocks
        out$score_num <- suppressWarnings(as.numeric(out$score))
        out$identity_num <- suppressWarnings(as.numeric(out$identity_pct))
        out$align_num <- suppressWarnings(as.numeric(out$align_len))
        out$ref_s <- suppressWarnings(as.numeric(pmin(out$ref_genomic_start, out$ref_genomic_end)))
        out$ref_e <- suppressWarnings(as.numeric(pmax(out$ref_genomic_start, out$ref_genomic_end)))
        out$qry_s <- suppressWarnings(as.numeric(pmin(out$query_genomic_start, out$query_genomic_end)))
        out$qry_e <- suppressWarnings(as.numeric(pmax(out$query_genomic_start, out$query_genomic_end)))
        out$strand_state <- ifelse(trimws(as.character(out$strand2 %||% "")) == "-", "reverse", "forward")
        out$qry_axis_s <- ifelse(out$strand_state == "reverse", -out$qry_e, out$qry_s)
        out$qry_axis_e <- ifelse(out$strand_state == "reverse", -out$qry_s, out$qry_e)
        out$ref_span <- pmax(1, out$ref_e - out$ref_s + 1)
        out$qry_span <- pmax(1, out$qry_e - out$qry_s + 1)
        out <- out[
            is.finite(out$identity_num) &
                is.finite(out$align_num) &
                is.finite(out$ref_s) &
                is.finite(out$ref_e) &
                is.finite(out$qry_s) &
                is.finite(out$qry_e) &
                is.finite(out$qry_axis_s) &
                is.finite(out$qry_axis_e) &
                out$identity_num >= as.numeric(min_identity %||% 0) &
                out$align_num >= as.numeric(min_block_length %||% 0) &
                out$ref_e >= out$ref_s &
                out$qry_e >= out$qry_s,
            ,
            drop = FALSE
        ]
        if (nrow(out) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        out[order(out$strand_state, out$ref_s, out$qry_axis_s, -ifelse(is.finite(out$score_num), out$score_num, -Inf)), , drop = FALSE]
    }

    deduplicate_pip_local_blocks <- function(df_blocks, overlap_threshold = 0.85) {
        dedup_loop <- function(df_loop) {
            if (!is.data.frame(df_loop) || nrow(df_loop) <= 1L) {
                return(df_loop)
            }
            ord <- order(
                -ifelse(is.finite(df_loop$score_num), df_loop$score_num, -Inf),
                -ifelse(is.finite(df_loop$identity_num), df_loop$identity_num, -Inf),
                -ifelse(is.finite(df_loop$align_num), df_loop$align_num, -Inf),
                df_loop$ref_s,
                df_loop$qry_axis_s
            )
            df_ord <- df_loop[ord, , drop = FALSE]
            keep <- logical(nrow(df_ord))
            kept_ranges <- list()
            for (ii in seq_len(nrow(df_ord))) {
                cur <- df_ord[ii, , drop = FALSE]
                cur_ref_len <- max(1, as.numeric(cur$ref_e) - as.numeric(cur$ref_s) + 1)
                cur_qry_len <- max(1, as.numeric(cur$qry_axis_e) - as.numeric(cur$qry_axis_s) + 1)
                cur_strand <- trimws(as.character(cur$strand_state %||% "forward"))
                is_redundant <- FALSE
                if (length(kept_ranges) > 0L) {
                    for (kr in kept_ranges) {
                        if (!identical(cur_strand, kr$strand)) {
                            next
                        }
                        ref_ov <- max(0, min(as.numeric(cur$ref_e), kr$ref_e) - max(as.numeric(cur$ref_s), kr$ref_s) + 1)
                        qry_ov <- max(0, min(as.numeric(cur$qry_axis_e), kr$qry_e) - max(as.numeric(cur$qry_axis_s), kr$qry_s) + 1)
                        ref_ratio <- ref_ov / max(1, min(cur_ref_len, kr$ref_len))
                        qry_ratio <- qry_ov / max(1, min(cur_qry_len, kr$qry_len))
                        if (ref_ratio >= overlap_threshold && qry_ratio >= overlap_threshold) {
                            is_redundant <- TRUE
                            break
                        }
                    }
                }
                if (!is_redundant) {
                    keep[ii] <- TRUE
                    kept_ranges[[length(kept_ranges) + 1L]] <- list(
                        ref_s = as.numeric(cur$ref_s),
                        ref_e = as.numeric(cur$ref_e),
                        ref_len = cur_ref_len,
                        qry_s = as.numeric(cur$qry_axis_s),
                        qry_e = as.numeric(cur$qry_axis_e),
                        qry_len = cur_qry_len,
                        strand = cur_strand
                    )
                }
            }
            df_keep <- df_ord[keep, , drop = FALSE]
            df_keep[order(df_keep$strand_state, df_keep$ref_s, df_keep$qry_axis_s), , drop = FALSE]
        }

        if (!is.data.frame(df_blocks) || nrow(df_blocks) <= 1L) {
            return(df_blocks)
        }
        if (!requireNamespace("IRanges", quietly = TRUE) || !requireNamespace("data.table", quietly = TRUE)) {
            return(dedup_loop(df_blocks))
        }

        dedup_group <- function(df_group) {
            ord <- order(
                -ifelse(is.finite(df_group$score_num), df_group$score_num, -Inf),
                -ifelse(is.finite(df_group$identity_num), df_group$identity_num, -Inf),
                -ifelse(is.finite(df_group$align_num), df_group$align_num, -Inf),
                df_group$ref_s,
                df_group$qry_axis_s
            )
            df_ord <- df_group[ord, , drop = FALSE]
            n <- nrow(df_ord)
            if (n <= 1L) {
                return(df_ord)
            }

            ref_ir <- IRanges::IRanges(start = df_ord$ref_s, end = df_ord$ref_e)
            qry_ir <- IRanges::IRanges(start = df_ord$qry_axis_s, end = df_ord$qry_axis_e)
            ref_hits <- as.data.frame(IRanges::findOverlaps(ref_ir, ref_ir))
            qry_hits <- as.data.frame(IRanges::findOverlaps(qry_ir, qry_ir))
            if (!is.data.frame(ref_hits) || nrow(ref_hits) == 0L || !is.data.frame(qry_hits) || nrow(qry_hits) == 0L) {
                return(df_ord)
            }
            ref_hits <- ref_hits[ref_hits$queryHits < ref_hits$subjectHits, , drop = FALSE]
            qry_hits <- qry_hits[qry_hits$queryHits < qry_hits$subjectHits, , drop = FALSE]
            if (nrow(ref_hits) == 0L || nrow(qry_hits) == 0L) {
                return(df_ord)
            }

            data.table::setDT(ref_hits)
            data.table::setDT(qry_hits)
            cand <- qry_hits[ref_hits, nomatch = 0L, on = c("queryHits", "subjectHits")]
            if (!is.data.frame(cand) || nrow(cand) == 0L) {
                return(df_ord)
            }

            ii <- as.integer(cand$queryHits)
            jj <- as.integer(cand$subjectHits)
            ref_ov <- pmax(0, pmin(df_ord$ref_e[ii], df_ord$ref_e[jj]) - pmax(df_ord$ref_s[ii], df_ord$ref_s[jj]) + 1)
            qry_ov <- pmax(0, pmin(df_ord$qry_axis_e[ii], df_ord$qry_axis_e[jj]) - pmax(df_ord$qry_axis_s[ii], df_ord$qry_axis_s[jj]) + 1)
            ref_ratio <- ref_ov / pmax(1, pmin(df_ord$ref_span[ii], df_ord$ref_span[jj]))
            qry_ratio <- qry_ov / pmax(1, pmin(df_ord$qry_span[ii], df_ord$qry_span[jj]))
            keep_hits <- which(ref_ratio >= overlap_threshold & qry_ratio >= overlap_threshold)
            if (length(keep_hits) == 0L) {
                return(df_ord)
            }

            pair_dt <- data.frame(
                i = pmin(ii[keep_hits], jj[keep_hits]),
                j = pmax(ii[keep_hits], jj[keep_hits]),
                stringsAsFactors = FALSE
            )
            pair_dt <- unique(pair_dt)
            adj <- split(pair_dt$j, pair_dt$i)
            redundant <- logical(n)
            keep <- logical(n)
            for (idx in seq_len(n)) {
                if (redundant[[idx]]) {
                    next
                }
                keep[[idx]] <- TRUE
                hits_next <- adj[[as.character(idx)]]
                if (length(hits_next) > 0L) {
                    redundant[as.integer(hits_next)] <- TRUE
                }
            }
            df_ord[keep, , drop = FALSE]
        }

        out_list <- lapply(
            split(df_blocks, trimws(as.character(df_blocks$strand_state %||% "forward")), drop = TRUE),
            dedup_group
        )
        out_list <- Filter(function(x) is.data.frame(x) && nrow(x) > 0L, out_list)
        if (length(out_list) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        out_df <- do.call(rbind,  out_list)
        out_df[order(out_df$strand_state, out_df$ref_s, out_df$qry_axis_s), , drop = FALSE]
    }

    prune_pip_contained_blocks <- function(df_blocks,
                                           containment_threshold = 0.92,
                                           identity_slack = 0.25,
                                           require_query_containment = FALSE) {
        if (!is.data.frame(df_blocks) || nrow(df_blocks) <= 1L) {
            return(df_blocks)
        }
        required <- c("ref_s", "ref_e", "qry_axis_s", "qry_axis_e", "identity_num", "align_num", "score_num", "strand_state")
        if (!all(required %in% names(df_blocks))) {
            return(df_blocks)
        }
        ord <- order(
            -ifelse(is.finite(df_blocks$identity_num), df_blocks$identity_num, -Inf),
            -ifelse(is.finite(df_blocks$align_num), df_blocks$align_num, -Inf),
            -ifelse(is.finite(df_blocks$score_num), df_blocks$score_num, -Inf),
            -ifelse(is.finite(df_blocks$ref_span), df_blocks$ref_span, -Inf),
            -ifelse(is.finite(df_blocks$qry_span), df_blocks$qry_span, -Inf),
            df_blocks$ref_s,
            df_blocks$qry_axis_s
        )
        df_ord <- df_blocks[ord, , drop = FALSE]
        keep <- logical(nrow(df_ord))
        kept_ranges <- list()
        for (ii in seq_len(nrow(df_ord))) {
            cur <- df_ord[ii, , drop = FALSE]
            cur_ref_len <- max(1, as.numeric(cur$ref_e) - as.numeric(cur$ref_s) + 1)
            cur_qry_len <- max(1, as.numeric(cur$qry_axis_e) - as.numeric(cur$qry_axis_s) + 1)
            cur_identity <- suppressWarnings(as.numeric(cur$identity_num))
            cur_align <- suppressWarnings(as.numeric(cur$align_num))
            cur_score <- suppressWarnings(as.numeric(cur$score_num))
            cur_strand <- trimws(as.character(cur$strand_state %||% "forward"))
            is_shadowed <- FALSE
            if (length(kept_ranges) > 0L) {
                for (kr in kept_ranges) {
                    if (!identical(cur_strand, kr$strand)) {
                        next
                    }
                    ref_ov <- max(0, min(as.numeric(cur$ref_e), kr$ref_e) - max(as.numeric(cur$ref_s), kr$ref_s) + 1)
                    qry_ov <- max(0, min(as.numeric(cur$qry_axis_e), kr$qry_e) - max(as.numeric(cur$qry_axis_s), kr$qry_s) + 1)
                    ref_cover <- ref_ov / cur_ref_len
                    qry_cover <- qry_ov / cur_qry_len
                    stronger_identity <- is.finite(kr$identity) &&
                        (!is.finite(cur_identity) || kr$identity >= (cur_identity - identity_slack))
                    stronger_support <- (
                        (is.finite(kr$align) && !is.finite(cur_align)) ||
                        (is.finite(kr$align) && is.finite(cur_align) && kr$align >= cur_align) ||
                        (is.finite(kr$score) && is.finite(cur_score) && kr$score >= cur_score)
                    )
                    cover_ok <- ref_cover >= containment_threshold &&
                        (
                            !isTRUE(require_query_containment) ||
                                qry_cover >= containment_threshold
                        )
                    if (cover_ok &&
                        stronger_identity &&
                        stronger_support) {
                        is_shadowed <- TRUE
                        break
                    }
                }
            }
            if (!is_shadowed) {
                keep[ii] <- TRUE
                kept_ranges[[length(kept_ranges) + 1L]] <- list(
                    ref_s = as.numeric(cur$ref_s),
                    ref_e = as.numeric(cur$ref_e),
                    qry_s = as.numeric(cur$qry_axis_s),
                    qry_e = as.numeric(cur$qry_axis_e),
                    strand = cur_strand,
                    identity = cur_identity,
                    align = cur_align,
                    score = cur_score
                )
            }
        }
        df_keep <- df_ord[keep, , drop = FALSE]
        df_keep[order(df_keep$strand_state, df_keep$ref_s, df_keep$qry_axis_s), , drop = FALSE]
    }

    prune_display_blocks_by_reference_dominance <- function(df_blocks,
                                                            containment_threshold = 0.88,
                                                            identity_slack = 0.25,
                                                            respect_strand = TRUE) {
        if (!is.data.frame(df_blocks) || nrow(df_blocks) <= 1L) {
            return(df_blocks)
        }
        required <- c("ref_genomic_start", "ref_genomic_end", "identity_pct", "align_len", "strand_state")
        if (!all(required %in% names(df_blocks))) {
            return(df_blocks)
        }
        ref_start <- suppressWarnings(as.numeric(pmin(df_blocks$ref_genomic_start, df_blocks$ref_genomic_end)))
        ref_end <- suppressWarnings(as.numeric(pmax(df_blocks$ref_genomic_start, df_blocks$ref_genomic_end)))
        identity_num <- suppressWarnings(as.numeric(df_blocks$identity_pct))
        align_num <- suppressWarnings(as.numeric(df_blocks$align_len))
        score_num <- if ("score" %in% names(df_blocks)) suppressWarnings(as.numeric(df_blocks$score)) else rep(NA_real_, nrow(df_blocks))
        ord <- order(
            -ifelse(is.finite(identity_num), identity_num, -Inf),
            -ifelse(is.finite(align_num), align_num, -Inf),
            -ifelse(is.finite(score_num), score_num, -Inf),
            ref_start,
            ref_end
        )
        df_ord <- df_blocks[ord, , drop = FALSE]
        ref_start <- ref_start[ord]
        ref_end <- ref_end[ord]
        identity_num <- identity_num[ord]
        align_num <- align_num[ord]
        score_num <- score_num[ord]
        strand_state <- trimws(as.character(df_ord$strand_state %||% "forward"))
        keep <- logical(nrow(df_ord))
        kept_ranges <- list()
        for (ii in seq_len(nrow(df_ord))) {
            cur_start <- ref_start[[ii]]
            cur_end <- ref_end[[ii]]
            cur_len <- max(1, cur_end - cur_start + 1)
            cur_identity <- identity_num[[ii]]
            cur_align <- align_num[[ii]]
            cur_score <- score_num[[ii]]
            cur_strand <- strand_state[[ii]]
            is_shadowed <- FALSE
            if (length(kept_ranges) > 0L) {
                for (kr in kept_ranges) {
                    if (isTRUE(respect_strand) && !identical(cur_strand, kr$strand)) {
                        next
                    }
                    ref_ov <- max(0, min(cur_end, kr$ref_e) - max(cur_start, kr$ref_s) + 1)
                    ref_cover <- ref_ov / cur_len
                    stronger_identity <- is.finite(kr$identity) &&
                        (!is.finite(cur_identity) || kr$identity >= (cur_identity - identity_slack))
                    stronger_support <- (
                        (is.finite(kr$align) && !is.finite(cur_align)) ||
                        (is.finite(kr$align) && is.finite(cur_align) && kr$align >= cur_align) ||
                        (is.finite(kr$score) && is.finite(cur_score) && kr$score >= cur_score)
                    )
                    if (ref_cover >= containment_threshold &&
                        stronger_identity &&
                        stronger_support) {
                        is_shadowed <- TRUE
                        break
                    }
                }
            }
            if (!is_shadowed) {
                keep[[ii]] <- TRUE
                kept_ranges[[length(kept_ranges) + 1L]] <- list(
                    ref_s = cur_start,
                    ref_e = cur_end,
                    strand = cur_strand,
                    identity = cur_identity,
                    align = cur_align,
                    score = cur_score
                )
            }
        }
        df_keep <- df_ord[keep, , drop = FALSE]
        df_keep[order(
            suppressWarnings(as.numeric(df_keep$ref_genomic_start)),
            suppressWarnings(as.numeric(df_keep$ref_genomic_end))
        ), , drop = FALSE]
    }

    chain_pip_local_blocks <- function(df_blocks,
                                       max_ref_gap = NULL,
                                       max_query_gap = NULL,
                                       max_gap_skew = NULL,
                                       overlap_tolerance = NULL) {
        chain_loop <- function(df_loop,
                               max_ref_gap,
                               max_query_gap,
                               max_gap_skew,
                               overlap_tolerance) {
            df_ord <- df_loop[order(df_loop$strand_state, df_loop$ref_s, df_loop$qry_axis_s, -ifelse(is.finite(df_loop$score_num), df_loop$score_num, -Inf)), , drop = FALSE]
            chain_ids <- integer(nrow(df_ord))
            chain_state <- list()
            next_chain_id <- 0L
            for (ii in seq_len(nrow(df_ord))) {
                cur <- df_ord[ii, , drop = FALSE]
                cur_strand <- trimws(as.character(cur$strand_state %||% "forward"))
                best_chain <- NA_integer_
                best_penalty <- Inf
                if (length(chain_state) > 0L) {
                    for (cid in seq_along(chain_state)) {
                        st <- chain_state[[cid]]
                        if (!identical(cur_strand, st$strand)) {
                            next
                        }
                        ref_gap <- as.numeric(cur$ref_s) - st$ref_e
                        qry_gap <- as.numeric(cur$qry_axis_s) - st$qry_e
                        if (ref_gap < -overlap_tolerance || qry_gap < -overlap_tolerance) {
                            next
                        }
                        if (ref_gap > max_ref_gap || qry_gap > max_query_gap) {
                            next
                        }
                        gap_skew <- abs(max(ref_gap, 0) - max(qry_gap, 0))
                        if (gap_skew > max_gap_skew) {
                            next
                        }
                        penalty <- gap_skew + max(ref_gap, 0) + max(qry_gap, 0)
                        if (!is.finite(best_penalty) || penalty < best_penalty) {
                            best_penalty <- penalty
                            best_chain <- cid
                        }
                    }
                }
                if (!is.finite(best_chain)) {
                    next_chain_id <- next_chain_id + 1L
                    best_chain <- next_chain_id
                    chain_state[[best_chain]] <- list(
                        strand = cur_strand,
                        ref_e = as.numeric(cur$ref_e),
                        qry_e = as.numeric(cur$qry_axis_e)
                    )
                } else {
                    chain_state[[best_chain]]$ref_e <- max(chain_state[[best_chain]]$ref_e, as.numeric(cur$ref_e))
                    chain_state[[best_chain]]$qry_e <- max(chain_state[[best_chain]]$qry_e, as.numeric(cur$qry_axis_e))
                }
                chain_ids[[ii]] <- best_chain
            }
            df_ord$chain_id <- as.integer(chain_ids)
            df_ord
        }

        if (!is.data.frame(df_blocks) || nrow(df_blocks) == 0L) {
            return(df_blocks)
        }
        typical_span <- suppressWarnings(stats::median(df_blocks$align_num, na.rm = TRUE))
        if (!is.finite(typical_span) || typical_span <= 0) {
            typical_span <- suppressWarnings(stats::median(df_blocks$ref_span, na.rm = TRUE))
        }
        if (!is.finite(typical_span) || typical_span <= 0) {
            typical_span <- 500
        }
        max_ref_gap <- if (is.null(max_ref_gap)) max(300, min(12000, as.integer(round(typical_span * 4.5)))) else suppressWarnings(as.integer(max_ref_gap))
        max_query_gap <- if (is.null(max_query_gap)) max(300, min(12000, as.integer(round(typical_span * 4.5)))) else suppressWarnings(as.integer(max_query_gap))
        max_gap_skew <- if (is.null(max_gap_skew)) max(500, min(18000, as.integer(round(typical_span * 6)))) else suppressWarnings(as.integer(max_gap_skew))
        overlap_tolerance <- if (is.null(overlap_tolerance)) max(60, min(1800, as.integer(round(typical_span * 0.75)))) else suppressWarnings(as.integer(overlap_tolerance))
        if (!requireNamespace("data.table", quietly = TRUE)) {
            df_ord <- chain_loop(df_blocks, max_ref_gap, max_query_gap, max_gap_skew, overlap_tolerance)
            chain_rank_df <- aggregate(align_num ~ chain_id, data = df_ord, FUN = function(x) sum(as.numeric(x), na.rm = TRUE))
            chain_rank_df <- chain_rank_df[order(-chain_rank_df$align_num, chain_rank_df$chain_id), , drop = FALSE]
            chain_rank_df$chain_rank <- seq_len(nrow(chain_rank_df))
            df_ord$chain_rank <- chain_rank_df$chain_rank[match(df_ord$chain_id, chain_rank_df$chain_id)]
            return(df_ord)
        }

        groups <- split(df_blocks, trimws(as.character(df_blocks$strand_state %||% "forward")), drop = TRUE)
        next_chain_id <- 0L
        chained_groups <- lapply(groups, function(df_group) {
            df_ord <- df_group[order(df_group$ref_s, df_group$qry_axis_s, -ifelse(is.finite(df_group$score_num), df_group$score_num, -Inf)), , drop = FALSE]
            chain_ids <- integer(nrow(df_ord))
            active <- data.table::data.table(
                chain_id = integer(0),
                ref_e = numeric(0),
                qry_e = numeric(0)
            )
            for (ii in seq_len(nrow(df_ord))) {
                cur_ref_s <- as.numeric(df_ord$ref_s[[ii]])
                cur_qry_s <- as.numeric(df_ord$qry_axis_s[[ii]])
                cur_ref_e <- as.numeric(df_ord$ref_e[[ii]])
                cur_qry_e <- as.numeric(df_ord$qry_axis_e[[ii]])
                if (nrow(active) > 0L) {
                    active <- active[
                        ref_e >= (cur_ref_s - overlap_tolerance) &
                            qry_e >= (cur_qry_s - overlap_tolerance)
                    ]
                }

                best_chain <- NA_integer_
                if (nrow(active) > 0L) {
                    cand <- active[
                        ref_e <= (cur_ref_s + max_ref_gap) &
                            qry_e <= (cur_qry_s + max_query_gap)
                    ]
                    if (nrow(cand) > 0L) {
                        cand[, ref_gap := cur_ref_s - ref_e]
                        cand[, qry_gap := cur_qry_s - qry_e]
                        cand <- cand[
                            abs(pmax(ref_gap, 0) - pmax(qry_gap, 0)) <= max_gap_skew
                        ]
                        if (nrow(cand) > 0L) {
                            cand[, penalty := abs(pmax(ref_gap, 0) - pmax(qry_gap, 0)) + pmax(ref_gap, 0) + pmax(qry_gap, 0)]
                            data.table::setorderv(cand, c("penalty", "ref_e", "qry_e"), c(1L, 1L, 1L))
                            best_chain <- as.integer(cand$chain_id[[1]])
                        }
                    }
                }

                if (is.na(best_chain)) {
                    next_chain_id <<- next_chain_id + 1L
                    best_chain <- next_chain_id
                    active <- data.table::rbindlist(
                        list(active, data.table::data.table(chain_id = best_chain, ref_e = cur_ref_e, qry_e = cur_qry_e)),
                        use.names = TRUE
                    )
                } else {
                    row_idx <- match(best_chain, active$chain_id)
                    if (is.finite(row_idx)) {
                        active$ref_e[[row_idx]] <- max(active$ref_e[[row_idx]], cur_ref_e)
                        active$qry_e[[row_idx]] <- max(active$qry_e[[row_idx]], cur_qry_e)
                    }
                }
                chain_ids[[ii]] <- best_chain
            }
            df_ord$chain_id <- as.integer(chain_ids)
            df_ord
        })

        df_ord <- do.call(rbind,  chained_groups)
        chain_rank_df <- aggregate(align_num ~ chain_id, data = df_ord, FUN = function(x) sum(as.numeric(x), na.rm = TRUE))
        chain_rank_df <- chain_rank_df[order(-chain_rank_df$align_num, chain_rank_df$chain_id), , drop = FALSE]
        chain_rank_df$chain_rank <- seq_len(nrow(chain_rank_df))
        df_ord$chain_rank <- chain_rank_df$chain_rank[match(df_ord$chain_id, chain_rank_df$chain_id)]
        df_ord
    }

    merge_pip_chain_segments <- function(df_blocks,
                                         merge_ref_gap = NULL,
                                         merge_query_gap = NULL,
                                         merge_gap_skew = NULL,
                                         overlap_tolerance = NULL) {
        if (!is.data.frame(df_blocks) || nrow(df_blocks) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        typical_span <- suppressWarnings(stats::median(df_blocks$align_num, na.rm = TRUE))
        if (!is.finite(typical_span) || typical_span <= 0) {
            typical_span <- suppressWarnings(stats::median(df_blocks$ref_span, na.rm = TRUE))
        }
        if (!is.finite(typical_span) || typical_span <= 0) {
            typical_span <- 500
        }
        # Conservative display merge:
        # keep chaining for biological grouping, but only collapse HSPs into
        # one painted segment when their gaps are very small on both axes.
        merge_ref_gap <- if (is.null(merge_ref_gap)) max(20, min(180, as.integer(round(typical_span * 0.18)))) else suppressWarnings(as.integer(merge_ref_gap))
        merge_query_gap <- if (is.null(merge_query_gap)) max(20, min(180, as.integer(round(typical_span * 0.18)))) else suppressWarnings(as.integer(merge_query_gap))
        merge_gap_skew <- if (is.null(merge_gap_skew)) max(40, min(320, as.integer(round(typical_span * 0.35)))) else suppressWarnings(as.integer(merge_gap_skew))
        overlap_tolerance <- if (is.null(overlap_tolerance)) max(15, min(120, as.integer(round(typical_span * 0.12)))) else suppressWarnings(as.integer(overlap_tolerance))

        emit_segment <- function(seg_df) {
            seg_df <- seg_df[order(seg_df$ref_s, seg_df$qry_axis_s), , drop = FALSE]
            ref_ranges <- data.frame(start = seg_df$ref_s, end = seg_df$ref_e, stringsAsFactors = FALSE)
            qry_ranges <- data.frame(start = seg_df$qry_s, end = seg_df$qry_e, stringsAsFactors = FALSE)
            align_support <- sum(seg_df$align_num, na.rm = TRUE)
            weighted_identity <- if (is.finite(align_support) && align_support > 0) {
                sum(seg_df$identity_num * seg_df$align_num, na.rm = TRUE) / align_support
            } else {
                NA_real_
            }
            data.frame(
                ref_plot_id = as.character(seg_df$ref_plot_id[1] %||% ""),
                query_plot_id = as.character(seg_df$query_plot_id[1] %||% ""),
                ref_seqid = as.character(seg_df$ref_seqid[1] %||% ""),
                query_seqid = as.character(seg_df$query_seqid[1] %||% ""),
                ref_genomic_start = min(seg_df$ref_s, na.rm = TRUE),
                ref_genomic_end = max(seg_df$ref_e, na.rm = TRUE),
                query_genomic_start = min(seg_df$qry_s, na.rm = TRUE),
                query_genomic_end = max(seg_df$qry_e, na.rm = TRUE),
                strand2 = ifelse(trimws(as.character(seg_df$strand_state[1] %||% "forward")) == "reverse", "-", "+"),
                strand_state = trimws(as.character(seg_df$strand_state[1] %||% "forward")),
                identity_pct = suppressWarnings(as.numeric(weighted_identity)),
                align_len = as.numeric(align_support %||% 0),
                score = sum(seg_df$score_num, na.rm = TRUE),
                component_count = nrow(seg_df),
                covered_ref_bp = feature_ranges_union_length(ref_ranges),
                covered_query_bp = feature_ranges_union_length(qry_ranges),
                chain_id = as.integer(seg_df$chain_id[1] %||% NA_integer_),
                chain_rank = as.integer(seg_df$chain_rank[1] %||% NA_integer_),
                stringsAsFactors = FALSE
            )
        }

        merged_rows <- list()
        block_idx <- 0L
        for (cid in unique(df_blocks$chain_id)) {
            chain_df <- df_blocks[df_blocks$chain_id == cid, , drop = FALSE]
            if (nrow(chain_df) == 0L) {
                next
            }
            chain_df <- chain_df[order(chain_df$ref_s, chain_df$qry_axis_s), , drop = FALSE]
            seg_start <- 1L
            cur_ref_e <- as.numeric(chain_df$ref_e[1])
            cur_qry_e <- as.numeric(chain_df$qry_axis_e[1])
            for (ii in seq_len(nrow(chain_df))[-1]) {
                ref_gap <- as.numeric(chain_df$ref_s[ii]) - cur_ref_e
                qry_gap <- as.numeric(chain_df$qry_axis_s[ii]) - cur_qry_e
                same_segment <- (
                    ref_gap >= -overlap_tolerance &&
                        qry_gap >= -overlap_tolerance &&
                        ref_gap <= merge_ref_gap &&
                        qry_gap <= merge_query_gap &&
                        abs(max(ref_gap, 0) - max(qry_gap, 0)) <= merge_gap_skew
                )
                if (!same_segment) {
                    block_idx <- block_idx + 1L
                    merged_rows[[block_idx]] <- emit_segment(chain_df[seg_start:(ii - 1L), , drop = FALSE])
                    seg_start <- ii
                    cur_ref_e <- as.numeric(chain_df$ref_e[ii])
                    cur_qry_e <- as.numeric(chain_df$qry_axis_e[ii])
                } else {
                    cur_ref_e <- max(cur_ref_e, as.numeric(chain_df$ref_e[ii]))
                    cur_qry_e <- max(cur_qry_e, as.numeric(chain_df$qry_axis_e[ii]))
                }
            }
            block_idx <- block_idx + 1L
            merged_rows[[block_idx]] <- emit_segment(chain_df[seg_start:nrow(chain_df), , drop = FALSE])
        }
        out <- do.call(rbind,  merged_rows)
        if (!is.data.frame(out) || nrow(out) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        out[order(out$chain_rank, out$ref_genomic_start, out$ref_genomic_end), , drop = FALSE]
    }

    build_pip_display_blocks <- function(df_blocks,
                                         min_identity = 70,
                                         min_block_length = 100,
                                         perf_run = NULL,
                                         perf_label = "pip") {
        out_empty <- list(
            raw_blocks = data.frame(stringsAsFactors = FALSE),
            deduplicated_blocks = data.frame(stringsAsFactors = FALSE),
            filtered_blocks = data.frame(stringsAsFactors = FALSE),
            chained_blocks = data.frame(stringsAsFactors = FALSE),
            display_blocks = data.frame(stringsAsFactors = FALSE)
        )
        step_time <- function(expr, step_txt) {
            t0 <- proc.time()[["elapsed"]]
            value <- expr
            elapsed_ms <- 1000 * (proc.time()[["elapsed"]] - t0)
            if (!is.null(perf_run)) {
                app_perf_mark(
                    perf_run,
                    sprintf("%s_%s_ms=%.1f", as.character(perf_label %||% "pip"), as.character(step_txt %||% "step"), as.numeric(elapsed_ms)),
                    "ORTHO_PIP_PIPE"
                )
            }
            value
        }
        normalized_df <- step_time(
            normalize_pip_local_blocks(
                df_blocks,
                min_identity = min_identity,
                min_block_length = min_block_length
            ),
            "normalize"
        )
        if (!is.data.frame(normalized_df) || nrow(normalized_df) == 0L) {
            return(out_empty)
        }
        dedup_df <- step_time(deduplicate_pip_local_blocks(normalized_df), "deduplicate")
        if (!is.data.frame(dedup_df) || nrow(dedup_df) == 0L) {
            return(out_empty)
        }
        filtered_df <- step_time(prune_pip_contained_blocks(dedup_df), "prune_contained")
        if (!is.data.frame(filtered_df) || nrow(filtered_df) == 0L) {
            return(out_empty)
        }
        chained_df <- step_time(chain_pip_local_blocks(filtered_df), "chain")
        if (!is.data.frame(chained_df) || nrow(chained_df) == 0L) {
            return(out_empty)
        }
        display_df <- step_time(merge_pip_chain_segments(chained_df), "merge")
        out_empty$raw_blocks <- normalized_df
        out_empty$deduplicated_blocks <- dedup_df
        out_empty$filtered_blocks <- filtered_df
        out_empty$chained_blocks <- chained_df
        out_empty$display_blocks <- display_df
        out_empty
    }

    summarize_pip_reference_support <- function(df_blocks, min_identity = 70, min_block_length = 100) {
        out_empty <- list(
            visible = FALSE,
            covered_bp = 0,
            aligned_bp = 0,
            weighted_identity = NA_real_,
            reduced_block_count = 0L,
            display_block_count = 0L,
            chain_count = 0L,
            coverage_fraction = 0,
            blocks_df = df_blocks
        )
        if (!is.data.frame(df_blocks) || nrow(df_blocks) == 0L) {
            return(out_empty)
        }
        pip_blocks <- build_pip_display_blocks(
            df_blocks,
            min_identity = min_identity,
            min_block_length = min_block_length
        )
        reduced_df <- pip_blocks$display_blocks
        if (!is.data.frame(reduced_df) || nrow(reduced_df) == 0L) {
            return(out_empty)
        }
        ref_ranges <- data.frame(
            start = suppressWarnings(as.numeric(pmin(reduced_df$ref_genomic_start, reduced_df$ref_genomic_end))),
            end = suppressWarnings(as.numeric(pmax(reduced_df$ref_genomic_start, reduced_df$ref_genomic_end))),
            stringsAsFactors = FALSE
        )
        covered_bp <- feature_ranges_union_length(ref_ranges)
        aligned_bp <- sum(suppressWarnings(as.numeric(reduced_df$align_len)), na.rm = TRUE)
        weighted_identity <- if (is.finite(aligned_bp) && aligned_bp > 0) {
            sum(suppressWarnings(as.numeric(reduced_df$identity_pct)) * suppressWarnings(as.numeric(reduced_df$align_len)), na.rm = TRUE) / aligned_bp
        } else {
            NA_real_
        }
        window_span <- max(1, max(ref_ranges$end, na.rm = TRUE) - min(ref_ranges$start, na.rm = TRUE) + 1)
        list(
            visible = nrow(reduced_df) > 0L,
            covered_bp = as.numeric(covered_bp %||% 0),
            aligned_bp = as.numeric(aligned_bp %||% 0),
            weighted_identity = suppressWarnings(as.numeric(weighted_identity)),
            reduced_block_count = as.integer(nrow(reduced_df)),
            display_block_count = as.integer(nrow(reduced_df)),
            chain_count = as.integer(length(unique(stats::na.omit(reduced_df$chain_id)))),
            coverage_fraction = if (is.finite(covered_bp) && is.finite(window_span) && window_span > 0) covered_bp / window_span else 0,
            blocks_df = reduced_df
        )
    }

    load_reference_window_features <- function(ref_ctx) {
        if (is.null(ref_ctx)) return(NULL)
        plot_id <- trimws(as.character(ref_ctx$plot_id %||% ""))
        if (!nzchar(plot_id)) return(NULL)
        ref_plot_data <- tryCatch(fileDataOrthologous()[[plot_id]], error = function(e) NULL)
        if (is.null(ref_plot_data)) return(NULL)
        ref_raw_df <- as.data.frame(ref_plot_data, stringsAsFactors = FALSE)
        if (nrow(ref_raw_df) == 0L) return(NULL)
        feature_type_raw <- tolower(trimws(as.character(ref_raw_df$V3 %||% rep("", nrow(ref_raw_df)))))
        ref_raw_df$feature_group <- ifelse(
            grepl("utr", feature_type_raw), "utr",
            ifelse(feature_type_raw %in% c("cds", "start_codon", "stop_codon"), "cds",
                   ifelse(feature_type_raw == "exon", "exon", "other"))
        )
        ref_raw_df$feature_type_raw <- feature_type_raw
        ref_raw_df$genomic_start <- suppressWarnings(as.numeric(ref_raw_df$V4))
        ref_raw_df$genomic_end   <- suppressWarnings(as.numeric(ref_raw_df$V5))
        ref_raw_df <- ref_raw_df[
            ref_raw_df$feature_group %in% c("exon", "cds", "utr") &
                is.finite(ref_raw_df$genomic_start) &
                is.finite(ref_raw_df$genomic_end),
            , drop = FALSE
        ]
        if (nrow(ref_raw_df) == 0L) return(NULL)
        ref_raw_df
    }

    build_hover_segment_overlay <- function(df,
                                            x_col,
                                            xend_col,
                                            y_col,
                                            tooltip_col = "tooltip",
                                            data_id_col = "data_id",
                                            id_suffix = "_hover",
                                            min_span = 0) {
        if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        required_cols <- c(x_col, xend_col, y_col, tooltip_col, data_id_col)
        if (!all(required_cols %in% names(df))) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        x_num <- suppressWarnings(as.numeric(df[[x_col]]))
        xend_num <- suppressWarnings(as.numeric(df[[xend_col]]))
        y_num <- suppressWarnings(as.numeric(df[[y_col]]))
        tooltip_txt <- sanitize_girafe_tooltip_text(df[[tooltip_col]] %||% rep("", nrow(df)))
        data_id_txt <- sanitize_girafe_data_id(df[[data_id_col]] %||% rep("", nrow(df)), fallback_prefix = "hoverseg")
        left <- pmin(x_num, xend_num)
        right <- pmax(x_num, xend_num)
        min_span_num <- suppressWarnings(as.numeric(min_span %||% 0))
        if (is.finite(min_span_num) && min_span_num > 0) {
            cur_span <- right - left
            expand_idx <- is.finite(cur_span) & cur_span < min_span_num
            if (any(expand_idx)) {
                mid <- (left[expand_idx] + right[expand_idx]) / 2
                left[expand_idx] <- mid - min_span_num / 2
                right[expand_idx] <- mid + min_span_num / 2
            }
        }
        keep <- is.finite(left) &
            is.finite(right) &
            is.finite(y_num) &
            !is.na(tooltip_txt) &
            nzchar(trimws(tooltip_txt)) &
            !is.na(data_id_txt) &
            nzchar(trimws(data_id_txt))
        if (!any(keep)) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        out <- data.frame(
            x = left[keep],
            xend = right[keep],
            y = y_num[keep],
            yend = y_num[keep],
            tooltip = tooltip_txt[keep],
            data_id = paste0(data_id_txt[keep], id_suffix, "_", seq_len(sum(keep))),
            stringsAsFactors = FALSE
        )
        rownames(out) <- NULL
        out
    }

    build_hover_rect_overlay <- function(df,
                                         xmin_col,
                                         xmax_col,
                                         ymin_col,
                                         ymax_col,
                                         tooltip_col = "tooltip",
                                         data_id_col = "data_id",
                                         id_suffix = "_hover_rect",
                                         min_width = 0,
                                         min_height = 0) {
        if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        required_cols <- c(xmin_col, xmax_col, ymin_col, ymax_col, tooltip_col, data_id_col)
        if (!all(required_cols %in% names(df))) {
            return(data.frame(stringsAsFactors = FALSE))
        }
        xmin_num <- suppressWarnings(as.numeric(df[[xmin_col]]))
        xmax_num <- suppressWarnings(as.numeric(df[[xmax_col]]))
        ymin_num <- suppressWarnings(as.numeric(df[[ymin_col]]))
        ymax_num <- suppressWarnings(as.numeric(df[[ymax_col]]))
        tooltip_txt <- sanitize_girafe_tooltip_text(df[[tooltip_col]] %||% rep("", nrow(df)))
        data_id_txt <- sanitize_girafe_data_id(df[[data_id_col]] %||% rep("", nrow(df)), fallback_prefix = "hoverrect")

        left <- pmin(xmin_num, xmax_num)
        right <- pmax(xmin_num, xmax_num)
        bottom <- pmin(ymin_num, ymax_num)
        top <- pmax(ymin_num, ymax_num)

        min_width_num <- suppressWarnings(as.numeric(min_width %||% 0))
        if (is.finite(min_width_num) && min_width_num > 0) {
            cur_width <- right - left
            expand_w_idx <- is.finite(cur_width) & cur_width < min_width_num
            if (any(expand_w_idx)) {
                mid_x <- (left[expand_w_idx] + right[expand_w_idx]) / 2
                left[expand_w_idx] <- mid_x - min_width_num / 2
                right[expand_w_idx] <- mid_x + min_width_num / 2
            }
        }

        min_height_num <- suppressWarnings(as.numeric(min_height %||% 0))
        if (is.finite(min_height_num) && min_height_num > 0) {
            cur_height <- top - bottom
            expand_h_idx <- is.finite(cur_height) & cur_height < min_height_num
            if (any(expand_h_idx)) {
                mid_y <- (bottom[expand_h_idx] + top[expand_h_idx]) / 2
                bottom[expand_h_idx] <- mid_y - min_height_num / 2
                top[expand_h_idx] <- mid_y + min_height_num / 2
            }
        }

        keep <- is.finite(left) &
            is.finite(right) &
            is.finite(bottom) &
            is.finite(top) &
            !is.na(tooltip_txt) &
            nzchar(trimws(tooltip_txt)) &
            !is.na(data_id_txt) &
            nzchar(trimws(data_id_txt))
        if (!any(keep)) {
            return(data.frame(stringsAsFactors = FALSE))
        }

        out <- data.frame(
            xmin = left[keep],
            xmax = right[keep],
            ymin = bottom[keep],
            ymax = top[keep],
            tooltip = tooltip_txt[keep],
            data_id = paste0(data_id_txt[keep], id_suffix, "_", seq_len(sum(keep))),
            stringsAsFactors = FALSE
        )
        rownames(out) <- NULL
        out
    }

    # Merge adjacent/overlapping LASTZ blocks of the same category and strand for
    # the hover layer. This reduces interactive SVG element count from potentially
    # thousands to a manageable number without touching the visual rendering at all.
    # Blocks are grouped per (y, id_cat, strand_state). Within each group, a simple
    # sweep-line merge collapses all overlapping or touching blocks into one rect
    # whose tooltip summarises the group (count, identity range, span).
    merge_blocks_for_hover <- function(df,
                                       gap_fraction = 0.002,
                                       ref_window_span = 1L) {
        if (!is.data.frame(df) || nrow(df) == 0L) return(df)
        required <- c("rect_xmin", "rect_xmax", "y", "id_cat", "strand_state",
                      "hover_ymin", "hover_ymax", "tooltip", "data_id")
        if (!all(required %in% names(df))) return(df)

        gap_bp <- max(1, ref_window_span * gap_fraction)
        rows_out <- list()

        # Group by track row (y) + category + strand
        group_keys <- paste(
            round(df$y, 4),
            as.character(df$id_cat %||% ""),
            as.character(df$strand_state %||% ""),
            sep = "|"
        )
        for (gk in unique(group_keys)) {
            g <- df[group_keys == gk, , drop = FALSE]
            if (nrow(g) == 0L) next
            # Sort by left edge
            ord <- order(suppressWarnings(as.numeric(g$rect_xmin)))
            g <- g[ord, , drop = FALSE]

            x_left   <- suppressWarnings(as.numeric(g$rect_xmin))
            x_right  <- suppressWarnings(as.numeric(g$rect_xmax))
            id_pct   <- suppressWarnings(as.numeric(g$identity_pct %||% NA_real_))
            align_bp <- suppressWarnings(as.numeric(g$align_len %||% NA_real_))

            # Sweep-line merge: collapse blocks separated by less than gap_bp
            cur_left  <- x_left[1]
            cur_right <- x_right[1]
            grp_idx   <- integer(nrow(g))
            grp_id    <- 1L
            grp_idx[1] <- grp_id
            if (nrow(g) > 1L) {
                for (k in 2:nrow(g)) {
                    if (is.finite(x_left[k]) && x_left[k] <= cur_right + gap_bp) {
                        cur_right <- max(cur_right, x_right[k], na.rm = TRUE)
                        grp_idx[k] <- grp_id
                    } else {
                        grp_id <- grp_id + 1L
                        cur_left  <- x_left[k]
                        cur_right <- x_right[k]
                        grp_idx[k] <- grp_id
                    }
                }
            }

            for (gi in unique(grp_idx)) {
                sel <- grp_idx == gi
                sub <- g[sel, , drop = FALSE]
                xmin_m <- suppressWarnings(min(as.numeric(sub$rect_xmin), na.rm = TRUE))
                xmax_m <- suppressWarnings(max(as.numeric(sub$rect_xmax), na.rm = TRUE))
                xmin_m_disp <- if ("rect_xmin_disp" %in% names(sub)) {
                    suppressWarnings(min(as.numeric(sub$rect_xmin_disp), na.rm = TRUE))
                } else {
                    xmin_m
                }
                xmax_m_disp <- if ("rect_xmax_disp" %in% names(sub)) {
                    suppressWarnings(max(as.numeric(sub$rect_xmax_disp), na.rm = TRUE))
                } else {
                    xmax_m
                }
                id_min <- suppressWarnings(min(as.numeric(sub$identity_pct %||% NA_real_), na.rm = TRUE))
                id_max <- suppressWarnings(max(as.numeric(sub$identity_pct %||% NA_real_), na.rm = TRUE))
                n_blk  <- nrow(sub)
                orient <- if (identical(as.character(sub$strand_state[1] %||% ""), "reverse")) {
                    "reverse / inversion candidate"
                } else {
                    "forward"
                }
                cat_lbl <- dplyr::case_when(
                    identical(as.character(sub$id_cat[1] %||% ""), "identical") ~ "\u226595% — nearly identical",
                    identical(as.character(sub$id_cat[1] %||% ""), "similar")   ~ "80–94% — similar",
                    TRUE ~ "60–79% — moderately similar"
                )
                qry_lbl <- as.character(sub$query_label[1] %||% "")
                tip <- if (n_blk == 1L) {
                    # Single block — use original tooltip verbatim
                    as.character(sub$tooltip[1])
                } else {
                    # Merged group — produce a summary tooltip
                    id_rng <- if (is.finite(id_min) && is.finite(id_max) && abs(id_max - id_min) > 0.1) {
                        sprintf("%.1f–%.1f%%", id_min, id_max)
                    } else if (is.finite(id_max)) {
                        sprintf("%.1f%%", id_max)
                    } else {
                        "—"
                    }
                    span_bp <- format(as.integer(round(xmax_m - xmin_m)), big.mark = ",")
                    sub_starts <- suppressWarnings(as.numeric(sub$rect_xmin))
                    sub_ends <- suppressWarnings(as.numeric(sub$rect_xmax))
                    sub_id_pct <- suppressWarnings(as.numeric(sub$identity_pct %||% NA_real_))
                    sub_len_bp <- pmax(0, suppressWarnings(as.numeric(sub_ends - sub_starts)))
                    detail_n <- min(n_blk, 4L)
                    detail_idx <- seq_len(detail_n)
                    detail_lines <- vapply(detail_idx, function(ii) {
                        start_txt <- if (is.finite(sub_starts[ii])) format(as.integer(round(sub_starts[ii])), big.mark = ",") else "?"
                        end_txt <- if (is.finite(sub_ends[ii])) format(as.integer(round(sub_ends[ii])), big.mark = ",") else "?"
                        len_txt <- if (is.finite(sub_len_bp[ii])) format(as.integer(round(sub_len_bp[ii])), big.mark = ",") else "?"
                        id_txt <- if (is.finite(sub_id_pct[ii])) sprintf("%.1f%%", sub_id_pct[ii]) else "—"
                        sprintf("&bull; %s-%s bp | %s | %s bp", start_txt, end_txt, id_txt, len_txt)
                    }, character(1))
                    extra_txt <- if (n_blk > detail_n) {
                        sprintf("<br/><i>+ %d additional overlapping region%s</i>", n_blk - detail_n, if ((n_blk - detail_n) == 1L) "" else "s")
                    } else {
                        ""
                    }
                    sprintf(
                        paste0(
                            "<b>%s</b><br/>",
                            "<b>Overlapping LASTZ region summary: %d blocks</b><br/>",
                            "<b>Category:</b> %s<br/>",
                            "<b>Orientation:</b> %s<br/>",
                            "<b>Identity range:</b> %s<br/>",
                            "<b>Merged span:</b> %s bp<br/>",
                            "<b>Included regions:</b><br/>%s%s"
                        ),
                        qry_lbl, n_blk, cat_lbl, orient, id_rng, span_bp,
                        paste(detail_lines, collapse = "<br/>"),
                        extra_txt
                    )
                }

                rows_out[[length(rows_out) + 1L]] <- data.frame(
                    rect_xmin   = xmin_m,
                    rect_xmax   = xmax_m,
                    rect_xmin_disp = xmin_m_disp,
                    rect_xmax_disp = xmax_m_disp,
                    y           = sub$y[1],
                    hover_ymin  = sub$hover_ymin[1],
                    hover_ymax  = sub$hover_ymax[1],
                    id_cat      = sub$id_cat[1],
                    strand_state = sub$strand_state[1],
                    tooltip     = tip,
                    data_id     = paste0("merged_blk_", sub$data_id[1]),
                    stringsAsFactors = FALSE
                )
            }
        }
        if (length(rows_out) == 0L) return(df[0L, , drop = FALSE])
        out <- do.call(rbind,  rows_out)
        rownames(out) <- NULL
        out
    }

    orient_reference_coord <- function(x, window_start, window_end, strand = "+") {
        x_num <- suppressWarnings(as.numeric(x))
        ws <- suppressWarnings(as.numeric(window_start))
        we <- suppressWarnings(as.numeric(window_end))
        strand_txt <- trimws(as.character(strand %||% "+"))[1L]
        if (!is.finite(ws) || !is.finite(we) || !identical(strand_txt, "-")) {
            return(x_num)
        }
        ws + we - x_num
    }

    add_reference_display_range <- function(df,
                                            start_col = "xstart_clip",
                                            end_col = "xend_clip",
                                            window_start,
                                            window_end,
                                            strand = "+",
                                            out_start = "xstart_disp",
                                            out_end = "xend_disp") {
        if (!is.data.frame(df) || nrow(df) == 0L) {
            return(df)
        }
        start_num <- suppressWarnings(as.numeric(df[[start_col]]))
        end_num <- suppressWarnings(as.numeric(df[[end_col]]))
        start_disp <- orient_reference_coord(start_num, window_start, window_end, strand = strand)
        end_disp <- orient_reference_coord(end_num, window_start, window_end, strand = strand)
        df[[out_start]] <- pmin(start_disp, end_disp, na.rm = FALSE)
        df[[out_end]] <- pmax(start_disp, end_disp, na.rm = FALSE)
        df
    }

    materialize_multipip_underlay_features <- function(ref_features,
                                                       ref_window_start,
                                                       ref_window_end,
                                                       ref_strand = "+",
                                                       ref_row_y = NA_real_,
                                                       feature_palette = list(),
                                                       feature_border = "#2C3E50") {
        if (!is.data.frame(ref_features) || nrow(ref_features) == 0L) {
            return(list(exon_df = NULL, utr_df = NULL, cds_df = NULL))
        }
        ref_window_start <- suppressWarnings(as.numeric(ref_window_start))
        ref_window_end <- suppressWarnings(as.numeric(ref_window_end))
        if (!is.finite(ref_window_start) || !is.finite(ref_window_end)) {
            return(list(exon_df = NULL, utr_df = NULL, cds_df = NULL))
        }
        ref_strand <- trimws(as.character(ref_strand %||% "+"))
        ref_features <- as.data.frame(ref_features, stringsAsFactors = FALSE)
        ref_features$xstart_clip <- pmax(ref_window_start, suppressWarnings(as.numeric(ref_features$genomic_start)))
        ref_features$xend_clip <- pmin(ref_window_end, suppressWarnings(as.numeric(ref_features$genomic_end)))
        ref_features <- ref_features[
            is.finite(ref_features$xstart_clip) &
                is.finite(ref_features$xend_clip) &
                ref_features$xend_clip >= ref_features$xstart_clip,
            , drop = FALSE
        ]
        if (nrow(ref_features) == 0L) {
            return(list(exon_df = NULL, utr_df = NULL, cds_df = NULL))
        }
        ref_features$tooltip <- ifelse(
            ref_features$feature_group == "cds",
            paste0("Coding exon<br/>", format(ref_features$xstart_clip, big.mark = ","), "\u2013", format(ref_features$xend_clip, big.mark = ","), " bp"),
            ifelse(
                ref_features$feature_group == "utr",
                paste0("UTR / non-coding exon<br/>", format(ref_features$xstart_clip, big.mark = ","), "\u2013", format(ref_features$xend_clip, big.mark = ","), " bp"),
                paste0("Exon context<br/>", format(ref_features$xstart_clip, big.mark = ","), "\u2013", format(ref_features$xend_clip, big.mark = ","), " bp")
            )
        )
        ref_features$data_id <- paste0("multipip_ref_feature_", seq_len(nrow(ref_features)))

        cds_df  <- ref_features[ref_features$feature_group == "cds",  , drop = FALSE]
        exon_df <- ref_features[ref_features$feature_group == "exon", , drop = FALSE]
        utr_df  <- ref_features[ref_features$feature_group == "utr",  , drop = FALSE]

        assign_exon_rank <- function(df) {
            if (!is.data.frame(df) || nrow(df) == 0L) return(df)
            if (identical(ref_strand, "-")) {
                df$exon_rank <- rank(-df$xstart_clip, ties.method = "first")
            } else {
                df$exon_rank <- rank(df$xstart_clip, ties.method = "first")
            }
            df
        }
        exon_df <- assign_exon_rank(exon_df)

        inherit_exon_rank <- function(df, exon_source_df) {
            if (!is.data.frame(df) || nrow(df) == 0L || !is.data.frame(exon_source_df) || nrow(exon_source_df) == 0L) {
                return(df)
            }
            exon_starts <- suppressWarnings(as.numeric(exon_source_df$xstart_clip))
            exon_ends <- suppressWarnings(as.numeric(exon_source_df$xend_clip))
            exon_ranks <- suppressWarnings(as.numeric(exon_source_df$exon_rank))
            df$exon_rank <- vapply(seq_len(nrow(df)), function(i) {
                cur_start <- suppressWarnings(as.numeric(df$xstart_clip[[i]]))
                cur_end <- suppressWarnings(as.numeric(df$xend_clip[[i]]))
                hits <- which(is.finite(exon_starts) & is.finite(exon_ends) & exon_starts <= cur_end & exon_ends >= cur_start)
                if (length(hits) == 0L) return(NA_real_)
                suppressWarnings(min(exon_ranks[hits], na.rm = TRUE))
            }, numeric(1))
            df
        }
        cds_df <- inherit_exon_rank(cds_df, exon_df)
        utr_df <- inherit_exon_rank(utr_df, exon_df)

        exon_df <- add_reference_display_range(exon_df, window_start = ref_window_start, window_end = ref_window_end, strand = ref_strand)
        cds_df <- add_reference_display_range(cds_df, window_start = ref_window_start, window_end = ref_window_end, strand = ref_strand)
        utr_df <- add_reference_display_range(utr_df, window_start = ref_window_start, window_end = ref_window_end, strand = ref_strand)
        ref_features <- add_reference_display_range(ref_features, window_start = ref_window_start, window_end = ref_window_end, strand = ref_strand)

        if (is.data.frame(exon_df) && nrow(exon_df) > 0L && "exon_rank" %in% names(exon_df)) {
            exon_df$tooltip <- sprintf(
                "<b>Exon %d</b><br/>Exon span<br/>%s\u2013%s bp<br/>Length: %s bp",
                as.integer(exon_df$exon_rank),
                format(as.integer(round(exon_df$xstart_clip)), big.mark = ","),
                format(as.integer(round(exon_df$xend_clip)),   big.mark = ","),
                format(as.integer(round(exon_df$xend_clip - exon_df$xstart_clip + 1)), big.mark = ",")
            )
        }
        if (is.data.frame(utr_df) && nrow(utr_df) > 0L && "exon_rank" %in% names(utr_df)) {
            utr_df$tooltip <- sprintf(
                "<b>Exon %d</b><br/>UTR / non-coding exon<br/>%s\u2013%s bp<br/>Length: %s bp",
                as.integer(utr_df$exon_rank),
                format(as.integer(round(utr_df$xstart_clip)), big.mark = ","),
                format(as.integer(round(utr_df$xend_clip)),   big.mark = ","),
                format(as.integer(round(utr_df$xend_clip - utr_df$xstart_clip + 1)), big.mark = ",")
            )
        }
        if (is.data.frame(cds_df) && nrow(cds_df) > 0L && "exon_rank" %in% names(cds_df)) {
            cds_df$tooltip <- sprintf(
                "<b>Exon %d</b><br/>CDS region<br/>%s\u2013%s bp<br/>Length: %s bp",
                as.integer(cds_df$exon_rank),
                format(as.integer(round(cds_df$xstart_clip)), big.mark = ","),
                format(as.integer(round(cds_df$xend_clip)),   big.mark = ","),
                format(as.integer(round(cds_df$xend_clip - cds_df$xstart_clip + 1)), big.mark = ",")
            )
        }

        list(
            all_df  = ref_features,
            exon_df = exon_df,
            utr_df  = utr_df,
            cds_df  = cds_df,
            palette = feature_palette,
            border  = feature_border,
            y       = ref_row_y
        )
    }

    build_multipip_underlay_features <- function(ref_ctx, ref_row_y, feature_palette, feature_border) {

        if (is.null(ref_ctx)) {
            return(list(exon_df = NULL, utr_df = NULL, cds_df = NULL))
        }
        ref_features <- tryCatch(load_reference_window_features(ref_ctx), error = function(e) NULL)
        if (!is.data.frame(ref_features) || nrow(ref_features) == 0L) {
            return(list(exon_df = NULL, utr_df = NULL, cds_df = NULL))
        }
        ref_window_start <- suppressWarnings(as.numeric(ref_ctx$window_start %||% NA_real_))
        ref_window_end <- suppressWarnings(as.numeric(ref_ctx$window_end %||% NA_real_))
        materialize_multipip_underlay_features(
            ref_features = ref_features,
            ref_window_start = ref_window_start,
            ref_window_end = ref_window_end,
            ref_strand = ref_ctx$strand %||% "+",
            ref_row_y = ref_row_y,
            feature_palette = feature_palette,
            feature_border = feature_border
        )
    }

    # ---------------------------------------------------------------------------
    # Gene structure annotation panel — PipMaker style (top panel of MultiPIP)
    # Returns a ggplot object ready to be stacked above the identity tracks via
    # patchwork. Uses the same x coordinate system as the MultiPIP main plot so
    # that patchwork alignment is pixel-perfect.
    # ---------------------------------------------------------------------------
    build_multipip_gene_structure_panel <- function(ref_ctx,
                                                    ref_underlay,
                                                    ref_window_start,
                                                    ref_window_end,
                                                    bg_color      = "#FFFDF7",
                                                    axis_color    = "#2F4357",
                                                    frame_color   = "#3C3A35",
                                                    exon_fill     = NULL,
                                                    cds_fill      = NULL,
                                                    utr_fill      = NULL,
                                                    ref_org_label = NULL) {
        ref_span   <- max(ref_window_end - ref_window_start, .Machine$double.eps)
        ref_strand <- trimws(as.character(ref_ctx$strand %||% "+"))
        is_minus   <- identical(ref_strand, "-")
        disp_window_start <- suppressWarnings(min(orient_reference_coord(c(ref_window_start, ref_window_end), ref_window_start, ref_window_end, strand = ref_strand), na.rm = TRUE))
        disp_window_end <- suppressWarnings(max(orient_reference_coord(c(ref_window_start, ref_window_end), ref_window_start, ref_window_end, strand = ref_strand), na.rm = TRUE))

        # Gene body window boundaries (clipped to display window)
        gene_start_raw <- suppressWarnings(as.numeric(ref_ctx$gene_start %||% NA_real_))
        gene_end_raw   <- suppressWarnings(as.numeric(ref_ctx$gene_end   %||% NA_real_))
        gene_start_clip <- if (is.finite(gene_start_raw)) pmax(ref_window_start, gene_start_raw) else ref_window_start
        gene_end_clip   <- if (is.finite(gene_end_raw))   pmin(ref_window_end,   gene_end_raw)   else ref_window_end
        gene_start_disp <- suppressWarnings(min(orient_reference_coord(c(gene_start_clip, gene_end_clip), ref_window_start, ref_window_end, strand = ref_strand), na.rm = TRUE))
        gene_end_disp <- suppressWarnings(max(orient_reference_coord(c(gene_start_clip, gene_end_clip), ref_window_start, ref_window_end, strand = ref_strand), na.rm = TRUE))

        # Y constants — CDS/UTR kept flat so the panel reads clean
        BACKBONE_Y <- 0.40
        CDS_YMIN   <- 0.24
        CDS_YMAX   <- 0.52
        UTR_YMIN   <- 0.27
        UTR_YMAX   <- 0.46
        LABEL_Y    <- 0.84

        # Gene name label: gene symbol + strand sign, centered, no coordinates
        gene_label  <- trimws(as.character(ref_ctx$gene_label %||% ref_ctx$title %||% "Reference"))
        strand_sym  <- if (is_minus) "(-)" else "(+)"
        locus_label <- paste0(gene_label, " ", strand_sym)

        # Direction chevrons along full display window (including flanking context)
        chevron_spacing <- ref_span * 0.05
        chevron_half    <- ref_span * 0.006
        # Cover the entire display window, not just the gene body
        chevron_from   <- disp_window_start + chevron_spacing
        chevron_to     <- disp_window_end   - chevron_spacing
        chevron_starts <- if (chevron_from < chevron_to) {
            seq(chevron_from, chevron_to, by = chevron_spacing)
        } else {
            numeric(0)
        }
        chevron_starts  <- chevron_starts[
            chevron_starts > disp_window_start + 0.01 * ref_span &
            chevron_starts < disp_window_end   - 0.01 * ref_span
        ]
        chevron_df <- if (length(chevron_starts) > 0L) {
            data.frame(
                x    = chevron_starts - chevron_half,
                xend = chevron_starts + chevron_half,
                y    = BACKBONE_Y,
                yend = BACKBONE_Y,
                stringsAsFactors = FALSE
            )
        } else {
            NULL
        }

        cds_df <- ref_underlay$cds_df %||% data.frame(stringsAsFactors = FALSE)
        exon_df <- ref_underlay$exon_df %||% data.frame(stringsAsFactors = FALSE)
        utr_df <- ref_underlay$utr_df %||% data.frame(stringsAsFactors = FALSE)
        has_cds <- is.data.frame(cds_df) && nrow(cds_df) > 0L
        has_exon <- is.data.frame(exon_df) && nrow(exon_df) > 0L
        has_utr <- is.data.frame(utr_df) && nrow(utr_df) > 0L

        exon_fill <- exon_fill %||% ref_underlay$palette$exon %||% "#F45D75"
        cds_fill <- cds_fill %||% ref_underlay$palette$cds %||% "#E8A44F"
        utr_fill <- utr_fill %||% ref_underlay$palette$utr %||% "#5BC0EB"
        border_c <- ref_underlay$border %||% "#2C3E50"
        hover_min_span <- max(ref_span * 0.0005, .Machine$double.eps)
        hover_min_height <- 0.11
        exon_hover_df <- data.frame(stringsAsFactors = FALSE)
        utr_hover_df <- data.frame(stringsAsFactors = FALSE)
        cds_hover_df <- data.frame(stringsAsFactors = FALSE)
        if (has_exon) {
            exon_df$hover_ymin <- CDS_YMIN
            exon_df$hover_ymax <- CDS_YMAX
            exon_hover_df <- build_hover_rect_overlay(
                exon_df,
                xmin_col = "xstart_disp",
                xmax_col = "xend_disp",
                ymin_col = "hover_ymin",
                ymax_col = "hover_ymax",
                tooltip_col = "tooltip",
                data_id_col = "data_id",
                id_suffix = "_panel",
                min_width = hover_min_span,
                min_height = hover_min_height
            )
        }
        if (has_utr) {
            utr_df$hover_ymin <- UTR_YMIN
            utr_df$hover_ymax <- UTR_YMAX
            utr_hover_df <- build_hover_rect_overlay(
                utr_df,
                xmin_col = "xstart_disp",
                xmax_col = "xend_disp",
                ymin_col = "hover_ymin",
                ymax_col = "hover_ymax",
                tooltip_col = "tooltip",
                data_id_col = "data_id",
                id_suffix = "_panel",
                min_width = hover_min_span,
                min_height = hover_min_height * 0.85
            )
        }
        if (has_cds) {
            cds_df$hover_ymin <- CDS_YMIN
            cds_df$hover_ymax <- CDS_YMAX
            cds_hover_df <- build_hover_rect_overlay(
                cds_df,
                xmin_col = "xstart_disp",
                xmax_col = "xend_disp",
                ymin_col = "hover_ymin",
                ymax_col = "hover_ymax",
                tooltip_col = "tooltip",
                data_id_col = "data_id",
                id_suffix = "_panel",
                min_width = hover_min_span,
                min_height = hover_min_height
            )
        }

        p <- ggplot2::ggplot() +
            # Overall background
            ggplot2::theme_void() +
            ggplot2::theme(
                panel.background  = ggplot2::element_rect(fill = bg_color, color = NA),
                plot.background   = ggplot2::element_rect(fill = bg_color, color = NA),
                axis.text.x       = ggplot2::element_blank(),
                axis.ticks.x      = ggplot2::element_blank(),
                axis.title.x      = ggplot2::element_blank(),
                plot.margin       = ggplot2::margin(t = 0, r = 0, b = -6, l = 0, unit = "pt")
            ) +
            # Gene body subtle background highlight (neutral, matches app bg)
            ggplot2::annotate("rect",
                xmin = gene_start_disp, xmax = gene_end_disp,
                ymin = 0, ymax = 1,
                fill = "#E8EDF2", color = NA, alpha = 0.55
            ) +
            # Genomic backbone: extends across the full display window (gene body + any
            # flanking context), so the directionality line is always visible even in
            # the padding/flank regions outside the transcribed gene body.
            ggplot2::annotate("segment",
                x = disp_window_start, xend = disp_window_end,
                y = BACKBONE_Y, yend = BACKBONE_Y,
                color = frame_color, linewidth = 0.55
            ) +
            # Direction chevrons
            {
                if (!is.null(chevron_df) && nrow(chevron_df) > 0L) {
                    ggplot2::geom_segment(
                        data = chevron_df,
                        ggplot2::aes(x = x, xend = xend, y = y, yend = yend),
                        inherit.aes = FALSE,
                        color    = axis_color,
                        linewidth = 0.38,
                        arrow    = ggplot2::arrow(
                            length = ggplot2::unit(0.06, "inches"),
                            type   = "open",
                            ends   = "last"
                        )
                    )
                }
            } +
            # Full exon extents (drawn first so CDS / UTR can refine them)
            {
                if (has_exon) {
                    ggplot2::geom_rect(
                        data = exon_df,
                        ggplot2::aes(
                            xmin    = xstart_disp,
                            xmax    = xend_disp,
                            ymin    = CDS_YMIN,
                            ymax    = CDS_YMAX
                        ),
                        inherit.aes = FALSE,
                        fill      = exon_fill,
                        color     = border_c,
                        linewidth = 0.24,
                        alpha     = 1
                    )
                }
            } +
            # UTR blocks (narrower)
            {
                if (has_utr) {
                    ggplot2::geom_rect(
                        data = utr_df,
                        ggplot2::aes(
                            xmin    = xstart_disp,
                            xmax    = xend_disp,
                            ymin    = UTR_YMIN,
                            ymax    = UTR_YMAX
                        ),
                        inherit.aes = FALSE,
                        fill      = utr_fill,
                        color     = border_c,
                        linewidth = 0.28
                    )
                }
            } +
            # CDS blocks (full height)
            {
                if (has_cds) {
                    ggplot2::geom_rect(
                        data = cds_df,
                        ggplot2::aes(
                            xmin    = xstart_disp,
                            xmax    = xend_disp,
                            ymin    = CDS_YMIN,
                            ymax    = CDS_YMAX
                        ),
                        inherit.aes = FALSE,
                        fill      = cds_fill,
                        color     = border_c,
                        linewidth = 0.35
                    )
                }
            } +
            {
                hover_layers <- list()
                if (is.data.frame(exon_hover_df) && nrow(exon_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = exon_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        inherit.aes = FALSE,
                        color = NA,
                        fill = axis_color,
                        alpha = 0.003
                    )
                }
                if (is.data.frame(utr_hover_df) && nrow(utr_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = utr_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        inherit.aes = FALSE,
                        color = NA,
                        fill = axis_color,
                        alpha = 0.003
                    )
                }
                if (is.data.frame(cds_hover_df) && nrow(cds_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = cds_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        inherit.aes = FALSE,
                        color = NA,
                        fill = axis_color,
                        alpha = 0.003
                    )
                }
                hover_layers
            } +
            # Exon numbers above CDS blocks
            {
                if (has_exon && "exon_rank" %in% names(exon_df)) {
                    ggplot2::geom_text(
                data = exon_df,
                ggplot2::aes(
                            x     = (xstart_disp + xend_disp) / 2,
                            y     = CDS_YMAX + 0.10,
                            label = exon_rank
                        ),
                        inherit.aes = FALSE,
                        color    = axis_color,
                        size     = 3.0,
                        fontface = "bold"
                    )
                }
            } +
            # Gene name + direction arrow — centered at top of panel
            ggplot2::annotate("text",
                x        = (disp_window_start + disp_window_end) / 2,
                y        = LABEL_Y,
                label    = locus_label,
                hjust    = 0.5,
                vjust    = 1,
                size     = 3.8,
                fontface = "bold",
                color    = axis_color
            ) +
            ggplot2::scale_x_continuous(
                limits = {
                    disp_range <- c(disp_window_start, disp_window_end)
                    disp_pad <- max(diff(disp_range) * 0.03, 1.2)
                    c(disp_range[1], disp_range[2] + disp_pad)
                },
                expand = ggplot2::expansion(mult = c(0, 0))
            ) +
            ggplot2::scale_y_continuous(
                limits = c(0.14, 0.96),
                expand = c(0, 0)
            )

        p
    }

    resolve_reference_display_window <- function(ref_ctx,
                                                 span_mode = "gene",
                                                 default_start = NA_real_,
                                                 default_end = NA_real_,
                                                 pad_fraction = 0.03,
                                                 min_pad_bp = 1L,
                                                 prefer_transcript = TRUE) {
        span_mode_txt <- tolower(trimws(as.character(span_mode %||% "gene")))
        if (!span_mode_txt %in% c("gene", "5kb", "10kb", "25kb", "50kb")) {
            span_mode_txt <- "gene"
        }

        gene_start <- suppressWarnings(as.numeric((ref_ctx %||% list())$gene_start %||% NA_real_))
        gene_end <- suppressWarnings(as.numeric((ref_ctx %||% list())$gene_end %||% NA_real_))
        tx_start <- suppressWarnings(as.numeric((ref_ctx %||% list())$tx_start %||% NA_real_))
        tx_end <- suppressWarnings(as.numeric((ref_ctx %||% list())$tx_end %||% NA_real_))

        normalize_pair <- function(start_val, end_val) {
            if (!is.finite(start_val) || !is.finite(end_val)) {
                return(c(start = NA_real_, end = NA_real_))
            }
            c(start = min(start_val, end_val), end = max(start_val, end_val))
        }

        tx_pair <- normalize_pair(tx_start, tx_end)
        gene_pair <- normalize_pair(gene_start, gene_end)
        body_pair <- if (isTRUE(prefer_transcript) && all(is.finite(tx_pair))) tx_pair else gene_pair
        if (!all(is.finite(body_pair))) {
            body_pair <- if (all(is.finite(gene_pair))) gene_pair else tx_pair
        }

        display_pair <- normalize_pair(default_start, default_end)
        if (all(is.finite(body_pair))) {
            flank_bp <- parse_locus_window_flank_bp(span_mode_txt, default_bp = 0L)
            if (identical(span_mode_txt, "gene")) {
                body_span_bp <- max(as.numeric(body_pair[["end"]] - body_pair[["start"]] + 1), 1)
                pad_bp <- max(as.integer(min_pad_bp %||% 1L), as.integer(round(body_span_bp * as.numeric(pad_fraction %||% 0.03))))
                display_pair <- c(
                    start = max(1L, as.integer(floor(body_pair[["start"]] - pad_bp))),
                    end = as.integer(ceiling(body_pair[["end"]] + pad_bp))
                )
            } else {
                display_pair <- c(
                    start = max(1L, as.integer(floor(body_pair[["start"]] - flank_bp))),
                    end = as.integer(ceiling(body_pair[["end"]] + flank_bp))
                )
            }
        }

        if (!all(is.finite(display_pair)) || display_pair[["end"]] <= display_pair[["start"]]) {
            display_pair <- c(start = 1, end = 100)
        }

        list(
            display_start = as.numeric(display_pair[["start"]]),
            display_end = as.numeric(display_pair[["end"]]),
            body_start = as.numeric(body_pair[["start"]]),
            body_end = as.numeric(body_pair[["end"]]),
            source = if (all(is.finite(body_pair)) && all(is.finite(tx_pair)) &&
                identical(unname(body_pair), unname(tx_pair))) "transcript" else "gene"
        )
    }

    build_multipip_display_segments <- function(df_segments,
                                                min_identity = 70,
                                                min_segment_bp = 25,
                                                ref_feature_df = NULL,
                                                perf_run = NULL,
                                                perf_label = "multipip") {
        out_empty <- list(
            raw_segments = data.frame(stringsAsFactors = FALSE),
            filtered_segments = data.frame(stringsAsFactors = FALSE),
            pruned_segments = data.frame(stringsAsFactors = FALSE)
        )
        step_time <- function(expr, step_txt) {
            t0 <- proc.time()[["elapsed"]]
            value <- expr
            elapsed_ms <- 1000 * (proc.time()[["elapsed"]] - t0)
            if (!is.null(perf_run)) {
                app_perf_mark(
                    perf_run,
                    sprintf("%s_%s_ms=%.1f", as.character(perf_label %||% "multipip"), as.character(step_txt %||% "step"), as.numeric(elapsed_ms)),
                    "ORTHO_MULTIPIP_PIPE"
                )
            }
            value
        }
        if (!is.data.frame(df_segments) || nrow(df_segments) == 0L) {
            return(out_empty)
        }
        seg <- df_segments
        seg$identity_pct <- suppressWarnings(as.numeric(seg$identity_pct))
        seg$segment_bp <- suppressWarnings(as.integer(seg$segment_bp))
        seg$ref_start <- suppressWarnings(as.numeric(seg$ref_start))
        seg$ref_end <- suppressWarnings(as.numeric(seg$ref_end))
        seg$qry_start <- suppressWarnings(as.numeric(seg$qry_start))
        seg$qry_end <- suppressWarnings(as.numeric(seg$qry_end))
        seg$score <- suppressWarnings(as.numeric(seg$score))
        seg <- seg[
            is.finite(seg$identity_pct) &
                is.finite(seg$segment_bp) &
                seg$identity_pct >= as.numeric(min_identity %||% 70) &
                seg$segment_bp >= as.integer(min_segment_bp %||% 25) &
                is.finite(seg$ref_start) &
                is.finite(seg$ref_end) &
                seg$ref_end >= seg$ref_start,
            ,
            drop = FALSE
        ]
        out_empty$raw_segments <- df_segments
        if (nrow(seg) == 0L) {
            return(out_empty)
        }
        seg <- seg[order(-seg$identity_pct, -seg$segment_bp, -ifelse(is.finite(seg$score), seg$score, -Inf), seg$ref_start, seg$qry_start), , drop = FALSE]
        pruned <- step_time(prune_reference_overlaps_per_query(seg), "prune")
        if (!is.data.frame(pruned) || nrow(pruned) == 0L) {
            out_empty$filtered_segments <- seg
            return(out_empty)
        }
        if (is.data.frame(ref_feature_df) && nrow(ref_feature_df) > 0L) {
            pruned <- step_time(classify_reference_underlay_context(pruned, ref_feature_df = ref_feature_df), "underlay")
        } else {
            pruned$underlay_context <- "outside_gene"
        }
        out_empty$filtered_segments <- seg
        out_empty$pruned_segments <- pruned[order(pruned$query_plot_id, pruned$ref_start, -pruned$identity_pct, -pruned$segment_bp), , drop = FALSE]
        out_empty
    }

    summarize_multipip_reference_support <- function(df_segments,
                                                     min_identity = 70,
                                                     min_segment_bp = 25,
                                                     ref_feature_df = NULL) {
        out_empty <- list(
            visible = FALSE,
            covered_bp = 0,
            aligned_bp = 0,
            weighted_identity = NA_real_,
            segment_count = 0L,
            coverage_fraction = 0,
            segments_df = data.frame(stringsAsFactors = FALSE)
        )
        if (!is.data.frame(df_segments) || nrow(df_segments) == 0L) {
            return(out_empty)
        }
        seg_view <- build_multipip_display_segments(
            df_segments = df_segments,
            min_identity = min_identity,
            min_segment_bp = min_segment_bp,
            ref_feature_df = ref_feature_df
        )
        seg_df <- seg_view$pruned_segments
        if (!is.data.frame(seg_df) || nrow(seg_df) == 0L) {
            return(out_empty)
        }
        ref_ranges <- data.frame(
            start = suppressWarnings(as.numeric(pmin(seg_df$ref_start, seg_df$ref_end))),
            end = suppressWarnings(as.numeric(pmax(seg_df$ref_start, seg_df$ref_end))),
            stringsAsFactors = FALSE
        )
        covered_bp <- feature_ranges_union_length(ref_ranges)
        aligned_bp <- sum(suppressWarnings(as.numeric(seg_df$segment_bp)), na.rm = TRUE)
        weighted_identity <- if (is.finite(aligned_bp) && aligned_bp > 0) {
            sum(suppressWarnings(as.numeric(seg_df$identity_pct)) * suppressWarnings(as.numeric(seg_df$segment_bp)), na.rm = TRUE) / aligned_bp
        } else {
            NA_real_
        }
        window_span <- max(1, max(ref_ranges$end, na.rm = TRUE) - min(ref_ranges$start, na.rm = TRUE) + 1)
        list(
            visible = nrow(seg_df) > 0L,
            covered_bp = as.numeric(covered_bp %||% 0),
            aligned_bp = as.numeric(aligned_bp %||% 0),
            weighted_identity = suppressWarnings(as.numeric(weighted_identity)),
            segment_count = as.integer(nrow(seg_df)),
            coverage_fraction = if (is.finite(covered_bp) && is.finite(window_span) && window_span > 0) covered_bp / window_span else 0,
            segments_df = seg_df
        )
    }

    assess_current_lastz_reference <- function(runs,
                                               reference_ctx,
                                               kind = c("blocks", "multipip"),
                                               min_identity = 70,
                                               min_length = 100L) {
        kind <- match.arg(kind)
        runs <- runs %||% list()
        min_identity <- suppressWarnings(as.numeric(min_identity %||% 70))
        if (!is.finite(min_identity)) min_identity <- 70
        min_length <- suppressWarnings(as.integer(min_length %||% if (identical(kind, "multipip")) 25L else 100L))
        if (!is.finite(min_length) || min_length < 1L) min_length <- if (identical(kind, "multipip")) 25L else 100L
        reference_id <- trimws(as.character((reference_ctx %||% list())$plot_id %||% ""))
        total_species <- length(runs)
        if (total_species == 0L) {
            return(list(
                status = "pending",
                basis = "selected_reference",
                reference_id = reference_id,
                summary = "Run local alignments to evaluate the selected reference.",
                detail = "The app evaluates only this reference against the visible organisms; it does not launch an all-against-all candidate sweep.",
                metrics = NULL,
                stamp = ""
            ))
        }
        supports <- lapply(runs, function(run_obj) {
            if (identical(kind, "multipip")) {
                summarize_multipip_reference_support(
                    (run_obj %||% list())$segments,
                    min_identity = min_identity,
                    min_segment_bp = min_length,
                    ref_feature_df = NULL
                )
            } else {
                summarize_pip_reference_support(
                    (run_obj %||% list())$blocks,
                    min_identity = min_identity,
                    min_block_length = min_length
                )
            }
        })
        ok_mask <- vapply(runs, function(run_obj) identical(trimws(as.character((run_obj %||% list())$status %||% "")), "ok"), logical(1))
        supported_mask <- vapply(supports, function(item) isTRUE(item$visible), logical(1))
        covered_bp <- vapply(supports, function(item) as.numeric(item$covered_bp %||% 0), numeric(1))
        aligned_bp <- vapply(supports, function(item) as.numeric(item$aligned_bp %||% 0), numeric(1))
        identities <- vapply(supports, function(item) as.numeric(item$weighted_identity %||% NA_real_), numeric(1))
        fragment_counts <- vapply(supports, function(item) {
            as.integer(if (identical(kind, "multipip")) item$segment_count %||% 0L else item$reduced_block_count %||% 0L)
        }, integer(1))
        window_start <- suppressWarnings(as.numeric((reference_ctx %||% list())$window_start %||% NA_real_))
        window_end <- suppressWarnings(as.numeric((reference_ctx %||% list())$window_end %||% NA_real_))
        window_bp <- window_end - window_start + 1
        coverage_fraction <- if (is.finite(window_bp) && window_bp > 0) covered_bp / window_bp else rep(NA_real_, length(covered_bp))
        weighted_keep <- is.finite(identities) & is.finite(aligned_bp) & aligned_bp > 0
        weighted_identity <- if (any(weighted_keep)) {
            sum(identities[weighted_keep] * aligned_bp[weighted_keep], na.rm = TRUE) / sum(aligned_bp[weighted_keep], na.rm = TRUE)
        } else {
            NA_real_
        }
        mean_coverage <- if (any(is.finite(coverage_fraction))) mean(coverage_fraction[is.finite(coverage_fraction)], na.rm = TRUE) else NA_real_
        metrics <- data.frame(
            reference_id = reference_id,
            supported_species = as.integer(sum(supported_mask, na.rm = TRUE)),
            successful_species = as.integer(sum(ok_mask, na.rm = TRUE)),
            total_species = as.integer(total_species),
            mean_coverage_fraction = as.numeric(mean_coverage),
            weighted_identity = as.numeric(weighted_identity),
            fragment_count = as.integer(sum(fragment_counts, na.rm = TRUE)),
            covered_bp = as.numeric(sum(covered_bp, na.rm = TRUE)),
            aligned_bp = as.numeric(sum(aligned_bp, na.rm = TRUE)),
            stringsAsFactors = FALSE
        )
        metric_label <- if (identical(kind, "multipip")) "visible gap-free segments" else "reduced blocks"
        evaluation_available <- any(ok_mask)
        list(
            status = if (evaluation_available) "evaluated" else "unavailable",
            basis = "selected_reference",
            reference_id = reference_id,
            summary = if (evaluation_available) {
                sprintf(
                    "Selected reference evaluated: conservation support in %d of %d visible organisms.",
                    metrics$supported_species[[1L]],
                    metrics$total_species[[1L]]
                )
            } else {
                "The selected reference could not be evaluated because no local alignment completed successfully."
            },
            detail = sprintf(
                "Successful alignments %d/%d | mean reference-window coverage %s | support-weighted identity %s | %s %d. No candidate-reference sweep was run.",
                metrics$successful_species[[1L]],
                metrics$total_species[[1L]],
                if (is.finite(mean_coverage)) sprintf("%.1f%%", 100 * mean_coverage) else "N/A",
                if (is.finite(weighted_identity)) sprintf("%.1f%%", weighted_identity) else "N/A",
                metric_label,
                metrics$fragment_count[[1L]]
            ),
            metrics = metrics,
            stamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S")
        )
    }

    summary_plot_data_fingerprint <- function(plot_data) {
        if (is.null(plot_data) || !is.data.frame(plot_data) || nrow(plot_data) == 0L) {
            return("plot:none")
        }
        n_rows <- as.integer(nrow(plot_data))
        chr_vals <- trimws(as.character(plot_data$V1 %||% rep("", n_rows)))
        type_vals <- tolower(trimws(as.character(plot_data$V3 %||% rep("", n_rows))))
        starts <- suppressWarnings(as.numeric(plot_data$V4))
        ends <- suppressWarnings(as.numeric(plot_data$V5))
        valid <- is.finite(starts) & is.finite(ends)
        chr_idx <- match(TRUE, nzchar(chr_vals), nomatch = 0L)
        chr_primary <- if (is.finite(chr_idx) && chr_idx > 0L) as.character(chr_vals[[chr_idx]] %||% "") else ""
        start_min <- if (any(valid)) min(starts[valid], na.rm = TRUE) else NA_real_
        end_max <- if (any(valid)) max(ends[valid], na.rm = TRUE) else NA_real_
        type_head <- paste(utils::head(type_vals, 6L), collapse = ",")
        type_tail <- paste(utils::tail(type_vals, 6L), collapse = ",")
        paste(
            "plot",
            n_rows,
            chr_primary,
            if (is.finite(start_min)) format(start_min, scientific = FALSE, trim = TRUE) else "NA",
            if (is.finite(end_max)) format(end_max, scientific = FALSE, trim = TRUE) else "NA",
            type_head,
            type_tail,
            sep = "::"
        )
    }

    summary_organism_fingerprint <- function(org_info) {
        if (is.null(org_info) || !is.list(org_info)) {
            return("org:none")
        }
        org_name <- trimws(as.character(org_info$name %||% ""))
        org_icon <- trimws(as.character(org_info$icon %||% ""))
        paste("org", org_name, org_icon, sep = "::")
    }

    summary_table_df <- function(df) {
        if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
            return(df)
        }
        if ("Organism_Icon" %in% names(df)) {
            return(df[, setdiff(names(df), "Organism_Icon"), drop = FALSE])
        }
        df
    }

    summary_toggle_label <- function(is_expanded = FALSE) {
        if (isTRUE(is_expanded)) "\u25BC Hide Summary Table" else "\u25B6 Show Summary Table"
    }

    analytics_toggle_label <- function(is_expanded = FALSE) {
        tagList(
            if (isTRUE(is_expanded)) "\u25BC" else "\u25B6",
            icon("chart-bar"),
            if (isTRUE(is_expanded)) " Hide Analytics" else " Show Analytics"
        )
    }

    deletion_confirmation_enabled <- function() {
        isTRUE(input$confirm_delete_actions %||% TRUE)
    }

    build_app_confirmation_modal <- function(
        title,
        subtitle = NULL,
        tone = c("info", "warning", "danger", "success"),
        title_icon = NULL,
        body = NULL,
        confirm_input_id,
        confirm_label,
        confirm_icon = "check"
    ) {
        tone <- match.arg(tone)
        safe_subtitle <- trimws(as.character(subtitle %||% ""))
        safe_title_icon <- trimws(as.character(title_icon %||% ""))
        if (!nzchar(safe_title_icon)) {
            safe_title_icon <- switch(
                tone,
                danger = "trash",
                warning = "exclamation-triangle",
                success = "check-circle",
                "info-circle"
            )
        }

        cancel_btn <- htmltools::tagAppendAttributes(
            modalButton("Cancel"),
            class = "app-confirmation-btn app-confirmation-btn-cancel"
        )

        confirm_btn <- actionButton(
            inputId = confirm_input_id,
            label = confirm_label,
            icon = icon(confirm_icon),
            class = paste(
                "btn app-confirmation-btn app-confirmation-btn-confirm",
                paste0("app-confirmation-btn-confirm--", tone)
            )
        )

        htmltools::tagAppendAttributes(
            modalDialog(
                title = tags$div(
                    class = "app-confirmation-modal-title",
                    tags$span(
                        class = "app-confirmation-modal-title-icon",
                        icon(safe_title_icon)
                    ),
                    tags$div(
                        class = "app-confirmation-modal-title-copy",
                        tags$div(class = "app-confirmation-modal-title-primary", title),
                        if (nzchar(safe_subtitle)) {
                            tags$div(class = "app-confirmation-modal-title-secondary", safe_subtitle)
                        } else {
                            NULL
                        }
                    )
                ),
                div(class = "app-confirmation-modal-body-inner", body),
                easyClose = TRUE,
                footer = tagList(cancel_btn, confirm_btn)
            ),
            class = paste("app-confirmation-modal", paste0("app-confirmation-modal--", tone))
        )
    }

    build_partial_gene_suggestions_modal <- function(query, suggestions, mode = c("homologous", "orthologous")) {
        mode <- match.arg(mode)
        query_txt <- trimws(as.character(query %||% ""))
        suggestions <- if (is.data.frame(suggestions)) suggestions else data.frame()
        if (exists("normalize_partial_gene_suggestions_df", mode = "function")) {
            suggestions <- normalize_partial_gene_suggestions_df(
                suggestions,
                source_labels = "source_labels" %in% names(suggestions),
                source_label_preview = "source_label_preview" %in% names(suggestions)
            )
        }
        if (exists("collapse_partial_gene_suggestions_by_locus", mode = "function")) {
            suggestions <- collapse_partial_gene_suggestions_by_locus(suggestions, query = query_txt)
        }
        suggestions <- suggestions[!is.na(suggestions$gene_name) & nzchar(trimws(as.character(suggestions$gene_name))), , drop = FALSE]
        query_key <- normalize_partial_gene_query(query_txt)
        suggestion_keys <- normalize_partial_gene_query(suggestions$gene_name)
        exact_flags <- suggestion_keys == query_key | tolower(as.character(suggestions$match_type %||% "")) == "exact"
        exact_flags[is.na(exact_flags)] <- FALSE
        if (nrow(suggestions) > 0L) {
            suggestions <- suggestions[order(!exact_flags, -suppressWarnings(as.numeric(suggestions$score %||% 0)), tolower(as.character(suggestions$gene_name))), , drop = FALSE]
            suggestion_keys <- normalize_partial_gene_query(suggestions$gene_name)
            exact_flags <- suggestion_keys == query_key | tolower(as.character(suggestions$match_type %||% "")) == "exact"
            exact_flags[is.na(exact_flags)] <- FALSE
            rownames(suggestions) <- NULL
        }
        total_suggestions <- nrow(suggestions)
        exact_count <- sum(exact_flags)
        evidence_help_text <- paste(
            "Confidence describes how reliably the displayed term maps to this annotation locus, not the strength of biological or experimental evidence.",
            "HIGH: a stable gene, transcript, or protein identifier.",
            "MEDIUM: an annotation name, alias, synonym, locus tag, or database cross-reference.",
            "LOW: a descriptive or less-specific term; confirm the locus before plotting."
        )
        evidence_label <- function(focusable = TRUE) {
            tagList(
                "Evidence",
                tags$span(
                    class = "gene-match-help",
                    tabindex = if (isTRUE(focusable)) "0" else NULL,
                    `aria-label` = "Explain evidence confidence",
                    `data-evidence-help` = "true",
                    icon("circle-question")
                )
            )
        }

        suggestion_items <- lapply(seq_len(nrow(suggestions)), function(i) {
            row <- suggestions[i, , drop = FALSE]
            gene <- trimws(as.character(row$gene_name[1] %||% ""))
            local_gene_id <- trimws(as.character(row$local_gene_id[1] %||% ""))
            local_symbol <- trimws(as.character(row$local_symbol[1] %||% ""))
            source_db <- trimws(as.character(row$source_db[1] %||% ""))
            term_type <- tolower(trimws(as.character(row$term_type[1] %||% "")))
            confidence <- toupper(trimws(as.character(row$confidence[1] %||% "")))
            match_role <- trimws(as.character(row$match_role[1] %||% ""))
            alias_names <- trimws(as.character(row$alias_names[1] %||% ""))
            alias_values <- if (nzchar(alias_names)) trimws(strsplit(alias_names, " | ", fixed = TRUE)[[1L]]) else character(0)
            alias_values <- unique(alias_values[nzchar(alias_values)])
            alias_preview <- if (length(alias_values) <= 8L) {
                paste(alias_values, collapse = ", ")
            } else {
                paste0(paste(alias_values[seq_len(8L)], collapse = ", "), sprintf(" +%d more", length(alias_values) - 8L))
            }
            requires_confirmation <- isTRUE(row$requires_confirmation[1] %||% FALSE)
            is_exact <- isTRUE(exact_flags[[i]])
            is_local_alias <- nzchar(source_db) && toupper(source_db) == "GFF"
            plot_gene <- if (identical(mode, "homologous") && nzchar(local_gene_id)) local_gene_id else gene
            payload <- list(
                gene = gene,
                plot_gene = plot_gene,
                local_gene_id = local_gene_id,
                local_symbol = local_symbol,
                term_type = term_type,
                source_db = source_db,
                confidence = confidence,
                match_role = match_role,
                aliases = alias_values,
                requires_confirmation = requires_confirmation,
                local_alias = isTRUE(is_local_alias)
            )
            payload_json <- tryCatch(
                as.character(jsonlite::toJSON(payload, auto_unbox = TRUE, null = "null", na = "null")),
                error = function(e) "{}"
            )
            source_count <- suppressWarnings(as.integer(row$source_count[1] %||% 1L))
            if (!is.finite(source_count) || is.na(source_count) || source_count < 1L) source_count <- 1L
            source_label <- trimws(as.character(row$file_label[1] %||% ""))
            source_preview <- trimws(as.character(row$source_label_preview[1] %||% row$source_labels[1] %||% source_label))
            organism_value <- if (identical(mode, "orthologous")) {
                paste(c(
                    sprintf("%d organism%s", source_count, ifelse(source_count == 1L, "", "s")),
                    if (nzchar(source_preview)) source_preview else NULL
                ), collapse = " · ")
            } else {
                source_label
            }
            evidence_parts <- c(source_db, term_type, confidence)
            evidence_parts <- evidence_parts[nzchar(evidence_parts)]
            evidence_value <- paste(evidence_parts, collapse = " · ")
            match_label <- if (is_exact) {
                "Exact match"
            } else if (identical(as.character(row$match_type[1] %||% ""), "prefix")) {
                "Starts with query"
            } else {
                "Contains query"
            }
            detail_row <- function(label, value, value_class = "") {
                value_txt <- trimws(as.character(value %||% ""))
                if (!nzchar(value_txt)) return(NULL)
                tags$span(
                    class = "gene-match-detail-row",
                    tags$span(class = "gene-match-detail-label", label),
                    tags$span(class = paste("gene-match-detail-value", value_class), value_txt)
                )
            }
            suggestion_copy <- tags$span(
                class = "partial-gene-suggestion-copy",
                tags$span(
                    class = "gene-match-card-header",
                    tags$span(class = "partial-gene-suggestion-name", gene),
                    if (is_exact) tags$span(class = "gene-match-exact-badge", "Exact match") else NULL
                ),
                tags$span(
                    class = "gene-match-detail-list",
                    if (identical(mode, "orthologous")) detail_row("Name seen in", organism_value, "gene-match-detail-value--organism") else NULL,
                    if (identical(mode, "homologous")) detail_row("Locus", local_gene_id, "gene-match-detail-value--mono") else NULL,
                    if (nzchar(local_symbol) && !identical(local_symbol, gene)) detail_row("Symbol", local_symbol) else NULL,
                    detail_row("Aliases", alias_preview),
                    detail_row(evidence_label(focusable = identical(mode, "homologous")), evidence_value)
                ),
                tags$span(
                    class = "gene-match-card-footer",
                    tags$span(
                        class = paste("gene-match-type-badge", if (is_exact) "gene-match-type-badge--exact" else ""),
                        match_label
                    ),
                    if (isTRUE(requires_confirmation)) {
                        tags$span(class = "gene-match-confirmation-badge", "Confirmation required")
                    } else {
                        NULL
                    }
                )
            )
            if (identical(mode, "homologous")) {
                tags$label(
                    class = paste("partial-gene-suggestion-option", if (is_exact) "partial-gene-suggestion-item--exact" else ""),
                    `data-gene-match-item` = "true",
                    `data-search-text` = paste(gene, alias_names, local_gene_id, local_symbol, source_label, source_preview),
                    `data-exact-match` = if (is_exact) "true" else "false",
                    tags$input(
                        type = "checkbox",
                        class = "partial-gene-suggestion-check",
                        value = plot_gene,
                        `data-gene` = gene,
                        `data-resolution` = payload_json
                    ),
                    suggestion_copy
                )
            } else {
                tags$button(
                    type = "button",
                    class = paste("partial-gene-suggestion-btn", if (is_exact) "partial-gene-suggestion-item--exact" else ""),
                    `data-mode` = mode,
                    `data-gene` = gene,
                    `data-resolution` = payload_json,
                    `data-gene-match-item` = "true",
                    `data-search-text` = paste(gene, alias_names, local_gene_id, local_symbol, source_label, source_preview),
                    `data-exact-match` = if (is_exact) "true" else "false",
                    suggestion_copy
                )
            }
        })
        external_alias_btn <- tags$button(
            id = "partial-gene-suggestion-search-external",
            type = "button",
            class = "btn app-confirmation-btn app-confirmation-btn-confirm app-confirmation-btn-confirm--info",
            `data-mode` = mode,
            `data-query` = query_txt,
            icon("database"),
            " Search external aliases"
        )
        footer <- if (identical(mode, "homologous")) {
            tagList(
                htmltools::tagAppendAttributes(
                    modalButton("Close"),
                    class = "app-confirmation-btn app-confirmation-btn-cancel"
                ),
                external_alias_btn,
                tags$button(
                    id = "partial-gene-suggestion-search-selected",
                    type = "button",
                    class = "btn app-confirmation-btn app-confirmation-btn-confirm app-confirmation-btn-confirm--info",
                    disabled = "disabled",
                    icon("search"),
                    " Plot selected"
                )
            )
        } else {
            tagList(
                htmltools::tagAppendAttributes(
                    modalButton("Close"),
                    class = "app-confirmation-btn app-confirmation-btn-cancel"
                ),
                external_alias_btn
            )
        }

        htmltools::tagAppendAttributes(
            modalDialog(
                title = tags$div(
                    class = "app-confirmation-modal-title",
                    tags$span(class = "app-confirmation-modal-title-icon", icon("search")),
                    tags$div(
                        class = "app-confirmation-modal-title-copy",
                        tags$div(class = "app-confirmation-modal-title-primary", "Possible Gene Matches"),
                        tags$div(class = "app-confirmation-modal-title-secondary", if (identical(mode, "orthologous")) "Cross-Species Gene Search" else "Multi-Gene Search")
                    )
                ),
                div(
                    class = "app-confirmation-modal-body-inner partial-gene-suggestion-modal",
                    tags$p(
                        class = paste("app-confirmation-modal-text gene-match-intro", if (exact_count > 0L) "gene-match-intro--exact" else ""),
                        if (exact_count > 0L) {
                            "An exact match was found for "
                        } else if (identical(mode, "orthologous")) {
                            "The query needs a cross-species-compatible gene choice for "
                        } else {
                            "No exact gene match was found for "
                        },
                        tags$strong(paste0(query_txt, if (exact_count > 0L && total_suggestions > exact_count) "," else ".")),
                        if (exact_count > 0L) {
                            if (total_suggestions > exact_count) {
                                sprintf(" together with %d additional gene%s containing that term. The exact match is highlighted; choose any result below.", total_suggestions - exact_count, ifelse(total_suggestions - exact_count == 1L, "", "s"))
                            } else {
                                " The exact match is highlighted below."
                            }
                        } else if (identical(mode, "orthologous")) {
                            " Similar local names or aliases were found in the selected annotation data:"
                        } else {
                            " Perhaps you meant one of these similar gene names found in the selected annotation data:"
                        }
                    ),
                    div(
                        class = "gene-match-browser",
                        `data-page-size` = "24",
                        `data-result-label` = "unique gene",
                        tags$div(
                            class = "gene-match-browser-toolbar",
                            tags$label(
                                class = "gene-match-filter-wrap",
                                tags$span(class = "sr-only", "Filter all gene suggestions"),
                                icon("filter"),
                                tags$input(
                                    type = "search",
                                    class = "gene-match-filter-input",
                                    placeholder = "Filter all suggestions...",
                                    autocomplete = "off"
                                )
                            ),
                            tags$span(
                                class = "gene-match-result-count",
                                `aria-live` = "polite",
                                sprintf("%d unique gene%s", total_suggestions, ifelse(total_suggestions == 1L, "", "s"))
                            )
                        ),
                    if (identical(mode, "homologous")) {
                        div(
                            class = "gene-match-selection-toolbar",
                            tags$button(
                                id = "partial-gene-suggestion-select-all",
                                type = "button",
                                class = "gene-match-select-all",
                                `data-check-selector` = ".partial-gene-suggestion-check",
                                `data-run-selector` = "#partial-gene-suggestion-search-selected",
                                `aria-pressed` = "false",
                                icon("check-double"),
                                tags$span(class = "gene-match-select-all-label", "Select all")
                            ),
                            tags$span(
                                class = "gene-match-selection-count",
                                `data-check-selector` = ".partial-gene-suggestion-check",
                                `aria-live` = "polite",
                                "0 selected"
                            )
                        )
                    } else {
                        NULL
                    },
                    div(
                        class = paste(
                            "partial-gene-suggestion-list",
                            if (identical(mode, "homologous")) "partial-gene-suggestion-list--multi" else "partial-gene-suggestion-list--single"
                        ),
                        suggestion_items
                    ),
                    tags$div(
                        class = "gene-match-pagination",
                        tags$button(type = "button", class = "gene-match-page-btn gene-match-page-prev", icon("chevron-left"), " Previous"),
                        tags$span(class = "gene-match-page-status", `aria-live` = "polite"),
                        tags$button(type = "button", class = "gene-match-page-btn gene-match-page-next", "Next ", icon("chevron-right"))
                    ),
                    ),
                    tags$p(
                        class = "partial-gene-suggestion-footnote",
                        if (identical(mode, "homologous")) {
                            "Select one or more suggested genes to plot, or search external databases for alternate nomenclature of the original query."
                        } else if (isTRUE(cross_species_requires_verified_orthology())) {
                            "Choose a candidate term. For Cross-Species searches, matching names or aliases only identify candidate loci; CGeV will plot only loci supported by explicit one-to-one orthology evidence."
                        } else {
                            "Choose a candidate term. Cross-Species resolves that term independently in each organism's local annotation; matching names or aliases do not by themselves prove one-to-one orthology."
                        }
                    )
                ),
                easyClose = TRUE,
                footer = footer
            ),
            class = "app-confirmation-modal app-confirmation-modal--info partial-gene-suggestion-dialog"
        )
    }

    build_alias_index_ambiguity_modal <- function(query, matches, mode = c("homologous", "orthologous")) {
        mode <- match.arg(mode)
        safe_text_one <- function(x, fallback = "") {
            vals <- as.character(x %||% fallback)
            vals <- vals[!is.na(vals)]
            if (length(vals) == 0L) {
                return(as.character(fallback %||% ""))
            }
            out <- trimws(vals[[1L]])
            if (!nzchar(out)) as.character(fallback %||% "") else out
        }
        query_txt <- safe_text_one(query)
        matches <- if (is.data.frame(matches)) matches else data.frame()
        if (nrow(matches) == 0L) {
            return(NULL)
        }
        evidence_help_text <- paste(
            "Confidence describes how reliably the displayed term maps to this annotation locus, not the strength of biological or experimental evidence.",
            "HIGH: a stable gene, transcript, or protein identifier.",
            "MEDIUM: an annotation name, alias, synonym, locus tag, or database cross-reference.",
            "LOW: a descriptive or less-specific term; confirm the locus before plotting."
        )
        evidence_label <- function(focusable = TRUE) {
            tagList(
                "Evidence",
                tags$span(
                    class = "gene-match-help",
                    tabindex = if (isTRUE(focusable)) "0" else NULL,
                    `aria-label` = "Explain evidence confidence",
                    `data-evidence-help` = "true",
                    icon("circle-question")
                )
            )
        }
        highlight_query_text <- function(text, query) {
            txt <- safe_text_one(text)
            if (!nzchar(txt)) return(HTML(""))
            escaped <- htmltools::htmlEscape(txt)
            q <- safe_text_one(query)
            if (!nzchar(q)) return(HTML(escaped))
            pattern <- paste0("(?i)(", gsub("([][{}()+*^$|\\\\?.])", "\\\\\\1", q, perl = TRUE), ")")
            highlighted <- gsub(pattern, "<strong>\\1</strong>", escaped, perl = TRUE)
            HTML(highlighted)
        }
        abbreviate_gene_description <- function(desc, max_chars = 230L) {
            txt <- trimws(gsub("[[:space:]]+", " ", safe_text_one(desc)))
            if (!nzchar(txt)) return(list(short = "", full = "", truncated = FALSE))
            max_chars <- suppressWarnings(as.integer(max_chars %||% 230L))
            if (!is.finite(max_chars) || is.na(max_chars) || max_chars < 80L) max_chars <- 230L
            if (nchar(txt, type = "chars") <= max_chars) {
                return(list(short = txt, full = txt, truncated = FALSE))
            }
            sentence_end <- gregexpr("(?<=[.!?])\\s+", txt, perl = TRUE)[[1]]
            cut_at <- NA_integer_
            if (!identical(sentence_end, -1L)) {
                ends <- sentence_end + attr(sentence_end, "match.length") - 1L
                candidates <- ends[ends >= 120L & ends <= max_chars]
                if (length(candidates) > 0L) cut_at <- max(candidates)
            }
            if (!is.finite(cut_at) || is.na(cut_at)) {
                cut_at <- max_chars
                space_before <- gregexpr("\\s+", substr(txt, 1L, max_chars), perl = TRUE)[[1]]
                if (!identical(space_before, -1L) && max(space_before) >= 120L) cut_at <- max(space_before)
            }
            short <- trimws(substr(txt, 1L, cut_at))
            list(short = paste0(short, "..."), full = txt, truncated = TRUE)
        }
        max_rows <- nrow(matches)
        match_items <- lapply(seq_len(max_rows), function(i) {
            row <- matches[i, , drop = FALSE]
            gene_id <- safe_text_one(row$local_gene_id[1] %||% row$local_feature_id[1] %||% "")
            gene_name <- safe_text_one(row$local_symbol[1] %||% row$query_term_original[1] %||% gene_id)
            chr <- safe_text_one(row$chromosome[1] %||% "")
            start_pos <- suppressWarnings(as.numeric(row$start[1] %||% NA_real_))
            end_pos <- suppressWarnings(as.numeric(row$end[1] %||% NA_real_))
            strand <- safe_text_one(row$strand[1] %||% "")
            source_db <- safe_text_one(row$source_db[1] %||% "alias index", fallback = "alias index")
            term_type <- safe_text_one(row$term_type[1] %||% "alias", fallback = "alias")
            confidence <- safe_text_one(row$confidence[1] %||% "")
            organism_name <- safe_text_one(row$organism_name[1] %||% "")
            input_match <- safe_text_one(row$input_match[1] %||% row$query_term_original[1] %||% "")
            match_role <- safe_text_one(row$match_role[1] %||% "")
            role_label <- switch(
                match_role,
                stable_id = "stable ID",
                official_symbol = "official symbol",
                official_name = "official name",
                synonym = "synonym",
                "alias"
            )
            recommended <- tolower(trimws(as.character(row$recommended[1] %||% "FALSE"))) %in% c("true", "1", "yes")
            desc <- safe_text_one(row$description[1] %||% "")
            desc_preview <- abbreviate_gene_description(desc)
            coord <- paste(c(
                if (nzchar(chr)) chr else NULL,
                if (is.finite(start_pos) && is.finite(end_pos)) {
                    sprintf("%s-%s", format(round(start_pos), big.mark = ","), format(round(end_pos), big.mark = ","))
                } else {
                    NULL
                },
                if (nzchar(strand)) strand else NULL
            ), collapse = " : ")
            payload <- list(
                mode = mode,
                gene = if (nzchar(gene_id)) gene_id else gene_name,
                query = query_txt,
                local_gene_id = gene_id,
                organism_id = safe_text_one(row$organism_id[1] %||% ""),
                organism_name = organism_name
            )
            payload_js <- tryCatch(
                as.character(jsonlite::toJSON(payload, auto_unbox = TRUE, null = "null", na = "null")),
                error = function(e) "{}"
            )
            is_exact_alias <- tolower(trimws(input_match)) == tolower(trimws(query_txt))
            alias_detail_row <- function(label, value, highlight = FALSE, value_class = "") {
                value_txt <- safe_text_one(value)
                if (!nzchar(value_txt)) return(NULL)
                tags$span(
                    class = "gene-match-detail-row",
                    tags$span(class = "gene-match-detail-label", label),
                    tags$span(
                        class = paste("gene-match-detail-value", value_class),
                        if (isTRUE(highlight)) highlight_query_text(value_txt, query_txt) else value_txt
                    )
                )
            }
            evidence_parts <- c(source_db, term_type, confidence)
            evidence_parts <- evidence_parts[nzchar(evidence_parts)]
            match_copy <- tags$span(
                class = "alias-index-match-copy",
                tags$span(
                    class = "gene-match-card-header",
                    tags$span(class = "partial-gene-suggestion-name", gene_name),
                    tags$span(
                        class = "gene-match-card-badges",
                        if (isTRUE(recommended)) tags$span(class = "gene-match-recommended-badge", "Recommended") else NULL,
                        if (isTRUE(is_exact_alias)) tags$span(class = "gene-match-exact-badge", "Exact match") else NULL
                    )
                ),
                tags$span(
                    class = "gene-match-detail-list",
                    alias_detail_row("Matched term", input_match, highlight = TRUE),
                    alias_detail_row("Locus", gene_id, value_class = "gene-match-detail-value--mono"),
                    if (identical(mode, "orthologous")) alias_detail_row("Organism", organism_name, value_class = "gene-match-detail-value--organism") else NULL,
                    alias_detail_row("Role", role_label),
                    alias_detail_row("Location", coord, value_class = "gene-match-detail-value--mono"),
                    alias_detail_row(evidence_label(focusable = identical(mode, "homologous")), paste(evidence_parts, collapse = " · "))
                ),
                if (nzchar(desc_preview$short)) {
                    tags$span(
                        class = "alias-index-description-preview",
                        highlight_query_text(desc_preview$short, query_txt)
                    )
                } else {
                    NULL
                }
            )
            tags$div(
                class = paste(
                    "alias-index-match-card",
                    if (isTRUE(recommended)) "alias-index-match-card--recommended" else ""
                ),
                `data-gene-match-item` = "true",
                `data-search-text` = paste(gene_name, gene_id, organism_name, input_match, match_role, desc, source_db),
                `data-exact-match` = if (isTRUE(is_exact_alias)) "true" else "false",
                if (identical(mode, "homologous")) {
                    tags$label(
                        class = "alias-index-match-select",
                        tags$input(
                            type = "checkbox",
                            class = "alias-index-match-check",
                            value = payload$gene
                        ),
                        match_copy
                    )
                } else {
                    tags$button(
                        type = "button",
                        class = paste(
                            "partial-gene-suggestion-btn",
                            if (isTRUE(recommended)) "partial-gene-suggestion-btn--recommended" else ""
                        ),
                        onclick = sprintf("Shiny.setInputValue('alias_index_match_pick', %s, {priority:'event'});", payload_js),
                        match_copy
                    )
                },
                if (isTRUE(desc_preview$truncated)) {
                    tags$details(
                        class = "alias-index-description-details",
                        tags$summary("Show full description"),
                        tags$div(
                            class = "alias-index-description-full",
                            highlight_query_text(desc_preview$full, query_txt)
                        )
                    )
                } else {
                    NULL
                }
            )
        })
        htmltools::tagAppendAttributes(
            modalDialog(
                title = tags$div(
                    class = "app-confirmation-modal-title",
                    tags$span(class = "app-confirmation-modal-title-icon", icon("sitemap")),
                    tags$div(
                        class = "app-confirmation-modal-title-copy",
                        tags$div(class = "app-confirmation-modal-title-primary", "Several Alias Matches"),
                        tags$div(class = "app-confirmation-modal-title-secondary", if (identical(mode, "orthologous")) "Cross-Species Gene Search" else "Multi-Gene Search")
                    )
                ),
                div(
                    class = "app-confirmation-modal-body-inner partial-gene-suggestion-modal",
                    tags$p(
                        class = "app-confirmation-modal-text gene-match-intro",
                        "The local alias index found several genes for ",
                        tags$strong(paste0(query_txt, ".")),
                        if (identical(mode, "homologous")) {
                            " Select one or more genes CGeV should plot."
                        } else if (isTRUE(cross_species_requires_verified_orthology())) {
                            " Select the reference locus CGeV should evaluate for orthology."
                        } else {
                            " Select the local locus CGeV should use for this organism."
                        }
                    ),
                    div(
                        class = "gene-match-browser",
                        `data-page-size` = "24",
                        `data-result-label` = "gene",
                        tags$div(
                            class = "gene-match-browser-toolbar",
                            tags$label(
                                class = "gene-match-filter-wrap",
                                tags$span(class = "sr-only", "Filter all alias matches"),
                                icon("filter"),
                                tags$input(
                                    type = "search",
                                    class = "gene-match-filter-input",
                                    placeholder = "Filter all matches...",
                                    autocomplete = "off"
                                )
                            ),
                            tags$span(
                                class = "gene-match-result-count",
                                `aria-live` = "polite",
                                sprintf("%d total match%s", nrow(matches), ifelse(nrow(matches) == 1L, "", "es"))
                            )
                        ),
                    if (identical(mode, "homologous")) {
                        div(
                            class = "gene-match-selection-toolbar",
                            tags$button(
                                id = "alias-index-match-select-all",
                                type = "button",
                                class = "gene-match-select-all",
                                `data-check-selector` = ".alias-index-match-check",
                                `data-run-selector` = "#alias-index-match-plot-selected",
                                `aria-pressed` = "false",
                                icon("check-double"),
