    safe_girafe <- function(..., transport_label = NULL) {
        args <- list(...)
        widget <- withCallingHandlers(
            do.call(ggiraph::girafe, args),
            warning = function(w) {
                msg <- conditionMessage(w)
                if (grepl("Failed setting attribute 'title'", msg, fixed = TRUE) ||
                    grepl("Failed setting attribute 'data-id'", msg, fixed = TRUE) ||
                    grepl("set_attr(name = attrName", msg, fixed = TRUE)) {
                    invokeRestart("muffleWarning")
                }
            }
        )
        if (exists("compact_girafe_widget", mode = "function")) {
            label_txt <- transport_label
            if (is.null(label_txt) || !nzchar(trimws(as.character(label_txt %||% "")))) {
                ggobj <- args$ggobj
                label_txt <- tryCatch(as.character((ggobj$labels %||% list())$title %||% "girafe"), error = function(e) "girafe")
            }
            widget <- compact_girafe_widget(widget, label = label_txt)
        }
        widget
    }
    warm_gene_plot_renderer_once <- function() {
        if (isTRUE(genePlotRendererWarmed()) ||
            !isTRUE(app_env_flag("APP_GENE_PLOT_RENDERER_PREWARM", TRUE)) ||
            isTRUE(secondary_work_should_yield())) {
            return(invisible(FALSE))
        }
        genePlotRendererWarmed(TRUE)
        warm_t0 <- app_perf_now()
        tryCatch({
            warm_plot <- ggplot2::ggplot(
                data.frame(x = 0, y = 0),
                ggplot2::aes(x = x, y = y)
            ) +
                ggplot2::geom_blank() +
                ggplot2::theme_void()
            invisible(safe_girafe(
                ggobj = warm_plot,
                width_svg = 1,
                height_svg = 1,
                transport_label = "gene_plot_renderer_prewarm",
                options = list(
                    ggiraph::opts_selection(type = "none"),
                    ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
                    ggiraph::opts_sizing(rescale = FALSE)
                )
            ))
            app_perf_mark_ms(NULL, "renderer_prewarm_ms", app_perf_elapsed_ms(warm_t0), "PLOT_WARM")
            invisible(TRUE)
        }, error = function(e) {
            genePlotRendererWarmed(FALSE)
            app_perf_mark(NULL, sprintf("renderer_prewarm_error=%s", as.character(e$message %||% "unknown")), "PLOT_WARM")
            invisible(FALSE)
        })
    }
    if (requireNamespace("later", quietly = TRUE) &&
        isTRUE(app_env_flag("APP_GENE_PLOT_RENDERER_PREWARM", TRUE))) {
        # Keep the synchronous ggiraph warm-up out of the first response.  A
        # cold call takes a few hundred milliseconds, so scheduling it before
        # the initial flush competes directly with the browser's first paint.
        # The same warm-up still runs shortly afterwards and remains optional.
        renderer_prewarm_delay_ms <- app_env_int(
            "APP_GENE_PLOT_RENDERER_PREWARM_DELAY_MS",
            1000L,
            min_value = 0L,
            max_value = 30000L
        )
        run_renderer_prewarm <- NULL
        run_renderer_prewarm <- function() {
            session_closed <- tryCatch(
                is.function(session$isClosed) && isTRUE(session$isClosed()),
                error = function(e) FALSE
            )
            if (isTRUE(session_closed)) {
                return(invisible(FALSE))
            }
            if (isTRUE(secondary_work_should_yield())) {
                app_perf_mark(NULL, "renderer_prewarm_yield=user_search_active", "PLOT_WARM")
                later::later(run_renderer_prewarm, delay = secondary_work_retry_delay_sec)
                return(invisible(FALSE))
            }
            tryCatch(warm_gene_plot_renderer_once(), error = function(e) NULL)
        }
        session$onFlushed(function() {
            later::later(
                run_renderer_prewarm,
                delay = max(renderer_prewarm_delay_ms / 1000, secondary_work_initial_delay_sec)
            )
        }, once = TRUE)
    }
    sanitize_girafe_tooltip_text <- function(x) {
        txt <- as.character(x %||% "")
        txt[is.na(txt)] <- ""
        txt <- enc2utf8(txt)
        # Strip control characters that can make SVG title/data-tooltip
        # attribute assignment fail silently in ggiraph 0.9.2.
        txt <- gsub("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F\\x7F]", " ", txt, perl = TRUE)
        txt <- gsub("[[:space:]]+", " ", txt, perl = TRUE)
        trimws(txt)
    }
    sanitize_girafe_data_id <- function(x, fallback_prefix = "girafe") {
        txt <- sanitize_girafe_tooltip_text(x)
        txt <- gsub("[^A-Za-z0-9_.:-]+", "_", txt, perl = TRUE)
        txt <- gsub("_{2,}", "_", txt, perl = TRUE)
        txt <- gsub("^_+|_+$", "", txt, perl = TRUE)
        blank_idx <- !nzchar(txt)
        if (any(blank_idx)) {
            txt[blank_idx] <- paste0(fallback_prefix, "_", seq_len(sum(blank_idx)))
        }
        txt
    }
    next_girafe_uid <- local({
        counter <- 0L
        function() {
            counter <<- counter + 1L
            ts_ms <- suppressWarnings(as.integer(round(as.numeric(Sys.time()) * 1000)))
            if (!is.finite(ts_ms)) {
                ts_ms <- as.integer(counter)
            }
            paste0("svg_", ts_ms, "_", counter)
        }
    })
    refresh_girafe_widget_uid <- function(widget_obj) {
        if (is.null(widget_obj)) return(widget_obj)
        if (!inherits(widget_obj, "girafe")) return(widget_obj)
        out <- widget_obj
        if (is.list(out$x)) {
            old_uid <- trimws(as.character(out$x$uid %||% ""))
            new_uid <- next_girafe_uid()
            if (nzchar(old_uid) && nzchar(new_uid) && !identical(old_uid, new_uid)) {
                if (is.character(out$x$html) && length(out$x$html) > 0L) {
                    out$x$html <- gsub(old_uid, new_uid, out$x$html, fixed = TRUE)
                }
                if (is.character(out$x$js) && length(out$x$js) > 0L) {
                    out$x$js <- gsub(old_uid, new_uid, out$x$js, fixed = TRUE)
                }
            }
            out$x$uid <- new_uid
        }
        out
    }
