    as_feature_ranges <- function(df_rows) {
        if (is.null(df_rows) || nrow(df_rows) == 0) {
            return(data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE))
        }
        s <- suppressWarnings(as.numeric(df_rows$V4))
        e <- suppressWarnings(as.numeric(df_rows$V5))
        keep <- is.finite(s) & is.finite(e)
        if (!any(keep)) {
            return(data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE))
        }
        out <- data.frame(
            start = pmin(s[keep], e[keep]),
            end = pmax(s[keep], e[keep]),
            stringsAsFactors = FALSE
        )
        out <- out[out$end >= out$start, , drop = FALSE]
        if (nrow(out) == 0) {
            return(data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE))
        }
        out
    }

    unique_feature_ranges <- function(ranges_df) {
        if (is.null(ranges_df) || nrow(ranges_df) == 0) {
            return(data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE))
        }
        out <- ranges_df[, c("start", "end"), drop = FALSE]
        out$start <- suppressWarnings(as.numeric(out$start))
        out$end <- suppressWarnings(as.numeric(out$end))
        out <- out[is.finite(out$start) & is.finite(out$end), , drop = FALSE]
        if (nrow(out) == 0) {
            return(data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE))
        }
        start_vals <- pmin(out$start, out$end)
        end_vals <- pmax(out$start, out$end)
        out$start <- start_vals
        out$end <- end_vals
        out <- unique(out)
        out[order(out$start, out$end), , drop = FALSE]
    }

    merge_feature_ranges <- function(ranges_df) {
        out <- unique_feature_ranges(ranges_df)
        if (nrow(out) <= 1) {
            return(out)
        }
        merged <- data.frame(start = out$start[1], end = out$end[1], stringsAsFactors = FALSE)
        if (nrow(out) > 1) {
            for (i in 2:nrow(out)) {
                if (out$start[i] <= merged$end[nrow(merged)] + 1) {
                    merged$end[nrow(merged)] <- max(merged$end[nrow(merged)], out$end[i])
                } else {
                    merged <- rbind(merged, data.frame(start = out$start[i], end = out$end[i], stringsAsFactors = FALSE))
                }
            }
        }
        merged
    }

    feature_ranges_union_length <- function(ranges_df) {
        merged <- merge_feature_ranges(ranges_df)
        if (is.null(merged) || nrow(merged) == 0) {
            return(0)
        }
        sum(as.numeric(merged$end) - as.numeric(merged$start) + 1)
    }

    feature_ranges_union_length_normalized <- function(ranges_df) {
        if (is.null(ranges_df) || nrow(ranges_df) == 0L) {
            return(0)
        }
        starts <- as.numeric(ranges_df$start)
        ends <- as.numeric(ranges_df$end)
        keep <- is.finite(starts) & is.finite(ends)
        starts <- starts[keep]
        ends <- ends[keep]
        if (length(starts) == 0L) return(0)
        ord <- order(starts, ends)
        starts <- starts[ord]
        ends <- ends[ord]
        total <- 0
        current_start <- starts[[1L]]
        current_end <- ends[[1L]]
        if (length(starts) > 1L) {
            for (idx in 2:length(starts)) {
                if (starts[[idx]] <= current_end + 1) {
                    current_end <- max(current_end, ends[[idx]])
                } else {
                    total <- total + current_end - current_start + 1
                    current_start <- starts[[idx]]
                    current_end <- ends[[idx]]
                }
            }
        }
        as.numeric(total + current_end - current_start + 1)
    }

    # ---------------------------------------------------------------------------
    # Select the canonical (representative) transcript from a list of blocks.
    # Returns the 1-based index of the canonical block within transcript_blocks.
    # Criterion cascade:
    #   NCBI annotation signals (applied first when present):
    #   1. tag=MANE Select        (col 9 attribute)
    #   2. tag=RefSeq Select      (col 9 attribute)
    #   3. source=BestRefSeq + NM_/NR_ accession prefix
    #   4. source=BestRefSeq      (any accession)
    #   5. NM_/NR_ accession prefix (regardless of source)
    #   Heuristic fallback (when no NCBI signal is found):
    #   6. Longest CDS (union of merged CDS ranges)
    #   7. Longest total transcript span
    #   8. Most exons
    #   9. Alphabetically first transcript ID (deterministic tiebreaker)
    #  10. Position in file (load order)
    # ncRNA fallback: if no block has CDS > 0, uses transcript length as primary.
    # ---------------------------------------------------------------------------
    compute_canonical_block_idx <- function(transcript_blocks) {
        n <- length(transcript_blocks)
        if (n <= 1L) return(1L)

        tx_types_local <- c(
            "mrna", "transcript", "ncrna", "rrna", "trna", "lncrna", "lnc_rna",
            "pseudogenic_transcript", "primary_transcript", "pre_mirna", "mirna",
            "snrna", "snorna", "guide_rna", "rnase_p_rna"
        )

        metrics <- lapply(seq_len(n), function(idx) {
            block_data <- transcript_blocks[[idx]]
            if (is.null(block_data) || !is.data.frame(block_data) || nrow(block_data) == 0L) {
                return(list(idx = idx, cds_len = 0, tx_len = 0, exon_n = 0L, tx_label = "", ncbi_priority = 6L))
            }
            cached_meta <- attr(block_data, "cgev_transcript_meta", exact = TRUE)
            row_types <- as.character((cached_meta %||% list())$row_types %||% character(0))
            if (length(row_types) != nrow(block_data)) {
                row_types <- tolower(trimws(as.character(block_data$V3 %||% rep("", nrow(block_data)))))
            }
            starts    <- suppressWarnings(as.numeric(block_data$V4))
            ends      <- suppressWarnings(as.numeric(block_data$V5))

            # CDS length (sum of merged CDS intervals)
            cds_ranges <- (cached_meta %||% list())$cds_ranges
            if (!is.data.frame(cds_ranges)) {
                cds_ranges <- as_feature_ranges(block_data[row_types == "cds", , drop = FALSE])
            }
            cds_len <- feature_ranges_union_length_normalized(cds_ranges)
            if (!is.finite(cds_len) || cds_len < 0) cds_len <- 0

            # Exon count (fall back to CDS rows if no exon features)
            exon_n <- sum(row_types == "exon", na.rm = TRUE)
            if (exon_n == 0L) exon_n <- sum(row_types == "cds", na.rm = TRUE)
            if (!is.finite(exon_n)) exon_n <- 0L

            # Transcript span length
            tx_rows <- which(row_types %in% tx_types_local)
            tx_len  <- NA_real_
            tx_label <- as.character((cached_meta %||% list())$transcript %||% "")
            tx_attr <- as.character((cached_meta %||% list())$tx_attr %||% "")
            if (length(tx_rows) > 0L) {
                ri     <- tx_rows[1L]
                cached_span <- suppressWarnings(as.numeric((cached_meta %||% list())$span %||% numeric(0)))
                tx_len <- if (length(cached_span) >= 2L && all(is.finite(cached_span[1:2]))) {
                    as.numeric(cached_span[2] - cached_span[1] + 1)
                } else {
                    suppressWarnings(as.numeric(ends[ri] - starts[ri] + 1))
                }
                if (!nzchar(tx_attr)) tx_attr <- as.character(block_data$V9[ri] %||% "")
                if (!nzchar(tx_label)) {
                    parsed <- tryCatch(parse_gff_attributes(tx_attr), error = function(e) list())
                    tx_label <- tryCatch(
                        as.character(pick_attr(parsed, c("transcript_id", "id", "name", "transcript")) %||% ""),
                        error = function(e) ""
                    )
                }
            }
            if (!is.finite(tx_len) || tx_len <= 0) {
                tx_span <- tryCatch(compute_transcript_span(block_data), error = function(e) c(start = NA_real_, end = NA_real_))
                tx_len  <- suppressWarnings(as.numeric(tx_span[["end"]] - tx_span[["start"]] + 1))
            }
            if (!is.finite(tx_len)) tx_len <- 0

            # NCBI canonical priority (1=best ... 6=fallback to heuristics)
            ncbi_priority <- 6L
            if (length(tx_rows) > 0L) {
                ri_src     <- tx_rows[1L]
                source_val <- tolower(trimws(as.character(block_data$V2[ri_src] %||% "")))
                if (!nzchar(tx_attr)) tx_attr <- as.character(block_data$V9[ri_src] %||% "")
                tag_matches <- stringr::str_match_all(
                    tx_attr,
                    stringr::regex('(?:^|;)\\s*tag(?:=|\\s+")([^;"]+)', ignore_case = TRUE)
                )[[1]]
                tag_raw <- if (nrow(tag_matches) > 0L) tag_matches[, 2] else character(0)
                tag_vals <- tolower(trimws(unlist(strsplit(paste(tag_raw, collapse = ","), ","))))
                is_nm_nr   <- grepl("^(NM_|NR_)", tx_label, ignore.case = TRUE)

                if (any(tag_vals == "mane select")) {
                    ncbi_priority <- 1L
                } else if (any(tag_vals == "refseq select")) {
                    ncbi_priority <- 2L
                } else if (source_val == "bestrefseq" && is_nm_nr) {
                    ncbi_priority <- 3L
                } else if (source_val == "bestrefseq") {
                    ncbi_priority <- 4L
                } else if (is_nm_nr) {
                    ncbi_priority <- 5L
                }
            }

            list(idx = idx, cds_len = cds_len, tx_len = tx_len,
                 exon_n = as.integer(exon_n), tx_label = tolower(tx_label),
                 ncbi_priority = ncbi_priority)
        })

        cds_lens       <- vapply(metrics, function(m) m$cds_len,       numeric(1))
        tx_lens        <- vapply(metrics, function(m) m$tx_len,        numeric(1))
        exon_ns        <- vapply(metrics, function(m) m$exon_n,        integer(1))
        tx_labels      <- vapply(metrics, function(m) m$tx_label,      character(1))
        ncbi_priorities <- vapply(metrics, function(m) m$ncbi_priority, integer(1))
        idxs           <- seq_len(n)

        has_cds <- any(is.finite(cds_lens) & cds_lens > 0, na.rm = TRUE)

        ord <- if (has_cds) {
            order(
                ncbi_priorities,
                -ifelse(is.finite(cds_lens),  cds_lens,  -Inf),
                -ifelse(is.finite(tx_lens),   tx_lens,   -Inf),
                -ifelse(is.finite(exon_ns),   exon_ns,   -Inf),
                tx_labels,
                idxs
            )
        } else {
            order(
                ncbi_priorities,
                -ifelse(is.finite(tx_lens),   tx_lens,   -Inf),
                -ifelse(is.finite(exon_ns),   exon_ns,   -Inf),
                tx_labels,
                idxs
            )
        }

        as.integer(ord[1L])
    }

    count_exons_with_cds_overlap <- function(exon_ranges, cds_ranges) {
        ex <- unique_feature_ranges(exon_ranges)
        cds <- unique_feature_ranges(cds_ranges)
        if (nrow(ex) == 0 || nrow(cds) == 0) {
            return(0L)
        }
        hits <- vapply(seq_len(nrow(ex)), function(i) {
            any(ex$start[i] <= cds$end & ex$end[i] >= cds$start)
        }, logical(1))
        as.integer(sum(hits))
    }

    count_normalized_exons_with_cds_overlap <- function(exon_ranges, cds_ranges) {
        if (is.null(exon_ranges) || is.null(cds_ranges) ||
            nrow(exon_ranges) == 0L || nrow(cds_ranges) == 0L) {
            return(0L)
        }
        ex_start <- as.numeric(exon_ranges$start)
        ex_end <- as.numeric(exon_ranges$end)
        cds_start <- as.numeric(cds_ranges$start)
        cds_end <- as.numeric(cds_ranges$end)
        hits <- vapply(seq_along(ex_start), function(i) {
            any(ex_start[[i]] <= cds_end & ex_end[[i]] >= cds_start)
        }, logical(1))
        as.integer(sum(hits))
    }

    get_attr_first_value <- function(attrs, keys = character(0), fallback = "") {
        if (is.null(attrs) || length(attrs) == 0) {
            return(as.character(fallback %||% ""))
        }
        keys_lc <- tolower(as.character(keys %||% character(0)))
        for (k in keys_lc) {
            vals <- attrs[[k]]
            vals <- as.character(vals %||% character(0))
            vals <- vals[!is.na(vals) & nzchar(trimws(vals))]
            if (length(vals) > 0) {
                return(trimws(vals[1]))
            }
        }
        as.character(fallback %||% "")
    }

    extract_biotype_from_attr_text <- function(attr_txt) {
        attr_value <- as.character(attr_txt %||% "")
        key_priority <- c("transcript_biotype", "gene_biotype", "biotype", "gene_type", "transcript_type", "gbkey")
        matches <- stringr::str_match_all(
            attr_value,
            stringr::regex(
                '(?:^|;)\\s*(transcript_biotype|gene_biotype|biotype|gene_type|transcript_type|gbkey)\\s*(?:=|\\s+)\\s*"?([^;"]+)',
                ignore_case = TRUE
            )
        )[[1]]
        bt <- ""
        if (nrow(matches) > 0L) {
            keys_found <- tolower(matches[, 2])
            for (key in key_priority) {
                idx <- which(keys_found == key)[1L]
                if (is.finite(idx)) {
                    bt <- safe_url_decode(matches[idx, 3])
                    break
                }
            }
        }
        bt <- trimws(as.character(bt %||% ""))
        if (!nzchar(bt)) {
            return("")
        }
        bt <- gsub("_", " ", bt, fixed = TRUE)
        stringr::str_to_sentence(tolower(bt))
    }

    normalize_gene_function_text <- function(x) {
        txt <- trimws(as_text_one(x))
        if (!nzchar(txt)) {
            return("")
        }
        txt <- gsub("\\s+", " ", txt, perl = TRUE)
        txt <- sub("^summary\\s*:\\s*", "", txt, ignore.case = TRUE, perl = TRUE)
        trimws(txt)
    }

    truncate_gene_function_text <- function(x, max_chars = 190L) {
        txt <- normalize_gene_function_text(x)
        max_chars <- suppressWarnings(as.integer(max_chars))
        if (!is.finite(max_chars) || max_chars < 40L) {
            max_chars <- 190L
        }
        if (!nzchar(txt) || nchar(txt) <= max_chars) {
            return(txt)
        }
        paste0(substr(txt, 1L, max_chars - 1L), "\u2026")
    }

    extract_local_gene_function_text <- function(plot_data) {
        if (is.null(plot_data) || nrow(plot_data) == 0 || !("V9" %in% colnames(plot_data))) {
            return("")
        }
        df <- as.data.frame(plot_data, stringsAsFactors = FALSE)
        row_types <- tolower(trimws(as.character(df$V3 %||% rep("", nrow(df)))))
        tx_types <- transcript_level_feature_types()
        gene_idx <- which(row_types == "gene")
        tx_idx <- which(row_types %in% tx_types)

        fetch_from_attr <- function(attr_txt, keys = c("description", "note", "product", "function", "gene_function")) {
            attrs <- tryCatch(parse_gff_attributes(as.character(attr_txt %||% "")), error = function(e) list())
            txt <- get_attr_first_value(attrs, keys, fallback = "")
            normalize_gene_function_text(txt)
        }

        if (length(gene_idx) > 0) {
            txt <- fetch_from_attr(df$V9[gene_idx[1]], keys = c("description", "note", "function", "gene_function", "product"))
            if (nzchar(txt)) {
                return(txt)
            }
        }
        if (length(tx_idx) > 0) {
            txt <- fetch_from_attr(df$V9[tx_idx[1]], keys = c("description", "product", "note", "function"))
            if (nzchar(txt)) {
                return(txt)
            }
        }

        scan_idx <- seq_len(min(8L, nrow(df)))
        for (i in scan_idx) {
            txt <- fetch_from_attr(df$V9[i], keys = c("description", "note", "product"))
            if (nzchar(txt)) {
                return(txt)
            }
        }
        ""
    }

    safe_ncbi_gene_summary_lookup <- function(gene_id, timeout_sec = 4L) {
        gid <- trimws(as.character(gene_id %||% ""))
        if (!nzchar(gid) || !grepl("^[0-9]+$", gid)) {
            return("")
        }
        req <- httr2::request("https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi") %>%
            httr2::req_user_agent("CGV-GeneFunction/1.0") %>%
            httr2::req_url_query(
                db = "gene",
                id = gid,
                retmode = "json",
                version = "2.0"
            ) %>%
            httr2::req_timeout(as.numeric(timeout_sec))

        resp <- tryCatch(httr2::req_perform(req), error = function(e) NULL)
        if (is.null(resp) || httr2::resp_status(resp) >= 400) {
            return("")
        }
        payload_txt <- tryCatch(httr2::resp_body_string(resp), error = function(e) "")
        if (!nzchar(payload_txt)) {
            return("")
        }
        payload <- tryCatch(jsonlite::fromJSON(payload_txt, simplifyVector = FALSE), error = function(e) NULL)
        if (is.null(payload$result) || is.null(payload$result[[gid]])) {
            return("")
        }
        rec <- payload$result[[gid]]
        if (!is.list(rec)) {
            return("")
        }
        normalize_gene_function_text(rec$summary %||% "")
    }

    resolve_function_gene_id <- function(plot_data, gene_label = "", matched_gene_id = "") {
        gene_id <- trimws(as.character(matched_gene_id %||% ""))
        if (!grepl("^[0-9]+$", gene_id)) {
            gene_id <- ""
        }
        if (nzchar(gene_id)) {
            return(gene_id)
        }
        candidates <- tryCatch(extract_go_candidates_from_plot_data(plot_data, gene_label = gene_label), error = function(e) NULL)
        cands <- unique(trimws(as.character(candidates$gene_ids %||% character(0))))
        cands <- cands[grepl("^[0-9]+$", cands)]
        if (length(cands) > 0) {
            return(as.character(cands[1]))
        }
        ""
    }

    resolve_gene_function_summary <- function(plot_data, gene_label = "", organism_name = "", taxid = NA_integer_, matched_gene_id = "") {
        gene_id <- resolve_function_gene_id(
            plot_data = plot_data,
            gene_label = gene_label,
            matched_gene_id = matched_gene_id
        )
        local_txt <- extract_local_gene_function_text(plot_data)
        if (nzchar(local_txt)) {
            short_txt <- truncate_gene_function_text(local_txt, max_chars = 190L)
            return(list(
                full = local_txt,
                short = short_txt,
                source = "Annotation",
                expandable = !identical(short_txt, local_txt),
                gene_id = gene_id
            ))
        }

        tid <- suppressWarnings(as.integer(taxid %||% NA_integer_))
        if (!is.finite(tid) || is.na(tid) || tid <= 0) {
            tid <- NA_integer_
        }
        gene_norm <- tolower(trimws(as.character(gene_label %||% "")))
        org_norm <- normalize_go_text(organism_name)
        org_norm <- as.character(org_norm[1] %||% "")
        cache_key <- paste(
            if (nzchar(gene_id)) paste0("gid:", gene_id) else paste0("gene:", gene_norm),
            if (is.finite(tid) && !is.na(tid)) paste0("tax:", tid) else paste0("org:", org_norm),
            sep = "||"
        )

        cache_map <- geneFunctionSummaryCache()
        if (!is.list(cache_map)) {
            cache_map <- list()
        }
        cached <- cache_map[[cache_key]]
        if (is.list(cached) && nzchar(as.character(cached$full %||% ""))) {
            return(cached)
        }

        ncbi_txt <- if (nzchar(gene_id)) safe_ncbi_gene_summary_lookup(gene_id, timeout_sec = 4L) else ""
        if (nzchar(ncbi_txt)) {
            short_txt <- truncate_gene_function_text(ncbi_txt, max_chars = 190L)
            result <- list(
                full = ncbi_txt,
                short = short_txt,
                source = "NCBI Gene",
                expandable = !identical(short_txt, ncbi_txt),
                gene_id = gene_id
            )
        } else {
            result <- list(
                full = "No function summary available for this gene.",
                short = "No function summary available for this gene.",
                source = "Not available",
                expandable = FALSE,
                gene_id = gene_id
            )
        }

        cache_map[[cache_key]] <- result
        if (length(cache_map) > 500L) {
            keep <- tail(names(cache_map), 500L)
            cache_map <- cache_map[keep]
        }
        geneFunctionSummaryCache(cache_map)
        result
    }

    build_transcript_metrics_payloads <- function(full_data, transcript_blocks = NULL, representative_name = "", organism_name = "", annotation_path = "", use_report_map = FALSE, report_path = "", perf_run = NULL, perf_context = "APP") {
        if (is.null(full_data) || nrow(full_data) == 0) {
            return(list())
        }

        blocks <- transcript_blocks
        if (is.null(blocks) || length(blocks) == 0) {
            blocks <- split_gene_data_by_transcript(full_data)
        }
        if (length(blocks) == 0) {
            blocks <- list(full_data)
        }

        clean_label <- function(x, fallback = "N/A") {
            txt <- trimws(as.character(x %||% ""))
            if (!nzchar(txt) || identical(txt, "NA")) {
                txt <- as.character(fallback %||% "N/A")
            }
            txt
        }
        format_bp_value <- function(x) {
            if (!is.finite(as.numeric(x))) {
                return("N/A")
            }
            paste0(format_bp_short(x), " bp")
        }
        format_bp_short_vec <- function(x) {
            xx <- suppressWarnings(as.numeric(x))
            out <- rep("N/A", length(xx))
            keep <- is.finite(xx)
            if (any(keep)) {
                out[keep] <- format(
                    as.integer(round(xx[keep])),
                    big.mark = ",",
                    scientific = FALSE,
                    trim = TRUE
                )
            }
            out
        }
        format_bp_value_vec <- function(x) {
            out <- format_bp_short_vec(x)
            keep <- out != "N/A"
            out[keep] <- paste0(out[keep], " bp")
            out
        }
        format_pct_short_vec <- function(x, digits = 1L) {
            xx <- suppressWarnings(as.numeric(x))
            out <- rep("N/A", length(xx))
            keep <- is.finite(xx)
            if (any(keep)) {
                out[keep] <- sprintf(paste0("%.", as.integer(digits), "f%%"), xx[keep])
            }
            out
        }
        tx_types <- transcript_level_feature_types()
        chr_short_cache <- new.env(parent = emptyenv())
        get_chr_short_cached <- function(chr_raw) {
            k <- paste0(
                as.character(annotation_path %||% ""),
                "::",
                as.character(chr_raw %||% ""),
                "::",
                as.character(isTRUE(use_report_map)),
                "::",
                as.character(report_path %||% "")
            )
            if (exists(k, envir = chr_short_cache, inherits = FALSE)) {
                return(get(k, envir = chr_short_cache, inherits = FALSE))
            }
            out <- tryCatch(
                get_short_chromosome_name(
                    chr_raw,
                    as.character(annotation_path %||% ""),
                    use_report_map = isTRUE(use_report_map),
                    report_path = as.character(report_path %||% "")
                ),
                error = function(e) chr_raw
            )
            assign(k, out, envir = chr_short_cache)
            out
        }

        metrics_setup_t0 <- app_perf_now()
        df_full <- as.data.frame(full_data, stringsAsFactors = FALSE)
        row_types_full <- tolower(trimws(as.character(df_full$V3 %||% rep("", nrow(df_full)))))
        gene_rows_full <- df_full[row_types_full == "gene", , drop = FALSE]
        gene_start <- suppressWarnings(min(as.numeric(gene_rows_full$V4), na.rm = TRUE))
        gene_end <- suppressWarnings(max(as.numeric(gene_rows_full$V5), na.rm = TRUE))
        if (!is.finite(gene_start) || !is.finite(gene_end) || gene_end < gene_start) {
            span_full <- compute_transcript_span(df_full)
            gene_start <- as.numeric(span_full[["start"]])
            gene_end <- as.numeric(span_full[["end"]])
        }
        gene_len <- if (is.finite(gene_start) && is.finite(gene_end) && gene_end >= gene_start) {
            as.numeric(gene_end - gene_start + 1)
        } else {
            NA_real_
        }

        gene_attr <- if (nrow(gene_rows_full) > 0) as.character(gene_rows_full$V9[1] %||% "") else ""
        gene_biotype <- extract_biotype_from_attr_text(gene_attr)

        cds_full_ranges <- as_feature_ranges(df_full[row_types_full == "cds", , drop = FALSE])
        gene_coding_bp <- feature_ranges_union_length(cds_full_ranges)
        gene_coding_pct <- if (is.finite(gene_len) && gene_len > 0 && is.finite(gene_coding_bp) && gene_coding_bp > 0) {
            100 * as.numeric(gene_coding_bp) / as.numeric(gene_len)
        } else {
            NA_real_
        }
        gene_noncoding_pct <- if (is.finite(gene_coding_pct)) {
            max(0, 100 - as.numeric(gene_coding_pct))
        } else {
            NA_real_
        }
        app_perf_mark_ms(perf_run, "metrics_setup_ms", app_perf_elapsed_ms(metrics_setup_t0), perf_context)

        per_block <- vector("list", length(blocks))
        exon_keys_by_block <- vector("list", length(blocks))
        exon_ranges_by_block <- vector("list", length(blocks))
        tx_lengths <- rep(NA_real_, length(blocks))
        cds_lengths <- rep(NA_real_, length(blocks))
        tx_biotypes <- rep("", length(blocks))
        tx_labels <- rep("N/A", length(blocks))
        chr_short_labels <- rep("N/A", length(blocks))
        stage_ms <- c(labels = 0, chromosome = 0, span = 0, biotype = 0, ranges = 0, derived = 0)

        for (i in seq_along(blocks)) {
            block <- blocks[[i]]
            if (is.null(block) || nrow(block) == 0) {
                block <- df_full
            }
            cached_meta <- attr(block, "cgev_transcript_meta", exact = TRUE)
            block <- as.data.frame(block, stringsAsFactors = FALSE)
            row_types <- as.character((cached_meta %||% list())$row_types %||% character(0))
            if (length(row_types) != nrow(block)) {
                row_types <- tolower(trimws(as.character(block$V3 %||% rep("", nrow(block)))))
            }
            tx_rows <- block[row_types %in% tx_types, , drop = FALSE]
            gene_rows <- block[row_types == "gene", , drop = FALSE]
            stage_t0 <- app_perf_now()
            labels <- extract_plot_labels(block)
            tx_name <- clean_label(normalize_display_id(labels$transcript), "N/A")
            tx_labels[i] <- tx_name
            stage_ms[["labels"]] <- stage_ms[["labels"]] + app_perf_elapsed_ms(stage_t0)
            stage_t0 <- app_perf_now()
            chr_raw <- clean_label(labels$chromosome, "N/A")
            chr_short <- get_chr_short_cached(chr_raw)
            chr_short_labels[i] <- clean_label(chr_short, chr_raw)
            stage_ms[["chromosome"]] <- stage_ms[["chromosome"]] + app_perf_elapsed_ms(stage_t0)

            stage_t0 <- app_perf_now()
            tx_span <- compute_transcript_span(block)
            tx_start <- as.numeric(tx_span[["start"]])
            tx_end <- as.numeric(tx_span[["end"]])
            tx_len <- if (is.finite(tx_start) && is.finite(tx_end) && tx_end >= tx_start) as.numeric(tx_end - tx_start + 1) else NA_real_
            tx_lengths[i] <- tx_len
            stage_ms[["span"]] <- stage_ms[["span"]] + app_perf_elapsed_ms(stage_t0)

            stage_t0 <- app_perf_now()
            tx_attr <- as.character((cached_meta %||% list())$tx_attr %||% "")
            if (!nzchar(tx_attr) && nrow(tx_rows) > 0) tx_attr <- as.character(tx_rows$V9[1] %||% "")
            gene_attr_block <- as.character((cached_meta %||% list())$gene_attr %||% "")
            if (!nzchar(gene_attr_block)) gene_attr_block <- if (nrow(gene_rows) > 0) as.character(gene_rows$V9[1] %||% "") else gene_attr
            tx_biotype <- extract_biotype_from_attr_text(tx_attr)
            if (!nzchar(tx_biotype)) {
                tx_biotype <- extract_biotype_from_attr_text(gene_attr_block)
            }
            tx_biotype <- clean_label(tx_biotype, "N/A")
            tx_biotypes[i] <- tx_biotype
            stage_ms[["biotype"]] <- stage_ms[["biotype"]] + app_perf_elapsed_ms(stage_t0)

            stage_t0 <- app_perf_now()
            exon_ranges <- (cached_meta %||% list())$exon_ranges
            if (!is.data.frame(exon_ranges)) {
                exon_ranges <- unique_feature_ranges(as_feature_ranges(block[row_types == "exon", , drop = FALSE]))
            }
            cds_ranges <- (cached_meta %||% list())$cds_ranges
            if (!is.data.frame(cds_ranges)) {
                cds_ranges <- unique_feature_ranges(as_feature_ranges(block[row_types == "cds", , drop = FALSE]))
            }
            exon_ranges_for_metrics <- exon_ranges
            if (nrow(exon_ranges_for_metrics) == 0 && nrow(cds_ranges) > 0) {
                exon_ranges_for_metrics <- cds_ranges
            }

            exon_ranges_by_block[[i]] <- exon_ranges_for_metrics
            exon_keys_by_block[[i]] <- if (nrow(exon_ranges_for_metrics) > 0) {
                paste0(exon_ranges_for_metrics$start, "-", exon_ranges_for_metrics$end)
            } else {
                character(0)
            }
            stage_ms[["ranges"]] <- stage_ms[["ranges"]] + app_perf_elapsed_ms(stage_t0)

            stage_t0 <- app_perf_now()
            cds_len <- feature_ranges_union_length_normalized(cds_ranges)
            cds_lengths[i] <- cds_len
            protein_aa <- if (is.finite(cds_len) && cds_len > 0) floor(cds_len / 3) else NA_real_
            coding_exons <- if (nrow(exon_ranges_for_metrics) > 0 && nrow(cds_ranges) > 0) {
                count_normalized_exons_with_cds_overlap(exon_ranges_for_metrics, cds_ranges)
            } else if (nrow(cds_ranges) > 0) {
                as.integer(nrow(cds_ranges))
            } else {
                0L
            }
            tx_coding_pct <- if (is.finite(tx_len) && tx_len > 0 && is.finite(cds_len) && cds_len > 0) {
                100 * as.numeric(cds_len) / as.numeric(tx_len)
            } else {
                NA_real_
            }
            tx_noncoding_bp <- if (is.finite(tx_len) && tx_len > 0) {
                max(0, as.numeric(tx_len) - ifelse(is.finite(cds_len), as.numeric(cds_len), 0))
            } else {
                NA_real_
            }
            per_block[[i]] <- list(
                tx_name = tx_name,
                tx_len = tx_len,
                tx_start = tx_start,
                tx_end = tx_end,
                cds_len = cds_len,
                protein_aa = protein_aa,
                coding_exons = coding_exons,
                tx_coding_pct = tx_coding_pct,
                tx_noncoding_bp = tx_noncoding_bp,
                tx_biotype = tx_biotype,
                chr_short = clean_label(chr_short_labels[i], "N/A")
            )
            stage_ms[["derived"]] <- stage_ms[["derived"]] + app_perf_elapsed_ms(stage_t0)
        }
        for (stage_name in names(stage_ms)) {
            app_perf_mark_ms(
                perf_run,
                paste0("metrics_stage_", stage_name, "_ms"),
                stage_ms[[stage_name]],
                perf_context
            )
        }

        metrics_aggregate_t0 <- app_perf_now()
        if (!nzchar(gene_biotype)) {
            tb <- tx_biotypes[nzchar(tx_biotypes) & tx_biotypes != "N/A"]
            if (length(tb) > 0) {
                gene_biotype <- names(sort(table(tb), decreasing = TRUE))[1]
            }
        }
        gene_biotype <- clean_label(gene_biotype, "N/A")

        ex_nonempty <- exon_ranges_by_block[vapply(exon_ranges_by_block, function(x) !is.null(x) && nrow(x) > 0, logical(1))]
        all_unique_exons <- if (length(ex_nonempty) > 0) {
            unique_feature_ranges(do.call(rbind,  ex_nonempty))
        } else {
            data.frame(start = numeric(0), end = numeric(0), stringsAsFactors = FALSE)
        }
        exon_lengths <- if (nrow(all_unique_exons) > 0) {
            as.numeric(all_unique_exons$end - all_unique_exons$start + 1)
        } else {
            numeric(0)
        }
        unique_exon_total <- as.integer(nrow(all_unique_exons))

        exon_key_vec <- unlist(exon_keys_by_block, use.names = FALSE)
        if (length(exon_key_vec) > 0) {
            exon_key_table <- table(exon_key_vec)
            constitutive_exons <- if (length(blocks) > 1) {
                as.integer(sum(as.integer(exon_key_table) >= length(blocks)))
            } else {
                as.integer(length(exon_key_table))
            }
            alternative_exons <- if (length(blocks) > 1) {
                as.integer(max(0, length(exon_key_table) - constitutive_exons))
            } else {
                0L
            }
        } else {
            constitutive_exons <- 0L
            alternative_exons <- 0L
        }

        longest_tx_idx <- if (any(is.finite(tx_lengths))) which.max(ifelse(is.finite(tx_lengths), tx_lengths, -Inf)) else NA_integer_
        longest_cds_idx <- if (any(is.finite(cds_lengths))) which.max(ifelse(is.finite(cds_lengths), cds_lengths, -Inf)) else NA_integer_

        longest_tx_txt <- if (is.finite(longest_tx_idx) && !is.na(longest_tx_idx)) {
            sprintf("%s (%s bp)", clean_label(tx_labels[longest_tx_idx], "N/A"), format_bp_short(tx_lengths[longest_tx_idx]))
        } else {
            "N/A"
        }
        longest_cds_txt <- if (is.finite(longest_cds_idx) && !is.na(longest_cds_idx) && is.finite(cds_lengths[longest_cds_idx]) && cds_lengths[longest_cds_idx] > 0) {
            sprintf("%s (%s bp)", clean_label(tx_labels[longest_cds_idx], "N/A"), format_bp_short(cds_lengths[longest_cds_idx]))
        } else {
            "N/A"
        }

        coding_vs_noncoding_txt <- if (is.finite(gene_coding_pct)) {
            sprintf("%s coding | %s non-coding", format_pct_short(gene_coding_pct), format_pct_short(gene_noncoding_pct))
        } else {
            "N/A"
        }

        gene_name_txt <- clean_label(normalize_display_id(representative_name), "N/A")
        organism_txt <- format_org_name(clean_label(organism_name, "N/A"))
        longest_exon_txt <- if (length(exon_lengths) > 0 && any(is.finite(exon_lengths))) {
            format_bp_value(max(exon_lengths, na.rm = TRUE))
        } else {
            "N/A"
        }
        shortest_exon_txt <- if (length(exon_lengths) > 0 && any(is.finite(exon_lengths))) {
            format_bp_value(min(exon_lengths, na.rm = TRUE))
        } else {
            "N/A"
        }
        gene_summary_section <- list(
            title = "Gene summary",
            rows = list(
                list(label = "Biotype", value = gene_biotype),
                list(label = "Transcript isoforms", value = as.character(length(blocks))),
                list(label = "Longest transcript", value = longest_tx_txt),
                list(label = "Longest CDS", value = longest_cds_txt),
                list(label = "Coding vs non-coding", value = coding_vs_noncoding_txt)
            )
        )
        splicing_complexity_section <- list(
            title = "Splicing complexity",
            rows = list(
                list(label = "Unique exons (gene)", value = as.character(unique_exon_total)),
                list(label = "Constitutive exons", value = as.character(constitutive_exons)),
                list(label = "Alternative exons", value = as.character(alternative_exons)),
                list(label = "Longest exon", value = longest_exon_txt),
                list(label = "Shortest exon", value = shortest_exon_txt)
            )
        )
        app_perf_mark_ms(perf_run, "metrics_aggregate_ms", app_perf_elapsed_ms(metrics_aggregate_t0), perf_context)

        metrics_payloads_t0 <- app_perf_now()
        # Formatting one scalar at a time is surprisingly expensive for genes
        # with hundreds of isoforms. Format each numeric field in one vectorized
        # pass, then assemble the same payload strings below.
        tx_len_vec <- vapply(per_block, function(tx) as.numeric(tx$tx_len %||% NA_real_), numeric(1))
        cds_len_vec <- vapply(per_block, function(tx) as.numeric(tx$cds_len %||% NA_real_), numeric(1))
        protein_aa_vec <- vapply(per_block, function(tx) as.numeric(tx$protein_aa %||% NA_real_), numeric(1))
        tx_coding_pct_vec <- vapply(per_block, function(tx) as.numeric(tx$tx_coding_pct %||% NA_real_), numeric(1))
        tx_noncoding_bp_vec <- vapply(per_block, function(tx) as.numeric(tx$tx_noncoding_bp %||% NA_real_), numeric(1))
        tx_start_vec <- vapply(per_block, function(tx) as.numeric(tx$tx_start %||% NA_real_), numeric(1))
        tx_end_vec <- vapply(per_block, function(tx) as.numeric(tx$tx_end %||% NA_real_), numeric(1))
        cds_gene_pct_vec <- if (is.finite(gene_len) && gene_len > 0) {
            ifelse(is.finite(cds_len_vec) & cds_len_vec > 0, 100 * cds_len_vec / gene_len, NA_real_)
        } else {
            rep(NA_real_, length(cds_len_vec))
        }
        tx_len_txt_vec <- format_bp_value_vec(tx_len_vec)
        cds_len_txt_vec <- format_bp_value_vec(cds_len_vec)
        cds_len_txt_vec[!is.finite(cds_len_vec) | cds_len_vec <= 0] <- "N/A"
        protein_aa_txt_vec <- format_bp_short_vec(protein_aa_vec)
        protein_aa_txt_vec[!is.finite(protein_aa_vec) | protein_aa_vec <= 0] <- "N/A"
        protein_aa_txt_vec[protein_aa_txt_vec != "N/A"] <- paste0(protein_aa_txt_vec[protein_aa_txt_vec != "N/A"], " aa")
        tx_coding_pct_txt_vec <- format_pct_short_vec(tx_coding_pct_vec)
        cds_gene_pct_txt_vec <- format_pct_short_vec(cds_gene_pct_vec)
        tx_noncoding_bp_txt_vec <- format_bp_value_vec(tx_noncoding_bp_vec)
        tx_start_txt_vec <- format_bp_short_vec(tx_start_vec)
        tx_end_txt_vec <- format_bp_short_vec(tx_end_vec)
        tx_coords_txt_vec <- ifelse(
            is.finite(tx_start_vec) & is.finite(tx_end_vec),
            paste0(tx_start_txt_vec, " - ", tx_end_txt_vec),
            "N/A"
        )
        payloads <- vector("list", length(blocks))
        for (i in seq_along(blocks)) {
            tx <- per_block[[i]]

            payloads[[i]] <- list(
                title = "Gene statistics",
                subtitle = sprintf(
                    "%s | %s",
                    gene_name_txt,
                    organism_txt
                ),
                sections = list(
                    gene_summary_section,
                    splicing_complexity_section,
                    list(
                        title = "Current transcript",
                        rows = list(
                            list(label = "Biotype", value = clean_label(tx$tx_biotype, "N/A")),
                            list(label = "Transcript length", value = tx_len_txt_vec[[i]]),
                            list(
                                label = "CDS length",
                                value = cds_len_txt_vec[[i]]
                            ),
                            list(
                                label = "Protein length",
                                value = protein_aa_txt_vec[[i]]
                            ),
                            list(label = "Coding exons", value = as.character(as.integer(tx$coding_exons %||% 0L))),
                            list(label = "CDS / transcript", value = tx_coding_pct_txt_vec[[i]]),
                            list(label = "CDS / gene", value = cds_gene_pct_txt_vec[[i]]),
                            list(
                                label = "Non-coding region (transcript)",
                                value = tx_noncoding_bp_txt_vec[[i]]
                            ),
                            list(label = "Transcript coords", value = tx_coords_txt_vec[[i]])
                        )
                    )
                )
            )
        }
        app_perf_mark_ms(perf_run, "metrics_payload_assembly_ms", app_perf_elapsed_ms(metrics_payloads_t0), perf_context)

        payloads
    }

    extract_sequence_from_blob <- function(blob_text) {
        txt <- as.character(blob_text %||% "")
        if (!nzchar(txt)) {
            return("")
        }
        if (exists("is_sequence_composition_blob", mode = "function") && isTRUE(is_sequence_composition_blob(txt))) {
            return("")
        }
        lines <- unlist(strsplit(txt, "\n", fixed = TRUE), use.names = FALSE)
        if (length(lines) <= 1) {
            return("")
        }
        seq_raw <- paste(lines[-1], collapse = "")
        seq_clean <- toupper(gsub("[^ACGTN]", "", seq_raw))
        seq_clean
    }

    # ── Europe PMC: search papers by gene + organism ──────────────────────────
    search_papers_epmc <- function(gene_names, organism_scientific = NULL,
                                   organism_aliases = NULL, page = 1,
                                   page_size = 10, sort_by = "CITED desc") {
        gene_names <- trimws(as.character(gene_names %||% character(0)))
        gene_names <- gene_names[nzchar(gene_names)]
        if (length(gene_names) == 0) {
            return(list(
                hits = 0L, page = 1L, page_size = as.integer(page_size),
                total_pages = 0L, papers = list(), error = "No gene name provided."
            ))
        }

        organism_scientific <- trimws(as.character(organism_scientific %||% ""))
        organism_aliases <- trimws(as.character(organism_aliases %||% character(0)))
        organism_aliases <- organism_aliases[nzchar(organism_aliases)]

        # Quote gene names to protect special characters (;, :, etc.)
        gene_terms <- paste0('"', gene_names, '"')
        gene_part <- paste0("(", paste(gene_terms, collapse = " OR "), ")")

        # Organism part: scientific name + common aliases
        org_terms <- c()
        if (nzchar(organism_scientific)) {
            org_terms <- c(org_terms, paste0('"', organism_scientific, '"'))
        }
        if (length(organism_aliases) > 0) {
            org_terms <- c(org_terms, paste0('"', organism_aliases, '"'))
        }

        if (length(org_terms) == 0) {
            return(list(
                hits = 0L, page = 1L, page_size = as.integer(page_size),
                total_pages = 0L, papers = list(),
                error = "No organism specified. Both gene and organism are required."
            ))
        }

        org_part <- paste0("(", paste(org_terms, collapse = " OR "), ")")
        query <- paste(gene_part, "AND", org_part)

        page <- max(1L, as.integer(page %||% 1))
        page_size <- max(1L, min(25L, as.integer(page_size %||% 10)))

        # Decode HTML entities helper
        decode_html <- function(x) {
            x <- as.character(x %||% "")
            if (!nzchar(x)) {
                return("")
            }
            x <- gsub("&lt;", "<", x, fixed = TRUE)
            x <- gsub("&gt;", ">", x, fixed = TRUE)
            x <- gsub("&amp;", "&", x, fixed = TRUE)
            x <- gsub("&quot;", '"', x, fixed = TRUE)
            x <- gsub("&#39;", "'", x, fixed = TRUE)
            x <- gsub("<[^>]+>", "", x)
            trimws(x)
        }

        # Map sort_by to Europe PMC API sort parameter
        sort_map <- list(
            "CITED desc"  = "CITED desc",
            "DATE desc"   = "P_PDATE_D desc",
            "DATE asc"    = "P_PDATE_D asc",
            "RELEVANCE"   = ""
        )
        sort_param <- sort_map[[sort_by]] %||% "CITED desc"

        # Use Europe PMC REST API directly with cursor pagination
        base_url <- "https://www.ebi.ac.uk/europepmc/webservices/rest/search"

        # First call to get hit count, then navigate to the target page using cursorMark
        cursor_mark <- "*"
        target_page_results <- NULL
        hit_count <- 0L

        tryCatch(
            {
                for (p in seq_len(page)) {
                    query_params <- list(
                        query = query,
                        format = "json",
                        resultType = "core",
                        pageSize = as.character(page_size),
                        synonym = "true",
                        cursorMark = cursor_mark
                    )
                    if (nzchar(sort_param)) {
                        query_params$sort <- sort_param
                    }

                    resp <- httr2::request(base_url) |>
                        httr2::req_url_query(!!!query_params) |>
                        httr2::req_timeout(8) |>
                        httr2::req_retry(max_tries = 1) |>
                        httr2::req_perform()

                    json <- httr2::resp_body_json(resp)
                    hit_count <- as.integer(json$hitCount %||% 0)

                    if (p == page) {
                        target_page_results <- json$resultList$result
                    }

                    next_cursor <- as.character(json$nextCursorMark %||% "")
                    if (!nzchar(next_cursor) || identical(next_cursor, cursor_mark)) {
                        break # No more pages
                    }
                    cursor_mark <- next_cursor
                }
            },
            error = function(e) {
                return(list(
                    hits = 0L, page = page, page_size = page_size,
                    total_pages = 0L, papers = list(), query = query,
                    error = paste("Europe PMC error:", conditionMessage(e))
                ))
            }
        )

        # Parse results
        paper_list <- list()
        if (!is.null(target_page_results) && is.list(target_page_results)) {
            for (i in seq_along(target_page_results)) {
                r <- target_page_results[[i]]
                if (!is.list(r)) next
                doi <- as.character(r$doi %||% "")
                pmid <- as.character(r$pmid %||% "")
                source <- as.character(r$source %||% "")
                id_epmc <- as.character(r$id %||% "")
                link <- if (nzchar(doi)) {
                    paste0("https://doi.org/", doi)
                } else if (nzchar(source) && nzchar(id_epmc)) {
                    paste0("https://europepmc.org/article/", source, "/", id_epmc)
                } else if (nzchar(pmid)) {
                    paste0("https://pubmed.ncbi.nlm.nih.gov/", pmid, "/")
                } else {
                    ""
                }
                abstract_raw <- as.character(r$abstractText %||% "")
                abstract_clean <- decode_html(abstract_raw)
                pub_year <- as.character(r$pubYear %||% r$firstPublicationDate %||% "")
                if (nzchar(pub_year) && nchar(pub_year) > 4) {
                    pub_year <- substr(pub_year, 1, 4)
                }
                cited <- suppressWarnings(as.integer(r$citedByCount %||% 0))
                if (!is.finite(cited)) cited <- 0L
                paper_list[[length(paper_list) + 1]] <- list(
                    title     = decode_html(as.character(r$title %||% "Untitled")),
                    authors   = as.character(r$authorString %||% "Unknown"),
                    year      = pub_year,
                    journal   = as.character(r$journalTitle %||% r$bookOrReportDetails$publisher %||% ""),
                    abstract  = if (nzchar(abstract_clean)) abstract_clean else "Abstract not available.",
                    doi       = doi,
                    link      = link,
                    cited_by  = cited,
                    source    = source
                )
            }
        }

        total_pages <- if (hit_count > 0 && page_size > 0) ceiling(hit_count / page_size) else 0L

        list(
            hits        = hit_count,
            page        = page,
            page_size   = page_size,
            total_pages = total_pages,
            papers      = paper_list,
            query       = query,
            error       = NULL
        )
    }

    build_plot_card_footer <- function(output_id) {
        div(
            class = "plot-card-footer",
            tags$button(
                type = "button",
                class = "plot-card-footer-nav plot-card-footer-nav-prev",
                title = "Show previous footer information",
                `aria-label` = "Show previous footer information",
                `aria-hidden` = "true",
                tabindex = "-1",
                disabled = NA,
                span(class = "plot-card-footer-nav-icon", `aria-hidden` = "true", HTML("&#x2039;"))
            ),
            div(
                class = "plot-card-footer-scroll",
                role = "region",
                `aria-label` = "Gene summary information",
                tabindex = "-1",
                uiOutput(output_id)
            ),
            tags$button(
                type = "button",
                class = "plot-card-footer-nav plot-card-footer-nav-next",
                title = "Show more footer information",
                `aria-label` = "Show more footer information",
                `aria-hidden` = "true",
                tabindex = "-1",
                disabled = NA,
                span(class = "plot-card-footer-nav-icon", `aria-hidden` = "true", HTML("&#x203A;"))
            )
        )
    }

    isoform_toggle_input_id <- function(context = "", plot_id = "") {
        context_key <- tolower(trimws(as.character(context %||% "")))
        context_key <- if (startsWith(context_key, "ortho")) "ortho" else "homo"
        paste0(
            "isoform_toggle_",
            context_key,
            "_",
            gsub("[^A-Za-z0-9_]", "_", as.character(plot_id %||% ""))
        )
    }

    build_footer_content_ui <- function(plot_data, seq_blob = NULL, metrics_payload = NULL,
                                        plot_id = NULL, context = "homo",
                                        gene_label = "", organism_name = "",
                                        gene_synonyms_str = "", organism_aliases_str = "",
                                        isoform_count = 0L, tx_group_key = NULL,
                                        total_transcripts = NULL,
                                        is_canonical = FALSE,
                                        is_canonical_copy = FALSE,
                                        isoform_expanded = FALSE) {
        footer_perf <- app_perf_new_run(sprintf("FOOTER-%s", toupper(as.character(context %||% "homo"))))
        app_perf_mark(
            footer_perf,
            sprintf("start plot_id=%s", as.character(plot_id %||% "NA")),
            "FOOTER"
        )
        if (is.null(plot_data) || nrow(plot_data) == 0) {
            app_perf_mark(footer_perf, "empty plot_data", "FOOTER")
            return(HTML("&nbsp;"))
        }

        df_gene <- plot_data %>% filter(V3 == "gene")
        tx_span <- compute_transcript_span(plot_data)
        tx_start <- as.numeric(tx_span[["start"]])
        tx_end   <- as.numeric(tx_span[["end"]])
        tx_len   <- as.numeric(tx_span[["end"]] - tx_span[["start"]] + 1)
        if (!is.finite(tx_len) || tx_len <= 0) tx_len <- NA_real_
        # Gene coords — prefer gene feature row, fall back to transcript span
        gene_start <- if (nrow(df_gene) > 0) suppressWarnings(min(as.numeric(df_gene$V4), na.rm = TRUE)) else tx_start
        gene_end   <- if (nrow(df_gene) > 0) suppressWarnings(max(as.numeric(df_gene$V5), na.rm = TRUE)) else tx_end
        if (!is.finite(gene_start)) gene_start <- tx_start
        if (!is.finite(gene_end))   gene_end   <- tx_end
        gene_coords <- if (is.finite(gene_start) && is.finite(gene_end)) {
            paste0(format_bp_short(gene_start), "  -  ", format_bp_short(gene_end))
        } else {
            "N/A"
        }
        gene_len <- if (is.finite(gene_start) && is.finite(gene_end)) {
            as.numeric(gene_end - gene_start + 1)
        } else {
            tx_len
        }
        if (!is.finite(gene_len) || gene_len <= 0) gene_len <- NA_real_

        comp_row <- NULL
        comp_blob <- if (exists("parse_sequence_composition_blob", mode = "function")) {
            tryCatch(parse_sequence_composition_blob(seq_blob), error = function(e) NULL)
        } else {
            NULL
        }
        seq_clean <- ""
        if (!is.null(comp_blob) && nzchar(as.character(comp_blob$composition %||% ""))) {
            comp_tbl <- tryCatch(extract_composition_percentages(comp_blob$composition), error = function(e) NULL)
            if (!is.null(comp_tbl) && nrow(comp_tbl) == 4) {
                comp_row <- comp_tbl
            }
        }
        if (is.null(comp_row)) {
            seq_clean <- extract_sequence_from_blob(seq_blob)
        }
        if (is.null(comp_row) && nzchar(seq_clean)) {
            comp_label <- tryCatch(calculate_sequence_composition(seq_clean)$composition, error = function(e) "")
            comp_tbl <- tryCatch(extract_composition_percentages(comp_label), error = function(e) NULL)
            if (!is.null(comp_tbl) && nrow(comp_tbl) == 4) {
                comp_row <- comp_tbl
            }
        }

        comp_ui <- if (!is.null(comp_row)) {
            tagList(
                span(class = "footer-label", "Sequence composition"),
                span(
                    class = "footer-composition-inline",
                    lapply(seq_len(nrow(comp_row)), function(i) {
                        b <- as.character(comp_row$base[i])
                        pct <- sprintf("%.2f%%", as.numeric(comp_row$pct[i]))
                        span(
                            class = "footer-base-item",
                            span(class = paste("footer-base-pill", paste0("base-", b)), b),
                            span(class = "footer-base-pct", pct)
                        )
                    })
                )
            )
        } else {
            tagList(
                span(class = "footer-label", "Sequence composition"),
                span(class = "footer-value", "N/A")
            )
        }

        use_full_sections <- isTRUE(is_canonical) && !isTRUE(is_canonical_copy)
        info_button <- build_plot_info_button_ui(
            plot_data = plot_data,
            metrics_payload = metrics_payload,
            is_canonical = is_canonical,
            is_canonical_copy = is_canonical_copy,
            gene_label = gene_label,
            organism_name = organism_name,
            button_class = "footer-info-btn"
        )
        info_item <- if (!is.null(info_button)) {
            div(
                class = "footer-item footer-item-info",
                info_button
            )
        } else {
            NULL
        }

        # Gene div → mode:'gene' (full 2-tab modal)
        # Canonical copy + regular isoforms → mode:'tx' (Structure/Exon Map/Sequence only)
        charts_mode <- if (isTRUE(is_canonical) && !isTRUE(is_canonical_copy)) "gene" else "tx"
        charts_variant <- if (identical(charts_mode, "gene")) "gene" else "transcript"
        charts_item_class <- if (isTRUE(use_full_sections)) {
            "footer-item footer-item-charts footer-item-primary-action"
        } else {
            "footer-item footer-item-charts"
        }
        charts_item <- if (!is.null(plot_id)) {
            div(
                class = charts_item_class,
                tags$button(
                    type = "button",
                    class = "footer-charts-btn",
                    title = if (charts_mode == "gene") "View gene charts" else "View transcript charts",
                    onclick = sprintf(
                        "Shiny.setInputValue('open_plot_charts',{id:'%s',context:'%s',mode:'%s',variant:'%s'},{priority:'event'})",
                        as.character(plot_id),
                        as.character(context),
                        charts_mode,
                        charts_variant
                    ),
                    tags$i(class = "fa fa-chart-pie", `aria-hidden` = "true"),
                    span("Charts")
                )
            )
        } else {
            NULL
        }

        # Expand transcripts button — shown on canonical card when gene has >1 transcript.
        # data-count = total_transcripts so JS label reads "N transcripts" (all inclusive,
        # including the canonical copy inserted into the expand group).
        isoform_count    <- as.integer(isoform_count %||% 0L)
        total_tx_display <- if (!is.null(total_transcripts) && is.finite(as.integer(total_transcripts))) {
            as.integer(total_transcripts)
        } else {
            isoform_count + 1L
        }
        # Canonical copies in the expand group must NOT show the expand button themselves
        expand_item <- if (!isTRUE(is_canonical_copy) && !is.null(tx_group_key) && nzchar(tx_group_key) && isoform_count > 0L) {
            div(
                class = "footer-item footer-item-isoform-toggle",
                tags$label(
                    class = "btn isoform-toggle-btn isoform-toggle-label",
                    style = "font-size:10.5px; color:#4B6072; background:none; border:none; padding:2px 0; cursor:pointer; display:inline-flex; align-items:center; gap:4px;",
                    tags$input(
                        type = "checkbox",
                        id = isoform_toggle_input_id(context, plot_id),
                        class = "isoform-toggle-checkbox",
                        `data-group` = tx_group_key,
                        `data-count` = as.character(total_tx_display),
                        `data-plot-id` = as.character(plot_id %||% ""),
                        checked = if (isTRUE(isoform_expanded)) "checked" else NULL
                    ),
                    tags$span(class = "isoform-toggle-down", `aria-hidden` = "true", HTML("&#x25BC;")),
                    tags$span(class = "isoform-toggle-up", `aria-hidden` = "true", HTML("&#x25B2;")),
                    tags$span(
                        id = paste0(isoform_toggle_input_id(context, plot_id), "_label"),
                        class = "isoform-toggle-text",
                        sprintf(
                            "%d transcript%s",
                            total_tx_display,
                            if (total_tx_display > 1L) "s" else ""
                        )
                    )
                )
            )
        } else {
            # Placeholder to keep footer items aligned across all cards
            div(class = "footer-item footer-item-isoform-toggle",
                style = "visibility:hidden; pointer-events:none;",
                tags$button(class = "btn isoform-toggle-btn",
                    style = "font-size:10.5px; padding:2px 0; display:inline-flex; align-items:center; gap:4px;",
                    HTML("&#x25BC; 0 transcripts")
                )
            )
        }

        # Length / coords labels differ for gene card vs transcript card
        tx_coords <- if (is.finite(tx_start) && is.finite(tx_end)) {
            paste0(format_bp_short(tx_start), "  -  ", format_bp_short(tx_end))
        } else {
            "N/A"
        }
        length_item <- if (isTRUE(is_canonical)) {
            div(
                class = "footer-item",
                span(class = "footer-label", "Gene length"),
                span(class = "footer-value", paste0(format_bp_short(gene_len), " bp"))
            )
        } else {
            div(
                class = "footer-item",
                span(class = "footer-label", "Transcript length"),
                span(class = "footer-value",
                    if (is.finite(tx_len)) paste0(format_bp_short(tx_len), " bp") else "N/A")
            )
        }
        tx_length_item <- if (isTRUE(is_canonical)) {
            div(
                class = "footer-item",
                span(class = "footer-label", "Transcript length"),
                span(class = "footer-value",
                    if (is.finite(tx_len)) paste0(format_bp_short(tx_len), " bp") else "N/A")
            )
        } else {
            NULL
        }
        coords_item <- if (isTRUE(is_canonical)) {
            div(
                class = "footer-item",
                span(class = "footer-label", "Gene coords"),
                span(class = "footer-value", gene_coords)
            )
        } else {
            div(
                class = "footer-item",
                span(class = "footer-label", "Transcript coords"),
                span(class = "footer-value", tx_coords)
            )
        }
        # Literature button: only on the main gene div (not on the canonical copy)
        papers_item <- if (isTRUE(is_canonical) && !isTRUE(is_canonical_copy) && nzchar(as.character(gene_label %||% ""))) {
            div(
                class = "footer-item footer-item-papers",
                tags$button(
                    type = "button",
                    class = "footer-papers-btn",
                    title = "Search related scientific literature",
                    `data-papers-gene` = as.character(gene_label %||% ""),
                    `data-papers-gene-synonyms` = as.character(gene_synonyms_str %||% ""),
                    `data-papers-organism` = as.character(organism_name %||% ""),
                    `data-papers-organism-aliases` = as.character(organism_aliases_str %||% ""),
                    tags$i(class = "fa fa-file-alt", `aria-hidden` = "true"),
                    span("Literature")
                )
            )
        } else {
            NULL
        }
        out_ui <- div(
            class = "footer-row",
            expand_item,
            length_item,
            tx_length_item,
            div(class = "footer-item footer-item-composition", comp_ui),
            coords_item,
            info_item,
            charts_item,
            papers_item
        )
        app_perf_mark(
            footer_perf,
            sprintf("done seq_len=%d", as.integer(nchar(seq_clean %||% ""))),
            "FOOTER"
        )
        out_ui
    }

    build_footer_cache_key <- function(id_local, context = "homo", title = "", org_info = NULL,
                                       gene_meta = NULL, genome_path = NULL,
                                       seq_blob = NULL, metrics_payload = NULL,
                                       plot_signature = "") {
        meta <- gene_meta %||% list()
        org <- org_info %||% list()
        metrics_size <- if (is.null(metrics_payload)) {
            0L
        } else {
            suppressWarnings(as.integer(utils::object.size(metrics_payload)))
        }
        if (!is.finite(metrics_size) || is.na(metrics_size)) metrics_size <- 0L
        paste(
            as.character(context %||% ""),
            as.character(id_local %||% ""),
            as.character(plot_signature %||% ""),
            as.character(title %||% ""),
            as.character(org$name %||% ""),
            as.character(meta$display_gene_name %||% meta$matched_gene_name %||% ""),
            as.character(meta$matched_gene_id %||% ""),
            as.character(meta$seqid %||% ""),
            as.character(meta$strand %||% ""),
            as.character(meta$gene_start_bp %||% ""),
            as.character(meta$gene_end_bp %||% ""),
            as.character(meta$tx_start_bp %||% ""),
            as.character(meta$tx_end_bp %||% ""),
            as.character(isTRUE(meta$is_canonical)),
            as.character(isTRUE(meta$is_canonical_copy)),
            as.character(meta$total_transcripts %||% ""),
            as.character(genome_path %||% ""),
            as.character(nchar(as.character(seq_blob %||% ""))),
            as.character(metrics_size),
            sep = "::"
        )
    }

    is_footer_sequence_deferred <- function() {
        raw <- tolower(trimws(as.character(Sys.getenv("APP_FOOTER_DEFER_SEQUENCE", "0") %||% "0")))
        !raw %in% c("", "0", "false", "no", "off")
    }

    should_suspend_hidden_ortho_outputs <- function() {
        raw <- tolower(trimws(as.character(Sys.getenv("APP_ORTHO_SUSPEND_HIDDEN", "1") %||% "1")))
        !raw %in% c("", "0", "false", "no", "off")
    }

    build_species_picker_content <- function(df_in) {
        if (is.null(df_in) || nrow(df_in) == 0) {
            return(character(0))
        }
        vapply(seq_len(nrow(df_in)), function(i) {
            label <- htmltools::htmlEscape(as.character(df_in$label[i] %||% df_in$species_id[i] %||% "Unknown"))
            sci <- htmltools::htmlEscape(as.character(df_in$organism[i] %||% "Unknown"))
            icon <- htmltools::htmlEscape(as.character(df_in$icon_url[i] %||% "/icons/DNA.ico"))
            sprintf(
                "<div class='species-option'><span class='species-icon-wrap'><img class='species-icon' src='%s' alt='icon'/></span><span class='species-text'><span class='species-label'>%s</span><span class='species-sci'><em>%s</em></span></span></div>",
                icon, label, sci
            )
        }, character(1))
    }

    make_plot_signature <- function(annotation_path, representative_name, transcript, chromosome, start_pos, end_pos) {
        paste(
            normalizePath(annotation_path %||% "", winslash = "/", mustWork = FALSE),
            tolower(normalize_display_id(representative_name)),
            tolower(normalize_display_id(transcript)),
            as.character(chromosome %||% "N/A"),
            as.character(start_pos %||% NA_real_),
            as.character(end_pos %||% NA_real_),
            sep = "||"
        )
    }

    get_preloaded_entry <- function(species_id) {
        reg <- preloadedRegistry()
        if (nrow(reg) == 0 || is.null(species_id) || !nzchar(as.character(species_id))) {
            return(NULL)
        }
        hit <- reg[as.character(reg$species_id) == as.character(species_id), , drop = FALSE]
        if (nrow(hit) == 0) {
            return(NULL)
        }
        hit[1, , drop = FALSE]
    }

    build_det_from_preloaded <- function(entry_row) {
        if (is.null(entry_row) || nrow(entry_row) == 0) {
            return(list(organism = NULL, taxid = NULL, source = "preloaded_catalog", input_source = "preloaded"))
        }
        list(
            organism = as.character(entry_row$organism[1] %||% entry_row$label[1] %||% NA_character_),
            taxid = suppressWarnings(as.integer(entry_row$taxid[1])),
            source = "preloaded_catalog",
            input_source = "preloaded",
            annotation_path = as.character(entry_row$annotation_path[1] %||% ""),
            genome_path = as.character(entry_row$genome_path[1] %||% ""),
            assembly_report_path = as.character(entry_row$assembly_report_path[1] %||% ""),
            icon_url = as.character(entry_row$icon_url[1] %||% "/icons/DNA.ico"),
            kingdom = as.character(entry_row$kingdom[1] %||% ""),
            species_id = as.character(entry_row$species_id[1] %||% ""),
            synonyms = as.character(entry_row$synonyms[1] %||% "")
        )
    }

    format_genome_source_line <- function(genome_path, source_text) {
        gp <- as.character(genome_path %||% "")
        mode_label <- if (is_twobit_file(gp)) "Genome 2bit" else "Genome FASTA"
        sprintf("%s: %s (%s)", mode_label, basename(gp), source_text)
    }

    describe_preloaded_entry <- function(entry_row) {
        if (is.null(entry_row) || nrow(entry_row) == 0) {
            return("No preloaded organism selected.")
        }
        ann <- as.character(entry_row$annotation_path[1] %||% "")
        gen <- as.character(entry_row$genome_path[1] %||% "")
        if (is.na(ann)) ann <- ""
        if (is.na(gen)) gen <- ""
        ann_txt <- if (nzchar(ann)) basename(ann) else "N/A"
        gen_txt <- if (nzchar(gen)) basename(gen) else "N/A"
        ann_mode <- as.character(entry_row$annotation_mode[1] %||% "plain")
        gen_mode <- as.character(entry_row$genome_mode[1] %||% ifelse(is_twobit_file(gen), "2bit", "fasta"))
        sprintf("Annotation (%s): %s\nGenome (%s): %s", ann_mode, ann_txt, gen_mode, gen_txt)
    }

    format_assembly_metric_value <- function(x) {
        txt <- trimws(as.character(x %||% ""))
        if (!nzchar(txt)) {
            return("")
        }
        if (grepl("^-?[0-9]+$", txt)) {
            num <- suppressWarnings(as.numeric(txt))
            if (is.finite(num)) {
                return(format(num, big.mark = ",", scientific = FALSE, trim = TRUE))
            }
        }
        txt
    }

    build_assembly_info_block_html <- function(entry_row) {
        if (is.null(entry_row) || nrow(entry_row) == 0) {
            return("")
        }
        report_path <- as.character(entry_row$assembly_report_path[1] %||% "")
        stats_path <- as.character(entry_row$assembly_stats_path[1] %||% "")
        bundle <- get_assembly_info_bundle(report_path = report_path, stats_path = stats_path)
        meta <- bundle$meta
        metrics <- bundle$metrics
        if (!is.list(meta)) meta <- list()
        if (is.null(metrics) || !is.data.frame(metrics)) {
            metrics <- data.frame(statistic = character(0), value = character(0), stringsAsFactors = FALSE)
        }
        if (length(meta) == 0 && nrow(metrics) == 0) {
            return("")
        }

        esc <- function(x) htmltools::htmlEscape(as.character(x %||% ""))
        org_name <- as.character(entry_row$organism[1] %||% entry_row$label[1] %||% entry_row$species_id[1] %||% "Organism")
        meta_labels <- c(
            "assembly name" = "Assembly name",
            "description" = "Description",
            "organism name" = "Organism name",
            "taxid" = "Taxid",
            "biosample" = "BioSample",
            "bioproject" = "BioProject",
            "submitter" = "Submitter",
            "date" = "Date",
            "synonyms" = "Synonyms",
            "assembly type" = "Assembly type",
            "release type" = "Release type",
            "assembly level" = "Assembly level",
            "genome representation" = "Genome representation",
            "refseq category" = "RefSeq category",
            "genbank assembly accession" = "GenBank assembly accession",
            "refseq assembly accession" = "RefSeq assembly accession",
            "refseq assembly and genbank assemblies identical" = "RefSeq and GenBank identical"
        )

        meta_items <- character(0)
        for (k in names(meta_labels)) {
            val <- trimws(as.character(meta[[k]] %||% ""))
            if (!nzchar(val)) next
            meta_items <- c(
                meta_items,
                sprintf(
                    "<li><span class='assembly-tip-key'>%s:</span> <span class='assembly-tip-value'>%s</span></li>",
                    esc(meta_labels[[k]]),
                    esc(val)
                )
            )
        }

        metric_items <- character(0)
        if (nrow(metrics) > 0) {
            for (i in seq_len(nrow(metrics))) {
                stat <- trimws(as.character(metrics$statistic[i] %||% ""))
                val <- format_assembly_metric_value(metrics$value[i] %||% "")
                if (!nzchar(stat) || !nzchar(val)) next
                metric_items <- c(
                    metric_items,
                    sprintf(
                        "<li><span class='assembly-tip-key'>%s:</span> <span class='assembly-tip-value'>%s</span></li>",
                        esc(stat),
                        esc(val)
                    )
                )
            }
        }

        parts <- c(sprintf("<div class='assembly-tip-organism'>%s</div>", esc(org_name)))
        if (length(meta_items) > 0) {
            parts <- c(
                parts,
                sprintf("<div class='assembly-tip-section'>%s</div>", esc(as_text_one("Assembly info"))),
                sprintf("<ul class='assembly-tip-list'>%s</ul>", paste(meta_items, collapse = ""))
            )
        }
        if (length(metric_items) > 0) {
            parts <- c(
                parts,
                sprintf("<div class='assembly-tip-section'>%s</div>", esc(as_text_one("Statistics (unit: all)"))),
                sprintf("<ul class='assembly-tip-list'>%s</ul>", paste(metric_items, collapse = ""))
            )
        }
        sprintf("<div class='assembly-tip-block'>%s</div>", paste(parts, collapse = ""))
    }

    build_preloaded_info_icon_ui <- function(entries_df, panel_context = "homo") {
        if (is.null(entries_df) || nrow(entries_df) == 0) {
            return(NULL)
        }
        species_ids <- unique(as.character(entries_df$species_id %||% character(0)))
        species_ids <- species_ids[!is.na(species_ids) & nzchar(species_ids)]
        if (length(species_ids) == 0) {
            return(NULL)
        }
        subtitle_txt <- if (nrow(entries_df) == 1) {
            as.character(entries_df$organism[1] %||% entries_df$label[1] %||% entries_df$species_id[1] %||% as_text_one("Selected organism"))
        } else {
            sprintf("%d %s", as.integer(nrow(entries_df)), as_text_one("Selected organism(s)"))
        }
        tags$button(
            type = "button",
            class = "preloaded-info-btn",
            title = as_text_one("View assembly details"),
            `data-assembly-title` = as_text_one("Assembly details"),
            `data-assembly-context` = as.character(panel_context %||% "homo"),
            `data-assembly-species-ids` = paste(species_ids, collapse = "|"),
            `data-assembly-subtitle` = as.character(subtitle_txt %||% ""),
            icon("info-circle")
        )
    }

    strip_known_extensions <- function(x) {
        out <- as.character(x %||% "")
        if (!nzchar(out)) {
            return("")
        }
        repeat {
            prev <- out
            out <- sub("\\.(gz|bgz)$", "", out, ignore.case = TRUE)
            out <- sub("\\.(gff3?|gtf|txt|fa|fasta|fna|2bit)$", "", out, ignore.case = TRUE)
            if (identical(prev, out)) break
        }
        out
    }

    tokenize_upload_filename <- function(x) {
        stop_tokens <- c(
            "genome", "annotation", "annot", "gff", "gff3", "gtf", "txt",
            "fa", "fasta", "fna", "dna", "toplevel", "top", "level",
            "chromosome", "chr", "scaffold", "assembly", "asm", "genomic"
        )
        stem <- tolower(strip_known_extensions(basename(as.character(x %||% ""))))
        stem <- gsub("[^a-z0-9]+", " ", stem)
        toks <- trimws(unlist(strsplit(stem, "\\s+")))
        toks <- toks[nzchar(toks)]
        toks <- setdiff(toks, stop_tokens)
        unique(toks)
    }

    get_annotation_seqids_for_match <- function(annotation_path) {
        p <- as.character(annotation_path %||% "")
        if (!nzchar(p) || !file.exists(p)) {
            return(character(0))
        }

        ids <- tryCatch(
            {
                cmap <- get_chromosome_length_map(p)
                names(cmap$raw %||% numeric(0))
            },
            error = function(e) character(0)
        )

        if (length(ids) == 0) {
            ids <- tryCatch(
                {
                    idx <- build_gff_gene_light_index(p)
                    unique(as.character(idx$genes_df$seqid %||% character(0)))
                },
                error = function(e) character(0)
            )
        }

        out <- unique(normalize_chr_id(ids))
        out[nzchar(out)]
    }

    get_genome_seqids_for_match <- function(genome_path) {
        p <- as.character(genome_path %||% "")
        if (!nzchar(p) || !file.exists(p)) {
            return(character(0))
        }

        ids <- if (is_twobit_file(p)) {
            tryCatch(get_twobit_seqnames(p), error = function(e) character(0))
        } else {
            tryCatch(names(get_fasta_header_map(p)$seqname_to_header), error = function(e) character(0))
        }

        out <- unique(normalize_chr_id(ids))
        out[nzchar(out)]
    }

    assign_uploaded_genomes_to_annotations <- function(annotation_paths, annotation_names, genome_paths, genome_names) {
        ann_paths <- as.character(annotation_paths %||% character(0))
        ann_names <- as.character(annotation_names %||% basename(ann_paths))
        gen_paths <- as.character(genome_paths %||% character(0))
        gen_names <- as.character(genome_names %||% basename(gen_paths))

        n_ann <- length(ann_paths)
        n_gen <- length(gen_paths)
        if (n_ann == 0) {
            return(list(ok = FALSE, message = "No annotation files provided.", status_lines = character(0)))
        }
        if (n_gen == 0) {
            return(list(ok = FALSE, message = "No genome files provided.", status_lines = character(0)))
        }
        if (n_ann != n_gen) {
            return(list(
                ok = FALSE,
                message = sprintf("Upload mode requires one genome per annotation file (%d annotations, %d genomes).", n_ann, n_gen),
                status_lines = character(0)
            ))
        }

        ann_seqids <- lapply(ann_paths, get_annotation_seqids_for_match)
        gen_seqids <- lapply(gen_paths, get_genome_seqids_for_match)
        ann_tokens <- lapply(ann_names, tokenize_upload_filename)
        gen_tokens <- lapply(gen_names, tokenize_upload_filename)

        score <- matrix(0, nrow = n_ann, ncol = n_gen)
        seq_overlap <- matrix(0L, nrow = n_ann, ncol = n_gen)
        token_overlap <- matrix(0L, nrow = n_ann, ncol = n_gen)
        exact_bonus <- matrix(0L, nrow = n_ann, ncol = n_gen)

        for (i in seq_len(n_ann)) {
            for (j in seq_len(n_gen)) {
                ov <- length(intersect(ann_seqids[[i]], gen_seqids[[j]]))
                cov <- if (length(ann_seqids[[i]]) > 0) ov / length(ann_seqids[[i]]) else 0
                tv <- length(intersect(ann_tokens[[i]], gen_tokens[[j]]))
                exact_name_bonus <- if (identical(
                    tolower(strip_known_extensions(basename(ann_names[i]))),
                    tolower(strip_known_extensions(basename(gen_names[j])))
                )) {
                    5
                } else {
                    0
                }

                seq_overlap[i, j] <- as.integer(ov)
                token_overlap[i, j] <- as.integer(tv)
                exact_bonus[i, j] <- as.integer(exact_name_bonus)
                score[i, j] <- (ov * 1000) + (cov * 100) + (tv * 25) + exact_name_bonus
            }
        }

        ann_remaining <- seq_len(n_ann)
        gen_remaining <- seq_len(n_gen)
        assigned_gen_idx <- rep(NA_integer_, n_ann)
        assigned_score <- rep(NA_real_, n_ann)
        assigned_ov <- rep(NA_integer_, n_ann)
        assigned_tv <- rep(NA_integer_, n_ann)
        assigned_exact <- rep(NA_integer_, n_ann)

        while (length(ann_remaining) > 0 && length(gen_remaining) > 0) {
            sub_s <- score[ann_remaining, gen_remaining, drop = FALSE]
            max_s <- suppressWarnings(max(sub_s, na.rm = TRUE))
            if (!is.finite(max_s) || max_s <= 0) break

            idx_all <- which(sub_s == max_s, arr.ind = TRUE)
            if (nrow(idx_all) > 1) {
                tie_ov <- seq_overlap[cbind(ann_remaining[idx_all[, 1]], gen_remaining[idx_all[, 2]])]
                tie_tv <- token_overlap[cbind(ann_remaining[idx_all[, 1]], gen_remaining[idx_all[, 2]])]
                ord <- order(-tie_ov, -tie_tv, ann_remaining[idx_all[, 1]], gen_remaining[idx_all[, 2]])
                idx_pick <- idx_all[ord[1], , drop = FALSE]
            } else {
                idx_pick <- idx_all
            }

            ai <- ann_remaining[idx_pick[1, 1]]
            gj <- gen_remaining[idx_pick[1, 2]]
            assigned_gen_idx[ai] <- gj
            assigned_score[ai] <- score[ai, gj]
            assigned_ov[ai] <- seq_overlap[ai, gj]
            assigned_tv[ai] <- token_overlap[ai, gj]
            assigned_exact[ai] <- exact_bonus[ai, gj]

            ann_remaining <- setdiff(ann_remaining, ai)
            gen_remaining <- setdiff(gen_remaining, gj)
        }

        if (length(ann_remaining) > 0) {
            for (k in seq_along(ann_remaining)) {
                ai <- ann_remaining[k]
                gj <- gen_remaining[k]
                assigned_gen_idx[ai] <- gj
                assigned_score[ai] <- score[ai, gj]
                assigned_ov[ai] <- seq_overlap[ai, gj]
                assigned_tv[ai] <- token_overlap[ai, gj]
                assigned_exact[ai] <- exact_bonus[ai, gj]
            }
        }

        if (any(is.na(assigned_gen_idx))) {
            return(list(ok = FALSE, message = "Could not build a complete annotation/genome mapping.", status_lines = character(0)))
        }

        assigned_method <- vapply(seq_len(n_ann), function(i) {
            ov_i <- as.integer(assigned_ov[i])
            ex_i <- as.integer(assigned_exact[i])
            tv_i <- as.integer(assigned_tv[i])
            if (is.na(ov_i)) ov_i <- 0L
            if (is.na(ex_i)) ex_i <- 0L
            if (is.na(tv_i)) tv_i <- 0L

            if (ov_i > 0L) {
                "seqid_overlap"
            } else if (ex_i > 0L) {
                "filename_exact"
            } else if (tv_i > 0L) {
                "filename_tokens"
            } else {
                "fallback_order"
            }
        }, character(1))

        ov_vec <- as.integer(assigned_ov)
        ex_vec <- as.integer(assigned_exact)
        tv_vec <- as.integer(assigned_tv)
        ov_vec[is.na(ov_vec)] <- 0L
        ex_vec[is.na(ex_vec)] <- 0L
        tv_vec[is.na(tv_vec)] <- 0L
        weak_idx <- which(ov_vec <= 0L & ex_vec <= 0L & tv_vec <= 0L)
        if (length(weak_idx) > 0) {
            weak_ann <- paste(ann_names[weak_idx], collapse = ", ")
            return(list(
                ok = FALSE,
                message = paste0(
                    "Could not confidently match some annotation/genome pairs: ",
                    weak_ann,
                    ". Upload genome files with matching seqids/chromosome names or clearer filenames."
                ),
                status_lines = character(0)
            ))
        }

        status_lines <- vapply(seq_len(n_ann), function(i) {
            sprintf(
                "Genome match: %s -> %s (%s; shared seqids=%d)",
                ann_names[i],
                gen_names[assigned_gen_idx[i]],
                assigned_method[i],
                as.integer(assigned_ov[i] %||% 0L)
            )
        }, character(1))

        list(
            ok = TRUE,
            message = "ok",
            genome_for_annotation = as.character(gen_paths[assigned_gen_idx]),
            mapping = data.frame(
                annotation = ann_names,
                genome = gen_names[assigned_gen_idx],
                method = assigned_method,
                shared_seqids = assigned_ov,
                score = assigned_score,
                stringsAsFactors = FALSE
            ),
            status_lines = status_lines
        )
    }

    get_ortho_upload_vectors <- function() {
        ann_paths <- as.character(input$files$datapath %||% character(0))
        ann_names <- as.character(input$files$name %||% basename(ann_paths))
        gen_paths <- as.character(input$genome_fasta_ortho$datapath %||% character(0))
        gen_names <- as.character(input$genome_fasta_ortho$name %||% basename(gen_paths))

        keep_ann <- nzchar(ann_paths) & file.exists(ann_paths)
        keep_gen <- nzchar(gen_paths) & file.exists(gen_paths)
        list(
            annotation_paths = ann_paths[keep_ann],
            annotation_names = ann_names[keep_ann],
            genome_paths = gen_paths[keep_gen],
            genome_names = gen_names[keep_gen]
        )
    }

    refresh_ortho_upload_source_label <- function() {
        if (!(as.character(input$ortho_data_mode %||% "") %in% c("upload", "mixed"))) {
            return(invisible(NULL))
        }
        up <- get_ortho_upload_vectors()
        n_ann <- length(up$annotation_paths)
        n_gen <- length(up$genome_paths)

        if (n_ann == 0 && n_gen == 0) {
            genomeSourceOrthologous("N/A")
        } else if (n_ann == 0) {
            genomeSourceOrthologous(sprintf("Uploaded genomes: %d (waiting annotation files)", n_gen))
        } else if (n_gen == 0) {
            genomeSourceOrthologous(sprintf("Uploaded genomes: 0/%d (required)", n_ann))
        } else if (n_ann != n_gen) {
            genomeSourceOrthologous(sprintf("Uploaded genomes: %d/%d (must match annotation count)", n_gen, n_ann))
        } else {
            genomeSourceOrthologous(sprintf("Uploaded genomes: %d/%d (ready)", n_gen, n_ann))
        }
        invisible(NULL)
    }

	    compute_transcript_span <- function(block_data) {
        if (is.null(block_data) || nrow(block_data) == 0) {
            return(c(start = NA_real_, end = NA_real_))
        }
        cached_meta <- attr(block_data, "cgev_transcript_meta", exact = TRUE)
        cached_span <- suppressWarnings(as.numeric((cached_meta %||% list())$span %||% numeric(0)))
        if (length(cached_span) >= 2L && all(is.finite(cached_span[1:2]))) {
            return(stats::setNames(cached_span[1:2], c("start", "end")))
        }
        row_types <- tolower(trimws(as.character(block_data$V3 %||% rep("", nrow(block_data)))))
        tx_level_types <- c(
            "mrna", "transcript", "lnc_rna", "trna", "rrna", "snorna", "snrna", "mirna",
            "ncrna", "primary_transcript", "pre_mirna", "guide_rna", "rnase_p_rna",
            "rnase_mrp_rna", "telomerase_rna", "antisense_rna", "srp_rna", "scarna",
            "vault_rna", "y_rna", "antisense_lncrna", "lncrna"
        )
        tx_idx <- which(row_types %in% tx_level_types)
        if (length(tx_idx) > 0) {
            source_df <- block_data[tx_idx, , drop = FALSE]
        } else {
            feat_idx <- which(row_types %in% c("exon", "cds", "start_codon", "stop_codon") | grepl("utr", row_types))
            if (length(feat_idx) == 0) feat_idx <- which(row_types == "gene")
            source_df <- if (length(feat_idx) > 0) block_data[feat_idx, , drop = FALSE] else block_data
        }
        starts <- suppressWarnings(as.numeric(source_df$V4))
        ends <- suppressWarnings(as.numeric(source_df$V5))
        start_val <- suppressWarnings(min(starts, na.rm = TRUE))
        end_val <- suppressWarnings(max(ends, na.rm = TRUE))
        if (!is.finite(start_val) || !is.finite(end_val)) {
            return(c(start = NA_real_, end = NA_real_))
        }
	        c(start = start_val, end = end_val)
	    }

	    transcript_span_length <- function(tx_span) {
	        start_val <- suppressWarnings(as.numeric((tx_span %||% c())[["start"]]))
	        end_val <- suppressWarnings(as.numeric((tx_span %||% c())[["end"]]))
	        if (!is.finite(start_val) || !is.finite(end_val)) {
	            return(NA_real_)
	        }
	        as.numeric(end_val - start_val + 1)
	    }

    normalize_sort_text <- function(x) {
        txt <- tolower(trimws(as.character(x %||% "")))
        txt[is.na(txt)] <- ""
        txt
    }

    extract_order_exon_lengths <- function(plot_data) {
        if (is.null(plot_data) || nrow(plot_data) == 0) {
            return(numeric(0))
        }
        processed <- tryCatch(process_gene_data(plot_data), error = function(e) NULL)
        df <- if (!is.null(processed) && !is.null(processed$df)) {
            as.data.frame(processed$df, stringsAsFactors = FALSE)
        } else {
            data.frame()
        }
        if (nrow(df) == 0) {
            return(numeric(0))
        }

        feature_vec <- tolower(trimws(as.character(df$feature_type %||% rep("", nrow(df)))))
        exon_df <- df[feature_vec == "exon", , drop = FALSE]
        if (nrow(exon_df) == 0) {
            exon_df <- df[feature_vec == "cds", , drop = FALSE]
        }
        if (nrow(exon_df) == 0) {
            return(numeric(0))
        }

        exon_df$xstart <- suppressWarnings(as.numeric(exon_df$xstart))
        exon_df$xend <- suppressWarnings(as.numeric(exon_df$xend))
        exon_df$largo <- suppressWarnings(as.numeric(exon_df$largo))
        exon_df <- exon_df[is.finite(exon_df$xstart) & is.finite(exon_df$xend), , drop = FALSE]
        if (nrow(exon_df) == 0) {
            return(numeric(0))
        }
        exon_df <- exon_df[order(exon_df$xstart, exon_df$xend), , drop = FALSE]

        len_vec <- as.numeric(exon_df$largo)
        bad_len <- !is.finite(len_vec) | len_vec <= 0
        if (any(bad_len)) {
            len_vec[bad_len] <- abs(exon_df$xend[bad_len] - exon_df$xstart[bad_len]) + 1
        }
        len_vec <- as.numeric(len_vec)
        len_vec[!is.finite(len_vec)] <- 0
        len_vec[len_vec < 0] <- 0
        len_vec
    }

    compare_exon_length_vectors <- function(a, b) {
        a <- suppressWarnings(as.numeric(a %||% numeric(0)))
        b <- suppressWarnings(as.numeric(b %||% numeric(0)))
        a <- a[is.finite(a) & a >= 0]
        b <- b[is.finite(b) & b >= 0]
        n_a <- length(a)
        n_b <- length(b)
        n_match <- min(n_a, n_b)

        diff_val <- 0
        if (n_match > 0) {
            diff_val <- diff_val + sum(abs(a[seq_len(n_match)] - b[seq_len(n_match)]), na.rm = TRUE)
        }
        if (n_a > n_match) {
            diff_val <- diff_val + sum(a[(n_match + 1):n_a], na.rm = TRUE)
        }
        if (n_b > n_match) {
            diff_val <- diff_val + sum(b[(n_match + 1):n_b], na.rm = TRUE)
        }
        as.numeric(diff_val)
    }

    compute_total_exon_difference_scores <- function(exon_lengths_list) {
        n <- length(exon_lengths_list)
        if (n == 0) {
            return(numeric(0))
        }
        if (n == 1) {
            return(0)
        }
        out <- numeric(n)
        for (i in seq_len(n)) {
            total_diff <- 0
            for (j in seq_len(n)) {
                if (identical(i, j)) next
                total_diff <- total_diff + compare_exon_length_vectors(exon_lengths_list[[i]], exon_lengths_list[[j]])
            }
            out[i] <- as.numeric(total_diff)
        }
        out
    }

    build_plot_sort_metrics <- function(ids, file_data_map, titles_map, organism_map = list()) {
        ids_chr <- as.character(ids %||% character(0))
        if (length(ids_chr) == 0) {
            return(data.frame(
                id = character(0),
                load_index = integer(0),
                organism = character(0),
                gene = character(0),
                transcript = character(0),
                chromosome = character(0),
                tx_length = numeric(0),
                exon_count = integer(0),
                exon_diff_total = numeric(0),
                stringsAsFactors = FALSE
            ))
        }

        out <- data.frame(
            id = ids_chr,
            load_index = seq_along(ids_chr),
            organism = rep("", length(ids_chr)),
            gene = rep("", length(ids_chr)),
            transcript = rep("", length(ids_chr)),
            chromosome = rep("", length(ids_chr)),
            tx_length = rep(NA_real_, length(ids_chr)),
            exon_count = rep(0L, length(ids_chr)),
            stringsAsFactors = FALSE
        )
        exon_lengths <- vector("list", length(ids_chr))

        for (i in seq_along(ids_chr)) {
            id_chr <- ids_chr[i]
            title_txt <- as.character(titles_map[[id_chr]] %||% "")
            org_info <- tryCatch(organism_map[[id_chr]], error = function(e) NULL)
            out$organism[i] <- trimws(as.character(org_info$name %||% ""))
            out$gene[i] <- trimws(as.character(extract_title_field(title_txt, "Gene") %||% ""))
            out$transcript[i] <- trimws(as.character(extract_title_field(title_txt, "Transcript") %||% ""))
            out$chromosome[i] <- trimws(as.character(extract_title_field(title_txt, "Chr") %||% ""))

            plot_data <- tryCatch(file_data_map[[id_chr]], error = function(e) NULL)
            if (!is.null(plot_data) && nrow(plot_data) > 0) {
                tx_span <- tryCatch(compute_transcript_span(plot_data), error = function(e) c(start = NA_real_, end = NA_real_))
                tx_start <- suppressWarnings(as.numeric(tx_span[["start"]]))
                tx_end <- suppressWarnings(as.numeric(tx_span[["end"]]))
                tx_len <- if (is.finite(tx_start) && is.finite(tx_end) && tx_end >= tx_start) {
                    as.numeric(tx_end - tx_start + 1)
                } else {
                    NA_real_
                }
                out$tx_length[i] <- tx_len

                if (!nzchar(out$chromosome[i])) {
                    out$chromosome[i] <- trimws(as.character(plot_data$V1[1] %||% ""))
                }

                if (!nzchar(out$transcript[i])) {
                    labels <- tryCatch(extract_plot_labels(plot_data), error = function(e) list(transcript = ""))
                    out$transcript[i] <- trimws(as.character(labels$transcript %||% ""))
                }
            }

            exon_len_vec <- extract_order_exon_lengths(plot_data)
            exon_lengths[[i]] <- exon_len_vec
            out$exon_count[i] <- as.integer(length(exon_len_vec))
        }

        out$exon_diff_total <- compute_total_exon_difference_scores(exon_lengths)
        out$organism_norm <- normalize_sort_text(out$organism)
        out$gene_norm <- normalize_sort_text(out$gene)
        out$transcript_norm <- normalize_sort_text(out$transcript)
        out$chromosome_norm <- normalize_sort_text(out$chromosome)
        out
    }

    sort_plot_ids <- function(ids, sort_mode = "load", file_data_map, titles_map, organism_map = list()) {
        ids_chr <- as.character(ids %||% character(0))
        if (length(ids_chr) <= 1) {
            return(ids_chr)
        }
        mode <- tolower(trimws(as.character(sort_mode %||% "load")))
        if (!nzchar(mode)) {
            mode <- "load"
        }
        # Fast path: default view keeps insertion order and should not trigger
        # expensive per-plot metric recomputation on every UI invalidation.
        if (identical(mode, "load")) {
            return(ids_chr)
        }

        metrics <- build_plot_sort_metrics(
            ids = ids_chr,
            file_data_map = file_data_map,
            titles_map = titles_map,
            organism_map = organism_map
        )
        if (nrow(metrics) == 0) {
            return(ids_chr)
        }

        num_desc <- function(x) {
            v <- suppressWarnings(as.numeric(x))
            v[!is.finite(v)] <- -Inf
            order(-v, metrics$load_index)
        }
        num_asc <- function(x) {
            v <- suppressWarnings(as.numeric(x))
            v[!is.finite(v)] <- Inf
            order(v, metrics$load_index)
        }
        txt_asc <- function(x) {
            v <- normalize_sort_text(x)
            v[!nzchar(v)] <- "~"
            order(xtfrm(v), metrics$load_index)
        }
        txt_desc <- function(x) {
            v <- normalize_sort_text(x)
            v[!nzchar(v)] <- ""
            order(-xtfrm(v), metrics$load_index)
        }

        ord <- switch(mode,
            "load" = order(metrics$load_index),
            "exondiff_desc" = num_desc(metrics$exon_diff_total),
            "exondiff_asc" = num_asc(metrics$exon_diff_total),
            "tx_len_desc" = num_desc(metrics$tx_length),
            "tx_len_asc" = num_asc(metrics$tx_length),
            "exon_desc" = num_desc(metrics$exon_count),
            "exon_asc" = num_asc(metrics$exon_count),
            "organism_asc" = txt_asc(metrics$organism_norm),
            "organism_desc" = txt_desc(metrics$organism_norm),
            "gene_asc" = txt_asc(metrics$gene_norm),
            "gene_desc" = txt_desc(metrics$gene_norm),
            "tx_asc" = txt_asc(metrics$transcript_norm),
            "tx_desc" = txt_desc(metrics$transcript_norm),
            "chr_asc" = txt_asc(metrics$chromosome_norm),
            "chr_desc" = txt_desc(metrics$chromosome_norm),
            order(metrics$load_index)
        )
        as.character(metrics$id[ord])
    }

    extract_title_field <- function(title_txt, field_name) {
        txt <- as.character(title_txt %||% "")
        if (length(txt) == 0 || !nzchar(txt)) {
            return(NA_character_)
        }
        pat <- sprintf("\\b%s\\s*:\\s*([^|]+)", stringr::str_replace_all(field_name, "([.^$|()\\[\\]{}*+?\\\\-])", "\\\\\\1"))
        m <- stringr::str_match(txt, pat)
        val <- trimws(as.character(m[1, 2] %||% NA_character_))
        if (length(val) == 0 || is.na(val) || !nzchar(val)) NA_character_ else val
    }

    sanitize_fasta_filename_token <- function(x, fallback = "transcript") {
        tok <- normalize_display_id(x %||% fallback)
        tok <- gsub("[^A-Za-z0-9._-]+", "_", tok)
        tok <- gsub("_+", "_", tok)
        tok <- gsub("^_+|_+$", "", tok)
        if (!nzchar(tok)) tok <- fallback
        tok
    }

    wrap_fasta_sequence <- function(seq_txt, width = 80L) {
        s <- toupper(gsub("[^ACGTN]", "", as.character(seq_txt %||% "")))
        if (!nzchar(s)) {
            return("")
        }
        w <- max(1L, as.integer(width))
        n <- nchar(s)
        starts <- seq.int(1L, n, by = w)
        ends <- pmin(starts + w - 1L, n)
        parts <- vapply(seq_along(starts), function(i) substr(s, starts[i], ends[i]), character(1))
        paste(parts, collapse = "\n")
    }

    build_transcript_fasta_content <- function(seq_blob, plot_data, title_txt, fallback_id = "transcript") {
        seq_clean <- extract_sequence_from_blob(seq_blob)

        tx_name <- extract_title_field(title_txt, "Transcript")
        if (is.na(tx_name) || !nzchar(tx_name)) {
            labels <- tryCatch(extract_plot_labels(plot_data), error = function(e) list(transcript = fallback_id))
            tx_name <- as.character(labels$transcript %||% fallback_id)
        }
        tx_name <- normalize_display_id(tx_name %||% fallback_id)
        if (!nzchar(tx_name)) tx_name <- fallback_id

        chr_name <- ""
        if (!is.null(plot_data) && nrow(plot_data) > 0) {
            chr_name <- as.character(plot_data$V1[1] %||% "")
        }
        tx_span <- tryCatch(compute_transcript_span(plot_data), error = function(e) c(start = NA_real_, end = NA_real_))
        tx_start <- suppressWarnings(as.numeric(tx_span[["start"]]))
        tx_end <- suppressWarnings(as.numeric(tx_span[["end"]]))

        header <- if (nzchar(chr_name) && is.finite(tx_start) && is.finite(tx_end)) {
            sprintf(">%s | chr=%s | start=%s | end=%s", tx_name, chr_name, as.integer(round(tx_start)), as.integer(round(tx_end)))
        } else {
            sprintf(">%s", tx_name)
        }
        seq_wrapped <- wrap_fasta_sequence(seq_clean, width = 80L)
        if (!nzchar(seq_wrapped)) {
            return(paste0(header, "\n"))
        }
        paste0(header, "\n", seq_wrapped)
    }

    build_gene_sequence_content <- function(genome_path, gene_name, chr_name, gene_start, gene_end, strand = "+") {
        gp        <- as.character(genome_path %||% "")
        gene_clean <- normalize_display_id(as.character(gene_name %||% "gene"))
        if (!nzchar(gene_clean)) gene_clean <- "gene"
        chr_clean  <- as.character(chr_name %||% "")
        g_start    <- suppressWarnings(as.numeric(gene_start))
        g_end      <- suppressWarnings(as.numeric(gene_end))

        header <- if (nzchar(chr_clean) && is.finite(g_start) && is.finite(g_end)) {
            sprintf(">%s | chr=%s | start=%s | end=%s",
                    gene_clean, chr_clean,
                    as.integer(round(g_start)), as.integer(round(g_end)))
        } else {
            sprintf(">%s", gene_clean)
        }

        if (!nzchar(gp) || !file.exists(gp) || !nzchar(chr_clean) ||
                !is.finite(g_start) || !is.finite(g_end)) {
            return(paste0(header, "\n"))
        }

        seq_txt <- tryCatch(
            extract_sequence_from_fasta(gp, chr_clean,
                                        as.integer(round(g_start)),
                                        as.integer(round(g_end))),
            error = function(e) ""
        )
        if (nzchar(seq_txt) && identical(as.character(strand %||% "+"), "-")) {
            seq_txt <- tryCatch(reverse_complement_dna(seq_txt), error = function(e) seq_txt)
        }
        seq_wrapped <- wrap_fasta_sequence(seq_txt, width = 80L)
        if (!nzchar(seq_wrapped)) return(paste0(header, "\n"))
        paste0(header, "\n", seq_wrapped)
    }

    build_locus_window_fasta_content <- function(locus_ctx, fallback_id = "locus", role_label = "") {
        ctx <- locus_ctx %||% list()
        org_txt <- trimws(as.character(ctx$organism_name %||% ""))
        gene_txt <- trimws(as.character(ctx$gene_label %||% ctx$matched_gene_id %||% ctx$title %||% fallback_id))
        seqid_txt <- trimws(as.character(ctx$seqid %||% ""))
        strand_txt <- trimws(as.character(ctx$strand %||% ""))
        if (!strand_txt %in% c("+", "-")) strand_txt <- ""
        start_i <- suppressWarnings(as.integer(ctx$window_start %||% NA_integer_))
        end_i <- suppressWarnings(as.integer(ctx$window_end %||% NA_integer_))

        header_id <- sanitize_fasta_filename_token(
            paste(c(org_txt, gene_txt, role_label), collapse = "_"),
            fallback = fallback_id
        )
        if (!nzchar(header_id)) {
            header_id <- fallback_id
        }

        meta_bits <- character()
        if (nzchar(org_txt)) meta_bits <- c(meta_bits, paste0("organism=", org_txt))
        if (nzchar(gene_txt)) meta_bits <- c(meta_bits, paste0("gene=", gene_txt))
        if (nzchar(role_label)) meta_bits <- c(meta_bits, paste0("role=", role_label))
        if (nzchar(seqid_txt)) meta_bits <- c(meta_bits, paste0("chr=", seqid_txt))
        if (is.finite(start_i)) meta_bits <- c(meta_bits, paste0("start=", start_i))
        if (is.finite(end_i)) meta_bits <- c(meta_bits, paste0("end=", end_i))
        if (nzchar(strand_txt)) meta_bits <- c(meta_bits, paste0("strand=", strand_txt))

        header <- if (length(meta_bits) > 0L) {
            paste0(">", header_id, " | ", paste(meta_bits, collapse = " | "))
        } else {
            paste0(">", header_id)
        }

        seq_txt <- extract_locus_window_sequence(ctx)
        seq_wrapped <- wrap_fasta_sequence(seq_txt, width = 80L)
        if (!nzchar(seq_wrapped)) {
            return(paste0(header, "\n"))
        }
        paste0(header, "\n", seq_wrapped)
    }

    build_sequence_blob_from_plot <- function(plot_data, title_txt = "", genome_path = NULL) {
        gp <- as.character(genome_path %||% "")
        if (!nzchar(gp) || !file.exists(gp) || is.null(plot_data) || nrow(plot_data) == 0) {
            return("")
        }

        processed <- tryCatch(process_gene_data(plot_data), error = function(e) NULL)
        if (is.null(processed) || is.null(processed$df)) {
            return("")
        }
        df_plot <- processed$df
        df_gene <- processed$df_gene
        df_transcript <- processed$df_transcript

        tx_span <- tryCatch(compute_transcript_span(plot_data), error = function(e) c(start = NA_real_, end = NA_real_))
        tx_start <- suppressWarnings(as.numeric(tx_span[["start"]]))
        tx_end <- suppressWarnings(as.numeric(tx_span[["end"]]))
        if (!is.finite(tx_start) || !is.finite(tx_end)) {
            return("")
        }

        tx_attr <- if (!is.null(df_transcript) && nrow(df_transcript) > 0) as.character(df_transcript$V9[1] %||% "") else ""
        tx_attrs <- parse_gff_attributes(tx_attr %||% "")
        gene_attr <- if (!is.null(df_gene) && nrow(df_gene) > 0) as.character(df_gene$V9[1] %||% "") else ""
        tx_label_candidates <- c(
            tx_attrs[["name"]][1],
            tx_attrs[["transcript"]][1],
            tx_attrs[["id"]][1],
            tx_attrs[["transcript_id"]][1],
            extract_title_field(title_txt, "Transcript"),
            extract_primary_gene_name(gene_attr),
            extract_primary_gene_id(gene_attr)
        )
        tx_label_candidates <- as.character(tx_label_candidates %||% character(0))
        tx_label_candidates <- tx_label_candidates[!is.na(tx_label_candidates) & nzchar(trimws(tx_label_candidates))]
        tx_label <- if (length(tx_label_candidates) > 0) tx_label_candidates[1] else "transcript"
        tx_label <- trimws(utils::URLdecode(tx_label))
        if (!nzchar(tx_label)) tx_label <- "transcript"

        tx_strand <- trimws(as.character(
            if (!is.null(df_transcript) && nrow(df_transcript) > 0) {
                df_transcript$V7[1]
            } else {
                (if (!is.null(df_gene) && nrow(df_gene) > 0) df_gene$V7[1] else plot_data$V7[1]) %||% "+"
            }
        ))
        if (!nzchar(tx_strand) || !tx_strand %in% c("+", "-")) tx_strand <- "+"

        exon_idx <- which(tolower(as.character(df_plot$feature_type %||% rep("", nrow(df_plot)))) == "exon")
        if (length(exon_idx) == 0) {
            exon_idx <- which(tolower(as.character(df_plot$feature_type %||% rep("", nrow(df_plot)))) == "cds")
        }
        exon_ranges <- if (length(exon_idx) > 0) {
            data.frame(
                start = suppressWarnings(as.numeric(df_plot$xstart[exon_idx])),
                end = suppressWarnings(as.numeric(df_plot$xend[exon_idx])),
                stringsAsFactors = FALSE
            )
        } else {
            NULL
        }

        chr_for_fetch <- as.character(
            (if (!is.null(df_gene) && nrow(df_gene) > 0) df_gene$V1[1] else NULL) %||%
                (if (!is.null(df_transcript) && nrow(df_transcript) > 0) df_transcript$V1[1] else NULL) %||%
                df_plot$seqid[1] %||%
                plot_data$V1[1] %||%
                ""
        )
        if (!nzchar(chr_for_fetch)) {
            return("")
        }

        seq_txt <- tryCatch(
            extract_spliced_exon_sequence(gp, chr_for_fetch, exon_ranges = exon_ranges, strand = tx_strand),
            error = function(e) ""
        )
        if (!nzchar(seq_txt)) {
            seq_txt <- tryCatch(
                extract_sequence_from_fasta(gp, chr_for_fetch, as.integer(round(tx_start)), as.integer(round(tx_end))),
                error = function(e) ""
            )
        }
        seq_txt <- toupper(gsub("[^ACGTN]", "", as.character(seq_txt %||% "")))
        if (!nzchar(seq_txt)) {
            return("")
        }

        header <- sprintf(
            ">%s | chr=%s | start=%s | end=%s",
            tx_label,
            chr_for_fetch,
            as.integer(round(tx_start)),
            as.integer(round(tx_end))
        )
        paste0(header, "\n", seq_txt)
    }

    clamp_promoter_bp <- function(x, min_bp = 100L, max_bp = 5000L, default_bp = 1000L) {
        n <- suppressWarnings(as.numeric(x))
        if (!is.finite(n)) n <- as.numeric(default_bp)
        n <- as.integer(round(n))
        n <- max(as.integer(min_bp), min(as.integer(max_bp), n))
        n
    }

    as_trimmed_chr <- function(x, fallback = "") {
        val <- trimws(as.character(x %||% fallback))
        if (!nzchar(val)) as.character(fallback) else val
    }

    as_numeric_or_na <- function(x) {
        val <- suppressWarnings(as.numeric(x))
        if (is.finite(val)) val else NA_real_
    }

    compute_promoter_window <- function(tx_start, tx_end, strand = "+", promoter_bp = 1000L, chr_len = NA_real_) {
        s <- as_numeric_or_na(tx_start)
        e <- as_numeric_or_na(tx_end)
        if (!is.finite(s) || !is.finite(e)) {
            return(list(start = NA_integer_, end = NA_integer_, requested_bp = as.integer(promoter_bp), actual_bp = 0L))
        }
        left <- min(s, e)
        right <- max(s, e)
        st <- as_trimmed_chr(strand, "+")
        if (!st %in% c("+", "-")) st <- "+"
        bp <- clamp_promoter_bp(promoter_bp)

        if (identical(st, "+")) {
            prom_end <- as.integer(round(left - 1))
            prom_start <- as.integer(round(prom_end - bp + 1))
        } else {
            prom_start <- as.integer(round(right + 1))
            prom_end <- as.integer(round(prom_start + bp - 1))
        }

        prom_start <- max(1L, prom_start)
        if (is.finite(chr_len) && chr_len > 0) {
            prom_end <- min(as.integer(round(chr_len)), prom_end)
        }
        if (!is.finite(prom_end) || prom_end < prom_start) {
            return(list(start = NA_integer_, end = NA_integer_, requested_bp = bp, actual_bp = 0L))
        }

        list(
            start = as.integer(prom_start),
            end = as.integer(prom_end),
            requested_bp = bp,
            actual_bp = as.integer(prom_end - prom_start + 1)
        )
    }

    build_promoter_fasta_payload <- function(meta, seq_txt, seqid, strand, prom_start, prom_end, requested_bp) {
        gene_txt <- normalize_display_id(meta$gene %||% "gene")
        tx_txt <- normalize_display_id(meta$transcript %||% meta$transcript_id %||% "transcript")
        org_txt <- normalize_display_id(meta$organism %||% "N/A")
        chr_txt <- normalize_display_id(seqid %||% meta$chromosome %||% "N/A")
        strand_txt <- as_trimmed_chr(strand, "+")
        if (!strand_txt %in% c("+", "-")) strand_txt <- "+"

        seq_wrapped <- wrap_fasta_sequence(seq_txt, width = 80L)
        header_id <- sanitize_fasta_filename_token(
            sprintf("%s_promoter_region_%dbp", gene_txt, as.integer(requested_bp)),
            fallback = "promoter_region"
        )
        header <- sprintf(
            ">%s | organism=%s | gene=%s | transcript=%s | chr=%s | strand=%s | promoter_start=%d | promoter_end=%d | length=%d",
            header_id,
            org_txt,
            gene_txt,
            tx_txt,
            chr_txt,
            strand_txt,
            as.integer(prom_start),
            as.integer(prom_end),
            as.integer(nchar(gsub("\\s+", "", seq_wrapped)))
        )
        file_base <- sanitize_fasta_filename_token(
            sprintf("%s_%s_promoter_region_%dbp", org_txt, gene_txt, as.integer(requested_bp)),
            fallback = "promoter_region"
        )
        list(
            filename = paste0(file_base, ".fasta"),
            content = paste0(header, "\n", seq_wrapped),
            gene = gene_txt,
            chr = chr_txt
        )
    }

    observeEvent(input$promoter_region_download_request,
        {
            payload <- input$promoter_region_download_request
            if (is.null(payload) || !is.list(payload)) {
                return(invisible(NULL))
            }

            pget <- function(name, fallback = "") as_trimmed_chr(payload[[name]], fallback = fallback)
            panel <- tolower(pget("panel", ""))
            plot_id <- pget("plot_id", "")
            seqid <- pget("seqid", "")
            if (!nzchar(seqid)) seqid <- pget("chromosome", "")
            strand <- pget("strand", "+")
            if (!strand %in% c("+", "-")) strand <- "+"

            tx_start <- as_numeric_or_na(payload[["tx_start"]])
            tx_end <- as_numeric_or_na(payload[["tx_end"]])
            promoter_bp <- clamp_promoter_bp(payload[["bp"]])

            if (!nzchar(plot_id) || !nzchar(seqid) || !is.finite(tx_start) || !is.finite(tx_end)) {
                emit_popup_status(
                    "Promoter region",
                    "Promoter region download failed: missing transcript coordinates or chromosome.",
                    tone = "warning",
                    clear = FALSE
                )
                return(invisible(NULL))
            }

            if (!panel %in% c("homologous", "orthologous")) {
                if (plot_id %in% names(genomePathsHomologous())) panel <- "homologous"
                if (plot_id %in% names(genomePathsOrthologous())) panel <- "orthologous"
            }

            genome_map <- if (identical(panel, "orthologous")) genomePathsOrthologous() else genomePathsHomologous()
            annotation_map <- if (identical(panel, "orthologous")) annotationPathsOrthologous() else annotationPathsHomologous()
            genome_path <- as.character(genome_map[[plot_id]] %||% "")
            annotation_path <- as.character(annotation_map[[plot_id]] %||% "")

            if (!nzchar(genome_path) || !file.exists(genome_path)) {
                emit_popup_status(
                    "Promoter region",
                    "Promoter region download failed: genome sequence file is not available for this plot.",
                    tone = "warning",
                    clear = FALSE
                )
                return(invisible(NULL))
            }

            chr_len <- suppressWarnings(as.numeric(get_chromosome_length_for_chr(annotation_path, seqid)))
            window <- compute_promoter_window(
                tx_start = tx_start,
                tx_end = tx_end,
                strand = strand,
                promoter_bp = promoter_bp,
                chr_len = chr_len
            )

            if (!is.finite(window$start) || !is.finite(window$end) || window$end < window$start) {
                emit_popup_status(
                    "Promoter region",
                    "Promoter region download failed: computed coordinates are outside chromosome bounds.",
                    tone = "warning",
                    clear = FALSE
                )
                return(invisible(NULL))
            }

            seq_txt <- extract_sequence_from_fasta(genome_path, seqid, window$start, window$end)
            if (!nzchar(seq_txt)) {
                alt_seqid <- pget("chromosome", "")
                if (nzchar(alt_seqid) && !identical(alt_seqid, seqid)) {
                    seq_txt <- extract_sequence_from_fasta(genome_path, alt_seqid, window$start, window$end)
                }
            }

            if (!nzchar(seq_txt)) {
                emit_popup_status(
                    "Promoter region",
                    sprintf("Promoter region download failed: unable to extract sequence for %s:%s-%s.", seqid, window$start, window$end),
                    tone = "warning",
                    clear = FALSE
                )
                return(invisible(NULL))
            }

            if (identical(strand, "-")) {
                seq_txt <- reverse_complement_dna(seq_txt)
            }

            payload_out <- build_promoter_fasta_payload(
                meta = payload,
                seq_txt = seq_txt,
                seqid = seqid,
                strand = strand,
                prom_start = window$start,
                prom_end = window$end,
                requested_bp = promoter_bp
            )
            session$sendCustomMessage("download_promoter_region_fasta", payload_out)

            emit_popup_status(
                "Promoter region",
                sprintf(
                    "Promoter region downloaded for gene '%s' (%s:%s-%s, %s strand).",
                    payload_out$gene,
                    payload_out$chr,
                    as.integer(window$start),
                    as.integer(window$end),
                    strand
                ),
                tone = "success",
                clear = FALSE
            )
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

    observeEvent(input$go_terms_request,
        {
            req_payload <- input$go_terms_request
            if (is.null(req_payload) || !is.list(req_payload)) {
                return(invisible(NULL))
            }
            perf_run_go <- app_perf_new_run("GO_LOCAL")

            pget <- function(name, fallback = "") trimws(as.character(req_payload[[name]] %||% fallback))
            request_id <- pget("request_id", "")
            plot_context <- pget("context", "")
            plot_id <- pget("plot_id", "")
            gene_hint <- tryCatch(normalize_display_id(pget("gene", "")), error = function(e) pget("gene", "N/A"))
            org_hint <- pget("organism", "")
            chr_hint <- pget("chromosome", "")
            app_perf_mark(
                perf_run_go,
                sprintf(
                    "request context=%s plot_id=%s gene=%s organism=%s",
                    as.character(plot_context %||% ""),
                    as.character(plot_id %||% ""),
                    as.character(gene_hint %||% ""),
                    as.character(org_hint %||% "")
                ),
                "GO_LOCAL"
            )

            send_response <- function(tone = "info",
                                      summary = "",
                                      sections = I(list()),
                                      empty_message = "",
                                      source_label = "",
                                      allow_online_fallback = FALSE,
                                      online_payload = list()) {
                subtitle_gene <- format_popup_label(gene_hint, "N/A")
                subtitle_org <- format_org_name(org_hint, "N/A")
                subtitle_chr <- format_popup_label(chr_hint, "N/A")
                send_go_popup_payload(list(
                    request_id = request_id,
                    title = "GO annotations",
                    subtitle = sprintf("Gene: %s | Organism: %s | Chr: %s", subtitle_gene, subtitle_org, subtitle_chr),
                    tone = as.character(tone %||% "info"),
                    summary = as.character(summary %||% ""),
                    sections = sections,
                    empty_message = as.character(empty_message %||% ""),
                    source = as.character(source_label %||% ""),
                    allow_online_fallback = isTRUE(allow_online_fallback),
                    online_payload = if (is.list(online_payload)) online_payload else list()
                ))
            }

            tryCatch(
                {
                    snap <- resolve_go_plot_snapshot(plot_context = plot_context, plot_id = plot_id)
                    if (is.null(snap) || is.null(snap$plot_data) || nrow(snap$plot_data) == 0) {
                        app_perf_mark(perf_run_go, "snapshot_missing", "GO_LOCAL")
                        send_response(
                            tone = "warning",
                            summary = "GO annotations are not available for this plot.",
                            sections = I(list()),
                            empty_message = "This plot is no longer available. Generate the visualization again and retry."
                        )
                        return(invisible(NULL))
                    }
                    app_perf_mark(
                        perf_run_go,
                        sprintf(
                            "snapshot_ok rows=%d annotation=%s",
                            as.integer(nrow(snap$plot_data)),
                            basename(as.character(snap$annotation_path %||% ""))
                        ),
                        "GO_LOCAL"
                    )

                    if (!nzchar(gene_hint) || identical(gene_hint, "N/A")) {
                        gene_hint <- trimws(as.character(extract_title_field(snap$title_txt, "Gene") %||% ""))
                    }
                    if (!nzchar(gene_hint) || identical(gene_hint, "N/A")) {
                        row_types <- tolower(trimws(as.character(snap$plot_data$V3 %||% rep("", nrow(snap$plot_data)))))
                        gidx <- which(row_types == "gene")[1]
                        if (is.finite(gidx)) {
                            attr <- as.character(snap$plot_data$V9[gidx] %||% "")
                            gene_hint <- normalize_display_id(extract_primary_gene_name(attr) %||% extract_primary_gene_id(attr) %||% "Gene")
                        }
                    }
                    if (!nzchar(org_hint)) org_hint <- as.character(snap$organism_name %||% "")
                    if (!nzchar(chr_hint)) chr_hint <- trimws(as.character(extract_title_field(snap$title_txt, "Chr") %||% ""))
                    if (!nzchar(plot_context)) plot_context <- as.character(snap$context %||% "")
                    online_payload_base <- list(
                        context = as.character(plot_context %||% ""),
                        plot_id = as.character(plot_id %||% ""),
                        gene = as.character(gene_hint %||% ""),
                        organism = as.character(org_hint %||% ""),
                        chromosome = as.character(chr_hint %||% ""),
                        annotation_path = as.character(snap$annotation_path %||% "")
                    )

                    go_entry <- resolve_go_registry_entry(
                        annotation_path = as.character(snap$annotation_path %||% ""),
                        organism_name = as.character(org_hint %||% "")
                    )
                    if (is.null(go_entry) || nrow(go_entry) == 0) {
                        app_perf_mark(perf_run_go, "registry_missing_retry_reload", "GO_LOCAL")
                        tryCatch(load_go_registry_cached(force = TRUE), error = function(e) data.frame())
                        go_entry <- resolve_go_registry_entry(
                            annotation_path = as.character(snap$annotation_path %||% ""),
                            organism_name = as.character(org_hint %||% "")
                        )
                    }
                    if (is.null(go_entry) || nrow(go_entry) == 0) {
                        app_perf_mark(perf_run_go, "registry_missing_after_reload", "GO_LOCAL")
                        send_response(
                            tone = "warning",
                            summary = "No GO source is configured for this organism.",
                            sections = I(list()),
                            empty_message = "This organism does not have a mapped GAF file in go_annotations/registry.tsv.",
                            allow_online_fallback = TRUE,
                            online_payload = online_payload_base
                        )
                        return(invisible(NULL))
                    }
                    app_perf_mark(
                        perf_run_go,
                        sprintf(
                            "registry_ok source=%s file=%s db=%s",
                            as.character(go_entry$source[1] %||% ""),
                            basename(as.character(go_entry$gaf_abs_path[1] %||% "")),
                            as.character(go_entry$db_namespace[1] %||% "")
                        ),
                        "GO_LOCAL"
                    )

                    candidates <- extract_go_candidates_from_plot_data(snap$plot_data, gene_label = gene_hint)
                    gene_hint_parts <- unique(trimws(unlist(strsplit(as.character(gene_hint %||% ""), "\\s*(?:->|→|,|;|/|\\||\\s+)\\s*", perl = TRUE), use.names = FALSE)))
                    gene_hint_parts <- gene_hint_parts[nzchar(gene_hint_parts) & nchar(gene_hint_parts) <= 60L & grepl("[A-Za-z]", gene_hint_parts)]
                    if (length(gene_hint_parts) > 0L) {
                        candidates$symbols <- unique(c(as.character(candidates$symbols %||% character(0)), gene_hint_parts))
                        candidates$object_ids <- unique(c(as.character(candidates$object_ids %||% character(0)), gene_hint_parts))
                    }
                    app_perf_mark(
                        perf_run_go,
                        sprintf(
                            "candidates object_ids=%d symbols=%d symbol_preview=%s",
                            length(as.character(candidates$object_ids %||% character(0))),
                            length(as.character(candidates$symbols %||% character(0))),
                            paste(head(as.character(candidates$symbols %||% character(0)), 6L), collapse = ",")
                        ),
                        "GO_LOCAL"
                    )
                    if (length(candidates$object_ids) == 0 && length(candidates$symbols) == 0) {
                        send_response(
                            tone = "warning",
                            summary = "No stable identifiers were found for this gene in the annotation block.",
                            sections = I(list()),
                            empty_message = "The GO query could not be built from the current GFF attributes.",
                            allow_online_fallback = TRUE,
                            online_payload = online_payload_base
                        )
                        return(invisible(NULL))
                    }

                    src_file <- as.character(go_entry$file_name[1] %||% basename(as.character(go_entry$gaf_abs_path[1] %||% "")))
                    src_label <- sprintf(
                        "%s (%s)",
                        format_popup_label(src_file, "GO source"),
                        format_popup_label(as.character(go_entry$source[1] %||% ""), "source")
                    )
                    query_cache_key <- if (requireNamespace("digest", quietly = TRUE)) {
                        digest::digest(
                            list(
                                as.character(go_entry$gaf_abs_path[1] %||% ""),
                                as.character(go_entry$index_fingerprint[1] %||% ""),
                                sort(as.character(candidates$object_ids %||% character(0))),
                                sort(tolower(as.character(candidates$symbols %||% character(0))))
                            ),
                            algo = "xxhash64"
                        )
                    } else {
                        paste(
                            as.character(go_entry$gaf_abs_path[1] %||% ""),
                            paste(sort(as.character(candidates$object_ids %||% character(0))), collapse = "|"),
                            paste(sort(tolower(as.character(candidates$symbols %||% character(0)))), collapse = "|"),
                            sep = "::"
                        )
                    }

                    finish_local_lookup <- function(worker_result) {
                        terms <- if (is.list(worker_result)) worker_result$terms else worker_result
                        if (!is.data.frame(terms)) terms <- data.frame()
                        cache_env_set(goQueryCache, query_cache_key, terms, max_size = 240L)
                        payload <- build_go_sections_payload(terms, per_aspect_limit = 25L)
                        if (is.null(payload$sections) || length(payload$sections) == 0 || as.integer(payload$total %||% 0L) <= 0L) {
                            send_response(
                                tone = "warning",
                                summary = sprintf("No GO terms matched for gene '%s'.", format_popup_label(gene_hint, "N/A")),
                                sections = I(list()),
                                empty_message = "Try another transcript or verify identifier compatibility for this organism.",
                                source_label = src_label,
                                allow_online_fallback = TRUE,
                                online_payload = online_payload_base
                            )
                        } else {
                            summary_txt <- sprintf(
                                "%d GO annotation%s matched for gene '%s'%s.",
                                as.integer(payload$total),
                                ifelse(as.integer(payload$total) == 1L, "", "s"),
                                format_popup_label(gene_hint, "N/A"),
                                ifelse(isTRUE(payload$truncated), " (initially showing 25 per aspect; use Show more)", "")
                            )
                            send_response(
                                tone = "success",
                                summary = summary_txt,
                                sections = payload$sections,
                                empty_message = "",
                                source_label = src_label
                            )
                        }

                        if (is.list(worker_result) && identical(worker_result$backend, "stream")) {
                            gaf_for_build <- as.character(worker_result$gaf_path %||% "")
                            build_key <- tryCatch(go_file_fingerprint(gaf_for_build), error = function(e) "")
                            if (nzchar(gaf_for_build) && nzchar(build_key) &&
                                !exists(build_key, envir = pendingGoIndexBuilds, inherits = FALSE)) {
                                assign(build_key, TRUE, envir = pendingGoIndexBuilds)
                                later::later(function() {
                                    target <- go_index_cache_path(gaf_for_build, base_dir = ".")
                                    if (requireNamespace("processx", quietly = TRUE)) {
                                        proc <- tryCatch(
                                            processx::process$new(
                                                command = file.path(R.home("bin"), "Rscript"),
                                                args = c(
                                                    "scripts/build_gaf_index.R",
                                                    "--root=.",
                                                    paste0("--gaf=", gaf_for_build),
                                                    paste0("--out=", target)
                                                ),
                                                wd = normalizePath(".", winslash = "/", mustWork = TRUE),
                                                stdout = "|",
                                                stderr = "|",
                                                cleanup_tree = FALSE
                                            ),
                                            error = function(e) e
                                        )
                                        if (inherits(proc, "error")) {
                                            rm(list = build_key, envir = pendingGoIndexBuilds)
                                            app_debug_log("[GO index] could not launch builder: ", conditionMessage(proc))
                                        } else {
                                            assign(build_key, proc, envir = pendingGoIndexBuilds)
                                            poll_build <- function() {
                                                active <- get0(build_key, envir = pendingGoIndexBuilds, inherits = FALSE, ifnotfound = NULL)
                                                if (is.null(active) || !inherits(active, "process")) return(invisible(NULL))
                                                if (isTRUE(active$is_alive())) {
                                                    later::later(poll_build, delay = 0.5)
                                                    return(invisible(NULL))
                                                }
                                                status <- active$get_exit_status()
                                                stderr_txt <- tryCatch(active$read_all_error(), error = function(e) "")
                                                rm(list = build_key, envir = pendingGoIndexBuilds)
                                                if (!identical(as.integer(status), 0L)) {
                                                    app_debug_log("[GO index] background build failed: ", stderr_txt)
                                                }
                                                invisible(NULL)
                                            }
                                            later::later(poll_build, delay = 0.5)
                                        }
                                    } else {
                                        promises::future_promise({
                                            build_go_gaf_index(gaf_for_build, target, force = FALSE)
                                        }, seed = TRUE) %...>% (function(value) {
                                            if (exists(build_key, envir = pendingGoIndexBuilds, inherits = FALSE)) {
                                                rm(list = build_key, envir = pendingGoIndexBuilds)
                                            }
                                            NULL
                                        }) %...!% (function(err) {
                                            if (exists(build_key, envir = pendingGoIndexBuilds, inherits = FALSE)) {
                                                rm(list = build_key, envir = pendingGoIndexBuilds)
                                            }
                                            app_debug_log("[GO index] background build failed: ", conditionMessage(err))
                                            NULL
                                        })
                                    }
                                }, delay = 0.2)
                            }
                        }
                        invisible(NULL)
                    }

                    cached_terms <- cache_env_get(goQueryCache, query_cache_key, default = NULL)
                    if (is.data.frame(cached_terms)) {
                        finish_local_lookup(list(terms = cached_terms, backend = "memory"))
                        return(invisible(NULL))
                    }

                    resolved_index <- resolve_go_index_path(
                        gaf_path = as.character(go_entry$gaf_abs_path[1] %||% ""),
                        configured_index = as.character(go_entry$index_abs_path[1] %||% ""),
                        expected_fingerprint = as.character(go_entry$index_fingerprint[1] %||% ""),
                        base_dir = "."
                    )
                    go_cache_candidate <- tryCatch(
                        go_index_cache_path(as.character(go_entry$gaf_abs_path[1] %||% ""), base_dir = "."),
                        error = function(e) ""
                    )
                    app_perf_mark(
                        perf_run_go,
                        sprintf(
                            "index_resolve path=%s available=%s candidate=%s exists=%s",
                            if (nzchar(resolved_index)) basename(resolved_index) else "none",
                            nzchar(resolved_index),
                            basename(go_cache_candidate),
                            nzchar(go_cache_candidate) && file.exists(go_cache_candidate)
                        ),
                        "GO_LOCAL"
                    )
                    if (nzchar(resolved_index)) {
                        index_started <- app_perf_now()
                        indexed_terms <- scan_gaf_indexed(
                            index_path = resolved_index,
                            db_namespace = as.character(go_entry$db_namespace[1] %||% ""),
                            candidate_object_ids = candidates$object_ids,
                            candidate_symbols = candidates$symbols
                        )
                        app_perf_mark_ms(perf_run_go, "sqlite_lookup_ms", app_perf_elapsed_ms(index_started), "GO_LOCAL")
                        app_perf_mark(perf_run_go, sprintf("terms_found=%d backend=sqlite", as.integer(nrow(indexed_terms))), "GO_LOCAL")
                        finish_local_lookup(list(
                            terms = indexed_terms,
                            backend = "sqlite",
                            index_path = resolved_index,
                            gaf_path = as.character(go_entry$gaf_abs_path[1] %||% "")
                        ))
                        return(invisible(NULL))
                    }

                    perf_run <- app_perf_new_run("GO_LOCAL")
                    worker_started <- app_perf_now()
                    promises::future_promise({
                        go_lookup_worker(go_entry, candidates, base_dir = ".")
                    }, seed = TRUE) %...>% (function(worker_result) {
                        app_perf_mark_ms(perf_run, "worker_total_ms", app_perf_elapsed_ms(worker_started), "GO_LOCAL")
                        finish_local_lookup(worker_result)
                        NULL
                    }) %...!% (function(err) {
                        send_response(
                            tone = "error",
                            summary = "An unexpected error occurred while searching local GO annotations.",
                            sections = I(list()),
                            empty_message = sprintf("Error: %s", conditionMessage(err)),
                            allow_online_fallback = TRUE,
                            online_payload = online_payload_base
                        )
                        NULL
                    })
                    return(invisible(NULL))
                },
                error = function(e) {
                    send_response(
                        tone = "error",
                        summary = "An unexpected error occurred while searching local GO annotations.",
                        sections = I(list()),
                        empty_message = sprintf("Error: %s", conditionMessage(e)),
                        allow_online_fallback = TRUE,
                        online_payload = list(
                            context = as.character(plot_context %||% ""),
                            plot_id = as.character(plot_id %||% ""),
                            gene = as.character(gene_hint %||% ""),
                            organism = as.character(org_hint %||% ""),
                            chromosome = as.character(chr_hint %||% "")
                        )
                    )
                }
            )
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

    observeEvent(input$go_terms_online_request,
        {
            req_payload <- input$go_terms_online_request
            if (is.null(req_payload) || !is.list(req_payload)) {
                return(invisible(NULL))
            }

            pget <- function(name, fallback = "") trimws(as.character(req_payload[[name]] %||% fallback))
            request_id <- pget("request_id", "")
            plot_context <- pget("context", "")
            plot_id <- pget("plot_id", "")
            gene_hint <- tryCatch(normalize_display_id(pget("gene", "")), error = function(e) pget("gene", "N/A"))
            org_hint <- pget("organism", "")
            chr_hint <- pget("chromosome", "")
            annotation_hint <- pget("annotation_path", "")

            build_response <- function(tone = "info",
                                      summary = "",
                                      sections = list(),
                                      empty_message = "",
                                      source_label = "",
                                      allow_online_fallback = FALSE,
                                      online_payload = list(),
                                      gene_value = gene_hint,
                                      organism_value = org_hint,
                                      chr_value = chr_hint) {
                list(
                    request_id = request_id,
                    title = "GO annotations",
                    subtitle = sprintf(
                        "Gene: %s | Organism: %s | Chr: %s",
                        format_popup_label(gene_value, "N/A"),
                        format_org_name(organism_value, "N/A"),
                        format_popup_label(chr_value, "N/A")
                    ),
                    tone = as.character(tone %||% "info"),
                    summary = as.character(summary %||% ""),
                    sections = sections,
                    empty_message = as.character(empty_message %||% ""),
                    source = as.character(source_label %||% ""),
                    allow_online_fallback = isTRUE(allow_online_fallback),
                    online_payload = if (is.list(online_payload)) online_payload else list()
                )
            }

            promises::future_promise({
                tryCatch({
                    snap <- resolve_go_plot_snapshot(plot_context = plot_context, plot_id = plot_id)
                    if (is.null(snap) || is.null(snap$plot_data) || nrow(snap$plot_data) == 0) {
                        return(build_response(
                            tone = "warning",
                            summary = "Online GO lookup could not start: plot context is no longer available.",
                            sections = list(),
                            empty_message = "Generate the visualization again and retry the online lookup."
                        ))
                    }

                    gene_local <- gene_hint
                    org_local <- org_hint
                    chr_local <- chr_hint
                    annotation_local <- annotation_hint
                    plot_context_local <- plot_context

                    if (!nzchar(gene_local) || identical(gene_local, "N/A")) {
                        gene_local <- trimws(as.character(extract_title_field(snap$title_txt, "Gene") %||% ""))
                    }
                    if (!nzchar(org_local)) org_local <- as.character(snap$organism_name %||% "")
                    if (!nzchar(chr_local)) chr_local <- trimws(as.character(extract_title_field(snap$title_txt, "Chr") %||% ""))
                    if (!nzchar(annotation_local)) annotation_local <- as.character(snap$annotation_path %||% "")
                    if (!nzchar(plot_context_local)) plot_context_local <- as.character(snap$context %||% "")

                    online_payload_base <- list(
                        context = as.character(plot_context_local %||% ""),
                        plot_id = as.character(plot_id %||% ""),
                        gene = as.character(gene_local %||% ""),
                        organism = as.character(org_local %||% ""),
                        chromosome = as.character(chr_local %||% ""),
                        annotation_path = as.character(annotation_local %||% "")
                    )

                    candidates <- extract_go_candidates_from_plot_data(snap$plot_data, gene_label = gene_local)
                    if (length(candidates$object_ids) == 0 && length(candidates$symbols) == 0) {
                        return(build_response(
                            tone = "warning",
                            summary = "Online GO lookup could not build a valid query from this annotation block.",
                            sections = list(),
                            empty_message = "Try another transcript/gene or verify the gene identifiers in the source annotation.",
                            allow_online_fallback = TRUE,
                            online_payload = online_payload_base,
                            gene_value = gene_local,
                            organism_value = org_local,
                            chr_value = chr_local
                        ))
                    }

                    taxid <- resolve_taxid_for_go_lookup(annotation_path = annotation_local, organism_name = org_local)
                    terms_online <- fetch_online_go_terms_with_cache(
                        candidates = candidates,
                        gene_hint = gene_local,
                        organism_name = org_local,
                        taxid = taxid
                    )
                    payload <- build_go_sections_payload(terms_online, per_aspect_limit = 25L)
                    src_label <- if (is.finite(taxid) && !is.na(taxid) && taxid > 0) {
                        sprintf("MyGene.info online fallback (taxid %s)", as.integer(taxid))
                    } else {
                        "MyGene.info online fallback"
                    }

                    if (is.null(payload$sections) || length(payload$sections) == 0 || as.integer(payload$total %||% 0L) <= 0L) {
                        return(build_response(
                            tone = "warning",
                            summary = sprintf("No online GO annotations were found for gene '%s'.", format_popup_label(gene_local, "N/A")),
                            sections = list(),
                            empty_message = "No GO terms were returned by the online fallback for this organism/gene combination.",
                            source_label = src_label,
                            allow_online_fallback = TRUE,
                            online_payload = online_payload_base,
                            gene_value = gene_local,
                            organism_value = org_local,
                            chr_value = chr_local
                        ))
                    }

                    summary_txt <- sprintf(
                        "Online fallback returned %d GO annotation%s for gene '%s'%s.",
                        as.integer(payload$total),
                        ifelse(as.integer(payload$total) == 1L, "", "s"),
                        format_popup_label(gene_local, "N/A"),
                        ifelse(isTRUE(payload$truncated), " (initially showing 25 per aspect; use Show more)", "")
                    )
                    build_response(
                        tone = "success",
                        summary = summary_txt,
                        sections = payload$sections,
                        empty_message = "",
                        source_label = src_label,
                        allow_online_fallback = FALSE,
                        online_payload = list(),
                        gene_value = gene_local,
                        organism_value = org_local,
                        chr_value = chr_local
                    )
                }, error = function(e) {
                    build_response(
                        tone = "error",
                        summary = "An unexpected error occurred during the online GO lookup.",
                        sections = list(),
                        empty_message = sprintf("Error: %s", conditionMessage(e)),
                        allow_online_fallback = TRUE,
                        online_payload = list(
                            context = as.character(plot_context %||% ""),
                            plot_id = as.character(plot_id %||% ""),
                            gene = as.character(gene_hint %||% ""),
                            organism = as.character(org_hint %||% ""),
                            chromosome = as.character(chr_hint %||% ""),
                            annotation_path = as.character(annotation_hint %||% "")
                        )
                    )
                })
            }) %...>% (function(response_payload) {
                send_go_popup_payload(response_payload)
                NULL
            }) %...!% (function(e) {
                send_go_popup_payload(build_response(
                    tone = "error",
                    summary = "An unexpected error occurred during the online GO lookup.",
                    sections = list(),
                    empty_message = sprintf("Error: %s", conditionMessage(e)),
                    allow_online_fallback = TRUE,
                    online_payload = list(
                        context = as.character(plot_context %||% ""),
                        plot_id = as.character(plot_id %||% ""),
                        gene = as.character(gene_hint %||% ""),
                        organism = as.character(org_hint %||% ""),
                        chromosome = as.character(chr_hint %||% ""),
                        annotation_path = as.character(annotation_hint %||% "")
                    )
                ))
                NULL
            })
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

    # ── Papers search observer (Europe PMC) ──────────────────────────────────────
    observeEvent(input$papers_search_request,
        {
            req_payload <- input$papers_search_request
            if (is.null(req_payload) || !is.list(req_payload)) {
                return(invisible(NULL))
            }

            pget <- function(name, fallback = "") trimws(as.character(req_payload[[name]] %||% fallback))
            request_id <- pget("request_id", "")
            gene_str <- pget("gene", "")
            synonyms_str <- pget("gene_synonyms", "")
            organism_str <- pget("organism", "")
            aliases_str <- pget("organism_aliases", "")
            page <- max(1L, suppressWarnings(as.integer(pget("page", "1"))))
            page_size <- max(1L, min(25L, suppressWarnings(as.integer(pget("page_size", "10")))))
            sort_by <- pget("sort_by", "CITED desc")

            if (!is.finite(page)) page <- 1L
            if (!is.finite(page_size)) page_size <- 10L

            # Build gene names vector
            gene_names <- gene_str
            if (nzchar(synonyms_str)) {
                syns <- trimws(unlist(strsplit(synonyms_str, "\\|")))
                syns <- syns[nzchar(syns)]
                gene_names <- unique(c(gene_str, syns))
            }
            gene_names <- gene_names[nzchar(gene_names)]

            # Build organism aliases vector
            org_aliases <- character(0)
            if (nzchar(aliases_str)) {
                org_aliases <- trimws(unlist(strsplit(aliases_str, "\\|")))
                org_aliases <- org_aliases[nzchar(org_aliases)]
            }

            promises::future_promise({
                search_papers_epmc(
                    gene_names = gene_names,
                    organism_scientific = organism_str,
                    organism_aliases = org_aliases,
                    page = page,
                    page_size = page_size,
                    sort_by = sort_by
                )
            }) %...>% (function(result) {
                result$request_id <- request_id
                result$gene <- gene_str
                result$organism <- organism_str
                session$sendCustomMessage("papers_popup_data", result)
                NULL
            }) %...!% (function(e) {
                session$sendCustomMessage("papers_popup_data", list(
                    request_id = request_id,
                    hits = 0L,
                    page = page,
                    page_size = page_size,
                    total_pages = 0L,
                    papers = list(),
                    gene = gene_str,
                    organism = organism_str,
                    error = paste("Error:", conditionMessage(e))
                ))
                NULL
            })
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

    # ── Organism images (iNaturalist) ──────────────────────────────
    fetch_organism_images_inaturalist <- function(organism_name, aliases = character(0), max_photos = 9L) {
        organism_name <- trimws(as.character(organism_name %||% ""))
        if (!nzchar(organism_name)) {
            return(list(organism = organism_name, photos = list(), error = "No organism name provided."))
        }

        ua <- "ComparativeGeneViewer/1.0 (Shiny; contact@cgv.app)"

        # Helper: search iNaturalist taxa by query string
        search_taxa <- function(query, rank_filter = NULL) {
            params <- list(q = query, per_page = 3)
            if (!is.null(rank_filter)) params$rank <- rank_filter
            tryCatch({
                resp <- httr2::request("https://api.inaturalist.org/v1/taxa") |>
                    httr2::req_url_query(!!!params) |>
                    httr2::req_user_agent(ua) |>
                    httr2::req_timeout(15) |>
                    httr2::req_perform()
                httr2::resp_body_json(resp, simplifyVector = FALSE)
            }, error = function(e) NULL)
        }

        # Helper: strip subspecies/variety to genus + species
        simplify_to_species <- function(name) {
            # Remove ssp., subsp., var., f., cultivar indicators
            cleaned <- gsub("\\s+(ssp\\.?|subsp\\.?|var\\.?|f\\.?|cultivar)\\s+.*$", "", name, ignore.case = TRUE)
            # Also try just first two words (genus + species)
            words <- strsplit(trimws(cleaned), "\\s+")[[1]]
            if (length(words) >= 2) paste(words[1:2], collapse = " ") else cleaned
        }

        # Build search candidates in priority order
        search_candidates <- organism_name
        # Add simplified species name if different
        simplified <- simplify_to_species(organism_name)
        if (tolower(simplified) != tolower(organism_name)) {
            search_candidates <- c(search_candidates, simplified)
        }
        # Add aliases (common names like "human", "rice", "zebrafish")
        if (length(aliases) > 0) {
            aliases <- trimws(aliases[nzchar(trimws(aliases))])
            search_candidates <- c(search_candidates, aliases)
        }
        search_candidates <- unique(search_candidates)

        # Step 1: Try each candidate until we find a taxon with observations
        taxon <- NULL
        taxon_id <- NULL
        common_name <- ""
        matched_query <- ""

        for (candidate in search_candidates) {
            if (!nzchar(candidate)) next
            # Try with species rank first, then without rank filter
            for (rank_f in list("species", NULL)) {
                taxa_data <- search_taxa(candidate, rank_filter = rank_f)
                if (is.null(taxa_data)) next
                results <- taxa_data$results %||% list()
                for (res in results) {
                    # Prefer taxa with observations_count > 0
                    obs_count <- as.integer(res$observations_count %||% 0)
                    if (obs_count > 0) {
                        taxon <- res
                        taxon_id <- res$id
                        common_name <- as.character(res$preferred_common_name %||% "")
                        matched_query <- candidate
                        break
                    }
                }
                if (!is.null(taxon)) break
            }
            if (!is.null(taxon)) break
        }

        if (is.null(taxon)) {
            return(list(
                organism = organism_name,
                photos = list(),
                error = paste0("Organism '", organism_name, "' not found on iNaturalist. Tried: ",
                               paste(search_candidates, collapse = ", "))
            ))
        }

        # Step 2: Get research-grade observations with photos
        obs_data <- tryCatch({
            resp <- httr2::request("https://api.inaturalist.org/v1/observations") |>
                httr2::req_url_query(
                    taxon_id = taxon_id,
                    quality_grade = "research",
                    photos = "true",
                    per_page = max_photos,
                    order_by = "votes",
                    photo_licensed = "true"
                ) |>
                httr2::req_user_agent(ua) |>
                httr2::req_timeout(15) |>
                httr2::req_perform()
            httr2::resp_body_json(resp, simplifyVector = FALSE)
        }, error = function(e) NULL)

        # If no research-grade, try without quality filter
        if (is.null(obs_data) || length(obs_data$results %||% list()) == 0L) {
            obs_data <- tryCatch({
                resp <- httr2::request("https://api.inaturalist.org/v1/observations") |>
                    httr2::req_url_query(
                        taxon_id = taxon_id,
                        photos = "true",
                        per_page = max_photos,
                        order_by = "votes",
                        photo_licensed = "true"
                    ) |>
                    httr2::req_user_agent(ua) |>
                    httr2::req_timeout(15) |>
                    httr2::req_perform()
                httr2::resp_body_json(resp, simplifyVector = FALSE)
            }, error = function(e) NULL)
        }

        if (is.null(obs_data)) {
            return(list(organism = organism_name, photos = list(), error = "Could not fetch observations from iNaturalist."))
        }

        observations <- obs_data$results %||% list()

        photos <- list()
        seen_ids <- character(0)

        for (obs in observations) {
            obs_photos <- obs$photos %||% list()
            if (length(obs_photos) == 0L) next

            p <- obs_photos[[1]]
            photo_id <- as.character(p$id %||% "")
            if (photo_id %in% seen_ids) next
            seen_ids <- c(seen_ids, photo_id)

            raw_url <- as.character(p$url %||% "")
            if (!nzchar(raw_url)) next

            medium_url <- gsub("square", "medium", raw_url, fixed = TRUE)
            large_url <- gsub("square", "large", raw_url, fixed = TRUE)
            original_url <- gsub("square", "original", raw_url, fixed = TRUE)

            photos <- c(photos, list(list(
                url = raw_url,
                medium = medium_url,
                large = large_url,
                original = original_url,
                attribution = as.character(p$attribution %||% "Unknown"),
                license = toupper(as.character(p$license_code %||% "")),
                observation_url = paste0("https://www.inaturalist.org/observations/", as.character(obs$id %||% ""))
            )))

            if (length(photos) >= max_photos) break
        }

        list(
            organism = organism_name,
            common_name = common_name,
            matched_query = matched_query,
            taxon_id = taxon_id,
            photos = photos
        )
    }

    organism_images_cache <- reactiveVal(list())

    observeEvent(input$organism_images_request,
        {
            req_payload <- input$organism_images_request
            if (is.null(req_payload) || !is.list(req_payload)) return(invisible(NULL))

            organism_str <- trimws(as.character(req_payload$organism %||% ""))
            if (!nzchar(organism_str)) {
                session$sendCustomMessage("organism_images_data", list(error = "No organism name provided."))
                return(invisible(NULL))
            }

            # Parse aliases from pipe-delimited string
            aliases_str <- trimws(as.character(req_payload$aliases %||% ""))
            org_aliases <- character(0)
            if (nzchar(aliases_str)) {
                org_aliases <- trimws(unlist(strsplit(aliases_str, "\\|")))
                org_aliases <- org_aliases[nzchar(org_aliases)]
            }

            # Check cache
            cache <- organism_images_cache()
            if (!is.null(cache[[organism_str]])) {
                session$sendCustomMessage("organism_images_data", cache[[organism_str]])
                return(invisible(NULL))
            }

            promises::future_promise({
                fetch_organism_images_inaturalist(organism_str, aliases = org_aliases, max_photos = 9L)
            }) %...>% (function(result) {
                # Cache the result
                cur <- isolate(organism_images_cache())
                cur[[organism_str]] <- result
                organism_images_cache(cur)
                session$sendCustomMessage("organism_images_data", result)
                NULL
            }) %...!% (function(e) {
                session$sendCustomMessage("organism_images_data", list(
                    organism = organism_str,
                    photos = list(),
                    error = paste("Error:", conditionMessage(e))
                ))
                NULL
            })
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

    build_chr_schematic_ui <- function(block_data, annotation_path, gene_label = NULL) {
        if (is.null(block_data) || nrow(block_data) == 0 || is.null(annotation_path) || !nzchar(annotation_path)) {
            return(NULL)
        }

        row_types <- tolower(trimws(as.character(block_data$V3 %||% rep("", nrow(block_data)))))
        gene_rows <- block_data[row_types == "gene", , drop = FALSE]
        if (nrow(gene_rows) == 0) gene_rows <- block_data

        chr_id <- as.character(gene_rows$V1[1] %||% block_data$V1[1] %||% "")
        if (!nzchar(chr_id)) {
            return(NULL)
        }

        gene_start <- suppressWarnings(min(as.numeric(gene_rows$V4), na.rm = TRUE))
        gene_end <- suppressWarnings(max(as.numeric(gene_rows$V5), na.rm = TRUE))
        if (!is.finite(gene_start) || !is.finite(gene_end) || gene_end < gene_start) {
            tx_span <- compute_transcript_span(block_data)
            gene_start <- as.numeric(tx_span[["start"]])
            gene_end <- as.numeric(tx_span[["end"]])
        }
        if (!is.finite(gene_start) || !is.finite(gene_end)) {
            return(NULL)
        }

        chr_len <- suppressWarnings(as.numeric(get_chromosome_length_for_chr(annotation_path, chr_id)))
        if (!is.finite(chr_len) || chr_len <= 0) {
            return(NULL)
        }

        chr_map <- get_chromosome_length_map(annotation_path)
        map_lengths <- suppressWarnings(as.numeric(c(chr_map$raw, chr_map$norm)))
        map_lengths <- map_lengths[is.finite(map_lengths) & map_lengths > 0]
        chr_max_len <- if (length(map_lengths) > 0) max(map_lengths, na.rm = TRUE) else chr_len
        if (!is.finite(chr_max_len) || chr_max_len <= 0) chr_max_len <- chr_len

        gene_name_fallback <- "Gene"
        if (nrow(gene_rows) > 0) {
            gattr <- as.character(gene_rows$V9[1] %||% "")
            gname <- extract_primary_gene_name(gattr) %||% extract_primary_gene_id(gattr) %||% "Gene"
            gene_name_fallback <- normalize_display_id(gname)
        }
        gene_name_clean <- normalize_display_id(gene_label %||% gene_name_fallback)

        s <- max(0, min(1, (gene_start - 1) / chr_len))
        e <- max(s, min(1, gene_end / chr_len))
        min_schematic_width <- 88
        max_schematic_width <- 138
        chr_ratio <- max(0, min(1, chr_len / chr_max_len))
        schematic_width <- as.integer(round(min_schematic_width + (max_schematic_width - min_schematic_width) * chr_ratio))
        schematic_width <- max(min_schematic_width, min(max_schematic_width, schematic_width))
        marker_x <- schematic_width * s
        marker_w <- max(2, schematic_width * (e - s))
        if ((marker_x + marker_w) > (schematic_width - 1)) {
            marker_w <- max(2, (schematic_width - 1) - marker_x)
        }
        marker_x <- max(1, min(marker_x, schematic_width - 3))

        grad_id <- paste0(
            "chrGrad_",
            gsub(
                "[^A-Za-z0-9_]",
                "_",
                paste0(chr_id, "_", round(gene_start), "_", round(gene_end))
            )
        )

        div(
            title = gene_name_clean,
            style = "flex:0 0 auto; margin-left: 4px;",
            div(
                style = sprintf("position:relative; width:%dpx; height:16px;", schematic_width),
                tags$svg(
                    width = as.character(schematic_width),
                    height = "16",
                    viewBox = "0 0 138 16",
                    preserveAspectRatio = "none",
                    style = "display:block;",
                    tags$defs(
                        tags$linearGradient(
                            id = grad_id,
                            x1 = "0%",
                            y1 = "0%",
                            x2 = "0%",
                            y2 = "100%",
                            tags$stop(offset = "0%", `stop-color` = "#E9F1F7"),
                            tags$stop(offset = "100%", `stop-color` = "#D8E4EF")
                        )
                    ),
                    tags$path(
                        d = "M8,1 H58 C61,1 63,2.6 63,4 H75 C75,2.6 77,1 80,1 H130 C134,1 137,4 137,8 C137,12 134,15 130,15 H80 C77,15 75,13.4 75,12 H63 C63,13.4 61,15 58,15 H8 C4,15 1,12 1,8 C1,4 4,1 8,1 Z",
                        fill = sprintf("url(#%s)", grad_id),
                        stroke = "#7F96AB",
                        `stroke-width` = "1"
                    ),
                    tags$rect(
                        x = sprintf("%.3f", marker_x),
                        y = "2",
                        width = sprintf("%.3f", marker_w),
                        height = "12",
                        rx = "2",
                        ry = "2",
                        fill = "#EB5E5E",
                        stroke = "#B53F3F",
                        `stroke-width` = "1"
                    )
                )
            )
        )
    }

