    # CORE: SERVER LAUNCH INITIALIZATION
    # =========================================================================

    sortedPlotIdsHomologous <- reactive({
        ids <- activePlotIdsHomologous()
        sort_plot_ids(
            ids = ids,
            sort_mode = input$homo_sort_mode %||% "load",
            file_data_map = fileDataHomologous(),
            titles_map = titlesHomologous(),
            organism_map = organismInfoHomologous()
        )
    })

    sortedPlotIdsOrthologous <- reactive({
        ids <- activePlotIdsOrthologous()
        sort_plot_ids(
            ids = ids,
            sort_mode = input$ortho_sort_mode %||% "load",
            file_data_map = fileDataOrthologous(),
            titles_map = titlesOrthologous(),
            organism_map = organismInfoOrthologous()
        )
    })

    primaryPlotIdsHomologous <- reactive({
        ids <- as.character(sortedPlotIdsHomologous() %||% character(0))
        ids <- ids[nzchar(ids)]
        if (length(ids) == 0L) {
            return(character(0))
        }
        meta_map <- tryCatch(plotGeneMetaHomologous(), error = function(e) list())
        Filter(function(pid) {
            meta <- tryCatch(meta_map[[pid]], error = function(e) NULL)
            !identical(meta$is_canonical, FALSE)
        }, ids)
    })

    primaryPlotIdsOrthologous <- reactive({
        ids <- as.character(sortedPlotIdsOrthologous() %||% character(0))
        ids <- ids[nzchar(ids)]
        if (length(ids) == 0L) {
            return(character(0))
        }
        meta_map <- tryCatch(plotGeneMetaOrthologous(), error = function(e) list())
        Filter(function(pid) {
            meta <- tryCatch(meta_map[[pid]], error = function(e) NULL)
            !identical(meta$is_canonical, FALSE)
        }, ids)
    })

    homoMultiTranscriptGeneGroups <- reactive({
        ids <- as.character(sortedPlotIdsHomologous() %||% character(0))
        ids <- ids[nzchar(ids)]
        if (length(ids) == 0L) {
            return(list())
        }

        meta_map <- tryCatch(plotGeneMetaHomologous(), error = function(e) list())
        org_map <- tryCatch(organismInfoHomologous(), error = function(e) list())
        ann_map <- tryCatch(annotationPathsHomologous(), error = function(e) list())
        titles_map <- tryCatch(titlesHomologous(), error = function(e) list())

        norm_key_local <- function(x) tolower(trimws(as.character(x %||% "")))
        safe_label <- function(x, fallback = "") {
            out <- trimws(as.character(x %||% ""))
            if (!nzchar(out)) fallback else out
        }

        rows <- lapply(seq_along(ids), function(idx) {
            pid <- as.character(ids[[idx]])
            meta <- tryCatch(meta_map[[pid]], error = function(e) NULL)
            total_tx <- suppressWarnings(as.integer(meta$total_transcripts %||% 1L))
            if (!is.finite(total_tx) || total_tx <= 1L) {
                return(NULL)
            }
            ttl <- as.character(tryCatch(titles_map[[pid]], error = function(e) "") %||% "")
            org_info <- tryCatch(org_map[[pid]], error = function(e) NULL)
            org_name <- safe_label(org_info$name, "Organism")
            ann_key <- norm_key_local(tryCatch(ann_map[[pid]], error = function(e) ""))
            org_key <- if (nzchar(ann_key)) paste0("ann:", ann_key) else paste0("org:", norm_key_local(org_name))
            gene_label <- safe_label(
                meta$display_gene_name %||% meta$matched_gene_name %||% extract_title_field(ttl, "Gene"),
                "Gene"
            )
            gene_key <- canonical_gene_group_key(
                query_gene = as.character(meta$query_gene %||% ""),
                matched_gene_name = as.character(meta$display_gene_name %||% meta$matched_gene_name %||% gene_label),
                matched_gene_id = as.character(meta$matched_gene_id %||% ""),
                title_gene = gene_label
            )
            tx_label <- safe_label(extract_title_field(ttl, "Transcript"), paste0("Tx_", pid))
            data.frame(
                plot_id = pid,
                group_key = paste(org_key, gene_key, sep = "||"),
                gene_label = gene_label,
                org_label = org_name,
                tx_label = tx_label,
                load_idx = as.integer(idx),
                total_tx = as.integer(total_tx),
                stringsAsFactors = FALSE
            )
        })

        group_df <- do.call(rbind,  Filter(Negate(is.null), rows))
        if (is.null(group_df) || !is.data.frame(group_df) || nrow(group_df) == 0L) {
            return(list())
        }

        split_rows <- split(group_df, group_df$group_key)
        groups <- lapply(split_rows, function(df_group) {
            df_group <- df_group[order(df_group$load_idx), , drop = FALSE]
            ids_group <- unique(as.character(df_group$plot_id))
            if (length(ids_group) <= 1L) {
                return(NULL)
            }
            gene_label <- as.character(df_group$gene_label[1] %||% "Gene")
            org_label <- as.character(df_group$org_label[1] %||% "Organism")
            list(
                key = as.character(df_group$group_key[1] %||% ""),
                ids = ids_group,
                gene_label = gene_label,
                org_label = org_label,
                label = sprintf("%s | %s (%d transcripts)", gene_label, org_label, length(ids_group))
            )
        })
        groups <- Filter(Negate(is.null), groups)
        if (length(groups) == 0L) {
            return(list())
        }
        names(groups) <- vapply(groups, function(g) as.character(g$key %||% ""), character(1))
        groups
    })

    homoAlignedSelectedGroupKey <- reactive({
        groups <- homoMultiTranscriptGeneGroups()
        if (length(groups) == 0L) {
            return("")
        }
        selected <- trimws(as.character(input$homo_aligned_gene_group %||% ""))
        keys <- names(groups)
        if (nzchar(selected) && selected %in% keys) {
            selected
        } else {
            keys[[1L]]
        }
    })

    homoAlignedPlotIds <- reactive({
        groups <- homoMultiTranscriptGeneGroups()
        key <- homoAlignedSelectedGroupKey()
        if (!nzchar(key) || !key %in% names(groups)) {
            return(character(0))
        }
        as.character(groups[[key]]$ids %||% character(0))
    })

    output$homo_visual_mode_ui <- renderUI({
        groups <- homoMultiTranscriptGeneGroups()
        current <- tolower(trimws(as.character(input$homo_visual_mode %||% "compact")))
        choices <- c("Compact" = "compact", "Detailed" = "detailed")
        if (length(groups) > 0L) {
            choices <- c(choices, "Synteny" = "aligned")
        }
        if (!current %in% unname(choices)) {
            current <- "compact"
        }
        div(
            class = "viz-mode-wrap",
            htmltools::tagAppendAttributes(
                radioButtons(
                    inputId = "homo_visual_mode",
                    label = NULL,
                    choices = choices,
                    selected = current,
                    inline = TRUE
                ),
                class = "viz-mode-toggle"
            )
        )
    })
    outputOptions(output, "homo_visual_mode_ui", suspendWhenHidden = FALSE)

    summarize_gene_plot_progress <- function(ids, visible_n, chunk_size, gene_meta_map) {
        ids_chr <- as.character(ids %||% character(0))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        total_ids <- length(ids_chr)
        if (total_ids <= 0L) {
            return(list(total = 0L, visible = 0L, step = 0L, remaining = 0L))
        }

        visible_n <- suppressWarnings(as.integer(visible_n %||% 0L))
        if (!is.finite(visible_n)) visible_n <- 0L
        visible_n <- max(0L, min(total_ids, visible_n))

        chunk_size <- suppressWarnings(as.integer(chunk_size %||% 0L))
        if (!is.finite(chunk_size) || chunk_size < 0L) chunk_size <- 0L
        next_visible_n <- min(total_ids, visible_n + chunk_size)

        is_gene_card <- vapply(ids_chr, function(pid) {
            meta <- tryCatch(gene_meta_map[[pid]], error = function(e) NULL)
            !identical(meta$is_canonical, FALSE)
        }, logical(1))

        total_genes <- sum(is_gene_card)
        visible_genes <- if (visible_n > 0L) sum(is_gene_card[seq_len(visible_n)]) else 0L
        step_genes <- if (next_visible_n > visible_n) {
            sum(is_gene_card[seq.int(visible_n + 1L, next_visible_n)])
        } else {
            0L
        }
        remaining_genes <- max(0L, total_genes - visible_genes)

        list(
            total = as.integer(total_genes),
            visible = as.integer(visible_genes),
            step = as.integer(step_genes),
            remaining = as.integer(remaining_genes)
        )
    }

	    alignedRepresentativePlotIdsOrthologous <- reactive({
	        ids <- as.character(sortedPlotIdsOrthologous() %||% integer(0))
        if (length(ids) == 0L) {
            return(character(0))
        }
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (!identical(current_mode, "aligned")) {
            # Representative selection is only consumed by Alignment.  Keep the
            # hidden shell cheap; switching modes invalidates this reactive and
            # runs the exact same selection algorithm on demand.
            return(ids)
        }

        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
        ann_map <- tryCatch(annotationPathsOrthologous(), error = function(e) list())
        files_map <- tryCatch(fileDataOrthologous(), error = function(e) list())
        gene_meta_map <- tryCatch(plotGeneMetaOrthologous(), error = function(e) list())

        first_non_empty_local <- function(...) {
            vals <- unlist(list(...), use.names = FALSE)
            for (v in vals) {
                txt <- trimws(as.character(v %||% ""))
                if (!is.na(txt) && nzchar(txt)) {
                    return(txt)
                }
            }
            ""
        }
        norm_key_local <- function(x) {
            tolower(trimws(as.character(x %||% "")))
        }
        tx_types_local <- c(
            "mrna", "transcript", "ncrna", "rrna", "trna", "lncrna", "lnc_rna",
            "pseudogenic_transcript", "primary_transcript", "pre_mirna", "mirna",
            "snrna", "snorna", "guide_rna", "rnase_p_rna"
        )

        candidate_rows <- lapply(seq_along(ids), function(idx) {
            plot_id <- ids[[idx]]
            fd <- tryCatch(files_map[[plot_id]], error = function(e) NULL)
            if (is.null(fd) || !is.data.frame(fd) || nrow(fd) == 0L) {
                return(NULL)
            }

            ttl <- as.character(tryCatch(titles_map[[plot_id]], error = function(e) "") %||% "")
            meta <- tryCatch(gene_meta_map[[plot_id]], error = function(e) NULL)
            gene_key <- canonical_gene_group_key(
                query_gene = as.character(meta$query_gene %||% ""),
                matched_gene_name = as.character(meta$display_gene_name %||% meta$matched_gene_name %||% ""),
                matched_gene_id = as.character(meta$matched_gene_id %||% ""),
                title_gene = as.character(extract_title_field(ttl, "Gene") %||% "")
            )

            ann_key <- norm_key_local(tryCatch(ann_map[[plot_id]], error = function(e) ""))
            org_key <- if (nzchar(ann_key)) {
                paste0("ann:", ann_key)
            } else {
                paste0("org:", norm_key_local(tryCatch(org_map[[plot_id]]$name, error = function(e) "")))
            }

            types <- tolower(trimws(as.character(fd$V3 %||% rep("", nrow(fd)))))
            starts <- suppressWarnings(as.numeric(fd$V4))
            ends <- suppressWarnings(as.numeric(fd$V5))
            attrs <- as.character(fd$V9 %||% rep("", nrow(fd)))

            exon_n <- sum(types == "exon", na.rm = TRUE)
            if (!is.finite(exon_n) || exon_n <= 0L) {
                exon_n <- sum(types == "cds", na.rm = TRUE)
            }

            cds_ranges <- as_feature_ranges(fd[types == "cds", , drop = FALSE])
            cds_len <- feature_ranges_union_length(unique_feature_ranges(cds_ranges))
            if (!is.finite(cds_len)) cds_len <- NA_real_

            tx_rows <- which(types %in% tx_types_local)
            tx_len <- NA_real_
            tx_label <- trimws(as.character(extract_title_field(ttl, "Transcript") %||% ""))
            if (length(tx_rows) > 0L) {
                tx_idx <- tx_rows[1L]
                tx_len <- suppressWarnings(as.numeric(ends[tx_idx] - starts[tx_idx] + 1))
                parsed <- tryCatch(parse_gff_attributes(attrs[tx_idx]), error = function(e) list())
                tx_label <- first_non_empty_local(
                    tryCatch(pick_attr(parsed, c("transcript_id", "id", "name", "transcript")), error = function(e) ""),
                    tx_label
                )
            }
            if (!is.finite(tx_len) || tx_len <= 0L) {
                tx_span <- tryCatch(compute_transcript_span(fd), error = function(e) c(start = NA_real_, end = NA_real_))
                tx_len <- suppressWarnings(as.numeric(transcript_span_length(tx_span)))
            }
            if (!is.finite(tx_len)) tx_len <- NA_real_
            if (!nzchar(tx_label)) tx_label <- paste0("Tx_", plot_id)

            # NCBI canonical priority (1=best ... 6=fallback to heuristics)
            ncbi_priority <- 6L
            if (length(tx_rows) > 0L) {
                source_val <- tolower(trimws(as.character(fd$V2[tx_rows[1L]] %||% "")))
                tag_raw    <- parsed[["tag"]] %||% character(0)
                tag_vals   <- tryCatch(
                    tolower(trimws(unlist(strsplit(paste(tag_raw, collapse = ","), ",")))),
                    error = function(e) character(0)
                )
                is_nm_nr <- grepl("^(NM_|NR_)", tx_label, ignore.case = TRUE)
                if (any(tag_vals == "mane select")) {
                    ncbi_priority <- 1L
                } else if (any(tag_vals == "refseq select")) {
                    ncbi_priority <- 2L
                } else if (source_val == "bestrefseq" && is_nm_nr) {
                    ncbi_priority <- 3L
                } else if (source_val == "bestrefseq") {
                    ncbi_priority <- 4L
                } else if (is_nm_nr) {
                    ncbi_priority <- 5L
                }
            }

            data.frame(
                plot_id       = plot_id,
                group_key     = paste(org_key, gene_key, sep = "||"),
                load_idx      = as.integer(idx),
                is_canonical  = isTRUE(meta$is_canonical),
                is_canonical_copy = isTRUE(meta$is_canonical_copy),
                cds_len       = as.numeric(cds_len),
                tx_len        = as.numeric(tx_len),
                exon_n        = as.integer(exon_n),
                tx_label      = as.character(tx_label),
                ncbi_priority = ncbi_priority,
                stringsAsFactors = FALSE
            )
        })

        candidate_df <- do.call(rbind,  Filter(Negate(is.null), candidate_rows))
        if (is.null(candidate_df) || nrow(candidate_df) == 0L) {
            return(ids)
        }

        choose_one_id <- function(df_group) {
            if (is.null(df_group) || nrow(df_group) == 0L) return(NA_character_)
            canonical_group <- df_group[df_group$is_canonical & !df_group$is_canonical_copy, , drop = FALSE]
            if (nrow(canonical_group) > 0L) {
                df_group <- canonical_group
            }
            has_cds <- any(is.finite(df_group$cds_len) & df_group$cds_len > 0, na.rm = TRUE)
            ord <- if (has_cds) {
                order(
                    !df_group$is_canonical,
                    df_group$is_canonical_copy,
                    df_group$ncbi_priority,
                    -ifelse(is.finite(df_group$cds_len), df_group$cds_len, -Inf),
                    -ifelse(is.finite(df_group$tx_len),  df_group$tx_len,  -Inf),
                    -ifelse(is.finite(df_group$exon_n),  df_group$exon_n,  -Inf),
                    tolower(df_group$tx_label),
                    df_group$load_idx
                )
            } else {
                order(
                    !df_group$is_canonical,
                    df_group$is_canonical_copy,
                    df_group$ncbi_priority,
                    -ifelse(is.finite(df_group$tx_len),  df_group$tx_len,  -Inf),
                    -ifelse(is.finite(df_group$exon_n),  df_group$exon_n,  -Inf),
                    tolower(df_group$tx_label),
                    df_group$load_idx
                )
            }
            as.character(df_group$plot_id[ord[1L]] %||% NA_character_)
        }

	        selected_ids <- unlist(lapply(split(candidate_df, candidate_df$group_key), choose_one_id), use.names = FALSE)
	        selected_ids <- unique(as.character(selected_ids %||% character(0)))
	        selected_ids <- selected_ids[nzchar(selected_ids)]
	        selected_ids <- ids[ids %in% selected_ids]
	        if (length(ids) > 1L && length(selected_ids) <= 1L) {
	            ids
	        } else {
	            selected_ids
	        }
	    })

