	                    -ifelse(is.finite(df_group$exon_n),  df_group$exon_n,  -Inf),
	                    tolower(df_group$tx_label),
	                    df_group$load_idx
	                )
	            } else {
	                order(
	                    !df_group$is_canonical,
	                    df_group$is_canonical_copy,
	                    df_group$ncbi_priority,
	                    -ifelse(is.finite(df_group$tx_len),  df_group$tx_len,  -Inf),
	                    -ifelse(is.finite(df_group$exon_n),  df_group$exon_n,  -Inf),
	                    tolower(df_group$tx_label),
	                    df_group$load_idx
	                )
	            }
	            as.character(df_group$plot_id[ord[1L]] %||% NA_character_)
	        }

	        selected_ids <- unlist(lapply(split(candidate_df, candidate_df$group_key), choose_one_id), use.names = FALSE)
	        selected_ids <- unique(as.character(selected_ids %||% character(0)))
	        selected_ids <- selected_ids[nzchar(selected_ids)]
	        selected_ids <- ids[ids %in% selected_ids]
	        if (length(selected_ids) == 0L) {
	            ids[[1]]
	        } else {
	            selected_ids
	        }
	    })

	    infer_taxonomic_bucket_local <- function(org_name = "", kingdom = "") {
	        name_lc <- tolower(trimws(as.character(org_name %||% "")))
	        kingdom_lc <- tolower(trimws(as.character(kingdom %||% "")))
	        genus <- trimws(strsplit(name_lc, "\\s+")[[1]][1] %||% "")
	        if (!nzchar(genus)) {
	            return(kingdom_lc)
	        }
	        mammalia <- c("homo", "pan", "gorilla", "pongo", "macaca", "papio", "callithrix", "mus", "rattus", "canis", "felis", "equus", "bos", "sus", "oryctolagus", "cavia", "monodelphis", "ornithorhynchus", "mustela", "ailuropoda", "phocoena", "tursiops", "loxodonta")
	        aves <- c("gallus", "taeniopygia", "anas", "meleagris", "falco", "aptenodytes")
	        actinopterygii <- c("danio", "oryzias", "gadus", "takifugu", "tetraodon", "xiphophorus", "gasterosteus", "salmo", "oncorhynchus")
	        amphibia <- c("xenopus", "ambystoma")
	        reptilia <- c("anolis", "pelodiscus", "chelonia")
	        insecta <- c("drosophila", "anopheles", "aedes", "apis", "bombus", "bombyx", "tribolium")
	        nematoda <- c("caenorhabditis", "brugia")
	        ascomycota <- c("saccharomyces", "schizosaccharomyces", "neurospora", "aspergillus", "candida")
	        monocots <- c("oryza", "zea", "brachypodium", "sorghum", "triticum", "hordeum", "setaria")
	        eudicots <- c("arabidopsis", "solanum", "glycine", "medicago", "vitis", "populus", "manihot", "phaseolus")

	        if (genus %in% mammalia) return("mammalia")
	        if (genus %in% aves) return("aves")
	        if (genus %in% actinopterygii) return("actinopterygii")
	        if (genus %in% amphibia) return("amphibia")
	        if (genus %in% reptilia) return("reptilia")
	        if (genus %in% insecta) return("insecta")
	        if (genus %in% nematoda) return("nematoda")
	        if (genus %in% ascomycota) return("ascomycota")
	        if (genus %in% monocots) return("monocot")
	        if (genus %in% eudicots) return("eudicot")
	        if (kingdom_lc %in% c("animalia", "metazoa")) return("animalia")
	        if (kingdom_lc %in% c("plantae", "plants")) return("plantae")
	        if (kingdom_lc %in% c("fungi")) return("fungi")
	        kingdom_lc
	    }

	    build_taxonomy_proxy_local <- function(org_info = NULL) {
	        org_name <- trimws(as.character(tryCatch(org_info$name, error = function(e) "") %||% ""))
	        kingdom <- trimws(as.character(tryCatch(org_info$kingdom, error = function(e) "") %||% ""))
	        taxid <- suppressWarnings(as.integer(tryCatch(org_info$taxid, error = function(e) NA_integer_) %||% NA_integer_))
	        name_lc <- tolower(org_name)
	        toks <- strsplit(name_lc, "\\s+")[[1]]
	        toks <- toks[nzchar(toks)]
	        genus <- if (length(toks) >= 1L) toks[1] else ""
	        species_binom <- if (length(toks) >= 2L) paste(toks[1], toks[2]) else genus
	        list(
	            name = org_name,
	            kingdom = tolower(kingdom),
	            taxid = taxid,
	            genus = genus,
	            species = species_binom,
	            bucket = infer_taxonomic_bucket_local(org_name, kingdom)
	        )
	    }

	    taxonomy_proximity_score_local <- function(meta_a, meta_b) {
	        if (is.null(meta_a) || is.null(meta_b)) {
	            return(0)
	        }
	        score <- 0
	        taxid_a <- suppressWarnings(as.integer(meta_a$taxid %||% NA_integer_))
	        taxid_b <- suppressWarnings(as.integer(meta_b$taxid %||% NA_integer_))
	        if (is.finite(taxid_a) && is.finite(taxid_b) && !is.na(taxid_a) && !is.na(taxid_b) && taxid_a > 0L && taxid_b > 0L && identical(taxid_a, taxid_b)) {
	            score <- score + 30
	        }
	        if (nzchar(meta_a$species %||% "") && nzchar(meta_b$species %||% "") && identical(meta_a$species, meta_b$species)) {
	            score <- score + 24
	        } else if (nzchar(meta_a$genus %||% "") && nzchar(meta_b$genus %||% "") && identical(meta_a$genus, meta_b$genus)) {
	            score <- score + 16
	        }
	        if (nzchar(meta_a$bucket %||% "") && nzchar(meta_b$bucket %||% "") && identical(meta_a$bucket, meta_b$bucket)) {
	            score <- score + 10
	        }
	        if (nzchar(meta_a$kingdom %||% "") && nzchar(meta_b$kingdom %||% "") && identical(meta_a$kingdom, meta_b$kingdom)) {
	            score <- score + 4
	        }
	        score
	    }

	    scalar_chr_safe <- function(x, default = "") {
	        if (is.null(x) || length(x) == 0L) {
	            return(as.character(default))
	        }
	        x1 <- x[[1]]
	        if (is.null(x1) || (length(x1) == 1L && is.na(x1))) {
	            return(as.character(default))
	        }
	        out <- trimws(as.character(x1))
	        if (!length(out) || !nzchar(out)) as.character(default) else out
	    }

	    build_cached_aligned_track_payload <- function(id_chr) {
	        id_chr <- as.character(id_chr %||% "")
	        if (!nzchar(id_chr)) {
	            return(NULL)
	        }
	        df_raw <- tryCatch(fileDataOrthologous()[[id_chr]], error = function(e) NULL)
	        if (is.null(df_raw) || !is.data.frame(df_raw) || nrow(df_raw) == 0L) {
	            return(NULL)
	        }

	        titulo <- tryCatch(titlesOrthologous()[[id_chr]], error = function(e) "")
	        org_info <- tryCatch(organismInfoOrthologous()[[id_chr]], error = function(e) NULL)
	        org_name <- as.character(org_info$name %||% "")
	        ann_path <- as.character(tryCatch(annotationPathsOrthologous()[[id_chr]], error = function(e) "") %||% "")
	        genome_path <- as.character(tryCatch(genomePathsOrthologous()[[id_chr]], error = function(e) "") %||% "")
	        if (!nzchar(org_name)) {
	            org_name <- scalar_chr_safe(titulo, paste0("Org ", id_chr))
	        }

	        processed <- tryCatch(process_gene_data(df_raw), error = function(e) NULL)
	        df <- processed$df %||% NULL
	        df_gene <- processed$df_gene %||% NULL
	        if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
	            return(NULL)
	        }

	        finite_mask <- is.finite(suppressWarnings(as.numeric(df$xstart))) &
	            is.finite(suppressWarnings(as.numeric(df$xend)))
	        df <- df[finite_mask, , drop = FALSE]
	        if (nrow(df) == 0L) {
	            return(NULL)
	        }

	        feature_type_norm <- tolower(trimws(as.character(df$feature_type %||% rep("", nrow(df)))))
	        gene_attr <- if (!is.null(df_gene) && nrow(df_gene) > 0L && "V9" %in% colnames(df_gene)) {
	            scalar_chr_safe(df_gene$V9[1], "")
	        } else {
	            ""
	        }
	        gene_name <- scalar_chr_safe(tryCatch(extract_primary_gene_name(gene_attr), error = function(e) ""), "")
	        if (!nzchar(gene_name)) {
	            gene_name <- scalar_chr_safe(tryCatch(extract_primary_gene_id(gene_attr), error = function(e) ""), "")
	        }
	        if (!nzchar(gene_name) || identical(gene_name, "Gene")) {
	            m <- stringr::str_match(as.character(titulo %||% ""), "^\\s*Gene:\\s*([^|]+)")
	            gene_name <- scalar_chr_safe(m[1, 2], "Gene")
	        }

	        strand_val <- if (!is.null(df_gene) && nrow(df_gene) > 0L && "V7" %in% colnames(df_gene)) {
	            scalar_chr_safe(df_gene$V7[1], "")
	        } else if ("strand" %in% colnames(df)) {
	            scalar_chr_safe(df$strand[1], "")
	        } else {
	            "+"
	        }
	        if (!strand_val %in% c("+", "-")) {
	            strand_val <- "+"
	        }

	        exon_anchor_df <- df[feature_type_norm %in% c("exon", "cds"), , drop = FALSE]
	        if (nrow(exon_anchor_df) == 0L) {
	            exon_anchor_df <- df
	        }
	        cds_anchor_df <- df[feature_type_norm == "cds", , drop = FALSE]
	        rel_coords_exon <- compute_transcript_relative_coords(df, strand = strand_val, anchor_df = exon_anchor_df)
	        df$rel_start_exon <- rel_coords_exon$rel_start
	        df$rel_end_exon <- rel_coords_exon$rel_end
	        df$rel_start_cds <- df$rel_start_exon
	        df$rel_end_cds <- df$rel_end_exon
	        df$rel_start <- df$rel_start_exon
	        df$rel_end <- df$rel_end_exon
	        df$org_label <- rep(org_name, nrow(df))
	        df$strand_val <- rep(strand_val, nrow(df))
	        df$gene_name <- rep(gene_name, nrow(df))
	        df$annotation_path <- rep(ann_path, nrow(df))
	        df$genome_path <- rep(genome_path, nrow(df))
	        df$gc_label <- rep("N/A", nrow(df))
	        df$feature_uid <- paste0("aligned_", id_chr, "_", seq_len(nrow(df)))
	        df$plot_group <- ifelse(feature_type_norm == "gene", "gene",
	            ifelse(feature_type_norm == "exon", "exon",
	                ifelse(feature_type_norm == "cds", "cds",
	                    ifelse(grepl("utr", feature_type_norm), "utr",
	                        ifelse(feature_type_norm %in% c("start_codon", "stop_codon"), "codon", "other")
	                    )
	                )
	            )
	        )
	        esc_attr <- function(x) {
	            x <- as.character(x %||% "")
	            x <- gsub("&", "&amp;", x, fixed = TRUE)
	            x <- gsub("<", "&lt;", x, fixed = TRUE)
	            x <- gsub(">", "&gt;", x, fixed = TRUE)
	            x
	        }
	        df$tooltip_html_fast <- sprintf(
	            "<b><em>%s</em></b><br/><b>Type:</b> %s<br/><b>Chr:</b> %s<br/><b>Start:</b> %s<br/><b>End:</b> %s<br/><b>Strand:</b> %s<br/><b>Length:</b> %s bp<br/><b>GC:</b> %s",
	            esc_attr(df$org_label),
	            esc_attr(df$feature_raw),
	            esc_attr(df$seqid),
	            format(as.integer(round(suppressWarnings(as.numeric(df$xstart)))), big.mark = ","),
	            format(as.integer(round(suppressWarnings(as.numeric(df$xend)))), big.mark = ","),
	            esc_attr(df$strand),
	            format(as.integer(round(suppressWarnings(as.numeric(df$largo)))), big.mark = ","),
	            "N/A"
	        )

	        exon_df <- df[df$plot_group == "exon", , drop = FALSE]
	        if (nrow(exon_df) == 0L) {
	            exon_df <- df[df$plot_group == "cds", , drop = FALSE]
	        }
	        if (nrow(exon_df) > 0L) {
	            exon_df <- exon_df[order(exon_df$rel_start_exon), , drop = FALSE]
	        } else {
	            exon_df <- NULL
	        }

	        chr_title <- trimws(as.character(extract_title_field(titulo, "Chr") %||% ""))
	        chr_val <- scalar_chr_safe(df$seqid[1], "")
	        chr_val_short <- if (nzchar(chr_title)) {
	            chr_title
	        } else {
	            get_short_chromosome_name(chr_val, ann_path, use_report_map = TRUE)
	        }

	        list(
	            df = df,
	            exon_df = exon_df,
	            summary = list(
	                org_name = org_name,
	                gene_name = gene_name,
	                strand_val = strand_val,
	                n_exons = sum(df$feature_type == "exon", na.rm = TRUE),
	                n_cds = sum(df$feature_type == "cds", na.rm = TRUE),
	                n_utr = sum(grepl("utr", df$feature_type), na.rm = TRUE),
	                gene_len = suppressWarnings(max(df$xend, na.rm = TRUE) - min(df$xstart, na.rm = TRUE) + 1),
	                chr_val = chr_val,
	                chr_val_short = chr_val_short,
	                title = as.character(titulo %||% ""),
	                annotation_path = ann_path,
	                genome_path = genome_path
	            )
	        )
	    }

	    aligned_track_cache_key <- function(id_chr) {
	        id_chr <- as.character(id_chr %||% "")
	        sig_map <- tryCatch(plotSignaturesOrthologous(), error = function(e) list())
	        title_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        ann_map <- tryCatch(annotationPathsOrthologous(), error = function(e) list())
	        genome_map <- tryCatch(genomePathsOrthologous(), error = function(e) list())
	        paste(
	            id_chr,
	            as.character(sig_map[[id_chr]] %||% ""),
	            as.character(title_map[[id_chr]] %||% ""),
	            as.character(tryCatch(org_map[[id_chr]]$name, error = function(e) "") %||% ""),
	            as.character(ann_map[[id_chr]] %||% ""),
	            as.character(genome_map[[id_chr]] %||% ""),
	            sep = "::"
	        )
	    }

	    get_cached_aligned_track_payload <- function(id_chr) {
	        id_chr <- as.character(id_chr %||% "")
	        if (!nzchar(id_chr)) {
	            return(NULL)
	        }
	        cache_slot <- paste0("track::", id_chr)
	        cache_key <- aligned_track_cache_key(id_chr)
	        if (exists(cache_slot, envir = orthoAlignedTrackCache, inherits = FALSE)) {
	            cached <- get(cache_slot, envir = orthoAlignedTrackCache, inherits = FALSE)
	            if (is.list(cached) && identical(as.character(cached$key %||% ""), cache_key)) {
	                return(cached$payload %||% NULL)
	            }
	        }
	        payload <- build_cached_aligned_track_payload(id_chr)
	        assign(cache_slot, list(key = cache_key, payload = payload), envir = orthoAlignedTrackCache)
	        trim_cache_env(orthoAlignedTrackCache, max_size = 256L)
	        payload
	    }

	    autoAlignedOrderedPlotIdsOrthologous <- reactive({
		        ids_all <- as.character(sortedPlotIdsOrthologous() %||% character(0))
	        ids <- as.character(alignedRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids_all) > 1L && length(ids) <= 1L) {
	            ids <- ids_all
	        }
	        if (length(ids) <= 1L) {
	            return(ids)
	        }
	        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
	        if (!identical(current_mode, "aligned")) {
	            # Similarity-chain ordering extracts spliced sequences.  Never do
	            # that work for the hidden Alignment output while Compact is active.
	            return(ids)
	        }

	        order_mode <- tolower(trimws(as.character(input$ortho_aligned_track_order %||% "similarity_chain")))
	        if (!order_mode %in% c("similarity_chain", "load", "organism", "reverse", "manual")) {
	            order_mode <- "similarity_chain"
	        }
	        if (identical(order_mode, "manual")) {
	            order_mode <- "similarity_chain"
	        }
	        anchor_id <- trimws(as.character(input$ortho_aligned_anchor_track %||% ""))
	        if (!nzchar(anchor_id) || identical(anchor_id, "__auto__") || !anchor_id %in% ids) {
	            anchor_id <- ""
	        }
	        if (identical(order_mode, "load")) {
	            return(ids)
	        }
	        if (identical(order_mode, "reverse")) {
	            return(rev(ids))
	        }

	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        tax_meta <- lapply(ids, function(id_chr) build_taxonomy_proxy_local(tryCatch(org_map[[id_chr]], error = function(e) NULL)))
	        names(tax_meta) <- ids
	        if (identical(order_mode, "organism")) {
	            ord_tbl <- data.frame(
	                id = ids,
	                organism = vapply(ids, function(id_chr) {
	                    trimws(as.character(tryCatch(org_map[[id_chr]]$name, error = function(e) "") %||% ""))
	                }, character(1)),
	                title = vapply(ids, function(id_chr) {
	                    trimws(as.character(tryCatch(titles_map[[id_chr]], error = function(e) "") %||% ""))
	                }, character(1)),
	                load_rank = seq_along(ids),
	                stringsAsFactors = FALSE
	            )
	            ord <- with(ord_tbl, order(tolower(organism), tolower(title), load_rank, na.last = TRUE))
	            return(as.character(ord_tbl$id[ord]))
	        }

	        aligned_mode <- tolower(trimws(as.character(input$ortho_aligned_mode %||% "protein")))
	        if (!aligned_mode %in% c("protein", "cds", "exon")) aligned_mode <- "protein"

	        tx_tracks <- vector("list", length(ids))
	        names(tx_tracks) <- ids

	        for (i in seq_along(ids)) {
	            id_chr <- ids[[i]]
	            payload <- tryCatch(get_cached_aligned_track_payload(id_chr), error = function(e) NULL)
	            df <- payload$df %||% NULL
	            norm_track <- tryCatch(normalize_aligned_track_for_mode(df, mode = aligned_mode), error = function(e) NULL)
	            df_mode <- norm_track$track_df %||% NULL
	            dfve <- norm_track$anchor_df %||% NULL
	            if (is.null(df_mode) || !is.data.frame(df_mode) || nrow(df_mode) == 0L || is.null(dfve) || !is.data.frame(dfve) || nrow(dfve) == 0L) {
	                next
	            }
	            tx_tracks[[i]] <- list(df = df_mode, exon_df = dfve[order(dfve$rel_start), , drop = FALSE])
	        }

	        similarity_score <- function(idx_a, idx_b) {
	            track_a <- tx_tracks[[idx_a]]
	            track_b <- tx_tracks[[idx_b]]
	            if (is.null(track_a) || is.null(track_b) || is.null(track_a$df) || is.null(track_b$df) ||
	                is.null(track_a$exon_df) || is.null(track_b$exon_df) ||
	                nrow(track_a$exon_df) == 0L || nrow(track_b$exon_df) == 0L) {
	                return(NA_real_)
	            }
	            corr_key <- paste(
	                paste(track_a$exon_df$xstart, collapse = ","),
	                paste(track_a$exon_df$xend, collapse = ","),
	                paste(track_b$exon_df$xstart, collapse = ","),
	                paste(track_b$exon_df$xend, collapse = ","),
	                aligned_mode,
	                "dna_matrix_v2",
	                "order",
	                sep = "|"
	            )
	            corr <- if (exists(corr_key, envir = orthoHomologyCache, inherits = FALSE)) {
	                get(corr_key, envir = orthoHomologyCache, inherits = FALSE)
	            } else {
	                computed <- tryCatch(
	                    compute_protein_guided_correspondence(track_a$df, track_b$df, track_a$exon_df, track_b$exon_df, mode = aligned_mode),
	                    error = function(e) NULL
	                )
	                assign(corr_key, computed, envir = orthoHomologyCache)
	                trim_cache_env(orthoHomologyCache, max_size = 200L)
	                computed
	            }
	            if (!is.null(corr) && is.data.frame(corr) && nrow(corr) > 0L) {
	                score <- suppressWarnings(as.numeric(stats::median(corr$identity_pct, na.rm = TRUE)))
	                overall <- suppressWarnings(as.numeric(stats::median(corr$overall_pid, na.rm = TRUE)))
	                n_blocks <- nrow(corr)
	                exon_balance <- 100 - abs(nrow(track_a$exon_df) - nrow(track_b$exon_df)) * 4
	                out <- c(score, overall, exon_balance)
	                out <- out[is.finite(out)]
	                if (length(out) > 0L) {
	                    return(mean(out) + min(n_blocks, 10L) * 0.25 + taxonomy_proximity_score_local(tax_meta[[idx_a]], tax_meta[[idx_b]]))
	                }
	            }
	            exon_a <- nrow(track_a$exon_df)
	            exon_b <- nrow(track_b$exon_df)
	            tax_bonus <- taxonomy_proximity_score_local(tax_meta[[idx_a]], tax_meta[[idx_b]])
	            if (is.finite(exon_a) && is.finite(exon_b)) {
	                return(100 - abs(exon_a - exon_b) * 8 + tax_bonus)
	            }
	            if (is.finite(tax_bonus) && tax_bonus > 0) {
	                return(tax_bonus)
	            }
	            NA_real_
	        }

	        score_mat <- matrix(NA_real_, nrow = length(ids), ncol = length(ids), dimnames = list(ids, ids))
	        diag(score_mat) <- Inf
	        for (i in seq_len(length(ids) - 1L)) {
	            for (j in seq.int(i + 1L, length(ids))) {
	                s <- similarity_score(i, j)
	                score_mat[i, j] <- s
	                score_mat[j, i] <- s
	            }
	        }

	        edge_score <- function(i, j) {
	            s <- suppressWarnings(as.numeric(score_mat[i, j]))
	            if (!is.finite(s)) -1e9 else s
	        }
	        path_total <- function(path_idx) {
	            if (length(path_idx) <= 1L) return(0)
	            total <- 0
	            for (kk in seq_len(length(path_idx) - 1L)) {
	                total <- total + edge_score(path_idx[kk], path_idx[kk + 1L])
	            }
	            total
	        }

	        if (nzchar(anchor_id)) {
	            anchor_idx <- suppressWarnings(as.integer(match(anchor_id, ids)))
	            if (!is.finite(anchor_idx) || is.na(anchor_idx) || anchor_idx < 1L) {
	                anchor_idx <- 1L
	            }
	            chain_idx <- anchor_idx
	            remaining <- setdiff(seq_along(ids), chain_idx)
	        } else {
	            best_pair <- which(score_mat == max(replace(score_mat, !is.finite(score_mat) | is.infinite(score_mat), -Inf), na.rm = TRUE), arr.ind = TRUE)
	            if (is.matrix(best_pair) && nrow(best_pair) > 0L) {
	                best_pair <- best_pair[best_pair[, 1] < best_pair[, 2], , drop = FALSE]
	            }
	            if (is.matrix(best_pair) && nrow(best_pair) > 0L) {
	                chain_idx <- as.integer(best_pair[1, ])
	            } else {
	                chain_idx <- c(1L, 2L)
	            }
	            remaining <- setdiff(seq_along(ids), chain_idx)
	        }
	        while (length(remaining) > 0L) {
	            best_candidate <- remaining[1L]
	            allowed_positions <- if (nzchar(anchor_id)) seq.int(2L, length(chain_idx) + 1L) else seq_len(length(chain_idx) + 1L)
	            if (length(allowed_positions) == 0L) {
	                allowed_positions <- length(chain_idx) + 1L
	            }
	            best_insert_pos <- allowed_positions[1L]
	            best_total <- -Inf
	            for (cand in remaining) {
	                for (insert_pos in allowed_positions) {
	                    trial <- append(chain_idx, cand, after = insert_pos - 1L)
	                    trial_total <- path_total(trial)
	                    if (!is.finite(best_total) || trial_total > best_total) {
	                        best_total <- trial_total
	                        best_candidate <- cand
	                        best_insert_pos <- insert_pos
	                    }
	                }
	            }
	            chain_idx <- append(chain_idx, best_candidate, after = best_insert_pos - 1L)
	            remaining <- setdiff(remaining, best_candidate)
	        }
	        as.character(ids[chain_idx])
	    })

	    alignedOrderedPlotIdsOrthologous <- reactive({
		        ids_all <- as.character(sortedPlotIdsOrthologous() %||% character(0))
	        ids <- as.character(alignedRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids_all) > 1L && length(ids) <= 1L) {
	            ids <- ids_all
	        }
	        if (length(ids) <= 1L) {
	            return(ids)
	        }
	        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
	        if (!identical(current_mode, "aligned")) {
	            return(ids)
	        }
	        order_mode <- tolower(trimws(as.character(input$ortho_aligned_track_order %||% "similarity_chain")))
	        if (!order_mode %in% c("similarity_chain", "load", "organism", "reverse", "manual")) {
	            order_mode <- "similarity_chain"
	        }
	        auto_ids <- as.character(autoAlignedOrderedPlotIdsOrthologous() %||% ids)
	        if (!identical(order_mode, "manual")) {
	            return(auto_ids)
	        }
	        manual_ids <- as.character(input$ortho_aligned_manual_order %||% character(0))
	        manual_ids <- manual_ids[manual_ids %in% ids]
	        manual_ids <- unique(manual_ids)
	        missing_ids <- auto_ids[!(auto_ids %in% manual_ids)]
	        c(manual_ids, missing_ids)
	    })

	    pipReferencePlotIdOrthologous <- reactive({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return("")
	        }
	        selected_id <- trimws(as.character(input$ortho_pip_reference_track %||% ""))
	        if (nzchar(selected_id) && selected_id %in% ids) {
	            return(selected_id)
	        }
	        ids[[1]]
	    })

	    pipOrderedPlotIdsOrthologous <- reactive({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return(character(0))
	        }
	        ref_id <- trimws(as.character(pipReferencePlotIdOrthologous() %||% ""))
	        if (!nzchar(ref_id) || !ref_id %in% ids) {
	            ref_id <- ids[[1]]
	        }
	        order_mode <- tolower(trimws(as.character(input$ortho_pip_track_order %||% "load")))
	        if (!order_mode %in% c("load", "organism", "similarity")) {
	            order_mode <- "load"
	        }
	        query_ids <- ids[ids != ref_id]
	        if (identical(order_mode, "organism") && length(query_ids) > 1L) {
	            org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	            query_ids <- query_ids[order(vapply(query_ids, function(pid) {
	                trimws(as.character((org_map[[pid]] %||% list())$name %||% pid))
	            }, character(1)), query_ids)]
	        }
	        c(ref_id, query_ids)
	    })

        pipVisiblePlotIdsOrthologous <- reactive({
            as.character(pipOrderedPlotIdsOrthologous() %||% character(0))
        })

	    pipRepresentativeWindowTracksOrthologous <- reactive({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return(list())
	        }
	        flank_bp <- parse_locus_window_flank_bp(input$ortho_pip_span %||% "gene", default_bp = 0L)
	        files_map <- tryCatch(fileDataOrthologous(), error = function(e) list())
	        ann_map <- tryCatch(annotationPathsOrthologous(), error = function(e) list())
	        genome_map <- tryCatch(genomePathsOrthologous(), error = function(e) list())
	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        gene_meta_map <- tryCatch(plotGeneMetaOrthologous(), error = function(e) list())
	        out <- lapply(ids, function(pid) {
	            extract_plot_locus_context(
	                plot_data = files_map[[pid]],
	                annotation_path = as.character(ann_map[[pid]] %||% ""),
	                genome_path = as.character(genome_map[[pid]] %||% ""),
	                flank_bp = flank_bp,
	                plot_id = pid,
	                title_txt = as.character(titles_map[[pid]] %||% ""),
	                organism_info = org_map[[pid]] %||% list(),
	                gene_meta = gene_meta_map[[pid]] %||% list()
	            )
	        })
	        names(out) <- ids
	        out
	    })

	    pipWindowTracksOrthologous <- reactive({
	        ids <- as.character(pipVisiblePlotIdsOrthologous() %||% character(0))
	        ctx_all <- pipRepresentativeWindowTracksOrthologous() %||% list()
	        ctx_all[ids]
	    })

	    pipReferenceWindowOrthologous <- reactive({
	        ref_id <- trimws(as.character(pipReferencePlotIdOrthologous() %||% ""))
	        ctx_map <- pipWindowTracksOrthologous() %||% list()
	        ctx_map[[ref_id]] %||% NULL
	    })

	    pipLocalAlignmentJobsOrthologous <- reactive({
	        ctx_map <- pipWindowTracksOrthologous() %||% list()
	        ref_ctx <- pipReferenceWindowOrthologous()
	        ids <- as.character(pipVisiblePlotIdsOrthologous() %||% character(0))
	        if (is.null(ref_ctx) || length(ids) <= 1L) {
	            return(list())
	        }
	        query_ids <- ids[ids != as.character(ref_ctx$plot_id %||% "")]
	        jobs <- lapply(query_ids, function(pid) {
	            qry_ctx <- ctx_map[[pid]] %||% NULL
	            if (is.null(qry_ctx)) {
	                return(NULL)
	            }
	            build_lastz_job_spec(
	                reference_ctx = ref_ctx,
	                query_ctx = qry_ctx,
	                format_name = "general"
	            )
	        })
	        jobs <- Filter(Negate(is.null), jobs)
	        names(jobs) <- query_ids[seq_along(jobs)]
	        jobs
	    })

        pipLocalAlignmentStateOrthologous <- reactiveVal(list(
            runs = list(),
            stamp = "",
            running = FALSE,
            token = ""
        ))
        setPipLocalAlignmentStateOrthologous <- function(runs = NULL, stamp = NULL, running = NULL, token = NULL, reset = FALSE) {
            state <- if (isTRUE(reset)) {
                list(runs = list(), stamp = "", running = FALSE, token = "")
            } else {
                pipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            }
            if (!is.null(runs)) state$runs <- runs %||% list()
            if (!is.null(stamp)) state$stamp <- trimws(as.character(stamp %||% ""))
            if (!is.null(running)) state$running <- isTRUE(running)
            if (!is.null(token)) state$token <- trimws(as.character(token %||% ""))
            pipLocalAlignmentStateOrthologous(state)
            invisible(state)
        }
        pipLocalAlignmentRunsCacheOrthologous <- function(value) {
            state <- pipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(state$runs %||% list())
            setPipLocalAlignmentStateOrthologous(runs = value)
            invisible(value)
        }
        pipLocalAlignmentRunStampOrthologous <- function(value) {
            state <- pipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(trimws(as.character(state$stamp %||% "")))
            setPipLocalAlignmentStateOrthologous(stamp = value)
            invisible(value)
        }
        pipLocalAlignmentRunningOrthologous <- function(value) {
            state <- pipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(isTRUE(state$running))
            setPipLocalAlignmentStateOrthologous(running = value)
            invisible(isTRUE(value))
        }
        pipLocalAlignmentTokenOrthologous <- function(value) {
            state <- pipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(trimws(as.character(state$token %||% "")))
            setPipLocalAlignmentStateOrthologous(token = value)
            invisible(value)
        }
        pipReferenceAssessmentOrthologous <- reactiveVal(list(
            status = "pending",
            basis = "default",
            reference_id = "",
            summary = "Choose a reference and run local alignments to evaluate it.",
            detail = "The evaluation reuses the selected reference alignment and does not run an all-against-all candidate sweep.",
            metrics = NULL,
            stamp = ""
        ))

        observeEvent(
            list(
                pipRepresentativePlotIdsOrthologous(),
                input$ortho_pip_reference_track,
                input$ortho_pip_span,
                input$ortho_pip_track_order
            ),
            {
                if (isTRUE(pipLocalAlignmentRunningOrthologous())) {
                    shinyjs::enable("ortho_pip_run_alignments")
                    set_popup_loading(FALSE, context = "LASTZ Blocks")
                }
                setPipLocalAlignmentStateOrthologous(reset = TRUE)
                current_ref <- trimws(as.character(pipReferencePlotIdOrthologous() %||% ""))
                pipReferenceAssessmentOrthologous(list(
                    status = "pending",
                    basis = if (nzchar(trimws(as.character(input$ortho_pip_reference_track %||% "")))) "manual" else "default",
                    reference_id = current_ref,
                    summary = "Run local alignments to evaluate the selected reference.",
                    detail = "Changing the reference changes the coordinate projection. The app evaluates only the selected reference against the visible organisms.",
                    metrics = NULL,
                    stamp = ""
                ))
            },
            ignoreInit = TRUE
        )


        observeEvent(input$ortho_pip_run_alignments, {
            lastz_dbg("=== LASTZ BLOCKS START ===", detail = format(Sys.time()))

            lastz_dbg("Step 1: Resolving contexts")
            ctx_map <- tryCatch(pipWindowTracksOrthologous() %||% list(), error = function(e) {
                lastz_dbg("Step 1 FAILED: pipWindowTracksOrthologous()", detail = e$message, level = "error")
                list()
            })
            lastz_dbg("Step 1a: ctx_map", detail = sprintf("length=%d, names=[%s]", length(ctx_map), paste(names(ctx_map), collapse = ",")))

            ref_ctx <- tryCatch(pipReferenceWindowOrthologous(), error = function(e) {
                lastz_dbg("Step 1b FAILED: pipReferenceWindowOrthologous()", detail = e$message, level = "error")
                NULL
            })
            lastz_dbg("Step 1b: ref_ctx", data = summarize_ctx_for_debug(ref_ctx, "reference"))

            ids <- as.character(pipVisiblePlotIdsOrthologous() %||% character(0))
            lastz_dbg("Step 1c: visible ids", detail = sprintf("n=%d, ids=[%s]", length(ids), paste(ids, collapse = ",")))

            if (is.null(ref_ctx) || length(ids) <= 1L) {
                lastz_dbg("ABORT: ref_ctx is NULL or ids <= 1", level = "warn")
                setPipLocalAlignmentStateOrthologous(reset = TRUE)
                return(invisible(NULL))
            }
            query_ids <- ids[ids != as.character(ref_ctx$plot_id %||% "")]
            lastz_dbg("Step 2: query_ids", detail = sprintf("n=%d, ids=[%s]", length(query_ids), paste(query_ids, collapse = ",")))

            # Log each query context
            for (qid in query_ids) {
                lastz_dbg(sprintf("Step 2a: query ctx [%s]", qid), data = summarize_ctx_for_debug(ctx_map[[qid]], qid))
            }

            lastz_dbg("Step 3: Resolving LASTZ binary")
            bin_info <- tryCatch(resolve_lastz_binary(), error = function(e) {
                lastz_dbg("Step 3 FAILED", detail = e$message, level = "error")
                list(available = FALSE, path = "", source = "error")
            })
            lastz_dbg("Step 3 result", data = list(
                available = isTRUE(bin_info$available),
                path = as.character(bin_info$path %||% ""),
                source = as.character(bin_info$source %||% "")
            ))

            lastz_dbg("Step 4: Extracting sequences for reference")
            ref_seq_result <- tryCatch({
                seq_txt <- extract_locus_window_sequence(ref_ctx)
                list(ok = TRUE, len = nchar(seq_txt), preview = substr(seq_txt, 1, 50))
            }, error = function(e) {
                list(ok = FALSE, error = e$message)
            })
            lastz_dbg("Step 4 ref sequence", data = ref_seq_result)

            if (isTRUE(pipLocalAlignmentRunningOrthologous())) {
                lastz_dbg("ABORT: already running", level = "warn")
                emit_popup_status("LASTZ Blocks", "Local LASTZ alignments are already running.", tone = "info", clear = TRUE)
                return(invisible(NULL))
            }

            setPipLocalAlignmentStateOrthologous(running = TRUE)
            shinyjs::disable("ortho_pip_run_alignments")
            set_popup_loading(
                TRUE,
                context = "LASTZ Blocks",
                text = lastz_progress_text(sprintf(
                    "Running %d LASTZ job%s in the background.",
                    length(query_ids),
                    if (length(query_ids) == 1L) "" else "s"
                )),
                headline = "Please be patient",
                auto_open = TRUE
            )

            query_ids_local <- query_ids
            ctx_map_local <- ctx_map
            ref_ctx_local <- ref_ctx
            run_token <- paste0("lastz_blocks_", format(Sys.time(), "%Y%m%d%H%M%OS6"), "_", sample.int(1000000L, 1))
            run_t0 <- app_perf_now()
            setPipLocalAlignmentStateOrthologous(running = TRUE, token = run_token)
            lastz_dbg("Step 5: Launching per-query futures", detail = sprintf("token=%s, jobs=%d", run_token, length(query_ids_local)))
            app_perf_mark(NULL, sprintf("lastz_blocks_run_start jobs=%d", as.integer(length(query_ids_local))), "ORTHO_LASTZ")

            finalize_pip_async <- function(runs, run_token_local) {
                current_token <- trimws(as.character(pipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, trimws(as.character(run_token_local %||% "")))) {
                    lastz_dbg("Stale LASTZ Blocks completion ignored", detail = sprintf("token=%s current=%s", run_token_local, current_token), level = "warn")
                    return(invisible(NULL))
                }

                total_blocks <- sum(vapply(runs, function(run_obj) {
                    blk <- (run_obj %||% list())$blocks
                    if (is.data.frame(blk)) nrow(blk) else 0L
                }, integer(1)), na.rm = TRUE)
                app_perf_mark_ms(NULL, "lastz_blocks_run_total_ms", app_perf_elapsed_ms(run_t0), "ORTHO_LASTZ")
                app_perf_mark(NULL, sprintf("lastz_blocks_run_done runs=%d blocks=%d", as.integer(length(runs)), as.integer(total_blocks)), "ORTHO_LASTZ")
                failed_statuses <- c("engine_error", "engine_timeout", "window_too_large")
                all_engine_errors <- length(runs) > 0L && all(vapply(runs, function(run_obj) {
                    trimws(as.character((run_obj %||% list())$status %||% "")) %in% failed_statuses
                }, logical(1)))
                combined_err <- unique(unlist(lapply(runs, function(run_obj) {
                    c(
                        as.character((run_obj %||% list())$stderr %||% character(0)),
                        as.character((run_obj %||% list())$setup_hint %||% character(0))
                    )
                }), use.names = FALSE))
                combined_err <- trimws(combined_err)
                combined_err <- combined_err[nzchar(combined_err)]

                lastz_dbg("Step 6: Saving async results", detail = sprintf("n_runs=%d total_blocks=%d", length(runs), as.integer(total_blocks)))
                setPipLocalAlignmentStateOrthologous(
                    runs = runs %||% list(),
                    stamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
                    running = FALSE,
                    token = run_token_local
                )
                pipReferenceAssessmentOrthologous(assess_current_lastz_reference(
                    runs = runs,
                    reference_ctx = ref_ctx_local,
                    kind = "blocks",
                    min_identity = max(0, min(100, suppressWarnings(as.numeric(input$ortho_pip_min_identity %||% 70)))),
                    min_length = suppressWarnings(as.integer(input$ortho_pip_min_length %||% 100L))
                ))
                shinyjs::enable("ortho_pip_run_alignments")
                set_popup_loading(FALSE, context = "LASTZ Blocks")

                if (all_engine_errors) {
                    statuses <- unique(vapply(runs, function(run_obj) {
                        trimws(as.character((run_obj %||% list())$status %||% "engine_error"))
                    }, character(1)))
                    err_msg <- if ("engine_timeout" %in% statuses) {
                        "the safety timeout was reached; reduce the locus span and retry"
                    } else if (length(combined_err) > 0L) {
                        combined_err[[1L]]
                    } else {
                        "unknown error"
                    }
                    emit_popup_status(
                        "LASTZ Blocks",
                        paste0("Local LASTZ alignments failed", if (nzchar(err_msg)) paste0(": ", err_msg) else "."),
                        tone = "error",
                        clear = TRUE
                    )
                    lastz_dbg("=== LASTZ BLOCKS END (ERROR) ===", detail = err_msg, level = "error")
                } else if (length(runs) > 0L) {
                    emit_popup_status("LASTZ Blocks", "Local LASTZ alignments finished.", tone = "success", clear = TRUE)
                    lastz_dbg("=== LASTZ BLOCKS END (OK) ===", detail = sprintf("total_blocks=%d", as.integer(total_blocks)))
                } else {
                    emit_popup_status("LASTZ Blocks", "No LASTZ jobs were available for the current tracks.", tone = "warning", clear = TRUE)
                    lastz_dbg("=== LASTZ BLOCKS END (NO JOBS) ===", level = "warn")
                }
                invisible(NULL)
            }

            promise_map <- with_lastz_future_plan(lapply(seq_along(query_ids_local), function(i) {
                pid <- query_ids_local[[i]]
                qry_ctx <- ctx_map_local[[pid]] %||% NULL
                if (is.null(qry_ctx)) {
                    lastz_dbg(sprintf("Step 5[%d]: query ctx is NULL, returning empty result", i), level = "warn")
                    return(promises::promise_resolve(NULL))
                }
                cache_key <- lastz_alignment_cache_key(
                    mode = "canonical_lastz",
                    reference_ctx = ref_ctx_local,
                    query_ctx = qry_ctx,
                    format_name = "general-cigarx",
                    bin_info = bin_info,
                    extra_args = character(0)
                )
                cached_result <- get_lastz_alignment_cached_result(cache_key, ref_ctx_local, qry_ctx)
                if (!is.null(cached_result)) {
                    app_perf_mark(NULL, sprintf("lastz_blocks_cache_hit pid=%s", as.character(pid)), "ORTHO_LASTZ")
                    lastz_dbg(sprintf("Step 5[%d]: cache hit", i), detail = as.character(cache_key))
                    return(promises::promise_resolve(list(
                        pid = pid,
                        idx = i,
                        query_seq_result = list(
                            ok = TRUE,
                            cached = TRUE,
                            len = as.integer(cached_result$query_width %||% 0L)
                        ),
                        run = cached_result,
                        cache_key = cache_key,
                        cache_hit = TRUE
                    )))
                }
                app_perf_mark(NULL, sprintf("lastz_blocks_cache_miss pid=%s", as.character(pid)), "ORTHO_LASTZ")
                tryCatch(
                    promises::future_promise({
                        qry_seq_result <- tryCatch({
                            seq_txt <- extract_locus_window_sequence(qry_ctx)
                            list(ok = TRUE, len = nchar(seq_txt), preview = substr(seq_txt, 1, 50))
                        }, error = function(e) {
                            list(ok = FALSE, error = e$message)
                        })
                        result <- tryCatch(
                            run_cached_canonical_lastz(
                                cache_key = cache_key,
                                reference_ctx = ref_ctx_local,
                                query_ctx = qry_ctx,
                                engine = "lastz"
                            ),
                            error = function(e) list(status = "engine_error", stderr = conditionMessage(e), blocks = data.frame(stringsAsFactors = FALSE))
                        )
                        list(
                            pid = pid,
                            idx = i,
                            query_seq_result = qry_seq_result,
                            run = result,
                            cache_key = cache_key,
                            cache_hit = FALSE
                        )
                    }, seed = FALSE),
                    error = function(e) {
                        promises::promise_resolve(list(
                            pid = pid,
                            idx = i,
                            query_seq_result = list(ok = FALSE, error = conditionMessage(e)),
                            run = list(status = "engine_error", stderr = conditionMessage(e), blocks = data.frame(stringsAsFactors = FALSE)),
                            cache_key = cache_key,
                            cache_hit = FALSE
                        ))
                    }
                )
            }), label = "LASTZ Blocks")
            names(promise_map) <- query_ids_local

            promises::promise_all(.list = promise_map) %...>% (function(run_payloads) {
                current_token <- trimws(as.character(pipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, run_token)) {
                    lastz_dbg("Stale LASTZ Blocks promise_all resolution ignored", detail = sprintf("token=%s current=%s", run_token, current_token), level = "warn")
                    return(NULL)
                }
                payload_list <- unname(as.list(run_payloads %||% list()))
                payload_list <- Filter(Negate(is.null), payload_list)
                if (length(payload_list) == 0L) {
                    finalize_pip_async(setNames(vector("list", length(query_ids_local)), query_ids_local), run_token)
                    return(NULL)
                }
                runs <- lapply(payload_list, function(item) item$run %||% list(status = "engine_error", stderr = "empty result", blocks = data.frame(stringsAsFactors = FALSE)))
                names(runs) <- vapply(payload_list, function(item) as.character(item$pid %||% ""), character(1))
                for (item in payload_list) {
                    lastz_dbg(sprintf("Step 5[%d]: query sequence", as.integer(item$idx %||% 0L)), data = item$query_seq_result %||% list())
                    result <- item$run %||% list()
                    if (!isTRUE(item$cache_hit) && nzchar(as.character(item$cache_key %||% ""))) {
                        set_lastz_alignment_cached_result(item$cache_key, result)
                    }
                    lastz_dbg(sprintf("Step 5[%d]: alignment result", as.integer(item$idx %||% 0L)), data = list(
                        pid = as.character(item$pid %||% ""),
                        status = as.character(result$status %||% ""),
                        n_blocks = if (is.data.frame(result$blocks)) nrow(result$blocks) else 0L,
                        ref_width = as.integer(result$reference_width %||% 0L),
                        qry_width = as.integer(result$query_width %||% 0L),
                        cache_hit = isTRUE(item$cache_hit),
                        stderr = paste(as.character(result$stderr %||% ""), collapse = " ")
                    ))
                }
                finalize_pip_async(runs, run_token)
                NULL
            }) %...!% (function(err) {
                current_token <- trimws(as.character(pipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, run_token)) {
                    lastz_dbg("Stale LASTZ Blocks promise_all error ignored", detail = sprintf("token=%s current=%s", run_token, current_token), level = "warn")
                    return(NULL)
                }
                err_msg <- trimws(as.character(conditionMessage(err) %||% as.character(err$message %||% "unknown error")))
                lastz_dbg("LASTZ Blocks FATAL ERROR", detail = err_msg, level = "error")
                error_map <- lapply(query_ids_local, function(pid) {
                    list(status = "engine_error", stderr = err_msg, blocks = data.frame(stringsAsFactors = FALSE))
                })
                names(error_map) <- query_ids_local
                finalize_pip_async(error_map, run_token)
                NULL
            })
        }, ignoreInit = TRUE)

	    pipLocalAlignmentRunsOrthologous <- reactive({
	        pipLocalAlignmentRunsCacheOrthologous() %||% list()
	    })

        resolve_multipip_job_builder <- function() {
            fn <- get0("build_lastz_multipip_job_spec", mode = "function", inherits = TRUE)
            if (is.null(fn) && "app_libraries" %in% search()) {
                fn <- get0("build_lastz_multipip_job_spec", envir = as.environment("app_libraries"), mode = "function", inherits = FALSE)
            }
            if (is.null(fn)) {
                stop("MultiPIP backend is unavailable: build_lastz_multipip_job_spec() is not loaded.")
            }
            fn
        }

        resolve_multipip_alignment_runner <- function() {
            fn <- get0("run_local_locus_alignment_multipip", mode = "function", inherits = TRUE)
            if (is.null(fn) && "app_libraries" %in% search()) {
                fn <- get0("run_local_locus_alignment_multipip", envir = as.environment("app_libraries"), mode = "function", inherits = FALSE)
            }
            if (is.null(fn)) {
                stop("MultiPIP backend is unavailable: run_local_locus_alignment_multipip() is not loaded.")
            }
            fn
        }

	    multipipReferencePlotIdOrthologous <- reactive({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return("")
	        }
	        selected_id <- trimws(as.character(input$ortho_multipip_reference_track %||% ""))
	        if (nzchar(selected_id) && selected_id %in% ids) {
	            return(selected_id)
	        }
	        ids[[1]]
	    })

	    multipipOrderedPlotIdsOrthologous <- reactive({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return(character(0))
	        }
	        ref_id <- trimws(as.character(multipipReferencePlotIdOrthologous() %||% ""))
	        if (!nzchar(ref_id) || !ref_id %in% ids) {
	            ref_id <- ids[[1]]
	        }
	        order_mode <- tolower(trimws(as.character(input$ortho_multipip_track_order %||% "load")))
	        if (!order_mode %in% c("load", "organism", "similarity")) {
	            order_mode <- "load"
	        }
	        query_ids <- ids[ids != ref_id]
	        if (identical(order_mode, "organism") && length(query_ids) > 1L) {
	            org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	            query_ids <- query_ids[order(vapply(query_ids, function(pid) {
	                trimws(as.character((org_map[[pid]] %||% list())$name %||% pid))
	            }, character(1)), query_ids)]
	        }
	        c(ref_id, query_ids)
	    })

	    multipipWindowTracksOrthologous <- reactive({
	        ids <- as.character(multipipOrderedPlotIdsOrthologous() %||% character(0))
	        if (length(ids) == 0L) {
	            return(list())
	        }
	        flank_bp <- parse_locus_window_flank_bp(input$ortho_multipip_span %||% "gene", default_bp = 0L)
	        files_map <- tryCatch(fileDataOrthologous(), error = function(e) list())
	        ann_map <- tryCatch(annotationPathsOrthologous(), error = function(e) list())
	        genome_map <- tryCatch(genomePathsOrthologous(), error = function(e) list())
	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        gene_meta_map <- tryCatch(plotGeneMetaOrthologous(), error = function(e) list())
	        out <- lapply(ids, function(pid) {
	            extract_plot_locus_context(
	                plot_data = files_map[[pid]],
	                annotation_path = as.character(ann_map[[pid]] %||% ""),
	                genome_path = as.character(genome_map[[pid]] %||% ""),
	                flank_bp = flank_bp,
	                plot_id = pid,
	                title_txt = as.character(titles_map[[pid]] %||% ""),
	                organism_info = org_map[[pid]] %||% list(),
	                gene_meta = gene_meta_map[[pid]] %||% list()
	            )
	        })
	        names(out) <- ids
	        out
	    })

	    multipipReferenceWindowOrthologous <- reactive({
	        ref_id <- trimws(as.character(multipipReferencePlotIdOrthologous() %||% ""))
	        ctx_map <- multipipWindowTracksOrthologous() %||% list()
	        ctx_map[[ref_id]] %||% NULL
	    })

	    multipipLocalAlignmentJobsOrthologous <- reactive({
	        ctx_map <- multipipWindowTracksOrthologous() %||% list()
	        ref_ctx <- multipipReferenceWindowOrthologous()
	        ids <- as.character(multipipOrderedPlotIdsOrthologous() %||% character(0))
	        if (is.null(ref_ctx) || length(ids) <= 1L) {
	            return(list())
	        }
            build_job <- resolve_multipip_job_builder()
	        query_ids <- ids[ids != as.character(ref_ctx$plot_id %||% "")]
	        jobs <- lapply(query_ids, function(pid) {
	            qry_ctx <- ctx_map[[pid]] %||% NULL
	            if (is.null(qry_ctx)) {
	                return(NULL)
	            }
	            build_job(
	                reference_ctx = ref_ctx,
	                query_ctx = qry_ctx
	            )
	        })
	        jobs <- Filter(Negate(is.null), jobs)
	        names(jobs) <- query_ids[seq_along(jobs)]
	        jobs
	    })

        multipipLocalAlignmentStateOrthologous <- reactiveVal(list(
            runs = list(),
            stamp = "",
            running = FALSE,
            token = ""
        ))
        setMultipipLocalAlignmentStateOrthologous <- function(runs = NULL, stamp = NULL, running = NULL, token = NULL, reset = FALSE) {
            state <- if (isTRUE(reset)) {
                list(runs = list(), stamp = "", running = FALSE, token = "")
            } else {
                multipipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            }
            if (!is.null(runs)) state$runs <- runs %||% list()
            if (!is.null(stamp)) state$stamp <- trimws(as.character(stamp %||% ""))
            if (!is.null(running)) state$running <- isTRUE(running)
            if (!is.null(token)) state$token <- trimws(as.character(token %||% ""))
            multipipLocalAlignmentStateOrthologous(state)
            invisible(state)
        }
        multipipLocalAlignmentRunsCacheOrthologous <- function(value) {
            state <- multipipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(state$runs %||% list())
            setMultipipLocalAlignmentStateOrthologous(runs = value)
            invisible(value)
        }
        multipipLocalAlignmentRunStampOrthologous <- function(value) {
            state <- multipipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(trimws(as.character(state$stamp %||% "")))
            setMultipipLocalAlignmentStateOrthologous(stamp = value)
            invisible(value)
        }
        multipipLocalAlignmentRunningOrthologous <- function(value) {
            state <- multipipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(isTRUE(state$running))
            setMultipipLocalAlignmentStateOrthologous(running = value)
            invisible(isTRUE(value))
        }
        multipipLocalAlignmentTokenOrthologous <- function(value) {
            state <- multipipLocalAlignmentStateOrthologous() %||% list(runs = list(), stamp = "", running = FALSE, token = "")
            if (missing(value)) return(trimws(as.character(state$token %||% "")))
            setMultipipLocalAlignmentStateOrthologous(token = value)
            invisible(value)
        }
        multipipReferenceAssessmentOrthologous <- reactiveVal(list(
            status = "pending",
            basis = "default",
            reference_id = "",
            summary = "Choose a reference and run local alignments to evaluate it.",
            detail = "The evaluation reuses the selected reference alignment and does not run an all-against-all candidate sweep.",
            metrics = NULL,
            stamp = ""
        ))

        observeEvent(
            list(
                pipRepresentativePlotIdsOrthologous(),
                input$ortho_multipip_reference_track,
                input$ortho_multipip_span,
                input$ortho_multipip_track_order
            ),
            {
                if (isTRUE(multipipLocalAlignmentRunningOrthologous())) {
                    shinyjs::enable("ortho_multipip_run_alignments")
                    set_popup_loading(FALSE, context = "MultiPIP")
                }
                setMultipipLocalAlignmentStateOrthologous(reset = TRUE)
                current_ref <- trimws(as.character(multipipReferencePlotIdOrthologous() %||% ""))
                multipipReferenceAssessmentOrthologous(list(
                    status = "pending",
                    basis = if (nzchar(trimws(as.character(input$ortho_multipip_reference_track %||% "")))) "manual" else "default",
                    reference_id = current_ref,
                    summary = "Run local alignments to evaluate the selected reference.",
                    detail = "Changing the reference changes the coordinate system. The app evaluates only the selected reference against the visible organisms.",
                    metrics = NULL,
                    stamp = ""
                ))
            },
            ignoreInit = TRUE
        )


        observeEvent(input$ortho_multipip_run_alignments, {
            lastz_dbg("=== MULTIPIP START ===", detail = format(Sys.time()))

            lastz_dbg("MP Step 1: Resolving contexts")
            ctx_map <- tryCatch(multipipWindowTracksOrthologous() %||% list(), error = function(e) {
                lastz_dbg("MP Step 1 FAILED: multipipWindowTracksOrthologous()", detail = e$message, level = "error")
                list()
            })
            lastz_dbg("MP Step 1a: ctx_map", detail = sprintf("length=%d, names=[%s]", length(ctx_map), paste(names(ctx_map), collapse = ",")))

            ref_ctx <- tryCatch(multipipReferenceWindowOrthologous(), error = function(e) {
                lastz_dbg("MP Step 1b FAILED: multipipReferenceWindowOrthologous()", detail = e$message, level = "error")
                NULL
            })
            lastz_dbg("MP Step 1b: ref_ctx", data = summarize_ctx_for_debug(ref_ctx, "reference"))

            ids <- as.character(multipipOrderedPlotIdsOrthologous() %||% character(0))
            lastz_dbg("MP Step 1c: ordered ids", detail = sprintf("n=%d, ids=[%s]", length(ids), paste(ids, collapse = ",")))

            if (is.null(ref_ctx) || length(ids) <= 1L) {
                lastz_dbg("MP ABORT: ref_ctx is NULL or ids <= 1", level = "warn")
                setMultipipLocalAlignmentStateOrthologous(reset = TRUE)
                return(invisible(NULL))
            }
            if (isTRUE(multipipLocalAlignmentRunningOrthologous())) {
                lastz_dbg("MP ABORT: already running", level = "warn")
                emit_popup_status("MultiPIP", "Local alignments are already running.", tone = "info", clear = TRUE)
                return(invisible(NULL))
            }

            lastz_dbg("MP Step 2: Resolving runner function")
            run_multipip <- tryCatch(resolve_multipip_alignment_runner(), error = function(e) {
                lastz_dbg("MP Step 2 FAILED", detail = e$message, level = "error")
                NULL
            })
            lastz_dbg("MP Step 2 result", detail = sprintf("is.function=%s", isTRUE(is.function(run_multipip))))

            query_ids <- ids[ids != as.character(ref_ctx$plot_id %||% "")]
            lastz_dbg("MP Step 3: query_ids", detail = sprintf("n=%d", length(query_ids)))
            for (qid in query_ids) {
                lastz_dbg(sprintf("MP Step 3a: query ctx [%s]", qid), data = summarize_ctx_for_debug(ctx_map[[qid]], qid))
            }

            lastz_dbg("MP Step 4: Checking LASTZ binary")
            bin_info <- tryCatch(resolve_lastz_binary(), error = function(e) {
                lastz_dbg("MP Step 4 FAILED", detail = e$message, level = "error")
                list(available = FALSE, path = "", source = "error")
            })
            lastz_dbg("MP Step 4 result", data = list(
                available = isTRUE(bin_info$available),
                path = as.character(bin_info$path %||% ""),
                source = as.character(bin_info$source %||% "")
            ))

            lastz_dbg("MP Step 5: Testing ref sequence extraction")
            ref_seq_result <- tryCatch({
                seq_txt <- extract_locus_window_sequence(ref_ctx)
                list(ok = TRUE, len = nchar(seq_txt), preview = substr(seq_txt, 1, 50))
            }, error = function(e) {
                list(ok = FALSE, error = e$message)
            })
            lastz_dbg("MP Step 5 ref sequence", data = ref_seq_result)

            setMultipipLocalAlignmentStateOrthologous(running = TRUE)
            shinyjs::disable("ortho_multipip_run_alignments")
            set_popup_loading(
                TRUE,
                context = "MultiPIP",
                text = lastz_progress_text(sprintf(
                    "Running %d MultiPIP LASTZ job%s.",
                    length(query_ids),
                    if (length(query_ids) == 1L) "" else "s"
                )),
                headline = "Please be patient",
                auto_open = TRUE
            )

            query_ids_local <- query_ids
            ctx_map_local <- ctx_map
            ref_ctx_local <- ref_ctx
            run_multipip_local <- run_multipip
            run_token <- paste0("multipip_", format(Sys.time(), "%Y%m%d%H%M%OS6"), "_", sample.int(1000000L, 1))
            run_t0 <- app_perf_now()
            setMultipipLocalAlignmentStateOrthologous(running = TRUE, token = run_token)
            lastz_dbg("MP Step 6: Launching per-query futures", detail = sprintf("token=%s, jobs=%d", run_token, length(query_ids_local)))
            app_perf_mark(NULL, sprintf("multipip_run_start jobs=%d", as.integer(length(query_ids_local))), "ORTHO_LASTZ")

            finalize_multipip_async <- function(runs, run_token_local) {
                current_token <- trimws(as.character(multipipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, trimws(as.character(run_token_local %||% "")))) {
                    lastz_dbg("MP stale completion ignored", detail = sprintf("token=%s current=%s", run_token_local, current_token), level = "warn")
                    return(invisible(NULL))
                }

                total_visible_segments <- sum(vapply(runs, function(run_obj) {
                    seg <- (run_obj %||% list())$segments
                    if (is.data.frame(seg)) nrow(seg) else 0L
                }, integer(1)), na.rm = TRUE)
                app_perf_mark_ms(NULL, "multipip_run_total_ms", app_perf_elapsed_ms(run_t0), "ORTHO_LASTZ")
                app_perf_mark(NULL, sprintf("multipip_run_done runs=%d segments=%d", as.integer(length(runs)), as.integer(total_visible_segments)), "ORTHO_LASTZ")
                failed_statuses <- c("engine_error", "engine_timeout", "window_too_large")
                all_engine_errors <- length(runs) > 0L && all(vapply(runs, function(run_obj) {
                    trimws(as.character((run_obj %||% list())$status %||% "")) %in% failed_statuses
                }, logical(1)))
                combined_err <- unique(unlist(lapply(runs, function(run_obj) {
                    c(
                        as.character((run_obj %||% list())$stderr %||% character(0)),
                        as.character((run_obj %||% list())$setup_hint %||% character(0))
                    )
                }), use.names = FALSE))
                combined_err <- trimws(combined_err)
                combined_err <- combined_err[nzchar(combined_err)]

                setMultipipLocalAlignmentStateOrthologous(
                    runs = runs %||% list(),
                    stamp = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
                    running = FALSE,
                    token = run_token_local
                )
                multipipReferenceAssessmentOrthologous(assess_current_lastz_reference(
                    runs = runs,
                    reference_ctx = ref_ctx_local,
                    kind = "multipip",
                    min_identity = max(50, min(100, suppressWarnings(as.numeric(input$ortho_multipip_min_identity %||% 70)))),
                    min_length = suppressWarnings(as.integer(input$ortho_multipip_min_segment_bp %||% 25L))
                ))
                shinyjs::enable("ortho_multipip_run_alignments")
                set_popup_loading(FALSE, context = "MultiPIP")

                if (all_engine_errors) {
                    statuses <- unique(vapply(runs, function(run_obj) {
                        trimws(as.character((run_obj %||% list())$status %||% "engine_error"))
                    }, character(1)))
                    err_msg <- if ("engine_timeout" %in% statuses) {
                        "the safety timeout was reached; reduce the locus span and retry"
                    } else if (length(combined_err) > 0L) {
                        combined_err[[1L]]
                    } else {
                        "unknown error"
                    }
                    emit_popup_status(
                        "MultiPIP",
                        paste0("Local alignments failed", if (nzchar(err_msg)) paste0(": ", err_msg) else "."),
                        tone = "error",
                        clear = TRUE
                    )
                    lastz_dbg("=== MULTIPIP END (ERROR) ===", detail = err_msg, level = "error")
                } else if (total_visible_segments <= 0L) {
                    emit_popup_status(
                        "MultiPIP",
                        "Local alignments finished, but no gap-free segments passed the current MultiPIP filters.",
                        tone = "warning",
                        clear = TRUE
                    )
                    lastz_dbg("=== MULTIPIP END (NO VISIBLE SEGMENTS) ===")
                } else {
                    emit_popup_status("MultiPIP", "Local alignments finished.", tone = "success", clear = TRUE)
                    lastz_dbg("=== MULTIPIP END (OK) ===", detail = sprintf("visible_segments=%d", as.integer(total_visible_segments)))
                }
                invisible(NULL)
            }

            promise_map <- with_lastz_future_plan(lapply(seq_along(query_ids_local), function(i) {
                pid <- query_ids_local[[i]]
                qry_ctx <- ctx_map_local[[pid]] %||% NULL
                if (is.null(qry_ctx)) {
                    lastz_dbg(sprintf("MP Step 6[%d]: query ctx is NULL, returning empty result", i), level = "warn")
                    return(promises::promise_resolve(NULL))
                }
                cache_key <- lastz_alignment_cache_key(
                    mode = "canonical_lastz",
                    reference_ctx = ref_ctx_local,
                    query_ctx = qry_ctx,
                    format_name = "general-cigarx",
                    bin_info = bin_info,
                    extra_args = character(0)
                )
                cached_result <- get_lastz_alignment_cached_result(cache_key, ref_ctx_local, qry_ctx)
                if (!is.null(cached_result)) {
                    app_perf_mark(NULL, sprintf("multipip_cache_hit pid=%s", as.character(pid)), "ORTHO_LASTZ")
                    lastz_dbg(sprintf("MP Step 6[%d]: cache hit", i), detail = as.character(cache_key))
                    return(promises::promise_resolve(list(
                        pid = pid,
                        idx = i,
                        query_seq_result = list(
                            ok = TRUE,
                            cached = TRUE,
                            len = as.integer(cached_result$query_width %||% 0L)
                        ),
                        run = cached_result,
                        cache_key = cache_key,
                        cache_hit = TRUE
                    )))
                }
                app_perf_mark(NULL, sprintf("multipip_cache_miss pid=%s", as.character(pid)), "ORTHO_LASTZ")
                tryCatch(
                    lastz_future_promise({
                        qry_seq_result <- tryCatch({
                            seq_txt <- extract_locus_window_sequence(qry_ctx)
                            list(ok = TRUE, len = nchar(seq_txt), preview = substr(seq_txt, 1, 50))
                        }, error = function(e) {
                            list(ok = FALSE, error = e$message)
                        })
                        result <- tryCatch(
                            run_cached_canonical_lastz(
                                cache_key = cache_key,
                                reference_ctx = ref_ctx_local,
                                query_ctx = qry_ctx,
                                engine = "lastz"
                            ),
                            error = function(e) list(status = "engine_error", stderr = conditionMessage(e), segments = data.frame(stringsAsFactors = FALSE))
                        )
                        list(
                            pid = pid,
                            idx = i,
                            query_seq_result = qry_seq_result,
                            run = result,
                            cache_key = cache_key,
                            cache_hit = FALSE
                        )
                    }, seed = FALSE),
                    error = function(e) {
                        promises::promise_resolve(list(
                            pid = pid,
                            idx = i,
                            query_seq_result = list(ok = FALSE, error = conditionMessage(e)),
                            run = list(status = "engine_error", stderr = conditionMessage(e), segments = data.frame(stringsAsFactors = FALSE)),
                            cache_key = cache_key,
                            cache_hit = FALSE
                        ))
                    }
                )
            }), label = "MultiPIP")
            names(promise_map) <- query_ids_local

            promises::promise_all(.list = promise_map) %...>% (function(run_payloads) {
                current_token <- trimws(as.character(multipipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, run_token)) {
                    lastz_dbg("MP stale promise_all resolution ignored", detail = sprintf("token=%s current=%s", run_token, current_token), level = "warn")
                    return(NULL)
                }
                payload_list <- unname(as.list(run_payloads %||% list()))
                payload_list <- Filter(Negate(is.null), payload_list)
                if (length(payload_list) == 0L) {
                    finalize_multipip_async(setNames(vector("list", length(query_ids_local)), query_ids_local), run_token)
                    return(NULL)
                }
                runs <- lapply(payload_list, function(item) item$run %||% list(status = "engine_error", stderr = "empty result", segments = data.frame(stringsAsFactors = FALSE)))
                names(runs) <- vapply(payload_list, function(item) as.character(item$pid %||% ""), character(1))
                for (item in payload_list) {
                    lastz_dbg(sprintf("MP Step 6[%d]: query sequence", as.integer(item$idx %||% 0L)), data = item$query_seq_result %||% list())
                    result <- item$run %||% list()
                    if (!isTRUE(item$cache_hit) && nzchar(as.character(item$cache_key %||% ""))) {
                        set_lastz_alignment_cached_result(item$cache_key, result)
                    }
                    lastz_dbg(sprintf("MP Step 6[%d]: alignment result", as.integer(item$idx %||% 0L)), data = list(
                        pid = as.character(item$pid %||% ""),
                        status = as.character(result$status %||% ""),
                        n_segments = if (is.data.frame(result$segments)) nrow(result$segments) else 0L,
                        ref_width = as.integer(result$reference_width %||% 0L),
                        qry_width = as.integer(result$query_width %||% 0L),
                        cache_hit = isTRUE(item$cache_hit),
                        stderr = paste(as.character(result$stderr %||% ""), collapse = " ")
                    ))
                }
                finalize_multipip_async(runs, run_token)
                NULL
            }) %...!% (function(err) {
                current_token <- trimws(as.character(multipipLocalAlignmentTokenOrthologous() %||% ""))
                if (!identical(current_token, run_token)) {
                    lastz_dbg("MP stale promise_all error ignored", detail = sprintf("token=%s current=%s", run_token, current_token), level = "warn")
                    return(NULL)
                }
                err_msg <- trimws(as.character(conditionMessage(err) %||% as.character(err$message %||% "unknown error")))
                lastz_dbg("MP FATAL ERROR", detail = err_msg, level = "error")
                error_map <- lapply(query_ids_local, function(pid) {
                    list(status = "engine_error", stderr = err_msg, segments = data.frame(stringsAsFactors = FALSE))
                })
                names(error_map) <- query_ids_local
                finalize_multipip_async(error_map, run_token)
                NULL
            })
        }, ignoreInit = TRUE)

	    multipipLocalAlignmentRunsOrthologous <- reactive({
	        multipipLocalAlignmentRunsCacheOrthologous() %||% list()
	    })

        pipProcessedSceneCacheOrthologous <- reactiveVal(list())
        multipipProcessedSceneCacheOrthologous <- reactiveVal(list())

        read_density_limit <- function(env_name, default_value) {
            raw_txt <- trimws(as.character(Sys.getenv(as.character(env_name %||% ""), as.character(default_value %||% 0L)) %||% as.character(default_value %||% 0L)))
            parsed <- suppressWarnings(as.integer(raw_txt))
            if (!is.finite(parsed) || is.na(parsed) || parsed < 1L) {
                parsed <- as.integer(default_value %||% 0L)
            }
            parsed
        }

        update_scene_cache <- function(cache_rv, key, value, max_entries = 6L) {
            cache_map <- cache_rv() %||% list()
            if (key %in% names(cache_map)) {
                cache_map[[key]] <- NULL
            }
            cache_map[[key]] <- value
            if (length(cache_map) > max_entries) {
                keep_idx <- seq.int(max(1L, length(cache_map) - max_entries + 1L), length(cache_map))
                cache_map <- cache_map[keep_idx]
            }
            cache_rv(cache_map)
            value
        }

        build_pip_reference_feature_df <- function(ref_id,
                                                   ref_ctx,
                                                   display_rows,
                                                   ref_window_start,
                                                   ref_window_end) {
            ref_feature_df <- data.frame(stringsAsFactors = FALSE)
            ref_plot_data <- tryCatch(fileDataOrthologous()[[ref_id]], error = function(e) NULL)
            if (is.null(ref_plot_data)) {
                return(ref_feature_df)
            }
            ref_raw_df <- as.data.frame(ref_plot_data, stringsAsFactors = FALSE)
            if (nrow(ref_raw_df) == 0L) {
                return(ref_feature_df)
            }
            feature_type_raw <- tolower(trimws(as.character(ref_raw_df$V3 %||% rep("", nrow(ref_raw_df)))))
            ref_raw_df$feature_group <- ifelse(
                grepl("utr", feature_type_raw),
                "utr",
                ifelse(feature_type_raw %in% c("cds", "start_codon", "stop_codon"), "cds", ifelse(feature_type_raw == "exon", "exon", "other"))
            )
            ref_raw_df$feature_type_raw <- feature_type_raw
            ref_raw_df$xstart <- suppressWarnings(as.numeric(ref_raw_df$V4))
            ref_raw_df$xend <- suppressWarnings(as.numeric(ref_raw_df$V5))
            ref_raw_df <- ref_raw_df[
                ref_raw_df$feature_group %in% c("utr", "cds", "exon") &
                    is.finite(ref_raw_df$xstart) &
                    is.finite(ref_raw_df$xend),
                ,
                drop = FALSE
            ]
            if (nrow(ref_raw_df) == 0L) {
                return(ref_feature_df)
            }
            ref_raw_df$xstart_clip <- pmax(ref_window_start, pmin(ref_raw_df$xstart, ref_raw_df$xend))
            ref_raw_df$xend_clip <- pmin(ref_window_end, pmax(ref_raw_df$xstart, ref_raw_df$xend))
            ref_raw_df <- ref_raw_df[ref_raw_df$xend_clip >= ref_raw_df$xstart_clip, , drop = FALSE]
            if (nrow(ref_raw_df) == 0L) {
                return(ref_feature_df)
            }
            ref_strand <- trimws(as.character(ref_ctx$strand %||% "+"))
            ref_raw_df$feature_label <- ifelse(
                ref_raw_df$feature_group == "cds", "CDS",
                ifelse(ref_raw_df$feature_group == "utr", "UTR", "Exon")
            )
            ref_raw_df <- add_reference_display_range(
                ref_raw_df,
                window_start = ref_window_start,
                window_end = ref_window_end,
                strand = ref_strand
            )
            exon_src_df <- ref_raw_df[ref_raw_df$feature_group == "exon", , drop = FALSE]
            if (nrow(exon_src_df) > 0L) {
                if (identical(ref_strand, "-")) {
                    exon_src_df$exon_rank <- rank(-exon_src_df$xstart_clip, ties.method = "first")
                } else {
                    exon_src_df$exon_rank <- rank(exon_src_df$xstart_clip, ties.method = "first")
                }
                ref_raw_df$exon_rank <- NA_real_
                ref_raw_df$exon_rank[match(rownames(exon_src_df), rownames(ref_raw_df))] <- exon_src_df$exon_rank
                non_exon_idx <- which(is.na(ref_raw_df$exon_rank))
                if (length(non_exon_idx) > 0L) {
                    exon_starts <- suppressWarnings(as.numeric(exon_src_df$xstart_clip))
                    exon_ends <- suppressWarnings(as.numeric(exon_src_df$xend_clip))
                    exon_ranks <- suppressWarnings(as.numeric(exon_src_df$exon_rank))
                    ref_raw_df$exon_rank[non_exon_idx] <- vapply(non_exon_idx, function(i) {
                        cur_start <- suppressWarnings(as.numeric(ref_raw_df$xstart_clip[[i]]))
                        cur_end <- suppressWarnings(as.numeric(ref_raw_df$xend_clip[[i]]))
                        hits <- which(is.finite(exon_starts) & is.finite(exon_ends) & exon_starts <= cur_end & exon_ends >= cur_start)
                        if (length(hits) == 0L) return(NA_real_)
                        suppressWarnings(min(exon_ranks[hits], na.rm = TRUE))
                    }, numeric(1))
                }
            } else {
                ref_raw_df$exon_rank <- NA_real_
            }
            ref_raw_df$tooltip <- sprintf(
                paste0(
                    "<b>Reference annotation</b><br/>",
                    "<b>Track:</b> %s<br/>",
                    "<b>Feature:</b> %s<br/>",
                    "<b>Exon:</b> %s<br/>",
                    "<b>Locus:</b> %s:%s-%s bp<br/>",
                    "<b>Displayed span:</b> %s bp"
                ),
                display_rows$label[match(ref_id, display_rows$plot_id)],
                ref_raw_df$feature_label,
                ifelse(is.finite(ref_raw_df$exon_rank), paste0("Exon ", as.integer(round(ref_raw_df$exon_rank))), "N/A"),
                as.character(ref_ctx$seqid %||% ""),
                format(as.integer(round(pmin(ref_raw_df$xstart, ref_raw_df$xend))), big.mark = ","),
                format(as.integer(round(pmax(ref_raw_df$xstart, ref_raw_df$xend))), big.mark = ","),
                format(as.integer(round(ref_raw_df$xend_clip - ref_raw_df$xstart_clip + 1)), big.mark = ",")
            )
            ref_raw_df$data_id <- paste0("pip_ref_feature_", seq_len(nrow(ref_raw_df)))
            ref_raw_df
        }

        classify_pip_context_scene <- function(start_vec,
                                               end_vec,
                                               ref_feature_df,
                                               ref_gene_start_clip,
                                               ref_gene_end_clip) {
            n <- max(length(start_vec), length(end_vec))
            if (n == 0L) {
                return(character(0))
            }
            start_num <- suppressWarnings(as.numeric(pmin(start_vec, end_vec)))
            end_num <- suppressWarnings(as.numeric(pmax(start_vec, end_vec)))
            out <- rep("other", n)
            valid <- is.finite(start_num) & is.finite(end_num)
            if (!any(valid)) {
                return(out)
            }
            if (is.finite(ref_gene_start_clip) && is.finite(ref_gene_end_clip)) {
                gene_mask <- start_num <= ref_gene_end_clip & end_num >= ref_gene_start_clip
                out[gene_mask] <- "intron"
            }
            if (!is.data.frame(ref_feature_df) || nrow(ref_feature_df) == 0L || !requireNamespace("IRanges", quietly = TRUE)) {
                return(out)
            }
            seg_ir <- IRanges::IRanges(
                start = as.integer(round(start_num[valid])),
                end = as.integer(round(end_num[valid]))
            )
            valid_idx <- which(valid)
            cds_df <- ref_feature_df[ref_feature_df$feature_group == "cds", , drop = FALSE]
            noncoding_df <- ref_feature_df[ref_feature_df$feature_group %in% c("utr", "exon"), , drop = FALSE]
            if (nrow(noncoding_df) > 0L) {
                noncoding_hits <- IRanges::findOverlaps(
                    seg_ir,
                    IRanges::IRanges(start = noncoding_df$xstart_clip, end = noncoding_df$xend_clip)
                )
                out[valid_idx[unique(S4Vectors::queryHits(noncoding_hits))]] <- "utr_exon"
            }
            if (nrow(cds_df) > 0L) {
                cds_hits <- IRanges::findOverlaps(
                    seg_ir,
                    IRanges::IRanges(start = cds_df$xstart_clip, end = cds_df$xend_clip)
                )
                out[valid_idx[unique(S4Vectors::queryHits(cds_hits))]] <- "cds"
            }
            out
        }

        sample_guardrail_rows_by_reference <- function(df_in,
                                                       start_col,
                                                       end_col,
                                                       max_keep,
                                                       strand_col = NULL,
                                                       score_col = NULL,
                                                       identity_col = NULL,
                                                       width_col = NULL,
                                                       per_bin = 4L) {
            if (!is.data.frame(df_in) || nrow(df_in) == 0L) {
                return(data.frame(stringsAsFactors = FALSE))
            }
            max_keep <- suppressWarnings(as.integer(max_keep))
            if (!is.finite(max_keep) || is.na(max_keep) || max_keep < 1L || nrow(df_in) <= max_keep) {
                return(df_in)
            }
            per_bin <- suppressWarnings(as.integer(per_bin))
            if (!is.finite(per_bin) || is.na(per_bin) || per_bin < 1L) {
                per_bin <- 4L
            }

            start_num <- suppressWarnings(as.numeric(df_in[[start_col]] %||% NA_real_))
            end_num <- suppressWarnings(as.numeric(df_in[[end_col]] %||% NA_real_))
            mid_num <- (pmin(start_num, end_num) + pmax(start_num, end_num)) / 2
            valid_mid <- is.finite(mid_num)
            if (!any(valid_mid)) {
                return(utils::head(df_in, max_keep))
            }

            strand_vec <- if (!is.null(strand_col) && strand_col %in% names(df_in)) {
                trimws(as.character(df_in[[strand_col]] %||% "forward"))
            } else {
                rep("forward", nrow(df_in))
            }
            strand_vec[!nzchar(strand_vec)] <- "forward"
            score_num <- if (!is.null(score_col) && score_col %in% names(df_in)) {
                suppressWarnings(as.numeric(df_in[[score_col]]))
            } else {
                rep(NA_real_, nrow(df_in))
            }
            identity_num <- if (!is.null(identity_col) && identity_col %in% names(df_in)) {
                suppressWarnings(as.numeric(df_in[[identity_col]]))
            } else {
                rep(NA_real_, nrow(df_in))
            }
            width_num <- if (!is.null(width_col) && width_col %in% names(df_in)) {
                suppressWarnings(as.numeric(df_in[[width_col]]))
            } else {
                pmax(1, pmax(start_num, end_num) - pmin(start_num, end_num) + 1)
            }

            ref_min <- suppressWarnings(min(mid_num[valid_mid], na.rm = TRUE))
            ref_max <- suppressWarnings(max(mid_num[valid_mid], na.rm = TRUE))
            bin_count <- max(25L, min(600L, as.integer(ceiling(max_keep / per_bin))))
            span_den <- max(ref_max - ref_min, 1)
            bin_id <- ifelse(
                valid_mid,
                pmax(0L, pmin(bin_count - 1L, as.integer(floor(((mid_num - ref_min) / span_den) * bin_count)))),
                0L
            )

            if (requireNamespace("data.table", quietly = TRUE)) {
                dt <- data.table::as.data.table(df_in)
                dt[, row_id__ := seq_len(.N)]
                dt[, strand_group__ := strand_vec]
                dt[, score_rank__ := ifelse(is.finite(score_num), score_num, -Inf)]
                dt[, identity_rank__ := ifelse(is.finite(identity_num), identity_num, -Inf)]
                dt[, width_rank__ := ifelse(is.finite(width_num), width_num, -Inf)]
                dt[, ref_mid_bin__ := bin_id]
                data.table::setorderv(
                    dt,
                    cols = c("ref_mid_bin__", "strand_group__", "score_rank__", "identity_rank__", "width_rank__", "row_id__"),
                    order = c(1L, 1L, -1L, -1L, -1L, 1L)
                )
                keep_ids <- dt[, utils::head(row_id__, per_bin), by = c("ref_mid_bin__", "strand_group__")]$V1
                keep_ids <- unique(as.integer(keep_ids))
                if (length(keep_ids) > max_keep) {
                    dt_global <- data.table::copy(dt)
                    data.table::setorderv(
                        dt_global,
                        cols = c("score_rank__", "identity_rank__", "width_rank__", "row_id__"),
                        order = c(-1L, -1L, -1L, 1L)
                    )
                    keep_ids <- utils::head(dt_global$row_id__, max_keep)
                }
                out_df <- df_in[sort(keep_ids), , drop = FALSE]
                rownames(out_df) <- NULL
                return(out_df)
            }

            ord <- order(
                bin_id,
                strand_vec,
                -ifelse(is.finite(score_num), score_num, -Inf),
                -ifelse(is.finite(identity_num), identity_num, -Inf),
                -ifelse(is.finite(width_num), width_num, -Inf),
                seq_len(nrow(df_in))
            )
            df_ord <- df_in[ord, , drop = FALSE]
            grp_key <- paste0(bin_id[ord], "::", strand_vec[ord])
            keep_local <- unlist(lapply(split(seq_len(nrow(df_ord)), grp_key), function(idx) utils::head(idx, per_bin)), use.names = FALSE)
            keep_local <- sort(unique(keep_local))
            out_df <- df_ord[keep_local, , drop = FALSE]
            if (nrow(out_df) > max_keep) {
                score_keep <- score_num[ord][keep_local]
                identity_keep <- identity_num[ord][keep_local]
                width_keep <- width_num[ord][keep_local]
                global_ord <- order(
                    -ifelse(is.finite(score_keep), score_keep, -Inf),
                    -ifelse(is.finite(identity_keep), identity_keep, -Inf),
                    -ifelse(is.finite(width_keep), width_keep, -Inf)
                )
                out_df <- out_df[utils::head(global_ord, max_keep), , drop = FALSE]
            }
            rownames(out_df) <- NULL
            out_df
        }

        sample_pip_blocks_for_guardrail <- function(df_blocks, max_keep) {
            if (!is.data.frame(df_blocks) || nrow(df_blocks) == 0L) {
                return(data.frame(stringsAsFactors = FALSE))
            }
            n_total <- nrow(df_blocks)
            if (n_total <= max_keep) {
                return(df_blocks)
            }
            strand_col <- if ("strand_state" %in% names(df_blocks)) {
                "strand_state"
            } else if ("strand2" %in% names(df_blocks)) {
                df_blocks$strand_state <- ifelse(trimws(as.character(df_blocks$strand2 %||% "+")) == "-", "reverse", "forward")
                "strand_state"
            } else {
                df_blocks$strand_state <- "forward"
                "strand_state"
            }
            id_col <- if ("identity_pct" %in% names(df_blocks)) "identity_pct" else if ("identity_num" %in% names(df_blocks)) "identity_num" else NULL
            top_n <- max(0L, min(as.integer(floor(max_keep * 0.40)), n_total))
            if (!is.null(id_col) && top_n > 0L) {
                id_vals <- suppressWarnings(as.numeric(df_blocks[[id_col]]))
                id_vals[!is.finite(id_vals)] <- 0
                top_idx <- order(id_vals, decreasing = TRUE)[seq_len(top_n)]
                rest_idx <- setdiff(seq_len(n_total), top_idx)
                rest_df <- df_blocks[rest_idx, , drop = FALSE]
                rest_keep <- max(1L, max_keep - top_n)
            } else {
                top_idx <- integer(0)
                rest_df <- df_blocks
                rest_keep <- max_keep
            }
            rest_sampled <- sample_guardrail_rows_by_reference(
                df_in = rest_df,
                start_col = if ("ref_genomic_start" %in% names(df_blocks)) "ref_genomic_start" else "ref_start",
                end_col = if ("ref_genomic_end" %in% names(df_blocks)) "ref_genomic_end" else "ref_end",
                max_keep = rest_keep,
                strand_col = strand_col,
                score_col = if ("score" %in% names(df_blocks)) "score" else if ("score_num" %in% names(df_blocks)) "score_num" else NULL,
                identity_col = if ("identity_pct" %in% names(df_blocks)) "identity_pct" else if ("identity_num" %in% names(df_blocks)) "identity_num" else NULL,
                width_col = if ("align_len" %in% names(df_blocks)) "align_len" else if ("align_num" %in% names(df_blocks)) "align_num" else NULL,
                per_bin = 4L
            )
            if (length(top_idx) > 0L) {
                dplyr::bind_rows(df_blocks[top_idx, , drop = FALSE], rest_sampled)
            } else {
                rest_sampled
            }
        }

        sample_multipip_segments_for_guardrail <- function(df_segments, max_keep) {
            if (!is.data.frame(df_segments) || nrow(df_segments) == 0L) {
                return(data.frame(stringsAsFactors = FALSE))
            }
            # Always keep the top-identity segments first so the most conserved
            # regions are never dropped by the spatial stratification.
            n_total <- nrow(df_segments)
            if (n_total <= max_keep) return(df_segments)

            id_col <- if ("identity_pct" %in% names(df_segments)) "identity_pct" else NULL
            top_n  <- max(0L, min(as.integer(floor(max_keep * 0.40)), n_total))
            if (!is.null(id_col) && top_n > 0L) {
                id_vals   <- suppressWarnings(as.numeric(df_segments[[id_col]]))
                id_vals[!is.finite(id_vals)] <- 0
                top_idx   <- order(id_vals, decreasing = TRUE)[seq_len(top_n)]
                rest_idx  <- setdiff(seq_len(n_total), top_idx)
                rest_df   <- df_segments[rest_idx, , drop = FALSE]
                rest_keep <- max(1L, max_keep - top_n)
            } else {
                top_idx  <- integer(0)
                rest_df  <- df_segments
                rest_keep <- max_keep
            }

            # Stratified spatial sample for the remaining budget
            rest_sampled <- sample_guardrail_rows_by_reference(
                df_in      = rest_df,
                start_col  = "ref_start",
                end_col    = "ref_end",
                max_keep   = rest_keep,
                strand_col = if ("strand" %in% names(rest_df)) "strand" else NULL,
                score_col  = if ("score" %in% names(rest_df)) "score" else NULL,
                identity_col = if ("identity_pct" %in% names(rest_df)) "identity_pct" else NULL,
                width_col  = if ("segment_bp" %in% names(rest_df)) "segment_bp" else NULL,
                per_bin    = 8L
            )

            if (length(top_idx) > 0L) {
                dplyr::bind_rows(df_segments[top_idx, , drop = FALSE], rest_sampled)
            } else {
                rest_sampled
            }
        }

        pipProcessedSceneOrthologous <- reactive({
            ids_all <- as.character(pipOrderedPlotIdsOrthologous() %||% character(0))
            ids <- as.character(pipVisiblePlotIdsOrthologous() %||% character(0))
            if (length(ids) == 0L) {
                ids <- as.character(sortedPlotIdsOrthologous() %||% character(0))
                ids_all <- ids
            }
            ctx_map <- pipWindowTracksOrthologous() %||% list()
            ref_ctx <- pipReferenceWindowOrthologous()
            run_map <- pipLocalAlignmentRunsOrthologous() %||% list()
            ref_id <- trimws(as.character(pipReferencePlotIdOrthologous() %||% ""))
            span_mode <- trimws(as.character(input$ortho_pip_span %||% "gene"))
            span_label <- switch(
                span_mode,
                "gene" = "Gene only",
                "5kb" = "Gene + 5 kb",
                "25kb" = "Gene + 25 kb",
                "50kb" = "Gene + 50 kb",
                "Gene + 10 kb"
            )
            min_identity <- max(0, min(100, suppressWarnings(as.numeric(input$ortho_pip_min_identity %||% 70))))
            if (!is.finite(min_identity)) min_identity <- 70
            min_block_length <- suppressWarnings(as.integer(input$ortho_pip_min_length %||% 100))
            if (!is.finite(min_block_length)) min_block_length <- 100L
            cache_key <- stable_short_cache_key(
                "pip-scene-v2",
                pipLocalAlignmentRunStampOrthologous(),
                ref_id,
                ids_all,
                ids,
                span_mode,
                min_identity,
                min_block_length
            )
            cache_map <- pipProcessedSceneCacheOrthologous() %||% list()
            cached <- cache_map[[cache_key]] %||% NULL
            if (!is.null(cached)) {
                return(cached)
            }
            if (length(ids) == 0L) {
                empty_scene <- list(
                    ids = character(0),
                    ids_all = as.character(ids_all %||% character(0)),
                    ctx_map = ctx_map,
                    ref_ctx = ref_ctx,
                    ref_id = ref_id,
                    span_label = span_label,
                    min_identity = min_identity,
                    min_block_length = min_block_length,
                    display_rows = data.frame(stringsAsFactors = FALSE),
                    ref_window_start = 1,
                    ref_window_end = 100,
                    ref_window_span = 99,
                    ref_row_y = NA_real_,
                    ref_gene_start_clip = NA_real_,
                    ref_gene_end_clip = NA_real_,
                    ref_gene_center = 50.5,
                    ref_label_main = "Reference",
                    ref_label_sub = "",
                    ref_gene_dir_left = "5'",
                    ref_gene_dir_right = "3'",
                    row_band_df = data.frame(stringsAsFactors = FALSE),
                    track_label_df = data.frame(stringsAsFactors = FALSE),
                    ref_feature_df = data.frame(stringsAsFactors = FALSE),
                    blocks_df = data.frame(stringsAsFactors = FALSE),
                    run_stats = list(),
                    raw_block_total = 0L,
                    visible_block_total = 0L,
                    status_label = "No local alignment runs yet",
                    guardrail_triggered = FALSE,
                    guardrail_message = "",
                    guardrail_limit = read_density_limit("APP_PIP_MAX_RAW_BLOCKS", 2500L)
                )
                return(update_scene_cache(pipProcessedSceneCacheOrthologous, cache_key, empty_scene))
            }

            perf_run <- app_perf_new_run("ORTHO_PIP_SCENE")
            app_perf_mark(perf_run, sprintf("scene_start ids=%d", as.integer(length(ids))), "ORTHO_PIP")
            raw_block_total <- sum(vapply(run_map, function(x) {
                blk <- (x %||% list())$blocks
                if (is.data.frame(blk)) nrow(blk) else 0L
            }, integer(1)))
            guardrail_limit <- read_density_limit("APP_PIP_MAX_RAW_BLOCKS", 2500L)
            guardrail_triggered <- raw_block_total > guardrail_limit
            guardrail_message <- if (guardrail_triggered) {
                sprintf(
                    "High-density summary mode active: %d raw LASTZ blocks exceed the interactive limit of %d. The view is showing a prioritized subset across the reference locus so navigation stays fast and stable. Increase the identity/length filters or reduce the locus window if you want fuller detail.",
                    as.integer(raw_block_total),
                    as.integer(guardrail_limit)
                )
            } else {
                ""
            }

            display_rows <- data.frame(
                plot_id = ids,
                y = rev(seq_along(ids)),
                stringsAsFactors = FALSE
            )
            display_rows$is_reference <- display_rows$plot_id == ref_id
            display_rows$label <- vapply(display_rows$plot_id, function(pid) {
                ctx <- ctx_map[[pid]] %||% list()
                org_txt <- trimws(as.character(ctx$organism_name %||% ""))
                ttl_txt <- trimws(as.character(ctx$title %||% ""))
                label <- if (nzchar(org_txt)) org_txt else if (nzchar(ttl_txt)) ttl_txt else pid
                # For query organisms, append gene+strand and transcript_id as
                # additional label lines (displayed below organism on the y-axis).
                if (!identical(pid, ref_id)) {
                    gene_txt <- trimws(as.character(ctx$gene_label %||% ctx$matched_gene_id %||% ""))
                    strand_txt <- trimws(as.character(ctx$strand %||% ""))
                    if (!strand_txt %in% c("+", "-")) strand_txt <- ""
                    tx_txt <- trimws(as.character(ctx$transcript_id %||% ctx$transcript_label %||% ""))
                    if (nzchar(gene_txt)) {
                        gene_part <- paste0(gene_txt, if (nzchar(strand_txt)) paste0(" (", strand_txt, ")") else "")
                        label <- paste0(label, "\n", gene_part)
                    }
                    if (nzchar(tx_txt)) label <- paste0(label, "\n", tx_txt)
                }
                label
            }, character(1))
            display_rows$tooltip <- vapply(display_rows$plot_id, function(pid) {
                ctx <- ctx_map[[pid]] %||% list()
                seqid_txt <- as.character(ctx$seqid %||% "")
                gene_start <- suppressWarnings(as.integer(ctx$gene_start %||% NA_integer_))
                gene_end <- suppressWarnings(as.integer(ctx$gene_end %||% NA_integer_))
                win_start <- suppressWarnings(as.integer(ctx$window_start %||% NA_integer_))
                win_end <- suppressWarnings(as.integer(ctx$window_end %||% NA_integer_))
                strand_txt <- as.character(ctx$strand %||% "")
                base_txt <- paste0(
                    display_rows$label[match(pid, display_rows$plot_id)],
                    "<br/><b>Locus:</b> ", seqid_txt,
                    if (is.finite(gene_start) && is.finite(gene_end)) paste0("<br/><b>Gene span:</b> ", format(gene_start, big.mark = ","), "\u2013", format(gene_end, big.mark = ","), " bp") else "",
                    if (is.finite(win_start) && is.finite(win_end)) paste0("<br/><b>Window:</b> ", format(win_start, big.mark = ","), "\u2013", format(win_end, big.mark = ","), " bp") else "",
                    if (nzchar(strand_txt)) paste0("<br/><b>Strand:</b> ", strand_txt) else ""
                )
                if (identical(pid, ref_id)) {
                    paste0(base_txt, "<br/><b>Reference window</b><br/>Span mode: ", span_label)
                } else {
                    paste0(base_txt, "<br/><b>Query window scaffolded for LASTZ local blocks</b>")
                }
            }, character(1))

            pip_window_spec <- resolve_reference_display_window(
                ref_ctx = ref_ctx,
                span_mode = span_mode,
                default_start = ref_ctx$window_start %||% 1,
                default_end = ref_ctx$window_end %||% 100,
                pad_fraction = 0.03,
                min_pad_bp = 1L,
                prefer_transcript = TRUE
            )
            ref_window_start <- suppressWarnings(as.numeric(pip_window_spec$display_start %||% ref_ctx$window_start %||% 1))
            ref_window_end <- suppressWarnings(as.numeric(pip_window_spec$display_end %||% ref_ctx$window_end %||% 100))
            if (!is.finite(ref_window_start) || !is.finite(ref_window_end) || ref_window_end <= ref_window_start) {
                ref_window_start <- 1
                ref_window_end <- 100
            }
            display_rows$x <- ref_window_start
            display_rows$xend <- ref_window_end
            display_rows$data_id <- paste0("pip_track_", display_rows$plot_id)
            ref_row_y <- suppressWarnings(as.numeric(display_rows$y[match(ref_id, display_rows$plot_id)]))
            ref_gene_start_clip <- suppressWarnings(as.numeric(pip_window_spec$body_start %||% NA_real_))
            ref_gene_end_clip <- suppressWarnings(as.numeric(pip_window_spec$body_end %||% NA_real_))
            if (is.finite(ref_gene_start_clip) && is.finite(ref_gene_end_clip)) {
                ref_gene_start_clip <- max(ref_window_start, min(ref_gene_start_clip, ref_gene_end_clip))
                ref_gene_end_clip <- min(ref_window_end, max(ref_gene_start_clip, ref_gene_end_clip, na.rm = TRUE))
            }
            if (!is.finite(ref_gene_start_clip) || !is.finite(ref_gene_end_clip) || ref_gene_end_clip < ref_gene_start_clip) {
                ref_gene_start_clip <- NA_real_
                ref_gene_end_clip <- NA_real_
            }
            ref_window_span <- max(ref_window_end - ref_window_start, .Machine$double.eps)
            ref_gene_center <- if (is.finite(ref_gene_start_clip) && is.finite(ref_gene_end_clip)) {
                mean(c(ref_gene_start_clip, ref_gene_end_clip))
            } else {
                mean(c(ref_window_start, ref_window_end))
            }
            ref_gene_name <- trimws(as.character(ref_ctx$gene_label %||% ""))
            if (!nzchar(ref_gene_name)) {
                ref_gene_name <- trimws(as.character(ref_ctx$matched_gene_id %||% ""))
            }
            if (!nzchar(ref_gene_name)) {
                ref_gene_name <- display_rows$label[match(ref_id, display_rows$plot_id)]
            }
            ref_gene_strand <- trimws(as.character(ref_ctx$strand %||% ""))
            if (!ref_gene_strand %in% c("+", "-")) {
                ref_gene_strand <- ""
            }
            ref_label_main <- paste0(ref_gene_name, if (nzchar(ref_gene_strand)) paste0(" (", ref_gene_strand, ")") else "")
            ref_label_sub <- if (!is.null(ref_ctx)) {
                ref_seqid_txt <- trimws(as.character(ref_ctx$seqid %||% ""))
                tx_id_txt <- trimws(as.character(ref_ctx$transcript_id %||% ref_ctx$transcript_label %||% ""))
                if (nzchar(ref_seqid_txt) && nzchar(tx_id_txt)) {
                    paste0(ref_seqid_txt, " | ", tx_id_txt)
                } else if (nzchar(ref_seqid_txt)) {
                    ref_seqid_txt
                } else {
                    tx_id_txt
                }
            } else {
                ""
            }
            ref_gene_dir_left <- if (identical(ref_gene_strand, "-")) "3'" else "5'"
            ref_gene_dir_right <- if (identical(ref_gene_strand, "-")) "5'" else "3'"
            row_band_df <- data.frame(
                xmin = ref_window_start,
                xmax = ref_window_end,
                ymin = display_rows$y - 0.32,
                ymax = display_rows$y + 0.32,
                is_reference = display_rows$is_reference,
                is_even = seq_len(nrow(display_rows)) %% 2L == 0L,
                stringsAsFactors = FALSE
            )
            track_label_df <- do.call(rbind,  lapply(display_rows$plot_id[display_rows$plot_id != ref_id], function(pid) {
                ctx <- ctx_map[[pid]] %||% list()
                row_y <- suppressWarnings(as.numeric(display_rows$y[match(pid, display_rows$plot_id)]))
                if (!is.finite(row_y)) {
                    return(NULL)
                }
                gene_txt <- trimws(as.character(ctx$gene_label %||% ctx$matched_gene_id %||% ctx$title %||% ""))
                if (!nzchar(gene_txt)) {
                    return(NULL)
                }
                strand_txt <- trimws(as.character(ctx$strand %||% ""))
                if (!strand_txt %in% c("+", "-")) {
                    strand_txt <- ""
                }
                seqid_txt <- trimws(as.character(ctx$seqid %||% ""))
                data.frame(
                    plot_id = pid,
                    x = ref_window_end - 0.012 * ref_window_span,
                    y = row_y + 0.18,
                    label_main = paste0(gene_txt, if (nzchar(strand_txt)) paste0(" (", strand_txt, ")") else ""),
                    label_sub = if (nzchar(seqid_txt)) seqid_txt else "query locus",
                    tooltip = display_rows$tooltip[match(pid, display_rows$plot_id)],
                    data_id = paste0("pip_query_label_", pid),
                    stringsAsFactors = FALSE
                )
            }))
            if (!is.data.frame(track_label_df)) {
                track_label_df <- data.frame(stringsAsFactors = FALSE)
            }

            ref_feature_df <- build_pip_reference_feature_df(
                ref_id = ref_id,
                ref_ctx = ref_ctx,
                display_rows = display_rows,
                ref_window_start = ref_window_start,
                ref_window_end = ref_window_end
            )
            blocks_df <- data.frame(stringsAsFactors = FALSE)
            run_stats <- list()
            query_count <- max(1L, length(ids[ids != ref_id]))
            track_guardrail_budget <- max(200L, min(as.integer(guardrail_limit), as.integer(floor(guardrail_limit / query_count))))
            for (pid in ids[ids != ref_id]) {
                run_obj <- run_map[[pid]] %||% list()
                blk_raw <- run_obj$blocks
                total_blocks <- if (is.data.frame(blk_raw)) nrow(blk_raw) else 0L
                status_txt <- trimws(as.character(run_obj$status %||% "not-run"))
                ctx <- ctx_map[[pid]] %||% list()
                stderr_txt <- trimws(paste(as.character(run_obj$stderr %||% character(0)), collapse = " "))
                if (nchar(stderr_txt, type = "width") > 140L) {
                    stderr_txt <- paste0(substr(stderr_txt, 1L, 137L), "...")
                }
                stat_row <- list(
                    plot_id = pid,
                    status = status_txt,
                    total_blocks = total_blocks,
                    visible_blocks = NA_integer_,
                    chain_blocks = NA_integer_,
                    sampled_blocks = NA_integer_,
                    stderr_txt = stderr_txt,
                    seqid_txt = trimws(as.character(ctx$seqid %||% "")),
                    org_txt = trimws(as.character(ctx$organism_name %||% ctx$title %||% pid))
                )
                if (is.data.frame(blk_raw) && nrow(blk_raw) > 0L) {
                    row_y <- suppressWarnings(as.numeric(display_rows$y[match(pid, display_rows$plot_id)]))
                    if (is.finite(row_y)) {
                        blk_input <- if (guardrail_triggered) {
                            sample_pip_blocks_for_guardrail(blk_raw, max_keep = track_guardrail_budget)
                        } else {
                            blk_raw
                        }
                        stat_row$sampled_blocks <- if (is.data.frame(blk_input)) nrow(blk_input) else 0L
                        pip_blocks <- build_pip_display_blocks(
                            blk_input,
                            min_identity = min_identity,
                            min_block_length = min_block_length,
                            perf_run = perf_run,
                            perf_label = paste0("plot_", pid)
                        )
	                        blk <- if (isTRUE(guardrail_triggered)) {
	                            pip_blocks$display_blocks
	                        } else {
	                            pip_blocks$filtered_blocks
	                        }
	                        if (isTRUE(guardrail_triggered)) {
	                            blk <- prune_display_blocks_by_reference_dominance(
	                                blk,
	                                containment_threshold = 0.80,
	                                identity_slack = 0.10,
	                                respect_strand = FALSE
	                            )
	                        }
	                        chain_df <- pip_blocks$chained_blocks
                        stat_row$visible_blocks <- if (is.data.frame(blk)) nrow(blk) else 0L
                        stat_row$chain_blocks <- if (is.data.frame(chain_df) && "chain_id" %in% names(chain_df)) {
                            length(unique(stats::na.omit(chain_df$chain_id)))
                        } else {
                            0L
                        }
	                        if (is.data.frame(blk) && nrow(blk) > 0L) {
	                            blk$y <- row_y
	                            blk$query_label <- display_rows$label[match(pid, display_rows$plot_id)]
	                            if (!"component_count" %in% names(blk)) {
	                                blk$component_count <- 1L
	                            }
	                            blk$align_metric <- if ("align_num" %in% names(blk)) {
	                                suppressWarnings(as.numeric(blk$align_num))
	                            } else {
	                                suppressWarnings(as.numeric(blk$align_len))
	                            }
	                            blk$score_metric <- if ("score_num" %in% names(blk)) {
	                                suppressWarnings(as.numeric(blk$score_num))
	                            } else {
	                                suppressWarnings(as.numeric(blk$score))
	                            }
	                            if (!"covered_ref_bp" %in% names(blk)) {
	                                blk$covered_ref_bp <- blk$align_metric
	                            }
	                            if (!"covered_query_bp" %in% names(blk)) {
	                                blk$covered_query_bp <- blk$align_metric
	                            }
	                            blk$identity_num <- suppressWarnings(as.numeric(blk$identity_pct))
	                            blk$context_group <- classify_pip_context_scene(
	                                blk$ref_genomic_start,
                                blk$ref_genomic_end,
                                ref_feature_df = ref_feature_df,
                                ref_gene_start_clip = ref_gene_start_clip,
                                ref_gene_end_clip = ref_gene_end_clip
                            )
	                            blk$identity_clamped <- pmax(50, pmin(100, blk$identity_num))
	                            blk$y_pip <- row_y - 0.22 + 0.44 * ((blk$identity_clamped - 50) / 50)
	                            blk <- blk[order(
	                                suppressWarnings(as.numeric(blk$identity_num)),
	                                suppressWarnings(as.numeric(blk$align_metric)),
	                                suppressWarnings(as.numeric(blk$score_metric))
	                            ), , drop = FALSE]
                            blk$tooltip <- sprintf(
                                paste0(
                                    "<b>%s</b><br/>",
                                    "<b>Local LASTZ alignment block</b><br/>",
                                    "<b>Reference:</b> %s:%s-%s bp<br/>",
                                    "<b>Query:</b> %s:%s-%s bp<br/>",
                                    "<b>Orientation:</b> %s<br/>",
                                    "<b>Identity:</b> %.1f%%<br/>",
                                    "<b>Aligned length:</b> %s bp<br/>",
                                    "<b>PIP context:</b> %s<br/>",
                                    "<b>Reference covered span:</b> %s bp<br/>",
                                    "<b>Query covered span:</b> %s bp<br/>",
                                    "<b>LASTZ score:</b> %s"
                                ),
                                blk$query_label,
                                as.character(ref_ctx$seqid %||% ""),
                                format(as.integer(round(blk$ref_genomic_start)), big.mark = ","),
                                format(as.integer(round(blk$ref_genomic_end)), big.mark = ","),
                                as.character((ctx_map[[pid]] %||% list())$seqid %||% ""),
                                format(as.integer(round(blk$query_genomic_start)), big.mark = ","),
                                format(as.integer(round(blk$query_genomic_end)), big.mark = ","),
                                ifelse(blk$strand_state == "reverse", "reverse / inversion candidate", "forward"),
                                suppressWarnings(as.numeric(blk$identity_pct)),
                                format(as.integer(round(blk$align_len)), big.mark = ","),
                                dplyr::case_when(
                                    blk$context_group == "cds" ~ "coding exon overlap",
                                    blk$context_group == "utr_exon" ~ "non-coding exon / UTR overlap",
                                    blk$context_group == "intron" ~ "intragenic non-exonic overlap",
                                    TRUE ~ "outside annotated gene body"
                                ),
                                format(as.integer(round(blk$covered_ref_bp %||% blk$align_len)), big.mark = ","),
                                format(as.integer(round(blk$covered_query_bp %||% blk$align_len)), big.mark = ","),
                                ifelse(is.finite(suppressWarnings(as.numeric(blk$score))), format(as.integer(round(as.numeric(blk$score))), big.mark = ","), "N/A")
                            )
                            blk$data_id <- paste0("pip_block_", pid, "_", seq_len(nrow(blk)))
                            blocks_df <- dplyr::bind_rows(blocks_df, blk)
                        }
                    }
                }
                run_stats[[pid]] <- stat_row
            }
            status_counts <- table(vapply(run_map, function(x) as.character((x %||% list())$status %||% "unknown"), character(1)))
            status_label <- if (length(status_counts) > 0L) {
                paste(paste(names(status_counts), as.integer(status_counts), sep = ":"), collapse = " | ")
            } else {
                "No local alignment runs yet"
            }
            visible_block_total <- if (is.data.frame(blocks_df)) nrow(blocks_df) else 0L
            scene <- list(
                ids = ids,
                ids_all = ids_all,
                ctx_map = ctx_map,
                ref_ctx = ref_ctx,
                ref_id = ref_id,
                span_label = span_label,
                min_identity = min_identity,
                min_block_length = min_block_length,
                display_rows = display_rows,
                ref_window_start = ref_window_start,
                ref_window_end = ref_window_end,
                ref_window_span = ref_window_span,
                ref_row_y = ref_row_y,
                ref_gene_start_clip = ref_gene_start_clip,
                ref_gene_end_clip = ref_gene_end_clip,
                ref_gene_center = ref_gene_center,
                ref_label_main = ref_label_main,
                ref_label_sub = ref_label_sub,
                ref_gene_dir_left = ref_gene_dir_left,
                ref_gene_dir_right = ref_gene_dir_right,
                row_band_df = row_band_df,
                track_label_df = track_label_df,
                ref_feature_df = ref_feature_df,
                blocks_df = blocks_df,
                run_stats = run_stats,
                raw_block_total = raw_block_total,
                visible_block_total = visible_block_total,
                status_label = status_label,
                guardrail_triggered = guardrail_triggered,
                guardrail_message = guardrail_message,
                guardrail_limit = guardrail_limit,
                track_guardrail_budget = track_guardrail_budget
            )
            app_perf_mark(
                perf_run,
                sprintf("scene_done raw=%d visible=%d guardrail=%d", as.integer(raw_block_total), as.integer(visible_block_total), as.integer(guardrail_triggered)),
                "ORTHO_PIP"
            )
            update_scene_cache(pipProcessedSceneCacheOrthologous, cache_key, scene)
        })

        multipipProcessedSceneOrthologous <- reactive({
            ids <- as.character(multipipOrderedPlotIdsOrthologous() %||% character(0))
            ref_ctx <- multipipReferenceWindowOrthologous()
            if (length(ids) == 0L || is.null(ref_ctx)) {
                return(list(
                    ids = ids,
                    ref_ctx = ref_ctx,
                    display_rows = data.frame(stringsAsFactors = FALSE),
                    segments_df = data.frame(stringsAsFactors = FALSE),
                    run_stats = list(),
                    raw_segment_total = 0L,
                    visible_segment_total = 0L,
                    guardrail_triggered = FALSE,
                    guardrail_message = ""
                ))
            }
            run_map <- multipipLocalAlignmentRunsOrthologous() %||% list()
            ctx_map <- multipipWindowTracksOrthologous() %||% list()
            ref_id <- trimws(as.character(multipipReferencePlotIdOrthologous() %||% ""))
            min_identity <- max(50, min(100, suppressWarnings(as.numeric(input$ortho_multipip_min_identity %||% 70))))
            if (!is.finite(min_identity)) min_identity <- 70
            min_segment_bp <- suppressWarnings(as.integer(input$ortho_multipip_min_segment_bp %||% 25))
            if (!is.finite(min_segment_bp)) min_segment_bp <- 25L
            cache_key <- stable_short_cache_key(
                "multipip-scene-v2",
                multipipLocalAlignmentRunStampOrthologous(),
                ref_id,
                ids,
                trimws(as.character(input$ortho_multipip_span %||% "gene")),
                min_identity,
                min_segment_bp
            )
            cache_map <- multipipProcessedSceneCacheOrthologous() %||% list()
            cached <- cache_map[[cache_key]] %||% NULL
            if (!is.null(cached)) {
                return(cached)
            }

            perf_run <- app_perf_new_run("ORTHO_MULTIPIP_SCENE")
            app_perf_mark(perf_run, sprintf("scene_start ids=%d", as.integer(length(ids))), "ORTHO_MULTIPIP")
            raw_segment_total <- sum(vapply(run_map, function(x) {
                seg <- (x %||% list())$segments
                if (is.data.frame(seg)) nrow(seg) else 0L
            }, integer(1)))
            guardrail_limit <- read_density_limit("APP_MULTIPIP_MAX_RAW_SEGMENTS", 12000L)
            guardrail_triggered <- raw_segment_total > guardrail_limit
            # Note: the warning message is deferred — it is rebuilt after the pipeline
            # runs so it can report the actual VISIBLE segment count, not just the raw count.
            guardrail_message <- ""   # filled in after scene is built

            ref_window_start <- suppressWarnings(as.numeric(ref_ctx$window_start %||% 1))
            ref_window_end <- suppressWarnings(as.numeric(ref_ctx$window_end %||% 100))
            if (!is.finite(ref_window_start) || !is.finite(ref_window_end) || ref_window_end <= ref_window_start) {
                ref_window_start <- 1
                ref_window_end <- 100
            }
            ref_span <- max(ref_window_end - ref_window_start, .Machine$double.eps)
            display_rows <- data.frame(
                plot_id = ids,
                y = rev(seq_along(ids)),
                stringsAsFactors = FALSE
            )
            display_rows$is_reference <- display_rows$plot_id == ref_id
            display_rows$org_label <- vapply(display_rows$plot_id, function(pid) {
                ctx <- ctx_map[[pid]] %||% list()
                org_txt <- trimws(as.character(ctx$organism_name %||% ""))
                label <- if (nzchar(org_txt)) org_txt else pid
                # For query organisms, append gene+strand and transcript as additional
                # label lines so the full context is visible on the left y-axis.
                if (!identical(pid, ref_id)) {
                    gene_txt <- trimws(as.character(ctx$gene_label %||% ctx$matched_gene_id %||% ""))
                    strand_txt <- trimws(as.character(ctx$strand %||% ""))
                    if (!strand_txt %in% c("+", "-")) strand_txt <- ""
                    tx_txt <- trimws(as.character(ctx$transcript_id %||% ctx$transcript_label %||% ""))
                    if (nzchar(gene_txt)) {
                        gene_part <- paste0(gene_txt, if (nzchar(strand_txt)) paste0(" (", strand_txt, ")") else "")
                        label <- paste0(label, "\n", gene_part)
                    }
                    if (nzchar(tx_txt)) label <- paste0(label, "\n", tx_txt)
                }
                label
            }, character(1))
            display_rows$track_label <- vapply(display_rows$plot_id, function(pid) {
                ctx <- ctx_map[[pid]] %||% list()
                gene_txt <- trimws(as.character(ctx$gene_label %||% ctx$matched_gene_id %||% ctx$title %||% ""))
                strand_txt <- trimws(as.character(ctx$strand %||% ""))
                if (!strand_txt %in% c("+", "-")) strand_txt <- ""
                if (!nzchar(gene_txt)) gene_txt <- pid
                paste0(gene_txt, if (nzchar(strand_txt)) paste0(" (", strand_txt, ")") else "")
            }, character(1))
            display_rows$seqid_label <- vapply(display_rows$plot_id, function(pid) {
                trimws(as.character((ctx_map[[pid]] %||% list())$seqid %||% ""))
            }, character(1))
            ref_row_y <- suppressWarnings(as.numeric(display_rows$y[match(ref_id, display_rows$plot_id)]))
            ref_underlay <- build_multipip_underlay_features(
                ref_ctx = ref_ctx,
                ref_row_y = ref_row_y,
                feature_palette = list(cds = "#4F79BC", utr = "#D4B44A", exon = "#3EA77B"),
                feature_border = "#2C3E50"
            )
            ref_feature_df <- ref_underlay$all_df %||% NULL
            segments_df <- data.frame(stringsAsFactors = FALSE)
            run_stats <- list()
            query_count <- max(1L, length(ids[ids != ref_id]))
            # Per-track budget: divide the global limit evenly but guarantee
            # at least 1 000 segments per track so detail isn't lost on any species.
            track_guardrail_budget <- max(1000L, min(as.integer(guardrail_limit), as.integer(floor(guardrail_limit / query_count))))
            for (pid in ids[ids != ref_id]) {
                ctx <- ctx_map[[pid]] %||% list()
                run_obj <- run_map[[pid]] %||% list(status = "not-run")
                seg_df <- run_obj$segments
                stat_row <- list(
                    plot_id = pid,
                    status = trimws(as.character(run_obj$status %||% "not-run")),
                    total_segments = if (is.data.frame(seg_df)) nrow(seg_df) else 0L,
                    visible_segments = NA_integer_,
                    sampled_segments = NA_integer_,
                    seqid_txt = trimws(as.character(ctx$seqid %||% "N/A")),
                    org_txt = trimws(as.character(ctx$organism_name %||% pid))
                )
                if (is.data.frame(seg_df) && nrow(seg_df) > 0L) {
                    seg_input <- if (guardrail_triggered) {
                        sample_multipip_segments_for_guardrail(seg_df, max_keep = track_guardrail_budget)
                    } else {
                        seg_df
                    }
                    stat_row$sampled_segments <- if (is.data.frame(seg_input)) nrow(seg_input) else 0L
                    seg_view <- build_multipip_display_segments(
                        df_segments = seg_input,
                        min_identity = min_identity,
                        min_segment_bp = min_segment_bp,
                        ref_feature_df = ref_feature_df,
                        perf_run = perf_run,
                        perf_label = paste0("plot_", pid)
                    )
                    seg_pruned <- seg_view$pruned_segments
                    stat_row$visible_segments <- if (is.data.frame(seg_pruned)) nrow(seg_pruned) else 0L
                    if (is.data.frame(seg_pruned) && nrow(seg_pruned) > 0L) {
                        row_y <- suppressWarnings(as.numeric(display_rows$y[match(pid, display_rows$plot_id)]))
                        seg_pruned$identity_pct <- suppressWarnings(as.numeric(seg_pruned$identity_pct))
                        seg_pruned$segment_bp <- suppressWarnings(as.integer(seg_pruned$segment_bp))
                        seg_pruned$y <- row_y
                        seg_pruned$y_pip <- row_y - 0.24 + 0.48 * ((pmax(50, pmin(100, seg_pruned$identity_pct)) - 50) / 50)
                        seg_pruned$tooltip <- sprintf(
                            paste0(
                                "<b>%s</b><br/>",
                                "<b>Gap-free local LASTZ segment</b><br/>",
                                "<b>Reference:</b> %s:%s-%s bp<br/>",
                                "<b>Query:</b> %s:%s-%s bp<br/>",
                                "<b>Orientation:</b> %s<br/>",
                                "<b>Identity:</b> %.1f%%<br/>",
                                "<b>Segment length:</b> %s bp<br/>",
                                "<b>Reference context:</b> %s"
                            ),
                            display_rows$org_label[match(pid, display_rows$plot_id)],
                            as.character(ref_ctx$seqid %||% ""),
                            format(as.integer(round(seg_pruned$ref_start)), big.mark = ","),
                            format(as.integer(round(seg_pruned$ref_end)), big.mark = ","),
                            as.character((ctx_map[[pid]] %||% list())$seqid %||% ""),
                            format(as.integer(round(seg_pruned$qry_start)), big.mark = ","),
                            format(as.integer(round(seg_pruned$qry_end)), big.mark = ","),
                            ifelse(trimws(as.character(seg_pruned$strand %||% "+")) == "-", "reverse", "forward"),
                            seg_pruned$identity_pct,
                            format(as.integer(seg_pruned$segment_bp), big.mark = ","),
                            dplyr::case_when(
                                seg_pruned$underlay_context == "cds" ~ "coding exon",
                                seg_pruned$underlay_context == "noncoding_exon" ~ "non-coding exon / UTR",
                                seg_pruned$underlay_context == "intron_or_flank" ~ "intron or flanking DNA",
                                TRUE ~ "outside gene body"
                            )
                        )
                        seg_pruned$data_id <- paste0("multipip_seg_", pid, "_", seq_len(nrow(seg_pruned)))
                        segments_df <- dplyr::bind_rows(segments_df, seg_pruned)
                    }
                }
                run_stats[[pid]] <- stat_row
            }
            ref_gene_start <- suppressWarnings(as.numeric(ref_ctx$gene_start %||% NA_real_))
            ref_gene_end <- suppressWarnings(as.numeric(ref_ctx$gene_end %||% NA_real_))
            if (!is.finite(ref_gene_start) || !is.finite(ref_gene_end)) {
                ref_gene_start <- NA_real_
                ref_gene_end <- NA_real_
            }
            ref_gene_center <- if (is.finite(ref_gene_start) && is.finite(ref_gene_end)) {
                mean(c(ref_gene_start, ref_gene_end))
            } else {
                mean(c(ref_window_start, ref_window_end))
            }
            scene <- list(
                ids = ids,
                ctx_map = ctx_map,
                ref_ctx = ref_ctx,
                ref_id = ref_id,
                min_identity = min_identity,
                min_segment_bp = min_segment_bp,
                ref_window_start = ref_window_start,
                ref_window_end = ref_window_end,
                ref_span = ref_span,
                display_rows = display_rows,
                ref_row_y = ref_row_y,
                ref_underlay = ref_underlay,
                ref_feature_df = ref_feature_df,
                segments_df = segments_df,
                run_stats = run_stats,
                ref_gene_start = ref_gene_start,
                ref_gene_end = ref_gene_end,
                ref_gene_center = ref_gene_center,
                raw_segment_total = raw_segment_total,
                visible_segment_total = if (is.data.frame(segments_df)) nrow(segments_df) else 0L,
                guardrail_triggered = guardrail_triggered,
                guardrail_message = {
                    # Build the message AFTER the pipeline so we can report the
                    # actual rendered count, not the raw count.
                    vis <- if (is.data.frame(segments_df)) nrow(segments_df) else 0L
                    if (guardrail_triggered) {
                        sprintf(
                            paste0(
                                "Large dataset: %s raw gap-free segments were reduced to %s ",
                                "rendered segments via spatial sampling + merging. ",
                                "Visual quality is preserved. ",
                                "To see all detail, raise the identity filter or reduce the locus window."
                            ),
                            format(as.integer(raw_segment_total), big.mark = ","),
                            format(as.integer(vis), big.mark = ",")
                        )
                    } else {
                        ""
                    }
                },
                guardrail_limit = guardrail_limit,
                track_guardrail_budget = track_guardrail_budget
            )
            app_perf_mark(
                perf_run,
                sprintf("scene_done raw=%d visible=%d guardrail=%d", as.integer(raw_segment_total), as.integer(scene$visible_segment_total), as.integer(guardrail_triggered)),
                "ORTHO_MULTIPIP"
            )
            update_scene_cache(multipipProcessedSceneCacheOrthologous, cache_key, scene)
        })

	    # PIPELINE DE BÚSQUEDA
    # Ahora acepta use_parallel
    run_lookup_pipeline <- function(file_path, input_gene, det_info = NULL, status_rv = NULL, diagnostics = FALSE, use_parallel = TRUE, file_label = NULL, popup_context = NULL, popup_headline = NULL, perf_context = "LOOKUP_PIPE", allow_partial_suggestions = TRUE) {
        lookup_t0 <- app_perf_now()
        lookup_perf <- app_perf_new_run(perf_context)
        if (!is.null(status_rv)) status_rv(sprintf("Searching '%s'...", input_gene))
        popup_ctx <- trimws(as.character(popup_context %||% ""))
        popup_head <- trimws(as.character(popup_headline %||% ""))
        lookup_cache_key <- function(path, gene, organism = NULL, taxid = NULL, sources = character(0), mode = "default") {
            paste(
                "partial-suggestions-v3",
                normalizePath(as.character(path %||% ""), winslash = "/", mustWork = FALSE),
                tolower(trimws(as.character(gene %||% ""))),
                tolower(trimws(as.character(organism %||% ""))),
                as.character(suppressWarnings(as.integer(taxid %||% NA_integer_))),
                paste(sort(as.character(sources %||% character(0))), collapse = ","),
                tolower(trimws(as.character(mode %||% "default"))),
                sep = "||"
            )
        }
        remember_lookup <- function(key, value) {
            cache_env_set(lookupPipelineCache, key, value, max_size = 240L)
            invisible(value)
        }
        push_progress <- function(msg, append = TRUE) {
            txt <- trimws(as.character(msg %||% ""))
            if (!nzchar(txt)) {
                return(invisible(NULL))
            }
            if (!is.null(status_rv) && isTRUE(append)) {
                append_status(status_rv, txt)
            }
            if (nzchar(popup_ctx)) {
                set_popup_loading(TRUE, context = popup_ctx, text = txt, headline = popup_head)
            }
            invisible(NULL)
        }
        cached_lookup_has_data <- function(cached) {
            data <- tryCatch((cached %||% list())$data, error = function(e) NULL)
            is.data.frame(data) && nrow(data) > 0L
        }
        describe_cached_lookup <- function(cached, gene) {
            stage <- as.character((cached %||% list())$lookup_stage %||% "")
            if (isTRUE(cached_lookup_has_data(cached))) {
                display <- as.character((cached %||% list())$display_gene_name %||%
                    (cached %||% list())$matched_gene_name %||% gene)
                if (!nzchar(trimws(display))) {
                    display <- as.character(gene)
                }
                if (identical(stage, "external_alias")) {
                    sprintf("\u2022 Cache hit: gene '%s' was found via external alias (%s).", gene, display)
                } else if (identical(stage, "alias_index")) {
                    sprintf("\u2022 Cache hit: gene '%s' was found via local alias index (%s).", gene, display)
                } else if (identical(stage, "local_bridge")) {
                    sprintf("\u2022 Cache hit: gene '%s' was found via local alias metadata (%s).", gene, display)
                } else {
                    sprintf("\u2022 Cache hit: gene '%s' was found in the local annotation (%s).", gene, display)
                }
            } else if (identical(stage, "partial_suggestions")) {
                sprintf("\u2022 Cache hit: gene '%s' was not found as an exact gene; local partial suggestions are available.", gene)
            } else {
                sprintf("\u2022 Cache hit: gene '%s' was not found in the local annotation or enabled external alias sources.", gene)
            }
        }

        query_candidates_used <- normalize_lookup_query_candidates(c(input_gene))
        partial_cache_mode <- if (isTRUE(allow_partial_suggestions)) "initial" else "initial_external_forced"

        enabled_external_sources <- get_enabled_external_alias_sources()
        cache_key_initial <- lookup_cache_key(
            path = file_path,
            gene = input_gene,
            organism = det_info$organism %||% NULL,
            taxid = det_info$taxid %||% NULL,
            sources = enabled_external_sources,
            mode = partial_cache_mode
        )
        cached_initial <- cache_env_get(lookupPipelineCache, cache_key_initial, default = NULL)
        if (!is.null(cached_initial)) {
            cached <- cached_initial
            push_progress(describe_cached_lookup(cached, input_gene), append = TRUE)
            return(attach_lookup_result_meta(
                cached,
                query_candidates = cached$query_candidates %||% query_candidates_used,
                best_alias_used = cached$best_alias_used %||% "",
                input_gene = input_gene
            ))
        }

        get_partial_suggestions_for_query <- function(max_per_file = 20L, max_total = 20L) {
            if (!isTRUE(allow_partial_suggestions)) {
                return(empty_partial_gene_suggestions_df(source_labels = TRUE, source_label_preview = TRUE))
            }
            find_deterministic_partial_gene_suggestions(
                annotation_paths = file_path,
                query = input_gene,
                file_labels = file_label %||% basename(file_path),
                det_list = list(det_info %||% list()),
                max_per_file = max_per_file,
                max_total = max_total,
                min_query_chars = 2L,
                min_shared_organisms = 1L,
                include_alias_sql = TRUE,
                base_dir = "."
            )
        }
        return_partial_suggestions <- function(progress_message, suggestions) {
            push_progress(progress_message)
            nohit <- attach_lookup_result_meta(
                list(data = NULL, matched_gene_id = NA_character_, matched_gene_name = NA_character_),
                query_candidates = query_candidates_used,
                best_alias_used = "",
                input_gene = input_gene
            )
            nohit$external_lookup_had_errors <- FALSE
            nohit$det_resolved <- det_info
            nohit$lookup_elapsed_ms <- app_perf_elapsed_ms(lookup_t0)
            nohit$lookup_stage <- "partial_suggestions"
            nohit$partial_gene_suggestions <- suggestions
            remember_lookup(cache_key_initial, nohit)
            return(nohit)
        }
        operation_alias_index_lookup <- NULL
        if (exists("make_operation_alias_index_lookup", mode = "function") &&
            exists("search_alias_index_for_context", mode = "function")) {
            operation_alias_index_lookup <- tryCatch(
                make_operation_alias_index_lookup(
                    query = input_gene,
                    file_path = file_path,
                    file_label = file_label,
                    base_dir = ".",
                    lookup_fun = get("search_alias_index_for_context", mode = "function")
                ),
                error = function(e) NULL
            )
        }
        lookup_alias_index_for_operation <- function(det_resolved) {
            if (is.function(operation_alias_index_lookup)) {
                return(operation_alias_index_lookup(det_resolved))
            }
            list(
                result = search_alias_index_for_context(
                    query = input_gene,
                    file_path = file_path,
                    det_info = det_resolved,
                    file_label = file_label,
                    base_dir = "."
                ),
                reused = FALSE
            )
        }
        alias_index_preflight <- function(det_resolved) {
            det <- det_resolved %||% list()
            org_id <- trimws(as.character(det$species_id %||% det$preloaded_id %||% ""))
            if (!nzchar(org_id) ||
                !exists("search_alias_index_for_context", mode = "function") ||
                !exists("alias_index_match_to_lookup", mode = "function")) {
                return(NULL)
            }
            alias_index_t0 <- app_perf_now()
            push_progress(sprintf("\u2022 Local alias index preflight for '%s'...", input_gene))
            alias_index_attempt <- tryCatch(
                lookup_alias_index_for_operation(det),
                error = function(e) {
                    app_debug_log("[AliasIndex] preflight failed: ", e$message)
                    NULL
                }
            )
            alias_index_res <- (alias_index_attempt %||% list())$result
            alias_index_status <- as.character((alias_index_res %||% list())$status %||% "no_match")
            alias_index_matches <- (alias_index_res %||% list())$matches
            if (!isTRUE((alias_index_attempt %||% list())$reused)) {
                app_perf_mark_ms(lookup_perf, "lookup_alias_index_ms", app_perf_elapsed_ms(alias_index_t0), perf_context)
            }
            if (startsWith(alias_index_status, "multiple") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                push_progress(sprintf("\u2022 Local alias index found %d possible genes; user selection is required.", nrow(alias_index_matches)))
                nohit <- attach_lookup_result_meta(
                    list(data = NULL, matched_gene_id = NA_character_, matched_gene_name = NA_character_),
                    query_candidates = query_candidates_used,
                    best_alias_used = "",
                    input_gene = input_gene
                )
                nohit$external_lookup_had_errors <- FALSE
                nohit$det_resolved <- det
                nohit$lookup_elapsed_ms <- app_perf_elapsed_ms(lookup_t0)
                nohit$lookup_stage <- "alias_index_ambiguous"
                nohit$alias_index_status <- alias_index_status
                nohit$alias_index_matches <- alias_index_matches
                return(nohit)
            } else if (startsWith(alias_index_status, "unique") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                selected_alias_match <- alias_index_matches[1, , drop = FALSE]
                selected_role <- as.character(selected_alias_match$match_role[1] %||% "")
                alias_fast_t0 <- app_perf_now()
                alias_lookup <- tryCatch(
                    alias_index_match_to_lookup(selected_alias_match, file_path = file_path, input_gene = input_gene),
                    error = function(e) NULL
                )
                app_perf_mark_ms(lookup_perf, "lookup_alias_fast_region_ms", app_perf_elapsed_ms(alias_fast_t0), perf_context)
                app_perf_mark(
                    lookup_perf,
                    sprintf("alias fast candidate role=%s rows=%d", selected_role, as.integer(nrow((alias_lookup %||% list())$data %||% data.frame()))),
                    perf_context
                )
                if (!is.null(alias_lookup$data) && is.data.frame(alias_lookup$data) && nrow(alias_lookup$data) > 0L) {
                    query_candidates_used <<- normalize_lookup_query_candidates(c(
                        query_candidates_used,
                        selected_alias_match$query_term_original,
                        selected_alias_match$local_gene_id,
                        selected_alias_match$local_symbol
                    ))
                    best_res <- attach_lookup_result_meta(
                        alias_lookup,
                        query_candidates = query_candidates_used,
                        best_alias_used = as.character(selected_alias_match$query_term_original[1] %||% ""),
                        input_gene = input_gene
                    )
                    best_res$lookup_stage <- "alias_index"
                    best_res$alias_index_status <- alias_index_status
                    best_res$alias_index_match <- selected_alias_match
                    best_res$external_lookup_had_errors <- FALSE
                    best_res$det_resolved <- det
                    best_res$lookup_elapsed_ms <- app_perf_elapsed_ms(lookup_t0)
                    push_progress(sprintf(
                        "\u2022 CGeV resolved '%s' as %s using the local alias index.",
                        input_gene,
                        as.character(best_res$matched_gene_id %||% best_res$matched_gene_name %||% selected_alias_match$local_gene_id[1] %||% "")
                    ))
                    remember_lookup(cache_key_initial, best_res)
                    return(best_res)
                }
            }
            NULL
        }

        preflight_lookup <- alias_index_preflight(det_info)
        if (!is.null(preflight_lookup)) {
            return(preflight_lookup)
        }

        # 1) local exact
        local_exact_t0 <- app_perf_now()
        push_progress(sprintf("\u2022 Step 1 of 3: Local exact lookup for '%s'...", input_gene))
        res <- search_gene_in_file(file_path, input_gene, show_diagnostics = FALSE, match_mode = "exact", return_meta = TRUE)
        app_perf_mark_ms(lookup_perf, "lookup_local_exact_ms", app_perf_elapsed_ms(local_exact_t0), perf_context)
        if (!is.null(res$data) && nrow(res$data) > 0) {
            app_perf_mark_ms(lookup_perf, "lookup_external_alias_ms", 0, perf_context)
            app_perf_mark_ms(lookup_perf, "lookup_local_flex_ms", 0, perf_context)
            push_progress(sprintf("\u2022 Local exact match found for '%s'.", input_gene))
            res <- attach_lookup_result_meta(res, query_candidates = query_candidates_used, best_alias_used = "", input_gene = input_gene)
            remember_lookup(cache_key_initial, res)
            return(res)
        }

        partial_suggestions_for_query <- get_partial_suggestions_for_query(max_per_file = 20L, max_total = 20L)
        if (is.data.frame(partial_suggestions_for_query) && nrow(partial_suggestions_for_query) > 0L) {
            return(return_partial_suggestions(sprintf(
                "\u2022 No exact local match for '%s'; showing local gene-name suggestions before trying broader alias matches.",
                input_gene
            ), partial_suggestions_for_query))
        }

        if (isTRUE(allow_partial_suggestions)) {
            # 2) local flexible before any external rescue.
            local_flex_t0 <- app_perf_now()
            push_progress(sprintf("\u2022 Step 2 of 3: Local flexible lookup for '%s'...", input_gene))
            res <- search_gene_in_file(file_path, input_gene, show_diagnostics = diagnostics, match_mode = "flex", return_meta = TRUE)
            app_perf_mark_ms(lookup_perf, "lookup_local_flex_ms", app_perf_elapsed_ms(local_flex_t0), perf_context)
            if (!is.null(res$data) && nrow(res$data) > 0) {
                app_perf_mark_ms(lookup_perf, "lookup_external_alias_ms", 0, perf_context)
                push_progress(sprintf("\u2022 Local flexible match found for '%s'.", input_gene))
                res <- attach_lookup_result_meta(res, query_candidates = query_candidates_used, best_alias_used = "", input_gene = input_gene)
                remember_lookup(cache_key_initial, res)
                return(res)
            }
        } else {
            app_perf_mark_ms(lookup_perf, "lookup_local_flex_ms", 0, perf_context)
            push_progress(sprintf("\u2022 Step 2 of 3: Local flexible lookup skipped; checking external aliases for '%s'.", input_gene))
        }

        # 3) external aliases + local exact rescue for local no-matches.
        det_resolved <- det_info
        det_has_info <- !is.null(det_resolved) && (!is.null(det_resolved$organism) || !is.null(det_resolved$taxid))
        if (!det_has_info) {
            det_fallback <- tryCatch(
                detect_organism_from_gff(file_path, original_name = file_label %||% basename(file_path)),
                error = function(e) list(organism = NULL, taxid = NULL, source = "none")
            )
            if (!is.null(det_fallback$organism) || !is.null(det_fallback$taxid)) {
                det_resolved <- det_fallback
                det_label <- format_org_name(as.character(det_fallback$organism %||% ""), as.character(det_fallback$taxid %||% "unknown organism"))
                push_progress(sprintf("\u2022 External context: %s.", det_label))
            }
        }
        org <- if (!is.null(det_resolved)) det_resolved$organism else NULL
        tx <- if (!is.null(det_resolved)) det_resolved$taxid else NULL
        cache_key_resolved <- lookup_cache_key(
            path = file_path,
            gene = input_gene,
            organism = det_resolved$organism %||% NULL,
            taxid = det_resolved$taxid %||% NULL,
            sources = enabled_external_sources,
            mode = if (isTRUE(allow_partial_suggestions)) "resolved" else "resolved_external_forced"
        )
        if (!identical(cache_key_resolved, cache_key_initial)) {
            cached_resolved <- cache_env_get(lookupPipelineCache, cache_key_resolved, default = NULL)
            if (!is.null(cached_resolved)) {
                cached <- cached_resolved
                push_progress(describe_cached_lookup(cached, input_gene), append = TRUE)
                cached <- attach_lookup_result_meta(
                    cached,
                    query_candidates = cached$query_candidates %||% query_candidates_used,
                    best_alias_used = cached$best_alias_used %||% "",
                    input_gene = input_gene
                )
                remember_lookup(cache_key_initial, cached)
                return(cached)
            }
        }

        if (length(enabled_external_sources) == 0) {
            push_progress("\u2022 Step 3 of 3: External alias lookup skipped (all external sources disabled in Settings).")
        } else if (is.null(org) && is.null(tx)) {
            push_progress("\u2022 Step 3 of 3: External alias lookup skipped (organism metadata unavailable).")
        } else {
            push_progress(sprintf(
                "\u2022 Step 3 of 3: External alias lookup, fastest sources first (%s)...",
                format_external_alias_sources(enabled_external_sources)
            ))
        }

        query_candidates_used <- normalize_lookup_query_candidates(c(input_gene))
        alias_bridge <- list(found = FALSE, alias_candidates = character(0))
        external_lookup_had_errors <- FALSE
        alias_index_checked <- FALSE
        external_alias_t0 <- app_perf_now()

        if (exists("search_alias_index_for_context", mode = "function") &&
            exists("alias_index_match_to_lookup", mode = "function")) {
            alias_index_checked <- TRUE
            alias_index_t0 <- app_perf_now()
            push_progress(sprintf("\u2022 Local alias index lookup for '%s'...", input_gene))
            alias_index_attempt <- tryCatch(
                lookup_alias_index_for_operation(det_resolved),
                error = function(e) {
                    app_debug_log("[AliasIndex] lookup failed: ", e$message)
                    NULL
                }
            )
            alias_index_res <- (alias_index_attempt %||% list())$result
            alias_index_status <- as.character((alias_index_res %||% list())$status %||% "no_match")
            alias_index_matches <- (alias_index_res %||% list())$matches
            if (!isTRUE((alias_index_attempt %||% list())$reused)) {
                app_perf_mark_ms(lookup_perf, "lookup_alias_index_ms", app_perf_elapsed_ms(alias_index_t0), perf_context)
            }
            if (startsWith(alias_index_status, "multiple") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                push_progress(sprintf("\u2022 Local alias index found %d possible genes; user selection is required.", nrow(alias_index_matches)))
                nohit <- attach_lookup_result_meta(
                    list(data = NULL, matched_gene_id = NA_character_, matched_gene_name = NA_character_),
                    query_candidates = query_candidates_used,
                    best_alias_used = "",
                    input_gene = input_gene
                )
                nohit$external_lookup_had_errors <- FALSE
                nohit$det_resolved <- det_resolved
                nohit$lookup_elapsed_ms <- app_perf_elapsed_ms(lookup_t0)
                nohit$lookup_stage <- "alias_index_ambiguous"
                nohit$alias_index_status <- alias_index_status
                nohit$alias_index_matches <- alias_index_matches
                return(nohit)
            }
            if (startsWith(alias_index_status, "unique") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                selected_alias_match <- alias_index_matches[1, , drop = FALSE]
                selected_conf <- toupper(as.character(selected_alias_match$confidence[1] %||% ""))
                if (selected_conf %in% c("HIGH", "MEDIUM") ||
                    isTRUE(is_verified_local_description_alias_match(selected_alias_match))) {
                    alias_lookup <- tryCatch(
                        alias_index_match_to_lookup(selected_alias_match, file_path = file_path, input_gene = input_gene),
                        error = function(e) NULL
                    )
                    if (!is.null(alias_lookup$data) && is.data.frame(alias_lookup$data) && nrow(alias_lookup$data) > 0L) {
                        query_candidates_used <- normalize_lookup_query_candidates(c(
                            query_candidates_used,
                            selected_alias_match$query_term_original,
                            selected_alias_match$local_gene_id,
                            selected_alias_match$local_symbol
                        ))
                        best_res <- attach_lookup_result_meta(
                            alias_lookup,
                            query_candidates = query_candidates_used,
                            best_alias_used = as.character(selected_alias_match$query_term_original[1] %||% ""),
                            input_gene = input_gene
                        )
                        best_res$lookup_stage <- "alias_index"
                        best_res$alias_index_status <- alias_index_status
                        best_res$alias_index_match <- selected_alias_match
                        push_progress(sprintf(
                            "\u2022 CGeV resolved '%s' as alias of %s using the local alias index.",
                            input_gene,
                            as.character(best_res$matched_gene_id %||% best_res$matched_gene_name %||% selected_alias_match$local_gene_id[1] %||% "")
                        ))
                        remember_lookup(cache_key_initial, best_res)
                        remember_lookup(cache_key_resolved, best_res)
                        return(best_res)
                    }
                }
            }
            if (identical(alias_index_status, "no_match")) {
                push_progress("\u2022 Local alias index did not find a match.")
            }
        }

        local_bridge_candidates <- build_gene_query_candidates(
            gene_name = input_gene,
            organism = org,
            taxid = tx,
            status_callback = NULL,
            max_aliases = 100,
            use_parallel = FALSE,
            alias_sources = character(0)
        )
        local_bridge_new_candidates <- setdiff(
            normalize_lookup_query_candidates(c(local_bridge_candidates)),
            query_candidates_used
        )
        if (length(local_bridge_new_candidates) > 0L) {
            app_perf_mark(
                lookup_perf,
                sprintf("local_alias_bridge_preflight candidates=%d", as.integer(length(local_bridge_new_candidates))),
                perf_context
            )
            alias_bridge <- resolve_external_alias_bridge(
                input_gene = input_gene,
                query_candidates = local_bridge_new_candidates,
                file_path = file_path,
                organism = org,
                taxid = tx,
                search_fun = search_gene_in_file
            )
            query_candidates_used <- normalize_lookup_query_candidates(c(query_candidates_used, local_bridge_candidates))
            if (isTRUE(alias_bridge$found)) {
                app_perf_mark_ms(lookup_perf, "lookup_external_alias_ms", app_perf_elapsed_ms(external_alias_t0), perf_context)
                best_res <- attach_lookup_result_meta(
                    alias_bridge$result,
                    query_candidates = query_candidates_used,
                    best_alias_used = alias_bridge$best_alias_used,
                    input_gene = input_gene
                )
                best_res$lookup_stage <- "local_bridge"
                push_progress(sprintf("\u2022 Match found via local alias metadata: %s.", as.character(best_res$display_gene_name %||% best_res$matched_gene_name %||% input_gene)))
                remember_lookup(cache_key_initial, best_res)
                remember_lookup(cache_key_resolved, best_res)
                return(best_res)
            }
            app_perf_mark(lookup_perf, "local_alias_bridge_preflight_no_match", perf_context)
        }

        if (!isTRUE(alias_index_checked) &&
            exists("search_alias_index_for_context", mode = "function") &&
            exists("alias_index_match_to_lookup", mode = "function")) {
            alias_index_t0 <- app_perf_now()
            push_progress(sprintf("\u2022 Local alias index lookup for '%s'...", input_gene))
            alias_index_attempt <- tryCatch(
                lookup_alias_index_for_operation(det_resolved),
                error = function(e) {
                    app_debug_log("[AliasIndex] lookup failed: ", e$message)
                    NULL
                }
            )
            alias_index_res <- (alias_index_attempt %||% list())$result
            alias_index_status <- as.character((alias_index_res %||% list())$status %||% "no_match")
            alias_index_matches <- (alias_index_res %||% list())$matches
            if (!isTRUE((alias_index_attempt %||% list())$reused)) {
                app_perf_mark_ms(lookup_perf, "lookup_alias_index_ms", app_perf_elapsed_ms(alias_index_t0), perf_context)
            }
            if (startsWith(alias_index_status, "multiple") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                push_progress(sprintf("\u2022 Local alias index found %d possible genes; user selection is required.", nrow(alias_index_matches)))
                nohit <- attach_lookup_result_meta(
                    list(data = NULL, matched_gene_id = NA_character_, matched_gene_name = NA_character_),
                    query_candidates = query_candidates_used,
                    best_alias_used = "",
                    input_gene = input_gene
                )
                nohit$external_lookup_had_errors <- FALSE
                nohit$det_resolved <- det_resolved
                nohit$lookup_elapsed_ms <- app_perf_elapsed_ms(lookup_t0)
                nohit$lookup_stage <- "alias_index_ambiguous"
                nohit$alias_index_status <- alias_index_status
                nohit$alias_index_matches <- alias_index_matches
                return(nohit)
            }
            if (startsWith(alias_index_status, "unique") &&
                is.data.frame(alias_index_matches) && nrow(alias_index_matches) > 0L) {
                selected_alias_match <- alias_index_matches[1, , drop = FALSE]
                selected_conf <- toupper(as.character(selected_alias_match$confidence[1] %||% ""))
                if (selected_conf %in% c("HIGH", "MEDIUM") ||
                    isTRUE(is_verified_local_description_alias_match(selected_alias_match))) {
                    alias_lookup <- tryCatch(
                        alias_index_match_to_lookup(selected_alias_match, file_path = file_path, input_gene = input_gene),
                        error = function(e) NULL
                    )
                    if (!is.null(alias_lookup$data) && is.data.frame(alias_lookup$data) && nrow(alias_lookup$data) > 0L) {
                        query_candidates_used <- normalize_lookup_query_candidates(c(
                            query_candidates_used,
                            selected_alias_match$query_term_original,
                            selected_alias_match$local_gene_id,
                            selected_alias_match$local_symbol
                        ))
                        best_res <- attach_lookup_result_meta(
                            alias_lookup,
                            query_candidates = query_candidates_used,
                            best_alias_used = as.character(selected_alias_match$query_term_original[1] %||% ""),
                            input_gene = input_gene
                        )
                        best_res$lookup_stage <- "alias_index"
                        best_res$alias_index_status <- alias_index_status
                        best_res$alias_index_match <- selected_alias_match
                        push_progress(sprintf(
                            "\u2022 CGeV resolved '%s' as alias of %s using the local alias index.",
                            input_gene,
                            as.character(best_res$matched_gene_id %||% best_res$matched_gene_name %||% selected_alias_match$local_gene_id[1] %||% "")
                        ))
                        remember_lookup(cache_key_initial, best_res)
                        remember_lookup(cache_key_resolved, best_res)
                        return(best_res)
                    }
                }
            }
            if (identical(alias_index_status, "no_match")) {
                push_progress("\u2022 Local alias index did not find a match.")
            }
        }

        fast_sources <- intersect(c("mygene", "uniprot"), enabled_external_sources)
        slow_sources <- intersect(c("ncbi", "ensembl"), enabled_external_sources)
        all_sources <- order_external_alias_sources_for_speed(unique(c(fast_sources, slow_sources)))

        if (length(all_sources) > 0L) {
            push_progress(sprintf(
                "\u2022 External alias lookup (parallel sources: %s)...",
                format_external_alias_sources(all_sources)
            ))
            query_candidates_phase <- build_gene_query_candidates(
                gene_name = input_gene,
                organism = org,
                taxid = tx,
                status_callback = function(m) push_progress(m),
                max_aliases = 100,
                use_parallel = use_parallel,
                alias_sources = all_sources
            )
            phase_lookup_meta <- attr(query_candidates_phase, "external_lookup_meta", exact = TRUE)
            if (isTRUE((phase_lookup_meta %||% list())$had_errors)) {
                external_lookup_had_errors <- TRUE
            }
            previous_candidates <- query_candidates_used
            query_candidates_used <- normalize_lookup_query_candidates(c(query_candidates_used, query_candidates_phase))
            if (length(query_candidates_used) == 0) {
                query_candidates_used <- normalize_lookup_query_candidates(c(input_gene))
            }
            new_alias_candidates <- setdiff(query_candidates_used, previous_candidates)
            if (length(new_alias_candidates) == 0L) {
                app_perf_mark(
                    lookup_perf,
                    sprintf(
                        "external_alias_bridge_skipped_no_new_alias source=%s",
                        paste(all_sources, collapse = ",")
                    ),
                    perf_context
                )
                push_progress("\u2022 External sources returned no new aliases to test locally.")
            } else {
                alias_bridge <- resolve_external_alias_bridge(
                    input_gene = input_gene,
                    query_candidates = new_alias_candidates,
                    file_path = file_path,
                    organism = org,
                    taxid = tx,
                    search_fun = search_gene_in_file
                )
                if (length(alias_bridge$alias_candidates) > 0) {
                    push_progress(sprintf("\u2022 Reviewing %d alias candidate(s) in local annotation...", length(alias_bridge$alias_candidates)))
                }

                if (isTRUE(alias_bridge$found)) {
                    app_perf_mark_ms(lookup_perf, "lookup_external_alias_ms", app_perf_elapsed_ms(external_alias_t0), perf_context)
                    best_res <- attach_lookup_result_meta(
                        alias_bridge$result,
                        query_candidates = query_candidates_used,
                        best_alias_used = alias_bridge$best_alias_used,
                        input_gene = input_gene
                    )
                    best_res$external_alias_source <- all_sources
                    best_res$lookup_stage <- "external_alias"
                    push_progress(sprintf(
                        "\u2022 Match found via external alias '%s': %s.",
                        as.character(alias_bridge$best_alias_used %||% ""),
                        as.character(best_res$display_gene_name %||% best_res$matched_gene_name %||% input_gene)
                    ))
                    remember_lookup(cache_key_initial, best_res)
                    remember_lookup(cache_key_resolved, best_res)
                    return(best_res)
                }
                push_progress("\u2022 External alias bridge unresolved after parallel sources.")
            }
        }
        app_perf_mark_ms(lookup_perf, "lookup_external_alias_ms", app_perf_elapsed_ms(external_alias_t0), perf_context)

        if (length(alias_bridge$alias_candidates) == 0) {
            push_progress("\u2022 No external aliases found.")
        } else {
            push_progress("\u2022 External aliases did not yield a local coordinate match.")
        }

        push_progress(sprintf("\u2022 No local or external match found for '%s'.", input_gene))
        nohit <- attach_lookup_result_meta(
            list(data = NULL, matched_gene_id = NA_character_, matched_gene_name = NA_character_),
            query_candidates = query_candidates_used,
            best_alias_used = "",
            input_gene = input_gene
        )
        nohit$external_lookup_had_errors <- isTRUE(external_lookup_had_errors)
        if (!isTRUE(external_lookup_had_errors)) {
            remember_lookup(cache_key_initial, nohit)
            remember_lookup(cache_key_resolved, nohit)
        } else {
            push_progress("\u2022 External lookup had transient errors; this no-match result will not be cached.", append = FALSE)
        }
        nohit
    }

