    observeEvent(input$assembly_info_request,
        {
            payload <- input$assembly_info_request
            req_id <- trimws(as.character(payload$request_id %||% ""))
            panel_ctx <- tolower(trimws(as.character(payload$context %||% "")))
            species_ids <- as.character(payload$species_ids %||% character(0))
            species_ids <- species_ids[!is.na(species_ids) & nzchar(trimws(species_ids))]
            subtitle_in <- trimws(as.character(payload$subtitle %||% ""))

            reg <- preloadedRegistry()
            ready_reg <- if (!is.null(reg) && nrow(reg) > 0) reg[as.logical(reg$ready), , drop = FALSE] else data.frame()
            rows <- data.frame()

            if (length(species_ids) > 0 && nrow(ready_reg) > 0) {
                idx <- match(species_ids, as.character(ready_reg$species_id))
                idx <- idx[is.finite(idx) & idx >= 1 & idx <= nrow(ready_reg)]
                if (length(idx) > 0) {
                    rows <- ready_reg[idx, , drop = FALSE]
                }
            }

            if (nrow(rows) == 0 && identical(panel_ctx, "homo")) {
                selected_entry <- get_preloaded_entry(input$homo_preloaded_species %||% "")
                if (!is.null(selected_entry) && nrow(selected_entry) > 0) {
                    rows <- selected_entry
                }
            }
            if (nrow(rows) == 0 && identical(panel_ctx, "ortho") && nrow(ready_reg) > 0) {
                sel_ids <- as.character(input$ortho_preloaded_species %||% character(0))
                idx <- match(sel_ids, as.character(ready_reg$species_id))
                idx <- idx[is.finite(idx) & idx >= 1 & idx <= nrow(ready_reg)]
                if (length(idx) > 0) {
                    rows <- ready_reg[idx, , drop = FALSE]
                }
            }

            blocks <- if (nrow(rows) > 0) {
                vapply(seq_len(nrow(rows)), function(i) {
                    build_assembly_info_block_html(rows[i, , drop = FALSE])
                }, character(1))
            } else {
                character(0)
            }
            blocks <- blocks[nzchar(blocks)]
            body_html <- if (length(blocks) > 0) {
                paste(blocks, collapse = "<hr class='assembly-tip-divider'/>")
            } else {
                sprintf(
                    "<div class='assembly-tip-empty'>%s</div>",
                    htmltools::htmlEscape(as_text_one("Assembly details are not available for this selection."))
                )
            }

            subtitle_txt <- subtitle_in
            if (!nzchar(subtitle_txt)) {
                subtitle_txt <- if (nrow(rows) == 1) {
                    as.character(rows$organism[1] %||% rows$label[1] %||% rows$species_id[1] %||% as_text_one("Selected organism"))
                } else if (nrow(rows) > 1) {
                    sprintf("%d %s", as.integer(nrow(rows)), as_text_one("Selected organism(s)"))
                } else {
                    as_text_one("Selected organism(s)")
                }
            }

            session$sendCustomMessage("assembly_info_popup_data", list(
                request_id = req_id,
                title = as_text_one("Assembly details"),
                subtitle = subtitle_txt,
                html = body_html
            ))
        },
        ignoreInit = TRUE
    )

