    # Keepalive ping from client-side keepalive.js — absorb silently so the
    # input does not accidentally trigger any reactive expressions.
    observeEvent(input$`.__keepalive__.`, {}, ignoreInit = TRUE, ignoreNULL = TRUE)

    lastTransportMetrics <- reactiveVal(NULL)
    observeEvent(input$cgv_transport_metrics,
        {
            payload <- input$cgv_transport_metrics
            prev_payload <- lastTransportMetrics()
            lastTransportMetrics(payload)

            if (!isTRUE(app_env_flag("APP_TRANSPORT_TIMING", FALSE))) {
                return(invisible(NULL))
            }

            ws <- payload$websocket %||% list()
            res <- payload$resources %||% list()
            nav <- payload$navigation %||% list()
            prev_ws <- (prev_payload %||% list())$websocket %||% list()
            delta_num <- function(current, previous) {
                cur <- suppressWarnings(as.numeric(current %||% 0))
                pre <- suppressWarnings(as.numeric(previous %||% 0))
                if (!is.finite(cur)) cur <- 0
                if (!is.finite(pre)) pre <- 0
                max(0, cur - pre)
            }
            d_ws_in <- delta_num(ws$inBytes, prev_ws$inBytes)
            d_ws_out <- delta_num(ws$outBytes, prev_ws$outBytes)
            d_ws_in_msg <- delta_num(ws$inMessages, prev_ws$inMessages)
            d_ws_out_msg <- delta_num(ws$outMessages, prev_ws$outMessages)
            message(sprintf(
                paste0(
                    "[TRANSPORT][browser] reason=%s elapsed_ms=%s ",
                    "delta_ws_in=%sB/%smsg delta_ws_out=%sB/%smsg ",
                    "ws_in=%sB/%smsg ws_out=%sB/%smsg ",
                    "resources_transfer=%sB encoded=%sB decoded=%sB nav_transfer=%sB"
                ),
                as.character(payload$reason %||% "unknown"),
                as.character(payload$elapsedMs %||% NA),
                as.character(as.integer(round(d_ws_in))),
                as.character(as.integer(round(d_ws_in_msg))),
                as.character(as.integer(round(d_ws_out))),
                as.character(as.integer(round(d_ws_out_msg))),
                as.character(ws$inBytes %||% 0),
                as.character(ws$inMessages %||% 0),
                as.character(ws$outBytes %||% 0),
                as.character(ws$outMessages %||% 0),
                as.character(res$transferSize %||% 0),
                as.character(res$encodedBodySize %||% 0),
                as.character(res$decodedBodySize %||% 0),
                as.character(nav$transferSize %||% 0)
            ))
            invisible(NULL)
        },
        ignoreInit = TRUE,
        ignoreNULL = TRUE
    )

    parse_batch_gene_query <- function(query_text, max_genes = 24L) {
        raw <- trimws(as.character(query_text %||% ""))
        if (!nzchar(raw)) {
            return(list(genes = character(0), mode = "single", truncated = FALSE))
        }

        raw <- gsub("\r\n?", "\n", raw, perl = TRUE)
        mode <- "single"
        chunks <- raw
        has_pipe2 <- grepl("\\|\\|", raw, perl = TRUE)
        has_newline <- grepl("\n", raw, fixed = TRUE)
        has_tab <- grepl("\t", raw, fixed = TRUE)
        if (has_pipe2 || has_newline || has_tab) {
            if (has_pipe2) {
                mode <- "pipe2"
            } else if (has_newline) {
                mode <- "newline"
            } else {
                mode <- "tab"
            }
            chunks <- unlist(strsplit(raw, "\\|\\||\\n|\\t", perl = TRUE), use.names = FALSE)
        }

        chunks <- trimws(as.character(chunks %||% character(0)))
        chunks <- gsub("^\"(.*)\"$", "\\1", chunks, perl = TRUE)
        chunks <- gsub("^'(.*)'$", "\\1", chunks, perl = TRUE)
        chunks <- trimws(chunks)
        chunks <- chunks[nzchar(chunks)]
        chunks <- unique(chunks)

        max_genes <- suppressWarnings(as.integer(max_genes))
        if (!is.finite(max_genes) || max_genes < 1L) {
            max_genes <- 1L
        }
        truncated <- length(chunks) > max_genes
        if (truncated) {
            chunks <- chunks[seq_len(max_genes)]
        }

        list(genes = chunks, mode = mode, truncated = truncated)
    }

    parse_batch_gene_payload <- function(payload_value, max_genes = 24L) {
        vals <- unlist(payload_value %||% character(0), use.names = FALSE)
        vals <- trimws(as.character(vals %||% character(0)))
        vals <- vals[!is.na(vals) & nzchar(vals)]
        if (length(vals) == 1L) {
            parsed_single <- parse_batch_gene_query(vals[[1]], max_genes = 1000L)
            if (length(parsed_single$genes) > 1L) {
                vals <- parsed_single$genes
            }
        }
        vals <- unique(vals)

        max_genes <- suppressWarnings(as.integer(max_genes))
        if (!is.finite(max_genes) || max_genes < 1L) {
            max_genes <- 1L
        }
        truncated <- length(vals) > max_genes
        if (truncated) {
            vals <- vals[seq_len(max_genes)]
        }

        list(genes = vals, mode = "chips", truncated = truncated)
    }

    clear_all_gene_search_inputs <- function() {
        updateTextInput(session, "filter1", value = "")
        updateTextInput(session, "gene_name", value = "")
        updateTextInput(session, "global_search_query", value = "")
        updateTextInput(session, "global_search_query_collapsed", value = "")
        session$sendCustomMessage(
            "clear_global_search_state",
            list()
        )
    }

    reset_homo_batch_summary <- function() {
        homoBatchSummary(list(
            active = FALSE,
            total = 0L,
            requested = character(0),
            completed = character(0),
            plotted = character(0),
            not_found = character(0),
            no_structure = character(0),
            duplicate = character(0),
            error = character(0)
        ))
        invisible(NULL)
    }

    start_homo_batch_summary <- function(genes = character(0)) {
        genes_chr <- trimws(as.character(genes %||% character(0)))
        genes_chr <- unique(genes_chr[nzchar(genes_chr)])
        homoBatchSummary(list(
            active = length(genes_chr) > 1L,
            total = as.integer(length(genes_chr)),
            requested = genes_chr,
            completed = character(0),
            plotted = character(0),
            not_found = character(0),
            no_structure = character(0),
            duplicate = character(0),
            error = character(0)
        ))
        invisible(NULL)
    }

    record_homo_batch_result <- function(gene, status = c("plotted", "not_found", "no_structure", "duplicate", "error")) {
        status_txt <- match.arg(status)
        gene_txt <- trimws(as.character(gene %||% ""))
        if (!nzchar(gene_txt)) {
            return(invisible(NULL))
        }

        st <- isolate(homoBatchSummary())
        if (!isTRUE(st$active)) {
            return(invisible(NULL))
        }

        st$completed <- unique(c(as.character(st$completed %||% character(0)), gene_txt))
        for (bucket in c("plotted", "not_found", "no_structure", "duplicate", "error")) {
            st[[bucket]] <- setdiff(as.character(st[[bucket]] %||% character(0)), gene_txt)
        }
        st[[status_txt]] <- unique(c(as.character(st[[status_txt]] %||% character(0)), gene_txt))
        homoBatchSummary(st)
        invisible(NULL)
    }

    emit_homo_batch_summary_if_ready <- function() {
        st <- isolate(homoBatchSummary())
        if (!isTRUE(st$active)) {
            return(invisible(NULL))
        }

        total_n <- suppressWarnings(as.integer(st$total %||% 0L))
        if (!is.finite(total_n) || total_n < 1L) {
            total_n <- length(unique(as.character(st$requested %||% character(0))))
        }
        plotted <- unique(trimws(as.character(st$plotted %||% character(0))))
        plotted <- plotted[nzchar(plotted)]
        not_found <- unique(trimws(as.character(st$not_found %||% character(0))))
        not_found <- not_found[nzchar(not_found)]
        no_structure <- unique(trimws(as.character(st$no_structure %||% character(0))))
        no_structure <- no_structure[nzchar(no_structure)]
        duplicate <- unique(trimws(as.character(st$duplicate %||% character(0))))
        duplicate <- duplicate[nzchar(duplicate)]
        error_genes <- unique(trimws(as.character(st$error %||% character(0))))
        error_genes <- error_genes[nzchar(error_genes)]

        summary_lines <- c(
            sprintf(
                "Multi-gene batch completed: %d of %d genes plotted.",
                length(plotted),
                as.integer(total_n)
            )
        )
        if (length(not_found) > 0L) {
            summary_lines <- c(
                summary_lines,
                sprintf("Not found (%d): %s.", length(not_found), summarize_label_list(not_found, max_items = 8L, fallback = "N/A"))
            )
        }
        if (length(no_structure) > 0L) {
            summary_lines <- c(
                summary_lines,
                sprintf("No transcript structure available (%d): %s.", length(no_structure), summarize_label_list(no_structure, max_items = 8L, fallback = "N/A"))
            )
        }
        if (length(duplicate) > 0L) {
            summary_lines <- c(
                summary_lines,
                sprintf("Already plotted (%d): %s.", length(duplicate), summarize_label_list(duplicate, max_items = 8L, fallback = "N/A"))
            )
        }
        if (length(error_genes) > 0L) {
            summary_lines <- c(
                summary_lines,
                sprintf("Errors (%d): %s.", length(error_genes), summarize_label_list(error_genes, max_items = 8L, fallback = "N/A"))
            )
        }

        summary_msg <- paste(summary_lines, collapse = "\n")
        summary_tone <- if (length(error_genes) > 0L && length(plotted) == 0L) {
            "error"
        } else if (length(not_found) > 0L || length(no_structure) > 0L || length(duplicate) > 0L || length(error_genes) > 0L) {
            "warning"
        } else {
            "success"
        }

        append_status(searchStatusHomologous, summary_msg)
        emit_popup_status("Multi-Gene Search", summary_msg, tone = summary_tone, clear = TRUE)
        reset_homo_batch_summary()
        invisible(NULL)
    }

    set_batch_search_state <- function(mode = "", total = 0L) {
        mode_txt <- tolower(trimws(as.character(mode %||% "")))
        if (!mode_txt %in% c("homologous", "orthologous")) {
            mode_txt <- ""
        }
        total_n <- suppressWarnings(as.integer(total))
        if (!is.finite(total_n) || total_n < 2L || !nzchar(mode_txt)) {
            batchSearchMode("")
            batchSearchRemaining(0L)
            batchSearchQueue(character())
            reset_homo_batch_summary()
            return(invisible(NULL))
        }
        batchSearchMode(mode_txt)
        batchSearchRemaining(total_n)
        invisible(NULL)
    }

    take_next_batch_gene <- function() {
        q <- isolate(trimws(as.character(batchSearchQueue() %||% character(0))))
        q <- q[nzchar(q)]
        if (length(q) == 0L) {
            batchSearchQueue(character())
            return("")
        }
        next_gene <- as.character(q[[1]] %||% "")
        if (length(q) > 1L) {
            batchSearchQueue(q[-1])
        } else {
            batchSearchQueue(character())
        }
        next_gene
    }

    dispatch_next_batch_search <- function(mode = "", delay_sec = 0.08) {
        mode_txt <- tolower(trimws(as.character(mode %||% "")))
        if (!mode_txt %in% c("homologous", "orthologous")) {
            return(invisible(FALSE))
        }

        dispatch <- function() {
            next_gene <- trimws(as.character(take_next_batch_gene() %||% ""))
            if (!nzchar(next_gene)) {
                batchSearchMode("")
                batchSearchRemaining(0L)
                reset_homo_batch_summary()
                clear_all_gene_search_inputs()
                return(invisible(FALSE))
            }

            updateTextInput(session, "global_search_query", value = next_gene)
            updateTextInput(session, "global_search_query_collapsed", value = next_gene)

            if (identical(mode_txt, "orthologous")) {
                updateTextInput(session, "gene_name", value = next_gene)
                execute_orthologous_search(gene_override = next_gene, origin = "global_batch")
            } else {
                updateTextInput(session, "filter1", value = next_gene)
                execute_homologous_search(gene_override = next_gene, origin = "global_batch")
            }
            invisible(TRUE)
        }

        delay_val <- suppressWarnings(as.numeric(delay_sec %||% 0))
        if (!is.finite(delay_val) || delay_val < 0) {
            delay_val <- 0
        }
        if (requireNamespace("later", quietly = TRUE) && delay_val > 0) {
            later::later(dispatch, delay = delay_val)
        } else {
            dispatch()
        }
        invisible(TRUE)
    }

    queue_global_batch_search <- function(genes, target_mode = "homologous") {
        q <- trimws(as.character(genes %||% character(0)))
        q <- q[nzchar(q)]
        if (length(q) == 0L) {
            batchSearchQueue(character())
            reset_homo_batch_summary()
            return(invisible(FALSE))
        }

        target_mode <- tolower(trimws(as.character(target_mode %||% "homologous")))
        if (!target_mode %in% c("homologous", "orthologous")) {
            target_mode <- "homologous"
        }

        batchSearchQueue(q)
        if (identical(target_mode, "homologous")) {
            start_homo_batch_summary(q)
        } else {
            reset_homo_batch_summary()
        }
        dispatch_next_batch_search(target_mode, delay_sec = 0.08)
        invisible(TRUE)
    }

    finalize_search_cleanup <- function(mode = "") {
        mode_txt <- tolower(trimws(as.character(mode %||% "")))
        active_mode <- tolower(trimws(as.character(batchSearchMode() %||% "")))
        remaining <- suppressWarnings(as.integer(batchSearchRemaining() %||% 0L))
        if (!is.finite(remaining) || remaining < 0L) {
            remaining <- 0L
        }

        is_active_batch <- nzchar(active_mode) &&
            remaining > 0L &&
            identical(mode_txt, active_mode)

        if (!is_active_batch) {
            batchSearchQueue(character())
            reset_homo_batch_summary()
            clear_all_gene_search_inputs()
            return(invisible(NULL))
        }

        remaining <- remaining - 1L
        if (remaining <= 0L) {
            if (identical(mode_txt, "homologous")) {
                emit_homo_batch_summary_if_ready()
            }
            batchSearchMode("")
            batchSearchRemaining(0L)
            batchSearchQueue(character())
            clear_all_gene_search_inputs()
        } else {
            batchSearchRemaining(remaining)
            queued_genes <- trimws(as.character(batchSearchQueue() %||% character(0)))
            queued_genes <- queued_genes[nzchar(queued_genes)]
            if (length(queued_genes) == 0L) {
                if (identical(mode_txt, "homologous")) {
                    emit_homo_batch_summary_if_ready()
                }
                batchSearchMode("")
                batchSearchRemaining(0L)
                clear_all_gene_search_inputs()
                return(invisible(NULL))
            }
            dispatch_next_batch_search(mode_txt, delay_sec = 0.10)
        }
        invisible(NULL)
    }

    execute_homologous_search <- function(gene_override = NULL, origin = "local") {
        gene_txt <- trimws(as.character(gene_override %||% ""))
        pendingHomoSearchOrigin(as.character(origin %||% "local"))
        if (nzchar(gene_txt)) {
            pendingHomoSearchGene(gene_txt)
            updateTextInput(session, "filter1", value = gene_txt)
        } else {
            pendingHomoSearchGene(NULL)
        }
        session$sendCustomMessage("cgv_trigger_homo_search", list(origin = as.character(origin %||% "local")))
        invisible(TRUE)
    }

    execute_orthologous_search <- function(gene_override = NULL, origin = "local") {
        gene_txt <- trimws(as.character(gene_override %||% ""))
        pendingOrthoSearchOrigin(as.character(origin %||% "local"))
        if (nzchar(gene_txt)) {
            pendingOrthoSearchGene(gene_txt)
            updateTextInput(session, "gene_name", value = gene_txt)
        } else {
            pendingOrthoSearchGene(NULL)
        }
        session$sendCustomMessage("cgv_trigger_ortho_search", list(origin = as.character(origin %||% "local")))
        invisible(TRUE)
    }

    observeEvent(input$neighbor_gene_visualize_request, {
        payload <- input$neighbor_gene_visualize_request %||% list()
        if (!is.list(payload)) return(invisible(NULL))

        scalar_text <- function(x) {
            value <- trimws(as.character(x %||% ""))
            if (length(value) == 0L || is.na(value[1])) return("")
            value[1]
        }
        neighbor_name <- scalar_text(payload$neighbor_name)
        neighbor_id <- scalar_text(payload$neighbor_id)
        source_gene <- scalar_text(payload$source_gene)
        invalid_labels <- c("", "N/A", "None", "Unknown")
        search_gene <- if (!neighbor_name %in% invalid_labels) neighbor_name else neighbor_id
        if (search_gene %in% invalid_labels) {
            emit_popup_status(
                "Genomic Neighbor",
                "This annotation does not provide a searchable gene identifier.",
                tone = "warning",
                clear = FALSE
            )
            return(invisible(NULL))
        }

        source_panel <- tolower(scalar_text(payload$panel))
        if (!source_panel %in% c("homologous", "orthologous")) {
            source_panel <- as.character(input$navtabs %||% preferredSearchWorkflow() %||% "homologous")
        }
        if (!source_panel %in% c("homologous", "orthologous")) source_panel <- "homologous"
        if (identical(source_panel, "orthologous")) {
            emit_popup_status(
                "Cross-Species Gene Search",
                paste0(
                    "Genomic neighbors and overlaps can be inspected here, but adding them below is available only in Multi-Gene Search. ",
                    "A cross-species result must first be confirmed across the selected organisms."
                ),
                tone = "info",
                clear = FALSE
            )
            return(invisible(NULL))
        }

        relation_detail <- scalar_text(payload$detail)
        relation_note <- if (nzchar(relation_detail)) paste0(" (", relation_detail, ")") else ""
        source_note <- if (nzchar(source_gene) && !source_gene %in% invalid_labels) {
            paste0(" from ", source_gene)
        } else {
            ""
        }
        emit_popup_status(
            "Genomic Neighbor",
            paste0("Adding ", search_gene, source_note, relation_note, " below the current results."),
            tone = "info",
            clear = FALSE
        )

        active_panel <- as.character(input$navtabs %||% "")
        # A contextual neighbor/overlap action normally originates from the
        # workflow that is already visible. Re-selecting that same hidden tab
        # emits a nav change and reopens the left workflow panel unnecessarily.
        if (!identical(active_panel, source_panel)) {
            updateTabsetPanel(session, "navtabs", selected = source_panel)
        }
        dispatch_neighbor_search <- function() {
            if (identical(source_panel, "orthologous")) {
                updateTextInput(session, "gene_name", value = search_gene)
                execute_orthologous_search(gene_override = search_gene, origin = "genomic_neighbor")
            } else {
                updateTextInput(session, "filter1", value = search_gene)
                execute_homologous_search(gene_override = search_gene, origin = "genomic_neighbor")
            }
            invisible(TRUE)
        }
        if (!identical(active_panel, source_panel) && requireNamespace("later", quietly = TRUE)) {
            later::later(dispatch_neighbor_search, delay = 0.08)
        } else {
            dispatch_neighbor_search()
        }
        invisible(TRUE)
    }, ignoreInit = TRUE, ignoreNULL = TRUE)

    observeEvent(searchPreparationReadyHomo(), {
        if (!isTRUE(searchPreparationReadyHomo())) return(invisible(NULL))
        pending <- isolate(pendingPreparedSearchHomo())
        if (!is.list(pending)) return(invisible(NULL))
        if (!identical(
            suppressWarnings(as.integer(pending$token %||% NA_integer_)),
            suppressWarnings(as.integer(isolate(searchPreparationTokenHomo()) %||% NA_integer_))
        )) {
            pendingPreparedSearchHomo(NULL)
            return(invisible(NULL))
        }
        pendingPreparedSearchHomo(NULL)
        execute_homologous_search(
            gene_override = as.character(pending$gene %||% ""),
            origin = as.character(pending$origin %||% "queued")
        )
        invisible(NULL)
    }, ignoreInit = TRUE)

    observeEvent(input$cgv_card_complete, {
        payload <- input$cgv_card_complete %||% list()
        run_id <- trimws(as.character(payload$run_id %||% ""))
        if (!nzchar(run_id)) return(invisible(NULL))
        homo_run <- (homoPlotTimingTracker()$run %||% list())$id %||% ""
        ortho_run <- (orthoPlotTimingTracker()$run %||% list())$id %||% ""
        if (identical(run_id, as.character(homo_run))) {
            handle_browser_card_complete(homoPlotTimingTracker, payload, "HOMO_TIMING")
        } else if (identical(run_id, as.character(ortho_run))) {
            handle_browser_card_complete(orthoPlotTimingTracker, payload, "ORTHO_TIMING")
        }
        invisible(NULL)
    }, ignoreInit = TRUE)

    observeEvent(searchPreparationReadyOrtho(), {
        if (!isTRUE(searchPreparationReadyOrtho())) return(invisible(NULL))
        pending <- isolate(pendingPreparedSearchOrtho())
        if (!is.list(pending)) return(invisible(NULL))
        if (!identical(
            suppressWarnings(as.integer(pending$token %||% NA_integer_)),
            suppressWarnings(as.integer(isolate(searchPreparationTokenOrtho()) %||% NA_integer_))
        )) {
            pendingPreparedSearchOrtho(NULL)
            return(invisible(NULL))
        }
        pendingPreparedSearchOrtho(NULL)
        execute_orthologous_search(
            gene_override = as.character(pending$gene %||% ""),
            origin = as.character(pending$origin %||% "queued")
        )
        invisible(NULL)
    }, ignoreInit = TRUE)

    if (isTRUE(catalogFeatureEnabled)) {
    run_installed_catalog_search <- function(query = NULL, force = FALSE) {
        term <- trimws(as.character(query %||% input$catalog_gene_query %||% ""))
        if (nchar(term) < 3L) {
            catalogSearchEpoch(isolate(catalogSearchEpoch()) + 1L)
            catalogSearchResults(empty_alias_catalog_results())
            catalogSearchStatus("Enter at least 3 characters to search every installed organism index.")
            catalogSearchLastTerm("")
            return(invisible(NULL))
        }
        if (!isTRUE(force) && identical(tolower(term), tolower(catalogSearchLastTerm()))) {
            return(invisible(catalogSearchResults()))
        }
        registry <- tryCatch(isolate(preloadedRegistry()), error = function(e) data.frame())
        if (!is.data.frame(registry)) registry <- data.frame()
        ready <- if (nrow(registry) > 0L && "ready" %in% names(registry)) !is.na(registry$ready) & as.logical(registry$ready) else rep(TRUE, nrow(registry))
        registry <- registry[ready, , drop = FALSE]
        ready_count <- nrow(registry)
        kingdom <- if ("kingdom" %in% names(registry)) trimws(as.character(registry$kingdom)) else rep("Other", ready_count)
        kingdom[!nzchar(kingdom)] <- "Other"
        kingdom_order <- unique(c(intersect(c("Plantae", "Animalia", "Fungi"), kingdom), kingdom))
        registry_groups <- lapply(kingdom_order, function(value) registry[kingdom == value, , drop = FALSE])
        names(registry_groups) <- kingdom_order
        registry_groups <- Filter(function(x) is.data.frame(x) && nrow(x) > 0L, registry_groups)

        token <- isolate(catalogSearchEpoch()) + 1L
        catalogSearchEpoch(token)
        catalogSearchResults(empty_alias_catalog_results())
        catalogSearchLastTerm(term)
        catalogSearchStatus(sprintf("Searching %d local organism indexes in %d group(s)…", ready_count, length(registry_groups)))
        started <- proc.time()[["elapsed"]]

        sort_catalog_rows <- function(results) {
            if (!is.data.frame(results) || nrow(results) == 0L) return(empty_alias_catalog_results())
            match_rank <- c(exact = 5L, normalized_basic = 4L, normalized_strict = 3L, prefix = 2L, contains = 1L)
            confidence_rank <- c(HIGH = 3L, MEDIUM = 2L, LOW = 1L)
            rank <- unname(match_rank[tolower(results$match_type)]) * 10L + unname(confidence_rank[toupper(results$confidence)])
            rank[is.na(rank)] <- 0L
            results[order(-rank, results$organism, results$resolved_gene, results$matched_term), , drop = FALSE]
        }

        process_group <- function(group_index = 1L, accumulated = empty_alias_catalog_results()) {
            if (!identical(isolate(catalogSearchEpoch()), token)) return(invisible(NULL))
            if (group_index > length(registry_groups)) {
                elapsed <- proc.time()[["elapsed"]] - started
                results <- accumulated
                results <- sort_catalog_rows(results)
                catalogSearchResults(results)
                if (nrow(results) == 0L) {
                    catalogSearchStatus(sprintf("No local alias matches for ‘%s’ across %d installed organism(s) (%.1fs).", term, ready_count, elapsed))
                } else {
                    organism_count <- length(unique(as.character(results$organism_id)))
                    catalogSearchStatus(sprintf(
                        "%d candidate genes across %d installed organism(s), searched in %.1fs.",
                        nrow(results), organism_count, elapsed
                    ))
                }
                return(invisible(results))
            }

            group_name <- names(registry_groups)[group_index]
            group_results <- tryCatch(
                search_installed_alias_catalog(term, registry = registry_groups[[group_index]], base_dir = "."),
                error = function(e) {
                    app_debug_log("[GeneCatalog] ", group_name, " search failed: ", e$message)
                    empty_alias_catalog_results()
                }
            )
            combined <- if (nrow(accumulated) > 0L && nrow(group_results) > 0L) {
                rbind(accumulated, group_results)
            } else if (nrow(group_results) > 0L) {
                group_results
            } else {
                accumulated
            }
            combined <- sort_catalog_rows(combined)
            catalogSearchResults(combined)
            catalogSearchStatus(sprintf(
                "%s complete · %d/%d groups · %d candidate gene(s) found so far…",
                group_name, group_index, length(registry_groups), nrow(combined)
            ))
            continue_search <- function() process_group(group_index + 1L, combined)
            if (requireNamespace("later", quietly = TRUE)) later::later(continue_search, delay = 0.03) else continue_search()
            invisible(combined)
        }

        launch_search <- function() process_group(1L, empty_alias_catalog_results())
        if (requireNamespace("later", quietly = TRUE)) later::later(launch_search, delay = 0.03) else launch_search()
        invisible(NULL)
    }

    catalog_debounced_query <- shiny::debounce(reactive(trimws(as.character(input$catalog_gene_query %||% ""))), 350)
    observeEvent(catalog_debounced_query(), {
