    run_global_search <- function(query_override = NULL) {
        active_panel <- as.character(input$navtabs %||% "home")
        target_mode <- if (active_panel %in% c("homologous", "orthologous")) {
            active_panel
        } else {
            as.character(preferredSearchWorkflow() %||% "homologous")
        }
        if (!target_mode %in% c("homologous", "orthologous")) {
            target_mode <- "homologous"
        }

        query <- trimws(as.character(query_override %||% ""))
        if (!nzchar(query)) {
            query <- trimws(as.character(input$global_search_query %||% ""))
        }
        if (!nzchar(query)) {
            if (identical(target_mode, "orthologous")) {
                query <- trimws(as.character(input$gene_name %||% ""))
            } else {
                query <- trimws(as.character(input$filter1 %||% ""))
            }
        }
        parsed_query <- parse_batch_gene_query(query, max_genes = 240L)
        parsed_chips <- parse_batch_gene_payload(input$global_search_chip_payload, max_genes = 240L)
        query_batch <- as.character(unique(c(parsed_chips$genes, parsed_query$genes)))
        query_batch <- query_batch[nzchar(query_batch)]
        was_truncated <- isTRUE(parsed_query$truncated) || isTRUE(parsed_chips$truncated)
        if (length(query_batch) > 24L) {
            query_batch <- query_batch[seq_len(24L)]
            was_truncated <- TRUE
        }
        if (length(query_batch) == 0) {
            return(invisible(NULL))
        }

        updateTabsetPanel(session, "navtabs", selected = target_mode)

        is_batch <- length(query_batch) > 1L
        set_batch_search_state(target_mode, length(query_batch))
        first_query <- as.character(query_batch[1] %||% "")
        updateTextInput(session, "global_search_query", value = first_query)
        updateTextInput(session, "global_search_query_collapsed", value = first_query)

        if (is_batch) {
            queued_msg <- sprintf(
                "Batch search queued: %d genes (%s).",
                length(query_batch),
                summarize_label_list(query_batch, max_items = 4L, fallback = sprintf("%d genes", length(query_batch)))
            )
            if (identical(target_mode, "orthologous")) {
                searchStatusOrthologous(queued_msg)
            } else {
                searchStatusHomologous(queued_msg)
            }

            emit_popup_status(
                if (identical(target_mode, "orthologous")) "Cross-Species Gene Search" else "Multi-Gene Search",
                queued_msg,
                tone = "info",
                clear = FALSE
            )

            if (isTRUE(was_truncated)) {
                append_status(
                    if (identical(target_mode, "orthologous")) searchStatusOrthologous else searchStatusHomologous,
                    "Batch input was trimmed to the first 24 unique genes for stability."
                )
            }

            queue_global_batch_search(query_batch, target_mode = target_mode)
            return(invisible(NULL))
        }

        dispatch_single <- function() {
            if (identical(target_mode, "orthologous")) {
                updateTextInput(session, "gene_name", value = first_query)
                execute_orthologous_search(gene_override = first_query, origin = "global")
            } else {
                updateTextInput(session, "filter1", value = first_query)
                execute_homologous_search(gene_override = first_query, origin = "global")
            }
            invisible(TRUE)
        }

        # Let tab/mode state settle only when switching tabs (e.g., from Home).
        needs_tab_settle <- !identical(as.character(active_panel %||% ""), as.character(target_mode %||% ""))
        delay_dispatch <- if (isTRUE(needs_tab_settle)) 0.08 else 0
        if (requireNamespace("later", quietly = TRUE) && delay_dispatch > 0) {
            later::later(dispatch_single, delay = delay_dispatch)
        } else {
            dispatch_single()
        }
    }

    observeEvent(input$global_search_go,
        {
            run_global_search()
        },
        ignoreInit = TRUE
    )

    observeEvent(input$global_search_go_collapsed,
        {
            run_global_search(input$global_search_query_collapsed %||% "")
        },
        ignoreInit = TRUE
    )

    observeEvent(input$workflow_enter_search,
        {
            payload <- input$workflow_enter_search %||% list()
            mode_txt <- tolower(trimws(as.character(payload$mode %||% "")))
            gene_txt <- trimws(as.character(payload$gene %||% ""))

            if (!nzchar(gene_txt)) {
                return(invisible(NULL))
            }

            if (identical(mode_txt, "orthologous")) {
                updateTextInput(session, "gene_name", value = gene_txt)
                execute_orthologous_search(gene_override = gene_txt, origin = "enter")
                return(invisible(TRUE))
            }

            if (identical(mode_txt, "homologous")) {
                updateTextInput(session, "filter1", value = gene_txt)
                execute_homologous_search(gene_override = gene_txt, origin = "enter")
                return(invisible(TRUE))
            }

            invisible(NULL)
        },
        ignoreInit = TRUE,
        ignoreNULL = TRUE
    )

    # Navigation (without auto-clearing plots)
    observeEvent(input$navtabs,
        {
            current_tab <- as.character(input$navtabs %||% "home")
            if (current_tab %in% c("homologous", "orthologous")) {
                preferredSearchWorkflow(current_tab)
            }
            if (!identical(current_tab, "homologous")) {
                updateTextInput(session, "filter1", value = "")
            }
            if (!identical(current_tab, "orthologous")) {
                updateTextInput(session, "gene_name", value = "")
            }
        },
        ignoreInit = TRUE
    )

    normalize_partial_gene_pick_item <- function(item, fallback_gene = "", mode = "homologous") {
        item <- item %||% list()
        if (!is.list(item)) item <- list()
        mode_txt <- tolower(trimws(as.character(mode %||% "homologous")))
        display_gene <- trimws(as.character(item$gene %||% fallback_gene %||% ""))
        local_gene_id <- trimws(as.character(item$local_gene_id %||% ""))
        plot_gene <- trimws(as.character(item$plot_gene %||% ""))
        if (!nzchar(plot_gene)) {
            plot_gene <- if (identical(mode_txt, "homologous") && nzchar(local_gene_id)) local_gene_id else display_gene
        }
        source_db <- trimws(as.character(item$source_db %||% ""))
        term_type <- tolower(trimws(as.character(item$term_type %||% "")))
        confidence <- toupper(trimws(as.character(item$confidence %||% "")))
        requires_confirmation <- isTRUE(item$requires_confirmation %||% FALSE)
        list(
            gene = display_gene,
            plot_gene = plot_gene,
            local_gene_id = local_gene_id,
            local_symbol = trimws(as.character(item$local_symbol %||% "")),
            term_type = term_type,
            source_db = source_db,
            confidence = confidence,
            match_role = trimws(as.character(item$match_role %||% "")),
            requires_confirmation = requires_confirmation
        )
    }

    extract_partial_gene_pick_items <- function(payload) {
        payload <- payload %||% list()
        mode_txt <- tolower(trimws(as.character(payload$mode %||% "homologous")))
        raw_items <- payload$items %||% NULL
        if (is.null(raw_items) && !is.null(payload$item)) {
            raw_items <- list(payload$item)
        }
        genes <- trimws(as.character(payload$genes %||% character(0)))
        genes <- genes[!is.na(genes) & nzchar(genes)]
        gene_txt <- trimws(as.character(payload$gene %||% ""))
        if (length(genes) == 0L && nzchar(gene_txt)) {
            genes <- gene_txt
        }
        if (is.list(raw_items) && length(raw_items) > 0L) {
            items <- lapply(seq_along(raw_items), function(idx) {
                fallback <- if (length(genes) >= idx) genes[[idx]] else ""
                normalize_partial_gene_pick_item(raw_items[[idx]], fallback_gene = fallback, mode = mode_txt)
            })
        } else {
            items <- lapply(genes, function(gene) {
                normalize_partial_gene_pick_item(list(gene = gene, plot_gene = gene), fallback_gene = gene, mode = mode_txt)
            })
        }
        items <- items[vapply(items, function(item) nzchar(as.character(item$plot_gene %||% item$gene %||% "")), logical(1))]
        if (length(items) == 0L) return(list())
        keys <- vapply(items, function(item) tolower(trimws(as.character(item$plot_gene %||% item$gene %||% ""))), character(1))
        items[!duplicated(keys)]
    }

    run_partial_gene_pick_items <- function(mode_txt, items) {
        mode_txt <- tolower(trimws(as.character(mode_txt %||% "homologous")))
        genes <- vapply(items, function(item) {
            if (identical(mode_txt, "homologous")) {
                trimws(as.character(item$plot_gene %||% item$local_gene_id %||% item$gene %||% ""))
            } else {
                # Cross-Species searches must remain nomenclature-based across organisms; keep
                # the selected display term while preserving metadata in the payload.
                trimws(as.character(item$gene %||% item$plot_gene %||% ""))
            }
        }, character(1))
        genes <- unique(genes[!is.na(genes) & nzchar(genes)])
        if (length(genes) == 0L) return(invisible(NULL))
        if (identical(mode_txt, "orthologous")) {
            first_gene <- genes[[1]]
            execute_orthologous_search(gene_override = first_gene, origin = "suggestion")
        } else if (length(genes) > 1L) {
            set_batch_search_state("homologous", length(genes))
            queue_global_batch_search(genes, target_mode = "homologous")
        } else {
            first_gene <- genes[[1]]
            display_gene <- trimws(as.character(items[[1]]$gene %||% first_gene))
            updateTextInput(session, "filter1", value = if (nzchar(display_gene)) display_gene else first_gene)
            execute_homologous_search(gene_override = first_gene, origin = "suggestion")
        }
        invisible(TRUE)
    }

    build_partial_gene_external_alias_confirmation_modal <- function(mode_txt, items) {
        mode_txt <- tolower(trimws(as.character(mode_txt %||% "homologous")))
        external_items <- items[vapply(items, function(item) isTRUE(item$requires_confirmation %||% FALSE), logical(1))]
        external_items <- external_items[seq_len(min(length(external_items), 8L))]
        item_nodes <- lapply(external_items, function(item) {
            display_gene <- trimws(as.character(item$gene %||% ""))
            local_gene_id <- trimws(as.character(item$local_gene_id %||% item$plot_gene %||% ""))
            local_symbol <- trimws(as.character(item$local_symbol %||% ""))
            source_db <- trimws(as.character(item$source_db %||% "external alias index"))
            confidence <- trimws(as.character(item$confidence %||% ""))
            tags$li(
                tags$strong(if (nzchar(display_gene)) display_gene else local_gene_id),
                " maps to ",
                tags$code(if (nzchar(local_gene_id)) local_gene_id else "an unresolved local locus"),
                if (nzchar(local_symbol)) paste0(" / ", local_symbol) else NULL,
                tags$span(
                    class = "partial-gene-suggestion-meta",
                    paste(c(source_db, confidence), collapse = " / ")
                )
            )
        })
        build_app_confirmation_modal(
            title = "Confirm External Alias",
            subtitle = if (identical(mode_txt, "orthologous")) "Cross-Species Gene Search" else "Multi-Gene Search",
            tone = "warning",
            title_icon = "database",
            body = tagList(
                tags$p(
                    class = "app-confirmation-modal-text",
                    "One or more selected suggestions came from an external alias source, not from the local GFF gene name. An alias identifies a candidate locus but does not prove orthology across species."
                ),
                tags$ul(class = "app-confirmation-modal-list", item_nodes),
                tags$p(
                    class = "app-confirmation-modal-question",
                    tags$strong(if (identical(mode_txt, "orthologous") && isTRUE(cross_species_requires_verified_orthology())) {
                        "Use this as an orthology candidate?"
                    } else {
                        "Plot using the shown local locus/loci?"
                    })
                )
            ),
            confirm_input_id = "confirm_partial_gene_external_alias_btn",
            confirm_label = if (identical(mode_txt, "orthologous") && isTRUE(cross_species_requires_verified_orthology())) {
                "Validate candidate"
            } else {
                "Plot confirmed alias"
            },
            confirm_icon = "check"
        )
    }

