    observeEvent(input$load_work_session_btn,
        {
            file_info <- input$upload_work_session
            if (is.null(file_info) || is.null(file_info$datapath) || !nzchar(as.character(file_info$datapath %||% ""))) {
                emit_popup_status("Work session", "Select a .rds session file before loading.", tone = "warning", clear = TRUE)
                return(invisible(NULL))
            }
            rds_path <- as.character(file_info$datapath %||% "")
            if (!nzchar(rds_path) || !file.exists(rds_path)) {
                emit_popup_status("Work session", "Session file could not be accessed.", tone = "error", clear = TRUE)
                return(invisible(NULL))
            }

            set_popup_loading(TRUE, context = "Work session", text = "Loading saved session...")
            on.exit(set_popup_loading(FALSE, context = "Work session"), add = TRUE)

            loaded <- tryCatch(readRDS(rds_path), error = function(e) e)
            if (inherits(loaded, "error")) {
                emit_popup_status("Work session", sprintf("Failed to read session file: %s", loaded$message), tone = "error", clear = TRUE)
                return(invisible(NULL))
            }

            restored <- tryCatch(apply_work_session_snapshot(loaded), error = function(e) e)
            if (inherits(restored, "error")) {
                emit_popup_status("Work session", sprintf("Failed to restore session: %s", restored$message), tone = "error", clear = TRUE)
                return(invisible(NULL))
            }

            msg <- sprintf(
                "Session restored: %d multi-gene and %d cross-species result set(s).",
                as.integer(restored$homologous %||% 0L),
                as.integer(restored$orthologous %||% 0L)
            )
            append_status(searchStatusHomologous, msg)
            append_status(searchStatusOrthologous, msg)
            emit_popup_status("Work session", msg, tone = "success", clear = TRUE)
        },
        ignoreInit = TRUE
    )

