    observeEvent(input$figure_studio_alignment_render_done, {
        evt <- input$figure_studio_alignment_render_done
        ctx <- tolower(trimws(as.character(evt$context %||% "")))
        output_id <- if (ctx %in% c("ortho", "orthologous")) {
