            ),
            div(
                id = "ortho-pip-card-shell",
                style = if (identical(mode, "pip_blocks")) "" else "display:none;",
                build_orthologous_pip_card_ui(ids_n = 0L, is_dark_theme = is_dark_theme)
            )
        )
    })
    outputOptions(output, "ortho_special_cards_ui", suspendWhenHidden = FALSE)

    observeEvent(input$ortho_visual_mode, {
        mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(mode, "pip")) mode <- "pip_blocks"
        mode_js <- jsonlite::toJSON(mode, auto_unbox = TRUE)
        shinyjs::runjs(paste0(
            "(function(){",
            "var mode=", mode_js, ";",
            "var alignedShell=document.getElementById('ortho-aligned-card-shell');",
            "var pipShell=document.getElementById('ortho-pip-card-shell');",
            "var multipipShell=document.getElementById('ortho-multipip-card-shell');",
            "var regularCards=document.getElementById('ortho-plot-cards-container');",
            "if(alignedShell){alignedShell.style.display=(mode==='aligned')?'':'none';}",
            "if(pipShell){pipShell.style.display=(mode==='pip_blocks')?'':'none';}",
            "if(multipipShell){multipipShell.style.display=(mode==='pip_multipip')?'':'none';}",
            "if(regularCards){regularCards.style.display=(mode==='aligned'||mode==='pip_blocks'||mode==='pip_multipip')?'none':'';}",
            "if(window.scheduleGgiraphNudge){window.scheduleGgiraphNudge(180);window.scheduleGgiraphNudge(700);}",
            "})();"
        ))
    }, ignoreInit = FALSE)

    observe({
        mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        ids <- as.character(primaryPlotIdsOrthologous() %||% integer(0))
        if (length(ids) > 0L && exists("ortho_timing_search_start", inherits = TRUE)) {
            message(sprintf(
                "[ORTHO_TIMING] Render queue start: %d cards at %.2fs",
                length(ids),
                as.numeric(difftime(Sys.time(), ortho_timing_search_start, units = "secs"))
            ))
        }
        inserted_now <- isolate(orthoInsertedCardIds() %||% character(0))
        if (identical(mode, "pip")) {
            mode <- "pip_blocks"
        }

        if (mode %in% c("aligned", "pip_blocks", "pip_multipip")) {
            if (length(inserted_now) > 0L) {
                clear_orthologous_cards_dom()
                orthoInsertedCardIds(character(0))
            }
            return(invisible(NULL))
        }

        if (length(inserted_now) == 1L && grepl("^__ORTHO_", inserted_now[[1]])) {
            clear_orthologous_cards_dom()
            orthoInsertedCardIds(character(0))
            inserted_now <- character(0)
        }

        ids_n <- length(ids)
        current_n <- suppressWarnings(as.integer(orthoVisibleCount() %||% orthoInitialVisibleCount))
        if (!is.finite(current_n) || current_n < orthoInitialVisibleCount) {
            current_n <- orthoInitialVisibleCount
        }
        visible_n <- min(ids_n, current_n)
        target_ids <- if (visible_n > 0L) ids[seq_len(visible_n)] else character(0)

        if (length(target_ids) == 0L) {
            if (length(inserted_now) > 0L) {
                clear_orthologous_cards_dom()
                orthoInsertedCardIds(character(0))
            }
            return(invisible(NULL))
        }

        if (length(inserted_now) == 0L) {
            append_orthologous_cards_dom(target_ids)
            orthoInsertedCardIds(target_ids)
            return(invisible(NULL))
        }

        prefix_ok <- length(inserted_now) <= length(target_ids) &&
            identical(inserted_now, target_ids[seq_len(length(inserted_now))])
        if (prefix_ok && length(inserted_now) < length(target_ids)) {
            append_ids <- target_ids[(length(inserted_now) + 1L):length(target_ids)]
            append_orthologous_cards_dom(append_ids)
            orthoInsertedCardIds(target_ids)
            return(invisible(NULL))
        }

        if (!identical(inserted_now, target_ids)) {
            clear_orthologous_cards_dom()
            append_orthologous_cards_dom(target_ids)
            orthoInsertedCardIds(target_ids)
        }
        invisible(NULL)
    })

    observeEvent(input$ortho_load_more,
        {
            current_n <- suppressWarnings(as.integer(orthoVisibleCount() %||% orthoInitialVisibleCount))
            if (!is.finite(current_n) || current_n < orthoInitialVisibleCount) {
                current_n <- orthoInitialVisibleCount
            }
            ids_n <- length(primaryPlotIdsOrthologous())
            orthoVisibleCount(min(ids_n, current_n + orthoRenderChunkSize))
        },
        ignoreInit = TRUE
    )

    observeEvent(primaryPlotIdsOrthologous(),
        {
            ids <- primaryPlotIdsOrthologous()
            ids_chr <- as.character(ids %||% integer(0))
            hydrated_isoform_ids <- as.character(orthoHydratedIsoformIds() %||% character(0))
            keep_ids <- unique(c(ids_chr, hydrated_isoform_ids[nzchar(hydrated_isoform_ids)]))
            for (id_chr in keep_ids) {
                bind_orthologous_footer_output(id_chr)
            }
            bound_now <- as.character(orthoFooterOutputsBound() %||% character(0))
            bound_keep <- intersect(bound_now, keep_ids)
            remove_ids <- setdiff(bound_now, keep_ids)
            if (length(remove_ids) > 0L) {
                invisible(lapply(remove_ids, unbind_orthologous_footer_output))
            }
            if (!identical(bound_now, bound_keep)) {
                orthoFooterOutputsBound(bound_keep)
            }
            queued_now <- as.character(orthoSecondaryBindingsQueued() %||% character(0))
            queued_keep <- intersect(queued_now, keep_ids)
            if (!identical(queued_now, queued_keep)) {
                orthoSecondaryBindingsQueued(queued_keep)
            }
            ids_n <- length(ids)
            ready_now <- as.character(orthoRenderedPlotIds() %||% character(0))
            ready_keep <- intersect(ready_now, ids_chr)
            if (!identical(ready_now, ready_keep)) {
                orthoRenderedPlotIds(ready_keep)
            }
            current_n <- suppressWarnings(as.integer(orthoVisibleCount() %||% orthoInitialVisibleCount))
            if (!is.finite(current_n) || current_n < orthoInitialVisibleCount) {
                current_n <- orthoInitialVisibleCount
            }
            if (ids_n <= 0L) {
                # Only mutate if value actually differs — avoids double-invalidation
                if (!identical(as.integer(orthoVisibleCount()), as.integer(orthoInitialVisibleCount))) {
                    orthoVisibleCount(orthoInitialVisibleCount)
                }
                cancel_ortho_auto_render_queue()
                if (length(ready_keep) > 0L) {
                    orthoRenderedPlotIds(character(0))
                }
                return(invisible(NULL))
            }
            if (current_n > ids_n) {
                # Only mutate if value actually differs — avoids double-invalidation
                if (!identical(as.integer(orthoVisibleCount()), ids_n)) {
                    orthoVisibleCount(ids_n)
                }
                cancel_ortho_auto_render_queue()
            }
            invisible(NULL)
        },
        ignoreInit = TRUE
    )

	    observe({
	        if (!isTRUE(orthoAutoRenderMore) || isTRUE(orthoAutoRenderQueued())) {
	            return(invisible(NULL))
	        }
	        pending_gate <- orthoFirstPaintGate()
	        if (identical(as.character(pending_gate$release_reason %||% ""), "awaiting_expected_plot")) {
	            search_state <- searchRunState()
	            ortho_search_active <- isTRUE((search_state$orthologous %||% list())$active)
	            if (isTRUE(ortho_search_active)) {
	                return(invisible(NULL))
	            }
	        }
	        ids <- primaryPlotIdsOrthologous()
	        ids_n <- length(ids)
        if (ids_n <= 0L) {
            return(invisible(NULL))
        }
        current_n <- suppressWarnings(as.integer(orthoVisibleCount() %||% orthoInitialVisibleCount))
        if (!is.finite(current_n) || current_n < orthoInitialVisibleCount) {
            current_n <- orthoInitialVisibleCount
        }
        if (current_n >= ids_n) {
            gate_now <- orthoFirstPaintGate()
            if (isTRUE(gate_now$enabled) && !isTRUE(gate_now$released)) {
                release_ortho_first_paint_gate(
                    as.character(gate_now$run_id %||% ""),
                    reason = "no_secondary_results"
                )
            }
            return(invisible(NULL))
        }
        visible_ids <- if (current_n > 0L) as.character(ids[seq_len(current_n)]) else character(0)
        # Only wait for canonical transcripts — hidden isoforms are suspended by Shiny
        # (display:none) and must not block the cascade from loading the next gene/organism.
        gene_meta_map <- tryCatch(plotGeneMetaOrthologous(), error = function(e) list())
        canonical_visible_ids <- Filter(function(pid) {
            meta <- tryCatch(gene_meta_map[[pid]], error = function(e) NULL)
            is.null(meta) || !isFALSE(meta$is_canonical)
        }, visible_ids)
        ready_now <- as.character(orthoRenderedPlotIds() %||% character(0))
        first_paint_gate <- orthoFirstPaintGate()
        if (isTRUE(first_paint_gate$enabled) && !isTRUE(first_paint_gate$released)) {
            timing_tracker <- orthoPlotTimingTracker()
            timing_run_id <- as.character((timing_tracker$run %||% list())$id %||% "")
            expected_ready_ids <- intersect(
                as.character(timing_tracker$gate_expected %||% character(0)),
                ready_now
            )
            if (identical(timing_run_id, as.character(first_paint_gate$run_id %||% "")) &&
                length(expected_ready_ids) > 0L) {
                arm_ortho_first_paint_timeout(as.character(first_paint_gate$run_id %||% ""))
            }
            return(invisible(NULL))
        }
        if (length(canonical_visible_ids) == 0L || !all(canonical_visible_ids %in% ready_now)) {
            return(invisible(NULL))
        }
        next_n <- min(ids_n, current_n + orthoRenderChunkSize)
        if (next_n <= current_n) {
            return(invisible(NULL))
        }
        scheduled_ids <- as.character(ids)
        scheduled_gate_token <- as.integer((orthoFirstPaintGate() %||% list())$token %||% 0L)
        scheduled_generation <- bump_ortho_auto_render_generation()
        orthoAutoRenderQueued(TRUE)
        app_perf_mark(
            app_perf_new_run("ORTHO_UI"),
            sprintf("auto render queued next_visible=%d/%d", as.integer(next_n), as.integer(ids_n)),
            "ORTHO_UI"
        )
        if (requireNamespace("later", quietly = TRUE)) {
            later::later(function() {
                isolate({
                    latest_gate <- orthoFirstPaintGate()
                    same_gate <- identical(
                        as.integer(latest_gate$token %||% 0L),
                        as.integer(scheduled_gate_token %||% 0L)
                    )
                    same_ids <- identical(
                        as.character(primaryPlotIdsOrthologous() %||% character(0)),
                        scheduled_ids
                    )
                    same_generation <- identical(
                        as.integer(orthoAutoRenderGeneration %||% 0L),
                        as.integer(scheduled_generation %||% 0L)
                    )
                    if (isTRUE(same_gate) && isTRUE(same_generation)) {
                        if (isTRUE(same_ids) &&
                            !(isTRUE(latest_gate$enabled) && !isTRUE(latest_gate$released))) {
                            visible_now <- suppressWarnings(as.integer(orthoVisibleCount() %||% current_n))
                            if (!is.finite(visible_now) || is.na(visible_now) || visible_now < 1L) {
                                visible_now <- current_n
                            }
                            orthoVisibleCount(as.integer(min(length(scheduled_ids), max(visible_now, next_n))))
                        }
                        orthoAutoRenderQueued(FALSE)
                    }
                })
            }, delay = orthoAutoRenderDelay)
        } else {
            orthoVisibleCount(as.integer(next_n))
            orthoAutoRenderQueued(FALSE)
        }
        invisible(NULL)
    })

	    output$ortho_aligned_mode_hint <- renderUI({
	        mode_sel <- tolower(trimws(as.character(input$ortho_aligned_mode %||% "protein")))
	        hint_text <- switch(mode_sel,
	            "protein" = tagList(
	                tags$b("\u2605 Translated CDS alignment (BLOSUM62)"),
	                tags$span(" \u2014 aligns the translated CDS at the amino-acid level. Best default for distant species and conservative exon correspondence.",
	                          style = "color: var(--bs-secondary-color, #6c757d);")
	            ),
	            "cds"     = tagList(
	                tags$b("CDS nucleotide alignment"),
	                tags$span(" \u2014 aligns coding DNA directly. Better for closer species, but more sensitive to synonymous divergence.",
	                          style = "color: var(--bs-secondary-color, #6c757d);")
	            ),
	            "exon"    = tagList(
	                tags$b("Full exon alignment (UTRs included)"),
	                tags$span(" \u2014 aligns spliced exons including UTRs. Useful for regulatory conservation, but noisier for distant species.",
	                          style = "color: var(--bs-secondary-color, #6c757d);")
	            ),
	            NULL
	        )
	        if (is.null(hint_text)) return(NULL)
	        tags$small(style = "line-height: 1.35; display: block;", hint_text)
	    })
    outputOptions(output, "ortho_aligned_mode_hint", suspendWhenHidden = FALSE)

	    aligned_event_display_label <- function(event_type = "fallback", compact = FALSE) {
	        etype <- tolower(trimws(as.character(event_type %||% "fallback")))
	        if (!etype %in% c("1:1", "1:n", "n:1", "partial", "fallback")) etype <- "fallback"
	        if (isTRUE(compact)) {
	            return(switch(
	                etype,
	                "1:1" = "1:1 direct",
	                "1:n" = "1:n split correspondence",
	                "n:1" = "n:1 merged correspondence",
	                "partial" = "partial / ambiguous",
	                "fallback" = "index fallback"
	            ))
	        }
	        switch(
	            etype,
	            "1:1" = "Direct 1:1 correspondence",
	            "1:n" = "1:n split correspondence",
	            "n:1" = "n:1 merged correspondence",
	            "partial" = "Partial / ambiguous correspondence",
	            "fallback" = "Index-based fallback correspondence"
	        )
	    }

	    aligned_identity_metric_label <- function(aligned_mode = "protein") {
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        switch(
	            mode_txt,
	            "protein" = "Protein identity",
	            "cds" = "CDS identity",
	            "exon" = "Exonic identity"
	        )
	    }

	    aligned_support_metric_label <- function(aligned_mode = "protein") {
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        switch(
	            mode_txt,
	            "protein" = "Aligned amino acids",
	            "cds" = "Aligned nucleotides",
	            "exon" = "Aligned nucleotides"
	        )
	    }

	    aligned_support_metric_unit <- function(aligned_mode = "protein") {
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        if (identical(mode_txt, "protein")) "aa" else "nt"
	    }

	    aligned_support_value_text <- function(value, aligned_mode = "protein") {
	        val_num <- suppressWarnings(as.numeric(value %||% NA_real_))
	        if (!is.finite(val_num)) {
	            return("N/A")
	        }
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (identical(mode_txt, "protein")) {
	            val_txt <- format(as.integer(round(val_num)), big.mark = ",")
	        } else if (abs(val_num - round(val_num)) < 0.05) {
	            val_txt <- format(as.integer(round(val_num)), big.mark = ",")
	        } else {
	            val_txt <- format(round(val_num, 1), nsmall = 1, trim = TRUE, scientific = FALSE, big.mark = ",")
	        }
	        paste0(val_txt, " ", aligned_support_metric_unit(aligned_mode))
	    }

	    aligned_ribbon_size_detail_html <- function(row_df, aligned_mode = "protein", is_dark_theme = FALSE) {
	        if (is.null(row_df) || !is.data.frame(row_df) || nrow(row_df) == 0L) {
	            return("")
	        }
	        top_units <- suppressWarnings(as.numeric(row_df$feature_units_A[1] %||% NA_real_))
	        bottom_units <- suppressWarnings(as.numeric(row_df$feature_units_B[1] %||% NA_real_))
	        aligned_units <- suppressWarnings(as.numeric(row_df$aligned_units[1] %||% row_df$n_codons[1] %||% NA_real_))
	        if (!any(is.finite(c(top_units, bottom_units, aligned_units)))) {
	            return("")
	        }
	        border_col <- if (is_dark_theme) "rgba(196,216,232,0.26)" else "rgba(84,110,129,0.24)"
	        title_col <- if (is_dark_theme) "#55D0B6" else "#36B39C"
	        paste0(
	            "<div style='margin-top:4px; padding-top:4px; border-top:1px solid ", border_col, "; font-size:inherit; line-height:1.2; color:inherit;'>",
	            "<div style='font-size:inherit; line-height:1.15; color:inherit;'><span style='color:", title_col, "; font-weight:700;'>Aligned feature span details</span></div>",
	            "<div style='margin-top:1px; font-size:inherit; line-height:1.2; color:inherit;'>",
	            "<b>Top feature size:</b> ", aligned_support_value_text(top_units, aligned_mode), "<br/>",
	            "<b>Bottom feature size:</b> ", aligned_support_value_text(bottom_units, aligned_mode), "<br/>",
	            "<b>Aligned span:</b> ", aligned_support_value_text(aligned_units, aligned_mode),
	            "</div></div>"
	        )
	    }

	    aligned_split_summary <- function(ribbon_pairs, row_df, aligned_mode = "protein") {
	        if (is.null(ribbon_pairs) || !is.data.frame(ribbon_pairs) || nrow(ribbon_pairs) == 0L ||
	            is.null(row_df) || !is.data.frame(row_df) || nrow(row_df) == 0L) {
	            return(NULL)
	        }
	        etype <- tolower(trimws(as.character(row_df$event_type[1] %||% "")))
	        if (!etype %in% c("1:n", "n:1")) {
	            return(NULL)
	        }
	        subset_df <- ribbon_pairs
	        if (identical(etype, "1:n")) {
	            src_idx <- suppressWarnings(as.integer(row_df$vis_exon_A[1]))
	            if (!is.finite(src_idx)) return(NULL)
	            subset_df <- subset_df[suppressWarnings(as.integer(subset_df$vis_exon_A)) == src_idx, , drop = FALSE]
	        } else {
	            tgt_idx <- suppressWarnings(as.integer(row_df$vis_exon_B[1]))
	            if (!is.finite(tgt_idx)) return(NULL)
	            subset_df <- subset_df[suppressWarnings(as.integer(subset_df$vis_exon_B)) == tgt_idx, , drop = FALSE]
	        }
	        if (nrow(subset_df) == 0L) {
	            return(NULL)
	        }
	        support_vals <- suppressWarnings(as.numeric(subset_df$n_codons))
	        support_mask <- is.finite(support_vals) & support_vals > 0
	        if (!any(support_mask)) {
	            return(NULL)
	        }
	        support_total <- sum(support_vals[support_mask], na.rm = TRUE)
	        pid_vals <- suppressWarnings(as.numeric(subset_df$identity_pct))
	        pid_mask <- support_mask & is.finite(pid_vals)
	        weighted_pid <- if (any(pid_mask)) {
	            100 * sum(support_vals[pid_mask] * (pid_vals[pid_mask] / 100), na.rm = TRUE) / sum(support_vals[pid_mask], na.rm = TRUE)
	        } else {
	            NA_real_
	        }
	        list(
	            support_total = support_total,
	            weighted_identity = weighted_pid,
	            support_label = aligned_support_metric_label(aligned_mode),
	            support_unit = aligned_support_metric_unit(aligned_mode)
	        )
	    }

	    aligned_label_support_threshold <- function(aligned_mode = "protein") {
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        if (identical(mode_txt, "protein")) 10L else 30L
	    }

	    aligned_anchor_unit_label <- function(geometry_mode = "exon") {
	        geom_txt <- tolower(trimws(as.character(geometry_mode %||% "exon")))
	        if (!geom_txt %in% c("cds", "exon")) geom_txt <- "exon"
	        if (identical(geom_txt, "cds")) "CDS block" else "exon"
	    }

	    aligned_geometry_note <- function(aligned_mode = "protein", geometry_mode = "exon") {
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        geom_txt <- tolower(trimws(as.character(geometry_mode %||% "exon")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        if (!geom_txt %in% c("cds", "exon")) geom_txt <- "exon"
	        if (identical(mode_txt, "exon")) {
	            "Display geometry: exon-aware transcript layout"
	        } else if (identical(geom_txt, "cds")) {
	            "Display geometry: CDS-anchored layout; identity refers to the aligned coding block"
	        } else {
	            "Display geometry: exon-aware fallback layout"
	        }
	    }

	    aligned_pairwise_fallback_identity <- function(seq1_txt, seq2_txt, aligned_mode = "protein", max_total_bp = 15000L) {
	        seq1_txt <- toupper(gsub("[^A-Z]", "", as.character(seq1_txt %||% "")))
	        seq2_txt <- toupper(gsub("[^A-Z]", "", as.character(seq2_txt %||% "")))
	        if (!nzchar(seq1_txt) || !nzchar(seq2_txt)) {
	            return(list(identity = NA_real_, note = "Pairwise identity unavailable"))
	        }
	        total_bp <- nchar(seq1_txt) + nchar(seq2_txt)
	        if (!is.finite(total_bp) || total_bp > as.integer(max_total_bp)) {
	            return(list(identity = NA_real_, note = "Pairwise identity skipped for large fallback blocks"))
	        }
	        if (!requireNamespace("Biostrings", quietly = TRUE) || !requireNamespace("pwalign", quietly = TRUE)) {
	            return(list(identity = NA_real_, note = "Pairwise identity unavailable"))
	        }
	        mode_txt <- tolower(trimws(as.character(aligned_mode %||% "protein")))
	        if (!mode_txt %in% c("protein", "cds", "exon")) mode_txt <- "protein"
	        pid_val <- tryCatch({
	            aln_fb <- pwalign::pairwiseAlignment(
	                Biostrings::DNAString(seq1_txt),
	                Biostrings::DNAString(seq2_txt),
	                type = "global",
	                substitutionMatrix = get_aligned_dna_substitution_matrix(),
	                gapOpening = -10,
	                gapExtension = -0.5
	            )
	            suppressWarnings(as.numeric(pwalign::pid(aln_fb)))
	        }, error = function(e) NA_real_)
	        note_txt <- if (identical(mode_txt, "exon")) {
	            "Fallback pairwise DNA identity over full displayed block"
	        } else {
	            "Fallback pairwise DNA identity over displayed coding block"
	        }
	        list(identity = pid_val, note = note_txt)
	    }

