        heading_color <- if (is_dark_theme) "#EAF3FB" else "#24394B"
        tags$details(
            style = paste0(
                "margin-top:8px; border:1px solid ", box_border, "; border-radius:10px; ",
                "background:", box_bg, "; padding:8px 10px;"
            ),
            tags$summary(
                style = paste0("cursor:pointer; font-weight:700; color:", heading_color, ";"),
                "How to interpret LASTZ Block View"
            ),
            tags$div(
                style = paste0("margin-top:8px; color:", text_color, "; font-size:12px; line-height:1.45;"),
                tags$ul(
                    style = "margin:0; padding-left:18px;",
                    tags$li("The x-axis shows genomic coordinates (bp) along the reference organism's chromosome. Left-to-right corresponds to increasing chromosomal position within the displayed window."),
                    tags$li(tags$strong("Y-axis within each track"), ": vertical position of each segment reflects its percent sequence identity to the reference (50% at bottom, 100% at top). Segments clustering near the top are highly conserved."),
                    tags$li(tags$strong("Segment colours"), ": coding exon overlap (blue) indicates the aligned block falls over a CDS region; UTR / non-coding exon overlap (gold) over UTR; intragenic non-exonic overlap (green) within the gene but outside annotated exons; other non-coding (grey) outside the gene body."),
                    tags$li(tags$strong("Forward vs reverse segments"), ": solid black segments align in the same orientation as the reference; dashed orange segments map to the opposite strand, suggesting a local inversion or strand-swap."),
                    tags$li(tags$strong("Reference gene body window"), ": the pale shaded region marks the extent of the reference gene (gene body, not just CDS) within the alignment window."),
                    tags$li(tags$strong("Min identity / Min block length filters"), ": blocks below the identity threshold or shorter than the length cutoff are hidden. The genomic axis and window are unchanged; only visible blocks are filtered."),
                    tags$li(tags$strong("Block density"), ": many short blocks indicate fragmented or rearranged synteny; a few long high-identity blocks indicate a conserved, collinear region."),
                    tags$li(tags$strong("Alignment window"), ": both organisms are aligned over the full genomic window (reference gene \u00b1 selected flank), not just the spliced transcript. Intergenic and intronic regions are included.")
                )
            )
        )
    })

