	    output$ortho_aligned_anchor_ui <- renderUI({
	        order_mode <- tolower(trimws(as.character(input$ortho_aligned_track_order %||% "similarity_chain")))
	        ids <- as.character(alignedRepresentativePlotIdsOrthologous() %||% character(0))
	        aligned_anchor_theme <- tolower(as.character(input$app_theme %||% "light"))
	        if (!aligned_anchor_theme %in% c("light", "dark")) aligned_anchor_theme <- "light"
	        is_dark_aligned_anchor <- identical(aligned_anchor_theme, "dark")
	        build_anchor_placeholder <- function(text) {
	            div(
	                class = "ortho-aligned-control ortho-aligned-control--select",
	                tags$label(
	                    "Anchor track:",
	                    class = "ortho-aligned-control-label"
	                ),
	                div(
	                    class = "ortho-aligned-empty-select",
	                    style = if (is_dark_aligned_anchor) {
	                        "height:40px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid #284562; background:linear-gradient(180deg,#10263b 0%,#0d2033 100%); color:#5d7e96; font-size:0.94rem;"
	                    } else {
	                        "height:40px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid rgba(189,201,210,0.95); background:rgba(248,250,252,0.96); color:#8394A2; font-size:0.94rem;"
	                    },
	                    text
	                )
	            )
	        }
	        if (!order_mode %in% c("similarity_chain", "manual")) {
	            return(build_anchor_placeholder("Used in biological/manual order"))
	        }
	        if (length(ids) <= 1L) {
	            return(build_anchor_placeholder("No anchor available yet"))
	        }
	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        strip_tx <- function(s) trimws(gsub("\\s*\\|\\s*Transcript:[^|]*", "", s))
	        choice_labels <- vapply(ids, function(id_chr) {
	            org_name <- trimws(as.character(tryCatch(org_map[[id_chr]]$name, error = function(e) "") %||% ""))
	            ttl <- strip_tx(trimws(as.character(tryCatch(titles_map[[id_chr]], error = function(e) "") %||% "")))
	            if (nzchar(org_name) && nzchar(ttl)) {
	                paste0(org_name, " | ", ttl)
	            } else if (nzchar(org_name)) {
	                org_name
	            } else if (nzchar(ttl)) {
	                ttl
	            } else {
	                id_chr
	            }
	        }, character(1))
	        current_anchor <- trimws(as.character(input$ortho_aligned_anchor_track %||% ""))
	        selected_anchor <- if (nzchar(current_anchor) && current_anchor != "__auto__" && current_anchor %in% ids) current_anchor else "__auto__"
	        div(
	            class = "ortho-aligned-control ortho-aligned-control--select",
	            tags$label(
	                "Anchor track:",
	                `for` = "ortho_aligned_anchor_track",
	                class = "ortho-aligned-control-label"
	            ),
	            shiny::selectInput(
	                inputId = "ortho_aligned_anchor_track",
	                label = NULL,
	                choices = c("Auto anchor (best-supported)" = "__auto__", stats::setNames(ids, choice_labels)),
	                selected = selected_anchor,
	                width = "100%"
	            )
	        )
	    })
    outputOptions(output, "ortho_aligned_anchor_ui", suspendWhenHidden = FALSE)

