	        }
	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
	        auto_ids <- as.character(autoAlignedOrderedPlotIdsOrthologous() %||% ids)
	        current_manual <- as.character(input$ortho_aligned_manual_order %||% character(0))
	        selected_ids <- current_manual[current_manual %in% ids]
	        selected_ids <- unique(selected_ids)
	        if (length(selected_ids) == 0L || !setequal(selected_ids, ids)) {
	            selected_ids <- auto_ids
	        }
	        choice_labels <- vapply(ids, function(id_chr) {
	            org_name <- trimws(as.character(tryCatch(org_map[[id_chr]]$name, error = function(e) "") %||% ""))
	            ttl <- trimws(as.character(tryCatch(titles_map[[id_chr]], error = function(e) "") %||% ""))
	            if (nzchar(org_name) && nzchar(ttl)) {
	                paste0(org_name, " | ", ttl)
	            } else if (nzchar(org_name)) {
	                org_name
	            } else if (nzchar(ttl)) {
	                ttl
	            } else {
	                id_chr
	            }
	        }, character(1))
	        div(
	            style = paste0("padding: 0 16px 8px 16px; border-bottom: 1px solid ", border_color, ";"),
	            tags$small(
	                style = "display:block; margin:6px 0 6px 0; line-height:1.3; color: var(--bs-secondary-color, #6c757d);",
	                "Manual order: drag selected items to set the comparison chain."
	            ),
	            shiny::selectizeInput(
	                inputId = "ortho_aligned_manual_order",
	                label = NULL,
	                choices = stats::setNames(ids, choice_labels),
	                selected = selected_ids,
	                multiple = TRUE,
	                width = "100%",
	                options = list(
	                    plugins = list("drag_drop"),
	                    hideSelected = FALSE,
	                    closeAfterSelect = FALSE,
	                    openOnFocus = FALSE
	                )
	            )
	        )
	    })

	    compute_aligned_ribbon_style <- function(event_type = "fallback", identity_pct = NA_real_, guided = TRUE,
	                                             span_a = NA_real_, span_b = NA_real_,
	                                             track_span_a = NA_real_, track_span_b = NA_real_,
	                                             base_alpha = 0.08, base_linewidth = 0.10) {
	        pid_val <- suppressWarnings(as.numeric(identity_pct))
	        span_vals <- c(suppressWarnings(as.numeric(span_a)), suppressWarnings(as.numeric(span_b)))
	        span_vals <- span_vals[is.finite(span_vals) & span_vals > 0]
	        track_vals <- c(suppressWarnings(as.numeric(track_span_a)), suppressWarnings(as.numeric(track_span_b)))
	        track_vals <- track_vals[is.finite(track_vals) & track_vals > 0]
	        span_max <- if (length(span_vals) > 0L) max(span_vals) else NA_real_
	        span_min <- if (length(span_vals) > 0L) min(span_vals) else NA_real_
	        track_ref <- if (length(track_vals) > 0L) stats::median(track_vals) else NA_real_
	        span_ratio <- if (is.finite(span_max) && is.finite(span_min) && span_min > 0) span_max / span_min else 1
	        track_share <- if (is.finite(span_max) && is.finite(track_ref) && track_ref > 0) span_max / track_ref else NA_real_

	        alpha_scale <- if (isTRUE(guided) && is.finite(pid_val)) {
	            max(0.55, min(1.18, 0.45 + pid_val / 100 * 0.62))
	        } else {
	            0.72
	        }
	        line_scale <- if (isTRUE(guided) && is.finite(pid_val)) {
	            max(0.10, min(0.42, 0.10 + pid_val / 100 * 0.30))
	        } else {
	            0.10
	        }

	        if (is.finite(track_share) && track_share >= 0.42) {
	            alpha_scale <- alpha_scale * 0.72
	            line_scale <- line_scale * 0.82
	        } else if (is.finite(track_share) && track_share >= 0.28) {
	            alpha_scale <- alpha_scale * 0.84
	            line_scale <- line_scale * 0.90
	        }
	        if (is.finite(span_ratio) && span_ratio >= 3.0) {
	            alpha_scale <- alpha_scale * 0.80
	            line_scale <- line_scale * 0.82
	        } else if (is.finite(span_ratio) && span_ratio >= 2.0) {
	            alpha_scale <- alpha_scale * 0.90
	            line_scale <- line_scale * 0.92
	        }
	        if (event_type %in% c("1:n", "n:1", "partial") && is.finite(track_share) && track_share >= 0.30) {
	            alpha_scale <- alpha_scale * 0.88
	        }

	        alpha_out <- max(0.05, min(0.18, base_alpha * alpha_scale))
	        line_out <- max(0.08, min(0.30, line_scale))
	        list(alpha = alpha_out, linewidth = line_out, span_ratio = span_ratio, track_share = track_share)
	    }

	    prune_aligned_ribbon_labels <- function(label_df, min_gap = 48, max_per_pair = 3L) {
	        if (is.null(label_df) || !is.data.frame(label_df) || nrow(label_df) == 0L) {
	            return(label_df)
	        }
	        if (!"pair_key" %in% names(label_df)) label_df$pair_key <- 1L
	        if (!"priority" %in% names(label_df)) label_df$priority <- 0
	        if (!"rib_width" %in% names(label_df)) label_df$rib_width <- min_gap
	        label_df$pair_key <- as.character(label_df$pair_key %||% "1")
	        ord <- order(label_df$pair_key, -suppressWarnings(as.numeric(label_df$priority)), -suppressWarnings(as.numeric(label_df$rib_width)), suppressWarnings(as.numeric(label_df$x)))
	        label_df <- label_df[ord, , drop = FALSE]
	        offset_pattern <- c(0, -1, 1, -2, 2, -3, 3, -4, 4)
	        y_step <- 0.075
	        placed_x <- list()
	        cluster_counts <- stats::setNames(integer(0), character(0))
	        label_df$y_adjust <- 0
	        for (i in seq_len(nrow(label_df))) {
	            pair_key <- as.character(label_df$pair_key[i] %||% "1")
	            if (!nzchar(pair_key)) pair_key <- "1"
	            xi <- suppressWarnings(as.numeric(label_df$x[i]))
	            wi <- suppressWarnings(as.numeric(label_df$rib_width[i]))
	            min_sep <- max(min_gap, if (is.finite(wi) && wi > 0) wi * 0.55 else min_gap)
	            xs <- if (pair_key %in% names(placed_x)) placed_x[[pair_key]] else numeric(0)
	            close_hits <- if (length(xs) > 0L && is.finite(xi)) sum(abs(xi - xs) < min_sep, na.rm = TRUE) else 0L
	            cluster_idx <- close_hits + 1L
	            if (!pair_key %in% names(cluster_counts)) cluster_counts[[pair_key]] <- 0L
	            cluster_counts[[pair_key]] <- max(cluster_counts[[pair_key]], cluster_idx)
	            pat_idx <- min(cluster_idx, length(offset_pattern))
	            label_df$y_adjust[i] <- offset_pattern[pat_idx] * y_step
	            placed_x[[pair_key]] <- c(xs, xi)
	        }
	        out <- label_df
	        out$y <- suppressWarnings(as.numeric(out$y)) + suppressWarnings(as.numeric(out$y_adjust %||% 0))
	        out$pair_key <- NULL
	        out$priority <- NULL
	        out$rib_width <- NULL
	        out$y_adjust <- NULL
	        out
	    }

	    output$ortho_aligned_plot_out <- bindEvent(renderGirafe({
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        req(identical(current_mode, "aligned"), cancelOutput = TRUE)
        aligned_perf <- app_perf_new_run("ORTHO_ALIGNED")
        app_perf_mark(aligned_perf, "render_enter", "ORTHO_ALIGNED")
        ids_all <- as.character(sortedPlotIdsOrthologous() %||% integer(0))
        rep_strategy <- tolower(trimws(as.character(input$ortho_aligned_representative %||% "longest_cds")))
        if (!rep_strategy %in% c("longest_cds", "longest_transcript", "most_exons", "all")) rep_strategy <- "longest_cds"
        track_order_mode <- tolower(trimws(as.character(input$ortho_aligned_track_order %||% "similarity_chain")))
	        if (!track_order_mode %in% c("similarity_chain", "load", "organism", "reverse", "manual")) track_order_mode <- "similarity_chain"
        ids <- as.character(alignedOrderedPlotIdsOrthologous() %||% character(0))
        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark_theme <- identical(theme_mode, "dark")
        aligned_bg_color <- if (is_dark_theme) "#102438" else "#FAFBFC"
        aligned_track_color <- if (is_dark_theme) "#A3B9CC" else "#C0CDD6"
        aligned_rect_border <- if (is_dark_theme) "#8FA8BC" else "#2C3E50"
        aligned_arrow_color <- if (is_dark_theme) "#B7CCE0" else "#4B6072"
        aligned_label_color <- if (is_dark_theme) "#E7F1FB" else "#2C3E50"
        aligned_axis_title_color <- if (is_dark_theme) "#EDF6FF" else "#2C3E50"
        aligned_axis_y_color <- if (is_dark_theme) "#E7F1FB" else "#34495E"
        aligned_axis_x_color <- if (is_dark_theme) "#D9E6F3" else "#5F7282"
        build_aligned_placeholder_simple <- function(msg) {
            p0 <- ggplot2::ggplot() +
                ggplot2::annotate("text", x = 0, y = 0, label = as.character(msg %||% "No aligned tracks could be rendered"), size = 4.2, color = aligned_axis_y_color) +
                ggplot2::xlim(-1, 1) +
                ggplot2::ylim(-1, 1) +
                ggplot2::theme_void() +
                ggplot2::theme(
                    panel.background = ggplot2::element_rect(fill = aligned_bg_color, color = NA),
                    plot.background = ggplot2::element_rect(fill = aligned_bg_color, color = NA)
                )
            safe_girafe(
                ggobj = p0,
                width_svg = 12,
                height_svg = 2.4,
                transport_label = "ortho_aligned_placeholder",
                options = list(
                    ggiraph::opts_hover(css = ""),
                    ggiraph::opts_selection(type = "none"),
                    ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
                    ggiraph::opts_sizing(rescale = TRUE)
                )
            )
        }
        if (length(ids) == 0) {
            req(FALSE, cancelOutput = TRUE)
        }
        parse_bool_env <- function(name, default = "1") {
            raw <- tolower(trimws(as.character(Sys.getenv(name, default) %||% default)))
            !raw %in% c("", "0", "false", "no", "off")
        }
        fast_enabled <- parse_bool_env("APP_ORTHO_ALIGNED_FAST", "1")
        # ── alignment mode and identity threshold (from UI controls) ─────────
        aligned_mode        <- tolower(trimws(as.character(input$ortho_aligned_mode        %||% "protein")))
        if (!aligned_mode %in% c("protein", "cds", "exon")) aligned_mode <- "protein"
        min_identity_thresh <- max(0, min(100, suppressWarnings(as.numeric(input$ortho_aligned_min_identity %||% 0))))
        if (!is.finite(min_identity_thresh)) min_identity_thresh <- 0
        aligned_ribbon_points <- app_env_int("APP_ALIGNED_RIBBON_POINTS", 25L, min_value = 8L, max_value = 25L)
        ids_chr <- as.character(ids %||% integer(0))
        sig_map <- plotSignaturesOrthologous()
        sig_vec <- vapply(ids_chr, function(id_chr) as.character(sig_map[[id_chr]] %||% ""), character(1))
	        cache_key <- paste(
	                            "aligned_v20",
	            paste(ids_chr, sig_vec, sep = ":"),
	            paste(ids_all, collapse = ","),
            theme_mode,
            as.character(isTRUE(fast_enabled)),
            aligned_mode,
            rep_strategy,
            track_order_mode,
            trimws(as.character(input$ortho_aligned_anchor_track %||% "")),
            as.character(as.integer(min_identity_thresh)),
            sep = "||",
            collapse = ";"
        )
        app_perf_mark(
            aligned_perf,
            sprintf("fast=%s ids=%d", ifelse(isTRUE(fast_enabled), "1", "0"), as.integer(length(ids_chr))),
            "ORTHO_ALIGNED"
        )

        if (isTRUE(fast_enabled)) {
	            fast_plot_obj <- tryCatch(
	                {
	                    if (exists(cache_key, envir = orthoAlignedPlotCache, inherits = FALSE)) {
	                        cached_plot <- get(cache_key, envir = orthoAlignedPlotCache, inherits = FALSE)
	                        if (!is.null(cached_plot)) {
	                            app_perf_mark(aligned_perf, "aligned_plot_cache_hit=1", "ORTHO_ALIGNED")
	                            orthoAlignedRenderCache(list(key = cache_key, plot_obj = cached_plot))
                                send_girafe_diag_expected(
                                    "ortho_aligned_plot_out",
                                    expected = list(render_mode = "aligned", cache_hit = TRUE),
                                    meta = list(cache_source = "plot_cache", cache_key = cache_key)
                                )
	                            return(refresh_girafe_widget_uid(cached_plot))
	                        }
	                    }
	                    app_perf_mark(aligned_perf, "aligned_plot_cache_hit=0", "ORTHO_ALIGNED")
	                    cached_aligned <- orthoAlignedRenderCache()
	                    cached_key <- as.character(cached_aligned$key %||% "")
                    cached_plot <- cached_aligned$plot_obj %||% NULL
                    if (nzchar(cached_key) && identical(cached_key, cache_key) && !is.null(cached_plot)) {
                        app_perf_mark(aligned_perf, "aligned_cache_hit=1", "ORTHO_ALIGNED")
                        send_girafe_diag_expected(
                            "ortho_aligned_plot_out",
                            expected = list(render_mode = "aligned", cache_hit = TRUE),
                            meta = list(cache_source = "render_cache", cache_key = cache_key)
                        )
                        return(refresh_girafe_widget_uid(cached_plot))
                    }
                    app_perf_mark(aligned_perf, "aligned_cache_hit=0", "ORTHO_ALIGNED")
                    total_t0 <- as.numeric(proc.time()[["elapsed"]])
                    gc_ms_accum <- 0
                    skipped_tracks <- 0L
                    skipped_ribbons <- 0L

                    esc_fast <- function(x) {
                        x <- as.character(x %||% "")
                        x <- gsub("&", "&amp;", x, fixed = TRUE)
                        x <- gsub("<", "&lt;", x, fixed = TRUE)
                        x <- gsub(">", "&gt;", x, fixed = TRUE)
                        x
                    }
                    scalar_chr <- function(x, default = "") {
                        if (is.null(x) || length(x) == 0L) {
                            return(as.character(default))
                        }
                        x1 <- x[[1]]
                        if (is.null(x1) || (length(x1) == 1L && is.na(x1))) {
                            return(as.character(default))
                        }
                        out <- trimws(as.character(x1))
                        if (!length(out) || !nzchar(out)) as.character(default) else out
                    }
                    normalize_dna <- function(seq_txt) {
                        toupper(gsub("[^ATCG]", "", as.character(seq_txt %||% "")))
                    }
                    calc_gc_pct_fast <- function(seq_txt) {
                        seq_norm <- normalize_dna(seq_txt)
                        if (!nzchar(seq_norm)) {
                            return(NA_real_)
                        }
                        gc_count <- nchar(gsub("[^GC]", "", seq_norm))
                        round(100 * gc_count / nchar(seq_norm), 2)
                    }
                    format_gc_pct_fast <- function(gc_pct) {
                        if (!is.finite(gc_pct)) {
                            return("N/A")
                        }
                        sprintf("%.2f%%", as.numeric(gc_pct))
                    }
                    seq_region_cache_key <- function(fasta_path, seqid, start_i, end_i) {
                        paste(
                            normalizePath(as.character(fasta_path %||% ""), winslash = "/", mustWork = FALSE),
                            trimws(as.character(seqid %||% "")),
                            as.integer(start_i),
                            as.integer(end_i),
                            sep = "::"
                        )
                    }
                    get_cached_seq <- function(fasta_path, seqid, start_pos, end_pos) {
                        fasta_txt <- trimws(as.character(fasta_path %||% ""))
                        if (!nzchar(fasta_txt) || !file.exists(fasta_txt)) {
                            return("")
                        }
                        seqid_txt <- trimws(as.character(seqid %||% ""))
                        start_num <- suppressWarnings(as.numeric(start_pos))
                        end_num <- suppressWarnings(as.numeric(end_pos))
                        if (!nzchar(seqid_txt) || !is.finite(start_num) || !is.finite(end_num)) {
                            return("")
                        }
                        start_i <- as.integer(round(min(start_num, end_num)))
                        end_i <- as.integer(round(max(start_num, end_num)))
                        if (start_i < 1L || end_i < start_i) {
                            return("")
                        }
                        key <- seq_region_cache_key(fasta_txt, seqid_txt, start_i, end_i)
                        if (exists(key, envir = orthoAlignedSeqCache, inherits = FALSE)) {
                            return(as.character(get(key, envir = orthoAlignedSeqCache, inherits = FALSE) %||% ""))
                        }
                        t0 <- as.numeric(proc.time()[["elapsed"]])
                        seq_txt <- tryCatch(
                            extract_sequence_from_fasta(fasta_txt, seqid_txt, start_i, end_i),
                            error = function(e) ""
                        )
                        seq_txt <- as.character(seq_txt %||% "")
                        gc_ms_accum <<- gc_ms_accum + (as.numeric(proc.time()[["elapsed"]]) - t0) * 1000
                        assign(key, seq_txt, envir = orthoAlignedSeqCache)
                        assign(key, calc_gc_pct_fast(seq_txt), envir = orthoAlignedGcCache)
                        seq_txt
                    }
                    get_cached_gc <- function(fasta_path, seqid, start_pos, end_pos) {
                        fasta_txt <- trimws(as.character(fasta_path %||% ""))
                        seqid_txt <- trimws(as.character(seqid %||% ""))
                        start_num <- suppressWarnings(as.numeric(start_pos))
                        end_num <- suppressWarnings(as.numeric(end_pos))
                        if (!nzchar(fasta_txt) || !file.exists(fasta_txt) || !nzchar(seqid_txt) || !is.finite(start_num) || !is.finite(end_num)) {
                            return(NA_real_)
                        }
                        start_i <- as.integer(round(min(start_num, end_num)))
                        end_i <- as.integer(round(max(start_num, end_num)))
                        if (start_i < 1L || end_i < start_i) {
                            return(NA_real_)
                        }
                        key <- seq_region_cache_key(fasta_txt, seqid_txt, start_i, end_i)
                        if (exists(key, envir = orthoAlignedGcCache, inherits = FALSE)) {
                            return(as.numeric(get(key, envir = orthoAlignedGcCache, inherits = FALSE)))
                        }
                        seq_txt <- get_cached_seq(fasta_txt, seqid_txt, start_i, end_i)
                        gc_pct <- calc_gc_pct_fast(seq_txt)
                        assign(key, gc_pct, envir = orthoAlignedGcCache)
                        gc_pct
                    }
                    fast_bezier_ribbon <- function(x1L, x1R, y1, x2L, x2R, y2, n_pts = 44L) {
                        t_seq <- seq(0, 1, length.out = as.integer(n_pts))
                        cubic_curve <- function(p0, p1, p2, p3, t) {
                            ((1 - t)^3 * p0) +
                                (3 * (1 - t)^2 * t * p1) +
                                (3 * (1 - t) * t^2 * p2) +
                                (t^3 * p3)
                        }
                        cp_y <- (y1 + y2) / 2
                        curve_y <- cubic_curve(y1, cp_y, cp_y, y2, t_seq)
                        # Match the original aligned_synteny ribbon signature:
                        # a smooth monotonic cubic easing in x, not a sinusoidal wave.
                        left_x <- cubic_curve(x1L, x1L, x2L, x2L, t_seq)
                        right_x <- cubic_curve(x1R, x1R, x2R, x2R, t_seq)

                        data.frame(
                            x = c(left_x, rev(right_x)),
                            y = c(curve_y, rev(curve_y)),
                            stringsAsFactors = FALSE
                        )
                    }
                    build_feature_tooltip_simple <- function(row) {
                        sprintf(
                            "<b><em>%s</em></b><br/><b>Type:</b> %s<br/><b>Chr:</b> %s<br/><b>Start:</b> %s<br/><b>End:</b> %s<br/><b>Strand:</b> %s<br/><b>Length:</b> %s bp<br/><b>GC:</b> %s",
                            esc_fast(row$org_label[1]),
                            esc_fast(row$feature_raw[1]),
                            esc_fast(row$seqid[1]),
                            format(as.integer(round(as.numeric(row$xstart[1]))), big.mark = ","),
                            format(as.integer(round(as.numeric(row$xend[1]))), big.mark = ","),
                            esc_fast(row$strand[1]),
                            format(as.integer(round(as.numeric(row$largo[1]))), big.mark = ","),
                            esc_fast(as.character(row$gc_label[1] %||% "N/A"))
                        )
                    }
