	                        if (is.list(cached_scene) && identical(as.character(cached_scene$key %||% ""), scene_cache_key)) {
	                            scene_data <- cached_scene$scene %||% NULL
	                        }
	                    }
	                    if (is.null(scene_data)) {
	                    app_perf_mark(aligned_perf, "aligned_scene_cache_hit=0", "ORTHO_ALIGNED")
	                    collect_t0 <- as.numeric(proc.time()[["elapsed"]])
	                    all_genes <- vector("list", length(ids_chr))
	                    track_geometry_modes <- rep("exon", length(ids_chr))
	                    titles_vec <- character(length(ids_chr))
	                    aligned_score_block_html <- function(value_txt, subtitle_txt, detail_html = "", note_html = "") {
	                        accent_col <- if (is_dark_theme) "#35D6A6" else "#18A97F"
	                        sub_col <- if (is_dark_theme) "#D5E7F5" else "#4E6476"
	                        border_col <- if (is_dark_theme) "rgba(137, 177, 206, 0.28)" else "rgba(118, 148, 169, 0.24)"
	                        sprintf(
	                            paste0(
	                                "<div style='margin-top:10px; padding-top:10px; border-top:1px solid %s;'>",
	                                "<div style='display:flex; align-items:flex-end; gap:10px; line-height:1;'>",
	                                "<span style='font-size:28px; font-weight:800; color:%s; letter-spacing:-0.02em;'>%s</span>",
	                                "<span style='font-size:11px; font-weight:700; color:%s; text-transform:uppercase; letter-spacing:0.04em;'>%s</span>",
	                                "</div>",
	                                "%s%s",
	                                "</div>"
	                            ),
	                            border_col, accent_col, value_txt, sub_col, subtitle_txt, detail_html, note_html
	                        )
	                    }
		                    for (i in seq_along(ids_chr)) {
	                        id_chr <- ids_chr[[i]]
	                        track_df <- tryCatch(
	                            {
	                                payload <- get_cached_aligned_track_payload(id_chr)
	                                df_raw <- payload$df %||% NULL
	                                norm_track <- tryCatch(normalize_aligned_track_for_mode(df_raw, mode = aligned_mode), error = function(e) NULL)
	                                df <- norm_track$track_df %||% df_raw
	                                if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
	                                    NULL
	                                } else {
	                                    n_rows <- nrow(df)
	                                    df$track_idx <- rep(as.numeric(i), n_rows)
	                                    geom_mode_i <- as.character(norm_track$geometry_mode %||% if (aligned_mode %in% c("protein", "cds")) "cds" else "exon")
	                                    df$aligned_geometry_mode <- rep(geom_mode_i, n_rows)
	                                    track_geometry_modes[i] <- geom_mode_i
	                                    half <- 0.18
	                                    df$ymin_feat <- i - half
	                                    df$ymax_feat <- i + half
	                                    df$tooltip_html <- as.character(df$tooltip_html_fast %||% rep("N/A", n_rows))
	                                    org_lbl_i <- as.character(payload$summary$org_name %||% paste("Org", i))
	                                    gene_lbl_i <- trimws(as.character(payload$summary$gene_name %||% ""))
	                                    strand_lbl_i <- trimws(as.character(payload$summary$strand_val %||% ""))
	                                    if (!strand_lbl_i %in% c("+", "-")) strand_lbl_i <- ""
	                                    titles_vec[i] <- if (nzchar(gene_lbl_i)) {
	                                        paste0(
	                                            org_lbl_i,
	                                            "\n",
	                                            gene_lbl_i,
	                                            if (nzchar(strand_lbl_i)) paste0(" (", strand_lbl_i, ")") else ""
	                                        )
	                                    } else {
	                                        org_lbl_i
	                                    }
	                                    df
	                                }
	                            },
	                            error = function(e) {
	                                app_perf_mark(aligned_perf, sprintf("track_error id=%s msg=%s", as.character(id_chr), as.character(e$message %||% "unknown")), "ORTHO_ALIGNED")
	                                NULL
                            }
                        )
                        if (is.null(track_df)) {
                            skipped_tracks <- skipped_tracks + 1L
                            all_genes[[i]] <- NULL
                        } else {
                            all_genes[[i]] <- track_df
                        }
                    }
                    collect_ms <- (as.numeric(proc.time()[["elapsed"]]) - collect_t0) * 1000
                    app_perf_mark(aligned_perf, sprintf("aligned_collect_ms=%.1f", collect_ms), "ORTHO_ALIGNED")
                    app_perf_mark(aligned_perf, sprintf("aligned_skipped_tracks=%d", as.integer(skipped_tracks)), "ORTHO_ALIGNED")

                    combined_df <- do.call(rbind,  Filter(Negate(is.null), all_genes))
                    valid_idx <- which(!vapply(all_genes, is.null, logical(1)))
	                    if (is.null(combined_df) || nrow(combined_df) == 0L || length(valid_idx) == 0L) {
	                        stop("fast-path-empty-tracks")
                    }

	                    ribbons_t0 <- as.numeric(proc.time()[["elapsed"]])
	                    exon_tracks <- vector("list", length(valid_idx))
                    for (vk in seq_along(valid_idx)) {
                        dfv <- all_genes[[valid_idx[vk]]]
                        if (is.null(dfv)) next
                        geom_mode_v <- as.character(dfv$aligned_geometry_mode[1] %||% if (aligned_mode %in% c("protein", "cds")) "cds" else "exon")
                        anchor_group_v <- if (identical(geom_mode_v, "cds")) "cds" else "exon"
                        dfve <- dfv[dfv$plot_group == anchor_group_v, , drop = FALSE]
                        if (nrow(dfve) == 0L && identical(anchor_group_v, "cds")) dfve <- dfv[dfv$plot_group == "exon", , drop = FALSE]
                        if (nrow(dfve) == 0L && identical(anchor_group_v, "exon")) dfve <- dfv[dfv$plot_group == "cds", , drop = FALSE]
                        if (nrow(dfve) == 0L) {
                            exon_tracks[[vk]] <- NULL
                        } else {
                            exon_tracks[[vk]] <- dfve[order(dfve$rel_start), , drop = FALSE]
                        }
                    }

                    n_pairs <- max(0L, length(valid_idx) - 1L)
                    pair_corrs <- vector("list", n_pairs)
                    pair_guided <- rep(FALSE, n_pairs)
                    pair_skipped <- rep(FALSE, n_pairs)
                    pair_corr_raw <- vector("list", n_pairs)
                    pair_corr_key <- character(n_pairs)
                    pair_has_data <- rep(FALSE, n_pairs)

                    # Pass 1: check cache, collect tasks for uncached pairs
                    uncached_indices <- integer(0)
                    uncached_tasks <- vector("list", n_pairs)
                    for (k in seq_len(n_pairs)) {
                        i1 <- valid_idx[k]
                        i2 <- valid_idx[k + 1L]
                        df1 <- all_genes[[i1]]
                        df2 <- all_genes[[i2]]
                        df1e <- exon_tracks[[k]]
                        df2e <- exon_tracks[[k + 1L]]
                        if (is.null(df1) || is.null(df2) || is.null(df1e) || is.null(df2e) ||
                                nrow(df1e) == 0L || nrow(df2e) == 0L) {
                            pair_skipped[k] <- TRUE
                            next
                        }
                        corr_key <- paste(
                            paste(df1e$xstart, collapse = ","),
                            paste(df1e$xend,   collapse = ","),
                            paste(df2e$xstart, collapse = ","),
                            paste(df2e$xend,   collapse = ","),
                            aligned_mode,
                            "dna_matrix_v2",
                            sep = "|"
                        )
                        pair_corr_key[k] <- corr_key
                        pair_has_data[k] <- TRUE
                        if (exists(corr_key, envir = orthoHomologyCache, inherits = FALSE)) {
                            pair_corr_raw[[k]] <- get(corr_key, envir = orthoHomologyCache, inherits = FALSE)
                        } else {
                            uncached_indices <- c(uncached_indices, k)
                            uncached_tasks[[k]] <- list(df1 = df1, df2 = df2, df1e = df1e, df2e = df2e)
                        }
                    }

                    # Pass 2: compute uncached pairs in-process.  Sending this mapper
                    # through future/furrr recursively exports the sequence helpers and
                    # their warm cache environments (multi-GiB in production) before any
                    # pair is evaluated.  The former error fallback already used this
                    # exact ordered lapply path, so make it the primary path and avoid the
                    # failed export without changing correspondence results or caching.
                    if (length(uncached_indices) > 0L) {
                        fn_corr <- compute_protein_guided_correspondence
                        local_aligned_mode <- aligned_mode
                        corr_compute_t0 <- as.numeric(proc.time()[["elapsed"]])
                        computed_list <- lapply(uncached_indices, function(k) {
                            task <- uncached_tasks[[k]]
                            tryCatch(
                                fn_corr(task$df1, task$df2, task$df1e, task$df2e, mode = local_aligned_mode),
                                error = function(e) NULL
                            )
                        })
                        corr_compute_ms <- (as.numeric(proc.time()[["elapsed"]]) - corr_compute_t0) * 1000
                        app_perf_mark(
                            aligned_perf,
                            sprintf(
                                "aligned_corr_compute_ms=%.1f pairs=%d schedule=in_process",
                                corr_compute_ms,
                                as.integer(length(uncached_indices))
                            ),
                            "ORTHO_ALIGNED"
                        )
                        for (j in seq_along(uncached_indices)) {
                            k <- uncached_indices[j]
                            computed <- computed_list[[j]]
                            assign(pair_corr_key[k], computed, envir = orthoHomologyCache)
                            trim_cache_env(orthoHomologyCache, max_size = 200L)
                            pair_corr_raw[[k]] <- computed
                        }
                    }

                    # Pass 3: assemble pair_corrs, pair_guided, count skipped
                    for (k in seq_len(n_pairs)) {
                        if (isTRUE(pair_skipped[k])) {
                            skipped_ribbons <- skipped_ribbons + 1L
                            next
                        }
                        if (!isTRUE(pair_has_data[k])) next
                        corr <- pair_corr_raw[[k]]
                        use_guided <- !is.null(corr) && is.data.frame(corr) && nrow(corr) > 0L
                        pair_guided[k] <- use_guided
                        if (use_guided) {
                            corr_filtered <- if (min_identity_thresh > 0) {
                                corr[is.na(corr$identity_pct) | corr$identity_pct >= min_identity_thresh, , drop = FALSE]
                            } else corr
                            pair_corrs[[k]] <- corr_filtered
                        } else {
                            i1 <- valid_idx[k]
                            i2 <- valid_idx[k + 1L]
                            df1e <- exon_tracks[[k]]
                            df2e <- exon_tracks[[k + 1L]]
                            n_match <- min(nrow(df1e), nrow(df2e))
                            pair_corrs[[k]] <- if (n_match > 0L) data.frame(
                                vis_exon_A = seq_len(n_match),
                                vis_exon_B = seq_len(n_match),
                                n_codons = NA_integer_,
                                identity_pct = NA_real_,
                                overall_pid = NA_real_,
                                event_type = "fallback",
                                stringsAsFactors = FALSE
                            ) else data.frame()
                        }
                    }

                    offset_layout <- tryCatch(
                        build_pairwise_aligned_offsets(exon_tracks, pair_corrs),
                        error = function(e) {
                            app_perf_mark(aligned_perf, sprintf("layout_error msg=%s", as.character(e$message %||% "unknown")), "ORTHO_ALIGNED")
                            list(offsets = rep(0, length(exon_tracks)), layouts = exon_tracks)
                        }
                    )
                    exon_layouts <- offset_layout$layouts %||% exon_tracks
                    track_offsets <- offset_layout$offsets %||% rep(0, length(exon_tracks))
                    for (vk in seq_along(valid_idx)) {
                        idx_i <- valid_idx[vk]
                        projected <- tryCatch(
                            project_features_with_track_offset(all_genes[[idx_i]], track_offsets[[vk]] %||% 0),
                            error = function(e) all_genes[[idx_i]]
                        )
                        all_genes[[idx_i]] <- projected
                    }
                    combined_df <- do.call(rbind,  Filter(Negate(is.null), all_genes))

	        ribbons <- list()
	        ribbon_labels <- list()
	        ribbon_hover_segments <- list()
                    relationship_palette <- synteny_relationship_palette()
                    event_fill_map <- relationship_palette$fill
                    event_alpha_map <- c(
                        "1:1"     = 0.13,
                        "1:n"     = 0.17,
                        "n:1"     = 0.17,
                        "partial" = 0.10,
                        "fallback"= 0.08
                    )
                    event_outline_map <- relationship_palette$outline
                    event_linetype_map <- relationship_palette$linetype
                    for (k in seq_len(max(0L, length(valid_idx) - 1L))) {
                        ribbon_pairs <- pair_corrs[[k]]
                        df1e <- exon_layouts[[k]]
                        df2e <- exon_layouts[[k + 1L]]
                        if (is.null(ribbon_pairs) || !is.data.frame(ribbon_pairs) || nrow(ribbon_pairs) == 0L ||
                                is.null(df1e) || is.null(df2e) || nrow(df1e) == 0L || nrow(df2e) == 0L) {
                            next
                        }

                        geom1 <- df1e
                        geom2 <- df2e
                        geom1$rel_start <- geom1$aligned_start
                        geom1$rel_end <- geom1$aligned_end
                        geom2$rel_start <- geom2$aligned_start
                        geom2$rel_end <- geom2$aligned_end
                        ribbon_pairs <- tryCatch(
                            add_split_geometry(ribbon_pairs, geom1, geom2),
                            error = function(e) ribbon_pairs
                        )

                        for (j in seq_len(nrow(ribbon_pairs))) {
                            row_j <- ribbon_pairs[j, , drop = FALSE]
                            idx_A <- as.integer(row_j$vis_exon_A[1])
                            idx_B <- as.integer(row_j$vis_exon_B[1])
                            if (is.na(idx_A) || idx_A < 1L || idx_A > nrow(df1e)) next
                            if (is.na(idx_B) || idx_B < 1L || idx_B > nrow(df2e)) next

                            ex1 <- df1e[idx_A, , drop = FALSE]
                            ex2 <- df2e[idx_B, , drop = FALSE]
                            y_top <- valid_idx[k] + 0.18
                            y_bot <- valid_idx[k + 1L] - 0.18
                            x1_span <- c(
                                as.numeric(row_j$x1L_adj[1] %||% ex1$aligned_start[1]),
                                as.numeric(row_j$x1R_adj[1] %||% ex1$aligned_end[1])
                            )
                            x2_span <- c(
                                as.numeric(row_j$x2L_adj[1] %||% ex2$aligned_start[1]),
                                as.numeric(row_j$x2R_adj[1] %||% ex2$aligned_end[1])
                            )
                            curve_pts <- fast_bezier_ribbon(
                                x1_span[1],
                                x1_span[2],
                                y_top,
                                x2_span[1],
                                x2_span[2],
                                y_bot,
                                n_pts = aligned_ribbon_points
                            )

                            etype <- as.character(row_j$event_type[1] %||% "fallback")
                            pid_val <- suppressWarnings(as.numeric(row_j$identity_pct[1]))
                            ov_pid <- suppressWarnings(as.numeric(row_j$overall_pid[1]))
                            n_cod <- suppressWarnings(as.integer(row_j$n_codons[1]))
                            size_detail_html <- aligned_ribbon_size_detail_html(
                                row_j,
                                aligned_mode,
                                is_dark_theme = is_dark_theme
                            )
                            size_diff <- abs(suppressWarnings(as.numeric(ex1$largo[1]) - as.numeric(ex2$largo[1])))
                            track_span_1 <- suppressWarnings(max(as.numeric(df1e$aligned_end), na.rm = TRUE) - min(as.numeric(df1e$aligned_start), na.rm = TRUE))
                            track_span_2 <- suppressWarnings(max(as.numeric(df2e$aligned_end), na.rm = TRUE) - min(as.numeric(df2e$aligned_start), na.rm = TRUE))
                            ribbon_style <- compute_aligned_ribbon_style(
                                event_type = etype,
                                identity_pct = pid_val,
                                guided = isTRUE(pair_guided[k]),
                                span_a = x1_span[2] - x1_span[1],
                                span_b = x2_span[2] - x2_span[1],
                                track_span_a = track_span_1,
                                track_span_b = track_span_2,
                                base_alpha = event_alpha_map[etype] %||% 0.08,
                                base_linewidth = 0.10
                            )
                            curve_pts$poly_id <- paste0("rib_", valid_idx[k], "_", valid_idx[k + 1L], "_", j)
                            curve_pts$ribbon_fill <- event_fill_map[etype] %||% "#2F6B9A"
                            curve_pts$ribbon_outline <- event_outline_map[etype] %||% "#214E70"
                            curve_pts$ribbon_linetype <- event_linetype_map[etype] %||% "solid"
                            curve_pts$ribbon_alpha <- ribbon_style$alpha
                            curve_pts$ribbon_linewidth <- ribbon_style$linewidth

                            gc1 <- get_cached_gc(ex1$genome_path[1], ex1$seqid[1], ex1$xstart[1], ex1$xend[1])
                            gc2 <- get_cached_gc(ex2$genome_path[1], ex2$seqid[1], ex2$xstart[1], ex2$xend[1])
	                            gc_html <- if (is.finite(gc1) && is.finite(gc2)) {
	                                sprintf("<b>GC:</b> %.1f%% vs %.1f%%", gc1, gc2)
	                            } else "<b>GC:</b> N/A"

	                            identity_label <- aligned_identity_metric_label(aligned_mode)
	                            support_label <- aligned_support_metric_label(aligned_mode)
	                            event_label <- aligned_event_display_label(etype, compact = FALSE)
	                            anchor_label <- aligned_anchor_unit_label(ex1$aligned_geometry_mode[1] %||% "exon")
	                            geometry_note <- aligned_geometry_note(aligned_mode, ex1$aligned_geometry_mode[1] %||% "exon")
	                            split_summary <- aligned_split_summary(ribbon_pairs, row_j, aligned_mode = aligned_mode)
	                            event_detail_html <- if (identical(tolower(trimws(as.character(etype %||% ""))), "partial")) {
	                                sprintf(
	                                    "<div style='margin-top:4px; font-size:11px; color:%s;'><b>Interpretation:</b> significant aligned support is distributed across multiple blocks on both tracks, so this is not a clean 1:1 or split-only mapping.</div>",
	                                    if (is_dark_theme) "#C4D8E8" else "#60788A"
	                                )
	                            } else ""
	                            split_detail_html <- if (!is.null(split_summary)) {
	                                sprintf(
	                                    paste0(
	                                        "<div style='margin-top:4px; font-size:11px; color:%s;'>",
	                                        "<b>Combined aligned support across split ribbons:</b> %s %s",
	                                        "</div>"
	                                    ),
	                                    if (is_dark_theme) "#C4D8E8" else "#60788A",
	                                    format(as.integer(round(split_summary$support_total)), big.mark = ","),
	                                    split_summary$support_unit
	                                )
	                            } else ""
	                            detail_html <- paste0(split_detail_html, event_detail_html)
	                            if (isTRUE(pair_guided[k])) {
	                                pid_txt <- if (is.finite(pid_val)) sprintf("%.1f%%", pid_val) else "N/A"
	                                cod_txt <- if (!is.na(n_cod)) as.character(n_cod) else "N/A"
	                                score_block_html <- aligned_score_block_html(
	                                    value_txt = pid_txt,
	                                    subtitle_txt = paste(identity_label, "score"),
	                                    detail_html = detail_html,
	                                    note_html = sprintf(
	                                        "<div style='margin-top:4px; font-size:11px; color:%s;'><b>%s:</b> %s &nbsp;&middot;&nbsp; <b>Event:</b> %s</div>",
	                                        if (is_dark_theme) "#C4D8E8" else "#60788A",
	                                        support_label, cod_txt, event_label
	                                    )
	                                )
	                                ident_html <- sprintf(
	                                    "<div style='margin-top:1px; font-size:inherit; line-height:1.2; color:inherit;'>%s<br/>%s</div>%s",
	                                    gc_html,
	                                    geometry_note,
	                                    score_block_html
	                                )
	                            } else {
                                seq1_txt <- get_cached_seq(ex1$genome_path[1], ex1$seqid[1], ex1$xstart[1], ex1$xend[1])
                                seq2_txt <- get_cached_seq(ex2$genome_path[1], ex2$seqid[1], ex2$xstart[1], ex2$xend[1])
	                                fb_ident <- aligned_pairwise_fallback_identity(seq1_txt, seq2_txt, aligned_mode = aligned_mode)
	                                if (is.finite(fb_ident$identity)) {
	                                    score_block_html <- aligned_score_block_html(
	                                        value_txt = sprintf("%.1f%%", as.numeric(fb_ident$identity)),
	                                        subtitle_txt = "fallback identity",
	                                        detail_html = detail_html,
	                                        note_html = sprintf(
	                                            "<div style='margin-top:4px; font-size:11px; color:%s;'><b>Event:</b> %s</div>",
	                                            if (is_dark_theme) "#C4D8E8" else "#60788A",
	                                            event_label
	                                        )
	                                    )
	                                    ident_html <- sprintf(
	                                        "<b>Fallback pairwise identity:</b> %.1f%%<br/><b>%s</b><br/>%s%s",
	                                        as.numeric(fb_ident$identity), geometry_note, as.character(fb_ident$note %||% ""), score_block_html
	                                    )
	                                } else {
	                                    ident_html <- sprintf(
	                                        "<b>Fallback pairwise identity:</b> N/A<br/><b>%s</b><br/>%s",
	                                        geometry_note, as.character(fb_ident$note %||% "Pairwise identity unavailable")
	                                    )
	                                }
	                            }

	                            curve_pts$tooltip <- sprintf(
	                                "<b>%s</b><br/><b>%s</b> %s %d &#8596; <b>%s</b> %s %d<br/>Top genomic: %s&#8211;%s bp<br/>Bottom genomic: %s&#8211;%s bp<br/>Size diff: %s bp%s%s",
	                                event_label,
	                                esc_fast(ex1$org_label[1]),
	                                anchor_label,
	                                as.integer(idx_A),
                                esc_fast(ex2$org_label[1]),
	                                anchor_label,
                                as.integer(idx_B),
                                format(round(as.numeric(ex1$xstart[1])), big.mark = ","),
                                format(round(as.numeric(ex1$xend[1])), big.mark = ","),
	                                format(round(as.numeric(ex2$xstart[1])), big.mark = ","),
	                                format(round(as.numeric(ex2$xend[1])), big.mark = ","),
	                                format(round(size_diff), big.mark = ","),
	                                size_detail_html,
	                                ident_html
	                            )
	                            ribbons[[length(ribbons) + 1L]] <- curve_pts
	                            ribbon_hover_segments[[length(ribbon_hover_segments) + 1L]] <- data.frame(
	                                x = mean(x1_span),
	                                xend = mean(x2_span),
	                                y = y_top,
	                                yend = y_bot,
	                                tooltip = curve_pts$tooltip[1],
	                                data_id = paste0(curve_pts$poly_id[1], "_hover"),
	                                stringsAsFactors = FALSE
	                            )
                        }
                    }
                    ribbons_ms <- (as.numeric(proc.time()[["elapsed"]]) - ribbons_t0) * 1000
                    app_perf_mark(aligned_perf, sprintf("aligned_gc_ms=%.1f", gc_ms_accum), "ORTHO_ALIGNED")
                    app_perf_mark(aligned_perf, sprintf("aligned_ribbons_ms=%.1f", ribbons_ms), "ORTHO_ALIGNED")

                    build_t0 <- as.numeric(proc.time()[["elapsed"]])
                    ribbon_df <- if (length(ribbons) > 0L) do.call(rbind,  ribbons) else data.frame()
                    ribbon_label_df <- data.frame()
                    feature_palette_colors <- get_transcript_feature_palette(
                        is_dark_theme = is_dark_theme,
                        is_colorblind_mode = isTRUE(input$colorblind_mode),
                        custom_overrides = get_custom_color_palette()
                    )
	                    visible_groups <- if (aligned_mode %in% c("protein", "cds")) "cds" else c("utr", "cds", "exon")
	                    req_df_base <- combined_df[
	                        !is.na(combined_df$disp_start) &
	                        !is.na(combined_df$disp_end) &
	                        combined_df$plot_group %in% visible_groups,
	                        , drop = FALSE
	                    ]
	                    if (aligned_mode %in% c("protein", "cds")) {
	                        missing_feature_tracks <- setdiff(
	                            as.character(valid_idx),
	                            unique(as.character(suppressWarnings(as.integer(req_df_base$track_idx))))
	                        )
	                        if (length(missing_feature_tracks) > 0L) {
	                            fallback_exon_df <- combined_df[
	                                !is.na(combined_df$disp_start) &
	                                    !is.na(combined_df$disp_end) &
	                                    combined_df$plot_group == "exon" &
	                                    as.character(suppressWarnings(as.integer(combined_df$track_idx))) %in% missing_feature_tracks,
	                                , drop = FALSE
	                            ]
	                            if (nrow(fallback_exon_df) > 0L) {
	                                req_df_base <- rbind(req_df_base, fallback_exon_df)
	                            }
	                        }
	                    }
	                    if (nrow(req_df_base) > 0L) {
	                        draw_order <- if (aligned_mode %in% c("protein", "cds")) c("cds") else c("utr", "cds", "exon")
	                        req_df_base$draw_rank <- match(req_df_base$plot_group, draw_order, nomatch = 0)
	                        req_df_base <- req_df_base[order(req_df_base$draw_rank), , drop = FALSE]
	                    }
	                    extent_df <- if (nrow(req_df_base) > 0L) req_df_base else combined_df
                    track_spans <- vapply(valid_idx, function(idx_i) {
	                        g <- extent_df[extent_df$track_idx == idx_i, , drop = FALSE]
	                        if (is.null(g) || nrow(g) == 0L) {
	                            g <- all_genes[[idx_i]]
	                        }
                        if (is.null(g) || nrow(g) == 0L) return(NA_real_)
                        gstart <- suppressWarnings(min(as.numeric(g$disp_start), na.rm = TRUE))
                        gend <- suppressWarnings(max(as.numeric(g$disp_end), na.rm = TRUE))
                        span <- gend - gstart
                        if (!is.finite(span) || span <= 0) NA_real_ else span
