        # --- Helper: HTML-escape for tooltips ---
        esc <- function(x) {
            x <- as.character(x %||% "")
            x <- gsub("&", "&amp;", x, fixed = TRUE)
            x <- gsub("<", "&lt;", x, fixed = TRUE)
            x <- gsub(">", "&gt;", x, fixed = TRUE)
            x
        }
        format_gc_pct <- function(gc_pct) {
            if (!is.finite(gc_pct)) {
                return("N/A")
            }
            sprintf("%.2f%%", as.numeric(gc_pct))
        }
        calc_gc_pct <- function(seq_txt) {
            seq_txt <- toupper(gsub("\\s+", "", as.character(seq_txt %||% "")))
            if (!nzchar(seq_txt)) {
                return(NA_real_)
            }
            known_bases <- gsub("[^ATCG]", "", seq_txt)
            known_total <- nchar(known_bases)
            if (known_total <= 0) {
                return(NA_real_)
            }
            gc_count <- nchar(gsub("[^GC]", "", known_bases))
            round(100 * gc_count / known_total, 2)
        }
        aligned_gc_cache <- new.env(parent = emptyenv())
        get_aligned_gc_pct <- function(fasta_path, seqid, start_pos, end_pos) {
            fasta_path <- trimws(as.character(fasta_path %||% ""))
            if (!nzchar(fasta_path) || !file.exists(fasta_path)) {
                return(NA_real_)
            }
            seqid_txt <- trimws(as.character(seqid %||% ""))
            start_num <- suppressWarnings(as.numeric(start_pos))
            end_num <- suppressWarnings(as.numeric(end_pos))
            if (!nzchar(seqid_txt) || !is.finite(start_num) || !is.finite(end_num)) {
                return(NA_real_)
            }
            start_i <- as.integer(round(min(start_num, end_num)))
            end_i <- as.integer(round(max(start_num, end_num)))
            if (start_i < 1L || end_i < start_i) {
                return(NA_real_)
            }
            cache_key <- paste(normalizePath(fasta_path, winslash = "/", mustWork = FALSE), seqid_txt, start_i, end_i, sep = "::")
            if (exists(cache_key, envir = aligned_gc_cache, inherits = FALSE)) {
                return(get(cache_key, envir = aligned_gc_cache, inherits = FALSE))
            }
            t_gc <- as.numeric(proc.time()[["elapsed"]])
            seq_txt <- tryCatch(
                extract_sequence_from_fasta(fasta_path, seqid_txt, start_i, end_i),
                error = function(e) ""
            )
            legacy_gc_ms <<- legacy_gc_ms + (as.numeric(proc.time()[["elapsed"]]) - t_gc) * 1000
            gc_pct <- calc_gc_pct(seq_txt)
            assign(cache_key, gc_pct, envir = aligned_gc_cache)
            gc_pct
        }

        # --- Helper: build rich tooltip from GFF attributes ---
        build_aligned_tooltip <- function(row) {
            attrs <- parse_gff_attributes(as.character(row$attributes_raw %||% ""))
            attr_lines <- character()
            if (length(attrs) > 0) {
                keys <- names(attrs)
                keys <- keys[!is.na(keys) & nzchar(keys)]
                attr_lines <- vapply(keys, function(k) {
                    vals <- attrs[[k]]
                    vals <- vals[!is.na(vals) & nzchar(trimws(vals))]
                    val_txt <- if (length(vals) == 0) "N/A" else paste(unique(vals), collapse = ", ")
                    lbl <- stringr::str_to_title(gsub("_", " ", k))
                    sprintf("<b>%s:</b> %s", esc(lbl), esc(val_txt))
                }, character(1))
            }
            attr_block <- if (length(attr_lines) > 0) {
                paste0(
                    "<hr style='border:none;border-top:1px solid #B6CCC6;margin:4px 0;'/>",
                    paste(attr_lines, collapse = "<br/>")
                )
            } else {
                ""
            }
            sprintf(
                "<b><em>%s</em></b><br/><b>Type:</b> %s<br/><b>Chr:</b> %s<br/><b>Start:</b> %s<br/><b>End:</b> %s<br/><b>Strand:</b> %s<br/><b>Length:</b> %s bp<br/><b>GC:</b> %s%s",
                esc(row$org_label),
                esc(row$feature_raw),
                esc(
                    get_short_chromosome_name(
                        row$seqid,
                        as.character(row$annotation_path %||% ""),
                        use_report_map = TRUE
                    )
                ),
                format(round(row$xstart), big.mark = ","),
                format(round(row$xend), big.mark = ","),
                esc(row$strand), format(round(row$largo), big.mark = ","),
                esc(row$gc_label),
                attr_block
            )
        }

        # --- Helper: cubic Bezier ribbon with true S-curves ---
        bezier_ribbon <- function(x1L, x1R, y1, x2L, x2R, y2, n_pts = 50) {
            t_seq <- seq(0, 1, length.out = n_pts)
            cubic_curve <- function(p0, p1, p2, p3, t) {
                ((1 - t)^3 * p0) +
                    (3 * (1 - t)^2 * t * p1) +
                    (3 * (1 - t) * t^2 * p2) +
                    (t^3 * p3)
            }

            cp_y <- (y1 + y2) / 2
            curve_y <- cubic_curve(y1, cp_y, cp_y, y2, t_seq)
            left_x <- cubic_curve(x1L, x1L, x2L, x2L, t_seq)
            right_x <- cubic_curve(x1R, x1R, x2R, x2R, t_seq)

            data.frame(
                x = c(left_x, rev(right_x)),
                y = c(curve_y, rev(curve_y)),
                stringsAsFactors = FALSE
            )
        }

