            df$gene_name <- rep(gene_name, n_rows)
            df$annotation_path <- rep(ann_path, n_rows)
            df$genome_path <- rep(genome_path, n_rows)
            df$gc_label <- vapply(seq_len(n_rows), function(j) {
                gc_pct <- get_aligned_gc_pct(genome_path, df$seqid[j], df$xstart[j], df$xend[j])
                format_gc_pct(gc_pct)
            }, character(1))
            df$feature_uid <- paste0("aligned_", id_chr, "_", seq_len(n_rows))

            df$plot_group <- ifelse(df$feature_type == "gene", "gene",
                ifelse(df$feature_type == "exon", "exon",
                    ifelse(df$feature_type == "cds", "cds",
                        ifelse(grepl("utr", df$feature_type), "utr",
                            ifelse(df$feature_type %in% c("start_codon", "stop_codon"), "codon", "other")
                        )
                    )
                )
            )

            # Uniform height for all features so they completely overlap (hide UTRs/CDS under Exons)
            half <- 0.18
            df$ymin_feat <- i - half
            df$ymax_feat <- i + half

            # Rich tooltips
            df$tooltip_html <- vapply(seq_len(n_rows), function(j) build_aligned_tooltip(df[j, ]), character(1))

            all_genes[[i]] <- df
        }
        collect_ms_legacy <- (as.numeric(proc.time()[["elapsed"]]) - collect_t0_legacy) * 1000
        app_perf_mark(aligned_perf, sprintf("aligned_collect_ms=%.1f", collect_ms_legacy), "ORTHO_ALIGNED")
        app_perf_mark(aligned_perf, sprintf("aligned_skipped_tracks=%d", as.integer(skipped_tracks_legacy)), "ORTHO_ALIGNED")

        combined_df <- do.call(rbind,  Filter(Negate(is.null), all_genes))
        if (is.null(combined_df) || nrow(combined_df) == 0) {
            total_ms_legacy <- (as.numeric(proc.time()[["elapsed"]]) - legacy_total_t0) * 1000
            app_perf_mark(aligned_perf, sprintf("aligned_gc_ms=%.1f", legacy_gc_ms), "ORTHO_ALIGNED")
            app_perf_mark(aligned_perf, "aligned_ribbons_ms=0.0", "ORTHO_ALIGNED")
            app_perf_mark(aligned_perf, "aligned_plot_build_ms=0.0", "ORTHO_ALIGNED")
            app_perf_mark(aligned_perf, sprintf("aligned_total_ms=%.1f", total_ms_legacy), "ORTHO_ALIGNED")
            send_girafe_diag_expected(
                "ortho_aligned_plot_out",
                expected = list(
                    render_mode = "aligned",
                    cache_hit = FALSE,
                    feature_hover = 0L,
                    ribbon_hover = 0L,
                    interactive_total = 0L
                ),
                meta = list(reason = "empty_combined_df")
            )
            return(build_aligned_placeholder_simple("No aligned tracks could be rendered"))
        }

        # --- Curved Bezier ribbons between adjacent tracks ---
        ribbons_t0_legacy <- as.numeric(proc.time()[["elapsed"]])
        ribbons <- list()
        ribbon_labels <- list()
        ribbon_hover_segments <- list()
        valid_idx <- which(!vapply(all_genes, is.null, logical(1)))
        exon_tracks <- vector("list", length(valid_idx))
        for (vk in seq_along(valid_idx)) {
            dfv <- all_genes[[valid_idx[vk]]]
            if (is.null(dfv)) next
            geom_mode_v <- as.character(dfv$aligned_geometry_mode[1] %||% if (aligned_mode %in% c("protein", "cds")) "cds" else "exon")
            anchor_group_v <- if (identical(geom_mode_v, "cds")) "cds" else "exon"
            dfve <- dfv[dfv$plot_group == anchor_group_v, , drop = FALSE]
            if (nrow(dfve) == 0L && identical(anchor_group_v, "cds")) dfve <- dfv[dfv$plot_group == "exon", , drop = FALSE]
            if (nrow(dfve) == 0L && identical(anchor_group_v, "exon")) dfve <- dfv[dfv$plot_group == "cds", , drop = FALSE]
            exon_tracks[[vk]] <- if (nrow(dfve) > 0L) dfve[order(dfve$rel_start), , drop = FALSE] else NULL
        }

        pair_corrs <- vector("list", max(0L, length(valid_idx) - 1L))
        pair_guided <- rep(FALSE, max(0L, length(valid_idx) - 1L))
        if (length(valid_idx) > 1L) {
            for (k in seq_len(length(valid_idx) - 1L)) {
                i1 <- valid_idx[k]
                i2 <- valid_idx[k + 1L]
                df1 <- all_genes[[i1]]
                df2 <- all_genes[[i2]]
                df1e <- exon_tracks[[k]]
                df2e <- exon_tracks[[k + 1L]]
                if (is.null(df1) || is.null(df2) || is.null(df1e) || is.null(df2e) || nrow(df1e) == 0L || nrow(df2e) == 0L) {
                    skipped_ribbons_legacy <- skipped_ribbons_legacy + 1L
                    next
                }

                corr_key_leg <- paste(
                    paste(df1e$xstart, collapse = ","),
                    paste(df1e$xend,   collapse = ","),
                    paste(df2e$xstart, collapse = ","),
                    paste(df2e$xend,   collapse = ","),
                    aligned_mode,
                    "dna_matrix_v2",
                    sep = "|"
                )
                corr_leg <- if (exists(corr_key_leg, envir = orthoHomologyCache, inherits = FALSE)) {
                    get(corr_key_leg, envir = orthoHomologyCache, inherits = FALSE)
                } else {
                    computed_leg <- tryCatch(
                        compute_protein_guided_correspondence(df1, df2, df1e, df2e, mode = aligned_mode),
                        error = function(e) NULL
                    )
                    assign(corr_key_leg, computed_leg, envir = orthoHomologyCache)
                    trim_cache_env(orthoHomologyCache, max_size = 200L)
                    computed_leg
                }

                use_guided_leg <- !is.null(corr_leg) && is.data.frame(corr_leg) && nrow(corr_leg) > 0L
                pair_guided[k] <- use_guided_leg
	                if (use_guided_leg) {
	                    corr_filtered_leg <- if (min_identity_thresh > 0) {
	                        corr_leg[is.na(corr_leg$identity_pct) | corr_leg$identity_pct >= min_identity_thresh, , drop = FALSE]
	                    } else corr_leg
	                    pair_corrs[[k]] <- corr_filtered_leg
                } else {
                    n_match <- min(nrow(df1e), nrow(df2e))
                    pair_corrs[[k]] <- if (n_match > 0L) data.frame(
                        vis_exon_A = seq_len(n_match),
                        vis_exon_B = seq_len(n_match),
                        n_codons = NA_integer_,
                        identity_pct = NA_real_,
                        overall_pid = NA_real_,
                        event_type = "fallback",
                        stringsAsFactors = FALSE
                    ) else data.frame()
                }
            }
        }

        offset_layout <- tryCatch(
            build_pairwise_aligned_offsets(exon_tracks, pair_corrs),
            error = function(e) {
                app_perf_mark(aligned_perf, sprintf("legacy_layout_error msg=%s", as.character(e$message %||% "unknown")), "ORTHO_ALIGNED")
                list(offsets = rep(0, length(exon_tracks)), layouts = exon_tracks)
            }
        )
        exon_layouts <- offset_layout$layouts %||% exon_tracks
        track_offsets <- offset_layout$offsets %||% rep(0, length(exon_tracks))
        for (vk in seq_along(valid_idx)) {
            idx_i <- valid_idx[vk]
            all_genes[[idx_i]] <- tryCatch(
                project_features_with_track_offset(all_genes[[idx_i]], track_offsets[[vk]] %||% 0),
                error = function(e) all_genes[[idx_i]]
            )
        }
        combined_df <- do.call(rbind,  Filter(Negate(is.null), all_genes))

        relationship_palette_leg <- synteny_relationship_palette()
        event_fill_map_leg <- relationship_palette_leg$fill
        event_alpha_map_leg <- c("1:1"=0.13, "1:n"=0.17, "n:1"=0.17, "partial"=0.10, "fallback"=0.08)
        event_outline_map_leg <- relationship_palette_leg$outline
        event_linetype_map_leg <- relationship_palette_leg$linetype
        for (k in seq_len(max(0L, length(valid_idx) - 1L))) {
            ribbon_pairs_leg <- pair_corrs[[k]]
            df1e <- exon_layouts[[k]]
            df2e <- exon_layouts[[k + 1L]]
            if (is.null(ribbon_pairs_leg) || !is.data.frame(ribbon_pairs_leg) || nrow(ribbon_pairs_leg) == 0L ||
                    is.null(df1e) || is.null(df2e) || nrow(df1e) == 0L || nrow(df2e) == 0L) {
                next
            }

            geom1 <- df1e
            geom2 <- df2e
            geom1$rel_start <- geom1$aligned_start
            geom1$rel_end <- geom1$aligned_end
            geom2$rel_start <- geom2$aligned_start
            geom2$rel_end <- geom2$aligned_end
            ribbon_pairs_leg <- tryCatch(
                add_split_geometry(ribbon_pairs_leg, geom1, geom2),
                error = function(e) ribbon_pairs_leg
            )

            for (j in seq_len(nrow(ribbon_pairs_leg))) {
                row_j_leg <- ribbon_pairs_leg[j, , drop = FALSE]
                idx_A_leg <- as.integer(row_j_leg$vis_exon_A[1])
                idx_B_leg <- as.integer(row_j_leg$vis_exon_B[1])
                if (is.na(idx_A_leg) || idx_A_leg < 1L || idx_A_leg > nrow(df1e)) next
                if (is.na(idx_B_leg) || idx_B_leg < 1L || idx_B_leg > nrow(df2e)) next

                ex1 <- df1e[idx_A_leg, , drop = FALSE]
                ex2 <- df2e[idx_B_leg, , drop = FALSE]
                y_top <- valid_idx[k] + 0.18
                y_bot <- valid_idx[k + 1L] - 0.18
                x1_span_leg <- c(
                    as.numeric(row_j_leg$x1L_adj[1] %||% ex1$aligned_start[1]),
                    as.numeric(row_j_leg$x1R_adj[1] %||% ex1$aligned_end[1])
                )
                x2_span_leg <- c(
                    as.numeric(row_j_leg$x2L_adj[1] %||% ex2$aligned_start[1]),
                    as.numeric(row_j_leg$x2R_adj[1] %||% ex2$aligned_end[1])
                )
                curve_pts <- bezier_ribbon(
                    x1_span_leg[1],
                    x1_span_leg[2],
                    y_top,
                    x2_span_leg[1],
                    x2_span_leg[2],
                    y_bot,
                    n_pts = aligned_ribbon_points
                )

                etype_leg <- as.character(row_j_leg$event_type[1] %||% "fallback")
                pid_val_leg <- suppressWarnings(as.numeric(row_j_leg$identity_pct[1]))
                ov_pid_leg <- suppressWarnings(as.numeric(row_j_leg$overall_pid[1]))
                n_cod_leg <- suppressWarnings(as.integer(row_j_leg$n_codons[1]))
                size_detail_html_leg <- aligned_ribbon_size_detail_html(
                    row_j_leg,
                    aligned_mode,
                    is_dark_theme = is_dark_theme
                )
                size_diff <- abs(round(suppressWarnings(as.numeric(ex1$largo[1])) - suppressWarnings(as.numeric(ex2$largo[1]))))
                track_span_1_leg <- suppressWarnings(max(as.numeric(df1e$aligned_end), na.rm = TRUE) - min(as.numeric(df1e$aligned_start), na.rm = TRUE))
                track_span_2_leg <- suppressWarnings(max(as.numeric(df2e$aligned_end), na.rm = TRUE) - min(as.numeric(df2e$aligned_start), na.rm = TRUE))
                ribbon_style_leg <- compute_aligned_ribbon_style(
                    event_type = etype_leg,
                    identity_pct = pid_val_leg,
                    guided = isTRUE(pair_guided[k]),
                    span_a = x1_span_leg[2] - x1_span_leg[1],
                    span_b = x2_span_leg[2] - x2_span_leg[1],
                    track_span_a = track_span_1_leg,
                    track_span_b = track_span_2_leg,
                    base_alpha = event_alpha_map_leg[etype_leg] %||% 0.08,
                    base_linewidth = 0.10
                )
                curve_pts$poly_id <- paste0("rib_", valid_idx[k], "_", valid_idx[k + 1L], "_", j)
                curve_pts$ribbon_fill <- event_fill_map_leg[etype_leg] %||% "#2F6B9A"
                curve_pts$ribbon_outline <- event_outline_map_leg[etype_leg] %||% "#214E70"
                curve_pts$ribbon_linetype <- event_linetype_map_leg[etype_leg] %||% "solid"
                curve_pts$ribbon_alpha <- ribbon_style_leg$alpha
                curve_pts$ribbon_linewidth <- ribbon_style_leg$linewidth

	                identity_label_leg <- aligned_identity_metric_label(aligned_mode)
	                support_label_leg <- aligned_support_metric_label(aligned_mode)
	                event_label_leg <- aligned_event_display_label(etype_leg, compact = FALSE)
	                anchor_label_leg <- aligned_anchor_unit_label(ex1$aligned_geometry_mode[1] %||% "exon")
	                geometry_note_leg <- aligned_geometry_note(aligned_mode, ex1$aligned_geometry_mode[1] %||% "exon")
                    split_summary_leg <- aligned_split_summary(ribbon_pairs_leg, row_j_leg, aligned_mode = aligned_mode)
                    split_detail_html_leg <- if (!is.null(split_summary_leg)) {
                        sprintf(
                            paste0(
                                "<div style='margin-top:4px; font-size:11px; color:%s;'>",
                                "<b>Combined aligned support across split ribbons:</b> %s %s",
                                "</div>"
                            ),
                            if (is_dark_theme) "#C4D8E8" else "#60788A",
                            format(as.integer(round(split_summary_leg$support_total)), big.mark = ","),
                            split_summary_leg$support_unit
                        )
                    } else ""
	                if (isTRUE(pair_guided[k])) {
                    gc1 <- tryCatch(calc_gc_pct(tryCatch(
                        extract_sequence_from_fasta(ex1$genome_path[1], ex1$seqid[1], ex1$xstart[1], ex1$xend[1]),
                        error = function(e) "")), error = function(e) NA_real_)
                    gc2 <- tryCatch(calc_gc_pct(tryCatch(
                        extract_sequence_from_fasta(ex2$genome_path[1], ex2$seqid[1], ex2$xstart[1], ex2$xend[1]),
                        error = function(e) "")), error = function(e) NA_real_)
                    gc_html <- if (is.finite(gc1) && is.finite(gc2)) {
                        sprintf("<b>GC:</b> %.1f%% vs %.1f%%", gc1, gc2)
                    } else "<b>GC:</b> N/A"
                    pid_txt_leg <- if (is.finite(pid_val_leg)) sprintf("%.1f%%", pid_val_leg) else "N/A"
                    cod_txt_leg <- if (!is.na(n_cod_leg))      as.character(n_cod_leg)        else "N/A"
                    score_block_leg <- aligned_score_block_html(
                        value_txt = pid_txt_leg,
                        subtitle_txt = paste(identity_label_leg, "score"),
                        detail_html = split_detail_html_leg,
                        note_html = sprintf(
                            "<div style='margin-top:4px; font-size:11px; color:%s;'><b>%s:</b> %s &nbsp;&middot;&nbsp; <b>Event:</b> %s</div>",
                            if (is_dark_theme) "#C4D8E8" else "#60788A",
                            support_label_leg, cod_txt_leg, event_label_leg
                        )
                    )
	                    align_html <- sprintf(
	                        "<div style='margin-top:1px; font-size:inherit; line-height:1.2; color:inherit;'>%s<br/>%s</div>%s",
	                        gc_html, geometry_note_leg, score_block_leg
	                    )
                } else {
                    seq1_txt <- tryCatch(extract_sequence_from_fasta(ex1$genome_path, ex1$seqid, ex1$xstart, ex1$xend), error = function(e) "")
                    seq2_txt <- tryCatch(extract_sequence_from_fasta(ex2$genome_path, ex2$seqid, ex2$xstart, ex2$xend), error = function(e) "")
                    align_html <- ""
                    if (nzchar(seq1_txt) && nzchar(seq2_txt)) {
                        gc1 <- calc_gc_pct(seq1_txt); gc2 <- calc_gc_pct(seq2_txt)
                        gc_html <- if (is.finite(gc1) && is.finite(gc2)) sprintf("<b>GC Sim:</b> %.1f%% vs %.1f%%", gc1, gc2) else "<b>GC Sim:</b> N/A"
	                        fb_ident_leg <- aligned_pairwise_fallback_identity(seq1_txt, seq2_txt, aligned_mode = aligned_mode)
	                        ident_html <- if (is.finite(fb_ident_leg$identity)) {
	                            score_block_leg <- aligned_score_block_html(
	                                value_txt = sprintf("%.1f%%", as.numeric(fb_ident_leg$identity)),
	                                subtitle_txt = "fallback identity",
	                                detail_html = split_detail_html_leg,
	                                note_html = sprintf(
	                                    "<div style='margin-top:4px; font-size:11px; color:%s;'><b>Event:</b> %s</div>",
	                                    if (is_dark_theme) "#C4D8E8" else "#60788A",
	                                    event_label_leg
	                                )
	                            )
	                            sprintf("<b>Fallback pairwise identity:</b> %.1f%%%s", as.numeric(fb_ident_leg$identity), score_block_leg)
	                        } else {
	                            "<b>Fallback pairwise identity:</b> N/A"
	                        }
	                        align_html <- paste0(
	                            "<br/>", gc_html,
	                            "<br/>", ident_html,
	                            "<br/><b>", geometry_note_leg, "</b>",
	                            "<br/>", as.character(fb_ident_leg$note %||% "Pairwise identity unavailable")
	                        )
                    }
                }

	                curve_pts$tooltip <- sprintf(
	                    "<b>%s</b><br/><b>%s</b> %s %d &#8596; <b>%s</b> %s %d<br/>Top genomic: %s&#8211;%s bp<br/>Bottom genomic: %s&#8211;%s bp<br/>Size diff: %s bp<br/>%s%s",
	                    event_label_leg,
	                    esc(ex1$org_label[1]),
	                    anchor_label_leg,
	                    as.integer(idx_A_leg),
	                    esc(ex2$org_label[1]),
	                    anchor_label_leg,
	                    as.integer(idx_B_leg),
	                    format(round(ex1$xstart[1]), big.mark = ","), format(round(ex1$xend[1]), big.mark = ","),
	                    format(round(ex2$xstart[1]), big.mark = ","), format(round(ex2$xend[1]), big.mark = ","),
	                    format(size_diff, big.mark = ","), size_detail_html_leg, align_html
	                )
	                ribbons[[length(ribbons) + 1L]] <- curve_pts
	                ribbon_hover_segments[[length(ribbon_hover_segments) + 1L]] <- data.frame(
	                    x = mean(x1_span_leg),
	                    xend = mean(x2_span_leg),
	                    y = y_top,
	                    yend = y_bot,
	                    tooltip = curve_pts$tooltip[1],
	                    data_id = paste0(curve_pts$poly_id[1], "_hover"),
	                    stringsAsFactors = FALSE
	                )
	                if (isTRUE(pair_guided[k]) && is.finite(pid_val_leg)) {
                    rib_width_leg <- max(
                        suppressWarnings(as.numeric(x1_span_leg[2] - x1_span_leg[1])),
                        suppressWarnings(as.numeric(x2_span_leg[2] - x2_span_leg[1])),
                        na.rm = TRUE
                    )
                    ribbon_labels[[length(ribbon_labels) + 1L]] <- data.frame(
                        x = mean(c(mean(x1_span_leg), mean(x2_span_leg))),
                        y = (y_top + y_bot) / 2,
                        label = sprintf("%.1f%%", as.numeric(pid_val_leg)),
                        pair_key = k,
                        priority = pid_val_leg + min(ifelse(is.finite(n_cod_leg), n_cod_leg, 0), 60) / 10,
                        rib_width = rib_width_leg,
                        stringsAsFactors = FALSE
                    )
                }
            }
        }
        ribbons_ms_legacy <- (as.numeric(proc.time()[["elapsed"]]) - ribbons_t0_legacy) * 1000
        app_perf_mark(aligned_perf, sprintf("aligned_gc_ms=%.1f", legacy_gc_ms), "ORTHO_ALIGNED")
        app_perf_mark(aligned_perf, sprintf("aligned_ribbons_ms=%.1f", ribbons_ms_legacy), "ORTHO_ALIGNED")
	        ribbon_df <- if (length(ribbons) > 0) do.call(rbind,  ribbons) else data.frame()
	        ribbon_label_df <- if (length(ribbon_labels) > 0) do.call(rbind,  ribbon_labels) else data.frame()
	        ribbon_hover_df <- if (length(ribbon_hover_segments) > 0) do.call(rbind,  ribbon_hover_segments) else data.frame()

        build_t0_legacy <- as.numeric(proc.time()[["elapsed"]])
        feature_palette_colors <- get_transcript_feature_palette(
            is_dark_theme = is_dark_theme,
            is_colorblind_mode = isTRUE(input$colorblind_mode),
            custom_overrides = get_custom_color_palette()
        )

        visible_groups <- if (aligned_mode %in% c("protein", "cds")) "cds" else c("utr", "cds", "exon")
        req_df <- combined_df[
            !is.na(combined_df$disp_start) &
            !is.na(combined_df$disp_end) &
            combined_df$plot_group %in% visible_groups,
            , drop = FALSE
        ]
        if (aligned_mode %in% c("protein", "cds")) {
            missing_feature_tracks <- setdiff(
                as.character(valid_idx),
                unique(as.character(suppressWarnings(as.integer(req_df$track_idx))))
            )
            if (length(missing_feature_tracks) > 0L) {
                fallback_exon_df <- combined_df[
                    !is.na(combined_df$disp_start) &
                        !is.na(combined_df$disp_end) &
                        combined_df$plot_group == "exon" &
                        as.character(suppressWarnings(as.integer(combined_df$track_idx))) %in% missing_feature_tracks,
                    , drop = FALSE
                ]
                if (nrow(fallback_exon_df) > 0L) {
                    req_df <- rbind(req_df, fallback_exon_df)
                }
            }
        }
        draw_order <- if (aligned_mode %in% c("protein", "cds")) c("cds") else c("utr", "cds", "exon")
        req_df$draw_rank <- match(req_df$plot_group, draw_order, nomatch = 0)
        req_df <- req_df[order(req_df$draw_rank), , drop = FALSE]
        extent_df <- if (nrow(req_df) > 0L) req_df else combined_df

        track_spans <- vapply(valid_idx, function(idx_i) {
            g <- extent_df[extent_df$track_idx == idx_i, , drop = FALSE]
            if (is.null(g) || nrow(g) == 0L) g <- all_genes[[idx_i]]
            if (is.null(g) || nrow(g) == 0L) return(NA_real_)
            gstart <- suppressWarnings(min(as.numeric(g$disp_start), na.rm = TRUE))
            gend <- suppressWarnings(max(as.numeric(g$disp_end), na.rm = TRUE))
            span <- gend - gstart
            if (!is.finite(span) || span <= 0) NA_real_ else span
        }, numeric(1))
        ref_span <- suppressWarnings(stats::median(track_spans[is.finite(track_spans) & track_spans > 0], na.rm = TRUE))
        if (!is.finite(ref_span) || ref_span <= 0) ref_span <- 1000
        ribbon_label_df <- data.frame()
        side_panel_width <- if (aligned_mode %in% c("protein", "cds")) 0.075 * ref_span else 0.18 * ref_span
        panel_gap <- if (aligned_mode %in% c("protein", "cds")) 0.012 * ref_span else 0.022 * ref_span
        x_min <- min(extent_df$disp_start, na.rm = TRUE) - side_panel_width - panel_gap
        x_max <- max(extent_df$disp_end, na.rm = TRUE) + side_panel_width + panel_gap
        if (!is.finite(x_min) || !is.finite(x_max) || x_max <= x_min) {
            x_min <- 0
            x_max <- 10
        }
        scene_width <- max(x_max - x_min, .Machine$double.eps)
        outer_margin <- if (aligned_mode %in% c("protein", "cds")) 0.008 * scene_width else 0.015 * scene_width
        plot_left <- x_min - outer_margin
        plot_right <- x_max + outer_margin

        p <- ggplot2::ggplot()

        # Track baselines
        track_df <- data.frame(y = valid_idx, yend = valid_idx, x = x_min, xend = x_max)
        p <- p + ggplot2::geom_segment(
            data = track_df,
            ggplot2::aes(x = x, xend = xend, y = y, yend = yend),
            color = aligned_track_color, linewidth = 0.7
        )

        # Curved ribbons (grouped by fill color to avoid scale_fill conflicts)
        if (nrow(ribbon_df) > 0) {
            if (!"ribbon_fill"  %in% names(ribbon_df)) ribbon_df$ribbon_fill  <- "#2F6B9A"
            if (!"ribbon_alpha" %in% names(ribbon_df)) ribbon_df$ribbon_alpha <- 0.18
            if (!"ribbon_linetype" %in% names(ribbon_df)) ribbon_df$ribbon_linetype <- "solid"
            ribbon_df$ribbon_style <- paste(
                ribbon_df$ribbon_fill,
                sprintf("%.3f", ribbon_df$ribbon_alpha),
                ribbon_df$ribbon_outline %||% "#214E70",
                ribbon_df$ribbon_linetype %||% "solid",
                sprintf("%.3f", suppressWarnings(as.numeric(ribbon_df$ribbon_linewidth %||% 0.12))),
                sep = "|"
            )
            for (.rstyle_leg in unique(ribbon_df$ribbon_style)) {
                .rdf_leg    <- ribbon_df[ribbon_df$ribbon_style == .rstyle_leg, , drop = FALSE]
                .rfill_leg  <- as.character(.rdf_leg$ribbon_fill[1] %||% "#2F6B9A")
                .ralpha_leg <- suppressWarnings(as.numeric(.rdf_leg$ribbon_alpha[1] %||% 0.08))
                .rcol_leg   <- as.character(.rdf_leg$ribbon_outline[1] %||% "#214E70")
                .rlty_leg   <- as.character(.rdf_leg$ribbon_linetype[1] %||% "solid")
                .rlwd_leg   <- suppressWarnings(as.numeric(.rdf_leg$ribbon_linewidth[1] %||% 0.12))
                p <- p + ggplot2::geom_polygon(
                    data = .rdf_leg,
                    ggplot2::aes(x = x, y = y, group = poly_id),
                    fill = .rfill_leg, alpha = .ralpha_leg, color = .rcol_leg, linewidth = .rlwd_leg, linetype = .rlty_leg
                )
            }
        }
        if (nrow(ribbon_label_df) > 0) {
            ribbon_label_size <- if (length(valid_idx) >= 5L) 1.95 else 2.15
            p <- p + ggplot2::geom_label(
                data = ribbon_label_df,
                ggplot2::aes(x = x, y = y, label = label),
                inherit.aes = FALSE,
                size = ribbon_label_size,
                label.padding = ggplot2::unit(0.10, "lines"),
                linewidth = 0.12,
                label.r = ggplot2::unit(0.10, "lines"),
                fontface = "bold",
                fill = if (is_dark_theme) "#102438D1" else "#FFFFFFD1",
                color = if (is_dark_theme) "#F4FAFF" else "#22313F"
            )
        }

        feature_hover_df <- data.frame(stringsAsFactors = FALSE)
        if (nrow(req_df) > 0) {
            req_df$hover_y <- (suppressWarnings(as.numeric(req_df$ymin_feat)) + suppressWarnings(as.numeric(req_df$ymax_feat))) / 2
            feature_hover_df <- build_hover_segment_overlay(
                req_df,
                x_col = "disp_start",
                xend_col = "disp_end",
                y_col = "hover_y",
                tooltip_col = "tooltip_html",
                data_id_col = "feature_uid",
                id_suffix = "_aligned",
                min_span = max((plot_right - plot_left) * 0.0005, .Machine$double.eps)
            )
            p <- p + ggplot2::geom_rect(
                data = req_df,
                ggplot2::aes(
                    xmin = disp_start, xmax = disp_end, ymin = ymin_feat, ymax = ymax_feat,
                    fill = plot_group
                ),
                alpha = 0.92, color = aligned_rect_border, linewidth = 0.25
            ) + ggplot2::scale_fill_manual(values = feature_palette_colors)
        }
        if (is.data.frame(feature_hover_df) && nrow(feature_hover_df) > 0L) {
            p <- p + ggiraph::geom_segment_interactive(
                data = feature_hover_df,
                ggplot2::aes(x = x, xend = xend, y = y, yend = yend, tooltip = tooltip, data_id = data_id),
                color = if (is_dark_theme) "#FFFFFF" else "#000000",
                alpha = 0.002,
                linewidth = 8.4,
                lineend = "round"
            )
        }

	        if (is.data.frame(ribbon_hover_df) && nrow(ribbon_hover_df) > 0) {
	            p <- p + ggiraph::geom_segment_interactive(
	                data = ribbon_hover_df,
	                ggplot2::aes(x = x, xend = xend, y = y, yend = yend, tooltip = tooltip, data_id = data_id),
	                color = if (is_dark_theme) "#FFFFFF" else "#000000",
	                alpha = 0.002,
	                linewidth = 6.2,
	                lineend = "round"
	            )
	        }

	        orientation_y <- min(valid_idx, na.rm = TRUE) - 0.52
	        orientation_df <- data.frame(
	            x = c(x_min, x_max),
	            y = c(orientation_y, orientation_y),
	            label = c("5'", "3'"),
	            hjust = c(0, 1),
	            stringsAsFactors = FALSE
	        )
	        p <- p +
	            ggplot2::geom_text(
	                data = orientation_df,
	                ggplot2::aes(x = x, y = y, label = label, hjust = hjust),
	                inherit.aes = FALSE,
	                size = 3.2,
	                fontface = "bold",
	                color = aligned_axis_title_color
	            ) +
	            ggplot2::scale_x_continuous(expand = ggplot2::expansion(mult = 0, add = 0)) +
	            ggplot2::scale_y_reverse(breaks = valid_idx, labels = titles_vec[valid_idx]) +
            ggplot2::coord_cartesian(xlim = c(plot_left, plot_right), clip = "off") +
            ggplot2::theme_minimal() +
            ggplot2::theme(
                legend.position = "none", panel.grid = ggplot2::element_blank(),
                panel.background = ggplot2::element_rect(fill = aligned_bg_color, color = NA),
                plot.background = ggplot2::element_rect(fill = aligned_bg_color, color = NA),
                axis.title.y = ggplot2::element_blank(),
                axis.title.x = ggplot2::element_text(size = 11, face = "bold", color = aligned_axis_title_color),
                axis.text.y = ggplot2::element_text(size = 10, face = "bold.italic", color = aligned_axis_y_color, lineheight = 1.15),
                axis.text.x = ggplot2::element_blank(),
                axis.ticks.x = ggplot2::element_blank(),
                plot.margin = ggplot2::margin(10, 15, 10, 15)
            ) +
	            ggplot2::labs(x = "Aligned transcript space (5' \u2192 3')")

        legacy_feature_hover_n <- if (is.data.frame(feature_hover_df)) as.integer(nrow(feature_hover_df)) else 0L
        legacy_ribbon_hover_n <- if (is.data.frame(ribbon_hover_df)) as.integer(nrow(ribbon_hover_df)) else 0L
        legacy_feature_visual_n <- if (is.data.frame(req_df)) as.integer(nrow(req_df)) else 0L
        legacy_ribbon_visual_n <- if (is.data.frame(ribbon_df)) as.integer(nrow(ribbon_df)) else 0L
        send_girafe_diag_expected(
            "ortho_aligned_plot_out",
            expected = list(
                render_mode = "aligned_legacy",
                cache_hit = FALSE,
                track_rows = as.integer(length(valid_idx)),
                feature_visual = legacy_feature_visual_n,
                ribbon_visual = legacy_ribbon_visual_n,
                feature_hover = legacy_feature_hover_n,
                ribbon_hover = legacy_ribbon_hover_n,
                interactive_total = as.integer(legacy_feature_hover_n + legacy_ribbon_hover_n)
            ),
            meta = list(cache_key = cache_key)
        )
        legacy_plot_obj <- safe_girafe(
            ggobj = p, width_svg = 15,
            height_svg = max(3.5, length(valid_idx) * 1.8 + 0.5),
            transport_label = "ortho_aligned_legacy",
            options = list(
                # Avoid geometry-changing hover in dense tracks (prevents edge flicker).
                ggiraph::opts_hover(css = ""),
                ggiraph::opts_selection(type = "none"),
                ggiraph::opts_tooltip(
                    css = analytics_tooltip_css,
                    use_fill = FALSE,
                    placement = "auto",
                    zindex = 999999,
                    delay_mouseover = 50,
                    delay_mouseout = 500
                ),
                ggiraph::opts_toolbar(
                    position = "topright",
                    hidden = c("selection", "zoom", "misc")
                ),
                ggiraph::opts_sizing(rescale = TRUE)
            )
        )
        build_ms_legacy <- (as.numeric(proc.time()[["elapsed"]]) - build_t0_legacy) * 1000
        total_ms_legacy <- (as.numeric(proc.time()[["elapsed"]]) - legacy_total_t0) * 1000
        app_perf_mark(aligned_perf, sprintf("aligned_plot_build_ms=%.1f", build_ms_legacy), "ORTHO_ALIGNED")
        app_perf_mark(aligned_perf, sprintf("aligned_total_ms=%.1f", total_ms_legacy), "ORTHO_ALIGNED")
        legacy_plot_obj
    }), list(
        input$ortho_visual_mode,
        input$app_theme,
        input$ortho_aligned_mode,
        input$ortho_aligned_representative,
        input$ortho_aligned_track_order,
        input$ortho_aligned_anchor_track,
        input$ortho_aligned_min_identity,
        alignedOrderedPlotIdsOrthologous(),
        sortedPlotIdsOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_aligned_plot_out", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

    # Footer with summary statistics for aligned view
    output$ortho_aligned_footer <- bindEvent(renderUI({
        mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (!identical(mode, "aligned")) {
            return(NULL)
        }
        ids_all <- as.character(sortedPlotIdsOrthologous() %||% integer(0))
        ids <- as.character(alignedOrderedPlotIdsOrthologous() %||% character(0))
        if (length(ids) == 0) {
            return(NULL)
        }
	        rep_strategy <- tolower(trimws(as.character(input$ortho_aligned_representative %||% "longest_cds")))
	        if (!rep_strategy %in% c("longest_cds", "longest_transcript", "most_exons", "all")) rep_strategy <- "longest_cds"
	        track_order_mode <- tolower(trimws(as.character(input$ortho_aligned_track_order %||% "similarity_chain")))
	        if (!track_order_mode %in% c("similarity_chain", "load", "organism", "reverse", "manual")) track_order_mode <- "similarity_chain"
	        anchor_id <- trimws(as.character(input$ortho_aligned_anchor_track %||% ""))
	        if (!nzchar(anchor_id) || identical(anchor_id, "__auto__") || !anchor_id %in% ids) anchor_id <- ""
	        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark_theme <- identical(theme_mode, "dark")
        summary_card_style <- if (is_dark_theme) {
            "display:inline-flex; align-items:center; gap:6px; background:#10263B; border:1px solid #2E4A63; border-radius:6px; padding:4px 8px; font-size:12px; color:#D8E5F3;"
        } else {
            "display:inline-flex; align-items:center; gap:6px; background:#FFFFFF; border:1px solid #DFE6ED; border-radius:6px; padding:4px 8px; font-size:12px;"
        }
        summary_title_color <- if (is_dark_theme) "#E7F1FB" else "#2C3E50"
        summary_separator_color <- if (is_dark_theme) "#98AFC3" else "#9BA6B0"

        esc <- function(x) {
            x <- as.character(x %||% "")
            x <- gsub("&", "&amp;", x, fixed = TRUE)
            x <- gsub("<", "&lt;", x, fixed = TRUE)
            x <- gsub(">", "&gt;", x, fixed = TRUE)
            x
        }
	        rep_label <- switch(rep_strategy,
	            "longest_transcript" = "Representative: Longest transcript",
	            "most_exons" = "Representative: Most exons",
	            "all" = "Representative: All transcripts",
	            "Representative: Canonical transcript"
	        )
	        order_label <- switch(track_order_mode,
	            "manual" = "Order: Manual",
	            "load" = "Order: Loaded order",
	            "organism" = "Order: Organism A-Z",
	            "reverse" = "Order: Reverse current",
	            "Order: Biological chain"
	        )
	        anchor_label <- "Anchor: Auto"
	        if (nzchar(anchor_id)) {
	            org_info_anchor <- tryCatch(organismInfoOrthologous()[[anchor_id]], error = function(e) NULL)
	            org_name_anchor <- trimws(as.character(org_info_anchor$name %||% ""))
	            ttl_anchor <- trimws(as.character(tryCatch(titlesOrthologous()[[anchor_id]], error = function(e) "") %||% ""))
	            anchor_parts <- c()
	            if (nzchar(org_name_anchor)) anchor_parts <- c(anchor_parts, org_name_anchor)
	            if (nzchar(ttl_anchor)) anchor_parts <- c(anchor_parts, ttl_anchor)
	            anchor_label <- if (length(anchor_parts) > 0L) {
	                paste0("Anchor: ", paste(anchor_parts, collapse = " | "))
	            } else {
	                paste0("Anchor: ", anchor_id)
	            }
	        }
	        hidden_n <- max(0L, length(ids_all) - length(ids))

	        summary_items <- lapply(seq_along(ids), function(i) {
	            id_chr <- as.character(ids[i])
	            payload <- tryCatch(get_cached_aligned_track_payload(id_chr), error = function(e) NULL)
	            summary <- payload$summary %||% NULL
	            if (is.null(summary)) {
	                return(NULL)
	            }
	            org_name <- as.character(summary$org_name %||% paste("Org", i))
	            gene_name <- as.character(summary$gene_name %||% "Gene")
	            strand_val <- as.character(summary$strand_val %||% "+")
	            n_exons <- suppressWarnings(as.integer(summary$n_exons %||% 0L))
	            n_cds <- suppressWarnings(as.integer(summary$n_cds %||% 0L))
	            n_utr <- suppressWarnings(as.integer(summary$n_utr %||% 0L))
	            gene_len <- suppressWarnings(as.numeric(summary$gene_len %||% NA_real_))
	            chr_val_short <- as.character(summary$chr_val_short %||% "")

	            div(
	                style = summary_card_style,
	                span(tags$strong(style = sprintf("color:%s;", summary_title_color), esc(org_name))),
	                span(style = sprintf("color:%s;", summary_separator_color), "|"),
	                span(paste0(gene_name, " (", strand_val, ")")),
	                span(style = sprintf("color:%s;", summary_separator_color), "|"),
	                span(paste0("Chr: ", chr_val_short)),
                span(style = sprintf("color:%s;", summary_separator_color), "|"),
                span(paste0(n_exons, " exons")),
                if (n_cds > 0) span(paste0(", ", n_cds, " CDS")) else NULL,
	                if (n_utr > 0) span(paste0(", ", n_utr, " UTRs")) else NULL,
	                span(style = sprintf("color:%s;", summary_separator_color), "|"),
	                span(paste0(format(round(gene_len), big.mark = ","), " bp"))
	        )
	    })

	        tagList(
	            div(
	                style = "display:flex; align-items:center; gap:8px; margin-bottom:6px;",
	                tags$i(class = "fa fa-chart-bar", style = "color:#18BC9C;"),
	                tags$strong(style = sprintf("color:%s; font-size:13px;", summary_title_color), "Summary")
	            ),
	            div(
	                style = sprintf("margin-bottom:8px; font-size:12px; color:%s;", if (is_dark_theme) "#C7D9EA" else "#4B6072"),
	                span(esc(rep_label)),
	                span(" | "),
	                span(esc(order_label)),
	                if (track_order_mode %in% c("similarity_chain", "manual")) {
	                    tagList(
	                        span(" | "),
	                        span(esc(anchor_label))
	                    )
	                } else {
	                    NULL
	                },
	                if (hidden_n > 0L) {
	                    span(paste0(" | Hidden isoforms: ", hidden_n))
	                } else {
	                    NULL
	                }
	            ),
	            div(style = "display:flex; flex-wrap:wrap; gap:4px;", summary_items)
	        )
	    })
    , list(
        input$ortho_visual_mode,
        input$ortho_aligned_representative,
        input$ortho_aligned_track_order,
        input$ortho_aligned_anchor_track,
        alignedOrderedPlotIdsOrthologous(),
        sortedPlotIdsOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_aligned_footer", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

	    output$ortho_pip_reference_ui <- renderUI({
	        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
	        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
	        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
            assess <- pipReferenceAssessmentOrthologous() %||% list()
        strip_tx <- function(s) trimws(gsub("\\s*\\|\\s*Transcript:[^|]*", "", s))
        label_for_id <- function(pid) {
            org_txt <- trimws(as.character(((org_map[[pid]] %||% list())$name %||% "")[1] %||% ""))
            ttl_txt <- strip_tx(trimws(as.character((titles_map[[pid]] %||% "")[1] %||% "")))
            if (nchar(ttl_txt, type = "width") > 55L) {
                ttl_txt <- paste0(substr(ttl_txt, 1L, 52L), "...")
            }
            if (nzchar(org_txt) && nzchar(ttl_txt)) {
                paste0(org_txt, " | ", ttl_txt)
            } else if (nzchar(org_txt)) {
                org_txt
            } else if (nzchar(ttl_txt)) {
                ttl_txt
            } else {
                pid
            }
        }
	        selected_id <- trimws(as.character(pipReferencePlotIdOrthologous() %||% ""))
	        if (length(ids) > 0L && (!nzchar(selected_id) || !selected_id %in% ids)) {
	            selected_id <- ids[[1]]
	        }
        pip_ref_theme <- tolower(as.character(input$app_theme %||% "light"))
        if (!pip_ref_theme %in% c("light", "dark")) pip_ref_theme <- "light"
        is_dark_pip_ref <- identical(pip_ref_theme, "dark")
        status_txt <- trimws(as.character(assess$status %||% "pending"))
        is_evaluated <- identical(status_txt, "evaluated") && identical(trimws(as.character(assess$reference_id %||% "")), selected_id)
        is_unavailable <- identical(status_txt, "unavailable") && identical(trimws(as.character(assess$reference_id %||% "")), selected_id)
        chip_bg <- if (is_evaluated) "rgba(75, 160, 115, 0.10)" else if (is_unavailable) "rgba(196, 84, 80, 0.10)" else "rgba(224, 123, 57, 0.10)"
        chip_border <- if (is_evaluated) "#75B990" else if (is_unavailable) "#D29792" else "#D49B72"
        chip_txt <- if (is_evaluated) "#2F6F4C" else if (is_unavailable) "#8D3E3A" else "#8C4D1E"
        chip_label <- if (is_evaluated) "Evaluated" else if (is_unavailable) "Unavailable" else "Pending run"
        detail_txt <- trimws(as.character(
            if (is_evaluated || is_unavailable) {
                assess$detail %||% assess$summary %||% ""
            } else {
                if (length(ids) > 0L) {
                    "Reference-centered view: run the selected reference once to measure support across the visible organisms."
                } else {
                    "Load cross-species comparison tracks first, then choose a reference and run local alignments."
                }
            }
        ))
        div(
            class = "ortho-aligned-control ortho-aligned-control--select",
            div(
                class = "ortho-pip-reference-label",
                tags$span("Reference track:", class = "ortho-aligned-control-label"),
                tags$span(
                    class = "ortho-pip-reference-chip",
                    style = paste0(
                        "display:inline-flex; align-items:center; padding:3px 9px; border-radius:999px; font-size:11px; font-weight:700; ",
                        "background:", chip_bg, "; border:1px solid ", chip_border, "; color:", chip_txt, ";"
                    ),
                    chip_label
                )
            ),
            if (length(ids) > 0L) {
                shiny::selectInput(
                    inputId = "ortho_pip_reference_track",
                    label = NULL,
                    choices = stats::setNames(ids, vapply(ids, label_for_id, character(1))),
                    selected = selected_id,
                    width = "100%"
                )
            } else {
                div(
                    class = "ortho-pip-no-ref-placeholder",
                    style = if (is_dark_pip_ref) {
                        "height:38px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid #284562; background:linear-gradient(180deg,#10263b 0%,#0d2033 100%); color:#5d7e96; font-size:0.94rem;"
                    } else {
                        "height:38px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid rgba(189,201,210,0.95); background:rgba(248,250,252,0.96); color:#8394A2; font-size:0.94rem;"
                    },
                    "No reference available yet"
                )
            }
	        )
	    })
    outputOptions(output, "ortho_pip_reference_ui", suspendWhenHidden = FALSE)

    output$ortho_pip_reference_note_ui <- renderUI({
        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
        assess <- pipReferenceAssessmentOrthologous() %||% list()
        status_txt <- trimws(as.character(assess$status %||% "pending"))
        is_evaluated <- identical(status_txt, "evaluated")
        is_unavailable <- identical(status_txt, "unavailable")
        title_txt <- if (is_evaluated || is_unavailable) "Reference evaluation" else "Reference status"
        detail_txt <- trimws(as.character(
            if (is_evaluated || is_unavailable) {
                assess$summary %||% assess$detail %||% ""
            } else {
                if (length(ids) > 0L) {
                    "Run local alignments to evaluate the selected reference against the visible organisms."
                } else {
                    "Load cross-species comparison tracks first, then choose a reference and run local alignments."
                }
            }
        ))
        if (!nzchar(detail_txt)) {
            return(NULL)
        }
        div(
            class = "ortho-pip-reference-note-card",
            tags$small(
                class = "ortho-pip-reference-note-copy",
                style = "display: block;",
                tags$b(title_txt),
                tags$span(
                    paste0(" — ", detail_txt),
                    style = "color: var(--bs-secondary-color, #6c757d);"
                )
            )
        )
    })

    output$ortho_pip_help <- renderUI({
        ref_ctx <- pipReferenceWindowOrthologous()
        run_map <- pipLocalAlignmentRunsOrthologous() %||% list()
        local_engine_msg <- ""
        if (length(run_map) > 0L) {
            first_run <- run_map[[1]] %||% list()
            run_status <- trimws(as.character(first_run$status %||% ""))
            if (identical(run_status, "engine_unavailable")) {
                local_engine_msg <- paste0(
                    " LASTZ is not available on this machine yet. ",
                    as.character(first_run$setup_hint %||% "Install LASTZ locally or set APP_LASTZ_BIN to the binary path.")
                )
            } else if (nzchar(trimws(as.character(first_run$binary_path %||% "")))) {
                local_engine_msg <- paste0(
                    " LASTZ local backend: ",
                    as.character(first_run$binary_path %||% "")
                )
            }
        }
        ref_note <- if (!is.null(ref_ctx)) {
            sprintf(
                " Current reference window: %s:%s-%s.",
                as.character(ref_ctx$seqid %||% ""),
                format(as.integer(ref_ctx$window_start %||% NA_integer_), big.mark = ","),
                format(as.integer(ref_ctx$window_end %||% NA_integer_), big.mark = ",")
            )
        } else {
            ""
        }
        span_mode <- trimws(as.character(input$ortho_pip_span %||% "gene"))
        flank_bp <- parse_locus_window_flank_bp(span_mode, default_bp = 0L)
        ref_bp <- if (!is.null(ref_ctx)) {
            start_i <- suppressWarnings(as.integer(ref_ctx$window_start %||% NA_integer_))
            end_i <- suppressWarnings(as.integer(ref_ctx$window_end %||% NA_integer_))
            if (is.finite(start_i) && is.finite(end_i) && end_i >= start_i) end_i - start_i + 1L else NA_integer_
        } else {
            NA_integer_
        }
        window_scope_msg <- if (is.finite(ref_bp)) {
            if (flank_bp <= 0L) {
                sprintf(" Gene body only aligns the exact gene window with 0 bp flanks (%s bp on the reference).", format(as.integer(ref_bp), big.mark = ","))
            } else {
                sprintf(" This setting aligns the gene plus %s bp on each side (%s bp on the reference), so it can take longer as the window grows.", format(as.integer(flank_bp), big.mark = ","), format(as.integer(ref_bp), big.mark = ","))
            }
        } else if (flank_bp <= 0L) {
            " Gene body only uses 0 bp flanks."
        } else {
            sprintf(" This setting adds %s bp on each side; longer windows can take longer to align.", format(as.integer(flank_bp), big.mark = ","))
        }
	        tags$small(
	            style = "line-height: 1.35; display: block;",
	            tags$b("Reference-centered local conservation"),
	            tags$span(
	                paste0(" — LASTZ projects each loaded organism against the current reference locus window, using the canonical transcript representative when available.", ref_note, window_scope_msg, local_engine_msg),
	                style = "color: var(--bs-secondary-color, #6c757d);"
	            )
	        )
    })

    output$ortho_pip_legend <- renderUI({
        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark_theme <- identical(theme_mode, "dark")
        chip_style <- function(bg, border, txt = if (is_dark_theme) "#C8DDF0" else "#324B5F") {
            paste0(
                "display:inline-flex; align-items:center; gap:5px; padding:3px 8px; border-radius:999px; font-size:11px; ",
                "background:", bg, "; border:1px solid ", border, "; color:", txt, "; font-weight:600;"
            )
        }
        dot_style <- function(fill, border = fill) {
            paste0("display:inline-block; width:10px; height:10px; border-radius:999px; background:", fill, "; border:1px solid ", border, "; flex-shrink:0;")
        }
        div(
            style = "display:flex; flex-wrap:wrap; gap:5px 8px; align-items:center; margin-bottom:5px;",
            tags$span(style = "font-size:11px; font-weight:700; color:inherit;", "Visual encoding:"),
            tags$span(
                style = chip_style("rgba(204,41,41,0.12)", if (is_dark_theme) "#E85555" else "#CC2929"),
                tags$span(style = dot_style(if (is_dark_theme) "#E85555" else "#CC2929"), NULL),
                "\u226595% \u2014 nearly identical"
            ),
            tags$span(
                style = chip_style("rgba(224,120,88,0.12)", if (is_dark_theme) "#F0A070" else "#E07858"),
                tags$span(style = dot_style(if (is_dark_theme) "#F0A070" else "#E07858"), NULL),
                "80\u201394% \u2014 similar"
            ),
            tags$span(
                style = chip_style("rgba(92,184,92,0.12)", if (is_dark_theme) "#7ED07E" else "#5CB85C"),
                tags$span(style = dot_style(if (is_dark_theme) "#7ED07E" else "#5CB85C"), NULL),
                "60\u201379% \u2014 moderately similar"
            ),
            tags$span(
                style = chip_style("rgba(224,123,57,0.10)", "#D49B72"),
                tags$span(style = "display:inline-block; width:14px; height:0; border-top:2px dashed #C0622A; flex-shrink:0;", NULL),
                "reverse-strand / inversion candidate"
            ),
            tags$span(
                style = chip_style("rgba(125,174,204,0.10)", "#B5C5CF"),
                tags$span(style = dot_style(if (is_dark_theme) "#D8EDF8" else "#A9C7D8", if (is_dark_theme) "#7893A8" else "#B5C5CF"), NULL),
                "reference gene body window"
            )
        )
    })

    output$ortho_pip_status_ui <- renderUI({
        scene <- pipProcessedSceneOrthologous()
        ids <- as.character(scene$ids %||% character(0))
        if (length(ids) == 0L) {
            return(
                tags$small(
                    style = "display:block; color: var(--bs-secondary-color, #6c757d);",
                    "No cross-species comparison tracks are loaded yet for LASTZ Block View."
                )
            )
        }
	        ref_id <- trimws(as.character(scene$ref_id %||% ""))
        ctx_map <- scene$ctx_map %||% list()
	        ref_label <- if (nzchar(ref_id)) {
	            ctx <- (ctx_map[[ref_id]] %||% list())
	            org_txt <- trimws(as.character(ctx$organism_name %||% ""))
	            ttl_txt <- trimws(as.character(ctx$title %||% ""))
	            if (nzchar(org_txt) && nzchar(ttl_txt)) paste0(org_txt, " | ", ttl_txt) else if (nzchar(org_txt)) org_txt else if (nzchar(ttl_txt)) ttl_txt else ref_id
	        } else {
	            "Auto"
	        }
        min_identity <- scene$min_identity %||% 70
        min_length <- scene$min_block_length %||% 100L
        assess <- pipReferenceAssessmentOrthologous() %||% list()
        chip_style <- function(bg, border, txt = "inherit") {
            paste0(
                "display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:999px; ",
                "background:", bg, "; border:1px solid ", border, "; color:", txt, "; font-size:12px; font-weight:600;"
            )
        }
        run_stats <- scene$run_stats %||% list()
        run_rows <- lapply(ids[ids != ref_id], function(pid) {
            st <- run_stats[[pid]] %||% list()
            status_txt <- trimws(as.character(st$status %||% "not-run"))
            total_blocks <- as.integer(st$total_blocks %||% 0L)
            filtered_blocks <- if (isTRUE(scene$guardrail_triggered)) {
                paste0(as.integer(st$visible_blocks %||% 0L), " shown from ", as.integer(st$sampled_blocks %||% 0L), " sampled")
            } else {
                as.character(as.integer(st$visible_blocks %||% 0L))
            }
            chain_blocks <- if (isTRUE(scene$guardrail_triggered)) {
                paste0(as.integer(st$chain_blocks %||% 0L), " summary chains")
            } else {
                as.character(as.integer(st$chain_blocks %||% 0L))
            }
            stderr_txt <- trimws(as.character(st$stderr_txt %||% ""))
            seqid_txt <- trimws(as.character(st$seqid_txt %||% ""))
            org_txt <- trimws(as.character(st$org_txt %||% pid))
            status_colors <- switch(
                status_txt,
                "ok" = c(bg = "rgba(75, 160, 115, 0.10)", border = "#75B990", txt = "#2F6F4C"),
                "missing_sequence" = c(bg = "rgba(224, 123, 57, 0.10)", border = "#D49B72", txt = "#8C4D1E"),
                "window_too_large" = c(bg = "rgba(224, 123, 57, 0.10)", border = "#D49B72", txt = "#8C4D1E"),
                "engine_timeout" = c(bg = "rgba(196, 84, 80, 0.10)", border = "#D29792", txt = "#8D3E3A"),
                "engine_error" = c(bg = "rgba(196, 84, 80, 0.10)", border = "#D29792", txt = "#8D3E3A"),
                "engine_unavailable" = c(bg = "rgba(196, 84, 80, 0.10)", border = "#D29792", txt = "#8D3E3A"),
                c(bg = "rgba(91, 143, 184, 0.10)", border = "#8AAFD0", txt = "#385C77")
            )
            tags$div(
                style = "display:flex; flex-wrap:wrap; gap:8px 10px; align-items:center;",
                tags$span(style = "font-weight:700;", org_txt),
                tags$span(style = chip_style(status_colors[["bg"]], status_colors[["border"]], status_colors[["txt"]]), paste0("status: ", status_txt)),
                if (nzchar(seqid_txt)) tags$span(style = "opacity:0.82;", paste0("locus: ", seqid_txt)) else NULL,
                tags$span(style = "opacity:0.82;", paste0("blocks parsed: ", total_blocks)),
                tags$span(style = "opacity:0.82;", paste0("visible LASTZ blocks: ", filtered_blocks)),
                tags$span(style = "opacity:0.82;", paste0("chains: ", chain_blocks)),
                if (nzchar(stderr_txt)) tags$span(style = "opacity:0.82; color:#C0622A;", paste0("stderr: ", stderr_txt)) else NULL
            )
        })
        tags$div(
            style = "display:flex; flex-direction:column; gap:8px;",
            tags$div(
                style = "display:flex; flex-wrap:wrap; gap:8px 12px; align-items:center;",
                tags$strong("Backend status"),
	                tags$span(style = "opacity:0.82;", paste0("Reference track: ", ref_label)),
                tags$span(style = "opacity:0.82;", paste0("Reference state: ", if (identical(trimws(as.character(assess$status %||% "")), "evaluated")) "Evaluated from current run" else if (identical(trimws(as.character(assess$status %||% "")), "unavailable")) "Evaluation unavailable" else "Pending run")),
                tags$span(style = "opacity:0.82;", paste0("Organisms shown: ", max(length(ids) - 1L, 0L), " query + 1 reference")),
                tags$span(style = "opacity:0.82;", paste0("Identity filter: ", as.integer(round(min_identity)), "%")),
                tags$span(style = "opacity:0.82;", paste0("Length filter: ", min_length, " bp")),
                if (isTRUE(scene$guardrail_triggered)) tags$span(style = "opacity:0.82; color:#C0622A;", scene$guardrail_message) else NULL
            ),
            if ((scene$raw_block_total %||% 0L) == 0L) {
                tags$small(
                    style = "display:block; color: var(--bs-secondary-color, #6c757d);",
                    "Local runs have not started yet. Click 'Run local alignments' to execute LASTZ for all loaded organism representatives."
                )
            } else {
                NULL
            },
            if (length(run_rows) > 0L) run_rows else list(
                tags$small(style = "display:block; color: var(--bs-secondary-color, #6c757d);", "Load at least one non-reference cross-species comparison track to run local comparisons.")
            )
        )
    })

    output$ortho_pip_plot_out <- bindEvent(renderGirafe({
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        req(identical(current_mode, "pip_blocks"), cancelOutput = TRUE)
        scene <- pipProcessedSceneOrthologous()
        ids_all <- as.character(scene$ids_all %||% character(0))
        ids <- as.character(scene$ids %||% character(0))
        ctx_map <- scene$ctx_map %||% list()
        ref_ctx <- scene$ref_ctx %||% NULL
        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark_theme <- identical(theme_mode, "dark")
        is_colorblind_mode <- isTRUE(input$colorblind_mode)
        bg_color <- if (is_dark_theme) "#102438" else "#FAFBFC"
        axis_color <- if (is_dark_theme) "#D9E6F3" else "#42586B"
        line_color <- if (is_dark_theme) "#5F7790" else "#C8D4DC"
        ref_color <- if (is_dark_theme) "#7FD0B2" else "#3EA77B"
        reverse_color <- if (is_dark_theme) "#F0A36C" else "#C0622A"
        # Nucleotide-view identity-category colours (MultiPipMaker style)
        custom_overrides <- get_custom_color_palette()
        nv_identical_color <- if (is_dark_theme) adjust_color_dark(custom_overrides$identity_high) else custom_overrides$identity_high  # >=95 %
        nv_similar_color   <- if (is_dark_theme) adjust_color_dark(custom_overrides$identity_mid) else custom_overrides$identity_mid  # 80-94 %
        nv_moderate_color  <- if (is_dark_theme) adjust_color_dark(custom_overrides$identity_low) else custom_overrides$identity_low  # 60-79 %
        feature_palette <- get_transcript_feature_palette(
            is_dark_theme = is_dark_theme,
            is_colorblind_mode = is_colorblind_mode,
            custom_overrides = custom_overrides
        )
        exon_fill <- unname(feature_palette[["exon"]] %||% if (is_dark_theme) "#FF6881" else "#F45D75")
        cds_fill <- unname(feature_palette[["cds"]] %||% if (is_dark_theme) "#F4B36A" else "#E8A44F")
        utr_fill <- unname(feature_palette[["utr"]] %||% if (is_dark_theme) "#55C7E8" else "#5BC0EB")
        feature_border <- if (is_dark_theme) "#8FA8BC" else "#4E6476"
        pip_placeholder_plot <- function(title_txt, subtitle_txt = "") {
            p0 <- ggplot2::ggplot() +
                ggplot2::annotate("text", x = 0, y = 0.18, label = title_txt, size = 4.4, color = axis_color, fontface = "bold") +
                {
                    if (nzchar(trimws(as.character(subtitle_txt %||% "")))) {
                        ggplot2::annotate("text", x = 0, y = -0.12, label = subtitle_txt, size = 3.3, color = axis_color)
                    }
                } +
                ggplot2::xlim(-1, 1) + ggplot2::ylim(-1, 1) +
                ggplot2::theme_void() +
                ggplot2::theme(
                    panel.background = ggplot2::element_rect(fill = bg_color, color = NA),
                    plot.background = ggplot2::element_rect(fill = bg_color, color = NA)
                )
            safe_girafe(
                ggobj = p0,
                width_svg = 12,
                height_svg = 2.8,
                transport_label = "ortho_pip_placeholder",
                options = list(
                    ggiraph::opts_hover(css = ""),
                    ggiraph::opts_selection(type = "none"),
                    ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
                    ggiraph::opts_sizing(rescale = TRUE)
	                )
	            )
	        }
	        tryCatch({
        if (length(ids) == 0L) {
            req(FALSE, cancelOutput = TRUE)
        }
        if (is.null(ref_ctx)) {
            req(FALSE, cancelOutput = TRUE)
        }
        ref_id <- trimws(as.character(scene$ref_id %||% ""))
        span_label <- switch(trimws(as.character(input$ortho_pip_span %||% "gene")),
            "gene" = "Gene body only",
            "5kb"  = "Gene \u00b1 5 kb",
            "10kb" = "Gene \u00b1 10 kb",
            "25kb" = "Gene \u00b1 25 kb",
            "50kb" = "Gene \u00b1 50 kb",
            as.character(scene$span_label %||% "Gene body only")
        )
        min_identity <- as.numeric(scene$min_identity %||% 70)
        min_block_length <- as.integer(scene$min_block_length %||% 100L)
        display_rows <- scene$display_rows %||% data.frame(stringsAsFactors = FALSE)
        # Display the representative transcript body itself in the available
        # width. When a gene row spans beyond the selected transcript (for
        # example because the annotation keeps a full gene feature), we still
        # anchor the visual scale to tx_start/tx_end so exon / intron spacing
        # reflects the actual representative transcript being shown.
        pip_window_spec <- resolve_reference_display_window(
            ref_ctx = ref_ctx,
            span_mode = input$ortho_pip_span %||% "gene",
            default_start = scene$ref_window_start %||% 1,
            default_end = scene$ref_window_end %||% 100,
            pad_fraction = 0.03,
            min_pad_bp = 1L,
            prefer_transcript = TRUE
        )
        ref_window_start <- as.numeric(pip_window_spec$display_start %||% scene$ref_window_start %||% 1)
        ref_window_end   <- as.numeric(pip_window_spec$display_end %||% scene$ref_window_end %||% 100)
        ref_row_y <- as.numeric(scene$ref_row_y %||% NA_real_)
        ref_gene_start_clip <- if (is.finite(as.numeric(pip_window_spec$body_start %||% NA_real_))) {
            max(ref_window_start, as.numeric(pip_window_spec$body_start))
        } else {
            as.numeric(scene$ref_gene_start_clip %||% NA_real_)
        }
        ref_gene_end_clip <- if (is.finite(as.numeric(pip_window_spec$body_end %||% NA_real_))) {
            min(ref_window_end, as.numeric(pip_window_spec$body_end))
        } else {
            as.numeric(scene$ref_gene_end_clip %||% NA_real_)
        }
        ref_window_span <- max(ref_window_end - ref_window_start, .Machine$double.eps)
        ref_gene_center <- if (is.finite(ref_gene_start_clip) && is.finite(ref_gene_end_clip)) {
            mean(c(ref_gene_start_clip, ref_gene_end_clip))
        } else {
            as.numeric(scene$ref_gene_center %||% mean(c(ref_window_start, ref_window_end)))
        }
        ref_label_main <- as.character(scene$ref_label_main %||% "Reference")
        ref_label_sub <- as.character(scene$ref_label_sub %||% "")
        ref_gene_dir_left <- as.character(scene$ref_gene_dir_left %||% "5'")
        ref_gene_dir_right <- as.character(scene$ref_gene_dir_right %||% "3'")
        ref_strand_display <- trimws(as.character(ref_ctx$strand %||% "+"))
        x_display_lastz <- function(x) orient_reference_coord(x, ref_window_start, ref_window_end, strand = ref_strand_display)
        display_breaks_df <- data.frame(
            raw = c(ref_window_start, mean(c(ref_window_start, ref_window_end)), ref_window_end),
            stringsAsFactors = FALSE
        )
        display_breaks_df$disp <- x_display_lastz(display_breaks_df$raw)
        display_breaks_df$label <- format(as.integer(round(display_breaks_df$raw)), big.mark = ",")
        display_breaks_df <- display_breaks_df[order(display_breaks_df$disp), , drop = FALSE]
        ref_gene_start_disp <- if (is.finite(ref_gene_start_clip)) x_display_lastz(ref_gene_start_clip) else NA_real_
        ref_gene_end_disp <- if (is.finite(ref_gene_end_clip)) x_display_lastz(ref_gene_end_clip) else NA_real_
        ref_gene_center_disp <- if (is.finite(ref_gene_center)) x_display_lastz(ref_gene_center) else mean(c(ref_window_start, ref_window_end))
        ref_gene_dir_left <- "5'"
        ref_gene_dir_right <- "3'"
        row_band_df <- scene$row_band_df %||% data.frame(stringsAsFactors = FALSE)
        track_label_df <- scene$track_label_df %||% data.frame(stringsAsFactors = FALSE)
        ref_feature_df <- scene$ref_feature_df %||% data.frame(stringsAsFactors = FALSE)
        blocks_df <- scene$blocks_df %||% data.frame(stringsAsFactors = FALSE)
        status_label <- as.character(scene$status_label %||% "No local alignment runs yet")
        run_map <- pipLocalAlignmentRunsOrthologous() %||% list()
        if (is.data.frame(ref_feature_df) && nrow(ref_feature_df) > 0L) {
            ref_feature_df <- add_reference_display_range(
                ref_feature_df,
                window_start = ref_window_start,
                window_end = ref_window_end,
                strand = ref_strand_display
            )
        }

        exon_df <- if (is.data.frame(ref_feature_df) && nrow(ref_feature_df) > 0L) {
            ref_feature_df[ref_feature_df$feature_group == "exon", , drop = FALSE]
        } else {
            NULL
        }
        utr_df <- if (is.data.frame(ref_feature_df) && nrow(ref_feature_df) > 0L) {
            ref_feature_df[ref_feature_df$feature_group == "utr", , drop = FALSE]
        } else {
            NULL
        }
        cds_df <- if (is.data.frame(ref_feature_df) && nrow(ref_feature_df) > 0L) {
            ref_feature_df[ref_feature_df$feature_group == "cds", , drop = FALSE]
        } else {
            NULL
        }
        if (is.data.frame(exon_df) && nrow(exon_df) > 0L && is.data.frame(cds_df) && nrow(cds_df) > 0L) {
            exon_keys <- paste(round(exon_df$xstart_clip), round(exon_df$xend_clip), sep = ":")
            cds_keys <- unique(paste(round(cds_df$xstart_clip), round(cds_df$xend_clip), sep = ":"))
            exon_df <- exon_df[!exon_keys %in% cds_keys, , drop = FALSE]
        }
        hover_min_span <- max(ref_window_span * 0.0005, .Machine$double.eps)
        feature_hover_color <- if (is_dark_theme) "#FFFFFF" else "#000000"
        pip_block_half <- 0.18
        if (is.data.frame(exon_df) && nrow(exon_df) > 0L) {
            exon_df$hover_ymin <- ref_row_y - 0.15
            exon_df$hover_ymax <- ref_row_y + 0.15
        }
        if (is.data.frame(utr_df) && nrow(utr_df) > 0L) {
            utr_df$hover_ymin <- ref_row_y - 0.115
            utr_df$hover_ymax <- ref_row_y + 0.115
        }
        if (is.data.frame(cds_df) && nrow(cds_df) > 0L) {
            cds_df$hover_ymin <- ref_row_y - 0.15
            cds_df$hover_ymax <- ref_row_y + 0.15
        }
        exon_hover_df <- build_hover_rect_overlay(
            exon_df,
            xmin_col = "xstart_disp",
            xmax_col = "xend_disp",
            ymin_col = "hover_ymin",
            ymax_col = "hover_ymax",
            tooltip_col = "tooltip",
            data_id_col = "data_id",
            id_suffix = "_pip_ref",
            min_width = hover_min_span,
            min_height = 0.30
        )
        utr_hover_df <- build_hover_rect_overlay(
            utr_df,
            xmin_col = "xstart_disp",
            xmax_col = "xend_disp",
            ymin_col = "hover_ymin",
            ymax_col = "hover_ymax",
            tooltip_col = "tooltip",
            data_id_col = "data_id",
            id_suffix = "_pip_ref",
            min_width = hover_min_span,
            min_height = 0.23
        )
        cds_hover_df <- build_hover_rect_overlay(
            cds_df,
            xmin_col = "xstart_disp",
            xmax_col = "xend_disp",
            ymin_col = "hover_ymin",
            ymax_col = "hover_ymax",
            tooltip_col = "tooltip",
            data_id_col = "data_id",
            id_suffix = "_pip_ref",
            min_width = hover_min_span,
            min_height = 0.30
        )
        if (is.data.frame(blocks_df) && nrow(blocks_df) > 0L) {
            id_pct_num <- suppressWarnings(as.numeric(blocks_df$identity_pct))
            blocks_df$id_cat <- ifelse(
                !is.finite(id_pct_num), "moderate",
                ifelse(id_pct_num >= 95, "identical",
                ifelse(id_pct_num >= 80, "similar", "moderate"))
            )
            blocks_df$rect_xmin <- pmax(blocks_df$ref_genomic_start, ref_window_start)
            blocks_df$rect_xmax <- pmin(blocks_df$ref_genomic_end,   ref_window_end)
            blocks_df <- blocks_df[
                is.finite(blocks_df$rect_xmin) &
                is.finite(blocks_df$rect_xmax) &
                blocks_df$rect_xmax > blocks_df$rect_xmin,
            , drop = FALSE]
            if (nrow(blocks_df) > 0L) {
                disp_bounds <- t(vapply(seq_len(nrow(blocks_df)), function(i) {
                    vals <- x_display_lastz(c(blocks_df$rect_xmin[[i]], blocks_df$rect_xmax[[i]]))
                    c(min(vals, na.rm = TRUE), max(vals, na.rm = TRUE))
                }, numeric(2)))
                blocks_df$rect_xmin_disp <- disp_bounds[, 1]
                blocks_df$rect_xmax_disp <- disp_bounds[, 2]
                blocks_df$hover_ymin <- blocks_df$y - pip_block_half
                blocks_df$hover_ymax <- blocks_df$y + pip_block_half
            }
        }
        blocks_hover_input <- merge_blocks_for_hover(
            blocks_df,
            gap_fraction = 0.002,
            ref_window_span = ref_window_span
        )
        block_hover_df <- build_hover_rect_overlay(
            blocks_hover_input,
            xmin_col = "rect_xmin_disp",
            xmax_col = "rect_xmax_disp",
            ymin_col = "hover_ymin",
            ymax_col = "hover_ymax",
            tooltip_col = "tooltip",
            data_id_col = "data_id",
            id_suffix = "_pip_block",
            min_width = hover_min_span,
            min_height = max(pip_block_half * 2 + 0.08, 0.44)
        )

        p <- ggplot2::ggplot(display_rows) +
            {
                band_df <- row_band_df[!row_band_df$is_reference & row_band_df$is_even, , drop = FALSE]
                if (nrow(band_df) > 0L) {
                    ggplot2::geom_rect(
                        data = band_df,
                        ggplot2::aes(
                            xmin = xmin,
                            xmax = xmax,
                            ymin = ymin,
                            ymax = ymax
                        ),
                        inherit.aes = FALSE,
                        fill = if (is_dark_theme) "#11283B" else "#F8FBFD",
                        alpha = 0.92,
                        color = NA
                    )
                }
            } +
            {
                ref_band_df <- row_band_df[row_band_df$is_reference, , drop = FALSE]
                if (nrow(ref_band_df) > 0L) {
                    ggplot2::geom_rect(
                        data = ref_band_df,
                        ggplot2::aes(
                            xmin = xmin,
                            xmax = xmax,
                            ymin = ymin,
                            ymax = ymax
                        ),
                        inherit.aes = FALSE,
                        fill = if (is_dark_theme) "#15324A" else "#F1F7FA",
                        alpha = 0.82,
                        color = NA
                    )
                }
            } +
            # Guide lines (50 %/100 % identity) removed — identity is now
            # encoded by fill colour (nucleotide-view style), not y-position.
            {
                if (is.finite(ref_gene_start_clip) && is.finite(ref_gene_end_clip)) {
                    ggplot2::annotate(
                        "rect",
                        xmin = ref_gene_start_disp,
                        xmax = ref_gene_end_disp,
                        ymin = min(display_rows$y) - 0.36,
                        ymax = max(display_rows$y) + 0.36,
                        fill = if (is_dark_theme) "#D8EDF8" else "#A9C7D8",
                        alpha = if (is_dark_theme) 0.05 else 0.08,
                        color = NA
                    )
                }
            } +
            {
                if (is.finite(ref_gene_start_disp)) {
                    ggplot2::geom_vline(
                        xintercept = ref_gene_start_disp,
                        color = if (is_dark_theme) "#7893A8" else "#B5C5CF",
                        linewidth = 0.45,
                        linetype = "22",
                        alpha = 0.75
                    )
                }
            } +
            {
                if (is.finite(ref_gene_end_disp)) {
                    ggplot2::geom_vline(
                        xintercept = ref_gene_end_disp,
                        color = if (is_dark_theme) "#7893A8" else "#B5C5CF",
                        linewidth = 0.45,
                        linetype = "22",
                        alpha = 0.75
                    )
                }
            } +
	            ggiraph::geom_segment_interactive(
	                data = display_rows[display_rows$is_reference, , drop = FALSE],
	                ggplot2::aes(
	                    x = x, xend = xend,
	                    y = y, yend = y,
	                    tooltip = tooltip,
	                    data_id = data_id
	                ),
	                colour = ref_color,
	                linewidth = 1.8,
	                lineend = "round"
	            ) +
	            ggiraph::geom_segment_interactive(
	                data = display_rows[!display_rows$is_reference, , drop = FALSE],
	                ggplot2::aes(
	                    x = x, xend = xend,
	                    y = y, yend = y,
	                    tooltip = tooltip,
	                    data_id = data_id
	                ),
	                colour = line_color,
	                linewidth = 0.6,
	                lineend = "round"
	            ) +
            {
                if (is.finite(ref_gene_start_disp) && is.finite(ref_gene_end_disp) && is.finite(ref_row_y)) {
                    ref_gene_left <- min(ref_gene_start_disp, ref_gene_end_disp, na.rm = TRUE)
                    ref_gene_right <- max(ref_gene_start_disp, ref_gene_end_disp, na.rm = TRUE)
                    ggplot2::geom_segment(
                        data = data.frame(
                            x = ref_gene_left,
                            xend = ref_gene_right,
                            y = ref_row_y,
                            yend = ref_row_y
                        ),
                        ggplot2::aes(x = x, xend = xend, y = y, yend = yend),
                        color = if (is_dark_theme) "#D8EDF8" else "#27485E",
                        linewidth = 1.45,
                        lineend = "round",
                        alpha = 0.95
                    )
                }
            } +
            {
                if (is.data.frame(exon_df) && nrow(exon_df) > 0L) {
                    ggplot2::geom_rect(
                        data = exon_df,
                        ggplot2::aes(
                            xmin = xstart_disp,
                            xmax = xend_disp,
                            ymin = ref_row_y - 0.14,
                            ymax = ref_row_y + 0.14
                        ),
                        fill = exon_fill,
                        color = feature_border,
                        linewidth = 0.55,
                        alpha = 1
                    )
                }
            } +
            {
                if (is.data.frame(utr_df) && nrow(utr_df) > 0L) {
                    ggplot2::geom_rect(
                        data = utr_df,
                        ggplot2::aes(
                            xmin = xstart_disp,
                            xmax = xend_disp,
                            ymin = ref_row_y - 0.11,
                            ymax = ref_row_y + 0.11
                        ),
                        fill = utr_fill,
                        color = feature_border,
                        linewidth = 0.45,
                        alpha = 1
                    )
                }
            } +
            {
                if (is.data.frame(cds_df) && nrow(cds_df) > 0L) {
                    ggplot2::geom_rect(
                        data = cds_df,
                        ggplot2::aes(
                            xmin = xstart_disp,
                            xmax = xend_disp,
                            ymin = ref_row_y - 0.14,
                            ymax = ref_row_y + 0.14
                        ),
                        fill = cds_fill,
                        color = feature_border,
                        linewidth = 0.55,
                        alpha = 1
                    )
                }
            } +
            {
                if (is.data.frame(blocks_df) && nrow(blocks_df) > 0L) {
                    fwd_df <- blocks_df[blocks_df$strand_state != "reverse", , drop = FALSE]
                    rev_df <- blocks_df[blocks_df$strand_state == "reverse", , drop = FALSE]
                    list(
                        # Forward-strand blocks: flat filled rectangles
                        ggplot2::geom_rect(
                            data = fwd_df,
                            ggplot2::aes(
                                xmin = rect_xmin_disp,
                                xmax = rect_xmax_disp,
                                ymin = y - pip_block_half,
                                ymax = y + pip_block_half,
                                fill = id_cat
                            ),
                            color = NA,
                            alpha = 0.88
                        ),
                        # Reverse-strand / inverted blocks: same fill + dashed orange border
                        ggplot2::geom_rect(
                            data = rev_df,
                            ggplot2::aes(
                                xmin = rect_xmin_disp,
                                xmax = rect_xmax_disp,
                                ymin = y - pip_block_half,
                                ymax = y + pip_block_half,
                                fill = id_cat
                            ),
                            color = reverse_color,
                            linewidth = 0.65,
                            linetype = "dashed",
                            alpha = 0.88
                        )
                    )
                }
            } +
            {
                hover_layers <- list()
                if (is.data.frame(exon_hover_df) && nrow(exon_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = exon_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        color = NA,
                        fill = feature_hover_color,
                        alpha = 0.003
                    )
                }
                if (is.data.frame(utr_hover_df) && nrow(utr_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = utr_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        color = NA,
                        fill = feature_hover_color,
                        alpha = 0.003
                    )
                }
                if (is.data.frame(cds_hover_df) && nrow(cds_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = cds_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        color = NA,
                        fill = feature_hover_color,
                        alpha = 0.003
                    )
                }
                if (is.data.frame(block_hover_df) && nrow(block_hover_df) > 0L) {
                    hover_layers[[length(hover_layers) + 1L]] <- ggiraph::geom_rect_interactive(
                        data = block_hover_df,
                        ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, tooltip = tooltip, data_id = data_id),
                        color = NA,
                        fill = feature_hover_color,
                        alpha = 0.003
                    )
                }
                hover_layers

            } +
            {
                if (!is.data.frame(blocks_df) || nrow(blocks_df) == 0L) {
	                    ggplot2::geom_label(
	                        data = data.frame(
	                            x = ref_gene_center,
	                            y = mean(range(display_rows$y)),
	                            label = "No local blocks visible with current filters\nTry lowering Min. local identity or Min. block length",
	                            stringsAsFactors = FALSE
	                        ),
	                        ggplot2::aes(x = x, y = y, label = label),
	                        inherit.aes = FALSE,
	                        color = axis_color,
	                        fill = if (is_dark_theme) "#173149" else "#F4F8FB",
	                        alpha = 0.95,
	                        linewidth = 0.25,
	                        label.r = grid::unit(0.16, "lines"),
	                        label.padding = grid::unit(0.24, "lines"),
	                        size = 3.3
	                    )
	                }
	            } +
	            ggplot2::scale_fill_manual(
                values = c(
                    identical = nv_identical_color,
                    similar   = nv_similar_color,
                    moderate  = nv_moderate_color
                ),
                guide = "none"
            ) +
            {
                exon_number_df <- ref_feature_df[ref_feature_df$feature_group == "exon" & is.finite(ref_feature_df$exon_rank), , drop = FALSE]
                if (is.data.frame(exon_number_df) && nrow(exon_number_df) > 0L) {
                    ggplot2::geom_text(
                        data = exon_number_df,
                        ggplot2::aes(
                            x = (xstart_disp + xend_disp) / 2,
                            y = ref_row_y + 0.24,
                            label = as.integer(round(exon_rank))
                        ),
                        inherit.aes = FALSE,
                        color = axis_color,
                        size = 3.0,
                        fontface = "bold"
                    )
                }
            } +
            {
                if (is.finite(ref_gene_start_disp) && is.finite(ref_gene_end_disp) && is.finite(ref_row_y)) {
                    display_right <- suppressWarnings(max(display_breaks_df$disp, na.rm = TRUE))
                    display_span <- suppressWarnings(diff(range(display_breaks_df$disp, na.rm = TRUE)))
                    arrow_len <- max(if (is.finite(display_span)) display_span * 0.007 else 0, 0.55)
                    arrow_xend <- display_right
                    arrow_x <- arrow_xend - arrow_len
                    if (is.finite(arrow_x) && is.finite(arrow_xend) && (arrow_xend - arrow_x) > 0.08) {
                        ggplot2::geom_segment(
                            data = data.frame(
                                x = arrow_x,
                                xend = arrow_xend,
                                y = ref_row_y,
                                yend = ref_row_y
                            ),
                            ggplot2::aes(x = x, xend = xend, y = y, yend = yend),
                            color = if (is_dark_theme) "#D8EDF8" else "#27485E",
                            linewidth = 1.45,
                            lineend = "round",
                            arrow = ggplot2::arrow(
                                length = grid::unit(0.085, "inches"),
                                type = "closed",
                                ends = "last"
                            ),
                            alpha = 0.98
                        )
                    }
                }
            } +
            # Gene + strand and transcript labels are now embedded in the
            # y-axis multi-line labels (see display_rows$label in the scene).
            # The right-side track_label_df overlay is suppressed here.
            ggplot2::annotate("text", x = ref_gene_center_disp, y = ref_row_y + 0.50, label = ref_label_main, color = axis_color, size = 4.2, fontface = "bold.italic") +
            ggplot2::scale_y_continuous(
                breaks = display_rows$y,
                labels = display_rows$label,
                expand = ggplot2::expansion(mult = c(0.08, 0.16))
            ) +
            ggplot2::scale_x_continuous(
                breaks = display_breaks_df$disp,
                labels = display_breaks_df$label,
                expand = ggplot2::expansion(mult = c(0.02, 0.02))
            ) +
            ggplot2::coord_cartesian(
                xlim = {
                    x_range <- range(display_breaks_df$disp, na.rm = TRUE)
                    x_pad <- max(diff(x_range) * 0.03, 1.2)
                    c(x_range[1], x_range[2] + x_pad)
                },
                clip = "on"
            ) +
            ggplot2::labs(x = "Reference locus coordinate system", y = NULL) +
            ggplot2::theme_minimal(base_size = 12) +
            ggplot2::theme(
                panel.background = ggplot2::element_rect(fill = bg_color, color = NA),
                plot.background = ggplot2::element_rect(fill = bg_color, color = NA),
                panel.grid.major.x = ggplot2::element_blank(),
                panel.grid.minor = ggplot2::element_blank(),
                panel.grid.major.y = ggplot2::element_blank(),
                axis.text.x = ggplot2::element_text(color = axis_color, size = 11),
                axis.text.y = ggplot2::element_text(
                    color      = axis_color,
                    size       = 9.5,
                    face       = "bold.italic",
                    lineheight = 1.2,
                    hjust      = 1,
                    margin     = ggplot2::margin(r = 4, unit = "pt")
                ),
                axis.title.x = ggplot2::element_text(color = axis_color, size = 12, face = "bold"),
                axis.title.y = ggplot2::element_blank(),
                axis.line.x  = ggplot2::element_blank(),
                axis.ticks.x = ggplot2::element_blank()
            )

        pip_exon_hover_n <- if (is.data.frame(exon_hover_df)) as.integer(nrow(exon_hover_df)) else 0L
        pip_utr_hover_n <- if (is.data.frame(utr_hover_df)) as.integer(nrow(utr_hover_df)) else 0L
        pip_cds_hover_n <- if (is.data.frame(cds_hover_df)) as.integer(nrow(cds_hover_df)) else 0L
        pip_block_hover_n <- if (is.data.frame(block_hover_df)) as.integer(nrow(block_hover_df)) else 0L
        send_girafe_diag_expected(
            "ortho_pip_plot_out",
            expected = list(
                render_mode = "pip",
                feature_hover_exon = pip_exon_hover_n,
                feature_hover_utr = pip_utr_hover_n,
                feature_hover_cds = pip_cds_hover_n,
                block_hover = pip_block_hover_n,
                block_visual = if (is.data.frame(blocks_df)) as.integer(nrow(blocks_df)) else 0L,
                interactive_total = as.integer(pip_exon_hover_n + pip_utr_hover_n + pip_cds_hover_n + pip_block_hover_n)
            ),
            meta = list(
                guardrail_triggered = isTRUE(scene$guardrail_triggered),
                raw_block_total = as.integer(scene$raw_block_total %||% 0L),
                visible_block_total = as.integer(scene$visible_block_total %||% 0L)
            )
        )
        safe_girafe(
            ggobj = p,
            width_svg = 14,
            height_svg = max(3.6, 1.2 + length(ids) * 0.78),
            transport_label = "ortho_pip_blocks",
	            options = list(
	                ggiraph::opts_hover(css = ""),
	                ggiraph::opts_selection(type = "none"),
	                ggiraph::opts_tooltip(
	                    css = analytics_tooltip_css,
	                    use_fill = FALSE,
	                    placement = "auto",
	                    zindex = 999999,
	                    delay_mouseover = 60,
	                    delay_mouseout = 500
	                ),
	                ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
	                ggiraph::opts_sizing(rescale = TRUE)
	            )
        )
        }, error = function(e) {
            pip_placeholder_plot(
                "LASTZ Block View could not be rendered yet",
                paste0("Runtime detail: ", trimws(as.character(conditionMessage(e) %||% "unknown error")))
            )
        })
    }), list(
        input$ortho_visual_mode,
        input$app_theme,
        input$colorblind_mode,
        input$ortho_pip_reference_track,
        input$ortho_pip_span,
        input$ortho_pip_track_order,
        input$ortho_pip_min_identity,
        input$ortho_pip_min_length,
        input$ortho_pip_run_alignments,
        pipLocalAlignmentRunStampOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_pip_plot_out", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

	    output$ortho_pip_footer <- bindEvent(renderUI({
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        req(identical(current_mode, "pip_blocks"), cancelOutput = TRUE)
        scene <- pipProcessedSceneOrthologous()
        ids <- as.character(scene$ids %||% character(0))
        if (length(ids) == 0L) {
            return(NULL)
        }
        ctx_map <- scene$ctx_map %||% list()
        ref_ctx <- scene$ref_ctx %||% NULL
        ref_id <- trimws(as.character(scene$ref_id %||% ""))
        ref_label <- if (nzchar(ref_id)) {
            ref_meta <- ctx_map[[ref_id]] %||% list()
            org_txt <- trimws(as.character(ref_meta$organism_name %||% ""))
            ttl_txt <- trimws(as.character(ref_meta$title %||% ""))
            if (nzchar(org_txt) && nzchar(ttl_txt)) paste0(org_txt, " | ", ttl_txt) else if (nzchar(org_txt)) org_txt else if (nzchar(ttl_txt)) ttl_txt else ref_id
        } else {
            "Auto"
        }
        span_label <- as.character(scene$span_label %||% "Gene + 10 kb")
        min_identity <- as.numeric(scene$min_identity %||% 70)
        min_length <- as.integer(scene$min_block_length %||% 100L)
        ref_window_txt <- if (!is.null(ref_ctx)) {
            paste0(
                as.character(scene$ref_ctx$seqid %||% ref_ctx$seqid %||% ""),
                ":",
                format(as.integer(scene$ref_window_start %||% NA_integer_), big.mark = ","),
                "-",
                format(as.integer(scene$ref_window_end %||% NA_integer_), big.mark = ",")
            )
        } else {
            "N/A"
        }
        ref_window_bp <- if (!is.null(ref_ctx)) {
            start_i <- suppressWarnings(as.integer(scene$ref_window_start %||% ref_ctx$window_start %||% NA_integer_))
            end_i <- suppressWarnings(as.integer(scene$ref_window_end %||% ref_ctx$window_end %||% NA_integer_))
            if (is.finite(start_i) && is.finite(end_i) && end_i >= start_i) end_i - start_i + 1L else NA_integer_
        } else {
            NA_integer_
        }
        flank_bp <- parse_locus_window_flank_bp(input$ortho_pip_span %||% "gene", default_bp = 0L)
        scope_txt <- if (flank_bp <= 0L) "Gene body only (0 bp flanks)" else paste0("Gene + ", format(as.integer(flank_bp), big.mark = ","), " bp flanks")
        block_total <- as.integer(scene$raw_block_total %||% 0L)
        display_block_total <- if (isTRUE(scene$guardrail_triggered)) {
            paste0(as.integer(scene$visible_block_total %||% 0L), " shown (summary)")
        } else {
            as.character(as.integer(scene$visible_block_total %||% 0L))
        }
        assess <- pipReferenceAssessmentOrthologous() %||% list()
        tags$div(
            style = "display:flex; flex-wrap:wrap; gap:8px 10px; align-items:center;",
            tags$span(style = "font-weight:700;", "LASTZ Block View ready"),
            tags$span(style = "opacity:0.82;", paste0("Reference: ", ref_label)),
            tags$span(style = "opacity:0.82;", paste0("Reference state: ", if (identical(trimws(as.character(assess$status %||% "")), "evaluated")) "Evaluated from current run" else if (identical(trimws(as.character(assess$status %||% "")), "unavailable")) "Evaluation unavailable" else "Pending run")),
            tags$span(style = "opacity:0.82;", paste0("Reference window: ", ref_window_txt)),
            tags$span(style = "opacity:0.82;", paste0("Window: ", span_label)),
            if (is.finite(ref_window_bp)) tags$span(style = "opacity:0.82;", paste0("Aligned reference bp: ", format(as.integer(ref_window_bp), big.mark = ","))) else NULL,
            tags$span(style = "opacity:0.82;", paste0("Scope: ", scope_txt)),
            tags$span(style = "opacity:0.82;", paste0("Organisms shown: ", max(length(ids) - 1L, 0L), " query + 1 reference")),
            tags$span(style = "opacity:0.82;", paste0("Raw blocks: ", block_total)),
            tags$span(style = "opacity:0.82;", paste0("Visible blocks: ", display_block_total)),
            tags$span(style = "opacity:0.82;", paste0("Min identity: ", as.integer(round(min_identity)), "%")),
            tags$span(style = "opacity:0.82;", paste0("Min block length: ", min_length, " bp")),
            if (isTRUE(scene$guardrail_triggered)) tags$span(style = "opacity:0.82; color:#C0622A;", scene$guardrail_message) else NULL
        )
    }), list(
        input$ortho_visual_mode,
        input$ortho_pip_reference_track,
        input$ortho_pip_span,
        input$ortho_pip_track_order,
        input$ortho_pip_min_identity,
        input$ortho_pip_min_length,
        input$ortho_pip_run_alignments,
        pipLocalAlignmentRunStampOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_pip_footer", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

    output$ortho_multipip_reference_ui <- renderUI({
        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
        titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
        org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
        assess <- multipipReferenceAssessmentOrthologous() %||% list()
        strip_tx <- function(s) trimws(gsub("\\s*\\|\\s*Transcript:[^|]*", "", s))
        label_for_id <- function(pid) {
            org_txt <- trimws(as.character(((org_map[[pid]] %||% list())$name %||% "")[1] %||% ""))
            ttl_txt <- strip_tx(trimws(as.character((titles_map[[pid]] %||% "")[1] %||% "")))
            if (nchar(ttl_txt, type = "width") > 55L) {
                ttl_txt <- paste0(substr(ttl_txt, 1L, 52L), "...")
            }
            if (nzchar(org_txt) && nzchar(ttl_txt)) {
                paste0(org_txt, " | ", ttl_txt)
            } else if (nzchar(org_txt)) {
                org_txt
            } else if (nzchar(ttl_txt)) {
                ttl_txt
            } else {
                pid
            }
        }
        selected_id <- trimws(as.character(multipipReferencePlotIdOrthologous() %||% ""))
        if (length(ids) > 0L && (!nzchar(selected_id) || !selected_id %in% ids)) {
            selected_id <- ids[[1]]
        }
        multipip_ref_theme <- tolower(as.character(input$app_theme %||% "light"))
        if (!multipip_ref_theme %in% c("light", "dark")) multipip_ref_theme <- "light"
        is_dark_multipip_ref <- identical(multipip_ref_theme, "dark")
        status_txt <- trimws(as.character(assess$status %||% "pending"))
        is_evaluated <- identical(status_txt, "evaluated") && identical(trimws(as.character(assess$reference_id %||% "")), selected_id)
        is_unavailable <- identical(status_txt, "unavailable") && identical(trimws(as.character(assess$reference_id %||% "")), selected_id)
        chip_bg <- if (is_evaluated) "rgba(76, 150, 96, 0.12)" else if (is_unavailable) "rgba(196, 84, 80, 0.10)" else "rgba(196, 133, 68, 0.12)"
        chip_border <- if (is_evaluated) "#6EA776" else if (is_unavailable) "#D29792" else "#C18A54"
        chip_txt <- if (is_evaluated) "#3C6A43" else if (is_unavailable) "#8D3E3A" else "#8B5B2C"
        chip_label <- if (is_evaluated) "Evaluated" else if (is_unavailable) "Unavailable" else "Pending run"
        div(
            class = "ortho-aligned-control ortho-aligned-control--select",
            div(
                class = "ortho-pip-reference-label",
                tags$span("Reference track:", class = "ortho-aligned-control-label"),
                tags$span(
                    class = "ortho-pip-reference-chip",
                    style = paste0(
                        "display:inline-flex; align-items:center; padding:3px 9px; border-radius:999px; font-size:11px; font-weight:700; ",
                        "background:", chip_bg, "; border:1px solid ", chip_border, "; color:", chip_txt, ";"
                    ),
                    chip_label
                )
            ),
            if (length(ids) > 0L) {
                shiny::selectInput(
                    inputId = "ortho_multipip_reference_track",
                    label = NULL,
                    choices = stats::setNames(ids, vapply(ids, label_for_id, character(1))),
                    selected = selected_id,
                    width = "100%"
                )
            } else {
                div(
                    class = "ortho-pip-no-ref-placeholder",
                    style = if (is_dark_multipip_ref) {
                        "height:38px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid #284562; background:linear-gradient(180deg,#10263b 0%,#0d2033 100%); color:#5d7e96; font-size:0.94rem;"
                    } else {
                        "height:38px; display:flex; align-items:center; padding:0 12px; border-radius:10px; border:1px solid rgba(189,201,210,0.95); background:rgba(248,250,252,0.96); color:#8394A2; font-size:0.94rem;"
                    },
                    "No reference available yet"
                )
            }
        )
    })
    outputOptions(output, "ortho_multipip_reference_ui", suspendWhenHidden = FALSE)

    output$ortho_multipip_reference_note_ui <- renderUI({
        ids <- as.character(pipRepresentativePlotIdsOrthologous() %||% character(0))
        assess <- multipipReferenceAssessmentOrthologous() %||% list()
        status_txt <- trimws(as.character(assess$status %||% "pending"))
        is_evaluated <- identical(status_txt, "evaluated")
        is_unavailable <- identical(status_txt, "unavailable")
        title_txt <- if (is_evaluated || is_unavailable) "Reference evaluation" else "Reference status"
        detail_txt <- trimws(as.character(
            if (is_evaluated || is_unavailable) {
                assess$summary %||% assess$detail %||% ""
            } else if (length(ids) > 0L) {
                "Run local alignments to evaluate the selected reference using the same gap-free segments shown by MultiPIP."
            } else {
                "Load cross-species comparison tracks first, then choose a reference and run local alignments."
            }
        ))
        if (!nzchar(detail_txt)) {
            return(NULL)
        }
        div(
            class = "ortho-pip-reference-note-card",
            tags$small(
                class = "ortho-pip-reference-note-copy",
                style = "display: block;",
                tags$b(title_txt),
                tags$span(
                    paste0(" — ", detail_txt),
                    style = "color: var(--bs-secondary-color, #6c757d);"
                )
            )
        )
    })

    output$ortho_multipip_help <- renderUI({
        ref_ctx <- multipipReferenceWindowOrthologous()
        run_map <- multipipLocalAlignmentRunsOrthologous() %||% list()
        engine_note <- ""
        if (length(run_map) > 0L) {
            first_run <- run_map[[1]] %||% list()
            if (identical(trimws(as.character(first_run$status %||% "")), "engine_unavailable")) {
                engine_note <- paste0(" ", as.character(first_run$setup_hint %||% "LASTZ is unavailable in this environment."))
            }
        }
        ref_window_txt <- if (!is.null(ref_ctx)) {
            paste0(
                as.character(ref_ctx$seqid %||% ""),
                ":",
                format(as.integer(ref_ctx$window_start %||% NA_integer_), big.mark = ","),
                "\u2013",
                format(as.integer(ref_ctx$window_end %||% NA_integer_), big.mark = ",")
            )
        } else {
            "not available yet"
        }
        span_mode <- trimws(as.character(input$ortho_multipip_span %||% "gene"))
        flank_bp <- parse_locus_window_flank_bp(span_mode, default_bp = 0L)
        ref_bp <- if (!is.null(ref_ctx)) {
            start_i <- suppressWarnings(as.integer(ref_ctx$window_start %||% NA_integer_))
            end_i <- suppressWarnings(as.integer(ref_ctx$window_end %||% NA_integer_))
            if (is.finite(start_i) && is.finite(end_i) && end_i >= start_i) end_i - start_i + 1L else NA_integer_
        } else {
            NA_integer_
        }
        window_scope_msg <- if (is.finite(ref_bp)) {
            if (flank_bp <= 0L) {
                sprintf(" Gene body only uses 0 bp flanks (%s bp on the reference).", format(as.integer(ref_bp), big.mark = ","))
            } else {
                sprintf(" This setting adds %s bp on each side (%s bp on the reference), so runtime can grow with the selected flank.", format(as.integer(flank_bp), big.mark = ","), format(as.integer(ref_bp), big.mark = ","))
            }
        } else if (flank_bp <= 0L) {
            " Gene body only uses 0 bp flanks."
        } else {
            sprintf(" This setting adds %s bp on each side; longer windows can take longer to align.", format(as.integer(flank_bp), big.mark = ","))
        }
        tags$small(
            HTML(
                paste0(
                    "<b>MultiPIP-style percent identity plot</b> &mdash; pruned <em>gap-free</em> LASTZ segments are stacked over the chosen reference, with identity read vertically from <b>50% to 100%</b>. ",
                    "Current reference window: ", ref_window_txt, ".", window_scope_msg, engine_note
                )
            )
        )
    })

    output$ortho_multipip_legend <- renderUI({
        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark <- identical(theme_mode, "dark")

        txt_col  <- if (is_dark) "#C8DDF0" else "#2F4357"
        lbl_col  <- if (is_dark) "#9bbfd4" else "#324B5F"
        chip <- function(fill_l, fill_d, border_l, border_d, label) {
            tags$span(
                style = paste0(
                    "display:inline-flex; align-items:center; gap:5px; padding:3px 8px; border-radius:999px; font-size:11px; ",
                    "border:1px solid ", if (is_dark) border_d else border_l, "; ",
                    "background:", if (is_dark) fill_d else fill_l, "; ",
                    "color:", txt_col, "; font-weight:600;"
                ),
                tags$span(
                    style = paste0(
                        "display:inline-block; width:14px; height:3px; border-radius:999px; ",
                        "background:", if (is_dark) border_d else border_l, "; flex-shrink:0;"
                    )
                ),
                label
            )
        }
        tagList(
            div(
                style = "display:flex; flex-wrap:wrap; gap:5px 8px; align-items:center; margin-bottom:5px;",
                tags$span(style = paste0("font-size:11px; font-weight:700; color:", lbl_col, ";"), "Visual encoding:"),
                chip("#F4F4F4", "rgba(200,221,240,0.08)", "#1E1E1E", "#8aacbe",
                     "forward gap-free segment"),
                chip("#FFF4E8", "rgba(197,108,44,0.12)", "#C56C2C", "#C56C2C",
                     "reverse / inversion candidate"),
                tags$span(
                    style = paste0(
                        "display:inline-flex; align-items:center; gap:5px; padding:3px 8px; border-radius:999px; font-size:11px; font-weight:600; ",
                        "border:1px solid ", if (is_dark) "#6b7e72" else "#C8BFA8", "; ",
                        "background:", if (is_dark) "rgba(200,186,130,0.10)" else "#F0EDE4", "; ",
                        "color:", txt_col, ";"
                    ),
                    tags$span(style = paste0(
                        "display:inline-block; width:12px; height:8px; border-radius:2px; flex-shrink:0; ",
                        "background:", if (is_dark) "rgba(255,246,168,0.45)" else "#FFF6A8", "; ",
                        "border:1px solid ", if (is_dark) "#8a8060" else "#8C867B", ";"
                    )),
                    "reference underlay annotation"
                )
            )
        )
    })

    output$ortho_multipip_status_ui <- renderUI({
        scene <- multipipProcessedSceneOrthologous()
        ids <- as.character(scene$ids %||% character(0))
        if (length(ids) == 0L) {
            return(div(style = "opacity:0.78;", "No cross-species comparison tracks are loaded yet for MultiPIP-style view."))
        }
        ref_id <- trimws(as.character(scene$ref_id %||% ""))
        min_identity <- as.numeric(scene$min_identity %||% 70)
        min_segment_bp <- as.integer(scene$min_segment_bp %||% 25L)
        run_stats <- scene$run_stats %||% list()
        rows <- lapply(ids[ids != ref_id], function(pid) {
            st <- run_stats[[pid]] %||% list()
            tags$div(
                class = "ortho-pip-status-row",
                tags$strong(trimws(as.character(st$org_txt %||% pid))),
                tags$span(
                    style = paste0(
                        "display:inline-flex; align-items:center; padding:3px 10px; border-radius:999px; font-size:12px; font-weight:700; ",
                        if (identical(trimws(as.character(st$status %||% "")), "ok")) {
                            "background:rgba(86, 175, 110, 0.10); border:1px solid #7CBD8A; color:#2F7441;"
                        } else if (identical(trimws(as.character(st$status %||% "")), "engine_unavailable")) {
                            "background:rgba(201, 129, 77, 0.10); border:1px solid #D49B72; color:#8B5B2C;"
                        } else {
                            "background:rgba(125, 150, 175, 0.10); border:1px solid #A7B8C8; color:#4F6779;"
                        }
                    ),
                    paste0("status: ", as.character(st$status %||% "not-run"))
                ),
                tags$span(paste0("locus: ", as.character(st$seqid_txt %||% "N/A"))),
                tags$span(paste0("segments parsed: ", as.integer(st$total_segments %||% 0L))),
                tags$span(
                    paste0(
                        "visible segments: ",
                        if (isTRUE(scene$guardrail_triggered)) {
                            paste0(as.integer(st$visible_segments %||% 0L), " shown from ", as.integer(st$sampled_segments %||% 0L), " sampled")
                        } else {
                            as.character(as.integer(st$visible_segments %||% 0L))
                        }
                    )
                )
            )
        })
        tagList(
            div(
                style = "display:flex; flex-wrap:wrap; gap:8px 14px; align-items:center; margin-bottom:8px;",
                tags$strong("Backend status"),
                tags$span(paste0("Reference track: ", max(length(ids) - 1L, 0L), " query + 1 reference")),
                tags$span(paste0("Identity filter: ", as.integer(round(min_identity)), "%")),
                tags$span(paste0("Length filter: ", min_segment_bp, " bp")),
                if (isTRUE(scene$guardrail_triggered)) tags$span(style = "color:#C56C2C;", scene$guardrail_message) else NULL
            ),
            rows
        )
    })

    output$ortho_multipip_plot_out <- bindEvent(renderGirafe({
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        req(identical(current_mode, "pip_multipip"), cancelOutput = TRUE)
        ids_requested <- as.character(multipipOrderedPlotIdsOrthologous() %||% character(0))
        req(length(ids_requested) > 0L, cancelOutput = TRUE)
        theme_mode <- tolower(as.character(input$app_theme %||% "light"))
        if (!theme_mode %in% c("light", "dark")) theme_mode <- "light"
        is_dark_theme <- identical(theme_mode, "dark")
        is_running_multipip <- isTRUE(multipipLocalAlignmentRunningOrthologous())
        run_map <- multipipLocalAlignmentRunsOrthologous() %||% list()
        has_run_payload <- length(run_map) > 0L
        bg_color <- if (is_dark_theme) "#102438" else "#FAFBFC"
        axis_color <- if (is_dark_theme) "#C8DAEA" else "#2F4357"
        subtitle_color <- if (is_dark_theme) "#9CB3C7" else "#5C7187"
        multipip_placeholder_plot <- function(title_txt, subtitle_txt = "") {
            p0 <- ggplot2::ggplot() +
                ggplot2::annotate("text", x = 0, y = 0.18, label = title_txt, size = 4.4, color = axis_color, fontface = "bold") +
                {
                    if (nzchar(trimws(as.character(subtitle_txt %||% "")))) {
                        ggplot2::annotate("text", x = 0, y = -0.12, label = subtitle_txt, size = 3.3, color = subtitle_color)
                    }
                } +
                ggplot2::xlim(-1, 1) + ggplot2::ylim(-1, 1) +
                ggplot2::theme_void() +
                ggplot2::theme(
                    panel.background = ggplot2::element_rect(fill = bg_color, color = NA),
                    plot.background = ggplot2::element_rect(fill = bg_color, color = NA)
                )
            safe_girafe(
                ggobj = p0,
                width_svg = 12,
                height_svg = 2.8,
                transport_label = "ortho_multipip_placeholder",
                options = list(
                    ggiraph::opts_hover(css = ""),
                    ggiraph::opts_selection(type = "none"),
                    ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
                    ggiraph::opts_sizing(rescale = TRUE)
                )
            )
        }
        scene <- multipipProcessedSceneOrthologous()
        ids <- as.character(scene$ids %||% character(0))
        if (length(ids) == 0L) {
            req(FALSE, cancelOutput = TRUE)
        }
        ctx_map <- scene$ctx_map %||% list()
        ref_ctx <- scene$ref_ctx %||% NULL
        if (is.null(ref_ctx)) {
            req(FALSE, cancelOutput = TRUE)
        }
        ref_id <- trimws(as.character(scene$ref_id %||% ""))
        min_identity <- as.numeric(scene$min_identity %||% 70)
        min_segment_bp <- as.integer(scene$min_segment_bp %||% 25L)
        ref_strand_display <- trimws(as.character(ref_ctx$strand %||% "+"))
        x_display_multipip <- function(x) orient_reference_coord(x, ref_window_start, ref_window_end, strand = ref_strand_display)
        # Use the representative transcript span as the visual coordinate system.
        # This keeps the reference structure at ~94% width (3% margin on each
        # side) even when the backing annotation also carries a larger gene row.
        multipip_window_spec <- resolve_reference_display_window(
            ref_ctx = ref_ctx,
            span_mode = input$ortho_multipip_span %||% "gene",
            default_start = scene$ref_window_start %||% 1,
            default_end = scene$ref_window_end %||% 100,
            pad_fraction = 0.03,
            min_pad_bp = 1L,
            prefer_transcript = TRUE
        )
        ref_window_start <- as.numeric(multipip_window_spec$display_start %||% scene$ref_window_start %||% 1)
        ref_window_end   <- as.numeric(multipip_window_spec$display_end %||% scene$ref_window_end %||% 100)
        x_display_multipip <- function(x) orient_reference_coord(x, ref_window_start, ref_window_end, strand = ref_strand_display)
        ref_span <- max(ref_window_end - ref_window_start, .Machine$double.eps)
        display_breaks_df <- data.frame(
            raw = c(ref_window_start, mean(c(ref_window_start, ref_window_end)), ref_window_end),
            stringsAsFactors = FALSE
        )
        display_breaks_df$disp <- x_display_multipip(display_breaks_df$raw)
        display_breaks_df$label <- format(as.integer(round(display_breaks_df$raw)), big.mark = ",")
        display_breaks_df <- display_breaks_df[order(display_breaks_df$disp), , drop = FALSE]
        all_display_rows <- scene$display_rows %||% data.frame(stringsAsFactors = FALSE)

        # Theme & palette
        is_colorblind_mode <- isTRUE(input$colorblind_mode)
        custom_overrides <- get_custom_color_palette()
        feature_palette    <- get_transcript_feature_palette(
            is_dark_theme      = is_dark_theme,
            is_colorblind_mode = is_colorblind_mode,
            custom_overrides = custom_overrides
        )
        pip_exon_color <- unname(feature_palette[["exon"]])
        pip_cds_color <- unname(feature_palette[["cds"]])
        pip_utr_color <- unname(feature_palette[["utr"]])

        axis_color    <- if (is_dark_theme) "#C8DAEA" else "#2F4357"
        frame_color   <- if (is_dark_theme) "#8FA8BC" else "#3C3A35"
        reverse_color <- if (is_dark_theme) "#F0A36C" else "#C56C2C"
        trace_color   <- if (is_dark_theme) "#D0DCE8" else "#161616"
        ref_underlay  <- scene$ref_underlay %||% list()
        ref_feature_df <- scene$ref_feature_df %||% NULL
        segments_df    <- scene$segments_df %||% data.frame(stringsAsFactors = FALSE)
        if (is.data.frame(segments_df) && nrow(segments_df) > 0L) {
            id_pct_num <- suppressWarnings(as.numeric(segments_df$identity_pct %||% NA_real_))
            segments_df$id_cat <- ifelse(
                is.finite(id_pct_num) & id_pct_num >= 95,
                "identical",
                ifelse(is.finite(id_pct_num) & id_pct_num >= 80, "similar", "moderate")
            )
            segments_df$strand_state <- ifelse(trimws(as.character(segments_df$strand %||% "+")) == "-", "reverse", "forward")
            segments_df$trace_col <- ifelse(trimws(as.character(segments_df$strand %||% "+")) == "-", reverse_color, trace_color)
        }

        # -- PipMaker layout: only query species as rows, reference → gene panel --
        query_rows <- all_display_rows[!all_display_rows$is_reference, , drop = FALSE]
        n_query    <- nrow(query_rows)
        # Track half-height: distance from row centre to box edge.
        # Larger = boxes taller = gap between adjacent boxes smaller.
        # 0.43 → gap ≈ 0.14 units (close but still distinct).
        TRACK_HALF <- 0.43
        # pip_inset: y_pip spans [row_y - pip_inset, row_y + pip_inset]
        # leaving a small margin inside each box border.
        pip_inset  <- TRACK_HALF * 0.83   # ≈ 0.357

        if (n_query > 0L) {
            query_rows$y <- rev(seq_len(n_query))
            # Re-map y_pip in segments_df to the new y positions
            if (is.data.frame(segments_df) && nrow(segments_df) > 0L && "query_plot_id" %in% names(segments_df)) {
                y_map <- setNames(query_rows$y, query_rows$plot_id)
                new_y <- y_map[as.character(segments_df$query_plot_id)]
                valid_y <- is.finite(suppressWarnings(as.numeric(new_y)))
                if (any(valid_y)) {
                    old_y <- as.numeric(segments_df$y)
                    segments_df$y[valid_y] <- as.numeric(new_y[valid_y])
                    for (pid in unique(segments_df$query_plot_id[valid_y])) {
                        idx <- valid_y & segments_df$query_plot_id == pid
                        if (any(idx)) {
                            row_y_new <- y_map[[as.character(pid)]]
                            id_pct    <- suppressWarnings(as.numeric(segments_df$identity_pct[idx]))
                            id_pct    <- pmax(50, pmin(100, ifelse(is.finite(id_pct), id_pct, 75)))
                            segments_df$y_pip[idx] <- row_y_new - pip_inset + 2 * pip_inset * ((id_pct - 50) / 50)
                        }
                    }
                }
            }
        }

        ref_gene_start_mp <- suppressWarnings(as.numeric(multipip_window_spec$body_start %||% NA_real_))
        ref_gene_end_mp   <- suppressWarnings(as.numeric(multipip_window_spec$body_end %||% NA_real_))
        ref_gene_center <- if (is.finite(ref_gene_start_mp) && is.finite(ref_gene_end_mp)) {
            mean(c(ref_gene_start_mp, ref_gene_end_mp))
        } else {
            as.numeric(scene$ref_gene_center %||% mean(c(ref_window_start, ref_window_end)))
        }
        ref_gene_center_disp <- x_display_multipip(ref_gene_center)

        # --- Display window ---
        # When a flanking span is selected (Gene + 5/10/25/50 kb), show the FULL
        # reference window so the aligned flanking context is always visible.
        # The gene body shading (Layer 2 below) distinguishes gene body from flank.
        # When "Gene only" is selected, zoom gently to the gene body with a small pad.
        # The display window is always ref_window_start / ref_window_end, which were
        # computed directly from the SELECTED reference gene's coordinates (+ any flank
        # chosen by the user, or 5% padding in "Gene only" mode).  We never re-centre
        # on the longest query gene — the reference gene always fills the full width.
        x_show_min  <- ref_window_start
        x_show_max  <- ref_window_end
        x_show_span <- max(x_show_max - x_show_min, .Machine$double.eps)
        ref_underlay_display <- materialize_multipip_underlay_features(
            ref_features = ref_feature_df,
            ref_window_start = x_show_min,
            ref_window_end = x_show_max,
            ref_strand = ref_strand_display,
            ref_row_y = scene$ref_row_y %||% NA_real_,
            feature_palette = ref_underlay$palette %||% list(exon = pip_exon_color, cds = pip_cds_color, utr = pip_utr_color),
            feature_border = ref_underlay$border %||% "#2C3E50"
        )

        # --- Prepare exon band data for the query tracks (PipMaker vertical bands) ---
        pip_exon_df <- ref_underlay_display$exon_df %||% data.frame(stringsAsFactors = FALSE)
        pip_cds_df <- ref_underlay_display$cds_df %||% data.frame(stringsAsFactors = FALSE)
        pip_utr_df <- ref_underlay_display$utr_df %||% data.frame(stringsAsFactors = FALSE)
        gene_sc_raw <- if (is.finite(ref_gene_start_mp)) pmax(ref_window_start, ref_gene_start_mp) else NA_real_
        gene_ec_raw <- if (is.finite(ref_gene_end_mp))   pmin(ref_window_end,   ref_gene_end_mp)   else NA_real_
        if (is.finite(gene_sc_raw) && is.finite(gene_ec_raw)) {
            gene_sc <- min(x_display_multipip(c(gene_sc_raw, gene_ec_raw)), na.rm = TRUE)
            gene_ec <- max(x_display_multipip(c(gene_sc_raw, gene_ec_raw)), na.rm = TRUE)
        } else {
            gene_sc <- NA_real_
            gene_ec <- NA_real_
        }

        # --- Reference organism label for gene panel ---
        # NOTE: isTRUE() only works on scalars — use which() for vector logical indexing
        ref_display_row <- all_display_rows[which(all_display_rows$is_reference), , drop = FALSE]
        ref_org_label_for_panel <- if (nrow(ref_display_row) > 0L)
            trimws(as.character(ref_display_row$org_label[[1]] %||% "")) else ""
        ref_ctx_display <- ref_ctx
        ref_ctx_display$gene_start <- if (is.finite(ref_gene_start_mp)) as.integer(round(ref_gene_start_mp)) else ref_ctx$gene_start
        ref_ctx_display$gene_end <- if (is.finite(ref_gene_end_mp)) as.integer(round(ref_gene_end_mp)) else ref_ctx$gene_end

        # --- Gene structure annotation panel (top) ---
        p_gene <- build_multipip_gene_structure_panel(
            ref_ctx          = ref_ctx_display,
            ref_underlay     = ref_underlay_display,
            ref_window_start = x_show_min,
            ref_window_end   = x_show_max,
            bg_color         = bg_color,
            axis_color       = axis_color,
            frame_color      = frame_color,
            exon_fill        = pip_exon_color,
            cds_fill         = pip_cds_color,
            utr_fill         = pip_utr_color,
            ref_org_label    = ref_org_label_for_panel
        )

        # Panel alignment: add a phantom (invisible) y-axis label to the gene panel
        # that matches the widest species label in the main plot.  ggplot2 then
        # allocates the exact same left-axis space for both panels automatically,
        # so the two drawing areas align horizontally without manual pt estimation.
        {
            label_strs <- if (n_query > 0L) {
                lv <- query_rows$org_label %||% query_rows$plot_id %||% character(0)
                as.character(lv[!is.na(lv) & nchar(as.character(lv)) > 0])
            } else character(0)
            longest_label <- if (length(label_strs) > 0L)
                label_strs[which.max(nchar(label_strs))] else ""
            if (nzchar(longest_label)) {
                # Show the reference organism name (italic) on the left y-axis of the
                # gene panel, matching the style of the query organism labels below.
                # longest_label is still used as the spacer so ggplot2 reserves at
                # least the same horizontal width — but we display ref_org_label_for_panel.
                gene_yaxis_label <- if (nzchar(ref_org_label_for_panel))
                    ref_org_label_for_panel else longest_label
                suppressMessages(
                    p_gene <- p_gene +
                        ggplot2::scale_y_continuous(
                            limits = c(0.14, 0.90),
                            breaks = 0.40,
                            labels = gene_yaxis_label,
                            expand = c(0, 0)
                        ) +
                        ggplot2::theme(
                            axis.text.y = ggplot2::element_text(
                                color  = axis_color,   # visible, italic
                                size   = 11,
                                face   = "bold.italic",
                                hjust  = 1,
                                lineheight = 1.15,
                                margin = ggplot2::margin(r = 4, unit = "pt")
                            )
                        )
                )
            }
        }

        # Clip segments to the display window so no rows fall outside the
        # scale range (avoids "Removed N rows" warnings from ggplot2).
        if (is.data.frame(segments_df) && nrow(segments_df) > 0L &&
            all(c("ref_start", "ref_end") %in% names(segments_df))) {
            seg_in <- is.finite(segments_df$ref_start) & is.finite(segments_df$ref_end) &
                      segments_df$ref_end   >= x_show_min &
                      segments_df$ref_start <= x_show_max
            segments_df <- segments_df[seg_in, , drop = FALSE]
            if (nrow(segments_df) > 0L) {
                segments_df$ref_start <- pmax(segments_df$ref_start, x_show_min)
                segments_df$ref_end   <- pmin(segments_df$ref_end,   x_show_max)
                seg_disp_bounds <- t(vapply(seq_len(nrow(segments_df)), function(i) {
                    vals <- x_display_multipip(c(segments_df$ref_start[[i]], segments_df$ref_end[[i]]))
                    c(min(vals, na.rm = TRUE), max(vals, na.rm = TRUE))
                }, numeric(2)))
                segments_df$ref_start_disp <- seg_disp_bounds[, 1]
                segments_df$ref_end_disp <- seg_disp_bounds[, 2]
            }
        }

        # --- Query identity tracks (main panel) ---
        shared_x_breaks <- pretty(c(x_show_min, x_show_max), n = 7)
        shared_x_labels <- function(x) format(as.integer(round(x)), big.mark = ",")
        shared_x_expand <- ggplot2::expansion(mult = c(0, 0))
        segments_df$hover_ymin <- segments_df$y_pip - 0.13
        segments_df$hover_ymax <- segments_df$y_pip + 0.13
        segments_hover_input <- segments_df
        if (is.data.frame(segments_hover_input) && nrow(segments_hover_input) > 0L) {
            segments_hover_input$rect_xmin <- segments_hover_input$ref_start
            segments_hover_input$rect_xmax <- segments_hover_input$ref_end
            segments_hover_input$rect_xmin_disp <- segments_hover_input$ref_start_disp
            segments_hover_input$rect_xmax_disp <- segments_hover_input$ref_end_disp
            segments_hover_input <- merge_blocks_for_hover(
                segments_hover_input,
                gap_fraction = 0.0015,
                ref_window_span = x_show_span
            )
        }
        segments_hover_df <- build_hover_rect_overlay(
            segments_hover_input,
            xmin_col = "rect_xmin_disp",
            xmax_col = "rect_xmax_disp",
            ymin_col = "hover_ymin",
            ymax_col = "hover_ymax",
            tooltip_col = "tooltip",
            data_id_col = "data_id",
            id_suffix = "_multipip",
            min_width = max(x_show_span * 0.0005, .Machine$double.eps),
            min_height = 0.26
        )
        segments_visual_df <- segments_df
        visual_merge_from <- app_env_int("APP_MULTIPIP_VISUAL_MERGE_FROM", 350L, min_value = 0L, max_value = 5000L)
        if (is.data.frame(segments_df) && nrow(segments_df) > visual_merge_from && visual_merge_from > 0L) {
            segments_visual_input <- segments_df
            segments_visual_input$rect_xmin <- segments_visual_input$ref_start
            segments_visual_input$rect_xmax <- segments_visual_input$ref_end
            segments_visual_input$rect_xmin_disp <- segments_visual_input$ref_start_disp
            segments_visual_input$rect_xmax_disp <- segments_visual_input$ref_end_disp
            segments_visual_input$y <- round(suppressWarnings(as.numeric(segments_visual_input$y_pip)), 2)
            segments_visual_input$hover_ymin <- segments_visual_input$y - 0.01
            segments_visual_input$hover_ymax <- segments_visual_input$y + 0.01
            segments_visual_merged <- merge_blocks_for_hover(
                segments_visual_input,
                gap_fraction = 0.003,
                ref_window_span = x_show_span
            )
            if (is.data.frame(segments_visual_merged) && nrow(segments_visual_merged) > 0L && nrow(segments_visual_merged) < nrow(segments_df)) {
                segments_visual_df <- data.frame(
                    ref_start_disp = suppressWarnings(as.numeric(segments_visual_merged$rect_xmin_disp)),
                    ref_end_disp = suppressWarnings(as.numeric(segments_visual_merged$rect_xmax_disp)),
                    y_pip = suppressWarnings(as.numeric(segments_visual_merged$y)),
                    trace_col = ifelse(
                        trimws(as.character(segments_visual_merged$strand_state %||% "forward")) == "reverse",
                        reverse_color,
                        trace_color
                    ),
                    stringsAsFactors = FALSE
                )
                segments_visual_df <- segments_visual_df[
                    is.finite(segments_visual_df$ref_start_disp) &
                        is.finite(segments_visual_df$ref_end_disp) &
                        is.finite(segments_visual_df$y_pip),
                    , drop = FALSE
                ]
            }
        }

        if (n_query == 0L) {
            p <- ggplot2::ggplot() +
                ggplot2::annotate("text", x = 0, y = 0, label = "No query species loaded",
                                  color = axis_color, size = 4) +
                ggplot2::xlim(x_show_min, x_show_max) +
                ggplot2::ylim(-1, 1) + ggplot2::theme_void() +
                ggplot2::theme(
                    panel.background = ggplot2::element_rect(fill = bg_color, color = NA),
                    plot.background  = ggplot2::element_rect(fill = bg_color, color = NA)
                )
        } else {
            y_all_min <- min(query_rows$y) - TRACK_HALF
            y_all_max <- max(query_rows$y) + TRACK_HALF

            row_box_df <- data.frame(
                xmin = x_show_min,
                xmax = x_show_max,
                ymin = query_rows$y - TRACK_HALF,
                ymax = query_rows$y + TRACK_HALF,
                stringsAsFactors = FALSE
            )

            # Attenuated border: distinct from the near-black alignment segment lines
            track_border_color <- if (is_dark_theme) "#4A6882" else "#A8B8C5"

            track_bg_color <- if (is_dark_theme) "#0f2133" else "#FFFFFF"
            p <- ggplot2::ggplot() +
                # Layer 1: track backgrounds (drawn first, under bands)
                ggplot2::geom_rect(
                    data = row_box_df,
                    ggplot2::aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax),
                    inherit.aes = FALSE,
                    fill      = track_bg_color,
                    color     = track_border_color,
                    linewidth = 0.55
                ) +
                # Layer 2: gene body subtle shading (across all query tracks)
                {
                    if (is.finite(gene_sc) && is.finite(gene_ec)) {
                        gene_shade <- if (is_dark_theme) "#1e4060" else "#EEF2F6"
                        ggplot2::annotate("rect",
                            xmin = gene_sc, xmax = gene_ec,
                            ymin = y_all_min, ymax = y_all_max,
                            fill = gene_shade, color = NA, alpha = if (is_dark_theme) 0.80 else 0.60
                        )
                    }
                } +
                # Layer 3: full exon extents across all tracks
                {
                    if (is.data.frame(pip_exon_df) && nrow(pip_exon_df) > 0L &&
                        all(c("xstart_clip", "xend_clip") %in% names(pip_exon_df))) {
                        ggplot2::geom_rect(
                            data = pip_exon_df,
                            ggplot2::aes(
                                xmin = xstart_disp,
                                xmax = xend_disp
                            ),
                            ymin = y_all_min, ymax = y_all_max,
                            inherit.aes = FALSE,
                            fill  = pip_exon_color,
                            color = NA,
                            alpha = if (is_dark_theme) 0.22 else 0.14
                        )
                    }
                } +
                # Layer 4: CDS exon vertical bands across all tracks (theme-aware color)
                {
                    if (is.data.frame(pip_cds_df) && nrow(pip_cds_df) > 0L &&
                        all(c("xstart_clip", "xend_clip") %in% names(pip_cds_df))) {
                        ggplot2::geom_rect(
                            data = pip_cds_df,
                            ggplot2::aes(
                                xmin = xstart_disp,
                                xmax = xend_disp
                            ),
                            ymin = y_all_min, ymax = y_all_max,
                            inherit.aes = FALSE,
                            fill  = pip_cds_color,
                            color = NA,
                            alpha = if (is_dark_theme) 0.50 else 0.32
                        )
                    }
                } +
                # Layer 5: UTR exon vertical bands across all tracks (theme-aware color)
                {
                    if (is.data.frame(pip_utr_df) && nrow(pip_utr_df) > 0L &&
                        all(c("xstart_clip", "xend_clip") %in% names(pip_utr_df))) {
                        ggplot2::geom_rect(
                            data = pip_utr_df,
                            ggplot2::aes(
                                xmin = xstart_disp,
                                xmax = xend_disp
                            ),
                            ymin = y_all_min, ymax = y_all_max,
                            inherit.aes = FALSE,
                            fill  = pip_utr_color,
                            color = NA,
                            alpha = if (is_dark_theme) 0.50 else 0.35
                        )
                    }
                } +
                # Layer 6: 50% / 100% guide lines — positions derived from pip_inset
                ggplot2::geom_segment(
                    data = query_rows,
                    ggplot2::aes(x = x_show_min, xend = x_show_max,
                                 y = y - pip_inset, yend = y - pip_inset),
                    inherit.aes = FALSE,
                    color     = if (is_dark_theme) "#3a6080" else "#D5D0C4",
                    linewidth = 0.2
                ) +
                ggplot2::geom_segment(
                    data = query_rows,
                    ggplot2::aes(x = x_show_min, xend = x_show_max,
                                 y = y + pip_inset, yend = y + pip_inset),
                    inherit.aes = FALSE,
                    color     = if (is_dark_theme) "#3a6080" else "#D5D0C4",
                    linewidth = 0.2
                ) +
                ggplot2::geom_text(
                    data = query_rows,
                    ggplot2::aes(x = x_show_max - 0.004 * x_show_span,
                                 y = y + pip_inset - 0.04, label = "100%"),
                    inherit.aes = FALSE,
                    color = axis_color, size = 2.5, hjust = 1, vjust = 1
                ) +
                ggplot2::geom_text(
                    data = query_rows,
                    ggplot2::aes(x = x_show_max - 0.004 * x_show_span,
                                 y = y - pip_inset + 0.04, label = "50%"),
                    inherit.aes = FALSE,
                    color = axis_color, size = 2.5, hjust = 1, vjust = 0
                ) +
                # Layer 7: identity segments (on top of everything).
                # When there are many visible segments the SVG would be too large
                # for smooth browser interaction — fall back to non-interactive
                # geom_segment which is ~5x lighter per element.
                {
                    if (is.data.frame(segments_visual_df) && nrow(segments_visual_df) > 0L) {
                        INTERACTIVE_SEGMENT_LIMIT <- 2500L
                        if (nrow(segments_visual_df) <= INTERACTIVE_SEGMENT_LIMIT) {
                            list(
                                ggplot2::geom_segment(
                                    data = segments_visual_df,
                                    ggplot2::aes(
                                        x    = ref_start_disp,
                                        xend = ref_end_disp,
                                        y    = y_pip,
                                        yend = y_pip,
                                        color = trace_col
                                    ),
                                    inherit.aes = FALSE,
                                    linewidth = 0.45,
                                    lineend   = "butt"
                                ),
                                {
                                    if (is.data.frame(segments_hover_df) && nrow(segments_hover_df) > 0L) {
                                        ggiraph::geom_rect_interactive(
                                            data = segments_hover_df,
                                            ggplot2::aes(
                                                xmin    = xmin,
                                                xmax    = xmax,
                                                ymin    = ymin,
                                                ymax    = ymax,
                                                tooltip = tooltip,
                                                data_id = data_id
                                            ),
                                            inherit.aes = FALSE,
                                            color = NA,
                                            fill = if (is_dark_theme) "#FFFFFF" else "#000000",
                                            alpha = 0.003
                                        )
                                    }
                                }
                            )
                        } else {
                            # Lightweight mode: plain SVG lines — no per-segment JS handlers.
                            # Much smaller SVG, faster browser rendering.
                            ggplot2::geom_segment(
                                data = segments_visual_df,
                                ggplot2::aes(
                                    x    = ref_start_disp,
                                    xend = ref_end_disp,
                                    y    = y_pip,
                                    yend = y_pip,
                                    color = trace_col
                                ),
                                inherit.aes = FALSE,
                                linewidth = 0.45,
                                lineend   = "butt"
                            )
                        }
                    }
                } +
                ggplot2::scale_y_continuous(
                    breaks = query_rows$y,
                    labels = query_rows$org_label,
                    expand = ggplot2::expansion(mult = c(0.05, 0.003))
                ) +
                ggplot2::scale_x_continuous(
                    limits = {
                        x_range <- range(display_breaks_df$disp, na.rm = TRUE)
                        x_pad <- max(diff(x_range) * 0.03, 1.2)
                        c(x_range[1], x_range[2] + x_pad)
                    },
                    breaks = display_breaks_df$disp,
                    labels = display_breaks_df$label,
                    expand = shared_x_expand
                ) +
                ggplot2::scale_color_identity() +
                ggplot2::labs(x = "Reference locus coordinate system", y = NULL) +
                ggplot2::theme_minimal(base_size = 12) +
                ggplot2::theme(
                    panel.background  = ggplot2::element_rect(fill = bg_color, color = NA),
                    plot.background   = ggplot2::element_rect(fill = bg_color, color = NA),
                    panel.grid        = ggplot2::element_blank(),
                    axis.text.y       = ggplot2::element_text(color = axis_color, size = 9.5, face = "bold.italic", hjust = 1, lineheight = 1.2, margin = ggplot2::margin(r = 4, unit = "pt")),
                    axis.text.x       = ggplot2::element_text(color = axis_color, size = 11),
                    axis.title.x      = ggplot2::element_text(color = axis_color, size = 12, face = "bold"),
                    axis.title.y      = ggplot2::element_blank(),
                    axis.ticks        = ggplot2::element_blank(),
                    plot.margin       = ggplot2::margin(t = -6, r = 0, b = 4, l = 0, unit = "pt")
                )

            if (!is.data.frame(segments_df) || nrow(segments_df) == 0L) {
                # Clamp label x to the display window so it never falls outside scale
                label_x <- max(x_show_min, min(x_show_max,
                    if (is.finite(ref_gene_center_disp)) ref_gene_center_disp
                    else mean(range(display_breaks_df$disp, na.rm = TRUE))
                ))
                empty_label_txt <- if (is_running_multipip && !has_run_payload) {
                    "Running local alignments...\nSegments will appear here when ready"
                } else if (!has_run_payload) {
                    "Reference scaffold ready\nRun local alignments to draw conserved segments"
                } else {
                    "No gap-free segments visible with current filters"
                }
                p <- p + ggplot2::annotate(
                    "label",
                    x     = label_x,
                    y     = mean(query_rows$y),
                    label = empty_label_txt,
                    color = axis_color,
                    fill  = if (is_dark_theme) "#1a3047" else "#FFFFFF"
                )
            }
        }

        # --- Combine gene panel + identity tracks via patchwork ---
        gene_h   <- 0.84   # slightly taller reference panel without reopening the inter-panel gap
        tracks_h <- max(2.0, 1.2 + n_query * 0.95)
        combined <- p_gene / p +
            patchwork::plot_layout(heights = c(gene_h, tracks_h)) &
            ggplot2::theme(
                plot.background  = ggplot2::element_rect(fill = bg_color, color = NA),
                panel.background = ggplot2::element_rect(fill = bg_color, color = NA),
                plot.margin      = ggplot2::margin(t = 0, r = 0, b = 0, l = 0, unit = "pt")
            )

        multipip_segment_hover_n <- if (is.data.frame(segments_hover_df)) as.integer(nrow(segments_hover_df)) else 0L
        send_girafe_diag_expected(
            "ortho_multipip_plot_out",
            expected = list(
                render_mode = "multipip",
                segment_visual = if (is.data.frame(segments_visual_df)) as.integer(nrow(segments_visual_df)) else 0L,
                segment_hover = multipip_segment_hover_n,
                interactive_total = multipip_segment_hover_n
            ),
            meta = list(
                guardrail_triggered = isTRUE(scene$guardrail_triggered),
                raw_segment_total = as.integer(scene$raw_segment_total %||% 0L),
                visible_segment_total = as.integer(scene$visible_segment_total %||% 0L)
            )
        )
        safe_girafe(
            ggobj      = combined,
            width_svg  = 14,
            height_svg = gene_h + tracks_h,
            transport_label = "ortho_multipip",
            options = list(
                ggiraph::opts_hover(css = ""),
                ggiraph::opts_selection(type = "none"),
                ggiraph::opts_tooltip(
                    css = analytics_tooltip_css,
                    use_fill = FALSE,
                    placement = "auto",
                    zindex = 999999,
                    delay_mouseover = 60,
                    delay_mouseout = 500
                ),
                ggiraph::opts_toolbar(hidden = c("selection", "zoom", "misc")),
                ggiraph::opts_sizing(rescale = TRUE)
            )
        )
    }), list(
        input$ortho_visual_mode,
        input$app_theme,
        input$colorblind_mode,
        input$ortho_multipip_reference_track,
        input$ortho_multipip_span,
        input$ortho_multipip_track_order,
        input$ortho_multipip_min_identity,
        input$ortho_multipip_min_segment_bp,
        multipipLocalAlignmentRunStampOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_multipip_plot_out", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

    output$ortho_multipip_footer <- bindEvent(renderUI({
        current_mode <- tolower(trimws(as.character(input$ortho_visual_mode %||% "compact")))
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        req(identical(current_mode, "pip_multipip"), cancelOutput = TRUE)
        scene <- multipipProcessedSceneOrthologous()
        is_running_multipip <- isTRUE(multipipLocalAlignmentRunningOrthologous())
        run_map <- multipipLocalAlignmentRunsOrthologous() %||% list()
        has_run_payload <- length(run_map) > 0L
        ids <- as.character(scene$ids %||% character(0))
        if (length(ids) == 0L) {
            return(NULL)
        }
        if (!has_run_payload && !is_running_multipip) {
            ref_ctx <- scene$ref_ctx %||% NULL
            ref_label <- if (!is.null(ref_ctx)) {
                paste0(
                    trimws(as.character(ref_ctx$organism_name %||% "")),
                    " | ",
                    trimws(as.character(ref_ctx$title %||% ref_ctx$plot_id %||% ""))
                )
            } else {
                "Auto"
            }
            ref_window_bp <- if (!is.null(ref_ctx)) {
                start_i <- suppressWarnings(as.integer(ref_ctx$window_start %||% NA_integer_))
                end_i <- suppressWarnings(as.integer(ref_ctx$window_end %||% NA_integer_))
                if (is.finite(start_i) && is.finite(end_i) && end_i >= start_i) end_i - start_i + 1L else NA_integer_
            } else {
                NA_integer_
            }
            flank_bp <- parse_locus_window_flank_bp(input$ortho_multipip_span %||% "gene", default_bp = 0L)
            return(
                tags$div(
                    style = "display:flex; flex-wrap:wrap; gap:8px 10px; align-items:center;",
                    tags$span(style = "font-weight:700;", "MultiPIP-style scaffold ready"),
                    tags$span(style = "opacity:0.82;", paste0("Reference: ", ref_label)),
                    if (is.finite(ref_window_bp)) tags$span(style = "opacity:0.82;", paste0("Aligned reference bp: ", format(as.integer(ref_window_bp), big.mark = ","))) else NULL,
                    tags$span(style = "opacity:0.82;", if (flank_bp <= 0L) "Scope: Gene body only (0 bp flanks)" else paste0("Scope: Gene + ", format(as.integer(flank_bp), big.mark = ","), " bp flanks")),
                    tags$span(style = "opacity:0.82;", paste0("Organisms shown: ", max(length(ids) - 1L, 0L), " query + 1 reference")),
                    tags$span(style = "opacity:0.82;", "The coordinate system and reference structure are ready."),
                    tags$span(style = "opacity:0.82;", "Run local alignments to draw the conserved segments.")
                )
            )
        }
        if (is_running_multipip &&
            as.integer(scene$raw_segment_total %||% 0L) == 0L &&
            as.integer(scene$visible_segment_total %||% 0L) == 0L) {
            return(
                tags$div(
                    style = "display:flex; flex-wrap:wrap; gap:8px 14px; align-items:center; margin-bottom:8px;",
                    tags$strong("Backend status"),
                    tags$span("MultiPIP local alignments are running in background."),
                    tags$span("The view will refresh when the final segments are ready.")
                )
            )
        }
        ref_ctx <- scene$ref_ctx %||% NULL
        ref_label <- if (!is.null(ref_ctx)) {
            paste0(
                trimws(as.character(ref_ctx$organism_name %||% "")),
                " | ",
                trimws(as.character(ref_ctx$title %||% ref_ctx$plot_id %||% ""))
            )
        } else {
            "Auto"
        }
        min_identity <- as.numeric(scene$min_identity %||% 70)
        min_segment_bp <- as.integer(scene$min_segment_bp %||% 25L)
        raw_segment_total  <- as.integer(scene$raw_segment_total  %||% 0L)
        vis_n              <- as.integer(scene$visible_segment_total %||% 0L)
        ref_window_bp <- if (!is.null(ref_ctx)) {
            start_i <- suppressWarnings(as.integer(ref_ctx$window_start %||% NA_integer_))
            end_i <- suppressWarnings(as.integer(ref_ctx$window_end %||% NA_integer_))
            if (is.finite(start_i) && is.finite(end_i) && end_i >= start_i) end_i - start_i + 1L else NA_integer_
        } else {
            NA_integer_
        }
        flank_bp <- parse_locus_window_flank_bp(input$ortho_multipip_span %||% "gene", default_bp = 0L)
        INTERACTIVE_LIMIT  <- 2500L
        is_lightweight     <- vis_n > INTERACTIVE_LIMIT
        assess <- multipipReferenceAssessmentOrthologous() %||% list()
        tags$div(
            style = "display:flex; flex-wrap:wrap; gap:8px 10px; align-items:center;",
            tags$span(style = "font-weight:700;", "MultiPIP-style local conservation ready"),
            tags$span(style = "opacity:0.82;", paste0("Reference: ", ref_label)),
            tags$span(style = "opacity:0.82;", paste0("Reference state: ", if (identical(trimws(as.character(assess$status %||% "")), "evaluated")) "Evaluated from current run" else if (identical(trimws(as.character(assess$status %||% "")), "unavailable")) "Evaluation unavailable" else "Pending run")),
            if (is.finite(ref_window_bp)) tags$span(style = "opacity:0.82;", paste0("Aligned reference bp: ", format(as.integer(ref_window_bp), big.mark = ","))) else NULL,
            tags$span(style = "opacity:0.82;", if (flank_bp <= 0L) "Scope: Gene body only (0 bp flanks)" else paste0("Scope: Gene + ", format(as.integer(flank_bp), big.mark = ","), " bp flanks")),
            tags$span(style = "opacity:0.82;", paste0("Organisms shown: ", max(length(ids) - 1L, 0L), " query + 1 reference")),
            tags$span(style = "opacity:0.82;", paste0(
                "Segments: ",
                format(raw_segment_total, big.mark = ","), " raw \u2192 ",
                format(vis_n, big.mark = ","), " rendered",
                if (isTRUE(scene$guardrail_triggered)) " (spatially sampled)" else ""
            )),
            tags$span(style = "opacity:0.82;", paste0("Min identity: ", as.integer(round(min_identity)), "% | Min length: ", min_segment_bp, " bp")),
            if (is_lightweight) tags$span(
                style = "opacity:0.82; color:#8B6914;",
                paste0("\u26A1 High-density mode (\u003e", INTERACTIVE_LIMIT, " segments): hover tooltips on segments are disabled for performance. Use identity/length filters to reduce density.")
            ) else NULL,
            if (isTRUE(scene$guardrail_triggered) && !is_lightweight) tags$span(
                style = "opacity:0.72; color:#6E8FA8;",
                scene$guardrail_message
            ) else NULL
        )
    }), list(
        input$ortho_visual_mode,
        input$ortho_multipip_reference_track,
        input$ortho_multipip_span,
        input$ortho_multipip_track_order,
        input$ortho_multipip_min_identity,
        input$ortho_multipip_min_segment_bp,
        input$ortho_multipip_run_alignments,
        multipipLocalAlignmentRunStampOrthologous()
    ), ignoreInit = FALSE)
    outputOptions(output, "ortho_multipip_footer", suspendWhenHidden = isTRUE(should_suspend_hidden_ortho_outputs()))

    # Download combined FASTA of exonic regions for all orthologs
    output$download_aligned_seq <- downloadHandler(
        filename = function() {
            paste0("aligned_exonic_sequences_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".fasta")
        },
        content = function(file) {
            ids <- as.character(alignedOrderedPlotIdsOrthologous() %||% character(0))
            if (length(ids) == 0) {
                return(NULL)
            }

            fasta_lines <- character()
            seqs <- genSequencesOrthologous()
            seqs_updated <- FALSE

            for (i in seq_along(ids)) {
                id_chr <- as.character(ids[i])
                seq_blob <- as.character(seqs[[id_chr]] %||% "")
                plot_data <- tryCatch(fileDataOrthologous()[[id_chr]], error = function(e) NULL)
                if (is.null(plot_data)) next

                ttl <- tryCatch(titlesOrthologous()[[id_chr]], error = function(e) "")
                org_info <- tryCatch(organismInfoOrthologous()[[id_chr]], error = function(e) NULL)
                org_name <- as.character(org_info$name %||% paste("Org", i))

                if (!nzchar(trimws(seq_blob)) ||
                    (exists("is_sequence_composition_blob", mode = "function") && isTRUE(is_sequence_composition_blob(seq_blob)))) {
                    genome_path <- tryCatch(genomePathsOrthologous()[[id_chr]], error = function(e) NULL)
                    seq_blob <- build_sequence_blob_from_plot(
                        plot_data = plot_data,
                        title_txt = ttl,
                        genome_path = genome_path
                    )
                    if (nzchar(trimws(seq_blob))) {
                        seqs[[id_chr]] <- seq_blob
                        seqs_updated <- TRUE
                    }
                }

                # Extract sequence using existing logic
                fasta_txt <- build_transcript_fasta_content(
                    seq_blob = seq_blob,
                    plot_data = plot_data,
                    title_txt = ttl,
                    fallback_id = paste0("transcript_", id_chr)
                )

                # Ensure organism name is in the header
                fasta_txt <- sub("^>([^\\|\\s]+)", paste0(">", gsub(" ", "_", org_name), "|\\1"), fasta_txt)
                fasta_lines <- c(fasta_lines, fasta_txt)
            }

            if (isTRUE(seqs_updated)) {
                genSequencesOrthologous(seqs)
            }
            writeLines(paste(fasta_lines, collapse = "\n\n"), file)
        },
        contentType = "text/plain"
    )

    output$download_pip_seq <- downloadHandler(
        filename = function() {
            paste0("lastz_locus_sequences_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".fasta")
        },
        content = function(file) {
            scene <- pipProcessedSceneOrthologous()
            ids <- as.character(scene$ids %||% character(0))
            if (length(ids) == 0L) {
                return(NULL)
            }
            ctx_map <- scene$ctx_map %||% list()
            ref_id <- trimws(as.character(scene$ref_id %||% ""))
            fasta_lines <- unlist(lapply(ids, function(pid) {
                ctx <- ctx_map[[pid]] %||% NULL
                if (is.null(ctx)) {
                    return(NULL)
                }
                role_label <- if (identical(pid, ref_id)) "reference" else "query"
                fasta_txt <- build_locus_window_fasta_content(
                    locus_ctx = ctx,
                    fallback_id = paste0("lastz_locus_", sanitize_fasta_filename_token(pid, "track")),
                    role_label = role_label
                )
                if (!nzchar(trimws(as.character(fasta_txt %||% "")))) {
                    return(NULL)
                }
                fasta_txt
            }), use.names = FALSE)
            if (length(fasta_lines) == 0L) {
                return(NULL)
            }
            writeLines(paste(fasta_lines, collapse = "\n\n"), file)
        },
        contentType = "text/plain"
    )

