    observeEvent(input$plot_close_request, {
        req(input$plot_close_request)
        id_txt <- as.character(input$plot_close_request$id)
        panel <- as.character(input$plot_close_request$panel)

        if (!nzchar(id_txt)) {
            return(invisible(NULL))
        }

        if (!isTRUE(deletion_confirmation_enabled())) {
            if (panel == "homologous") remove_homologous_plot(id_txt, announce = TRUE)
            if (panel == "orthologous") remove_orthologous_plot(id_txt, announce = TRUE)
            return(invisible(NULL))
        }

        pendingPlotDeletePanel(panel)
        pendingPlotDeleteId(id_txt)
        plot_label <- get_plot_delete_title(panel, id_txt)

        showModal(
            modalDialog(
                title = "Delete Visualization",
                tags$p("Are you sure you want to delete this visualization?"),
                tags$p(tags$strong(plot_label)),
                tags$p("This action cannot be undone."),
                easyClose = TRUE,
                footer = tagList(
                    modalButton("Cancel"),
                    actionButton(
                        inputId = "confirm_delete_plot_btn",
                        label = "Delete visualization",
                        icon = icon("trash"),
                        class = "btn btn-danger"
                    )
                )
            )
        )
    })

    observeEvent(input$confirm_delete_plot_btn,
        {
            removeModal()
            panel <- as.character(pendingPlotDeletePanel() %||% "")
            id_txt <- as.character(pendingPlotDeleteId() %||% "")
            pendingPlotDeletePanel("")
            pendingPlotDeleteId("")

            if (!nzchar(panel) || !nzchar(id_txt)) {
                emit_popup_status("Visualizations", "No visualization was selected for deletion.", tone = "warning", clear = TRUE)
                return(invisible(NULL))
            }

            if (identical(panel, "homologous")) {
                ok <- isTRUE(remove_homologous_plot(id_txt, announce = TRUE))
            } else if (identical(panel, "orthologous")) {
                cancel_orthologous_background_rescue("delete_visualization")
                ok <- isTRUE(remove_orthologous_plot(id_txt, announce = TRUE))
            } else {
                ok <- FALSE
            }
            if (!ok) {
                emit_popup_status("Visualizations", "Could not delete the selected visualization.", tone = "error", clear = TRUE)
            }
        },
        ignoreInit = TRUE
    )

    canonical_gene_group_key <- function(query_gene = "", matched_gene_name = "", matched_gene_id = "", title_gene = "") {
        id_txt <- trimws(as.character(matched_gene_id %||% ""))
        query_txt <- trimws(as.character(query_gene %||% ""))
        name_txt <- trimws(as.character(matched_gene_name %||% ""))
        title_txt <- trimws(as.character(title_gene %||% ""))
        if (!nzchar(name_txt)) name_txt <- title_txt
        if (!nzchar(query_txt)) query_txt <- name_txt

        if (nzchar(id_txt) && isTRUE(is_known_gene_stable_id(id_txt))) {
            id_comp <- normalize_gene_compact(id_txt)
            if (nzchar(id_comp)) {
                return(paste0("id:", id_comp))
            }
        }

        q_alpha <- extract_gene_query_alpha_core(query_txt)
        q_digit <- extract_gene_query_digit_core(query_txt)
        if (nzchar(q_alpha) && nzchar(q_digit)) {
            return(paste0("qd:", q_alpha, ":", q_digit))
        }

        q_comp <- normalize_gene_compact(query_txt)
        if (nzchar(q_comp)) {
            return(paste0("q:", q_comp))
        }

        n_alpha <- extract_gene_query_alpha_core(name_txt)
        n_digit <- extract_gene_query_digit_core(name_txt)
        if (nzchar(n_alpha) && nzchar(n_digit)) {
            return(paste0("nd:", n_alpha, ":", n_digit))
        }

        n_comp <- normalize_gene_compact(name_txt)
        if (nzchar(n_comp)) {
            return(paste0("n:", n_comp))
        }

        "gene:unknown"
    }

    header_mode_onclick <- function(input_id, value) {
        sprintf(
            "if(window.Shiny){Shiny.setInputValue('%s','%s',{priority:'event'});}",
            as.character(input_id %||% ""),
            as.character(value %||% "")
        )
    }

    header_mode_button <- function(input_id, value, label, detail, icon_name, active = FALSE, disabled = FALSE, tone = "visualize", title = "") {
        cls <- paste(
            "summary-display-mode-button",
            paste0("summary-display-mode-button--", tone),
            if (isTRUE(active)) "is-active" else "",
            if (isTRUE(disabled)) "is-disabled" else ""
        )
        attrs <- list(
            type = "button",
            class = cls,
            title = as.character(title %||% ""),
            `aria-pressed` = if (isTRUE(active)) "true" else "false"
        )
        if (isTRUE(disabled)) {
            attrs$disabled <- NA
            attrs$`aria-disabled` <- "true"
        } else {
            attrs$onclick <- header_mode_onclick(input_id, value)
        }
        do.call(
            tags$button,
            c(
                attrs,
                list(
                    icon(icon_name),
                    span(class = "summary-display-mode-copy", span(class = "summary-display-mode-label", label), span(class = "summary-display-mode-detail", detail))
                )
            )
        )
    }

    header_submode_button <- function(input_id, value, label, active = FALSE) {
        tags$button(
            type = "button",
            class = paste("summary-display-submode-button", if (isTRUE(active)) "is-active" else ""),
            `aria-pressed` = if (isTRUE(active)) "true" else "false",
            onclick = header_mode_onclick(input_id, value),
            label
        )
    }

    header_genomic_ruler_button <- function() {
        tags$button(
            type = "button",
            class = "summary-display-submode-button summary-genomic-ruler-toggle is-active",
            `data-genomic-ruler-toggle` = "true",
            `aria-pressed` = "true",
            `aria-label` = "Hide genomic context scale",
            title = "Show or hide genomic coordinates and compressed neighbor-distance context",
            icon("ruler-horizontal"),
            span(class = "summary-genomic-ruler-toggle-label", "Hide scale")
        )
    }

    header_genomic_context_button <- function(kind, label, icon_name) {
        kind_txt <- tolower(trimws(as.character(kind %||% "")))
        short_label <- if (identical(kind_txt, "overlaps")) "overlaps" else "neighbors"
        tags$button(
            type = "button",
            class = paste(
                "summary-display-submode-button summary-genomic-context-toggle",
                paste0("summary-genomic-context-toggle--", kind_txt),
                "is-active"
            ),
            `data-genomic-context-toggle` = kind_txt,
            `aria-pressed` = "true",
            `aria-label` = if (identical(kind_txt, "overlaps")) {
                "Hide overlapping genes"
            } else {
                "Hide neighboring genes"
            },
            title = paste("Show or hide", tolower(label), "on gene cards"),
            icon(icon_name),
            span(class = "summary-genomic-context-toggle-label", paste("Hide", short_label))
        )
    }

    build_header_mode_switch <- function(scope, current_mode, current_orientation = "genomic", align_available = TRUE, align_disabled_title = "", align_choices = NULL) {
        scope <- as.character(scope %||% "homo")
        input_id <- paste0(scope, "_header_mode_pick")
        orientation_input_id <- paste0(scope, "_orientation_pick")
        current_mode <- tolower(trimws(as.character(current_mode %||% "compact")))
        current_orientation <- tolower(trimws(as.character(current_orientation %||% "genomic")))
        if (!current_orientation %in% c("genomic", "transcription")) current_orientation <- "genomic"
        if (identical(current_mode, "pip")) current_mode <- "pip_blocks"
        alignment_modes <- c("aligned", "pip_blocks", "pip_multipip")
        is_alignment <- current_mode %in% alignment_modes
        if (!current_mode %in% c("compact", "detailed", alignment_modes)) {
            current_mode <- "compact"
            is_alignment <- FALSE
        }

        align_detail <- if (identical(scope, "ortho")) {
            "Compare across organisms"
        } else {
            "Compare transcripts"
        }
        align_title <- if (isTRUE(align_available)) {
            "Switch to alignment mode"
        } else {
            as.character(align_disabled_title %||% "")
        }
        align_value <- if (identical(scope, "ortho")) "aligned" else "aligned"

        subbar <- if (is_alignment) {
            if (is.null(align_choices) || length(align_choices) == 0L) {
                div(
                    class = "summary-display-mode-subbar",
                    span(class = "summary-display-submode-label", "Alignment"),
                    span(class = "summary-display-mode-note", "Transcript-level comparison is active")
                )
            } else {
                div(
                    class = "summary-display-mode-subbar",
                    span(class = "summary-display-submode-label", "Alignment view"),
                    tagList(lapply(names(align_choices), function(lbl) {
                        val <- as.character(align_choices[[lbl]] %||% "")
                        header_submode_button(input_id, val, lbl, active = identical(current_mode, val))
                    }))
                )
            }
        } else {
            div(
                class = "summary-display-mode-subbar summary-display-detail-subbar",
                span(
                    class = "summary-display-submode-label summary-display-detail-label",
                    span("Visual"),
                    span("Detail")
                ),
                header_submode_button(input_id, "compact", "Compact", active = identical(current_mode, "compact")),
                header_submode_button(input_id, "detailed", "Detailed", active = identical(current_mode, "detailed"))
            )
        }
        context_subbar <- if (!is_alignment) {
            div(
                class = "summary-display-mode-subbar summary-display-context-subbar",
                header_genomic_context_button("neighbors", "Neighbors", "location-arrow"),
                header_genomic_context_button("overlaps", "Overlaps", "layer-group"),
                header_genomic_ruler_button()
            )
        } else {
            NULL
        }
        orientation_note <- if (identical(current_orientation, "transcription")) {
            "All genes face 5\u2032\u21923\u2032; minus-strand loci are mirrored"
        } else {
            "Native genomic coordinates"
        }
        orientation_subbar <- if (!is_alignment) {
            div(
                class = "summary-display-mode-subbar summary-display-orientation-subbar",
                title = orientation_note,
                span(class = "summary-display-submode-label", "Direction"),
                header_submode_button(
                    orientation_input_id,
                    "genomic",
                    "Genomic",
                    active = identical(current_orientation, "genomic")
                ),
                header_submode_button(
                    orientation_input_id,
                    "transcription",
                    "5\u2032\u21923\u2032",
                    active = identical(current_orientation, "transcription")
                ),
                span(
                    class = "summary-display-orientation-note",
                    `aria-live` = "polite",
                    orientation_note
                )
            )
        } else {
            NULL
        }
        left_controls <- if (!is_alignment) {
            div(
                class = "summary-display-side summary-display-side--left",
                context_subbar
            )
        } else {
            NULL
        }
        right_controls <- div(
            class = "summary-display-side summary-display-side--right",
            subbar,
            orientation_subbar
        )

        div(
            class = "summary-display-mode-control",
            left_controls,
            div(
                class = "summary-display-mode-main",
                header_mode_button(
                    input_id = input_id,
                    value = "visualize",
                    label = "Visualize mode",
                    detail = "Explore gene models",
                    icon_name = "eye",
                    active = !is_alignment,
                    tone = "visualize",
                    title = "Switch to visualization mode"
                ),
                header_mode_button(
                    input_id = input_id,
                    value = align_value,
                    label = "Alignment mode",
                    detail = align_detail,
                    icon_name = "project-diagram",
                    active = is_alignment,
                    disabled = !isTRUE(align_available),
                    tone = "align",
                    title = align_title
                )
            ),
            right_controls
        )
    }

    build_summary_context_header <- function(search_mode_label, ids, titles_map, organism_map, gene_meta_map = list(), mode_control = NULL, draft_organisms = NULL, draft_genes = NULL, organism_status = NULL) {
        id_vec <- as.character(ids %||% integer(0))
        id_vec <- id_vec[nzchar(id_vec)]
        if (length(id_vec) > 0L) {
            id_vec <- Filter(function(pid) {
                if (endsWith(as.character(pid), "_c")) {
                    return(FALSE)
                }
                meta <- tryCatch(gene_meta_map[[pid]], error = function(e) NULL)
                !isTRUE(meta$is_canonical_copy) && !identical(meta$is_canonical, FALSE)
            }, id_vec)
            id_vec <- as.character(unique(id_vec))
        }
        resolve_summary_org_registry <- function(org_name = "", org_info = NULL) {
            empty <- list(species_id = "", aliases = "")
            org_name <- trimws(as.character(org_name %||% ""))
            org_info <- org_info %||% list()
            sid <- trimws(as.character(org_info$species_id %||% org_info$preloaded_id %||% ""))
            aliases <- trimws(as.character(org_info$aliases %||% org_info$synonyms %||% ""))
            reg <- tryCatch(preloadedRegistry(), error = function(e) data.frame())
            if (!is.null(reg) && is.data.frame(reg) && nrow(reg) > 0L) {
                row <- NULL
                if (nzchar(sid) && "species_id" %in% names(reg)) {
                    hit <- which(as.character(reg$species_id) == sid)[1]
                    if (is.finite(hit)) row <- reg[hit, , drop = FALSE]
                }
                if (is.null(row) && nzchar(org_name) && "organism" %in% names(reg)) {
                    hit <- which(tolower(trimws(as.character(reg$organism))) == tolower(org_name))[1]
                    if (is.finite(hit)) row <- reg[hit, , drop = FALSE]
                }
                if (!is.null(row) && nrow(row) > 0L) {
                    if (!nzchar(sid)) sid <- trimws(as.character(row$species_id[1] %||% ""))
                    if (!nzchar(aliases)) aliases <- trimws(as.character(row$synonyms[1] %||% ""))
                }
            }
            empty$species_id <- sid
            empty$aliases <- aliases
            empty
        }

        build_org_row_key <- function(name, species_id = "") {
            sid <- tolower(trimws(as.character(species_id %||% "")))
            nm <- tolower(trimws(as.character(name %||% "")))
            if (nzchar(sid)) paste0("sid:", sid) else paste0("name:", nm)
        }
        org_signature <- function(df) {
            if (is.null(df) || !is.data.frame(df) || nrow(df) == 0L) {
                return(character(0))
            }
            name_col <- if ("name" %in% names(df)) {
                df$name
            } else if ("organism" %in% names(df)) {
                df$organism
            } else {
                rep("", nrow(df))
            }
            species_col <- if ("species_id" %in% names(df)) df$species_id else rep("", nrow(df))
            sort(unique(vapply(seq_len(nrow(df)), function(i) {
                build_org_row_key(name_col[i], species_col[i])
            }, character(1))))
        }

        draft_df <- draft_organisms
        has_live_organism_context <- !is.null(draft_df) && is.data.frame(draft_df)
        live_org_signature <- org_signature(draft_df)

        status_df <- organism_status
        use_status_context <- !is.null(status_df) && is.data.frame(status_df) && nrow(status_df) > 0L
        if (isTRUE(use_status_context) && isTRUE(has_live_organism_context)) {
            use_status_context <- identical(org_signature(status_df), live_org_signature)
        }

        if (isTRUE(use_status_context)) {
            org_rows <- lapply(seq_len(nrow(status_df)), function(i) {
                org_name <- trimws(as.character(status_df$name[i] %||% ""))
                org_icon <- trimws(as.character(status_df$icon[i] %||% "/icons/DNA.ico"))
                if (!nzchar(org_name)) {
                    return(NULL)
                }
                data.frame(
                    key = as.character(status_df$key[i] %||% paste(tolower(org_name), org_icon, sep = "|")),
                    name = org_name,
                    icon = if (nzchar(org_icon)) org_icon else "/icons/DNA.ico",
                    species_id = as.character(status_df$species_id[i] %||% ""),
                    aliases = as.character(status_df$aliases[i] %||% ""),
                    status = as.character(status_df$status[i] %||% "pending"),
                    stringsAsFactors = FALSE
                )
            })
        } else if (isTRUE(has_live_organism_context)) {
            if (nrow(draft_df) > 0L) {
                org_rows <- lapply(seq_len(nrow(draft_df)), function(i) {
                    org_name <- trimws(as.character(draft_df$name[i] %||% ""))
                    org_icon <- trimws(as.character(draft_df$icon[i] %||% "/icons/DNA.ico"))
                    if (!nzchar(org_name)) {
                        return(NULL)
                    }
                    data.frame(
                        key = build_org_row_key(org_name, draft_df$species_id[i] %||% ""),
                        name = org_name,
                        icon = if (nzchar(org_icon)) org_icon else "/icons/DNA.ico",
                        species_id = as.character(draft_df$species_id[i] %||% ""),
                        aliases = as.character(draft_df$aliases[i] %||% ""),
                        status = "pending",
                        stringsAsFactors = FALSE
                    )
                })
            } else {
                org_rows <- list()
            }
        } else if (length(id_vec) > 0L) {
            org_rows <- lapply(id_vec, function(pid) {
                org_info <- tryCatch(organism_map[[pid]], error = function(e) NULL)
                org_name <- trimws(as.character(org_info$name %||% ""))
                org_icon <- trimws(as.character(org_info$icon %||% "/icons/DNA.ico"))
                if (!nzchar(org_name)) {
                    return(NULL)
                }
                reg_info <- resolve_summary_org_registry(org_name, org_info)
                data.frame(
                    key = paste(tolower(org_name), org_icon, sep = "|"),
                    name = org_name,
                    icon = org_icon,
                    species_id = as.character(reg_info$species_id %||% ""),
                    aliases = as.character(reg_info$aliases %||% ""),
                    status = "found",
                    stringsAsFactors = FALSE
                )
            })
        } else {
            org_rows <- list()
        }
        org_rows <- Filter(Negate(is.null), org_rows)
        org_df <- if (length(org_rows) > 0) do.call(rbind,  org_rows) else NULL
        org_counts <- if (!is.null(org_df) && nrow(org_df) > 0) as.list(table(org_df$key)) else list()
        org_unique <- if (!is.null(org_df) && nrow(org_df) > 0) org_df[!duplicated(org_df$key), , drop = FALSE] else NULL
        n_org_unique <- if (!is.null(org_unique) && nrow(org_unique) > 0) as.integer(nrow(org_unique)) else 0L
        header_layout_class <- if (n_org_unique <= 2L) "summary-context-card-inline" else "summary-context-card-stacked"

        if (length(id_vec) > 0L) {
            title_gene_names <- vapply(id_vec, function(pid) {
                ttl <- tryCatch(titles_map[[pid]], error = function(e) "")
                g <- trimws(as.character(extract_title_field(ttl, "Gene") %||% ""))
                if (nzchar(g)) g else NA_character_
            }, character(1))
            gene_rows <- lapply(seq_along(id_vec), function(i) {
                pid <- id_vec[[i]]
                meta <- tryCatch(gene_meta_map[[pid]], error = function(e) NULL)
                query_gene <- trimws(as.character(meta$query_gene %||% ""))
                display_gene_name <- trimws(as.character(meta$display_gene_name %||% ""))
                matched_gene_name <- trimws(as.character(meta$matched_gene_name %||% ""))
                matched_gene_id <- trimws(as.character(meta$matched_gene_id %||% ""))
                title_gene <- as.character(title_gene_names[[i]] %||% "")
                display_gene <- if (nzchar(display_gene_name)) {
                    display_gene_name
                } else if (nzchar(query_gene)) {
                    query_gene
                } else if (nzchar(matched_gene_name)) {
                    matched_gene_name
                } else if (nzchar(title_gene)) {
                    title_gene
                } else {
                    "Gene"
                }
                data.frame(
                    key = canonical_gene_group_key(
                        query_gene = query_gene,
                        matched_gene_name = if (nzchar(display_gene_name)) display_gene_name else matched_gene_name,
                        matched_gene_id = matched_gene_id,
                        title_gene = title_gene
                    ),
                    label = display_gene,
                    priority = if (nzchar(display_gene_name)) 1L else if (nzchar(query_gene)) 2L else if (nzchar(matched_gene_name)) 3L else 4L,
                    stringsAsFactors = FALSE
                )
            })
        } else {
            draft_gene_vec <- unique(trimws(as.character(draft_genes %||% character(0))))
            draft_gene_vec <- draft_gene_vec[!is.na(draft_gene_vec) & nzchar(draft_gene_vec)]
            gene_rows <- lapply(seq_along(draft_gene_vec), function(i) {
                gene_txt <- as.character(draft_gene_vec[[i]] %||% "")
                data.frame(
                    key = canonical_gene_group_key(
                        query_gene = gene_txt,
                        matched_gene_name = gene_txt,
                        matched_gene_id = "",
                        title_gene = gene_txt
                    ),
                    label = gene_txt,
                    priority = as.integer(i),
                    stringsAsFactors = FALSE
                )
            })
        }
        gene_rows <- Filter(Negate(is.null), gene_rows)
        gene_df <- if (length(gene_rows) > 0) do.call(rbind,  gene_rows) else NULL
        if (!is.null(gene_df) && nrow(gene_df) > 0) {
            gene_df <- gene_df[order(gene_df$key, gene_df$priority, nchar(gene_df$label)), , drop = FALSE]
            gene_df <- gene_df[!duplicated(gene_df$key), , drop = FALSE]
        }
        is_cross_species_header <- grepl("Cross", as.character(search_mode_label %||% ""), ignore.case = TRUE)
        result_organism_keys <- unique(vapply(id_vec, function(pid) {
            org_info <- tryCatch(organism_map[[pid]], error = function(e) NULL)
            species_id <- tolower(trimws(as.character(org_info$species_id %||% org_info$preloaded_id %||% "")))
            organism_name <- tolower(trimws(as.character(org_info$name %||% "")))
            if (!nzchar(organism_name)) {
                ttl <- tryCatch(titles_map[[pid]], error = function(e) "")
                organism_name <- tolower(trimws(as.character(extract_title_field(ttl, "Organism") %||% "")))
            }
            if (nzchar(species_id)) {
                paste0("sid:", species_id)
            } else if (nzchar(organism_name)) {
                paste0("name:", organism_name)
            } else {
                ""
            }
        }, character(1)))
        result_organism_keys <- result_organism_keys[nzchar(result_organism_keys)]
        show_cross_species_scope_notice <- isTRUE(is_cross_species_header) &&
            length(result_organism_keys) >= 2L
        gene_hint <- if (is.null(gene_df) || nrow(gene_df) == 0) {
            if (isTRUE(is_cross_species_header)) "Gene: pending" else "Genes: pending"
        } else if (nrow(gene_df) == 1 || isTRUE(is_cross_species_header)) {
            paste0("Gene: ", as.character(gene_df$label[1] %||% "Gene"))
        } else {
            paste0("Genes: ", nrow(gene_df))
        }

        div(
            class = paste("summary-context-card", header_layout_class),
            div(
                class = "summary-context-title",
                span(class = "summary-context-kicker", "Search type"),
                span(class = "summary-context-mode", as.character(search_mode_label %||% "Search"))
            ),
            div(
                class = "summary-context-organisms",
                if (!is.null(org_unique) && nrow(org_unique) > 0) {
                    tagList(lapply(seq_len(nrow(org_unique)), function(i) {
                        key <- as.character(org_unique$key[i] %||% "")
                        cnt <- as.integer(org_counts[[key]] %||% 1L)
                        status <- tolower(trimws(as.character(org_unique$status[i] %||% "pending")))
                        status_label <- switch(
                            status,
                            found_local = "Found in local annotation",
                            found_alias = "Found via local alias index",
                            found_external = "Found after external database lookup",
                            found = "Found",
                            local_search = "Searching local annotation",
                            external_pending = "External lookup queued",
                            external_search = "Checking external databases",
                            not_found = "Gene not found in this organism",
                            "Pending lookup"
                        )
                        status_detail <- switch(
                            status,
                            found_local = "The gene was resolved from the local annotation.",
                            found_alias = "The gene was resolved from the local precomputed alias index.",
                            found_external = "The gene was recovered after checking external databases.",
                            found = "The gene is available in this organism.",
                            local_search = "CGeV is checking the local annotation first.",
                            external_pending = "No local match yet. External databases will be checked in the background.",
                            external_search = "No local match yet. External databases are being checked.",
                            not_found = "No local or external match was found for this organism.",
                            "Waiting for the lookup workflow to start."
                        )
                        div(
                            class = paste("summary-organism-pill", paste0("summary-organism-pill-", gsub("[^a-z0-9_-]+", "-", status))),
                            title = status_label,
                            `data-assembly-title` = "Assembly details",
                            `data-assembly-context` = if (grepl("Cross", as.character(search_mode_label %||% ""), ignore.case = TRUE)) "ortho" else "homo",
                            `data-assembly-species-ids` = as.character(org_unique$species_id[i] %||% ""),
                            `data-assembly-subtitle` = as.character(org_unique$name[i] %||% "Organism"),
                            `data-orgimg-organism` = as.character(org_unique$name[i] %||% ""),
                            `data-orgimg-aliases` = as.character(org_unique$aliases[i] %||% ""),
                            tags$img(
                                src = as.character(org_unique$icon[i] %||% "/icons/DNA.ico"),
                                alt = as.character(org_unique$name[i] %||% "Organism"),
                                class = "summary-organism-icon"
                            ),
                            span(class = "summary-organism-name", as.character(org_unique$name[i] %||% "Organism")),
                            if (cnt > 1L) span(class = "summary-organism-count", cnt) else NULL
                        )
                    }))
                } else {
                    span(class = "summary-context-empty", "Waiting for organisms")
                }
            ),
            div(
                class = "summary-context-actions",
                span(class = "summary-context-gene-hint", gene_hint),
                if (isTRUE(show_cross_species_scope_notice)) {
                    tags$details(
                        class = "summary-cross-species-scope",
                        tags$summary(
                            class = "summary-cross-species-scope-trigger",
                            title = "Learn what is included in Cross-Species results",
                            `aria-label` = "About Cross-Species result scope",
                            icon("info-circle"),
                            span(class = "summary-cross-species-scope-trigger-label", "About results")
                        ),
                        div(
                            class = "summary-cross-species-scope-panel",
                            role = "note",
                            div(
                                class = "summary-cross-species-scope-heading",
                                icon("info-circle"),
                                span("Comparison scope")
                            ),
                            tags$p(
                                if (isTRUE(cross_species_requires_verified_orthology())) {
                                    "Cross-Species first resolves local loci, then shows only a group supported by explicit one-to-one Ensembl Compara orthology in at least two selected organisms. Matching names or aliases alone are never treated as biological equivalence."
                                } else {
                                    "Cross-Species compares unambiguous loci matched independently in each organism's local annotation. By default, these local matches are not a claim of verified one-to-one orthology."
                                }
                            ),
                            tags$p(
                                class = "summary-cross-species-scope-takeaway",
                                tags$strong("There may be additional family members in each organism."),
                                " This view does not list members found only within one organism. Use Multi-Gene Search to explore a gene family within a single organism."
                            )
                        )
                    )
                } else {
                    NULL
                },
                if (length(id_vec) > 0L) {
                    actionButton(
                        inputId = if (isTRUE(is_cross_species_header)) {
                            "open_share_analysis_ortho"
                        } else {
                            "open_share_analysis_homo"
                        },
                        label = span("Share"),
                        icon = icon("share-nodes"),
                        class = "summary-share-analysis-btn",
                        title = "Share this analysis as a read-only interactive report"
                    )
                } else {
                    NULL
                },
                tags$button(
                    type = "button",
                    class = "app-notification-center-btn app-notification-center-toggle",
                    `aria-label` = "Open notification history",
                    `aria-expanded` = "false",
                    title = "Notification history",
                    icon("bell"),
                    span(class = "app-notification-center-badge", "0")
                )
            ),
            if (!is.null(mode_control)) {
                div(class = "summary-context-mode-slot", mode_control)
            } else {
                NULL
            }
        )
    }

    build_plot_summary_df <- function(ids, titles_map, organism_map, file_data_map, sequence_map, annotation_map = NULL, signature_map = NULL, gene_meta_map = NULL, cache_scope = "summary", perf_context = "SUMMARY") {
        summary_perf <- app_perf_new_run(sprintf("%s_BUILD", as.character(perf_context %||% "SUMMARY")))
        app_perf_mark(summary_perf, sprintf("start ids=%d", as.integer(length(ids %||% integer(0)))), as.character(perf_context %||% "SUMMARY"))
        if (length(ids) == 0) {
            app_perf_mark(summary_perf, "empty ids", as.character(perf_context %||% "SUMMARY"))
            return(NULL)
        }

        tx_level_types <- c(
            "mrna", "transcript", "lnc_rna", "trna", "rrna", "snorna", "snrna", "mirna",
            "ncrna", "primary_transcript", "pre_mirna", "guide_rna", "rnase_p_rna",
            "rnase_mrp_rna", "telomerase_rna", "antisense_rna", "srp_rna", "scarna",
            "vault_rna", "y_rna", "antisense_lncrna", "lncrna"
        )

        first_non_empty <- function(...) {
            vals <- unlist(list(...), use.names = FALSE)
            for (v in vals) {
                txt <- trimws(as.character(v %||% ""))
                if (!is.na(txt) && nzchar(txt)) {
                    return(txt)
                }
            }
            ""
        }

        parse_span <- function(starts, ends) {
            s <- suppressWarnings(as.numeric(starts))
            e <- suppressWarnings(as.numeric(ends))
            valid <- is.finite(s) & is.finite(e)
            if (!any(valid)) {
                return(c(start = NA_real_, end = NA_real_, len = NA_real_))
            }
            start_bp <- min(s[valid], na.rm = TRUE)
            end_bp <- max(e[valid], na.rm = TRUE)
            c(start = start_bp, end = end_bp, len = end_bp - start_bp + 1)
        }

        sum_bp <- function(starts, ends) {
            s <- suppressWarnings(as.numeric(starts))
            e <- suppressWarnings(as.numeric(ends))
            valid <- is.finite(s) & is.finite(e)
            if (!any(valid)) {
                return(NA_real_)
            }
            sum(pmax(0, e[valid] - s[valid] + 1), na.rm = TRUE)
        }

        pick_attr <- function(attrs, keys) {
            if (length(attrs) == 0 || length(keys) == 0) {
                return("")
            }
            for (k in keys) {
                val <- trimws(as.character(attrs[[k]][1] %||% ""))
                if (!is.na(val) && nzchar(val)) {
                    return(val)
                }
            }
            ""
        }

        row_cache_keys <- character(length(ids))

        build_row_for_id <- function(id) {
            id_chr <- as.character(id)
            titulo <- tryCatch(titles_map[[id_chr]], error = function(e) "")
            org_info <- tryCatch(organism_map[[id_chr]], error = function(e) NULL)
            plot_data <- tryCatch(file_data_map[[id_chr]], error = function(e) NULL)
            seq_blob <- tryCatch(sequence_map[[id_chr]], error = function(e) NULL)
            annotation_path <- tryCatch(annotation_map[[id_chr]], error = function(e) "")
            annotation_path <- as.character(annotation_path %||% "")
            gene_meta <- tryCatch(gene_meta_map[[id_chr]], error = function(e) NULL)

            org_name <- trimws(as.character(org_info$name %||% ""))
            org_icon <- first_non_empty(as.character(org_info$icon %||% ""), "/icons/DNA.ico")
            gene_name <- trimws(as.character(gene_meta$display_gene_name %||% gene_meta$matched_gene_name %||% extract_title_field(titulo, "Gene") %||% ""))
            tx_id <- trimws(as.character(extract_title_field(titulo, "Transcript") %||% ""))
            chr_id <- trimws(as.character(extract_title_field(titulo, "Chr") %||% ""))

            gene_biotype <- ""
            tx_biotype <- ""
            strand_val <- ""

            gene_start_bp <- NA_integer_
            gene_end_bp <- NA_integer_
            gene_len <- NA_real_

            tx_start_bp <- NA_integer_
            tx_end_bp <- NA_integer_
            tx_len <- NA_real_

            n_exons <- NA_integer_
            n_introns <- NA_integer_
            n_cds <- NA_integer_
            n_utr <- NA_integer_
            exonic_bp <- NA_real_
            cds_bp <- NA_real_
            cds_tx_pct <- NA_real_

            a_pct <- NA_real_
            t_pct <- NA_real_
            c_pct <- NA_real_
            g_pct <- NA_real_
            gc_pct <- NA_real_
            feature_rows <- NA_integer_

            upstream_gene <- "N/A"
            upstream_distance_bp <- NA_real_
            downstream_gene <- "N/A"
            downstream_distance_bp <- NA_real_

            gene_attr_txt <- ""
            target_chr_raw <- ""
            target_start_for_neighbors <- NA_real_
            target_end_for_neighbors <- NA_real_
            target_gene_id <- ""

            if (!is.null(plot_data) && nrow(plot_data) > 0) {
                types <- tolower(trimws(as.character(plot_data$V3 %||% rep("", nrow(plot_data)))))
                starts <- suppressWarnings(as.numeric(plot_data$V4))
                ends <- suppressWarnings(as.numeric(plot_data$V5))
                valid <- is.finite(starts) & is.finite(ends)

                feature_rows <- as.integer(nrow(plot_data))
                gene_rows <- which(types == "gene")
                tx_rows <- which(types %in% tx_level_types)
                exon_rows <- which(types == "exon")
                cds_rows <- which(types == "cds")
                utr_rows <- which(grepl("utr", types))

                n_exons <- as.integer(length(exon_rows))
                n_introns <- if (is.finite(n_exons) && n_exons > 0L) as.integer(max(0L, n_exons - 1L)) else NA_integer_
                n_cds <- as.integer(length(cds_rows))
                n_utr <- as.integer(length(utr_rows))

                gene_span <- if (length(gene_rows) > 0) parse_span(starts[gene_rows], ends[gene_rows]) else parse_span(starts, ends)
                tx_span <- if (length(tx_rows) > 0) parse_span(starts[tx_rows], ends[tx_rows]) else parse_span(starts, ends)

                if (is.finite(gene_span[["start"]])) gene_start_bp <- as.integer(round(gene_span[["start"]]))
                if (is.finite(gene_span[["end"]])) gene_end_bp <- as.integer(round(gene_span[["end"]]))
                gene_len <- as.numeric(gene_span[["len"]])

                if (is.finite(tx_span[["start"]])) tx_start_bp <- as.integer(round(tx_span[["start"]]))
                if (is.finite(tx_span[["end"]])) tx_end_bp <- as.integer(round(tx_span[["end"]]))
                tx_len <- as.numeric(transcript_span_length(tx_span))

                exonic_bp <- if (length(exon_rows) > 0) sum_bp(starts[exon_rows], ends[exon_rows]) else NA_real_
                cds_bp <- if (length(cds_rows) > 0) sum_bp(starts[cds_rows], ends[cds_rows]) else NA_real_
                if (is.finite(cds_bp) && is.finite(tx_len) && tx_len > 0) {
                    cds_tx_pct <- round(100 * as.numeric(cds_bp) / as.numeric(tx_len), 2)
                }

                if (length(gene_rows) > 0) {
                    strand_val <- as.character(plot_data$V7[gene_rows[1]] %||% "")
                } else if (length(tx_rows) > 0) {
                    strand_val <- as.character(plot_data$V7[tx_rows[1]] %||% "")
                } else if (any(valid)) {
                    strand_val <- as.character(plot_data$V7[which(valid)[1]] %||% "")
                }

                if (length(gene_rows) > 0) {
                    target_chr_raw <- as.character(plot_data$V1[gene_rows[1]] %||% "")
                } else if (length(tx_rows) > 0) {
                    target_chr_raw <- as.character(plot_data$V1[tx_rows[1]] %||% "")
                } else if (any(valid)) {
                    target_chr_raw <- as.character(plot_data$V1[which(valid)[1]] %||% "")
                }

                target_start_for_neighbors <- if (is.finite(gene_span[["start"]])) as.numeric(gene_span[["start"]]) else as.numeric(tx_span[["start"]])
                target_end_for_neighbors <- if (is.finite(gene_span[["end"]])) as.numeric(gene_span[["end"]]) else as.numeric(tx_span[["end"]])

                gene_attr_txt <- if (length(gene_rows) > 0) as.character(plot_data$V9[gene_rows[1]] %||% "") else ""
                tx_attr_txt <- if (length(tx_rows) > 0) as.character(plot_data$V9[tx_rows[1]] %||% "") else ""
                gene_attrs <- parse_gff_attributes(gene_attr_txt)
                tx_attrs <- parse_gff_attributes(tx_attr_txt)

                gene_biotype <- first_non_empty(
                    pick_attr(gene_attrs, c("gene_biotype", "biotype", "gbkey", "gene_type")),
                    pick_attr(tx_attrs, c("gene_biotype", "biotype", "gene_type"))
                )
                tx_biotype <- first_non_empty(
                    pick_attr(tx_attrs, c("transcript_biotype", "biotype", "transcript_type", "gbkey")),
                    gene_biotype
                )

                if (!nzchar(gene_name)) {
                    gene_name <- first_non_empty(
                        pick_attr(gene_attrs, c("gene_name", "gene", "name", "id", "locus_tag")),
                        extract_primary_gene_name(gene_attr_txt),
                        extract_primary_gene_id(gene_attr_txt)
                    )
                }

                if (!nzchar(tx_id)) {
                    tx_id <- first_non_empty(
                        pick_attr(tx_attrs, c("transcript_id", "id", "name", "transcript")),
                        pick_attr(gene_attrs, c("transcript_id", "id", "name"))
                    )
                }

                target_gene_id <- first_non_empty(
                    extract_primary_gene_id(gene_attr_txt),
                    pick_attr(gene_attrs, c("id", "gene_id", "locus_tag")),
                    gene_name
                )
            }

            if (!nzchar(gene_name)) gene_name <- "Gene"
            if (!nzchar(tx_id)) tx_id <- "N/A"
            if (!nzchar(chr_id)) chr_id <- "N/A"

            comp_blob <- if (exists("parse_sequence_composition_blob", mode = "function")) {
                tryCatch(parse_sequence_composition_blob(seq_blob), error = function(e) NULL)
            } else {
                NULL
            }
            if (!is.null(comp_blob) && is.list(comp_blob)) {
                counts <- suppressWarnings(as.numeric((comp_blob$counts %||% c(A = 0, T = 0, C = 0, G = 0))[c("A", "T", "C", "G")]))
                counts[!is.finite(counts)] <- 0
                names(counts) <- c("A", "T", "C", "G")
                total <- suppressWarnings(as.numeric(comp_blob$known_total %||% sum(counts, na.rm = TRUE)))
                if (is.finite(total) && total > 0) {
                    a_pct <- round(100 * counts[["A"]] / total, 2)
                    t_pct <- round(100 * counts[["T"]] / total, 2)
                    c_pct <- round(100 * counts[["C"]] / total, 2)
                    g_pct <- round(100 * counts[["G"]] / total, 2)
                    gc_pct <- round(100 * (counts[["G"]] + counts[["C"]]) / total, 2)
                }
            } else {
                seq_str <- tryCatch(extract_sequence_from_blob(seq_blob), error = function(e) "")
                if (!nzchar(seq_str) && !(exists("is_sequence_composition_blob", mode = "function") && isTRUE(is_sequence_composition_blob(seq_blob)))) {
                    seq_str <- toupper(gsub("[^ACGT]", "", as.character(seq_blob %||% "")))
                } else {
                    seq_str <- toupper(gsub("[^ACGT]", "", seq_str))
                }

                total <- nchar(seq_str)
                if (total > 0) {
                    a_count <- nchar(gsub("[^A]", "", seq_str))
                    t_count <- nchar(gsub("[^T]", "", seq_str))
                    c_count <- nchar(gsub("[^C]", "", seq_str))
                    g_count <- nchar(gsub("[^G]", "", seq_str))

                    a_pct <- round(100 * a_count / total, 2)
                    t_pct <- round(100 * t_count / total, 2)
                    c_pct <- round(100 * c_count / total, 2)
                    g_pct <- round(100 * g_count / total, 2)
                    gc_pct <- round(100 * (g_count + c_count) / total, 2)
                }
            }

            if (
                nzchar(annotation_path) &&
                    file.exists(annotation_path) &&
                    nzchar(target_chr_raw) &&
                    is.finite(target_start_for_neighbors) &&
                    is.finite(target_end_for_neighbors)
            ) {
                neighbor_target <- data.frame(
                    gene_id = as.character(target_gene_id %||% ""),
                    chr = as.character(target_chr_raw),
                    start = as.numeric(target_start_for_neighbors),
                    end = as.numeric(target_end_for_neighbors),
                    strand = as.character(strand_val %||% ""),
                    stringsAsFactors = FALSE
                )

                neighbor_ctx <- tryCatch(
                    get_neighbor_context_for_target(annotation_path, neighbor_target),
                    error = function(e) NULL
                )

                if (!is.null(neighbor_ctx)) {
                    upstream_gene <- first_non_empty(
                        neighbor_ctx$upstream$neighbor_label,
                        neighbor_ctx$upstream$neighbor_name,
                        neighbor_ctx$upstream$neighbor_id
                    )
                    downstream_gene <- first_non_empty(
                        neighbor_ctx$downstream$neighbor_label,
                        neighbor_ctx$downstream$neighbor_name,
                        neighbor_ctx$downstream$neighbor_id
                    )

                    if (!nzchar(upstream_gene)) upstream_gene <- "N/A"
                    if (!nzchar(downstream_gene)) downstream_gene <- "N/A"

                    upstream_distance_bp <- suppressWarnings(as.numeric(neighbor_ctx$upstream$dist_bp))
                    downstream_distance_bp <- suppressWarnings(as.numeric(neighbor_ctx$downstream$dist_bp))
                }
            }

            data.frame(
                Organism = org_name,
                Organism_Icon = org_icon,
                Gene = gene_name,
                Transcript = tx_id,
                Gene_Biotype = gene_biotype,
                Tx_Biotype = tx_biotype,
                Chromosome = chr_id,
                Strand = strand_val,
                Upstream_Gene = upstream_gene,
                Upstream_Distance_bp = if (is.finite(upstream_distance_bp)) as.integer(round(upstream_distance_bp)) else NA_integer_,
                Downstream_Gene = downstream_gene,
                Downstream_Distance_bp = if (is.finite(downstream_distance_bp)) as.integer(round(downstream_distance_bp)) else NA_integer_,
                Gene_Start_bp = if (is.finite(gene_start_bp)) as.integer(gene_start_bp) else NA_integer_,
                Gene_End_bp = if (is.finite(gene_end_bp)) as.integer(gene_end_bp) else NA_integer_,
                Gene_Length_bp = if (is.finite(gene_len)) as.integer(round(gene_len)) else NA_integer_,
                Transcript_Start_bp = if (is.finite(tx_start_bp)) as.integer(tx_start_bp) else NA_integer_,
                Transcript_End_bp = if (is.finite(tx_end_bp)) as.integer(tx_end_bp) else NA_integer_,
                Transcript_Length_bp = if (is.finite(tx_len)) as.integer(round(tx_len)) else NA_integer_,
                Exons = n_exons,
                Introns = n_introns,
                CDS = n_cds,
                UTR = n_utr,
                Exonic_bp = if (is.finite(exonic_bp)) as.integer(round(exonic_bp)) else NA_integer_,
                CDS_bp = if (is.finite(cds_bp)) as.integer(round(cds_bp)) else NA_integer_,
                CDS_to_Tx_pct = cds_tx_pct,
                A_pct = a_pct,
                T_pct = t_pct,
                C_pct = c_pct,
                G_pct = g_pct,
                GC_Content_pct = gc_pct,
                Feature_Rows = feature_rows,
                stringsAsFactors = FALSE
            )
        }

        rows <- lapply(seq_along(ids), function(idx) {
            id_chr <- as.character(ids[[idx]])
            plot_signature <- as.character(tryCatch(signature_map[[id_chr]], error = function(e) "") %||% "")
            titulo <- as.character(tryCatch(titles_map[[id_chr]], error = function(e) "") %||% "")
            org_info <- tryCatch(organism_map[[id_chr]], error = function(e) NULL)
            plot_data <- tryCatch(file_data_map[[id_chr]], error = function(e) NULL)
            seq_blob <- tryCatch(sequence_map[[id_chr]], error = function(e) NULL)
            annotation_path <- as.character(tryCatch(annotation_map[[id_chr]], error = function(e) "") %||% "")
            row_key <- paste(
                "summary-row-v1",
                as.character(cache_scope %||% "summary"),
                id_chr,
                if (nzchar(plot_signature)) paste0("sig:", plot_signature) else summary_plot_data_fingerprint(plot_data),
                paste0("ttl:", titulo),
                paste0(
                    "meta:",
                    trimws(as.character(tryCatch(gene_meta_map[[id_chr]]$display_gene_name, error = function(e) "") %||% "")),
                    "|",
                    trimws(as.character(tryCatch(gene_meta_map[[id_chr]]$matched_gene_name, error = function(e) "") %||% "")),
                    "|",
                    trimws(as.character(tryCatch(gene_meta_map[[id_chr]]$matched_gene_id, error = function(e) "") %||% ""))
                ),
                summary_organism_fingerprint(org_info),
                summary_annotation_fingerprint(annotation_path),
                summary_sequence_fingerprint(seq_blob),
                sep = "||"
            )
            row_cache_key <- stable_short_cache_key("summary-row-v1", row_key)
            row_cache_keys[[idx]] <<- row_cache_key
            if (exists(row_cache_key, envir = summaryRowCache, inherits = FALSE)) {
                return(get(row_cache_key, envir = summaryRowCache, inherits = FALSE))
            }
            row_df <- build_row_for_id(id_chr)
            assign(row_cache_key, row_df, envir = summaryRowCache)
            trim_cache_env(summaryRowCache, max_size = 1500L)
            row_df
        })

        rows <- Filter(Negate(is.null), rows)
        if (length(rows) == 0) {
            app_perf_mark(summary_perf, "no rows", as.character(perf_context %||% "SUMMARY"))
            return(NULL)
        }
        frame_key <- stable_short_cache_key(
            "summary-frame-v1",
            as.character(cache_scope %||% "summary"),
            paste(row_cache_keys[nzchar(row_cache_keys)], collapse = "|||")
        )
        if (exists(frame_key, envir = summaryFrameCache, inherits = FALSE)) {
            cached_df <- get(frame_key, envir = summaryFrameCache, inherits = FALSE)
            if (is.data.frame(cached_df)) {
                app_perf_mark(summary_perf, sprintf("frame cache hit rows=%d", as.integer(nrow(cached_df))), as.character(perf_context %||% "SUMMARY"))
                return(cached_df)
            }
        }
        out <- do.call(rbind,  rows)
        assign(frame_key, out, envir = summaryFrameCache)
        trim_cache_env(summaryFrameCache, max_size = 64L)
        app_perf_mark(summary_perf, sprintf("done rows=%d", as.integer(nrow(out %||% data.frame()))), as.character(perf_context %||% "SUMMARY"))
        out
    }

