            homoAnalyticsPhase2(TRUE)
        }
        if (tab_value %in% c("heatmap", "radar", "corr")) {
            homoAnalyticsPhase2(TRUE)
            homoAnalyticsPhase3(TRUE)
        }
        activate_analytics_tab("homo")
    }, ignoreInit = TRUE)

