    # ============================================================
    # PHASE 2 — Per-plot Charts Modal
    # ============================================================
    observeEvent(input$open_plot_charts,
        {
            evt <- input$open_plot_charts
            req(evt)
            pid <- as.character(evt$id %||% "")
            ctx <- normalize_plot_context(evt$context %||% "homo")
            if (!nzchar(pid)) {
                return(invisible(NULL))
            }

            modal_mode <- as.character(evt$mode %||% "gene")  # "gene" | "tx"

            selectedChartPlotId(pid)
            selectedChartContext(ctx)
            selectedChartModalMode(modal_mode)

            # Collect all plot IDs belonging to the same gene (for Tab 2 isoform analytics)
            iso_df <- tryCatch(get_chart_modal_isoforms_df(pid, ctx), error = function(e) data.frame())
            iso_ids <- if (!is.null(iso_df) && nrow(iso_df) > 0 && "source_plot" %in% names(iso_df)) {
                unique(as.character(iso_df$source_plot[nzchar(as.character(iso_df$source_plot %||% ""))]))
            } else {
                character(0)
            }
            selectedChartIsoformIds(iso_ids)

            # Retrieve gene / organism info for modal title
            if (ctx == "homo") {
                org_info <- tryCatch(organismInfoHomologous()[[pid]], error = function(e) NULL)
                titulo <- tryCatch(titlesHomologous()[[pid]], error = function(e) "")
                gene_meta <- tryCatch(plotGeneMetaHomologous()[[pid]], error = function(e) NULL)
            } else {
                org_info <- tryCatch(organismInfoOrthologous()[[pid]], error = function(e) NULL)
                titulo <- tryCatch(titlesOrthologous()[[pid]], error = function(e) "")
                gene_meta <- tryCatch(plotGeneMetaOrthologous()[[pid]], error = function(e) NULL)
            }
            gene_name <- trimws(as.character(gene_meta$display_gene_name %||% gene_meta$matched_gene_name %||% extract_title_field(titulo, "Gene") %||% "Gene"))
            org_name <- as.character(org_info$name %||% "")
            tx_name <- trimws(as.character(extract_title_field(titulo, "Transcript") %||% "N/A"))
            org_icon <- as.character(org_info$icon %||% "/icons/DNA.ico")
            modal_title <- tags$div(
                class = "chart-modal-title-main",
                tags$div(
                    class = "chart-modal-title-label",
                    icon("chart-pie"),
                    tags$div(
                        class = "chart-modal-title-copy",
                        tags$div(
                            class = "chart-modal-title-primary chart-modal-title-primary--inline",
                            tags$img(
                                src = if (nzchar(org_icon)) org_icon else "/icons/DNA.ico",
                                alt = if (nzchar(org_name)) org_name else "Organism",
                                class = "chart-modal-title-org-icon"
                            ),
                            tags$span(
                                class = "chart-modal-title-org chart-modal-title-org-inline",
                                if (nzchar(org_name)) org_name else "Organism"
                            ),
                            tags$span(class = "chart-modal-title-sep", "|"),
                            tags$span(
                                class = "chart-modal-title-gene",
                                if (nzchar(gene_name)) gene_name else "Gene"
                            ),
                            # In transcript mode also show the transcript name
                            if (modal_mode == "tx" && nzchar(tx_name) && tx_name != "N/A") {
                                tagList(
                                    tags$span(class = "chart-modal-title-sep", "|"),
                                    tags$span(class = "chart-modal-title-tx", tx_name)
                                )
                            }
                        )
                    )
                ),
                tags$div(
                    class = "chart-modal-title-actions",
                    tags$button(
                        type = "button",
                        class = "chart-modal-export-all-btn",
                        onclick = "exportChartModalSVGs();",
                        icon("file-zipper"),
                        "SVG ZIP"
                    ),
                    tags$button(
                        type = "button",
                        class = "chart-modal-close-btn",
                        onclick = "$(this).closest('.modal').modal('hide');",
                        HTML("&times;")
                    )
                )
            )

            # ── Build modal body depending on mode ─────────────────────────────
            # mode == "gene" → full 2-tab layout (Gene + Isoforms)
            # mode == "tx"   → flat 3-tab layout (Structure | Exon Map | Sequence)
            modal_body_content <- if (modal_mode == "tx") {
                # Transcript mode: flat sub-tabs only, no outer Gene/Isoforms tabs
                div(
                    class = "chart-modal-chart-wrap",
                    tabsetPanel(
                        id   = "chart_modal_tx_subtabs",
                        type = "pills",
                        tabPanel(
                            title = tagList(icon("sitemap"), " Structure"),
                            div(
                                class = "chart-modal-sub-wrap",
                                chart_export_svg_btn("chart_modal_structure", "chart_structure.svg"),
                                chart_info_tip("<strong>Transcript Structure</strong><br/>CDS, UTR, and intron base-pair composition for this transcript.<div class='ci-axes'><b>Bar sections:</b> proportional to bp<br/><b>X-axis:</b> Base pairs</div><div class='ci-tip'>Hover each section to see exact bp and percentage.</div>"),
                                ggiraph::girafeOutput("chart_modal_structure", height = "auto", width = "100%")
                            )
                        ),
                        tabPanel(
                            title = tagList(icon("map"), " Exon Map"),
                            div(
                                class = "chart-modal-sub-wrap",
                                chart_export_svg_btn("chart_modal_exons", "chart_exon_map.svg"),
                                chart_info_tip("<strong>Exon Map</strong><br/>Lollipop chart showing each exon's length ordered by genomic position.<div class='ci-axes'><b>X-axis:</b> Exon number (E1, E2, &hellip;)<br/><b>Y-axis:</b> Length (bp)</div><div class='ci-tip'>Taller stems = longer exons. Hover for exact position and length.</div>"),
                                ggiraph::girafeOutput("chart_modal_exons", height = "auto", width = "100%")
                            )
                        ),
                        tabPanel(
                            title = tagList(icon("arrows-left-right"), " Intron Map"),
                            div(
                                class = "chart-modal-sub-wrap",
                                chart_export_svg_btn("chart_modal_introns", "chart_intron_map.svg"),
                                chart_info_tip("<strong>Intron Map</strong><br/>Lollipop chart showing each intron's length inferred from gaps between consecutive annotated exons.<div class='ci-axes'><b>X-axis:</b> Intron number (I1, I2, &hellip;)<br/><b>Y-axis:</b> Length (bp)</div><div class='ci-tip'>Single-exon transcripts show a no-intron message.</div>"),
                                ggiraph::girafeOutput("chart_modal_introns", height = "auto", width = "100%")
                            )
                        ),
                        tabPanel(
                            title = tagList(icon("circle-half-stroke"), " Sequence"),
                            div(
                                class = "chart-modal-sub-wrap",
                                chart_export_svg_btn("chart_modal_seq", "chart_sequence_composition.svg"),
