    observeEvent(input$open_gene_function,
        {
            evt <- input$open_gene_function
            req(evt)
            pid <- as.character(evt$id %||% "")
            ctx <- normalize_plot_context(evt$context %||% "homo")
            if (!nzchar(pid)) {
                return(invisible(NULL))
            }

            d <- get_chart_plot_data(pid, ctx)
            if (is.null(d$file_data) || nrow(d$file_data) == 0) {
                return(invisible(NULL))
            }

            titulo <- if (identical(ctx, "ortho")) {
                as.character(tryCatch(titlesOrthologous()[[pid]], error = function(e) "") %||% "")
            } else {
                as.character(tryCatch(titlesHomologous()[[pid]], error = function(e) "") %||% "")
            }
            ann_path <- if (identical(ctx, "ortho")) {
                as.character(tryCatch(annotationPathsOrthologous()[[pid]], error = function(e) "") %||% "")
            } else {
                as.character(tryCatch(annotationPathsHomologous()[[pid]], error = function(e) "") %||% "")
            }
            gene_meta <- if (identical(ctx, "ortho")) {
                tryCatch(plotGeneMetaOrthologous()[[pid]], error = function(e) NULL)
            } else {
                tryCatch(plotGeneMetaHomologous()[[pid]], error = function(e) NULL)
            }

            org_info <- d$org_info %||% list()
            org_name <- as.character(org_info$name %||% "")
            org_icon <- as.character(org_info$icon %||% "/icons/DNA.ico")
            gene_name <- trimws(as.character(gene_meta$display_gene_name %||% gene_meta$matched_gene_name %||% extract_title_field(titulo, "Gene") %||% "Gene"))
            tx_name <- trimws(as.character(extract_title_field(titulo, "Transcript") %||% "N/A"))
            chr_name <- trimws(as.character(extract_title_field(titulo, "Chr") %||% "N/A"))
            if (!nzchar(gene_name)) gene_name <- "Gene"
            if (!nzchar(tx_name)) tx_name <- "N/A"
            if (!nzchar(chr_name)) chr_name <- "N/A"

            org_taxid <- suppressWarnings(as.integer(org_info$taxid %||% NA_integer_))
            if (!is.finite(org_taxid) || is.na(org_taxid) || org_taxid <= 0) {
                org_taxid <- resolve_taxid_for_go_lookup(
                    annotation_path = ann_path,
                    organism_name = org_name
                )
            }
            if (!is.finite(org_taxid) || is.na(org_taxid) || org_taxid <= 0) {
                org_taxid <- NA_integer_
            }

            fn_payload <- resolve_gene_function_summary(
                plot_data = d$file_data,
                gene_label = gene_name,
                organism_name = org_name,
                taxid = org_taxid,
                matched_gene_id = as.character(gene_meta$matched_gene_id %||% "")
            )
            summary_txt <- normalize_gene_function_text(fn_payload$full %||% fn_payload$short %||% "")
            if (!nzchar(summary_txt)) {
                summary_txt <- "No function summary available for this gene."
            }
            source_txt <- trimws(as.character(fn_payload$source %||% "Not available"))
            gene_id_txt <- trimws(as.character(fn_payload$gene_id %||% ""))
            context_txt <- if (identical(ctx, "ortho")) "Cross-Species Gene Search" else "Multi-Gene Search"
            annotation_txt <- if (nzchar(ann_path)) basename(ann_path) else "N/A"
            source_detail_txt <- if (identical(source_txt, "Annotation")) {
                "Extracted from local annotation attributes (description/note/product)."
            } else if (identical(source_txt, "NCBI Gene")) {
                "Retrieved from NCBI Gene summary (E-utilities esummary) and cached in app memory."
            } else {
                "No local description was found and no online summary could be resolved."
            }
            ncbi_gene_url <- if (nzchar(gene_id_txt) && grepl("^[0-9]+$", gene_id_txt)) {
                sprintf("https://www.ncbi.nlm.nih.gov/gene/%s", gene_id_txt)
            } else {
                ""
            }

            meta_row <- tags$div(
                class = "gene-function-meta",
                tags$span(class = "gene-function-chip", icon("dna"), paste0("Gene: ", gene_name)),
                tags$span(class = "gene-function-chip", icon("code-branch"), paste0("Transcript: ", tx_name)),
                tags$span(class = "gene-function-chip", icon("barcode"), paste0("Chr: ", chr_name)),
                if (nzchar(org_name)) {
                    tags$span(class = "gene-function-chip", icon("leaf"), tags$em(org_name))
                } else {
                    NULL
                },
                if (nzchar(gene_id_txt)) {
                    tags$span(class = "gene-function-chip", icon("fingerprint"), paste0("GeneID: ", gene_id_txt))
                } else {
                    NULL
                },
                if (is.finite(org_taxid) && !is.na(org_taxid)) {
                    tags$span(class = "gene-function-chip", icon("hashtag"), paste0("TaxID: ", as.integer(org_taxid)))
                } else {
                    NULL
                },
                tags$span(class = "gene-function-chip", icon("file"), paste0("Annotation: ", annotation_txt)),
                tags$span(class = "gene-function-chip gene-function-chip-source", icon("database"), paste0("Source: ", source_txt)),
                tags$span(class = "gene-function-chip", icon("sitemap"), context_txt)
            )

            modal_title <- tags$div(
                class = "gene-function-title-main",
                tags$div(
                    class = "gene-function-title-label",
                    icon("info-circle"),
                    tags$div(
                        class = "gene-function-title-copy",
                        tags$div(
                            class = "gene-function-title-primary",
                            "Gene Function Summary"
                        ),
                        tags$div(
                            class = "gene-function-title-secondary",
                            tags$img(
                                src = if (nzchar(org_icon)) org_icon else "/icons/DNA.ico",
                                alt = if (nzchar(org_name)) org_name else "Organism",
                                class = "gene-function-title-org-icon"
                            ),
                            tags$span(class = "gene-function-title-org", if (nzchar(org_name)) org_name else "Organism"),
                            tags$span(class = "gene-function-title-sep", "|"),
                            tags$span(class = "gene-function-title-gene", gene_name)
                        )
                    )
                ),
                tags$div(
                    class = "gene-function-title-actions",
                    tags$button(
                        type = "button",
                        class = "gene-function-close-btn",
                        onclick = "$(this).closest('.modal').modal('hide');",
                        HTML("&times;")
                    )
                )
            )

            showModal(modalDialog(
                title = modal_title,
                size = "l",
                easyClose = TRUE,
                footer = NULL,
                div(
                    class = "gene-function-body",
                    meta_row,
                    tags$p(class = "gene-function-origin", source_detail_txt),
                    tags$div(
                        class = "gene-function-text-wrap",
                        tags$p(class = "gene-function-text", summary_txt)
                    ),
                    if (nzchar(ncbi_gene_url)) {
                        tags$div(
                            class = "gene-function-links",
                            tags$a(
                                href = ncbi_gene_url,
                                target = "_blank",
                                class = "gene-function-link",
                                icon("external-link-alt"),
                                " Open NCBI Gene record"
                            )
                        )
                    } else {
                        NULL
                    }
                )
            ) |> tagAppendAttributes(class = "gene-function-modal"))
        },
        ignoreNULL = TRUE,
        ignoreInit = TRUE
    )

    # ============================================================
    # ANALYTICS — función auxiliar: mensaje girafe vacío
    # ============================================================
    girafe_msg_plot <- function(text, dark = FALSE) {
        bg <- if (dark) "#1A2B3C" else "#FFFFFF"
        col <- if (dark) "#8CA0B0" else "#78909C"
        safe_girafe(
            ggobj = ggplot2::ggplot() +
                ggplot2::annotate("text",
                    x = 0.5, y = 0.5,
                    label = text, size = 4.5,
                    color = col, hjust = 0.5, vjust = 0.5
                ) +
                ggplot2::theme_void() +
                ggplot2::theme(
                    plot.background = ggplot2::element_rect(fill = bg, color = NA)
                ),
            width_svg = 7, height_svg = 3,
            transport_label = "analytics_empty"
        )
    }

    # ============================================================
    # ANALYTICS — helper function: chart theme
    # ============================================================
    analytics_gg_theme <- function(dark = FALSE) {
        base_bg <- if (dark) "#1A2B3C" else "#FFFFFF"
        base_text <- if (dark) "#D0E4F0" else "#2C3E50"
        grid_col <- if (dark) "#2A3F59" else "#E5EAED"
        ggplot2::theme_minimal(base_size = 10.2, base_family = "sans") +
            ggplot2::theme(
                plot.background = ggplot2::element_rect(fill = base_bg, color = NA),
                panel.background = ggplot2::element_rect(fill = base_bg, color = NA),
                panel.grid.major = ggplot2::element_line(color = grid_col, linewidth = 0.28),
                panel.grid.minor = ggplot2::element_blank(),
                text = ggplot2::element_text(color = base_text, family = "sans"),
                axis.text = ggplot2::element_text(color = base_text, size = 8.4),
                axis.title = ggplot2::element_text(color = base_text, size = 9.1),
                legend.background = ggplot2::element_rect(fill = base_bg, color = NA),
                legend.text = ggplot2::element_text(color = base_text, size = 8.3),
                legend.title = ggplot2::element_text(color = base_text, face = "bold", size = 8.4),
                plot.title = ggplot2::element_text(
                    color = base_text, face = "bold", size = 12.5,
                    hjust = 0.5, margin = ggplot2::margin(b = 3)
                ),
                plot.subtitle = ggplot2::element_text(
                    color = if (dark) "#A8C5DA" else "#546E7A", size = 9.8,
                    hjust = 0.5, margin = ggplot2::margin(b = 6)
                ),
                strip.text = ggplot2::element_text(color = base_text, face = "bold", size = 8.8),
                plot.margin = ggplot2::margin(6, 8, 6, 8)
            )
    }

    # Reusable tooltip CSS.
    # z-index:999999 → aparece por encima de sidebar (2600) y cualquier overlay.
    # NOTA: ggiraph valida el CSS y prohíbe explícitamente tanto "position"
    #   como "pointer-events" — ambos son gestionados internamente por girafe.
    #   El override de pointer-events se hace vía CSS global en www/css/custom.scss
    #   usando el selector div[id^="tooltip_"] (fuera del alcance de ggiraph).
    analytics_tooltip_css <- paste(
        "background:var(--app-message-bg);",
        "color:var(--app-message-text);",
        "border:1px solid var(--app-message-border);",
        "border-radius:var(--app-message-radius);",
        "padding:8px 11px;",
        "font-family:var(--app-font-family),Roboto,'Segoe UI','Helvetica Neue',Arial,sans-serif;",
        "font-size:12px;",
        "font-weight:600;",
        "line-height:1.4;",
        "letter-spacing:0.01em;",
        "box-shadow:var(--app-message-shadow);",
        "z-index:999999;"
    )

    # Compact analytics layout helpers
    analytics_svg_height <- function(n_items,
                                     min_h = 2.4,
                                     max_h = 6.8,
                                     base = 1.35,
                                     per_item = 0.42) {
        n_num <- suppressWarnings(as.numeric(n_items))
        if (!is.finite(n_num) || n_num <= 0) n_num <- 1
        pmin(max_h, pmax(min_h, base + per_item * n_num))
    }

    # Adaptive axis layout to prevent label overlap for large transcript sets.
    analytics_axis_density <- function(n_items) {
        n <- suppressWarnings(as.integer(n_items))
        if (!is.finite(n) || n < 1L) n <- 1L
        if (n <= 8L) {
            return(list(
                axis_text_size = 8.4,
                label_width = 58L,
                per_item = 0.42,
                max_h = 6.8,
                heatmap_x_size = 7.4,
                sparse_step = 1L
            ))
        }
        if (n <= 16L) {
            return(list(
                axis_text_size = 8.0,
                label_width = 44L,
                per_item = 0.50,
                max_h = 9.8,
                heatmap_x_size = 7.1,
                sparse_step = 1L
            ))
        }
        if (n <= 30L) {
            return(list(
                axis_text_size = 7.5,
                label_width = 34L,
                per_item = 0.60,
                max_h = 14.0,
                heatmap_x_size = 6.8,
                sparse_step = 2L
            ))
        }
        if (n <= 50L) {
            return(list(
                axis_text_size = 7.0,
                label_width = 26L,
                per_item = 0.70,
                max_h = 22.0,
                heatmap_x_size = 6.5,
                sparse_step = 3L
            ))
        }
        list(
            axis_text_size = 6.6,
            label_width = 22L,
            per_item = 0.78,
            max_h = 30.0,
            heatmap_x_size = 6.2,
            sparse_step = 4L
        )
    }

    analytics_compact_axis_labels <- function(labels, n_items) {
        dens <- analytics_axis_density(n_items)
        lbl <- as.character(labels %||% "")
        lbl <- trimws(lbl)
        lbl[!nzchar(lbl)] <- "N/A"
        stringr::str_trunc(lbl, width = dens$label_width, ellipsis = "...")
    }

    # Pick text color with enough contrast against tile fill color.
    analytics_contrast_text_color <- function(fill_hex,
                                              light_text = "#EAF3FA",
                                              dark_text = "#1F2A35",
                                              luminance_cutoff = 0.62) {
        vals <- as.character(fill_hex %||% "")
        vals[is.na(vals) | !nzchar(vals)] <- "#FFFFFF"
        rgb <- tryCatch(
            suppressWarnings(grDevices::col2rgb(vals, alpha = FALSE) / 255),
            error = function(e) {
                matrix(1, nrow = 3, ncol = length(vals))
            }
        )
        lum <- 0.2126 * rgb[1, ] + 0.7152 * rgb[2, ] + 0.0722 * rgb[3, ]
        ifelse(is.finite(lum) & lum > luminance_cutoff, dark_text, light_text)
    }

    analytics_sparse_axis_labels <- function(labels, n_items) {
        dens <- analytics_axis_density(n_items)
        out <- analytics_compact_axis_labels(labels, n_items)
        step <- suppressWarnings(as.integer(dens$sparse_step))
        if (!is.finite(step) || step < 2L) {
            return(out)
        }
        idx <- seq_along(out)
        keep <- (idx %% step == 1L) | (idx == length(out))
        out[!keep] <- ""
        out
    }

    analytics_adaptive_axis_labels <- function(labels, n_items, sparse_from = 30L) {
        # Keep every axis label visible; adapt only via truncation/size/plot dimensions.
        analytics_compact_axis_labels(labels, n_items)
    }

    # Keep the per-group sample size visible even when long gene labels need
    # truncation. The total sample size is reported separately in the subtitle.
    analytics_labels_with_n <- function(labels, counts, n_items) {
        labels_txt <- as.character(labels %||% character(0))
        counts_num <- suppressWarnings(as.integer(counts %||% integer(0)))
        if (length(labels_txt) == 0L) return(character(0))
        if (length(counts_num) == 0L) {
            counts_num <- rep(0L, length(labels_txt))
        }
        if (length(counts_num) != length(labels_txt)) {
            counts_num <- rep_len(counts_num, length(labels_txt))
        }
        counts_num[!is.finite(counts_num) | counts_num < 0L] <- 0L
        suffix <- paste0(" (n = ", counts_num, ")")
        max_width <- analytics_axis_density(n_items)$label_width
        base_width <- pmax(4L, as.integer(max_width) - nchar(suffix, type = "width"))
        base_label <- mapply(
            function(lbl, width) stringr::str_trunc(lbl, width = width, ellipsis = "..."),
            labels_txt,
            base_width,
            USE.NAMES = FALSE
        )
        paste0(base_label, suffix)
    }

    # Build axis labels: gene name + italic organism (for ortho mode).
    # Returns named list of plotmath expressions (ortho) or named character vector (homo).
    analytics_build_axis_labels <- function(gene_labels, organism_labels, axis_keys, n_genes) {
        gene_trunc <- analytics_adaptive_axis_labels(gene_labels, n_genes)
        has_org <- !is.null(organism_labels) && any(nzchar(trimws(organism_labels)))
        if (has_org) {
            org_trunc <- analytics_adaptive_axis_labels(organism_labels, n_genes)
            exprs <- mapply(function(g, o) {
                if (nzchar(trimws(o))) {
                    bquote(atop(.(g), scriptstyle(italic(.(o)))))
                } else {
                    g
                }
            }, gene_trunc, org_trunc, SIMPLIFY = FALSE, USE.NAMES = FALSE)
            stats::setNames(exprs, axis_keys)
        } else {
            stats::setNames(gene_trunc, axis_keys)
        }
    }

    analytics_build_label_rows <- function(gene_labels, organism_labels, axis_keys, n_genes) {
        gene_trunc <- as.character(analytics_adaptive_axis_labels(gene_labels, n_genes) %||% character(0))
        org_trunc <- if (is.null(organism_labels)) {
            rep("", length(gene_trunc))
        } else {
            as.character(analytics_adaptive_axis_labels(organism_labels, n_genes) %||% character(0))
        }
        data.frame(
            axis_id = factor(as.character(axis_keys), levels = rev(as.character(axis_keys))),
            gene = gene_trunc,
            organism = org_trunc,
            stringsAsFactors = FALSE
        )
    }

    analytics_label_panel_width <- function(label_rows) {
        if (is.null(label_rows) || !is.data.frame(label_rows) || nrow(label_rows) == 0L) {
            return(1.00)
        }
        max_chars <- max(
            nchar(as.character(label_rows$gene %||% ""), type = "width"),
            nchar(as.character(label_rows$organism %||% ""), type = "width"),
            na.rm = TRUE
        )
        width_val <- 0.72 + (max_chars / 34)
        max(0.98, min(1.36, width_val))
    }

    analytics_label_panel_plot <- function(label_rows, dark = FALSE, text_size = 8.4) {
        if (is.null(label_rows) || !is.data.frame(label_rows) || nrow(label_rows) == 0L) {
            return(NULL)
        }
        base_text <- if (dark) "#D0E4F0" else "#2C3E50"
        bg_fill <- if (dark) "#1A2B3C" else "#FFFFFF"
        org_rows <- label_rows[nzchar(trimws(as.character(label_rows$organism %||% ""))), , drop = FALSE]

        p <- ggplot2::ggplot(label_rows, ggplot2::aes(x = 1, y = axis_id)) +
            ggplot2::geom_text(
                ggplot2::aes(label = gene),
                hjust = 1,
                nudge_y = 0.18,
                size = text_size / 2.9,
                color = base_text,
                family = "sans",
                lineheight = 0.95
            ) +
            ggplot2::scale_x_continuous(limits = c(0, 1), expand = ggplot2::expansion(mult = c(0, 0), add = c(0, 0))) +
            ggplot2::scale_y_discrete(drop = FALSE) +
            ggplot2::coord_cartesian(clip = "off") +
            ggplot2::theme_void() +
            ggplot2::theme(
                plot.background = ggplot2::element_rect(fill = bg_fill, color = NA),
                panel.background = ggplot2::element_rect(fill = bg_fill, color = NA),
                plot.margin = ggplot2::margin(6, -18, 6, 8)
            )

        if (nrow(org_rows) > 0L) {
            p <- p + ggplot2::geom_text(
                data = org_rows,
                ggplot2::aes(label = organism),
                hjust = 1,
                nudge_y = -0.18,
                size = max(6.8, text_size - 0.25) / 2.9,
                color = base_text,
                family = "sans",
                fontface = "italic",
                lineheight = 0.94
            )
        }

        p
    }

    analytics_compose_with_label_panel <- function(label_plot, main_plot, label_width, main_width) {
        (label_plot + main_plot + patchwork::plot_layout(widths = c(label_width, main_width))) &
            ggplot2::theme(
                plot.margin = ggplot2::margin(6, 8, 6, -34)
            )
    }

    analytics_girafe_options <- function(hover_css = "opacity:0.88;stroke:white;stroke-width:1.2px;") {
        theme_mode <- tolower(trimws(as.character(input$app_theme %||% "light")))
        is_dark_local <- identical(theme_mode, "dark")
        hover_css_txt <- as.character(hover_css %||% "")
        if (is_dark_local && nzchar(hover_css_txt)) {
            hover_css_txt <- gsub("white", "#1A2B3C", hover_css_txt, fixed = TRUE)
        }
        list(
            ggiraph::opts_hover(css = hover_css_txt),
            ggiraph::opts_tooltip(
                css = analytics_tooltip_css,
                use_fill = FALSE,
                placement = "doc",
                zindex = 999999,
                delay_mouseover = 40,
                delay_mouseout = 120
            ),
            ggiraph::opts_selection(type = "none"),
            ggiraph::opts_toolbar(
                position = "bottomright",
                hidden = c("selection", "zoom", "misc")
            ),
            ggiraph::opts_sizing(rescale = TRUE)
        )
    }

    is_dark_theme_active <- function() {
        theme_mode <- tolower(trimws(as.character(input$app_theme %||% "light")))
        identical(theme_mode, "dark")
    }

    is_colorblind_mode_active <- function() {
        isTRUE(input$colorblind_mode)
    }

    analytics_discrete_palette <- function(n, colorblind = FALSE) {
        n <- suppressWarnings(as.integer(n))
        if (!is.finite(n) || n < 1L) n <- 1L
        if (!isTRUE(colorblind)) {
            return(scales::hue_pal()(n))
        }
        # Okabe-Ito inspired sequence for better CVD accessibility.
        base <- c("#0072B2", "#E69F00", "#009E73", "#CC79A7", "#D55E00", "#56B4E9", "#F0E442", "#999999")
        rep(base, length.out = n)
    }

    analytics_diverging_palette <- function(colorblind = FALSE, dark = FALSE) {
        if (isTRUE(colorblind)) {
            return(list(
                low = "#0072B2",
                mid = if (isTRUE(dark)) "#E6EDF3" else "#F7F7F7",
                high = "#E69F00",
                na = if (isTRUE(dark)) "#2A3F59" else "#ECEFF1"
            ))
        }
        list(
            low = "#1565C0",
            mid = "white",
            high = "#C62828",
            na = if (isTRUE(dark)) "#2A3F59" else "#ECEFF1"
        )
    }

    analytics_named_palette <- function(key, colorblind = FALSE, dark = FALSE) {
        key <- tolower(trimws(as.character(key %||% "")))
        if (!isTRUE(colorblind)) {
            return(switch(key,
                arch = c("CDS" = "#2196F3", "UTR" = "#64B5F6", "Intron" = "#B0BEC5"),
                exon_counts = c("Exons" = "#43A047", "Introns" = "#78909C"),
                exon_bp = c("Exonic bp" = "#66BB6A", "Intronic bp" = "#B0BEC5"),
                bases = c("A" = "#FFA34A", "T" = "#E7D84C", "C" = "#8ACF52", "G" = "#B49AEF"),
                context_state = c("Overlap" = "#D55E00", "Gap" = "#2C7FB8"),
                c("primary" = "#42A5F5")
            ))
        }
        switch(key,
            arch = c("CDS" = "#0072B2", "UTR" = "#56B4E9", "Intron" = if (isTRUE(dark)) "#8FA1B0" else "#8C9AA6"),
            exon_counts = c("Exons" = "#009E73", "Introns" = if (isTRUE(dark)) "#8FA1B0" else "#8C9AA6"),
            exon_bp = c("Exonic bp" = "#009E73", "Intronic bp" = if (isTRUE(dark)) "#8FA1B0" else "#8C9AA6"),
            bases = c("A" = "#E69F00", "T" = "#F0E442", "C" = "#009E73", "G" = "#CC79A7"),
            context_state = c("Overlap" = "#D55E00", "Gap" = "#0072B2"),
            c("primary" = "#0072B2")
        )
    }

    # ============================================================
    # CHARTS MODAL — helper: obtiene datos por plot ID + contexto
    # ============================================================
    get_chart_plot_data <- function(pid, ctx) {
        pid <- as.character(pid %||% "")
        if (identical(ctx, "ortho")) {
            list(
                file_data = tryCatch(fileDataOrthologous()[[pid]], error = function(e) NULL),
                seq_blob  = tryCatch(genSequencesOrthologous()[[pid]], error = function(e) NULL),
                org_info  = tryCatch(organismInfoOrthologous()[[pid]], error = function(e) NULL),
                metrics   = tryCatch(get_plot_metrics_payload(pid, "ortho"), error = function(e) NULL)
            )
        } else {
            list(
                file_data = tryCatch(fileDataHomologous()[[pid]], error = function(e) NULL),
                seq_blob  = tryCatch(genSequencesHomologous()[[pid]], error = function(e) NULL),
                org_info  = tryCatch(organismInfoHomologous()[[pid]], error = function(e) NULL),
                metrics   = tryCatch(get_plot_metrics_payload(pid, "homo"), error = function(e) NULL)
            )
        }
    }

    get_chart_modal_isoforms_df <- function(pid, ctx) {
        pid <- as.character(pid %||% "")
        if (!nzchar(pid)) {
            return(data.frame())
        }

        first_non_empty_local <- function(...) {
            vals <- unlist(list(...), use.names = FALSE)
            for (v in vals) {
                txt <- trimws(as.character(v %||% ""))
                if (!is.na(txt) && nzchar(txt)) {
                    return(txt)
                }
            }
            ""
        }

        norm_key <- function(x) {
            tolower(trimws(as.character(x %||% "")))
        }
        tx_types <- c(
            "mrna", "transcript", "ncrna", "rrna", "trna",
            "lncrna", "lnc_rna", "pseudogenic_transcript",
            "primary_transcript", "pre_mirna", "mirna",
            "snrna", "snorna", "guide_rna", "rnase_p_rna"
        )

        if (identical(ctx, "ortho")) {
            ids <- tryCatch(as.character(activePlotIdsOrthologous() %||% character(0)), error = function(e) character(0))
            titles_map <- tryCatch(titlesOrthologous(), error = function(e) list())
            files_map <- tryCatch(fileDataOrthologous(), error = function(e) list())
            org_map <- tryCatch(organismInfoOrthologous(), error = function(e) list())
            ann_map <- tryCatch(annotationPathsOrthologous(), error = function(e) list())
        } else {
            ids <- tryCatch(as.character(activePlotIdsHomologous() %||% character(0)), error = function(e) character(0))
            titles_map <- tryCatch(titlesHomologous(), error = function(e) list())
            files_map <- tryCatch(fileDataHomologous(), error = function(e) list())
            org_map <- tryCatch(organismInfoHomologous(), error = function(e) list())
            ann_map <- tryCatch(annotationPathsHomologous(), error = function(e) list())
        }

        ids <- unique(c(pid, ids))
        if (length(ids) == 0) {
            return(data.frame())
        }

        title_pid <- as.character(titles_map[[pid]] %||% "")
        base_gene <- norm_key(extract_title_field(title_pid, "Gene"))
        base_org <- norm_key(tryCatch(org_map[[pid]]$name, error = function(e) ""))
        base_ann <- norm_key(as.character(ann_map[[pid]] %||% ""))

        out_rows <- lapply(ids, function(plot_id) {
            plot_id <- as.character(plot_id %||% "")
            if (!nzchar(plot_id)) {
                return(NULL)
            }

            fd <- tryCatch(files_map[[plot_id]], error = function(e) NULL)
            if (is.null(fd) || nrow(fd) == 0) {
                return(NULL)
            }

            ttl <- as.character(titles_map[[plot_id]] %||% "")
            gene_i <- norm_key(extract_title_field(ttl, "Gene"))
            org_i <- norm_key(tryCatch(org_map[[plot_id]]$name, error = function(e) ""))
            ann_i <- norm_key(as.character(ann_map[[plot_id]] %||% ""))

            if (nzchar(base_gene)) {
                if (!identical(gene_i, base_gene)) {
                    return(NULL)
                }
            } else if (!identical(plot_id, pid)) {
                return(NULL)
            }
            if (nzchar(base_ann)) {
                if (!identical(ann_i, base_ann)) {
                    return(NULL)
                }
            } else if (nzchar(base_org) && !identical(org_i, base_org)) {
                return(NULL)
            }

            types <- tolower(trimws(as.character(fd$V3 %||% rep("", nrow(fd)))))
            starts <- suppressWarnings(as.numeric(fd$V4))
            ends <- suppressWarnings(as.numeric(fd$V5))
            attrs <- as.character(fd$V9 %||% rep("", nrow(fd)))
            tx_rows <- which(types %in% tx_types)

            if (length(tx_rows) == 0) {
                tx_span <- tryCatch(compute_transcript_span(fd), error = function(e) c(start = NA_real_, end = NA_real_, len = NA_real_))
                tx_len <- suppressWarnings(as.numeric(transcript_span_length(tx_span)))
                if (!is.finite(tx_len)) {
                    valid <- is.finite(starts) & is.finite(ends)
                    if (any(valid)) {
                        tx_len <- as.numeric(max(ends[valid], na.rm = TRUE) - min(starts[valid], na.rm = TRUE) + 1)
                    }
                }
                tx_id <- trimws(as.character(extract_title_field(ttl, "Transcript") %||% ""))
                if (!nzchar(tx_id)) tx_id <- paste0("Tx_", plot_id)
                return(data.frame(
                    tx_id = tx_id,
                    tx_len = tx_len,
                    source_plot = plot_id,
                    stringsAsFactors = FALSE
                ))
            }

            do.call(rbind,  lapply(tx_rows, function(r) {
                parsed <- tryCatch(parse_gff_attributes(attrs[r]), error = function(e) list())
                tx_id <- first_non_empty_local(
                    tryCatch(pick_attr(parsed, c("transcript_id", "id", "name", "transcript")), error = function(e) ""),
                    trimws(as.character(extract_title_field(ttl, "Transcript") %||% "")),
                    paste0("Tx_", plot_id, "_", r)
                )
                tx_len <- suppressWarnings(as.numeric(ends[r] - starts[r] + 1))
                if (!is.finite(tx_len) || tx_len <= 0) {
                    tx_span <- tryCatch(compute_transcript_span(fd), error = function(e) c(start = NA_real_, end = NA_real_, len = NA_real_))
                    tx_len <- suppressWarnings(as.numeric(transcript_span_length(tx_span)))
                }
                data.frame(
                    tx_id = as.character(tx_id),
                    tx_len = as.numeric(tx_len),
                    source_plot = plot_id,
                    stringsAsFactors = FALSE
                )
            }))
        })

        df_tx <- do.call(rbind,  Filter(Negate(is.null), out_rows))
        if (is.null(df_tx) || nrow(df_tx) == 0) {
            return(data.frame())
        }

        df_tx$tx_id <- trimws(as.character(df_tx$tx_id %||% ""))
        missing_id <- !nzchar(df_tx$tx_id)
        if (any(missing_id)) {
            df_tx$tx_id[missing_id] <- paste0("Isoform ", seq_len(sum(missing_id)))
        }
        df_tx$tx_len <- suppressWarnings(as.numeric(df_tx$tx_len))
        df_tx <- df_tx[is.finite(df_tx$tx_len) & df_tx$tx_len > 0, c("tx_id", "tx_len", "source_plot"), drop = FALSE]
        if (nrow(df_tx) == 0) {
            return(data.frame())
        }

        tx_key <- paste0(tolower(df_tx$tx_id), "|", round(df_tx$tx_len))
        df_tx <- df_tx[!duplicated(tx_key), , drop = FALSE]
        df_tx <- df_tx[order(-df_tx$tx_len, tolower(df_tx$tx_id)), , drop = FALSE]
        rownames(df_tx) <- NULL
        df_tx
    }

