    # ============================================================
    # CHART 1A — Gene Architecture (stacked bar: CDS | UTR | Intron)
    # ============================================================
    render_arch_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_base <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode)
            n_genes <- nrow(df_base)
            dens <- analytics_axis_density(n_genes)
            axis_label_map <- analytics_build_axis_labels(
                df_base$x_label, df_base$x_label_organism,
                levels(df_base$axis_id), n_genes
            )
            label_rows <- analytics_build_label_rows(
                df_base$x_label, df_base$x_label_organism,
                levels(df_base$axis_id), n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(df_base$x_label_organism %||% ""))))

            df_prep <- df_base %>%
                dplyr::mutate(
                    Intron_bp = pmax(0L, as.integer(Gene_Length_bp) - as.integer(Exonic_bp)),
                    UTR_bp    = pmax(0L, as.integer(Exonic_bp) - as.integer(CDS_bp)),
                    CDS_bp    = pmax(0L, as.integer(CDS_bp))
                ) %>%
                # Drop genes with all-NA architecture to avoid ggplot warnings
                dplyr::filter(!is.na(CDS_bp) | !is.na(UTR_bp) | !is.na(Intron_bp)) %>%
                tidyr::pivot_longer(
                    cols      = c("CDS_bp", "UTR_bp", "Intron_bp"),
                    names_to  = "Region",
                    values_to = "bp"
                ) %>%
                dplyr::mutate(
                    Region = factor(Region,
                        levels = c("CDS_bp", "UTR_bp", "Intron_bp"),
                        labels = c("CDS", "UTR", "Intron")
                    ),
                    # Replace NA bp with 0 for partial data (e.g. gene has exons but no CDS)
                    bp = dplyr::coalesce(bp, 0L),
                    tooltip_txt = paste0(
                        "<b>", x_label, "</b><br/>",
                        "<b>", Region, ":</b> ", format(bp, big.mark = ","), " bp"
                    )
                )

            pal <- analytics_named_palette("arch", colorblind = is_cb, dark = is_dark)

            p <- ggplot2::ggplot(
                df_prep,
                ggplot2::aes(
                    x = axis_id, y = bp, fill = Region,
                    tooltip = tooltip_txt,
                    data_id = paste0(axis_id, "_", Region)
                )
            ) +
                ggiraph::geom_col_interactive(width = 0.46, color = if (is_dark) "#1A2B3C" else "white", linewidth = 0.22) +
                ggplot2::coord_flip() +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev) +
                ggplot2::scale_fill_manual(values = pal) +
                ggplot2::scale_y_continuous(labels = scales::label_number(scale_cut = scales::cut_short_scale())) +
                ggplot2::labs(
                    title = "Gene Architecture",
                    subtitle = "Base pair composition: CDS | UTR | Introns",
                    x = NULL, y = "bp", fill = "Region"
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            ggobj <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, p, label_width, 4.3)
            } else {
                p
            }

            safe_girafe(
                ggobj = ggobj,
                width_svg = 8.4,
                height_svg = analytics_svg_height(
                    n_genes,
                    min_h = 2.35, max_h = dens$max_h, base = 1.25, per_item = dens$per_item
                ),
                transport_label = paste0(mode, "_gene_architecture"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("opacity:0.88;stroke:white;stroke-width:1.2px;")
            )
        })
    }

    output$homo_arch_chart <- render_arch_chart(build_homo_summary, mode = "homo", order_input_id = "homo_arch_order")
    output$ortho_arch_chart <- render_arch_chart(build_ortho_summary, mode = "ortho", order_input_id = "ortho_arch_order")

    # ============================================================
    # CHART 1B — Exons & Introns (counts + base pairs)
    # ============================================================
    render_exon_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_prep <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode) %>%
                dplyr::mutate(
                    Exonic_bp   = pmax(0L, as.integer(Exonic_bp)),
                    Intronic_bp = pmax(0L, as.integer(Gene_Length_bp) - as.integer(Exonic_bp)),
                    Exons       = dplyr::coalesce(as.integer(Exons), 0L),
                    Introns     = dplyr::coalesce(as.integer(Introns), 0L),
                    Exonic_bp   = dplyr::coalesce(Exonic_bp, 0L),
                    Intronic_bp = dplyr::coalesce(Intronic_bp, 0L)
                )
            n_genes <- nrow(df_prep)
            dens <- analytics_axis_density(n_genes)
            axis_label_map <- analytics_build_axis_labels(
                df_prep$x_label, df_prep$x_label_organism,
                levels(df_prep$axis_id), n_genes
            )
            label_rows <- analytics_build_label_rows(
                df_prep$x_label, df_prep$x_label_organism,
                levels(df_prep$axis_id), n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(df_prep$x_label_organism %||% ""))))

            # Top panel: counts
            df_counts <- df_prep %>%
                tidyr::pivot_longer(
                    cols = c("Exons", "Introns"),
                    names_to = "Tipo", values_to = "N"
                ) %>%
                dplyr::mutate(
                    Tipo = factor(Tipo,
                        levels = c("Exons", "Introns"),
                        labels = c("Exons", "Introns")
                    ),
                    tooltip_txt = paste0(
                        "<b>", x_label, "</b><br/>",
                        "<b>", Tipo, ":</b> ", N
                    )
                )

            # Lower panel: base pairs
            df_bp <- df_prep %>%
                tidyr::pivot_longer(
                    cols = c("Exonic_bp", "Intronic_bp"),
                    names_to = "Tipo", values_to = "bp"
                ) %>%
                dplyr::mutate(
                    Tipo = factor(Tipo,
                        levels = c("Exonic_bp", "Intronic_bp"),
                        labels = c("Exonic bp", "Intronic bp")
                    ),
                    tooltip_txt = paste0(
                        "<b>", x_label, "</b><br/>",
                        "<b>", Tipo, ":</b> ",
                        format(bp, big.mark = ","), " bp"
                    )
                )

            pal_counts <- analytics_named_palette("exon_counts", colorblind = is_cb, dark = is_dark)
            pal_bp <- analytics_named_palette("exon_bp", colorblind = is_cb, dark = is_dark)

            p_counts <- ggplot2::ggplot(
                df_counts,
                ggplot2::aes(
                    x = axis_id, y = N, fill = Tipo,
                    tooltip = tooltip_txt,
                    data_id = paste0(axis_id, "_", Tipo, "_N")
                )
            ) +
                ggiraph::geom_col_interactive(
                    position = "dodge", width = 0.46,
                    color = if (is_dark) "#1A2B3C" else "white", linewidth = 0.22
                ) +
                ggplot2::coord_flip() +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev) +
                ggplot2::scale_fill_manual(values = pal_counts) +
                ggplot2::labs(
                    title = "Exon & Intron Count",
                    x = NULL, y = "Count", fill = NULL
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    legend.position = "top",
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            p_bp <- ggplot2::ggplot(
                df_bp,
                ggplot2::aes(
                    x = axis_id, y = bp, fill = Tipo,
                    tooltip = tooltip_txt,
                    data_id = paste0(axis_id, "_", Tipo, "_bp")
                )
            ) +
                ggiraph::geom_col_interactive(
                    position = "stack", width = 0.46,
                    color = if (is_dark) "#1A2B3C" else "white", linewidth = 0.22
                ) +
                ggplot2::coord_flip() +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev) +
                ggplot2::scale_fill_manual(values = pal_bp) +
                ggplot2::scale_y_continuous(labels = scales::label_number(scale_cut = scales::cut_short_scale())) +
                ggplot2::labs(
                    title = "Exonic vs Intronic Base Pairs",
                    x = NULL, y = "bp", fill = NULL
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    legend.position = "top",
                    axis.text.y = ggplot2::element_blank(),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -12) else ggplot2::margin(6, 8, 6, 8)
                )

            h_svg <- analytics_svg_height(
                n_genes,
                min_h = 3.1, max_h = dens$max_h, base = 2.0, per_item = dens$per_item
            )

            bg_fill <- if (is_dark) "#1A2B3C" else "#FFFFFF"

            chart_pair <- patchwork::wrap_plots(p_counts, p_bp, ncol = 2) &
                ggplot2::theme(
                    plot.background = ggplot2::element_rect(fill = bg_fill, color = NA),
                    panel.background = ggplot2::element_rect(fill = bg_fill, color = NA)
                )

            combined <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, chart_pair, label_width, 5.2)
            } else {
                chart_pair
            }

            safe_girafe(
                ggobj = combined,
                width_svg = 9.6, height_svg = h_svg,
                transport_label = paste0(mode, "_exon_chart"),
                bg = bg_fill,
                options = analytics_girafe_options("opacity:0.88;stroke:white;stroke-width:1.2px;")
            )
        })
    }

    output$homo_exon_chart <- render_exon_chart(build_homo_summary, mode = "homo", order_input_id = "homo_exon_order")
    output$ortho_exon_chart <- render_exon_chart(build_ortho_summary, mode = "ortho", order_input_id = "ortho_exon_order")

    # ============================================================
    # CHART 1C — Sequence Composition (A | T | C | G)
    # ============================================================
    render_seq_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_axis <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode)

            df_prep <- df_axis %>%
                dplyr::mutate(
                    A = as.numeric(A_pct),
                    T = as.numeric(T_pct),
                    C = as.numeric(C_pct),
                    G = as.numeric(G_pct),
                    GC = as.numeric(GC_Content_pct)
                ) %>%
                # Drop genes with no sequence data to avoid
                # "Removed N rows containing missing values" warnings
                dplyr::filter(!is.na(A) & !is.na(T) & !is.na(C) & !is.na(G)) %>%
                tidyr::pivot_longer(
                    cols = c("A", "T", "C", "G"),
                    names_to = "Base", values_to = "pct"
                ) %>%
                dplyr::mutate(
                    Base = factor(Base, levels = c("A", "T", "C", "G")),
                    tooltip_txt = paste0(
                        "<b>", x_label, "</b><br/>",
                        "<b>", Base, ":</b> ", round(pct, 2), "%<br/>",
                        "<b>GC total:</b> ", round(GC, 2), "%"
                    )
                )
            if (nrow(df_prep) == 0L) {
                return(NULL)
            }
            n_genes <- dplyr::n_distinct(df_prep$axis_id)
            dens <- analytics_axis_density(n_genes)
            axis_label_map <- analytics_build_axis_labels(
                df_axis$x_label, df_axis$x_label_organism,
                levels(df_axis$axis_id), n_genes
            )
            label_rows <- analytics_build_label_rows(
                df_axis$x_label, df_axis$x_label_organism,
                levels(df_axis$axis_id), n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(df_axis$x_label_organism %||% ""))))

            pal_bases <- analytics_named_palette("bases", colorblind = is_cb, dark = is_dark)
            bar_border_col <- if (is_dark) "#1A2B3C" else "white"
            hover_stroke_col <- if (is_dark) "#A8C5DA" else "white"

            p <- ggplot2::ggplot(
                df_prep,
                ggplot2::aes(
                    x = axis_id, y = pct, fill = Base,
                    tooltip = tooltip_txt,
                    data_id = paste0(axis_id, "_", Base)
                )
            ) +
                ggiraph::geom_col_interactive(
                    position = "dodge", width = 0.48,
                    color = bar_border_col, linewidth = 0.35
                ) +
                ggplot2::coord_flip(ylim = c(0, 50)) +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev) +
                ggplot2::scale_fill_manual(values = pal_bases) +
                ggplot2::scale_y_continuous(
                    labels = function(x) paste0(x, "%")
                ) +
                ggplot2::labs(
                    title = "Nucleotide Composition",
                    subtitle = "Percentage of each nucleotide in the gene sequence",
                    x = NULL, y = "Percentage (%)", fill = "Base"
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            # Añadir anotación de GC% por gen
            df_gc <- df_prep %>%
                dplyr::select(axis_id, GC) %>%
                dplyr::distinct()

            p <- p +
                ggiraph::geom_text_interactive(
                    data = df_gc,
                    ggplot2::aes(
                        x = axis_id, y = 47,
                        label = paste0("GC: ", round(GC, 1), "%"),
                        tooltip = paste0("GC: ", round(GC, 2), "%"),
                        data_id = paste0(axis_id, "_gc"),
                        fill = NULL
                    ),
                    hjust = 1,
                    size = 2.7,
                    color = if (is_dark) "#A0C8E0" else "#455A64",
                    fontface = "bold",
                    inherit.aes = FALSE
                )

            ggobj <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, p, label_width, 4.5)
            } else {
                p
            }

            safe_girafe(
                ggobj = ggobj,
                width_svg = 8.4,
                height_svg = analytics_svg_height(
                    n_genes,
                    min_h = 2.45, max_h = dens$max_h, base = 1.3, per_item = dens$per_item
                ),
                transport_label = paste0(mode, "_sequence_composition"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options(
                    paste0("opacity:0.9;stroke:", hover_stroke_col, ";stroke-width:1.2px;")
                )
            )
        })
    }

    output$homo_seq_chart <- render_seq_chart(build_homo_summary, mode = "homo", order_input_id = "homo_seq_order")
    output$ortho_seq_chart <- render_seq_chart(build_ortho_summary, mode = "ortho", order_input_id = "ortho_seq_order")

    # ============================================================
    # CHART 1D — Genomic Context (nearest neighbor gene distances)
    # ============================================================
    render_context_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_side <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode) %>%
                dplyr::transmute(
                    axis_key = as.character(axis_id),
                    x_label = as.character(x_label),
                    x_label_organism = as.character(x_label_organism %||% ""),
                    up_neighbor = as.character(Upstream_Gene),
                    down_neighbor = as.character(Downstream_Gene),
                    up_distance = suppressWarnings(as.numeric(Upstream_Distance_bp)),
                    down_distance = suppressWarnings(as.numeric(Downstream_Distance_bp))
                )

            df_long <- dplyr::bind_rows(
                dplyr::transmute(
                    df_side,
                    axis_key = axis_key,
                    x_label = x_label,
                    x_label_organism = x_label_organism,
                    side = "Upstream",
                    neighbor = ifelse(
                        is.na(up_neighbor) | up_neighbor == "N/A" | !nzchar(trimws(up_neighbor)),
                        "unknown", up_neighbor
                    ),
                    distance_bp = up_distance
                ),
                dplyr::transmute(
                    df_side,
                    axis_key = axis_key,
                    x_label = x_label,
                    x_label_organism = x_label_organism,
                    side = "Downstream",
                    neighbor = ifelse(
                        is.na(down_neighbor) | down_neighbor == "N/A" | !nzchar(trimws(down_neighbor)),
                        "unknown", down_neighbor
                    ),
                    distance_bp = down_distance
                )
            ) %>%
                dplyr::filter(is.finite(distance_bp)) %>%
                dplyr::mutate(
                    side = factor(side, levels = c("Upstream", "Downstream")),
                    state = ifelse(distance_bp < 0, "Overlap", "Gap"),
                    state = factor(state, levels = c("Overlap", "Gap")),
                    tooltip_txt = paste0(
                        "<b>", x_label, "</b><br/>",
                        ifelse(nzchar(trimws(x_label_organism)), paste0("<i>", x_label_organism, "</i><br/>"), ""),
                        "<b>Panel:</b> ", side, "<br/>",
                        "<b>Neighbor:</b> ", neighbor, "<br/>",
                        ifelse(
                            distance_bp < 0,
                            paste0("<b>Overlap:</b> ", format(abs(distance_bp), big.mark = ","), " bp"),
                            ifelse(
                                distance_bp == 0,
                                "<b>Distance:</b> 0 bp (touching)",
                                paste0("<b>Distance:</b> ", format(distance_bp, big.mark = ","), " bp")
                            )
                        )
                    ),
                    data_id = paste0(axis_key, "_", side)
                )

            if (nrow(df_long) == 0) {
                return(girafe_msg_plot("No neighboring gene data available", dark = is_dark))
            }

            zero_col <- if (is_dark) "#2A3F59" else "#CFD8DC"
            state_pal <- analytics_named_palette("context_state", colorblind = is_cb, dark = is_dark)

            axis_order <- as.character(df_side$axis_key)
            n_genes <- length(axis_order)
            dens <- analytics_axis_density(n_genes)
            org_map_ctx <- df_side %>%
                dplyr::distinct(x_label, .keep_all = TRUE)
            org_map_ctx <- df_side %>%
                dplyr::distinct(axis_key, x_label, x_label_organism)
            axis_label_map <- analytics_build_axis_labels(
                org_map_ctx$x_label, org_map_ctx$x_label_organism, org_map_ctx$axis_key, n_genes
            )
            label_rows <- analytics_build_label_rows(
                org_map_ctx$x_label, org_map_ctx$x_label_organism, org_map_ctx$axis_key, n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(org_map_ctx$x_label_organism %||% ""))))
            df_long$axis_key <- factor(df_long$axis_key, levels = rev(axis_order))

            p <- ggplot2::ggplot(
                df_long,
                ggplot2::aes(
                    x = distance_bp,
                    y = axis_key,
                    color = state,
                    tooltip = tooltip_txt,
                    data_id = data_id
                )
            ) +
                ggplot2::geom_vline(xintercept = 0, color = zero_col, linewidth = 0.9) +
                ggplot2::geom_segment(
                    ggplot2::aes(
                        x = 0,
                        xend = distance_bp,
                        y = axis_key,
                        yend = axis_key,
                        color = state
                    ),
                    linewidth = 0.55, alpha = 0.62, show.legend = FALSE
                ) +
                ggiraph::geom_point_interactive(size = 2.9, alpha = 0.95) +
                ggplot2::facet_wrap(~side, nrow = 1, drop = FALSE) +
                ggplot2::scale_color_manual(
                    values = state_pal,
                    name = NULL,
                    breaks = c("Overlap", "Gap"),
                    labels = c("Overlap", "Gap")
                ) +
                ggplot2::scale_x_continuous(
                    labels = scales::label_number(big.mark = ",")
                ) +
                ggplot2::scale_y_discrete(labels = if (use_label_panel) NULL else axis_label_map) +
                ggplot2::labs(
                    title = "Genomic Context: Nearest Neighbor Distance",
                    subtitle = "Signed edge-to-edge distance (bp): negative = overlap; zero/positive = gap",
                    x = "Distance to nearest neighboring gene (bp)",
                    y = NULL
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    legend.position = "top",
                    strip.text = ggplot2::element_text(face = "bold"),
                    panel.grid.major.y = ggplot2::element_blank(),
                    panel.grid.minor = ggplot2::element_blank(),
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            ggobj <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, p, label_width, 4.9)
            } else {
                p
            }

            safe_girafe(
                ggobj = ggobj,
                width_svg = 9.8,
                height_svg = analytics_svg_height(
                    n_genes,
                    min_h = 3.0, max_h = dens$max_h, base = 2.0, per_item = dens$per_item
                ),
                transport_label = paste0(mode, "_context_chart"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("stroke:white;stroke-width:1.5px;opacity:0.96;")
            )
        })
    }

    output$homo_context_chart <- render_context_chart(build_homo_summary, mode = "homo", order_input_id = "homo_context_order")
    output$ortho_context_chart <- render_context_chart(build_ortho_summary, mode = "ortho", order_input_id = "ortho_context_order")

    # ============================================================
    # PHASE 3 — Analytics: Exon Length Distribution
    # ============================================================
    render_exon_dist_chart <- function(df_reactive, ids_reactive, filedata_fn, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            ids <- ids_reactive()
            shiny::req(length(ids) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }

            id_chars <- as.character(ids)
            fd_list <- filedata_fn()

            # Labels from summary with stable id mapping, then ordered by selected metric.
            map_n <- min(length(id_chars), nrow(df))
            shiny::req(map_n > 0)
            df_lbl <- get_cached_analytics_prepared_df(
                df[seq_len(map_n), , drop = FALSE],
                mode = mode,
                order_mode = order_mode
            ) %>%
                dplyr::mutate(plot_id_chr = id_chars[seq_len(map_n)]) %>%
                dplyr::mutate(plot_id_chr = as.character(plot_id_chr))

            # Build long-form df: one row per exon
            all_exons <- do.call(rbind,  Filter(Negate(is.null), lapply(id_chars, function(pid) {
                fd <- fd_list[[pid]]
                get_cached_exon_lengths_for_plot(pid, mode = mode, file_data = fd)
            })))
            shiny::req(!is.null(all_exons), nrow(all_exons) > 0)

            # Join labels
            all_exons <- dplyr::left_join(all_exons,
                df_lbl[, c("plot_id_chr", "axis_id", "x_label", "x_label_organism")],
                by = "plot_id_chr"
            )
            all_exons <- all_exons[!is.na(all_exons$axis_id), ]
            shiny::req(nrow(all_exons) > 0)

            label_map_exon <- df_lbl %>%
                dplyr::distinct(axis_id, x_label, x_label_organism)
            axis_order <- as.character(label_map_exon$axis_id)
            all_exons$axis_key <- factor(as.character(all_exons$axis_id), levels = axis_order)
            all_exons <- all_exons[!is.na(all_exons$axis_key), , drop = FALSE]
            all_exons$exon_length <- suppressWarnings(as.numeric(all_exons$exon_length))
            all_exons <- all_exons[is.finite(all_exons$exon_length) & all_exons$exon_length > 0, , drop = FALSE]
            shiny::req(nrow(all_exons) > 0)
            exon_group_stats <- all_exons %>%
                dplyr::group_by(axis_key) %>%
                dplyr::summarise(
                    n = dplyr::n(),
                    unique_lengths = dplyr::n_distinct(exon_length),
                    .groups = "drop"
                )
            use_violin <- any(exon_group_stats$n >= 2L & exon_group_stats$unique_lengths >= 2L)

            # Per-point tooltip
            all_exons$tooltip_txt <- paste0(
                "<b>", all_exons$x_label, "</b><br/>",
                ifelse(nzchar(trimws(as.character(all_exons$x_label_organism %||% ""))), paste0("<i>", all_exons$x_label_organism, "</i><br/>"), ""),
                "Exon length: <b>",
                format(round(all_exons$exon_length), big.mark = ","), " bp</b>"
            )

            # Per-boxplot summary tooltip
            box_stats <- all_exons %>%
                dplyr::group_by(axis_key, x_label, x_label_organism) %>%
                dplyr::summarise(
                    n = dplyr::n(),
                    med_bp = median(exon_length, na.rm = TRUE),
                    q25 = quantile(exon_length, 0.25, na.rm = TRUE),
                    q75 = quantile(exon_length, 0.75, na.rm = TRUE),
                    .groups = "drop"
                ) %>%
                dplyr::mutate(box_tip = paste0(
                    "<b>", x_label, "</b><br/>",
                    ifelse(nzchar(trimws(as.character(x_label_organism %||% ""))), paste0("<i>", x_label_organism, "</i><br/>"), ""),
                    "Exons: ", n, "<br/>",
                    "Median: ", format(round(med_bp), big.mark = ","), " bp<br/>",
                    "Q1\u2013Q3: ", format(round(q25), big.mark = ","),
                    " \u2013 ", format(round(q75), big.mark = ","), " bp"
                ))
            all_exons <- dplyr::left_join(all_exons,
                box_stats[, c("axis_key", "box_tip")],
                by = "axis_key"
            )

            n_genes <- length(axis_order)
            dens <- analytics_axis_density(n_genes)
            exon_n_by_axis <- stats::setNames(
                as.integer(box_stats$n),
                as.character(box_stats$axis_key)
            )
            exon_labels_with_n <- analytics_labels_with_n(
                label_map_exon$x_label,
                unname(exon_n_by_axis[as.character(label_map_exon$axis_id)]),
                n_genes
            )
            axis_label_map <- analytics_build_axis_labels(
                exon_labels_with_n, label_map_exon$x_label_organism, label_map_exon$axis_id, n_genes
            )
            label_rows <- analytics_build_label_rows(
                exon_labels_with_n, label_map_exon$x_label_organism, label_map_exon$axis_id, n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(label_map_exon$x_label_organism %||% ""))))
            h_svg <- analytics_svg_height(
                n_genes,
                min_h = 3.4, max_h = dens$max_h, base = 2.3, per_item = dens$per_item
            )
            pt_color <- if (is_cb) "#0072B2" else if (is_dark) "#4A90C4" else "#1565C0"
            violin_fill <- if (is_cb) {
                if (is_dark) "#2F4A61" else "#D6E4EE"
            } else if (is_dark) {
                "#2A3F59"
            } else {
                "#E3F2FD"
            }
            violin_line <- if (is_cb) {
                if (is_dark) "#5FA2D9" else "#6BAED6"
            } else if (is_dark) {
                "#4A90C4"
            } else {
                "#90CAF9"
            }
            box_fill <- if (is_cb) "#E69F00" else "#42A5F5"

            p <- ggplot2::ggplot(
                all_exons,
                ggplot2::aes(x = axis_key, y = exon_length)
            )
            if (isTRUE(use_violin)) {
                p <- p +
                    # Static violin (background shape)
                    ggplot2::geom_violin(
                    fill = violin_fill,
                    color = violin_line,
                    linewidth = 0.4, trim = FALSE, na.rm = TRUE
                    )
            }
            p <- p +
                # Interactive boxplot (IQR on hover)
                ggiraph::geom_boxplot_interactive(
                    ggplot2::aes(tooltip = box_tip, data_id = axis_key),
                    width = 0.14, fill = box_fill, alpha = 0.7,
                    outlier.shape = NA, na.rm = TRUE
                ) +
                # Interactive jitter (individual exons on hover)
                ggiraph::geom_jitter_interactive(
                    ggplot2::aes(
                        tooltip = tooltip_txt,
                        data_id = paste0(
                            axis_key, "_",
                            round(exon_length)
                        )
                    ),
                    width = 0.11, height = 0,
                    size = 1.25, alpha = 0.42, color = pt_color, na.rm = TRUE
                ) +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev(axis_order)) +
                ggplot2::scale_y_log10(
                    labels = scales::label_number(
                        scale_cut = scales::cut_short_scale()
                    ),
                    breaks = scales::trans_breaks("log10", function(x) 10^x)
                ) +
                ggplot2::coord_flip() +
                ggplot2::labs(
                    title = "Exon Length Distribution",
                    subtitle = paste0(
                        "N = ", format(nrow(all_exons), big.mark = ","), " exons \u00b7 ",
                        "Log\u2081\u2080 scale \u00b7 box = IQR \u00b7",
                        " line = median \u00b7 dots = individual exons"
                    ),
                    x = NULL, y = "Exon length (bp)"
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            ggobj <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, p, label_width, 4.7)
            } else {
                p
            }

            safe_girafe(
                ggobj = ggobj,
                width_svg = 9.4, height_svg = h_svg,
                transport_label = paste0(mode, "_exon_length_distribution"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("r:3.4px;opacity:0.88;stroke-width:1.1px;")
            )
        })
    }

    # ============================================================
    # PHASE 3 — Analytics: Intron Length Distribution
    # ============================================================
    render_intron_dist_chart <- function(df_reactive, ids_reactive, filedata_fn, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            ids <- ids_reactive()
            shiny::req(length(ids) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }

            id_chars <- as.character(ids)
            fd_list <- filedata_fn()

            map_n <- min(length(id_chars), nrow(df))
            shiny::req(map_n > 0)
            df_lbl <- get_cached_analytics_prepared_df(
                df[seq_len(map_n), , drop = FALSE],
                mode = mode,
                order_mode = order_mode
            ) %>%
                dplyr::mutate(plot_id_chr = id_chars[seq_len(map_n)]) %>%
                dplyr::mutate(plot_id_chr = as.character(plot_id_chr))

            all_introns <- do.call(rbind, Filter(Negate(is.null), lapply(id_chars, function(pid) {
                fd <- fd_list[[pid]]
                get_cached_intron_lengths_for_plot(pid, mode = mode, file_data = fd)
            })))
            if (is.null(all_introns) || !is.data.frame(all_introns) || nrow(all_introns) == 0L) {
                return(girafe_msg_plot("No introns detected for these entries", dark = is_dark))
            }

            all_introns <- dplyr::left_join(
                all_introns,
                df_lbl[, c("plot_id_chr", "axis_id", "x_label", "x_label_organism")],
                by = "plot_id_chr"
            )
            all_introns <- all_introns[!is.na(all_introns$axis_id), , drop = FALSE]
            if (nrow(all_introns) == 0L) {
                return(girafe_msg_plot("No introns detected for these entries", dark = is_dark))
            }

            label_map_intron <- df_lbl %>%
                dplyr::distinct(axis_id, x_label, x_label_organism)
            axis_order_all <- as.character(label_map_intron$axis_id)
            all_introns$axis_key <- factor(as.character(all_introns$axis_id), levels = axis_order_all)
            all_introns <- all_introns[!is.na(all_introns$axis_key), , drop = FALSE]
            all_introns$intron_length <- suppressWarnings(as.numeric(all_introns$intron_length))
            all_introns <- all_introns[is.finite(all_introns$intron_length) & all_introns$intron_length > 0, , drop = FALSE]
            if (nrow(all_introns) == 0L) {
                return(girafe_msg_plot("No introns detected for these entries", dark = is_dark))
            }
            axis_order <- axis_order_all[axis_order_all %in% unique(as.character(all_introns$axis_id))]
            label_map_intron_plot <- label_map_intron[as.character(label_map_intron$axis_id) %in% axis_order, , drop = FALSE]

            intron_stats <- all_introns %>%
                dplyr::group_by(axis_key, x_label, x_label_organism) %>%
                dplyr::summarise(
                    n = dplyr::n(),
                    total_bp = sum(intron_length, na.rm = TRUE),
                    med_bp = median(intron_length, na.rm = TRUE),
                    q25 = quantile(intron_length, 0.25, na.rm = TRUE),
                    q75 = quantile(intron_length, 0.75, na.rm = TRUE),
                    unique_lengths = dplyr::n_distinct(intron_length),
                    .groups = "drop"
                ) %>%
                dplyr::mutate(box_tip = paste0(
                    "<b>", x_label, "</b><br/>",
                    ifelse(nzchar(trimws(as.character(x_label_organism %||% ""))), paste0("<i>", x_label_organism, "</i><br/>"), ""),
                    "Introns: ", n, "<br/>",
                    "Total intronic bp: ", format(round(total_bp), big.mark = ","), " bp<br/>",
                    "Median: ", format(round(med_bp), big.mark = ","), " bp<br/>",
                    "Q1\u2013Q3: ", format(round(q25), big.mark = ","),
                    " \u2013 ", format(round(q75), big.mark = ","), " bp"
                ))
            all_introns <- dplyr::left_join(
                all_introns,
                intron_stats[, c("axis_key", "n", "total_bp", "box_tip")],
                by = "axis_key"
            )
            all_introns$tooltip_txt <- paste0(
                "<b>", all_introns$x_label, "</b><br/>",
                ifelse(nzchar(trimws(as.character(all_introns$x_label_organism %||% ""))), paste0("<i>", all_introns$x_label_organism, "</i><br/>"), ""),
                "Intron ", all_introns$intron_n, " of ", all_introns$n, "<br/>",
                "Position: ", format(round(all_introns$intron_start), big.mark = ","), " \u2013 ",
                format(round(all_introns$intron_end), big.mark = ","), "<br/>",
                "Length: <b>", format(round(all_introns$intron_length), big.mark = ","), " bp</b><br/>",
                "Total intronic bp: ", format(round(all_introns$total_bp), big.mark = ","), " bp"
            )

            intron_group_stats <- all_introns %>%
                dplyr::group_by(axis_key) %>%
                dplyr::summarise(
                    n = dplyr::n(),
                    unique_lengths = dplyr::n_distinct(intron_length),
                    .groups = "drop"
                )
            use_violin <- any(intron_group_stats$n >= 2L & intron_group_stats$unique_lengths >= 2L)

            n_genes <- length(axis_order)
            n_with_introns <- dplyr::n_distinct(as.character(all_introns$axis_key))
            omitted_no_introns <- max(0L, nrow(label_map_intron) - n_with_introns)
            dens <- analytics_axis_density(n_genes)
            intron_n_by_axis <- stats::setNames(
                as.integer(intron_stats$n),
                as.character(intron_stats$axis_key)
            )
            intron_labels_with_n <- analytics_labels_with_n(
                label_map_intron_plot$x_label,
                unname(intron_n_by_axis[as.character(label_map_intron_plot$axis_id)]),
                n_genes
            )
            axis_label_map <- analytics_build_axis_labels(
                intron_labels_with_n, label_map_intron_plot$x_label_organism, label_map_intron_plot$axis_id, n_genes
            )
            label_rows <- analytics_build_label_rows(
                intron_labels_with_n, label_map_intron_plot$x_label_organism, label_map_intron_plot$axis_id, n_genes
            )
            use_label_panel <- any(nzchar(trimws(as.character(label_map_intron_plot$x_label_organism %||% ""))))
            h_svg <- analytics_svg_height(
                n_genes,
                min_h = 3.4, max_h = dens$max_h, base = 2.3, per_item = dens$per_item
            )
            pt_color <- if (is_cb) "#E69F00" else if (is_dark) "#D0B86B" else "#8D6E00"
            violin_fill <- if (is_cb) {
                if (is_dark) "#4A3E22" else "#F4E8BF"
            } else if (is_dark) {
                "#343A40"
            } else {
                "#ECEFF1"
            }
            violin_line <- if (is_cb) {
                if (is_dark) "#D9B75F" else "#D6A63A"
            } else if (is_dark) {
                "#8FA1B0"
            } else {
                "#B0BEC5"
            }
            box_fill <- if (is_cb) "#0072B2" else "#78909C"

            p <- ggplot2::ggplot(
                all_introns,
                ggplot2::aes(x = axis_key, y = intron_length)
            )
            if (isTRUE(use_violin)) {
                p <- p +
                    ggplot2::geom_violin(
                        fill = violin_fill,
                        color = violin_line,
                        linewidth = 0.4, trim = FALSE, na.rm = TRUE
                    )
            }
            p <- p +
                ggiraph::geom_boxplot_interactive(
                    ggplot2::aes(tooltip = box_tip, data_id = axis_key),
                    width = 0.14, fill = box_fill, alpha = 0.7,
                    outlier.shape = NA, na.rm = TRUE
                ) +
                ggiraph::geom_jitter_interactive(
                    ggplot2::aes(
                        tooltip = tooltip_txt,
                        data_id = paste0(axis_key, "_", intron_n, "_", round(intron_length))
                    ),
                    width = 0.11, height = 0,
                    size = 1.25, alpha = 0.48, color = pt_color, na.rm = TRUE
                ) +
                ggplot2::scale_x_discrete(labels = if (use_label_panel) NULL else axis_label_map, limits = rev(axis_order)) +
                ggplot2::scale_y_log10(
                    labels = scales::label_number(scale_cut = scales::cut_short_scale()),
                    breaks = scales::trans_breaks("log10", function(x) 10^x)
                ) +
                ggplot2::coord_flip() +
                ggplot2::labs(
                    title = "Intron Length Distribution",
                    subtitle = paste0(
                        "N = ", format(nrow(all_introns), big.mark = ","), " introns \u00b7 ",
                        "Log\u2081\u2080 scale \u00b7 box = IQR \u00b7 line = median \u00b7 dots = individual introns",
                        if (omitted_no_introns > 0L) {
                            paste0(" \u00b7 omitted ", omitted_no_introns, " no-intron entr", ifelse(omitted_no_introns == 1L, "y", "ies"))
                        } else {
                            ""
                        }
                    ),
                    x = NULL, y = "Intron length (bp)"
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.y = if (use_label_panel) ggplot2::element_blank() else ggplot2::element_text(size = dens$axis_text_size, hjust = 1),
                    axis.ticks.y = ggplot2::element_blank(),
                    plot.margin = if (use_label_panel) ggplot2::margin(6, 8, 6, -16) else ggplot2::margin(6, 8, 6, 8)
                )

            ggobj <- if (use_label_panel) {
                label_plot <- analytics_label_panel_plot(label_rows, dark = is_dark, text_size = dens$axis_text_size)
                label_width <- analytics_label_panel_width(label_rows)
                analytics_compose_with_label_panel(label_plot, p, label_width, 4.7)
            } else {
                p
            }

            safe_girafe(
                ggobj = ggobj,
                width_svg = 9.4, height_svg = h_svg,
                transport_label = paste0(mode, "_intron_length_distribution"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("r:3.4px;opacity:0.88;stroke-width:1.1px;")
            )
        })
    }

    # ============================================================
    # PHASE 3 — Analytics: GC% vs Gene Length Scatter
    # ============================================================
    render_scatter_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode)
            df_prep <- get_cached_scatter_prepared_df(df, order_mode = order_mode)
            shiny::req(nrow(df_prep) > 0)
            scatter_cache_key <- paste(
                "analytics-scatter-render-v6",
                tolower(trimws(as.character(mode %||% "homo"))),
                tolower(trimws(as.character(order_mode %||% "load"))),
                if (isTRUE(is_dark)) "dark" else "light",
                if (isTRUE(is_cb)) "cb" else "std",
                as.character(attr(df, "analytics_cache_key") %||% analytics_df_fingerprint(df)),
                sep = "||"
            )
            cached_scatter <- cache_env_get(
                analyticsScatterRenderCache,
                scatter_cache_key,
                default = NULL
            )
            if (!is.null(cached_scatter)) {
                return(cached_scatter)
            }

            n_pts <- nrow(df_prep)
            pt_pal <- analytics_discrete_palette(n_pts, colorblind = is_cb)
            label_size <- if (n_pts >= 20) 1.95 else 2.18

            p <- ggplot2::ggplot(
                df_prep,
                ggplot2::aes(
                    x = gc, y = len_bp,
                    size = n_exons,
                    fill = x_label,
                    tooltip = tooltip_txt,
                    data_id = data_id_lbl
                )
            ) +
                ggiraph::geom_point_interactive(
                    shape = 21,
                    color = if (is_dark) "#DCE8F5" else "#FFFFFF",
                    stroke = 1.05,
                    alpha = 0.9
                ) +
                ggplot2::geom_point(
                    ggplot2::aes(x = gc, y = len_bp),
                    inherit.aes = FALSE,
                    shape = 16,
                    size = if (n_pts >= 20) 1.05 else 1.25,
                    color = if (is_dark) "#F4FAFF" else "#1F2F3E",
                    alpha = 0.95,
                    show.legend = FALSE
                ) +
                ggrepel::geom_label_repel(
                    data = df_prep,
                    ggplot2::aes(x = gc, y = len_bp, label = scatter_label_plotmath),
                    parse = TRUE,
                    size = label_size,
                    fontface = "plain",
                    lineheight = 0.72,
                    label.size = 0.2,
                    label.r = grid::unit(0.15, "lines"),
                    label.padding = grid::unit(0.07, "lines"),
                    box.padding = grid::unit(0.26, "lines"),
                    point.padding = grid::unit(0.48, "lines"),
                    min.segment.length = 0,
                    max.overlaps = Inf,
                    force = if (n_pts >= 20) 3.2 else 2.1,
                    force_pull = 0.14,
                    seed = 123,
                    color = if (is_dark) "#D0E4F0" else "#546E7A",
                    fill = if (is_dark) scales::alpha("#13283B", 0.86) else scales::alpha("#FFFFFF", 0.9),
                    segment.color = if (is_dark) "#4A5E70" else "#B0BEC5",
                    segment.alpha = 0.8,
                    segment.size = 0.25,
                    inherit.aes = FALSE
                ) +
                ggplot2::scale_x_continuous(
                    expand = ggplot2::expansion(mult = c(0.06, 0.16))
                ) +
                ggplot2::scale_y_continuous(
                    expand = ggplot2::expansion(mult = c(0.05, 0.24)),
                    labels = scales::label_number(
                        scale_cut = scales::cut_short_scale()
                    )
                ) +
                ggplot2::scale_size_continuous(
                    range = c(2.6, 8.5),
                    name = "Exon\ncount",
                    breaks = scales::pretty_breaks(4),
                    guide = ggplot2::guide_legend(
                        override.aes = list(
                            color = if (is_dark) "#A8C5DA" else "#546E7A",
                            fill  = if (is_dark) "#2A3F59" else "#D5E0EA",
                            alpha = 1
                        )
                    )
                ) +
                ggplot2::scale_fill_manual(values = pt_pal, guide = "none") +
                ggplot2::labs(
                    title = "GC Content vs Gene Length",
                    subtitle = "Bubble size = number of exons",
                    x = "GC content (%)", y = "Gene length (bp)"
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    legend.position = "right",
                    axis.text = ggplot2::element_text(size = 7.7),
                    axis.title = ggplot2::element_text(size = 8.4),
                    legend.text = ggplot2::element_text(size = 7.0),
                    legend.title = ggplot2::element_text(size = 7.1),
                    plot.title = ggplot2::element_text(size = 11.2, face = "bold", hjust = 0.5),
                    plot.subtitle = ggplot2::element_text(size = 8.7, hjust = 0.5)
                )

            scatter_plot <- safe_girafe(
                ggobj = p,
                width_svg = 8.2,
                height_svg = analytics_svg_height(
                    n_pts,
                    min_h = 3.6, max_h = 5.8, base = 3.0, per_item = 0.2
                ),
                transport_label = paste0(mode, "_gc_length_scatter"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("stroke:white;stroke-width:2.1px;opacity:0.96;")
            )
            cache_env_set(
                analyticsScatterRenderCache,
                scatter_cache_key,
                scatter_plot,
                max_size = 16L
            )
            scatter_plot
        })
    }

    # Wire Phase 3 outputs
    # exon_dist and scatter are phase-2 charts: their df_reactive is wrapped in a
    # gate that requires homoAnalyticsPhase2 / orthoAnalyticsPhase2 to be TRUE before
    # reading build_*_summary. This defers them to a separate flush cycle (~450 ms
    # after analytics opens), so lighter charts reach the browser first.
    output$homo_exon_dist_chart <- render_exon_dist_chart(
        reactive({ req(isTRUE(homoAnalyticsPhase2())); build_homo_summary() }),
        sortedPlotIdsHomologous,
        function() fileDataHomologous(),
        mode = "homo",
        order_input_id = "homo_exon_dist_order"
    )
    output$ortho_exon_dist_chart <- render_exon_dist_chart(
        reactive({ req(isTRUE(orthoAnalyticsPhase2())); build_ortho_summary() }),
        sortedPlotIdsOrthologous,
        function() fileDataOrthologous(),
        mode = "ortho",
        order_input_id = "ortho_exon_dist_order"
    )
    output$homo_intron_dist_chart <- render_intron_dist_chart(
        reactive({ req(isTRUE(homoAnalyticsPhase2())); build_homo_summary() }),
        sortedPlotIdsHomologous,
        function() fileDataHomologous(),
        mode = "homo",
        order_input_id = "homo_intron_dist_order"
    )
    output$ortho_intron_dist_chart <- render_intron_dist_chart(
        reactive({ req(isTRUE(orthoAnalyticsPhase2())); build_ortho_summary() }),
        sortedPlotIdsOrthologous,
        function() fileDataOrthologous(),
        mode = "ortho",
        order_input_id = "ortho_intron_dist_order"
    )
    output$homo_scatter_chart <- render_scatter_chart(
        reactive({ req(isTRUE(homoAnalyticsPhase2())); build_homo_summary() }),
        mode = "homo",
        order_input_id = "homo_scatter_order"
    )
    output$ortho_scatter_chart <- render_scatter_chart(
        reactive({ req(isTRUE(orthoAnalyticsPhase2())); build_ortho_summary() }),
        mode = "ortho",
        order_input_id = "ortho_scatter_order"
    )

    # ============================================================
    # PHASE 5 — Comparative Deep Analytics: Heatmap
    # ============================================================
    render_heatmap_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_lab <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode)

            if (nrow(df_lab) < 2) {
                return(girafe_msg_plot(
                    "Load \u22652 genes to compare metrics in the heatmap",
                    is_dark
                ))
            }

            metrics_raw <- c(
                "Gene_Length_bp", "Transcript_Length_bp",
                "Exons", "Introns",
                "GC_Content_pct", "CDS_to_Tx_pct",
                "Exonic_bp", "CDS_bp"
            )
            log_cols <- c(
                "Gene_Length_bp", "Transcript_Length_bp",
                "Exonic_bp", "CDS_bp"
            )
            short_lbl <- c(
                Gene_Length_bp       = "Gene len",
                Transcript_Length_bp = "Tx len",
                Exons                = "Exons",
                Introns              = "Introns",
                GC_Content_pct       = "GC %",
                CDS_to_Tx_pct        = "CDS/Tx %",
                Exonic_bp            = "Exonic bp",
                CDS_bp               = "CDS bp"
            )
            pct_cols <- c("GC_Content_pct", "CDS_to_Tx_pct")

            # Extract + optionally log10-transform
            mat <- get_cached_analytics_metric_matrix(df_lab, metrics_raw = metrics_raw, log_cols = log_cols)

            # Z-score per column (skip constant columns)
            mat_z <- apply(mat, 2, function(x) {
                s <- sd(x, na.rm = TRUE)
                if (!is.finite(s) || s == 0) {
                    return(rep(0, length(x)))
                }
                (x - mean(x, na.rm = TRUE)) / s
            })

            n_genes <- nrow(df_lab)
            n_metrics <- length(metrics_raw)
            dens <- analytics_axis_density(n_genes)
            axis_label_map <- analytics_build_axis_labels(
                df_lab$x_label, df_lab$x_label_organism,
                levels(df_lab$axis_id), n_genes
            )

            # Build long df
            df_long <- do.call(rbind,  lapply(seq_len(n_genes), function(i) {
                lbl <- df_lab$x_label[i]
                axis_id <- df_lab$axis_id[i]
                do.call(rbind,  lapply(seq_along(metrics_raw), function(j) {
                    m <- metrics_raw[j]
                    raw <- suppressWarnings(as.numeric(df_lab[[m]][i]))
                    z <- mat_z[i, j]
                    fmt_raw <- if (m %in% pct_cols) {
                        paste0(round(raw, 1), "%")
                    } else if (m %in% log_cols) {
                        format(round(raw), big.mark = ",")
                    } else {
                        as.character(round(raw))
                    }
                    data.frame(
                        gene = axis_id,
                        metric = factor(short_lbl[m],
                            levels = rev(short_lbl)
                        ),
                        z_score = z,
                        tip = paste0(
                            "<b>", lbl, "</b><br/>",
                            short_lbl[m], ": <b>", fmt_raw, "</b><br/>",
                            "Z-score: ", round(z, 2)
                        ),
                        stringsAsFactors = FALSE
                    )
                }))
            }))

            div_pal <- analytics_diverging_palette(colorblind = is_cb, dark = is_dark)
            z_rng <- suppressWarnings(range(df_long$z_score, na.rm = TRUE, finite = TRUE))
            if (!all(is.finite(z_rng)) || z_rng[1] >= z_rng[2]) {
                z_rng <- c(-1, 1)
            }
            z_pal <- scales::div_gradient_pal(
                low = div_pal$low,
                mid = div_pal$mid,
                high = div_pal$high,
                space = "Lab"
            )
            z_scaled <- scales::rescale_mid(df_long$z_score, to = c(0, 1), from = z_rng, mid = 0)
            z_scaled <- pmax(0, pmin(1, z_scaled))
            df_long$fill_hex <- ifelse(is.finite(df_long$z_score), z_pal(z_scaled), div_pal$na)
            df_long$label_col <- analytics_contrast_text_color(
                df_long$fill_hex,
                light_text = if (is_dark) "#EAF3FA" else "#FFFFFF",
                dark_text = if (is_dark) "#1F2A35" else "#2A3440",
                luminance_cutoff = if (is_dark) 0.60 else 0.57
            )

            p <- ggplot2::ggplot(
                df_long,
                ggplot2::aes(
                    x = gene, y = metric,
                    fill = z_score,
                    tooltip = tip,
                    data_id = paste0(gene, "_", metric)
                )
            ) +
                ggiraph::geom_tile_interactive(
                    color     = if (is_dark) "#1A2B3C" else "white",
                    linewidth = 0.8
                ) +
                ggiraph::geom_text_interactive(
                    ggplot2::aes(
                        label = ifelse(is.finite(z_score),
                            sprintf("%.1f", z_score), ""
                        ),
                        tooltip = tip,
                        data_id = paste0(gene, "_", metric),
                        color = label_col
                    ),
                    size = 2.65
                ) +
                ggplot2::scale_color_identity(guide = "none") +
                ggplot2::scale_fill_gradient2(
                    low      = div_pal$low,
                    mid      = div_pal$mid,
                    high     = div_pal$high,
                    midpoint = 0,
                    name     = "Z-score",
                    na.value = div_pal$na
                ) +
                ggplot2::scale_x_discrete(labels = axis_label_map) +
                ggplot2::labs(
                    title = "Gene Metrics Heatmap",
                    subtitle = "Z-score normalized per metric (blue = below avg, red = above avg)",
                    x = NULL, y = NULL
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.x = ggplot2::element_text(angle = 35, hjust = 1, size = dens$heatmap_x_size),
                    axis.text.y = ggplot2::element_text(size = 7.5),
                    legend.text = ggplot2::element_text(size = 7.0),
                    legend.title = ggplot2::element_text(size = 7.1),
                    plot.title = ggplot2::element_text(size = 14.2, face = "bold", hjust = 0.5),
                    plot.subtitle = ggplot2::element_text(size = 10.0, hjust = 0.5),
                    panel.grid = ggplot2::element_blank(),
                    plot.margin = ggplot2::margin(8, 12, 24, 10)
                )

            safe_girafe(
                ggobj = p,
                width_svg = max(8.2, min(11.2, 7.2 + n_genes * 0.08)),
                height_svg = max(3.8, n_metrics * 0.58 + 1.9),
                transport_label = paste0(mode, "_metrics_heatmap"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("stroke:white;stroke-width:1.6px;opacity:0.9;")
            )
        })
    }

    # ============================================================
    # PHASE 5 — Comparative Deep Analytics: Radar
    # ============================================================
    render_radar_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            order_mode <- if (!is.null(order_input_id) && nzchar(as.character(order_input_id %||% ""))) {
                as.character(input[[order_input_id]] %||% "load")
            } else {
                "load"
            }
            df_lab <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = order_mode)

            if (nrow(df_lab) < 2) {
                return(girafe_msg_plot(
                    "Load \u22652 genes to compare radar profiles",
                    is_dark
                ))
            }

            radar_scene <- get_cached_radar_scene(df_lab, mode = mode)
            if (!identical(radar_scene$status, "ok")) {
                return(girafe_msg_plot(
                    "Radar requires at least 2 genes with complete metrics",
                    is_dark
                ))
            }
            df_lab <- radar_scene$df_lab
            n_genes <- radar_scene$n_genes
            dropped_genes <- radar_scene$dropped_genes
            mode_txt <- tolower(trimws(as.character(mode %||% "homo")))
            show_legend_organism <- isTRUE(radar_scene$show_legend_organism) || identical(mode_txt, "ortho")
            legend_ncol <- radar_scene$legend_ncol
            radar_height <- radar_scene$radar_height
            spokes_df <- radar_scene$spokes_df
            poly_df <- radar_scene$poly_df
            gene_pal <- analytics_discrete_palette(n_genes, colorblind = is_cb)
            names(gene_pal) <- df_lab$radar_display
            radar_render_key <- paste(
                "analytics-radar-render-v9",
                mode_txt,
                tolower(trimws(as.character(order_mode %||% "load"))),
                if (isTRUE(is_dark)) "dark" else "light",
                if (isTRUE(is_cb)) "cb" else "std",
                if (show_legend_organism) "with-org" else "gene-only",
                as.character(attr(df_lab, "analytics_cache_key") %||% analytics_df_fingerprint(df_lab)),
                sep = "||"
            )
            cached_radar <- cache_env_get(analyticsRadarRenderCache, radar_render_key, default = NULL)
            if (!is.null(cached_radar)) {
                return(cached_radar)
            }

            grid_col <- if (is_dark) "#2A3F59" else "#E0E7ED"
            spoke_col <- if (is_dark) "#3A5570" else "#CFD8DC"
            base_text <- if (is_dark) "#D0E4F0" else "#343A40"
            vertex_fill <- if (is_dark) "#1A2B3C" else "#FFFFFF"

            p <- ggplot2::ggplot() +
                # Background circles
                ggplot2::geom_path(
                    data = radar_scene$grid_df,
                    ggplot2::aes(x = x, y = y, group = r),
                    color = grid_col, linewidth = 0.4
                ) +
                # Grid level labels
                ggplot2::annotate(
                    "text",
                    x = radar_scene$grid_levels * spokes_df$xend[1] + 0.04,
                    y = radar_scene$grid_levels * spokes_df$yend[1],
                    label = paste0(as.integer(radar_scene$grid_levels * 100), "%"),
                    size = 1.95, color = spoke_col, hjust = 0
                ) +
                # Spokes
                ggplot2::geom_segment(
                    data = spokes_df,
                    ggplot2::aes(x = 0, y = 0, xend = xend, yend = yend),
                    color = spoke_col, linewidth = 0.5
                ) +
                # Gene filled polygons
                ggiraph::geom_polygon_interactive(
                    data = poly_df,
                    ggplot2::aes(
                        x = x, y = y, group = gene,
                        fill = gene,
                        tooltip = tip_poly,
                        data_id = gene
                    ),
                    alpha = 0.12, linewidth = 0
                ) +
                # Gene outlines
                ggiraph::geom_path_interactive(
                    data = poly_df,
                    ggplot2::aes(
                        x = x, y = y, group = gene,
                        color = gene,
                        tooltip = tip_poly,
                        data_id = gene
                    ),
                    linewidth = 1.0
                ) +
                # Vertex points (per-metric tooltip)
                ggiraph::geom_point_interactive(
                    data = poly_df[!poly_df$is_close, ],
                    ggplot2::aes(
                        x = x, y = y, color = gene,
                        tooltip = tip_pt,
                        data_id = paste0(gene, "_", metric)
                    ),
                    size = 2.3, shape = 21, fill = vertex_fill, stroke = 1.1
                ) +
                # Axis labels
                ggplot2::geom_text(
                    data = spokes_df,
                    ggplot2::aes(x = lbl_x, y = lbl_y, label = lbl),
                    size = 2.45, color = base_text, hjust = 0.5,
                    lineheight = 0.82
                ) +
                ggplot2::scale_fill_manual(values = gene_pal, guide = "none") +
                ggplot2::scale_color_manual(
                    values = gene_pal,
                    name = NULL,
                    guide = "none"
                ) +
                ggplot2::coord_equal(
                    xlim = c(-1.52, 1.52),
                    ylim = c(-1.52, 1.52)
                ) +
                ggplot2::labs(
                    title = "Gene Profile Radar",
                    subtitle = paste0(
                        "6 metrics normalized to 0\u20131 range per metric",
                        if (dropped_genes > 0L) {
                            paste0(
                                " \u00b7 omitted ", dropped_genes,
                                " incomplete gene", ifelse(dropped_genes == 1L, "", "s")
                            )
                        } else {
                            ""
                        }
                    )
                ) +
                ggplot2::theme_void(base_size = 9.8) +
                ggplot2::theme(
                    plot.background = ggplot2::element_rect(
                        fill  = if (is_dark) "#1A2B3C" else "#FFFFFF",
                        color = NA
                    ),
                    plot.title = ggplot2::element_text(
                        color = base_text, face = "bold", size = 11.1,
                        hjust = 0.5, margin = ggplot2::margin(t = 3, b = 2)
                    ),
                    plot.subtitle = ggplot2::element_text(
                        color = if (is_dark) "#A8C5DA" else "#546E7A",
                        size = 8.5, hjust = 0.5, margin = ggplot2::margin(b = 3)
                    ),
                    plot.margin = ggplot2::margin(10, 8, 0, 8),
                    legend.position = "none"
                )

            legend_cols <- max(1L, as.integer(legend_ncol %||% 1L))
            legend_rows_n <- max(1L, ceiling(n_genes / legend_cols))
            legend_x_vals <- seq(1, by = 1.35, length.out = legend_cols)
            legend_df <- data.frame(
                radar_display = df_lab$radar_display,
                gene = as.character(df_lab$gene_full %||% df_lab$x_label %||% "Gene"),
                organism = trimws(as.character(df_lab$organism_full %||% "")),
                x = legend_x_vals[((seq_len(n_genes) - 1L) %% legend_cols) + 1L],
                y = rev(seq_len(legend_rows_n))[((seq_len(n_genes) - 1L) %/% legend_cols) + 1L],
                stringsAsFactors = FALSE
            )
            legend_org_df <- if (show_legend_organism) {
                legend_df[nzchar(legend_df$organism), , drop = FALSE]
            } else {
                legend_df[FALSE, , drop = FALSE]
            }
            radar_legend_plot <- ggplot2::ggplot(legend_df, ggplot2::aes(x = x, y = y)) +
                ggplot2::geom_segment(
                    ggplot2::aes(
                        x = x - 0.34, xend = x - 0.12,
                        y = y, yend = y,
                        color = radar_display
                    ),
                    linewidth = 1.5,
                    lineend = "round",
                    show.legend = FALSE
                ) +
                ggplot2::geom_point(
                    ggplot2::aes(
                        x = x - 0.23, y = y,
                        color = radar_display
                    ),
                    shape = 21,
                    size = 4.6,
                    stroke = 1.4,
                    fill = vertex_fill,
                    show.legend = FALSE
                ) +
                ggplot2::geom_text(
                    ggplot2::aes(
                        x = x - 0.01,
                        y = y + 0.11,
                        label = gene
                    ),
                    hjust = 0,
                    vjust = 0.5,
                    size = 5.9 / 2.9,
                    color = base_text,
                    family = "sans"
                ) +
                ggplot2::scale_color_manual(values = gene_pal, guide = "none") +
                ggplot2::coord_cartesian(
                    xlim = c(0.5, max(legend_x_vals) + 0.62),
                    ylim = c(0.45, legend_rows_n + 0.45),
                    clip = "off"
                ) +
                ggplot2::theme_void() +
                ggplot2::theme(
                    plot.background = ggplot2::element_rect(
                        fill = if (is_dark) "#1A2B3C" else "#FFFFFF",
                        color = NA
                    ),
                    panel.background = ggplot2::element_rect(
                        fill = if (is_dark) "#1A2B3C" else "#FFFFFF",
                        color = NA
                    ),
                    plot.margin = ggplot2::margin(-2, 8, 4, 8)
                )

            if (nrow(legend_org_df) > 0L) {
                radar_legend_plot <- radar_legend_plot +
                    ggplot2::geom_text(
                        data = legend_org_df,
                        ggplot2::aes(
                            x = x - 0.01,
                            y = y - 0.11,
                            label = organism
                        ),
                        hjust = 0,
                        vjust = 0.5,
                        size = 5.55 / 2.9,
                        color = base_text,
                        family = "sans",
                        fontface = "italic"
                    )
            }

            radar_combined <- (p / radar_legend_plot) +
                patchwork::plot_layout(
                    heights = c(4.8, 0.68 + legend_rows_n * 0.54)
                )

            radar_plot <- safe_girafe(
                ggobj = radar_combined,
                width_svg = 6.8, height_svg = radar_height,
                transport_label = paste0(mode, "_metrics_radar"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("stroke-width:2px;opacity:0.96;")
            )
            cache_env_set(
                analyticsRadarRenderCache,
                radar_render_key,
                radar_plot,
                max_size = 16L
            )
            radar_plot
        })
    }

    # ============================================================
    # PHASE 5 — Comparative Deep Analytics: Correlation Matrix
    # ============================================================
    render_corr_chart <- function(df_reactive, mode = "homo", order_input_id = NULL) {
        renderGirafe({
            df <- df_reactive()
            shiny::req(!is.null(df), nrow(df) > 0)
            is_dark <- is_dark_theme_active()
            is_cb <- is_colorblind_mode_active()
            corr_order_mode <- tolower(trimws(as.character(input[[order_input_id]] %||% "metric_default")))

            if (nrow(df) < 3) {
                return(girafe_msg_plot(
                    "Load \u22653 genes to compute a meaningful correlation matrix",
                    is_dark
                ))
            }

            df <- get_cached_analytics_prepared_df(df, mode = mode, order_mode = "load")
            corr_scene <- get_cached_corr_scene(df, mode = mode, corr_order_mode = corr_order_mode)
            shiny::req(identical(corr_scene$status, "ok"))
            n_m <- corr_scene$n_m
            df_cor <- corr_scene$df_cor
            df_cor_ok <- corr_scene$df_cor_ok
            df_cor_na <- corr_scene$df_cor_na
            corr_render_key <- paste(
                "analytics-corr-render-v1",
                tolower(trimws(as.character(mode %||% "homo"))),
                corr_order_mode,
                if (isTRUE(is_dark)) "dark" else "light",
                if (isTRUE(is_cb)) "cb" else "std",
                as.character(attr(df, "analytics_cache_key") %||% analytics_df_fingerprint(df)),
                sep = "||"
            )
            cached_corr <- cache_env_get(analyticsCorrRenderCache, corr_render_key, default = NULL)
            if (!is.null(cached_corr)) {
                return(cached_corr)
            }

            div_pal <- analytics_diverging_palette(colorblind = is_cb, dark = is_dark)
            r_scaled <- pmax(0, pmin(1, scales::rescale(df_cor$r, to = c(0, 1), from = c(-1, 1))))
            df_cor$fill_hex <- ifelse(
                is.finite(df_cor$r),
                scales::div_gradient_pal(
                    low = div_pal$low,
                    mid = div_pal$mid,
                    high = div_pal$high,
                    space = "Lab"
                )(r_scaled),
                div_pal$na
            )
            df_cor$label_col <- analytics_contrast_text_color(
                df_cor$fill_hex,
                light_text = if (is_dark) "#EAF3FA" else "#FFFFFF",
                dark_text = if (is_dark) "#1F2A35" else "#2A3440",
                luminance_cutoff = if (is_dark) 0.60 else 0.57
            )

            p <- ggplot2::ggplot(
                df_cor,
                ggplot2::aes(
                    x = Var1, y = Var2
                )
            ) +
                ggplot2::geom_tile(
                    data = df_cor_na,
                    fill = div_pal$na,
                    color = if (is_dark) "#1A2B3C" else "white",
                    linewidth = 0.6
                ) +
                ggiraph::geom_tile_interactive(
                    data = df_cor_ok,
                    ggplot2::aes(
                        fill = r,
                        tooltip = tip,
                        data_id = data_id
                    ),
                    color = if (is_dark) "#1A2B3C" else "white",
                    linewidth = 0.6
                ) +
                ggplot2::geom_text(
                    ggplot2::aes(
                        label   = r_lbl,
                        color   = label_col
                    ),
                    size = 2.65
                ) +
                ggplot2::scale_color_identity(guide = "none") +
                ggplot2::scale_fill_gradient2(
                    low      = div_pal$low,
                    mid      = div_pal$mid,
                    high     = div_pal$high,
                    midpoint = 0,
                    limits   = c(-1, 1),
                    name     = "r",
                    na.value = div_pal$na
                ) +
                ggplot2::labs(
                    title = "Pairwise Correlation Matrix",
                    subtitle = paste0(
                        "Pearson r across ", nrow(df), " genes",
                        " \u00b7 log\u2081\u2080 applied to bp/count metrics"
                    ),
                    x = NULL, y = NULL
                ) +
                analytics_gg_theme(dark = is_dark) +
                ggplot2::theme(
                    axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, size = 7.3),
                    axis.text.y = ggplot2::element_text(size = 7.3),
                    legend.text = ggplot2::element_text(size = 7.0),
                    legend.title = ggplot2::element_text(size = 7.1),
                    plot.title = ggplot2::element_text(size = 11.1, face = "bold", hjust = 0.5),
                    plot.subtitle = ggplot2::element_text(size = 8.6, hjust = 0.5),
                    panel.grid = ggplot2::element_blank(),
                    plot.margin = ggplot2::margin(8, 12, 20, 10)
                )

            corr_plot <- safe_girafe(
                ggobj = p,
                width_svg = max(4.6, n_m * 0.84 + 1.9),
                height_svg = max(4.6, n_m * 0.84 + 1.9),
                transport_label = paste0(mode, "_correlation_matrix"),
                bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
                options = analytics_girafe_options("stroke:white;stroke-width:1.6px;opacity:0.9;")
            )
            cache_env_set(
                analyticsCorrRenderCache,
                corr_render_key,
                corr_plot,
                max_size = 16L
            )
            corr_plot
        })
    }

    # Wire Phase 5 outputs (tier-3 gated — deepest charts render after tier 2)
    output$homo_heatmap_chart <- render_heatmap_chart(reactive({ req(isTRUE(homoAnalyticsPhase3())); build_homo_summary() }), mode = "homo", order_input_id = "homo_heatmap_order")
    output$ortho_heatmap_chart <- render_heatmap_chart(reactive({ req(isTRUE(orthoAnalyticsPhase3())); build_ortho_summary() }), mode = "ortho", order_input_id = "ortho_heatmap_order")
    output$homo_radar_chart <- render_radar_chart(reactive({ req(isTRUE(homoAnalyticsPhase3())); build_homo_summary() }), mode = "homo", order_input_id = "homo_radar_order")
    output$ortho_radar_chart <- render_radar_chart(reactive({ req(isTRUE(orthoAnalyticsPhase3())); build_ortho_summary() }), mode = "ortho", order_input_id = "ortho_radar_order")
    output$homo_corr_chart <- render_corr_chart(reactive({ req(isTRUE(homoAnalyticsPhase3())); build_homo_summary() }), mode = "homo", order_input_id = "homo_corr_order")
    output$ortho_corr_chart <- render_corr_chart(reactive({ req(isTRUE(orthoAnalyticsPhase3())); build_ortho_summary() }), mode = "ortho", order_input_id = "ortho_corr_order")

    homo_export_summary <- reactive({
        req(homoAnalyticsExportNonce() > 0)
        get_homo_summary_df(perf_context = "HOMO_SUM_EXPORT")
    })
    ortho_export_summary <- reactive({
        req(orthoAnalyticsExportNonce() > 0)
        get_ortho_summary_df(perf_context = "ORTHO_SUM_EXPORT")
    })
    homo_export_plot_ids <- reactive({
        req(homoAnalyticsExportNonce() > 0)
        activePlotIdsHomologous()
    })
    ortho_export_plot_ids <- reactive({
        req(orthoAnalyticsExportNonce() > 0)
        activePlotIdsOrthologous()
    })
    homo_export_filedata <- reactive({
        req(homoAnalyticsExportNonce() > 0)
        fileDataHomologous()
    })
    ortho_export_filedata <- reactive({
        req(orthoAnalyticsExportNonce() > 0)
        fileDataOrthologous()
    })

    output$homo_arch_chart_export <- render_arch_chart(homo_export_summary, mode = "homo", order_input_id = "homo_arch_order")
    output$homo_exon_chart_export <- render_exon_chart(homo_export_summary, mode = "homo", order_input_id = "homo_exon_order")
    output$homo_seq_chart_export <- render_seq_chart(homo_export_summary, mode = "homo", order_input_id = "homo_seq_order")
    output$homo_context_chart_export <- render_context_chart(homo_export_summary, mode = "homo", order_input_id = "homo_context_order")
    output$homo_exon_dist_chart_export <- render_exon_dist_chart(homo_export_summary, homo_export_plot_ids, homo_export_filedata, mode = "homo", order_input_id = "homo_exon_dist_order")
    output$homo_intron_dist_chart_export <- render_intron_dist_chart(homo_export_summary, homo_export_plot_ids, homo_export_filedata, mode = "homo", order_input_id = "homo_intron_dist_order")
    output$homo_scatter_chart_export <- render_scatter_chart(homo_export_summary, mode = "homo", order_input_id = "homo_scatter_order")
    output$homo_heatmap_chart_export <- render_heatmap_chart(homo_export_summary, mode = "homo", order_input_id = "homo_heatmap_order")
    output$homo_radar_chart_export <- render_radar_chart(homo_export_summary, mode = "homo", order_input_id = "homo_radar_order")
    output$homo_corr_chart_export <- render_corr_chart(homo_export_summary, mode = "homo", order_input_id = "homo_corr_order")

    output$ortho_arch_chart_export <- render_arch_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_arch_order")
    output$ortho_exon_chart_export <- render_exon_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_exon_order")
    output$ortho_seq_chart_export <- render_seq_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_seq_order")
    output$ortho_context_chart_export <- render_context_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_context_order")
    output$ortho_exon_dist_chart_export <- render_exon_dist_chart(ortho_export_summary, ortho_export_plot_ids, ortho_export_filedata, mode = "ortho", order_input_id = "ortho_exon_dist_order")
    output$ortho_intron_dist_chart_export <- render_intron_dist_chart(ortho_export_summary, ortho_export_plot_ids, ortho_export_filedata, mode = "ortho", order_input_id = "ortho_intron_dist_order")
    output$ortho_scatter_chart_export <- render_scatter_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_scatter_order")
    output$ortho_heatmap_chart_export <- render_heatmap_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_heatmap_order")
    output$ortho_radar_chart_export <- render_radar_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_radar_order")
    output$ortho_corr_chart_export <- render_corr_chart(ortho_export_summary, mode = "ortho", order_input_id = "ortho_corr_order")

    # ── Charts modal Tab 2: per-gene isoform analytics ────────────
    output$chart_modal_gene_arch    <- render_arch_chart(build_modal_gene_summary,    mode = "modal")
    output$chart_modal_gene_exon    <- render_exon_chart(build_modal_gene_summary,    mode = "modal")
    output$chart_modal_gene_seq     <- render_seq_chart(build_modal_gene_summary,     mode = "modal")
    output$chart_modal_gene_context <- render_context_chart(build_modal_gene_summary, mode = "modal")

    modal_gene_ids_rv      <- reactive(selectedChartIsoformIds())
    modal_gene_filedata_rv <- reactive({
        if (identical(selectedChartContext(), "ortho")) fileDataOrthologous() else fileDataHomologous()
    })
    output$chart_modal_gene_exon_dist <- render_exon_dist_chart(
        df_reactive    = build_modal_gene_summary,
        ids_reactive   = modal_gene_ids_rv,
        filedata_fn    = modal_gene_filedata_rv,
        mode           = "modal",
        order_input_id = NULL
    )
    output$chart_modal_gene_intron_dist <- render_intron_dist_chart(
        df_reactive    = build_modal_gene_summary,
        ids_reactive   = modal_gene_ids_rv,
        filedata_fn    = modal_gene_filedata_rv,
        mode           = "modal",
        order_input_id = NULL
    )

    analytics_output_ids <- c(
        "homo_arch_chart", "homo_exon_chart", "homo_seq_chart",
        "homo_context_chart", "homo_exon_dist_chart", "homo_intron_dist_chart", "homo_scatter_chart",
        "homo_heatmap_chart", "homo_radar_chart", "homo_corr_chart",
        "ortho_arch_chart", "ortho_exon_chart", "ortho_seq_chart",
        "ortho_context_chart", "ortho_exon_dist_chart", "ortho_intron_dist_chart", "ortho_scatter_chart",
        "ortho_heatmap_chart", "ortho_radar_chart", "ortho_corr_chart"
    )
    homo_analytics_output_ids <- analytics_output_ids[startsWith(analytics_output_ids, "homo_")]
    ortho_analytics_output_ids <- analytics_output_ids[startsWith(analytics_output_ids, "ortho_")]
    homo_analytics_tier1_output_ids <- c("homo_arch_chart", "homo_exon_chart", "homo_seq_chart", "homo_context_chart")
    ortho_analytics_tier1_output_ids <- c("ortho_arch_chart", "ortho_exon_chart", "ortho_seq_chart", "ortho_context_chart")
    homo_analytics_tier2_output_ids <- c("homo_exon_dist_chart", "homo_intron_dist_chart", "homo_scatter_chart")
    ortho_analytics_tier2_output_ids <- c("ortho_exon_dist_chart", "ortho_intron_dist_chart", "ortho_scatter_chart")
    homo_analytics_tier3_output_ids <- c("homo_heatmap_chart", "homo_radar_chart", "homo_corr_chart")
    ortho_analytics_tier3_output_ids <- c("ortho_heatmap_chart", "ortho_radar_chart", "ortho_corr_chart")
    homo_analytics_export_output_ids <- paste0(homo_analytics_output_ids, "_export")
    ortho_analytics_export_output_ids <- paste0(ortho_analytics_output_ids, "_export")
    analytics_export_output_ids <- c(homo_analytics_export_output_ids, ortho_analytics_export_output_ids)
    analytics_tab_output_map <- list(
        arch = "arch_chart",
        exon = "exon_chart",
        seq = "seq_chart",
        context = "context_chart",
        exon_dist = "exon_dist_chart",
        intron_dist = "intron_dist_chart",
        scatter = "scatter_chart",
        heatmap = "heatmap_chart",
        radar = "radar_chart",
        corr = "corr_chart"
    )
    set_analytics_output_suspension <- function(output_ids, suspend = TRUE) {
        ids_chr <- as.character(output_ids %||% character(0))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        invisible(lapply(ids_chr, function(output_id) {
            outputOptions(output, output_id, suspendWhenHidden = isTRUE(suspend))
        }))
    }
    activate_analytics_tab <- function(scope = c("homo", "ortho")) {
        scope <- match.arg(scope)
        visible <- if (identical(scope, "homo")) isTRUE(homoAnalyticsVisible()) else isTRUE(orthoAnalyticsVisible())
        all_ids <- if (identical(scope, "homo")) homo_analytics_output_ids else ortho_analytics_output_ids
        if (!isTRUE(visible)) {
            set_analytics_output_suspension(all_ids, suspend = TRUE)
            return(invisible(NULL))
        }
        input_id <- paste0(scope, "_analytics_tabs")
        tab_value <- as.character(input[[input_id]] %||% "arch")
        if (!nzchar(tab_value) || is.null(analytics_tab_output_map[[tab_value]])) {
            tab_value <- "arch"
        }
        selected_output <- paste0(scope, "_", analytics_tab_output_map[[tab_value]])
        set_analytics_output_suspension(all_ids, suspend = TRUE)
        set_analytics_output_suspension(selected_output, suspend = FALSE)
        invisible(selected_output)
    }
    # Default: keep hidden analytics suspended. Analytics charts now render on
    # demand per active tab, so opening the section no longer sends every widget
    # through the Shiny websocket at once.
    set_analytics_output_suspension(analytics_output_ids, suspend = TRUE)
    set_analytics_output_suspension(analytics_export_output_ids, suspend = FALSE)

    # ============================================================
    # PHASE 2 — Per-plot Charts Modal: render functions
    # ============================================================

    # --- A. Structure chart (horizontal stacked bar: CDS | UTR | Intron) ---
    output$chart_modal_structure <- renderGirafe({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        chart_mode <- selectedChartModalMode()
        d <- get_chart_plot_data(pid, ctx)
        req(!is.null(d$file_data), nrow(d$file_data) > 0)
        is_dark <- is_dark_theme_active()
        is_cb <- is_colorblind_mode_active()

        # In tx mode, filter GFF rows to only the specific transcript
        fd <- d$file_data
        chart_label <- "Gene"  # x-axis label
        chart_title <- "Gene Structure Composition"
        if (identical(chart_mode, "tx")) {
            titulo_local <- tryCatch(
                if (identical(ctx, "ortho")) titlesOrthologous()[[pid]] else titlesHomologous()[[pid]],
                error = function(e) ""
            )
            tx_name_local <- trimws(as.character(extract_title_field(titulo_local, "Transcript") %||% ""))
            if (nzchar(tx_name_local)) {
                tx_rows <- grep(tx_name_local, as.character(fd$V9), fixed = TRUE)
                if (length(tx_rows) > 0) fd <- fd[tx_rows, , drop = FALSE]
                chart_label <- tx_name_local
                chart_title <- "Transcript Structure Composition"
            }
        }

        types  <- tolower(trimws(as.character(fd$V3)))
        starts <- suppressWarnings(as.numeric(fd$V4))
        ends   <- suppressWarnings(as.numeric(fd$V5))

        # For tx mode use mRNA/transcript span; for gene mode use gene span
        span_rows <- if (identical(chart_mode, "tx")) {
            mrna_r <- which(types %in% c("mrna", "transcript"))
            if (length(mrna_r) > 0) mrna_r else which(types == "gene")
        } else {
            which(types == "gene")
        }
        exon_rows <- which(types == "exon")
        cds_rows  <- which(types == "cds")
        if (length(exon_rows) == 0) exon_rows <- cds_rows

        gene_len <- if (length(span_rows) > 0) {
            max(ends[span_rows], na.rm = TRUE) - min(starts[span_rows], na.rm = TRUE) + 1
        } else {
            NA_real_
        }
        exon_bp <- if (length(exon_rows) > 0) {
            ex <- unique(data.frame(s = starts[exon_rows], e = ends[exon_rows]))
            ex <- ex[is.finite(ex$s) & is.finite(ex$e), ]
            sum(ex$e - ex$s + 1)
        } else {
            NA_real_
        }
        cds_bp <- if (length(cds_rows) > 0) {
            cd <- unique(data.frame(s = starts[cds_rows], e = ends[cds_rows]))
            cd <- cd[is.finite(cd$s) & is.finite(cd$e), ]
            sum(cd$e - cd$s + 1)
        } else {
            NA_real_
        }

        utr_bp    <- pmax(0, exon_bp - cds_bp, na.rm = TRUE)
        intron_bp <- pmax(0, gene_len - exon_bp, na.rm = TRUE)
        cds_bp    <- pmax(0, cds_bp, na.rm = TRUE)

        req(is.finite(gene_len) && gene_len > 0)

        df <- data.frame(
            Region = factor(c("CDS", "UTR", "Intron"), levels = c("CDS", "UTR", "Intron")),
            bp     = c(cds_bp, utr_bp, intron_bp)
        )
        df$pct <- 100 * df$bp / gene_len
        df$tooltip_txt <- paste0(
            "<b>", df$Region, "</b><br/>",
            format(round(df$bp), big.mark = ","), " bp (",
            round(df$pct, 1), "%)"
        )

        pal <- analytics_named_palette("arch", colorblind = is_cb, dark = is_dark)

        p <- ggplot2::ggplot(
            df,
            ggplot2::aes(
                x = chart_label, y = bp, fill = Region,
                tooltip = tooltip_txt, data_id = Region
            )
        ) +
            ggiraph::geom_col_interactive(color = if (is_dark) "#1A2B3C" else "white", linewidth = 0.5, width = 0.55) +
            ggplot2::coord_flip() +
            ggplot2::scale_fill_manual(values = pal) +
            ggplot2::scale_y_continuous(
                labels = scales::label_number(scale_cut = scales::cut_short_scale())
            ) +
            ggplot2::labs(
                title    = chart_title,
                subtitle = paste0("Total span: ", format(round(gene_len), big.mark = ","), " bp"),
                x = NULL, y = "Base pairs (bp)", fill = "Region"
            ) +
            analytics_gg_theme(dark = is_dark) +
            ggplot2::theme(
                axis.text.y = ggplot2::element_blank(),
                plot.title = ggplot2::element_text(size = 13.5, hjust = 0.5),
                plot.subtitle = ggplot2::element_text(size = 10.5, hjust = 0.5)
            )

        safe_girafe(
            ggobj = p, width_svg = 8, height_svg = 3,
            transport_label = "chart_modal_gene_architecture",
            bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
            options = list(
                ggiraph::opts_hover(css = "opacity:0.85;stroke:white;stroke-width:2px;"),
                ggiraph::opts_tooltip(
                    css = analytics_tooltip_css,
                    use_fill = FALSE,
                    placement = "doc",
                    zindex = 999999,
                    delay_mouseover = 40,
                    delay_mouseout = 120
                ),
                ggiraph::opts_selection(type = "none"),
                ggiraph::opts_toolbar(
                    position = "bottomright",
                    hidden = c("selection", "zoom", "misc")
                ),
                ggiraph::opts_sizing(rescale = TRUE)
            )
        )
    })

    # --- B. Exon Map (lollipop: position vs length) ---
    output$chart_modal_exons <- renderGirafe({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        d <- get_chart_plot_data(pid, ctx)
        req(!is.null(d$file_data), nrow(d$file_data) > 0)
        is_dark <- is_dark_theme_active()
        is_cb <- is_colorblind_mode_active()

        types <- tolower(trimws(as.character(d$file_data$V3)))
        starts <- suppressWarnings(as.numeric(d$file_data$V4))
        ends <- suppressWarnings(as.numeric(d$file_data$V5))

        exon_rows <- which(types == "exon")
        cds_rows <- which(types == "cds")
        use_rows <- if (length(exon_rows) > 0) exon_rows else cds_rows
        req(length(use_rows) > 0)

        ex <- unique(data.frame(start = starts[use_rows], end = ends[use_rows]))
        ex <- ex[is.finite(ex$start) & is.finite(ex$end), ]
        req(nrow(ex) > 0)
        ex <- ex[order(ex$start), ]
        ex$exon_n <- seq_len(nrow(ex))
        ex$length <- ex$end - ex$start + 1
        ex$tooltip_txt <- paste0(
            "<b>Exon ", ex$exon_n, "</b><br/>",
            "Position: ", format(ex$start, big.mark = ","), " \u2013 ",
            format(ex$end, big.mark = ","), "<br/>",
            "Length: <b>", format(ex$length, big.mark = ","), " bp</b>"
        )

        n_exons <- nrow(ex)
        seg_col <- if (is_cb) "#0072B2" else if (is_dark) "#4A90C4" else "#2196F3"
        pt_col <- if (is_cb) "#E69F00" else if (is_dark) "#64B5F6" else "#1565C0"

        p <- ggplot2::ggplot(ex, ggplot2::aes(x = exon_n, y = length)) +
            ggiraph::geom_segment_interactive(
                ggplot2::aes(
                    xend = exon_n, yend = 0,
                    tooltip = tooltip_txt,
                    data_id = paste0("seg_", exon_n)
                ),
                color = seg_col, linewidth = 1.2
            ) +
            ggiraph::geom_point_interactive(
                ggplot2::aes(
                    tooltip = tooltip_txt,
                    data_id = paste0("pt_", exon_n)
                ),
                color = pt_col, size = 3.5, shape = 21, fill = seg_col
            ) +
            ggplot2::scale_x_continuous(
                breaks = if (n_exons <= 20) seq_len(n_exons) else scales::pretty_breaks(8)(seq_len(n_exons)),
                labels = function(x) paste0("E", x)
            ) +
            ggplot2::scale_y_continuous(
                labels = scales::label_number(scale_cut = scales::cut_short_scale())
            ) +
            ggplot2::labs(
                title = "Exon Map",
                subtitle = paste0(
                    n_exons, " exon", ifelse(n_exons == 1, "", "s"),
                    " \u00b7 ordered by genomic position"
                ),
                x = "Exon (by position)", y = "Length (bp)"
            ) +
            analytics_gg_theme(dark = is_dark) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(size = 13.5, hjust = 0.5),
                plot.subtitle = ggplot2::element_text(size = 10.5, hjust = 0.5)
            )

        safe_girafe(
            ggobj = p,
            width_svg = max(7, n_exons * 0.5 + 2),
            height_svg = 4.5,
            transport_label = "chart_modal_exon_map",
            bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
            options = list(
                ggiraph::opts_hover(css = "r:6px;opacity:0.9;"),
                ggiraph::opts_tooltip(
                    css = analytics_tooltip_css,
                    use_fill = FALSE,
                    placement = "doc",
                    zindex = 999999,
                    delay_mouseover = 40,
                    delay_mouseout = 120
                ),
                ggiraph::opts_selection(type = "none"),
                ggiraph::opts_toolbar(
                    position = "bottomright",
                    hidden = c("selection", "zoom", "misc")
                ),
                ggiraph::opts_sizing(rescale = TRUE)
            )
        )
    })

    # --- B2. Intron Map (lollipop: position vs inferred length) ---
    output$chart_modal_introns <- renderGirafe({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        chart_mode <- selectedChartModalMode()
        d <- get_chart_plot_data(pid, ctx)
        req(!is.null(d$file_data), nrow(d$file_data) > 0)
        is_dark <- is_dark_theme_active()
        is_cb <- is_colorblind_mode_active()

        fd <- d$file_data
        chart_subject <- if (identical(chart_mode, "tx")) "transcript" else "gene"
        if (identical(chart_mode, "tx")) {
            titulo_local <- tryCatch(
                if (identical(ctx, "ortho")) titlesOrthologous()[[pid]] else titlesHomologous()[[pid]],
                error = function(e) ""
            )
            tx_name_local <- trimws(as.character(extract_title_field(titulo_local, "Transcript") %||% ""))
            if (nzchar(tx_name_local)) {
                tx_rows <- grep(tx_name_local, as.character(fd$V9), fixed = TRUE)
                if (length(tx_rows) > 0) {
                    fd <- fd[tx_rows, , drop = FALSE]
                    chart_subject <- tx_name_local
                }
            }
        }

        intr <- get_cached_intron_lengths_for_plot(
            paste0(pid, "_", chart_mode, "_modal_introns"),
            mode = "modal_single",
            file_data = fd
        )
        if (is.null(intr) || !is.data.frame(intr) || nrow(intr) == 0L) {
            return(girafe_msg_plot("No introns detected for this entry", dark = is_dark))
        }

        intr$intron_n <- seq_len(nrow(intr))
        intr$intron_length <- suppressWarnings(as.numeric(intr$intron_length))
        intr$total_introns <- nrow(intr)
        intr$total_bp <- sum(intr$intron_length, na.rm = TRUE)
        intr$tooltip_txt <- paste0(
            "<b>Intron ", intr$intron_n, " of ", intr$total_introns, "</b><br/>",
            "Position: ", format(round(intr$intron_start), big.mark = ","), " \u2013 ",
            format(round(intr$intron_end), big.mark = ","), "<br/>",
            "Length: <b>", format(round(intr$intron_length), big.mark = ","), " bp</b><br/>",
            "Total intronic bp: ", format(round(intr$total_bp), big.mark = ","), " bp"
        )

        n_introns <- nrow(intr)
        seg_col <- if (is_cb) "#0072B2" else if (is_dark) "#8FA1B0" else "#78909C"
        pt_col <- if (is_cb) "#E69F00" else if (is_dark) "#D0B86B" else "#8D6E00"

        p <- ggplot2::ggplot(intr, ggplot2::aes(x = intron_n, y = intron_length)) +
            ggiraph::geom_segment_interactive(
                ggplot2::aes(
                    xend = intron_n, yend = 0,
                    tooltip = tooltip_txt,
                    data_id = paste0("intron_seg_", intron_n)
                ),
                color = seg_col, linewidth = 1.2
            ) +
            ggiraph::geom_point_interactive(
                ggplot2::aes(
                    tooltip = tooltip_txt,
                    data_id = paste0("intron_pt_", intron_n)
                ),
                color = pt_col, size = 3.5, shape = 21, fill = seg_col
            ) +
            ggplot2::scale_x_continuous(
                breaks = if (n_introns <= 20) seq_len(n_introns) else scales::pretty_breaks(8)(seq_len(n_introns)),
                labels = function(x) paste0("I", x)
            ) +
            ggplot2::scale_y_continuous(
                labels = scales::label_number(scale_cut = scales::cut_short_scale())
            ) +
            ggplot2::labs(
                title = "Intron Map",
                subtitle = paste0(
                    n_introns, " intron", ifelse(n_introns == 1, "", "s"),
                    " \u00b7 total ", format(round(intr$total_bp[1]), big.mark = ","), " bp",
                    " \u00b7 inferred from exon gaps"
                ),
                x = "Intron (by position)", y = "Length (bp)"
            ) +
            analytics_gg_theme(dark = is_dark) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(size = 13.5, hjust = 0.5),
                plot.subtitle = ggplot2::element_text(size = 10.5, hjust = 0.5)
            )

        safe_girafe(
            ggobj = p,
            width_svg = max(7, n_introns * 0.5 + 2),
            height_svg = 4.5,
            transport_label = "chart_modal_intron_map",
            bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
            options = list(
                ggiraph::opts_hover(css = "r:6px;opacity:0.9;"),
                ggiraph::opts_tooltip(
                    css = analytics_tooltip_css,
                    use_fill = FALSE,
                    placement = "doc",
                    zindex = 999999,
                    delay_mouseover = 40,
                    delay_mouseout = 120
                ),
                ggiraph::opts_selection(type = "none"),
                ggiraph::opts_toolbar(
                    position = "bottomright",
                    hidden = c("selection", "zoom", "misc")
                ),
                ggiraph::opts_sizing(rescale = TRUE)
            )
        )
    })

    # --- C. Sequence donut (A / T / C / G percentages) ---
    output$chart_modal_seq <- renderGirafe({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        chart_mode <- selectedChartModalMode()
        d <- get_chart_plot_data(pid, ctx)
        is_dark <- is_dark_theme_active()
        is_cb <- is_colorblind_mode_active()

        comp_info <- NULL
        seq_str <- ""
        if (identical(chart_mode, "tx")) {
            comp_info <- if (exists("parse_sequence_composition_blob", mode = "function")) {
                tryCatch(parse_sequence_composition_blob(d$seq_blob), error = function(e) NULL)
            } else {
                NULL
            }

            # ── Transcript mode ────────────────────────────────────────────────
            # Prefer exact spliced transcript composition; do not use the genomic
            # transcript span here because that includes introns.
            titulo_local_seq <- tryCatch(
                if (identical(ctx, "ortho")) titlesOrthologous()[[pid]] else titlesHomologous()[[pid]],
                error = function(e) ""
            )
            tx_name_seq <- trimws(as.character(extract_title_field(titulo_local_seq, "Transcript") %||% ""))
            gm_seq <- tryCatch(
                if (identical(ctx, "ortho")) plotGeneMetaOrthologous()[[pid]] else plotGeneMetaHomologous()[[pid]],
                error = function(e) NULL
            )
            gp_seq <- tryCatch(
                if (identical(ctx, "ortho")) genomePathsOrthologous()[[pid]] else genomePathsHomologous()[[pid]],
                error = function(e) NULL
            )

            if (is.null(comp_info) && !is.null(d$file_data) && nrow(d$file_data) > 0 &&
                !is.null(gp_seq) && nzchar(as.character(gp_seq %||% "")) && file.exists(as.character(gp_seq)) &&
                !is.null(gm_seq) && exists("get_transcript_composition_cached", mode = "function")) {
                fd_all <- d$file_data
                types_all <- tolower(trimws(as.character(fd_all$V3 %||% rep("", nrow(fd_all)))))
                exon_rows <- which(types_all == "exon")
                if (length(exon_rows) == 0L) {
                    exon_rows <- which(types_all == "cds")
                }
                if (length(exon_rows) > 0L) {
                    exons <- data.frame(
                        start = suppressWarnings(as.numeric(fd_all$V4[exon_rows])),
                        end = suppressWarnings(as.numeric(fd_all$V5[exon_rows])),
                        stringsAsFactors = FALSE
                    )
                    chr_name_seq <- as.character(fd_all$V1[exon_rows[1]] %||% gm_seq$seqid %||% "")
                    comp_info <- tryCatch(
                        get_transcript_composition_cached(
                            as.character(gp_seq),
                            chr_name_seq,
                            exons,
                            strand = as.character(gm_seq$strand %||% "+")
                        ),
                        error = function(e) NULL
                    )
                }
            }
            if (is.null(comp_info)) {
                fb <- tryCatch(extract_sequence_from_blob(d$seq_blob), error = function(e) "")
                if (nzchar(fb)) {
                    seq_str <- fb
                }
            }
        } else {
            # Gene mode: prefer the full genomic gene sequence (gene start → end)
            gene_meta_cseq <- tryCatch(
                if (identical(ctx, "ortho")) plotGeneMetaOrthologous()[[pid]] else plotGeneMetaHomologous()[[pid]],
                error = function(e) NULL
            )
            genome_path_cseq <- tryCatch(
                if (identical(ctx, "ortho")) genomePathsOrthologous()[[pid]] else genomePathsHomologous()[[pid]],
                error = function(e) NULL
            )
            gene_seq <- NULL
            if (
                !is.null(genome_path_cseq) && nzchar(as.character(genome_path_cseq %||% "")) &&
                !is.null(gene_meta_cseq) &&
                is.finite(suppressWarnings(as.numeric(gene_meta_cseq$gene_start_bp %||% NA))) &&
                is.finite(suppressWarnings(as.numeric(gene_meta_cseq$gene_end_bp   %||% NA)))
            ) {
                gene_blob_cseq <- tryCatch(
                    build_gene_sequence_content(
                        genome_path = as.character(genome_path_cseq),
                        gene_name   = as.character(gene_meta_cseq$display_gene_name %||% gene_meta_cseq$matched_gene_name %||% "gene"),
                        chr_name    = as.character(gene_meta_cseq$seqid  %||% ""),
                        gene_start  = gene_meta_cseq$gene_start_bp,
                        gene_end    = gene_meta_cseq$gene_end_bp,
                        strand      = as.character(gene_meta_cseq$strand %||% "+")
                    ),
                    error = function(e) NULL
                )
                if (!is.null(gene_blob_cseq) && nzchar(gene_blob_cseq))
                    gene_seq <- tryCatch(extract_sequence_from_blob(gene_blob_cseq), error = function(e) NULL)
            }
            if (nzchar(as.character(gene_seq %||% ""))) {
                seq_str <- gene_seq
            }
            else {
                fb <- tryCatch(extract_sequence_from_blob(d$seq_blob), error = function(e) "")
                if (nzchar(fb)) {
                    seq_str <- fb
                } else if (!(exists("is_sequence_composition_blob", mode = "function") && isTRUE(is_sequence_composition_blob(d$seq_blob)))) {
                    seq_str <- toupper(gsub("[^ACGTacgt]", "", as.character(d$seq_blob %||% "")))
                }
            }
        }

        if (!is.null(comp_info) && is.list(comp_info)) {
            counts <- suppressWarnings(as.integer((comp_info$counts %||% c(A = 0L, T = 0L, C = 0L, G = 0L))[c("A", "T", "C", "G")]))
            counts[!is.finite(counts)] <- 0L
            names(counts) <- c("A", "T", "C", "G")
            total <- suppressWarnings(as.numeric(comp_info$known_total %||% sum(counts, na.rm = TRUE)))
            req(is.finite(total) && total > 0)
            a_n <- counts[["A"]]
            t_n <- counts[["T"]]
            c_n <- counts[["C"]]
            g_n <- counts[["G"]]
        } else {
            req(nchar(seq_str) > 0)
            seq_str <- toupper(gsub("[^ACGT]", "", seq_str))
            total <- nchar(seq_str)
            req(total > 0)
            a_n <- nchar(gsub("[^A]", "", seq_str))
            t_n <- nchar(gsub("[^T]", "", seq_str))
            c_n <- nchar(gsub("[^C]", "", seq_str))
            g_n <- nchar(gsub("[^G]", "", seq_str))
        }
        a_pct <- 100 * a_n / total
        t_pct <- 100 * t_n / total
        c_pct <- 100 * c_n / total
        g_pct <- 100 * g_n / total
        gc <- g_pct + c_pct

        df <- data.frame(
            Base = factor(c("A", "T", "C", "G"), levels = c("A", "T", "C", "G")),
            pct = c(a_pct, t_pct, c_pct, g_pct),
            count = c(a_n, t_n, c_n, g_n)
        )
        df$tooltip_txt <- paste0(
            "<b>Base ", df$Base, "</b><br/>",
            "Percentage: <b>", round(df$pct, 2), "%</b><br/>",
            "Count: <b>", format(df$count, big.mark = ","), "</b> bases"
        )
        pal <- analytics_named_palette("bases", colorblind = is_cb, dark = is_dark)
        slice_border_col <- if (is_dark) "#1A2B3C" else "white"
        hover_stroke_col <- if (is_dark) "#A8C5DA" else "white"

        df$frac <- df$pct / sum(df$pct)
        df$end <- 2 * pi * cumsum(df$frac)
        df$start <- c(0, utils::head(df$end, -1))

        ring_outer <- 1
        ring_inner <- 0.52
        df_poly <- do.call(rbind,  lapply(seq_len(nrow(df)), function(i) {
            theta <- seq(df$start[i], df$end[i], length.out = 120)
            data.frame(
                Base = df$Base[i],
                tooltip_txt = df$tooltip_txt[i],
                data_id = paste0("base_", as.character(df$Base[i])),
                grp = i,
                x = c(ring_outer * sin(theta), rev(ring_inner * sin(theta))),
                y = c(ring_outer * cos(theta), rev(ring_inner * cos(theta))),
                stringsAsFactors = FALSE
            )
        }))

        p <- ggplot2::ggplot(
            df_poly,
            ggplot2::aes(
                x = x, y = y, group = grp, fill = Base,
                tooltip = tooltip_txt, data_id = data_id
            )
        ) +
            ggiraph::geom_polygon_interactive(
                color = slice_border_col,
                linewidth = 0.8
            ) +
            ggplot2::coord_equal(xlim = c(-1.06, 1.06), ylim = c(-1.06, 1.06), clip = "off") +
            ggplot2::scale_fill_manual(values = pal) +
            ggplot2::annotate("text",
                x = 0, y = 0,
                label = paste0("GC\n", round(gc, 1), "%"),
                size = 4.35, fontface = "bold",
                color = if (is_dark) "#D0E4F0" else "#2C3E50"
            ) +
            ggplot2::labs(
                title    = "Nucleotide Composition",
                subtitle = paste0(
                    if (identical(chart_mode, "tx")) "Transcript span: " else "Gene span: ",
                    format(total, big.mark = ","), " bp"
                ),
                fill     = "Base"
            ) +
            ggplot2::theme_void(base_size = 10) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(
                    face = "bold", size = 11.1, hjust = 0.5,
                    color = if (is_dark) "#D0E4F0" else "#2C3E50",
                    margin = ggplot2::margin(t = 3, b = 2)
                ),
                plot.subtitle = ggplot2::element_text(
                    size = 8.6, hjust = 0.5,
                    color = if (is_dark) "#A8C5DA" else "#546E7A",
                    margin = ggplot2::margin(b = 4)
                ),
                plot.background = ggplot2::element_rect(
                    fill = if (is_dark) "#1A2B3C" else "#FFFFFF", color = NA
                ),
                legend.text = ggplot2::element_text(
                    color = if (is_dark) "#D0E4F0" else "#2C3E50"
                ),
                legend.title = ggplot2::element_text(
                    color = if (is_dark) "#D0E4F0" else "#2C3E50", face = "bold"
                ),
                legend.background = ggplot2::element_rect(
                    fill = if (is_dark) "#1A2B3C" else "#FFFFFF", color = NA
                ),
                legend.key = ggplot2::element_rect(
                    fill = if (is_dark) "#1A2B3C" else "#FFFFFF", color = NA
                ),
                panel.background = ggplot2::element_rect(
                    fill = if (is_dark) "#1A2B3C" else "#FFFFFF", color = NA
                ),
                plot.margin = ggplot2::margin(2, 8, 2, 8)
            )

        safe_girafe(
            ggobj = p, width_svg = 6, height_svg = 3.95,
            transport_label = "chart_modal_gc_content",
            bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
            options = analytics_girafe_options(
                paste0("opacity:0.9;stroke:", hover_stroke_col, ";stroke-width:2.2px;cursor:pointer;")
            )
        )
    })

    # --- D. Isoforms: conditional uiOutput ---
    output$chart_modal_isoforms_ui <- renderUI({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        df_tx <- get_chart_modal_isoforms_df(pid, ctx)

        if (nrow(df_tx) < 2) {
            return(div(
                class = "chart-modal-no-data",
                icon("info-circle"),
                span(" Single transcript \u2014 isoform comparison not available for this gene/context.")
            ))
        }
        ggiraph::girafeOutput("chart_modal_isoforms_girafe", height = "auto", width = "100%")
    })

    # --- E. Isoforms girafe (only fires when >=2 transcripts) ---
    output$chart_modal_isoforms_girafe <- renderGirafe({
        pid <- selectedChartPlotId()
        req(!is.null(pid))
        ctx <- selectedChartContext()
        is_dark <- is_dark_theme_active()
        is_cb <- is_colorblind_mode_active()
        df_tx <- get_chart_modal_isoforms_df(pid, ctx)
        req(nrow(df_tx) >= 2)
        iso_col <- analytics_named_palette("primary", colorblind = is_cb, dark = is_dark)[["primary"]]

        df_tx$isoform <- trimws(as.character(df_tx$tx_id))
        df_tx$isoform_label <- ifelse(
            nchar(df_tx$isoform) > 28,
            paste0(substr(df_tx$isoform, 1, 26), "\u2026"),
            df_tx$isoform
        )
        df_tx$isoform_label <- make.unique(df_tx$isoform_label, sep = " \u00b7 ")
        df_tx$isoform_label <- factor(df_tx$isoform_label, levels = df_tx$isoform_label)

        p <- ggplot2::ggplot(
            df_tx,
            ggplot2::aes(
                x = isoform_label,
                y = tx_len,
                tooltip = paste0(
                    "<b>", isoform, "</b><br/>",
                    "Length: ", format(tx_len, big.mark = ","), " bp"
                ),
                data_id = paste0(isoform_label, "_", seq_len(nrow(df_tx)))
            )
        ) +
            ggiraph::geom_col_interactive(
                fill = iso_col, color = if (is_dark) "#1A2B3C" else "white", linewidth = 0.3, width = 0.48
            ) +
            ggplot2::coord_flip() +
            ggplot2::scale_y_continuous(
                labels = scales::label_number(scale_cut = scales::cut_short_scale())
            ) +
            ggplot2::labs(
                title = "Transcript Isoforms",
                subtitle = paste0(nrow(df_tx), " isoforms \u2014 ordered by length"),
                x = NULL, y = "Transcript length (bp)"
            ) +
            analytics_gg_theme(dark = is_dark) +
            ggplot2::theme(
                plot.title = ggplot2::element_text(size = 13.5, hjust = 0.5),
                plot.subtitle = ggplot2::element_text(size = 10.5, hjust = 0.5)
            )

        safe_girafe(
            ggobj = p,
            width_svg = 8.4,
            height_svg = analytics_svg_height(
                nrow(df_tx),
                min_h = 2.8, max_h = 5.8, base = 1.8, per_item = 0.4
            ),
            transport_label = "chart_modal_isoforms",
            bg = if (is_dark) "#1A2B3C" else "#FFFFFF",
            options = analytics_girafe_options("opacity:0.88;stroke:white;stroke-width:1.2px;")
        )
    })

    # ============================================================
    # FIN ANALYTICS SECTION
    # ============================================================

    # Charts modal sub-tabs visibility:
    # - First-visible group (Gene tab sub-tabs + isoforms overview): eager render (FALSE)
    #   These are lightweight and must be ready the moment the modal opens.
    # - Isoforms analytics group (Architecture, Exons & Introns, Sequence, Context,
    #   Exon Lengths sub-tabs inside the Isoforms tab): lazy render (TRUE)
    #   chart_modal_gene_intron_dist is eager so the modal ZIP can include
    #   chart_intron_lengths.svg without requiring a prior tab visit.
    #   These are heavier charts on a secondary tab; suspending them reduces the
    #   concurrent render queue from 10 → 5, so the first visible chart appears
    #   roughly twice as fast. Shiny resumes them when the user navigates to that tab.
    # NOTE: must be placed AFTER all output$chart_modal_* are defined above.
    invisible(lapply(
        c("chart_modal_structure", "chart_modal_exons", "chart_modal_introns", "chart_modal_seq",
          "chart_modal_isoforms_ui", "chart_modal_isoforms_girafe", "chart_modal_gene_intron_dist"),
        function(output_id) outputOptions(output, output_id, suspendWhenHidden = FALSE)
    ))
    invisible(lapply(
        c("chart_modal_gene_arch", "chart_modal_gene_exon", "chart_modal_gene_seq",
          "chart_modal_gene_context", "chart_modal_gene_exon_dist"),
        function(output_id) outputOptions(output, output_id, suspendWhenHidden = TRUE)
    ))

