    # Table downloads live inside a view-specific menu that is hidden until the
    # user opens it. Keep the handlers active so their links are ready as soon
    # as the Table download option becomes visible.
    outputOptions(output, "download_homo_summary_csv", suspendWhenHidden = FALSE)
    outputOptions(output, "download_ortho_summary_csv", suspendWhenHidden = FALSE)


    observe({
        ids_chr <- as.character(activePlotIdsHomologous() %||% integer(0))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        keep_ids <- unique(c(ids_chr, get_active_homologous_copy_ids(ids_chr)))
        bound_now <- as.character(isolate(homoDownloadOutputsBound()) %||% character(0))
        remove_ids <- setdiff(bound_now, keep_ids)
        add_ids <- setdiff(keep_ids, bound_now)
        if (length(remove_ids) > 0L) {
            invisible(lapply(remove_ids, unbind_homologous_download_output))
        }
        if (length(add_ids) > 0L) {
            invisible(lapply(add_ids, register_homologous_download_output))
        }
        target_bound <- keep_ids
        if (!identical(bound_now, target_bound)) {
            homoDownloadOutputsBound(target_bound)
        }
    })

    observe({
        ids_chr <- as.character(activePlotIdsOrthologous() %||% integer(0))
        ids_chr <- ids_chr[nzchar(ids_chr)]
        keep_ids <- unique(c(ids_chr, get_active_orthologous_copy_ids(ids_chr)))
        bound_now <- as.character(isolate(orthoDownloadOutputsBound()) %||% character(0))
        remove_ids <- setdiff(bound_now, keep_ids)
        add_ids <- setdiff(keep_ids, bound_now)
        if (length(remove_ids) > 0L) {
            invisible(lapply(remove_ids, unbind_orthologous_download_output))
        }
        if (length(add_ids) > 0L) {
            invisible(lapply(add_ids, register_orthologous_download_output))
        }
        target_bound <- keep_ids
        if (!identical(bound_now, target_bound)) {
            orthoDownloadOutputsBound(target_bound)
        }
    })

    # ============================================================
    # PHASE 6 — STRING Network Interactive Module
    # ============================================================
    build_string_info_widget <- function(label = "Loading STRING network...", title = "", icon_code = "f1ce", icon_color = "#4A90C4", font_size = 14) {
        if (!requireNamespace("visNetwork", quietly = TRUE)) {
            return(tags$div(style = "padding:24px;text-align:center;color:#5D6D7E;",
                tags$p("Install the 'visNetwork' package to view interactive STRING networks.")))
        }
        visNetwork(
            data.frame(
                id = "info",
                label = as.character(label %||% "Loading STRING network..."),
                shape = "icon",
                icon.face = "FontAwesome",
                icon.code = as.character(icon_code %||% "f1ce"),
                icon.size = 44,
                icon.color = as.character(icon_color %||% "#4A90C4"),
                font.size = as.numeric(font_size %||% 14),
                font.color = "#5D6D7E",
                title = as.character(title %||% ""),
                stringsAsFactors = FALSE
            ),
            data.frame(from = character(0), to = character(0), stringsAsFactors = FALSE)
        ) %>%
            visNodes(font = list(multi = TRUE)) %>%
            visInteraction(zoomView = FALSE, dragView = FALSE)
    }

    build_string_error_widget <- function(label, title = "", icon_code = "f071", icon_color = "#D4A537", font_size = 14) {
        build_string_info_widget(
            label = label,
            title = title,
            icon_code = icon_code,
            icon_color = icon_color,
            font_size = font_size
        )
    }

    build_string_query_payload <- function(pid, ctx) {
        d <- get_chart_plot_data(pid, ctx)
        if (is.null(d$file_data) || nrow(d$file_data) == 0) {
            return(list(error_widget = build_string_error_widget("Plot data not available", "This plot is no longer available. Generate it again and retry.")))
        }

        is_invalid_str <- function(x) {
            length(x) == 0 || is.na(x) || !nzchar(x) || x == "Gene"
        }
        is_invalid_num <- function(x) {
            length(x) == 0 || is.na(x) || !is.finite(x) || x <= 0
        }

        titulo <- if (identical(ctx, "homo")) titlesHomologous()[[pid]] else titlesOrthologous()[[pid]]
        ann_path <- if (identical(ctx, "homo")) annotationPathsHomologous()[[pid]] else annotationPathsOrthologous()[[pid]]
        gene_title <- trimws(as.character(extract_title_field(titulo, "Gene") %||% "Gene"))
        org_name <- as.character(d$org_info$name %||% "Organism")

        types <- tolower(trimws(as.character(d$file_data$V3)))
        gene_rows <- which(types == "gene")
        gene_attr <- if (length(gene_rows) > 0) as.character(d$file_data$V9[gene_rows[1]]) else ""
        gene_name <- tryCatch(extract_primary_gene_name(gene_attr), error = function(e) "")
        if (is_invalid_str(gene_name)) {
            gene_name <- gene_title
        }
        if (is_invalid_str(gene_name)) {
            return(list(
                org_name = org_name,
                gene_title = gene_title,
                error_widget = build_string_error_widget("No gene name", "Could not resolve a stable gene name for STRING query.", font_size = 16)
            ))
        }

        taxid <- suppressWarnings(as.numeric(d$org_info$taxid))
        if (is_invalid_num(taxid)) {
            taxid <- suppressWarnings(as.numeric(resolve_taxid_for_go_lookup(ann_path, d$org_info$name)))
        }
        if (is_invalid_num(taxid)) {
            return(list(
                org_name = org_name,
                gene_title = gene_title,
                error_widget = build_string_error_widget(
                    "TaxID not found",
                    "Organism TaxID not found. STRING requires a valid TaxID.",
                    icon_code = "f06a",
                    icon_color = "#C0392B",
                    font_size = 16
                )
            ))
        }

        plot_taxid_for_string <- function(plot_id, ctx_name, plot_d = NULL) {
            plot_id <- as.character(plot_id %||% "")
            if (is.null(plot_d)) {
                plot_d <- get_chart_plot_data(plot_id, ctx_name)
            }
            ann_path_i <- tryCatch(
                if (identical(ctx_name, "homo")) annotationPathsHomologous()[[plot_id]] else annotationPathsOrthologous()[[plot_id]],
                error = function(e) ""
            )
            org_info_i <- plot_d$org_info %||% list()
            tx <- suppressWarnings(as.numeric(org_info_i$taxid %||% NA_real_))
            if (is_invalid_num(tx)) {
                tx <- suppressWarnings(as.numeric(resolve_taxid_for_go_lookup(ann_path_i, org_info_i$name %||% "")))
            }
            tx
        }

        extract_gff_ids_for_plot <- function(plot_id, ctx_name, plot_d = NULL) {
            ids <- c()
            tryCatch({
                if (is.null(plot_d)) {
                    plot_d <- get_chart_plot_data(as.character(plot_id), ctx_name)
                }
                if (!is.null(plot_d$file_data) && nrow(plot_d$file_data) > 0) {
                    for (row_attr in as.character(plot_d$file_data$V9)) {
                        pa <- tryCatch(parse_gff_attributes(row_attr), error = function(e) list())
                        for (key in c("gene", "gene_id", "locus_tag", "name", "protein_id", "id")) {
                            v <- pa[[key]][1]
                            if (!is.null(v) && !is.na(v) && nzchar(trimws(v))) {
                                clean_v <- trimws(v)
                                clean_v2 <- sub("^(gene|rna|mrna|cds|transcript)[:-]", "", clean_v, ignore.case = TRUE)
                                ids <- c(ids, clean_v, clean_v2)
                            }
                        }
                        dbx_vals <- c(pa[["dbxref"]], pa[["db_xref"]])
                        for (dbx in dbx_vals) {
                            if (is.null(dbx) || is.na(dbx) || !nzchar(dbx)) next
                            entries <- trimws(unlist(strsplit(as.character(dbx), ",", fixed = TRUE)))
                            for (ent in entries) {
                                if (!nzchar(ent)) next
                                ids <- c(ids, ent)
                                parts <- strsplit(ent, ":", fixed = TRUE)[[1]]
                                if (length(parts) >= 2) {
                                    ids <- c(ids, trimws(paste(parts[-1], collapse = ":")))
                                }
                            }
                        }
                    }
                }
            }, error = function(e) NULL)
            unique(ids[nzchar(ids)])
        }

        collect_screen_records <- function(ctx_name, ids, titles_map) {
            records <- list()
            for (i_id in ids %||% integer(0)) {
                id_chr <- as.character(i_id)
                plot_d <- tryCatch(get_chart_plot_data(id_chr, ctx_name), error = function(e) NULL)
                if (is.null(plot_d) || is.null(plot_d$file_data) || nrow(plot_d$file_data) == 0L) next
                t_str <- tryCatch(titles_map[[id_chr]], error = function(e) "")
                g_name <- trimws(as.character(extract_title_field(t_str, "Gene") %||% ""))
                candidates <- c()
                if (!is_invalid_str(g_name)) candidates <- c(candidates, g_name)
                candidates <- c(candidates, extract_gff_ids_for_plot(id_chr, ctx_name, plot_d = plot_d))
                candidates <- unique(trimws(candidates))
                candidates <- candidates[nzchar(candidates) & !is.na(candidates)]
                if (length(candidates) == 0L) next
                records[[length(records) + 1L]] <- list(
                    taxid = plot_taxid_for_string(id_chr, ctx_name, plot_d = plot_d),
                    candidates = candidates
                )
            }
            records
        }

        screen_records <- c(
            tryCatch(collect_screen_records("homo", activePlotIdsHomologous(), titlesHomologous() %||% list()), error = function(e) list()),
            tryCatch(collect_screen_records("ortho", activePlotIdsOrthologous(), titlesOrthologous() %||% list()), error = function(e) list())
        )
        screen_variants <- tryCatch(
            string_collect_same_taxid_candidates(screen_records, taxid),
            error = function(e) character(0)
        )

        id_candidates <- unique(c(
            gene_name,
            gsub(";", ".", gene_name, fixed = TRUE),
            gsub(";", "-", gene_name, fixed = TRUE),
            gsub(";", "", gene_name, fixed = TRUE)
        ))
        tryCatch({
            all_attrs_raw <- as.character(d$file_data$V9)
            for (row_i in seq_along(all_attrs_raw)) {
                parsed <- tryCatch(parse_gff_attributes(all_attrs_raw[row_i]), error = function(e) list())
                pid_val <- parsed[["protein_id"]][1]
                if (!is.null(pid_val) && !is.na(pid_val) && nzchar(trimws(pid_val))) {
                    id_candidates <- c(id_candidates, trimws(pid_val))
                }
                dbx_vals <- c(parsed[["dbxref"]], parsed[["db_xref"]])
                for (dbx in dbx_vals) {
                    if (is.null(dbx) || is.na(dbx) || !nzchar(dbx)) next
                    entries <- trimws(unlist(strsplit(as.character(dbx), ",", fixed = TRUE)))
                    for (ent in entries) {
                        parts <- strsplit(ent, ":", fixed = TRUE)[[1]]
                        if (length(parts) >= 2) {
                            id_candidates <- c(id_candidates, trimws(paste(parts[-1], collapse = ":")))
                        }
                        id_candidates <- c(id_candidates, trimws(ent))
                    }
                }
                syn_vals <- c(parsed[["gene_synonym"]], parsed[["gene_synonyms"]], parsed[["synonym"]])
                for (sv in syn_vals) {
                    if (is.null(sv) || is.na(sv) || !nzchar(sv)) next
                    syns <- trimws(unlist(strsplit(as.character(sv), ",", fixed = TRUE)))
                    id_candidates <- c(id_candidates, syns[nzchar(syns)])
                }
                for (key in c("locus_tag", "name", "id")) {
                    v <- parsed[[key]][1]
                    if (!is.null(v) && !is.na(v) && nzchar(trimws(v))) {
                        id_candidates <- c(id_candidates, trimws(v))
                    }
                }
            }
        }, error = function(e) NULL)
        gene_id_fallback <- tryCatch(extract_primary_gene_id(gene_attr), error = function(e) "")
        if (!is_invalid_str(gene_id_fallback)) {
            id_candidates <- c(id_candidates, gene_id_fallback)
        }
        id_candidates <- unique(trimws(id_candidates))
        id_candidates <- id_candidates[nzchar(id_candidates) & !is.na(id_candidates) & id_candidates != "Gene"]
        if (length(id_candidates) > 64L) {
            id_candidates <- id_candidates[seq_len(64L)]
        }

        list(
            org_name = org_name,
            gene_title = gene_title,
            gene_name = gene_name,
            taxid = as.numeric(taxid),
            id_candidates = id_candidates,
            screen_variants = screen_variants,
            required_score = 600L,
            add_nodes = 8L,
            is_dark = identical(tolower(as.character(input$app_theme %||% "light")), "dark")
        )
    }

    build_string_network_widget_async <- function(query_payload) {
        safe_tolower <- function(x) {
            ifelse(is.na(x) | length(x) == 0, "", tolower(x))
        }

        with_string_time_limit <- function(expr, seconds = 8) {
            # setTimeLimit() interacts poorly with future::multisession workers
            # and can cause "MultisessionFuture was interrupted" errors.
            # Rely on httr2::req_timeout() for HTTP-level timeouts instead.
            force(expr)
        }

        string_api_request <- function(path, query = list(), has_header = TRUE, seconds = 30) {
            base_url <- sprintf(
                "https://string-db.org/api/%s/%s",
                if (isTRUE(has_header)) "tsv" else "tsv-no-header",
                path
            )
            response <- with_string_time_limit(
                httr2::request(base_url) %>%
                    httr2::req_user_agent("CGVViewer STRING client") %>%
                    httr2::req_url_query(!!!c(query, list(caller_identity = "cgvviewer"))) %>%
                    httr2::req_timeout(seconds) %>%
                    httr2::req_retry(max_tries = 2, retry_on_failure = TRUE) %>%
                    httr2::req_perform(),
                seconds = seconds + 2
            )

            body <- tryCatch(httr2::resp_body_string(response), error = function(e) "")
            if (!nzchar(trimws(body))) {
                return(data.frame(stringsAsFactors = FALSE))
            }

            out <- utils::read.delim(
                text = body,
                sep = "\t",
                header = isTRUE(has_header),
                stringsAsFactors = FALSE,
                quote = "",
                comment.char = ""
            )

            if (!isTRUE(has_header) && ncol(out) >= 6) {
                colnames(out)[seq_len(6)] <- c(
                    "queryIndex", "stringId", "ncbiTaxonId",
                    "taxonName", "preferredName", "annotation"
                )
            }

            out
        }

        gene_name <- as.character(query_payload$gene_name %||% "Gene")
        taxid <- as.numeric(query_payload$taxid %||% NA_real_)
        id_candidates <- unique(as.character(query_payload$id_candidates %||% character(0)))
        screen_variants <- unique(as.character(query_payload$screen_variants %||% character(0)))
        is_dark <- isTRUE(query_payload$is_dark)

        resolved_string_id <- NULL
        resolved_pref_name <- NULL
        batch_candidates <- unique(c(id_candidates, screen_variants))
        batch_candidates <- batch_candidates[nzchar(batch_candidates)]

        if (length(batch_candidates) > 0) {
            mapped_ids <- tryCatch(
                string_api_request(
                    path = "get_string_ids",
                    query = list(
                        identifiers = paste(batch_candidates, collapse = "\r"),
                        species = as.character(as.integer(taxid))
                    ),
                    has_header = FALSE,
                    seconds = 25
                ),
                error = function(e) NULL
            )
            if (is.data.frame(mapped_ids) && nrow(mapped_ids) > 0) {
                resolved_pns <- tolower(trimws(as.character(mapped_ids$preferredName %||% character(0))))
                resolved_pns <- resolved_pns[nzchar(resolved_pns)]
                screen_variants <- unique(c(screen_variants, resolved_pns))
            }
        }

        for (cand in id_candidates) {
            map_result <- tryCatch(
                string_api_request(
                    path = "get_string_ids",
                    query = list(
                        identifiers = as.character(cand),
                        species = as.character(as.integer(taxid))
                    ),
                    has_header = FALSE,
                    seconds = 20
                ),
                error = function(e) NULL
            )
            if (is.data.frame(map_result) && nrow(map_result) > 0) {
                resolved_string_id <- trimws(as.character(map_result$stringId[1] %||% ""))
                resolved_pref_name <- trimws(as.character(map_result$preferredName[1] %||% ""))
                break
            }
        }

        if (is.null(resolved_string_id) || !nzchar(resolved_string_id)) {
            err_label <- sprintf("Protein not found in STRING\n%s (taxon %s)", gene_name, as.character(taxid))
            err_tip <- sprintf("STRING could not identify protein '%s' in taxon %s. Try with a different gene name or verify the organism.", gene_name, as.character(taxid))
            return(build_string_error_widget(err_label, paste0("<div style='padding:8px; max-width:300px; font-family:sans-serif;'>", htmltools::htmlEscape(err_tip), "</div>"), icon_code = "f002"))
        }

        net_data <- tryCatch(
            string_api_request(
                path = "network",
                query = list(
                    identifiers = resolved_string_id,
                    species = as.character(as.integer(taxid)),
                    required_score = "600",
                    add_nodes = "8"
                ),
                has_header = TRUE,
                seconds = 30
            ),
            error = function(e) e
        )

        if (inherits(net_data, "error") || !is.data.frame(net_data) || nrow(net_data) == 0) {
            err_msg <- if (inherits(net_data, "error")) conditionMessage(net_data) else "No interactions were returned."
            return(build_string_error_widget(
                "No interactions found",
                paste0("<div style='padding:8px; max-width:300px; font-family:sans-serif;'>", htmltools::htmlEscape(paste("STRING API could not retrieve interactions:", err_msg)), "</div>")
            ))
        }

        nodes_raw <- data.frame(
            id = c(net_data$stringId_A, net_data$stringId_B),
            label = c(net_data$preferredName_A, net_data$preferredName_B),
            stringsAsFactors = FALSE
        )
        nodes <- unique(nodes_raw)
        node_labels_lc <- safe_tolower(nodes$label)
        node_labels_normalized <- gsub("[;._-]+", "", node_labels_lc)
        nodes$is_target <- as.character(nodes$id) == as.character(resolved_string_id)
        nodes$is_plotted <- (node_labels_lc %in% screen_variants | node_labels_normalized %in% screen_variants) & !nodes$is_target
        nodes$color.background <- ifelse(nodes$is_target, "#E74C3C", ifelse(nodes$is_plotted, "#F39C12", "#D6E1EA"))
        nodes$color.border <- ifelse(nodes$is_target, "#C0392B", ifelse(nodes$is_plotted, "#D68910", "#9BA6B0"))
        nodes$font.color <- if (is_dark) {
            ifelse(nodes$is_target, "#FF8A80", ifelse(nodes$is_plotted, "#FFD54F", "#D0E4F0"))
        } else {
            ifelse(nodes$is_target, "#8B0000", ifelse(nodes$is_plotted, "#7D5A00", "#2C3E50"))
        }
        nodes$shape <- "dot"
        nodes$size <- ifelse(nodes$is_target, 28, ifelse(nodes$is_plotted, 19, 13))
        nodes$borderWidth <- ifelse(nodes$is_target | nodes$is_plotted, 2, 1)
        nodes$title <- paste0(
            "<div style='padding:8px 10px; font-family:Roboto,sans-serif; background:#2C3E50; color:#FFFFFF; border-radius:6px; font-size:12px;'><b>",
            nodes$label,
            "</b><br/><span style='color:#9BB5C9; font-size:11px;'>STRING ID: ",
            nodes$id,
            "</span></div>"
        )

        edges <- data.frame(
            from = net_data$stringId_A,
            to = net_data$stringId_B,
            title = paste0("<div style='padding:6px 10px; font-family:Roboto,sans-serif; background:#2C3E50; color:#FFFFFF; border-radius:6px; font-size:12px;'>Score: <b>", net_data$score, "</b></div>"),
            width = ifelse(as.numeric(net_data$score) <= 1, 0.8 + (as.numeric(net_data$score) * 1.4), 0.8 + ((as.numeric(net_data$score) / 1000) * 1.4)),
            color = "rgba(124, 144, 166, 0.22)",
            stringsAsFactors = FALSE
        )

        net_bg <- if (is_dark) "#0F1D2B" else "#FFFFFF"
        if (!requireNamespace("visNetwork", quietly = TRUE)) {
            return(build_string_error_widget("visNetwork package not available"))
        }
        visNetwork(nodes, edges, background = net_bg) %>%
            visNodes(
                font = list(
                    size = 14,
                    face = "Roboto, sans-serif",
                    strokeWidth = if (is_dark) 2 else 1,
                    strokeColor = if (is_dark) "rgba(0,0,0,0.6)" else "rgba(255,255,255,0.6)"
                ),
                shadow = list(enabled = TRUE, size = 4),
                color = list(
                    background = if (is_dark) "#1A2B3C" else "#D6E1EA",
                    border = if (is_dark) "#3A5570" else "#9BA6B0"
                ),
                scaling = list(
                    label = list(enabled = TRUE, min = 11, max = 18)
                )
            ) %>%
            visEdges(
                smooth = FALSE,
                shadow = FALSE,
                selectionWidth = 1.2,
                hoverWidth = 0.6
            ) %>%
            visOptions(highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE)) %>%
            visPhysics(
                solver = "forceAtlas2Based",
                forceAtlas2Based = list(gravitationalConstant = -85, centralGravity = 0.01, springLength = 165, springConstant = 0.025),
                stabilization = list(iterations = 250)
            ) %>%
            visInteraction(zoomView = TRUE, dragView = TRUE, dragNodes = TRUE, zoomSpeed = 0.45) %>%
            visEvents(
                stabilized = "function(){ if (typeof this.__minScale !== 'number') { this.__minScale = this.getScale(); this.__homePos = this.getViewPosition(); } }",
                zoom = "function(params){ var minScale = (typeof this.__minScale === 'number') ? this.__minScale : this.getScale(); if (!params) return; if (params.scale < minScale) { this.moveTo({ position: this.__homePos || this.getViewPosition(), scale: minScale, animation: false }); } }",
                dragEnd = "function(){ var minScale = (typeof this.__minScale === 'number') ? this.__minScale : this.getScale(); var home = this.__homePos || this.getViewPosition(); var view = this.getViewPosition ? this.getViewPosition() : home; var scale = this.getScale ? this.getScale() : minScale; if (!isFinite(scale) || scale < minScale) scale = minScale; var zoomFactor = Math.max(0, (scale / minScale) - 1); var maxOffset = 180 + (zoomFactor * 520); var tx = Math.max(home.x - maxOffset, Math.min(home.x + maxOffset, view.x)); var ty = Math.max(home.y - maxOffset, Math.min(home.y + maxOffset, view.y)); if (Math.abs(tx - view.x) > 1 || Math.abs(ty - view.y) > 1) { this.moveTo({ position: {x: tx, y: ty}, scale: scale, animation: {duration: 160, easingFunction: 'easeInOutQuad'} }); } }"
            )
    }

    build_string_network_widget_from_data <- function(network_payload, is_dark = FALSE, stabilization_iterations = 120L) {
        if (!requireNamespace("visNetwork", quietly = TRUE)) {
            return(build_string_error_widget("visNetwork package not available"))
        }
        if (!is.list(network_payload) ||
            !is.data.frame(network_payload$nodes) ||
            !is.data.frame(network_payload$edges) ||
            nrow(network_payload$nodes) == 0L) {
            return(build_string_error_widget("No interactions found"))
        }

        nodes <- network_payload$nodes
        edges_raw <- network_payload$edges
        role <- as.character(nodes$role %||% rep("neighbor", nrow(nodes)))
        nodes$color.background <- ifelse(role == "target", "#E74C3C", ifelse(role == "plotted", "#F39C12", if (is_dark) "#1A2B3C" else "#D6E1EA"))
        nodes$color.border <- ifelse(role == "target", "#C0392B", ifelse(role == "plotted", "#D68910", if (is_dark) "#3A5570" else "#9BA6B0"))
        nodes$font.color <- if (is_dark) {
            ifelse(role == "target", "#FF8A80", ifelse(role == "plotted", "#FFD54F", "#D0E4F0"))
        } else {
            ifelse(role == "target", "#8B0000", ifelse(role == "plotted", "#7D5A00", "#2C3E50"))
        }
        nodes$shape <- "dot"
        nodes$size <- ifelse(role == "target", 28, ifelse(role == "plotted", 19, 13))
        nodes$borderWidth <- ifelse(role %in% c("target", "plotted"), 2, 1)
        nodes$title <- paste0(
            "<div style='padding:8px 10px; font-family:Roboto,sans-serif; background:#2C3E50; color:#FFFFFF; border-radius:6px; font-size:12px;'><b>",
            htmltools::htmlEscape(as.character(nodes$label)),
            "</b><br/><span style='color:#9BB5C9; font-size:11px;'>STRING ID: ",
            htmltools::htmlEscape(as.character(nodes$id)),
            "</span></div>"
        )

        score <- suppressWarnings(as.numeric(edges_raw$score))
        edges <- data.frame(
            from = as.character(edges_raw$from),
            to = as.character(edges_raw$to),
            title = paste0("<div style='padding:6px 10px; font-family:Roboto,sans-serif; background:#2C3E50; color:#FFFFFF; border-radius:6px; font-size:12px;'>Score: <b>", score, "</b></div>"),
            width = ifelse(score <= 1, 0.8 + score * 1.4, 0.8 + (score / 1000) * 1.4),
            color = "rgba(124, 144, 166, 0.22)",
            stringsAsFactors = FALSE
        )

        visNetwork(nodes, edges, background = if (is_dark) "#0F1D2B" else "#FFFFFF") %>%
            visNodes(
                font = list(
                    size = 14,
                    face = "Roboto, sans-serif",
                    strokeWidth = if (is_dark) 2 else 1,
                    strokeColor = if (is_dark) "rgba(0,0,0,0.6)" else "rgba(255,255,255,0.6)"
                ),
                shadow = list(enabled = TRUE, size = 4),
                scaling = list(label = list(enabled = TRUE, min = 11, max = 18))
            ) %>%
            visEdges(smooth = FALSE, shadow = FALSE, selectionWidth = 1.2, hoverWidth = 0.6) %>%
            visOptions(highlightNearest = list(enabled = TRUE, degree = 1, hover = TRUE)) %>%
            visPhysics(
                solver = "barnesHut",
                barnesHut = list(
                    gravitationalConstant = -3200,
                    centralGravity = 0.18,
                    springLength = 150,
                    springConstant = 0.035,
                    damping = 0.12
                ),
                stabilization = list(iterations = as.integer(stabilization_iterations))
            ) %>%
            visInteraction(
                zoomView = TRUE,
                dragView = TRUE,
                dragNodes = TRUE,
                navigationButtons = TRUE,
                keyboard = list(enabled = TRUE, bindToWindow = FALSE),
                zoomSpeed = 0.18
            ) %>%
            visEvents(
                startStabilizing = "function(){ this.__cgvStabilizeStarted = (window.performance && performance.now) ? performance.now() : Date.now(); }",
                stabilizationIterationsDone = "function(){ var now=(window.performance&&performance.now)?performance.now():Date.now(); var start=this.__cgvStabilizeStarted||now; if(window.Shiny&&Shiny.setInputValue){ Shiny.setInputValue('string_stabilize_ms',{ms:Math.max(0,now-start),at:Date.now()},{priority:'event'}); } }",
                stabilized = "function(){ if (!this.__cgvHomeReady) { this.__cgvHomeReady = true; try { this.fit({ animation: { duration: 260, easingFunction: 'easeInOutQuad' } }); } catch(e) {} } }",
                doubleClick = "function(){ try { this.fit({ animation: { duration: 240, easingFunction: 'easeInOutQuad' } }); } catch(e) {} }"
            )
    }

    observeEvent(input$open_string_network, {
        evt <- input$open_string_network
        req(evt)
        pid <- as.character(evt$id %||% "")
        ctx <- normalize_plot_context(evt$context %||% "homo")
        if (!nzchar(pid)) {
            return(invisible(NULL))
        }

        stringNetworkRequestState$id <- paste0("string_reset_", as.integer(Sys.time()), "_", sample.int(1000000L, 1))
        stringNetworkData(NULL)
        stringNetworkWidget(build_string_info_widget("Loading STRING network...", "Preparing external STRING query...", icon_code = "f110"))
        session$sendCustomMessage("string_network_reset", list(
            outputId = "string_network_plot",
            at = as.numeric(Sys.time())
        ))

        selectedChartPlotId(pid)
        selectedChartContext(ctx)

        d <- get_chart_plot_data(pid, ctx)
        org_name <- as.character(d$org_info$name %||% "Organism")
        titulo <- if (ctx == "homo") titlesHomologous()[[pid]] else titlesOrthologous()[[pid]]
        gene_title <- trimws(as.character(extract_title_field(titulo, "Gene") %||% "Gene"))

        showModal(modalDialog(
            title = tags$div(
                class = "string-modal-header-inner",
                tags$div(
                    class = "string-modal-title-block",
                    icon("project-diagram"),
                    tags$div(
                        tags$span(" STRING Protein Network"),
                        tags$p(
                            class = "string-modal-subtitle",
                            tags$span(sprintf("Gene: %s | ", gene_title)),
                            tags$em(org_name)
                        )
                    )
                ),
                tags$div(
                    class = "string-modal-actions",
                    tags$button(
                        type = "button",
                        class = "string-modal-close-btn",
                        onclick = "$(this).closest('.modal').modal('hide');",
                        HTML("&times;")
                    )
                )
            ),
            size = "l",
            easyClose = TRUE,
            footer = NULL,
            div(
                class = "string-network-body-wrap chart-modal-chart-wrap",
                tags$div(
                    class = "chart-export-tip",
                    tags$button(
                        type = "button",
                        class = "btn btn-sm btn-export-svg chart-export-btn",
                        title = "Export STRING network as SVG",
                        onclick = "exportStringNetworkSVG('string_network_plot', 'string_coexpression_network.svg');",
                        icon("download"),
                        "SVG"
                    )
                ),
                chart_info_tip(
                    "<strong>STRING Protein Network</strong><br/>Interactive protein-protein interaction map from STRING.<div class='ci-axes'><b>Nodes:</b> proteins<br/><b>Edges:</b> STRING interactions (thicker = higher score)<br/><b>Colors:</b> Red = target, Orange = plotted genes, Gray = additional interactors<br/><b>Score:</b> STRING combined confidence score (0&ndash;1000). Higher = stronger evidence.</div><div class='ci-tip'>The score is computed by STRING by integrating multiple evidence channels (experiments, curated databases, co-expression, text mining, neighborhood/fusion/co-occurrence) into one probabilistic confidence value. Drag nodes to inspect neighborhoods, use wheel zoom-in, and hover nodes/edges for details.</div>"
                ),
                shinycssloaders::withSpinner(
                    if (requireNamespace("visNetwork", quietly = TRUE)) {
                        visNetworkOutput("string_network_plot", height = "500px")
                    } else {
                        tags$div(style = "padding:24px;text-align:center;color:#5D6D7E;",
                            tags$p("Install the 'visNetwork' package to view interactive STRING networks."))
                    },
                    type = 8, color = "#9C528B"
                )
            ),
            tags$div(
                class = "string-network-legend",
                tags$span(tags$span(class = "legend-dot", style = "background:#E74C3C;"), " Target Gene"),
                tags$span(tags$span(class = "legend-dot", style = "background:#F39C12;"), " In Display (Plotted)"),
                tags$span(tags$span(class = "legend-dot", style = "background:#D6E1EA;"), " STRING Interactor")
            )
        ) |> tagAppendAttributes(class = "string-network-modal"))

        query_payload <- build_string_query_payload(pid, ctx)
        if (!is.null(query_payload$error_widget)) {
            stringNetworkWidget(query_payload$error_widget)
            return(invisible(NULL))
        }

        req_id <- paste0("string_", as.integer(Sys.time()), "_", sample.int(1000000L, 1))
        stringNetworkRequestState$id <- req_id
        perf_run <- app_perf_new_run("STRING")
        app_perf_mark(perf_run, "snapshot_ready", "STRING")

        cache_t0 <- app_perf_now()
        cached_payload <- tryCatch(string_try_cached_payload(query_payload, base_dir = "."), error = function(e) NULL)
        app_perf_mark_ms(perf_run, "sync_cache_check_ms", app_perf_elapsed_ms(cache_t0), "STRING")
        if (is.list(cached_payload)) {
            display_payload <- tryCatch(
                string_apply_display_roles(cached_payload, query_payload, base_dir = ".", resolve_missing = FALSE),
                error = function(e) cached_payload
            )
            stringNetworkData(display_payload)
            stringNetworkWidget(build_string_network_widget_from_data(
                display_payload,
                is_dark = identical(tolower(as.character(input$app_theme %||% "light")), "dark")
            ))
            app_perf_mark(perf_run, "persistent_cache_hit", "STRING")
            return(invisible(NULL))
        }
        app_perf_mark(perf_run, "persistent_cache_miss", "STRING")

        pending_key <- string_cache_hash(
            "pending",
            as.integer(query_payload$taxid),
            query_payload$id_candidates,
            as.integer(query_payload$required_score),
            as.integer(query_payload$add_nodes)
        )
        pending <- get0(pending_key, envir = pendingStringPromises, inherits = FALSE, ifnotfound = NULL)
        if (is.null(pending)) {
            future_launch_t0 <- app_perf_now()
            app_perf_mark(perf_run, "worker_launch_start", "STRING")
            pending <- promises::future_promise({
                string_resolve_and_fetch(query_payload, base_dir = ".")
            }, seed = TRUE)
            assign(pending_key, pending, envir = pendingStringPromises)
            app_perf_mark_ms(perf_run, "worker_launch_ms", app_perf_elapsed_ms(future_launch_t0), "STRING")
        } else {
            app_perf_mark(perf_run, "joined_inflight_request", "STRING")
        }

        pending %...>% (function(result) {
            if (exists(pending_key, envir = pendingStringPromises, inherits = FALSE)) {
                rm(list = pending_key, envir = pendingStringPromises)
            }
            if (identical(stringNetworkRequestState$id, req_id)) {
                if (is.list(result) && isTRUE(result$ok) && is.list(result$payload)) {
                    display_payload <- tryCatch(
                        string_apply_display_roles(result$payload, query_payload, base_dir = "."),
                        error = function(e) result$payload
                    )
                    stringNetworkData(display_payload)
                    stringNetworkWidget(build_string_network_widget_from_data(
                        display_payload,
                        is_dark = identical(tolower(as.character(input$app_theme %||% "light")), "dark")
                    ))
                    app_perf_mark(perf_run, if (isTRUE(result$cache_hit)) "worker_cache_hit" else "network_ready", "STRING")
                } else {
                    reason <- as.character(result$reason %||% "lookup_failed")
                    label <- if (identical(reason, "not_found")) {
                        sprintf("Protein not found in STRING\n%s (taxon %s)", query_payload$gene_name, query_payload$taxid)
                    } else {
                        "No interactions found"
                    }
                    stringNetworkWidget(build_string_error_widget(label))
                    app_perf_mark(perf_run, paste0("empty_result=", reason), "STRING")
                }
            }
            NULL
        }) %...!% (function(err) {
            if (exists(pending_key, envir = pendingStringPromises, inherits = FALSE)) {
                rm(list = pending_key, envir = pendingStringPromises)
            }
            if (identical(stringNetworkRequestState$id, req_id)) {
                short_msg <- trimws(as.character(conditionMessage(err) %||% "Unknown error"))
                short_msg <- gsub("[\r\n]+", " ", short_msg)
                short_msg <- stringr::str_trunc(short_msg, width = 120)
                stringNetworkWidget(
                    build_string_error_widget(
                        paste0("STRING lookup failed\n", short_msg),
                        paste0("<div style='padding:8px; max-width:300px; font-family:sans-serif;'>", htmltools::htmlEscape(conditionMessage(err)), "</div>")
                    )
                )
                app_perf_mark(perf_run, paste0("error=", short_msg), "STRING")
            }
            NULL
        })
    })

    observeEvent(input$string_network_closed, {
        stringNetworkRequestState$id <- paste0("string_closed_", as.integer(Sys.time()), "_", sample.int(1000000L, 1))
        stringNetworkData(NULL)
        stringNetworkWidget(NULL)
        session$sendCustomMessage("string_network_reset", list(
            outputId = "string_network_plot",
            at = as.numeric(Sys.time())
        ))
    }, ignoreInit = TRUE)

    observeEvent(input$app_theme, {
        payload <- isolate(stringNetworkData())
        if (!is.list(payload)) return(invisible(NULL))
        dark <- identical(tolower(as.character(input$app_theme %||% "light")), "dark")
        nodes <- payload$nodes
        if (is.data.frame(nodes) && nrow(nodes) > 0L && requireNamespace("visNetwork", quietly = TRUE)) {
            role <- as.character(nodes$role %||% rep("neighbor", nrow(nodes)))
            updates <- data.frame(
                id = as.character(nodes$id),
                color.background = ifelse(role == "target", "#E74C3C", ifelse(role == "plotted", "#F39C12", if (dark) "#1A2B3C" else "#D6E1EA")),
                color.border = ifelse(role == "target", "#C0392B", ifelse(role == "plotted", "#D68910", if (dark) "#3A5570" else "#9BA6B0")),
                font.color = if (dark) {
                    ifelse(role == "target", "#FF8A80", ifelse(role == "plotted", "#FFD54F", "#D0E4F0"))
                } else {
                    ifelse(role == "target", "#8B0000", ifelse(role == "plotted", "#7D5A00", "#2C3E50"))
                },
                stringsAsFactors = FALSE
            )
            tryCatch(
                visNetwork::visNetworkProxy("string_network_plot", session = session) %>%
                    visNetwork::visUpdateNodes(updates),
                error = function(e) NULL
            )
        }
        session$sendCustomMessage("string_network_theme", list(
            dark = dark
        ))
    }, ignoreInit = TRUE)

    observeEvent(input$string_stabilize_ms, {
        ms <- suppressWarnings(as.numeric((input$string_stabilize_ms %||% list())$ms %||% NA_real_))
        if (is.finite(ms)) {
            app_perf_mark_ms(NULL, "stabilization_ms", ms, "STRING")
        }
    }, ignoreInit = TRUE)

    output$string_network_plot <- if (requireNamespace("visNetwork", quietly = TRUE)) {
        renderVisNetwork({
            stringNetworkWidget() %||% build_string_info_widget("Loading STRING network...", "Preparing external STRING query...", icon_code = "f110")
        })
    } else {
        renderUI({
            tags$div(style = "padding:24px;text-align:center;color:#5D6D7E;",
                tags$p("Install the 'visNetwork' package to view interactive STRING networks."))
        })
    }

    # ── Feedback & Support Logic ──────────────────────────────────────────────
    feedback_viewed_at <- reactiveVal(as.POSIXct(NA))
    feedback_submit_log <- reactiveVal(numeric(0))
    feedback_last_signature <- reactiveVal("")
    feedback_last_signature_at <- reactiveVal(as.POSIXct(NA))
    feedback_submission_dir <- file.path(get_cgv_cache_root("."), "feedback_submissions")
    if (!dir.exists(feedback_submission_dir)) {
        dir.create(feedback_submission_dir, recursive = TRUE, showWarnings = FALSE)
    }

    observeEvent(input$navtabs, {
        if (identical(input$navtabs, "feedback")) {
            feedback_viewed_at(Sys.time())
        }
    }, ignoreInit = FALSE)

    build_feedback_page_url <- function(session) {
        protocol <- as.character(session$clientData$url_protocol %||% "")
        hostname <- as.character(session$clientData$url_hostname %||% "")
        port <- as.character(session$clientData$url_port %||% "")
        pathname <- as.character(session$clientData$url_pathname %||% "")
        search <- as.character(session$clientData$url_search %||% "")
        hash <- as.character(session$clientData$url_hash %||% "")

        if (!nzchar(hostname)) {
            return("")
        }

        origin <- paste0(
            protocol,
            if (nzchar(protocol)) "//" else "",
            hostname,
            if (nzchar(port)) paste0(":", port) else ""
        )

        paste0(origin, pathname, search, hash)
    }

    reset_feedback_form <- function(is_bug) {
        updateTextInput(session, "feedback_website", value = "")

        if (isTRUE(is_bug)) {
            updateTextInput(session, "bug_title", value = "")
            updateTextAreaInput(session, "bug_steps", value = "")
            updateTextAreaInput(session, "bug_expected", value = "")
        } else {
            updateTextInput(session, "sugg_title", value = "")
            updateTextAreaInput(session, "sugg_problem", value = "")
            updateTextAreaInput(session, "sugg_idea", value = "")
        }
    }

    notify_feedback <- function(text, tone = "info") {
        emit_popup_status(
            context = "Feedback",
            text = text,
            tone = as.character(tone %||% "info"),
            clear = TRUE
        )
        invisible(NULL)
    }

    observeEvent(input$submit_feedback_btn, {
        req(input$feedback_type)

        is_bug <- identical(input$feedback_type, "bug")
        now <- Sys.time()
        now_num <- as.numeric(now)

        if (!input$feedback_type %in% c("bug", "suggestion")) {
            notify_feedback("Please select a valid feedback type.", tone = "error")
            return()
        }

        full_name <- feedback_normalize_header_text(input$feedback_name)
        email <- feedback_normalize_header_text(input$feedback_email)
        honeypot <- feedback_normalize_text(input$feedback_website)

        title <- if (is_bug) feedback_normalize_header_text(input$bug_title) else feedback_normalize_header_text(input$sugg_title)
        primary_details <- if (is_bug) feedback_normalize_text(input$bug_steps) else feedback_normalize_text(input$sugg_problem)
        secondary_details <- if (is_bug) feedback_normalize_text(input$bug_expected) else feedback_normalize_text(input$sugg_idea)

        if (nzchar(honeypot)) {
            notify_feedback("Unable to send feedback right now. Please reload the page and try again.", tone = "error")
            return()
        }

        viewed_at <- feedback_viewed_at()
        if (is.na(viewed_at) || as.numeric(difftime(now, viewed_at, units = "secs")) < 3) {
            notify_feedback("Please wait a couple of seconds before sending your feedback.", tone = "warning")
            return()
        }

        recent_submissions <- feedback_submit_log()
        recent_submissions <- recent_submissions[(now_num - recent_submissions) < 3600]
        feedback_submit_log(recent_submissions)

        if (length(recent_submissions) && (now_num - tail(recent_submissions, 1)) < 30) {
            notify_feedback("Please wait at least 30 seconds before sending another report.", tone = "warning")
            return()
        }

        if (length(recent_submissions) >= 4) {
            notify_feedback("This session has reached the feedback limit for now. Please try again a little later.", tone = "warning")
            return()
        }

        if (nchar(full_name) < 3) {
            notify_feedback("Please provide your full name so we can identify the report correctly.", tone = "error")
            return()
        }

        if (nchar(full_name, type = "chars") > 120L) {
            notify_feedback("Please shorten your name to 120 characters or fewer.", tone = "error")
            return()
        }

        if (!feedback_is_valid_email(email)) {
            notify_feedback("Please provide a valid email address so we can reply if needed.", tone = "error")
            return()
        }

        if (nchar(title) < 5) {
            notify_feedback("Please provide a short title with at least 5 characters.", tone = "error")
            return()
        }

        if (nchar(title, type = "chars") > 160L) {
            notify_feedback("Please shorten the title to 160 characters or fewer.", tone = "error")
            return()
        }

        if (nchar(primary_details) < 15) {
            notify_feedback("Please provide a bit more detail so we can understand the issue or suggestion.", tone = "error")
            return()
        }

        if (
            nchar(primary_details, type = "chars") > 10000L ||
            nchar(secondary_details, type = "chars") > 10000L
        ) {
            notify_feedback("Please keep each feedback detail field under 10,000 characters.", tone = "error")
            return()
        }

        signature <- paste(
            tolower(c(input$feedback_type, full_name, email, title, primary_details, secondary_details)),
            collapse = "||"
        )
        last_signature_at <- feedback_last_signature_at()
        if (
            identical(signature, feedback_last_signature()) &&
            !is.na(last_signature_at) &&
            as.numeric(difftime(now, last_signature_at, units = "mins")) < 10
        ) {
            notify_feedback("That looks identical to your last submission. Please edit it or wait a bit before sending again.", tone = "warning")
            return()
        }

        app_section <- as.character(input$navtabs %||% "feedback")
        page_url <- build_feedback_page_url(session)
        submitted_at <- format(now, "%Y-%m-%d %H:%M:%S %Z")
        feedback_label <- if (is_bug) "Bug report" else "Feature suggestion"
        details_header <- if (is_bug) "What happened / steps to reproduce" else "Current limitation or need"
        followup_header <- if (is_bug) "Expected behavior" else "Requested improvement"
        file_stub <- paste0(
            format(now, "%Y%m%d_%H%M%S"),
            "_",
            paste(sample(c(letters, LETTERS, 0:9), 6, replace = TRUE), collapse = "")
        )
        submission_id <- paste0("feedback_", file_stub)

        message_lines <- Filter(Negate(is.null), list(
            sprintf("Submission ID: %s", submission_id),
            sprintf("Reporter: %s", full_name),
            sprintf("Reply email: %s", email),
            sprintf("Feedback type: %s", feedback_label),
            sprintf("Current app section: %s", app_section),
            sprintf("Submitted at: %s", submitted_at),
            if (nzchar(page_url)) sprintf("Page URL: %s", page_url) else NULL,
            "",
            details_header,
            primary_details,
            if (nzchar(secondary_details)) "" else NULL,
            if (nzchar(secondary_details)) followup_header else NULL,
            if (nzchar(secondary_details)) secondary_details else NULL
        ))

        payload <- list(
            name = full_name,
            email = email,
            subject = sprintf("[CGeV %s] %s", if (is_bug) "Bug" else "Suggestion", title),
            feedback_type = feedback_label,
            full_name = full_name,
            reporter_email = email,
            title = title,
            message = paste(message_lines, collapse = "\n"),
            app_section = app_section,
            app_version = "Comparative Gene Viewer",
            submitted_at = submitted_at,
            page_url = page_url,
            submission_id = submission_id
        )

        if (is_bug) {
            payload$bug_steps <- primary_details
            payload$expected_behavior <- secondary_details
        } else {
            payload$current_limitation <- primary_details
            payload$requested_improvement <- secondary_details
        }

        save_path <- file.path(feedback_submission_dir, paste0("feedback_", file_stub, ".rds"))

        tryCatch({
            payload$delivery <- list(
                state = "pending",
                attempted_at = format(now, "%Y-%m-%d %H:%M:%S %Z")
            )
            saveRDS(payload, save_path)

            delivery <- feedback_send_notification(payload)
            receipt_delivery <- if (isTRUE(delivery$ok)) {
                feedback_send_receipt(payload)
            } else {
                list(
                    ok = FALSE,
                    state = "not_attempted",
                    status = NA_integer_,
                    provider_id = "",
                    error = "Primary CGeV inbox delivery was not accepted."
                )
            }
            payload$delivery <- c(
                delivery[c("state", "status", "provider_id", "error")],
                list(attempted_at = format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z"))
            )
            payload$receipt_delivery <- c(
                receipt_delivery[c("state", "status", "provider_id", "error")],
                list(attempted_at = format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z"))
            )
            tryCatch(
                saveRDS(payload, save_path),
                error = function(e) {
                    message("[Feedback] Could not persist delivery metadata: ", conditionMessage(e))
                }
            )

            if (isTRUE(delivery$ok)) {
                message(
                    "[Feedback] Email accepted by Resend (status ",
                    delivery$status,
                    ", id ",
                    delivery$provider_id,
                    ")."
                )
                feedback_submit_log(c(recent_submissions, now_num))
                feedback_last_signature(signature)
                feedback_last_signature_at(now)
                reset_feedback_form(is_bug)
                if (identical(receipt_delivery$state, "disabled")) {
                    notify_feedback(
                        "Thanks. Your feedback was sent to the CGeV inbox. Replies will go to the email you provided.",
                        tone = "success"
                    )
                } else if (isTRUE(receipt_delivery$ok)) {
                    message(
                        "[Feedback] Reporter confirmation accepted by Resend (status ",
                        receipt_delivery$status,
                        ", id ",
                        receipt_delivery$provider_id,
                        ")."
                    )
                    notify_feedback(
                        "Thanks. Your feedback was sent to CGeV, and a confirmation copy is on its way to your email.",
                        tone = "success"
                    )
                } else {
                    message(
                        "[Feedback] Reporter confirmation failed (state ",
                        receipt_delivery$state,
                        ", status ",
                        receipt_delivery$status,
                        "): ",
                        receipt_delivery$error
                    )
                    notify_feedback(
                        "Your feedback was sent to CGeV, but we could not send the confirmation copy. We can still reply to the email you provided.",
                        tone = "warning"
                    )
                }
            } else {
                message(
                    "[Feedback] Email delivery failed (state ",
                    delivery$state,
                    ", status ",
                    delivery$status,
                    "): ",
                    delivery$error
                )
                if (
                    identical(delivery$state, "not_configured") &&
                    identical(tolower(Sys.getenv("CGV_RUNTIME", "")), "desktop")
                ) {
                    notify_feedback(
                        paste(
                            "Your feedback was saved locally, but this Desktop build cannot send it yet.",
                            "Please use Feedback at cgev.mobilomics.org",
                            "or email cgvviewer@gmail.com."
                        ),
                        tone = "warning"
                    )
                } else {
                    notify_feedback(
                        "Your feedback was saved, but the email could not be delivered to the CGeV inbox. Please try again shortly.",
                        tone = "error"
                    )
                }
            }
        }, error = function(e) {
            notify_feedback("We could not save your feedback right now. Please try again later.", tone = "error")
            message("[Feedback] Save error: ", e$message)
        })
    }, ignoreInit = TRUE)

    # =========================================================================
    # PORTABLE ANALYSIS / STATIC READ-ONLY REPORTS
    # =========================================================================
    if (isTRUE(app_env_flag("APP_SHARED_REPORTS_ENABLED", default = TRUE))) {
        background_job_path <- trimws(Sys.getenv("CGV_BACKGROUND_REPORT_JOB_PATH", ""))
        background_job <- if (nzchar(background_job_path)) {
            cgv_read_background_report_job(path = background_job_path)
        } else {
            NULL
        }
        background_bootstrap <- is.list(background_job) &&
            isTRUE(app_env_flag("CGV_BACKGROUND_REPORT_RENDERER", default = FALSE))
        background_job_id <- as.character((background_job %||% list())$id %||% "")
        mark_background_ready <- function(result) {
            if (!isTRUE(background_bootstrap) || !nzchar(background_job_id)) return(invisible(NULL))
            cgv_update_background_report(
                background_job_id,
                state = "ready",
                result = result,
                error = "",
                base_dir = "."
            )
            invisible(NULL)
        }
        mark_background_failed <- function(message) {
            if (!isTRUE(background_bootstrap) || !nzchar(background_job_id)) return(invisible(NULL))
            try(cgv_update_background_report(
                background_job_id,
                state = "failed",
                error = as.character(message %||% "Background report generation failed."),
                base_dir = "."
            ), silent = TRUE)
            invisible(NULL)
        }
        sharedAnalysisDomain <- init_shared_analysis_domain(
            input = input,
            output = output,
            session = session,
            build_session_snapshot_fn = function() build_work_session_snapshot(),
            homo_summary_fn = function() get_homo_summary_df(perf_context = "HOMO_SHARE"),
            ortho_summary_fn = function() get_ortho_summary_df(perf_context = "ORTHO_SHARE"),
            pip_runs_fn = function() {
                ortho_runs <- pipLocalAlignmentRunsOrthologous() %||% list()
                ortho_ids <- names(ortho_runs)
                if (is.null(ortho_ids)) ortho_ids <- as.character(seq_along(ortho_runs))
                names(ortho_runs) <- paste0("cross_species_", ortho_ids)
                ortho_runs
            },
            multipip_runs_fn = function() {
                ortho_runs <- multipipLocalAlignmentRunsOrthologous() %||% list()
                ortho_ids <- names(ortho_runs)
                if (is.null(ortho_ids)) ortho_ids <- as.character(seq_along(ortho_runs))
                names(ortho_runs) <- paste0("cross_species_", ortho_ids)
                ortho_runs
            },
            run_lastz_fn = function(contexts) {
                contexts <- unique(as.character(contexts %||% character(0)))
                jobs <- list()

                if ("ortho" %in% contexts) {
                    ortho_blocks_contexts <- tryCatch(pipWindowTracksOrthologous() %||% list(), error = function(e) list())
                    ortho_blocks_reference <- tryCatch(pipReferenceWindowOrthologous(), error = function(e) NULL)
                    ortho_blocks_ids <- as.character(tryCatch(pipVisiblePlotIdsOrthologous(), error = function(e) character(0)))
                    ortho_multipip_contexts <- tryCatch(multipipWindowTracksOrthologous() %||% list(), error = function(e) list())
                    ortho_multipip_reference <- tryCatch(multipipReferenceWindowOrthologous(), error = function(e) NULL)
                    ortho_multipip_ids <- as.character(tryCatch(multipipOrderedPlotIdsOrthologous(), error = function(e) character(0)))
                    jobs$ortho_blocks <- run_canonical_lastz_contexts_async(
                        ortho_blocks_contexts,
                        ortho_blocks_reference,
                        ortho_blocks_ids
                    )
                    same_ortho_alignment <- identical(
                        as.character(input$ortho_pip_span %||% "gene"),
                        as.character(input$ortho_multipip_span %||% "gene")
                    ) && identical(
                        trimws(as.character((ortho_blocks_reference %||% list())$plot_id %||% "")),
                        trimws(as.character((ortho_multipip_reference %||% list())$plot_id %||% ""))
                    ) && setequal(ortho_blocks_ids, ortho_multipip_ids)
                    jobs$ortho_multipip <- if (isTRUE(same_ortho_alignment)) {
                        jobs$ortho_blocks
                    } else {
                        run_canonical_lastz_contexts_async(
                            ortho_multipip_contexts,
                            ortho_multipip_reference,
                            ortho_multipip_ids
                        )
                    }
                }

                if (length(jobs) == 0L) {
                    return(promises::promise_resolve(list(missing = character(0), pip_runs = list(), multipip_prepared = TRUE)))
                }

                return(promises::promise_all(.list = jobs) %...>% (function(states) {
                    states <- as.list(states %||% list())
                    missing_async <- character(0)
                    completed_for_report_async <- list()

                    if ("ortho" %in% contexts) {
                        ortho_blocks_state <- states$ortho_blocks %||% list(status = "error", runs = list())
                        ortho_multipip_state <- states$ortho_multipip %||% list(status = "error", runs = list())
                        setPipLocalAlignmentStateOrthologous(
                            runs = ortho_blocks_state$runs %||% list(),
                            stamp = as.character(ortho_blocks_state$stamp %||% Sys.time()),
                            running = FALSE,
                            token = paste0("report_", cgv_random_secret(8L))
                        )
                        setMultipipLocalAlignmentStateOrthologous(
                            runs = ortho_multipip_state$runs %||% list(),
                            stamp = as.character(ortho_multipip_state$stamp %||% Sys.time()),
                            running = FALSE,
                            token = paste0("report_", cgv_random_secret(8L))
                        )
                        pipReferenceAssessmentOrthologous(assess_current_lastz_reference(
                            ortho_blocks_state$runs %||% list(),
                            ortho_blocks_reference,
                            kind = "blocks",
                            min_identity = as.numeric(input$ortho_pip_min_identity %||% 70),
                            min_length = as.integer(input$ortho_pip_min_length %||% 100L)
                        ))
                        multipipReferenceAssessmentOrthologous(assess_current_lastz_reference(
                            ortho_multipip_state$runs %||% list(),
                            ortho_multipip_reference,
                            kind = "multipip",
                            min_identity = as.numeric(input$ortho_multipip_min_identity %||% 70),
                            min_length = as.integer(input$ortho_multipip_min_segment_bp %||% 25L)
                        ))
                        completed_ortho <- cgv_completed_alignment_runs(ortho_blocks_state$runs %||% list())
                        if (length(completed_ortho)) {
                            ortho_ids <- names(completed_ortho)
                            if (is.null(ortho_ids)) ortho_ids <- as.character(seq_along(completed_ortho))
                            names(completed_ortho) <- paste0("cross_species_", ortho_ids)
                            completed_for_report_async <- c(completed_for_report_async, completed_ortho)
                        } else {
                            missing_async <- c(missing_async, "Cross-Species LASTZ: no compatible alignment result was completed.")
                        }
                        if (!length(cgv_completed_alignment_runs(ortho_multipip_state$runs %||% list()))) {
                            missing_async <- c(missing_async, "Cross-Species MultiPIP: no compatible alignment result was completed.")
                        }
                    }

                    list(
                        missing = unique(missing_async),
                        pip_runs = completed_for_report_async,
                        multipip_prepared = TRUE
                    )
                }))
            },
            active_homo_ids_rv = activePlotIdsHomologous,
            active_ortho_ids_rv = activePlotIdsOrthologous,
            homo_synteny_available_fn = function() {
                length(homoMultiTranscriptGeneGroups()) > 0L
            },
            homo_synteny_groups_fn = function() {
                groups <- homoMultiTranscriptGeneGroups()
                unname(lapply(groups, function(group) {
                    list(
                        value = as.character(group$key %||% ""),
                        gene_label = as.character(group$gene_label %||% ""),
                        organism_label = as.character(group$org_label %||% ""),
                        label = as.character(group$label %||% group$gene_label %||% "")
                    )
                }))
            },
            plot_chr_length_fn = function(workflow, plot_id, chr_name) {
                ann_map <- if (identical(as.character(workflow), "multi_gene")) {
                    tryCatch(annotationPathsHomologous(), error = function(e) list())
                } else {
                    tryCatch(annotationPathsOrthologous(), error = function(e) list())
                }
                ann_path <- as.character(ann_map[[as.character(plot_id)]] %||% "")
                if (!nzchar(ann_path) || !file.exists(ann_path)) return(NA_real_)
                len <- suppressWarnings(as.numeric(get_chromosome_length_for_chr(ann_path, as.character(chr_name))))
                if (is.finite(len) && len > 0) len else NA_real_
            },
            enqueue_background_report_fn = function(snapshot, email, options) {
                cgv_enqueue_background_report(
                    snapshot = snapshot,
                    email = email,
                    options = options,
                    base_dir = "."
                )
            },
            background_report_ready_fn = mark_background_ready,
            background_report_failed_fn = mark_background_failed,
            background_bootstrap = background_bootstrap,
            app_version = cgv_release_version,
            base_dir = "."
        )

        if (isTRUE(background_bootstrap)) {
            session$onFlushed(function() {
                restored <- tryCatch(
                    shiny::isolate(apply_work_session_snapshot(background_job$snapshot)),
                    error = function(e) e
                )
                if (inherits(restored, "error")) {
                    mark_background_failed(paste0("Could not restore the queued analysis: ", conditionMessage(restored)))
                    return(invisible(NULL))
                }
                try(cgv_update_background_report(
                    background_job_id,
                    state = "rendering",
                    error = "",
                    base_dir = "."
                ), silent = TRUE)
                session$onFlushed(function() {
                    launch <- function() {
                        if (session$isClosed()) return(invisible(NULL))
                        session$sendCustomMessage("cgv:background-report-bootstrap", list(
                            options = background_job$options %||% list(),
                            settle_ms = 3500L
                        ))
                        invisible(NULL)
                    }
                    if (requireNamespace("later", quietly = TRUE)) {
                        later::later(launch, delay = 2)
                    } else {
                        launch()
                    }
                }, once = TRUE)
                invisible(NULL)
            }, once = TRUE)
        }
    } else {
        shinyjs::hide("open_share_analysis_homo")
        shinyjs::hide("open_share_analysis_ortho")
    }

}

if (exists("cgv_runtime_server", mode = "function")) cgv_runtime_server(.cgv_server_definition) else .cgv_server_definition
